// Beckhoff TwinCAT Safety Logic - Adversarial Resilient Press System (SIL2)
VAR_GLOBAL
    // Digital Safety IO
    bTwoHandButton1 AT %I* : BOOL;
    bTwoHandButton2 AT %I* : BOOL;
    bLightCurtainOK AT %I* : BOOL;
    bEStopOK AT %I* : BOOL;
    bLocalResetButton AT %I* : BOOL;
    bSafetyDoorClosed AT %I* : BOOL;
    bSafetyDoorLocked AT %I* : BOOL;

    // Analog Safety Inputs for Drift Detection (e.g. pressure sensors for hydraulic press)
    nPressPressureChA AT %I* : INT;
    nPressPressureChB AT %I* : INT;

    // HIL Digital Twin State vector comparison
    bDigitalTwinMismatch AT %I* : BOOL;

    // Cybersecurity & Infrastructure
    bSecureHMITokenValid AT %I* : BOOL;
    bRemoteResetCmd AT %I* : BOOL;
    bPrimaryPLCHeartbeat AT %I* : BOOL;
    bSecondaryPLCHeartbeat AT %I* : BOOL;
    bFailoverActive AT %I* : BOOL;
    bFSoE_ConnStates AT %I* : WORD;

    // Safety Outputs
    bLockCommand AT %Q* : BOOL;
    bPressEnable AT %Q* : BOOL;
    bSimulateFaultCmd AT %Q* : BOOL; // Self-test actuator cmd
END_VAR

PROGRAM MAIN
VAR
    fbTwoHand : FB_TwoHand;
    fbLightCurtain : FB_LightCurtain;
    fbEStop : FB_EStop;
    fbGuardLock : FB_GuardLocking;
    fbSafetyCircuit : FB_SafeStop;

    // Security & Infrastructure
    bValidReset : BOOL;
    bPLCHeartbeatOK : BOOL;

    // Adversarial Defense States
    bSensorDriftDetected : BOOL;
    nPressureDiff : INT;
    nMaxAllowedDrift : INT := 250; // Configurable threshold

    // Self-Test Routine State Machine
    eSelfTestState : (INIT, SIMULATE_FAULT, VERIFY_FAULT, TEST_PASS, TEST_FAIL) := INIT;
    fbTestTimer : TON;
    bSystemReady : BOOL := FALSE;
END_VAR

// 1. Dual-Channel Analog Sensor Drift Detection
nPressureDiff := ABS(nPressPressureChA - nPressPressureChB);
IF nPressureDiff > nMaxAllowedDrift THEN
    bSensorDriftDetected := TRUE;
ELSE
    bSensorDriftDetected := FALSE;
END_IF;

// 2. Automated Startup Self-Test Routine
CASE eSelfTestState OF
    INIT:
        bSimulateFaultCmd := FALSE;
        bSystemReady := FALSE;
        IF bValidReset THEN
            eSelfTestState := SIMULATE_FAULT;
            fbTestTimer(IN:=FALSE);
        END_IF

    SIMULATE_FAULT:
        bSimulateFaultCmd := TRUE; // Command physical safety relay to drop
        fbTestTimer(IN:=TRUE, PT:=T#2S);
        // Expecting feedback from contactor/relay to drop EStopOK signal
        IF NOT bEStopOK THEN
            bSimulateFaultCmd := FALSE;
            eSelfTestState := VERIFY_FAULT;
            fbTestTimer(IN:=FALSE);
        ELSIF fbTestTimer.Q THEN
            eSelfTestState := TEST_FAIL;
        END_IF

    VERIFY_FAULT:
        // Wait for system to stabilize and reset to be applied again
        fbTestTimer(IN:=TRUE, PT:=T#500MS);
        IF fbTestTimer.Q AND bEStopOK AND bValidReset THEN
            eSelfTestState := TEST_PASS;
        END_IF

    TEST_PASS:
        bSystemReady := TRUE;

    TEST_FAIL:
        bSystemReady := FALSE;
        // Require hard cycle
END_CASE

// Infrastructure Monitoring
bPLCHeartbeatOK := (NOT bFailoverActive AND bPrimaryPLCHeartbeat) OR (bFailoverActive AND bSecondaryPLCHeartbeat);
bValidReset := bLocalResetButton OR (bRemoteResetCmd AND bSecureHMITokenValid);

// 3. Safety logic integration (including Digital Twin mismatch detection)
fbEStop(
    bEStop := (bEStopOK AND bPLCHeartbeatOK AND NOT bSensorDriftDetected AND NOT bDigitalTwinMismatch AND bSystemReady),
    bReset := bValidReset,
    bSafeEStop => 
);

fbLightCurtain(
    bLightCurtain := (bLightCurtainOK AND bSystemReady),
    bReset := bValidReset,
    bSafeLightCurtain => 
);

fbGuardLock(
    bDoorClosed := bSafetyDoorClosed,
    bDoorLocked := bSafetyDoorLocked,
    bReset := bValidReset,
    bLockEnable := fbEStop.bSafeEStop AND fbLightCurtain.bSafeLightCurtain,
    bLockOutput => bLockCommand,
    bSafeDoorState => 
);

fbTwoHand(
    bButton1 := bTwoHandButton1,
    bButton2 := bTwoHandButton2,
    tDiscrepancyTime := T#500MS,
    bSafeTwoHand => 
);

// Overall Safety Logic (SIL2 Compliant)
fbSafetyCircuit(
    bEnable := fbEStop.bSafeEStop AND fbLightCurtain.bSafeLightCurtain AND fbGuardLock.bSafeDoorState AND fbTwoHand.bSafeTwoHand AND bSystemReady,
    bReset := bValidReset,
    bSafeOutput => bPressEnable
);
END_PROGRAM

FUNCTION_BLOCK FB_SortationConveyor
VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    bItemDetected : BOOL;
    sBarcodeData : STRING(255);
    bBarcodeReady : BOOL;
END_VAR
VAR_OUTPUT
    bConveyorRun : BOOL;
    bDivertGate1 : BOOL;
    bDivertGate2 : BOOL;
    rOEE_Total : REAL;
END_VAR
VAR
    eState : INT := 0;
    nTotal : UDINT;
    nGood : UDINT;
END_VAR

CASE eState OF
    0:
        bConveyorRun := FALSE;
        bDivertGate1 := FALSE;
        bDivertGate2 := FALSE;
        IF bStart THEN eState := 1; END_IF
    1:
        bConveyorRun := TRUE;
        IF bBarcodeReady THEN
            nTotal := nTotal + 1;
            IF sBarcodeData = 'DEST_1' THEN bDivertGate1 := TRUE; bDivertGate2 := FALSE; nGood := nGood + 1;
            ELSIF sBarcodeData = 'DEST_2' THEN bDivertGate1 := FALSE; bDivertGate2 := TRUE; nGood := nGood + 1;
            ELSE bDivertGate1 := FALSE; bDivertGate2 := FALSE;
            END_IF
        END_IF
        IF nTotal > 0 THEN rOEE_Total := 0.95 * 0.98 * (UDINT_TO_REAL(nGood) / UDINT_TO_REAL(nTotal)); END_IF
        IF bStop THEN eState := 2; END_IF
    2:
        bConveyorRun := FALSE;
        IF bStart THEN eState := 1; END_IF
END_CASE

FUNCTION_BLOCK FB_SortationConveyor_M1
VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    sBarcodeData : STRING(255);
    bBarcodeReady : BOOL;
END_VAR
VAR_OUTPUT
    bConveyorRun : BOOL;
    bInductionDriveRun : BOOL;
    bDivertGate1 : BOOL;
    bDivertGate2 : BOOL;
    rOEE_Total : REAL;
END_VAR
VAR
    eState : INT := 0;
    nTotal : UDINT;
    nGood : UDINT;
    fbGapTimer : TON;
    bGapReady : BOOL;
END_VAR

fbGapTimer(IN := bConveyorRun AND NOT bGapReady, PT := T#500MS);
IF fbGapTimer.Q THEN bGapReady := TRUE; END_IF

CASE eState OF
    0:
        bConveyorRun := FALSE;
        bInductionDriveRun := FALSE;
        IF bStart THEN eState := 1; END_IF
    1:
        bConveyorRun := TRUE;
        bInductionDriveRun := TRUE;
        IF bGapReady AND bBarcodeReady THEN
            bGapReady := FALSE;
            nTotal := nTotal + 1;
            IF sBarcodeData = 'DEST_1' THEN bDivertGate1 := TRUE; bDivertGate2 := FALSE; nGood := nGood + 1;
            ELSIF sBarcodeData = 'DEST_2' THEN bDivertGate1 := FALSE; bDivertGate2 := TRUE; nGood := nGood + 1;
            ELSE bDivertGate1 := FALSE; bDivertGate2 := FALSE;
            END_IF
        END_IF
        IF nTotal > 0 THEN rOEE_Total := 0.95 * 0.98 * (UDINT_TO_REAL(nGood) / UDINT_TO_REAL(nTotal)); END_IF
        IF bStop THEN eState := 2; END_IF
    2:
        bConveyorRun := FALSE;
        bInductionDriveRun := FALSE;
        IF bStart THEN eState := 1; END_IF
END_CASE

FUNCTION_BLOCK FB_SortationConveyor_M2
VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    sBarcodeData : STRING(255);
    bBarcodeReady : BOOL;
    nEcatState AT %I* : UINT;
    nDriveCoEFault AT %I* : UDINT;
END_VAR
VAR_OUTPUT
    bConveyorRun : BOOL;
    bFault : BOOL;
    sFaultMsg : STRING;
    rOEE_Total : REAL;
END_VAR
VAR
    eState : INT := 0;
    fbGapTimer : TON;
    bGapReady : BOOL;
    nTotal, nGood : UDINT;
END_VAR

IF (nEcatState <> 8) THEN
    bFault := TRUE;
    sFaultMsg := 'EtherCAT Not in OP';
    eState := 99;
ELSIF nDriveCoEFault <> 0 THEN
    bFault := TRUE;
    sFaultMsg := CONCAT('Drive CoE Fault: ', UDINT_TO_STRING(nDriveCoEFault));
    eState := 99;
END_IF

CASE eState OF
    0:
        IF NOT bFault AND bStart THEN eState := 1; END_IF
    1:
        bConveyorRun := TRUE;
        IF bStop THEN eState := 2; END_IF
    2:
        bConveyorRun := FALSE;
        IF bStart THEN eState := 1; END_IF
    99:
        bConveyorRun := FALSE;
        IF NOT bFault AND bStart THEN eState := 0; sFaultMsg := ''; END_IF
END_CASE

FUNCTION_BLOCK FB_SortationConveyor_M3
VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    nEcatState AT %I* : UINT;
    nAccessLevel : INT;
    bPartnerHeartbeat : BOOL;
END_VAR
VAR_OUTPUT
    bConveyorRun : BOOL;
    bStandbyActive : BOOL;
    {attribute 'OPC.UA.DA' := '1'}
    rOEE_Total : REAL;
END_VAR
VAR
    eState : INT := 0;
    fbHeartbeatTimeout : TON;
END_VAR

IF nAccessLevel < 2 AND (bStart OR bStop) THEN
    RETURN; // Deny control
END_IF

fbHeartbeatTimeout(IN := NOT bPartnerHeartbeat, PT := T#500MS);
bStandbyActive := fbHeartbeatTimeout.Q;

CASE eState OF
    0:
        IF bStart AND bStandbyActive THEN eState := 1; END_IF
    1:
        bConveyorRun := TRUE;
        rOEE_Total := 0.85;
        IF bStop THEN eState := 2; END_IF
    2:
        bConveyorRun := FALSE;
        IF bStart THEN eState := 1; END_IF
END_CASE

FUNCTION_BLOCK FB_SortationConveyor_M4
VAR_INPUT
    bStart : BOOL;
    bInitiateSelfTest : BOOL;
    rGateSensorAnalog AT %I* : REAL;
    bHIL_SyncActive : BOOL;
END_VAR
VAR_OUTPUT
    bConveyorRun : BOOL;
    bSelfTestPassed : BOOL;
    rSensorDriftOffset : REAL;
    {attribute 'OPC.UA.DA' := '1'}
    sTwinState : STRING;
END_VAR
VAR
    eState : INT := 0;
    rBaselineSensorVal : REAL := 5.0;
    fbTestTimer : TON;
END_VAR

rSensorDriftOffset := rGateSensorAnalog - rBaselineSensorVal;
IF ABS(rSensorDriftOffset) > 1.5 THEN
    sTwinState := 'DRIFT_DETECTED';
    eState := 99;
END_IF

IF bHIL_SyncActive THEN
    sTwinState := 'SYNCED_WITH_HIL';
END_IF

CASE eState OF
    0:
        IF bInitiateSelfTest THEN eState := 10; END_IF
    10:
        sTwinState := 'INJECTING_FAULT';
        fbTestTimer(IN := TRUE, PT := T#2S);
        IF fbTestTimer.Q THEN
            bSelfTestPassed := TRUE;
            fbTestTimer(IN := FALSE);
            eState := 0;
        END_IF
    1:
        bConveyorRun := TRUE;
    99:
        bConveyorRun := FALSE;
END_CASE

