PROGRAM InclineConveyor_Mutation3
VAR
    Start_PB, Stop_PB, Motor_Run, Overload_Sensor : BOOL;
    Motor_Speed, Tail_Pulley_Speed, Tensioner_Pressure, DC_Bus_Voltage : REAL;
    System_Fault, Regen_Active, Tensioner_Pump : BOOL;

    // IEC 62443 RBAC
    User_Role : INT; // 0=Guest, 1=Operator, 2=Admin
    Auth_Token_Valid : BOOL;

    // CIP Sync Redundancy
    Primary_Active : BOOL := TRUE;
    Heartbeat_Tx, Heartbeat_Rx : DINT;
    Redundancy_Loss : BOOL;

    // MQTT SCADA
    MQTT_Publish_Trigger : BOOL;
    MQTT_Payload : STRING[255];

    Diagnostic_State : INT;
END_VAR

// Cybersecurity: Validate command authority
IF User_Role < 1 OR NOT Auth_Token_Valid THEN
    Start_PB := FALSE; // Deny
END_IF;

// CIP Sync Redundancy Check
IF (Heartbeat_Tx - Heartbeat_Rx) > 5000 THEN // 5 sec timeout
    Redundancy_Loss := TRUE;
    Primary_Active := NOT Primary_Active; // Toggle failover
END_IF;

IF Primary_Active THEN
    // Core Logic
    IF Overload_Sensor THEN System_Fault := TRUE; Diagnostic_State := 1; END_IF;
    IF Motor_Run AND (Motor_Speed - Tail_Pulley_Speed > 5.0) THEN System_Fault := TRUE; Diagnostic_State := 2; END_IF;

    IF Motor_Speed < -1.0 AND NOT Motor_Run THEN
        Regen_Active := TRUE;
        IF DC_Bus_Voltage > 750.0 THEN System_Fault := TRUE; Diagnostic_State := 3; END_IF;
    ELSE
        Regen_Active := FALSE;
    END_IF;

    Tensioner_Pump := ((Motor_Run OR Regen_Active) AND NOT System_Fault AND Tensioner_Pressure < 100.0);

    IF Start_PB AND NOT System_Fault THEN Motor_Run := TRUE; END_IF;
    IF Stop_PB OR System_Fault THEN Motor_Run := FALSE; END_IF;

    // MQTT SCADA Update
    IF System_Fault OR MQTT_Publish_Trigger THEN
        // Construct JSON Payload for MQTT
        MQTT_Payload := CONCAT('{"status":', DINT_TO_STRING(Diagnostic_State), ',"speed":', REAL_TO_STRING(Motor_Speed), '}');
    END_IF;
ELSE
    // Standby Mode - consume inputs from primary
    Motor_Run := FALSE;
END_IF;
END_PROGRAM
