VAR
    Start_PB, Stop_PB, Motor_Run, Overload_Sensor, System_Fault, Regen_Active, Tensioner_Pump : BOOL;
    Motor_Speed, Tail_Pulley_Speed, Tensioner_Pressure, DC_Bus_Voltage : REAL;
    User_Role : INT; Auth_Token_Valid, Primary_Active : BOOL;
    Diagnostic_State : INT;

    // Adversarial: Sensor Drift Detection (Kalman Filter Simplified)
    Estimated_Tail_Speed : REAL;
    Kalman_Gain : REAL := 0.2;
    Drift_Warning : BOOL;

    // Adversarial: Digital Twin Sync
    HIL_Sync_Active : BOOL;
    Virtual_Speed : REAL;
    DigitalTwin_Mismatch : BOOL;

    // Adversarial: Startup Self-Test
    Self_Test_Active : BOOL;
    Self_Test_Step : INT := 0;
    Self_Test_Passed : BOOL;
    Self_Test_Timer : TON;
END_VAR

// Startup Self-Test Routine
IF NOT Self_Test_Passed AND NOT System_Fault THEN
    Self_Test_Active := TRUE;
    Self_Test_Timer(IN:=TRUE, PT:=T#2s);
    CASE Self_Test_Step OF
        0: Tensioner_Pump := TRUE; // Test pump
           IF Self_Test_Timer.Q THEN Self_Test_Step := 1; Self_Test_Timer(IN:=FALSE); END_IF;
        1: Tensioner_Pump := FALSE; 
           // Verify pressure holds
           IF Tensioner_Pressure > 50.0 THEN Self_Test_Passed := TRUE; Self_Test_Active := FALSE;
           ELSE System_Fault := TRUE; Diagnostic_State := 99; END_IF;
    END_CASE;
END_IF;

IF Primary_Active AND Self_Test_Passed THEN
    // Sensor Drift Detection
    Estimated_Tail_Speed := Estimated_Tail_Speed + Kalman_Gain * (Tail_Pulley_Speed - Estimated_Tail_Speed);
    IF ABS(Estimated_Tail_Speed - Tail_Pulley_Speed) > 2.0 THEN
        Drift_Warning := TRUE;
    END_IF;

    // HIL Digital Twin Sync
    IF HIL_Sync_Active THEN
        IF ABS(Motor_Speed - Virtual_Speed) > 10.0 THEN
            DigitalTwin_Mismatch := TRUE; System_Fault := TRUE; Diagnostic_State := 4;
        END_IF;
    END_IF;

    // Core Logic
    IF Overload_Sensor THEN System_Fault := TRUE; Diagnostic_State := 1; END_IF;
    IF Motor_Run AND (Motor_Speed - Estimated_Tail_Speed > 5.0) THEN System_Fault := TRUE; Diagnostic_State := 2; END_IF;

    IF Motor_Speed < -1.0 AND NOT Motor_Run THEN
        Regen_Active := TRUE;
        IF DC_Bus_Voltage > 750.0 THEN System_Fault := TRUE; Diagnostic_State := 3; END_IF;
    ELSE
        Regen_Active := FALSE;
    END_IF;

    Tensioner_Pump := ((Motor_Run OR Regen_Active) AND NOT System_Fault AND Tensioner_Pressure < 100.0);

    IF Start_PB AND NOT System_Fault AND User_Role >= 1 AND Auth_Token_Valid THEN Motor_Run := TRUE; END_IF;
    IF Stop_PB OR System_Fault THEN Motor_Run := FALSE; END_IF;
END_IF;
END_PROGRAM
