            fbAuditTrail(bExecute:=TRUE, sMessage:='Batch Started', sUser:=sOperatorId, sBatch:=sBatchId);
            eState := HEATING;
        END_IF

    HEATING:
        rTargetTemp := 45.0; // degC
        IF rActualTemp >= rTargetTemp THEN
            fbAuditTrail(bExecute:=TRUE, sMessage:='Heating Complete', sUser:=sOperatorId, sBatch:=sBatchId);
            eState := GRANULATING;
        END_IF

    GRANULATING:
        IF rImpellerPower >= rPowerThreshold THEN
            fbAuditTrail(bExecute:=TRUE, sMessage:='Endpoint Detected via Power', sUser:=sOperatorId, sBatch:=sBatchId);
            eState := COOLING;
        END_IF

    COOLING:
        rTargetTemp := 25.0;
        IF rActualTemp <= rTargetTemp THEN
            fbAuditTrail(bExecute:=TRUE, sMessage:='Cooling Complete', sUser:=sOperatorId, sBatch:=sBatchId);
            eState := DISCHARGE;
        END_IF

    DISCHARGE:
        bBatchComplete := TRUE;
        fbAuditTrail(bExecute:=TRUE, sMessage:='Batch Complete', sUser:=sOperatorId, sBatch:=sBatchId);
        eState := DONE;

    DONE:
        IF NOT bStartBatch THEN
            eState := INIT;
        END_IF

    FAULT:
        // Fault handling
END_CASE
