FUNCTION_BLOCK "RO_Control"
TITLE = 'RO Control System'
VERSION : 0.1

VAR_INPUT
    Start_Cmd : BOOL;
    Stop_Cmd : BOOL;
    Feed_Pressure : REAL;
    Permeate_Conductivity : REAL;
    High_Pressure_Setpoint : REAL;
    Conductivity_Limit : REAL;
    Tank_Level_High : BOOL;
    Ack_Fault : BOOL;
END_VAR

VAR_OUTPUT
    HP_Pump_Run : BOOL;
    HP_Pump_Speed : REAL; // 0.0 - 100.0%
    Inlet_Valve : BOOL;
    Flush_Valve : BOOL;
    System_Fault : BOOL;
    Fault_Code : INT;
END_VAR

VAR
    State : INT; // 0=Off, 1=Startup, 2=Running, 3=Flushing, 4=Fault
    Flush_Timer : TON;
    PID_Inst : "PID_Compact";
    Conductivity_Alarm : BOOL;
END_VAR

BEGIN
    // Conductivity Monitoring
    IF Permeate_Conductivity > Conductivity_Limit THEN
        Conductivity_Alarm := TRUE;
    ELSE
        Conductivity_Alarm := FALSE;
    END_IF;

    // Fault Management
    IF Feed_Pressure < 1.5 THEN
        System_Fault := TRUE;
        Fault_Code := 1; // Low Feed Pressure
    ELSIF Conductivity_Alarm THEN
        System_Fault := TRUE;
        Fault_Code := 2; // High Conductivity
    END_IF;

    IF Ack_Fault THEN
        System_Fault := FALSE;
        Fault_Code := 0;
    END_IF;

    // State Machine
    IF System_Fault THEN
        State := 4;
    ELSIF Stop_Cmd OR Tank_Level_High THEN
        IF State = 2 THEN
            State := 3; // Go to Flush before stopping
        ELSE
            State := 0;
        END_IF;
    ELSIF Start_Cmd AND NOT System_Fault AND State = 0 THEN
        State := 1;
    END_IF;

    CASE State OF
        0: // Off
            HP_Pump_Run := FALSE;
            HP_Pump_Speed := 0.0;
            Inlet_Valve := FALSE;
            Flush_Valve := FALSE;
            Flush_Timer(IN:=FALSE, PT:=T#0S);

        1: // Startup
            Inlet_Valve := TRUE;
            Flush_Valve := FALSE;
            HP_Pump_Run := TRUE;
            State := 2;

        2: // Running
            Inlet_Valve := TRUE;
            Flush_Valve := FALSE;
            HP_Pump_Run := TRUE;

            // PID Control for HP Pump
            PID_Inst(Setpoint := High_Pressure_Setpoint,
                     Feedback := Feed_Pressure,
                     Output => HP_Pump_Speed);

        3: // Flushing
            Inlet_Valve := TRUE;
            Flush_Valve := TRUE;
            HP_Pump_Run := TRUE;
            HP_Pump_Speed := 50.0; // Fixed speed for flush
            Flush_Timer(IN:=TRUE, PT:=T#30S);
            IF Flush_Timer.Q THEN
                State := 0;
            END_IF;

        4: // Fault
            HP_Pump_Run := FALSE;
            HP_Pump_Speed := 0.0;
            Inlet_Valve := FALSE;
            Flush_Valve := FALSE;
    END_CASE;
END_FUNCTION_BLOCK
```

