VAR
    TYPE E_State : (INIT, SELF_TEST, HIL_SYNC, NORMAL, FAULT) := INIT; END_TYPE
    CurrentState : E_State;
    WindDir1 AT %I* : REAL;
    WindDir2 AT %I* : REAL;
    HIL_TwinDir AT %I* : REAL;
    YawMotorCw AT %Q* : BOOL;
    YawMotorCcw AT %Q* : BOOL;
    HydraulicBrake AT %Q* : BOOL;
    TestTimer : TON;
    TestStep : INT;
    DriftAcc : REAL;
    ErrorCode : UINT;
END_VAR

CASE CurrentState OF
    INIT:
        HydraulicBrake := TRUE;
        CurrentState := SELF_TEST;
        TestStep := 1;
    SELF_TEST:
        TestTimer(IN:=TRUE, PT:=T#2S);
        IF TestTimer.Q THEN
            CASE TestStep OF
                1: HydraulicBrake := FALSE; TestStep := 2;
                2: YawMotorCw := TRUE; TestStep := 3;
                3: YawMotorCw := FALSE; YawMotorCcw := TRUE; TestStep := 4;
                4: YawMotorCcw := FALSE; HydraulicBrake := TRUE; CurrentState := HIL_SYNC;
            END_CASE
            TestTimer(IN:=FALSE);
        END_IF;
    HIL_SYNC:
        IF ABS(WindDir1 - HIL_TwinDir) < 5.0 THEN
            CurrentState := NORMAL;
        ELSE
            ErrorCode := 301;
            CurrentState := FAULT;
        END_IF;
    NORMAL:
        IF ABS(WindDir1 - WindDir2) > 2.0 THEN
            DriftAcc := DriftAcc + 0.1;
            IF DriftAcc > 100.0 THEN
                ErrorCode := 102;
                CurrentState := FAULT;
            END_IF;
        ELSE
            DriftAcc := 0.0;
        END_IF;
    FAULT:
        YawMotorCw := FALSE;
        YawMotorCcw := FALSE;
        HydraulicBrake := TRUE;
END_CASE;
