    // Battery Scheduling
    IF #agv_BatteryLvl < 20.0 THEN
        #charge_Req := TRUE;
        #agv_DestNode := 1; // Node 1 is charging station
    ELSIF #agv_BatteryLvl > 95.0 THEN
        #charge_Req := FALSE;
