// Base code for Overhead Gantry Crane
PROGRAM GantryCrane
VAR
    Load_Weight : REAL; // From Load Cell
    Hoist_Position : REAL; // From Encoder
    Target_Position : REAL;
    Sway_Angle : REAL; // Measured or estimated sway
    Overload_Limit : REAL := 5000.0;
    Velocity_Cmd : REAL;
    AntiSway_Kp : REAL := 1.5;
    AntiSway_Kd : REAL := 0.5;
    Fault_Overload : BOOL;
    Crane_Moving : BOOL;
END_VAR

// Load Cell Overload Protection
IF Load_Weight > Overload_Limit THEN
    Fault_Overload := TRUE;
    Velocity_Cmd := 0.0; // Stop immediately
ELSE
    Fault_Overload := FALSE;
END_IF;

// Anti-Sway and Hoist Positioning (Simplified PD control)
IF NOT Fault_Overload AND Crane_Moving THEN
    // Position Error
    VAR Pos_Error : REAL := Target_Position - Hoist_Position; END_VAR

    // Anti-Sway compensation (Oppose sway velocity/angle)
    VAR Sway_Comp : REAL := (Sway_Angle * AntiSway_Kp); END_VAR

    // Calculate Velocity Command
    Velocity_Cmd := (Pos_Error * 0.1) - Sway_Comp;

    // Limit Max Velocity
    IF Velocity_Cmd > 10.0 THEN Velocity_Cmd := 10.0; END_IF;
    IF Velocity_Cmd < -10.0 THEN Velocity_Cmd := -10.0; END_IF;
ELSE
    Velocity_Cmd := 0.0;
END_IF;
END_PROGRAM
