IF NOT Self_Test_Complete THEN
    CASE Self_Test_Step OF
        0: // Init
            LACT_Pump := FALSE;
            Test_TMR(IN:=TRUE, PT:=T#2s);
            IF Test_TMR.Q THEN Self_Test_Step := 1; Test_TMR(IN:=FALSE); END_IF;
