        2: // Pump Bump Test
            LACT_Pump := TRUE;
            Test_TMR(IN:=TRUE, PT:=T#1s);
            IF Test_TMR.Q THEN 
                LACT_Pump := FALSE; 
                Self_Test_Complete := TRUE;
            END_IF;
    END_CASE;
    RETURN; // Halt normal execution until passed
END_IF;

// Sensor Drift Detection (Moving Average)
Flow_History[History_Index] := Actual_Flow;
History_Index := (History_Index + 1) MOD 100;

Sum_Flow := 0.0;
FOR i := 0 TO 99 DO
    Sum_Flow := Sum_Flow + Flow_History[i];
END_FOR;
Flow_Moving_Avg := Sum_Flow / 100.0;

// Evaluate Adversarial Drift
IF ABS(Actual_Flow - Flow_Moving_Avg) > Drift_Tolerance THEN
    Drift_Warning := TRUE;
