    Drift_Warning := FALSE;
END_IF;

// Normal Operation (if Self-Test passed)
IF Self_Test_Complete AND NOT Drift_Warning THEN
    LACT_Pump := TRUE;
ELSE
    LACT_Pump := FALSE;
END_IF;
END_PROGRAM
