FUNCTION_BLOCK "LeakDetectionAdversarial"
VERSION : 0.1
   VAR_INPUT
      InletFlow : Real;   
      OutletFlow : Real;  
      InletPressure : Real; 
      OutletPressure : Real; 
      AvgTemperature : Real;
      DeltaTime : Real;   
      ThresholdMass : Real; 
      ThresholdPressureDrop : Real; 
      ThermalCoeff : Real;
      PN_IO_Status : Word;
      UserRoleLevel : Int; 
      PLC_PrimaryActive : Bool; 
      SelfTestActivate : Bool; // Trigger daily test
      HIL_SyncData : Real; // Sync parameter from digital twin
   END_VAR
   VAR_OUTPUT
      LeakDetected : Bool;
      IsolationValveCommand : Bool;
      SystemFault : Bool;
      DiagnosticCode : Int;
      SCADA_Map : ARRAY[0..14] OF Real; 
      SelfTestActive : Bool;
   END_VAR
   VAR
      AccumulatedMassIn : Real;
      AccumulatedMassOut : Real;
      MassImbalance : Real;
      CompensatedImbalance : Real;
      PrevInletPressure : Real;
      PressureRateOfChange : Real;
      AccessDenied : Bool;
      SensorDriftOffset : Real;
      DriftTimer : Real;
      SimulatedLeakActive : Bool;
   END_VAR

BEGIN
   // Role-based Access Control (IEC 62443)
   IF #UserRoleLevel < 1 THEN
       #AccessDenied := TRUE;
       RETURN; 
   END_IF;

   // Redundant PLC Failover
   IF NOT #PLC_PrimaryActive THEN
       RETURN;
   END_IF;

   // Sensor Drift Detection & Dynamic Recalibration
   #DriftTimer := #DriftTimer + #DeltaTime;
   IF #DriftTimer > 86400.0 THEN // Every 24 hours
       #SensorDriftOffset := (#InletFlow - #OutletFlow) * 0.01; // Example drift calc
       #DriftTimer := 0.0;
   END_IF;

   // Self-Test Routine (simulates leak without physical actuation)
   IF #SelfTestActivate THEN
       #SimulatedLeakActive := TRUE;
       #SelfTestActive := TRUE;
   ELSE
       #SimulatedLeakActive := FALSE;
       #SelfTestActive := FALSE;
   END_IF;

   // Real-time synchronization with HIL digital twin
   // Align threshold with HIL predictions
   #ThresholdMass := #ThresholdMass + (#HIL_SyncData * 0.05);

   // Fault Diagnostic Handler (Profinet)
   IF (#PN_IO_Status <> 16#0000) THEN
       #SystemFault := TRUE;
       #DiagnosticCode := WORD_TO_INT(#PN_IO_Status);
       IF NOT #SimulatedLeakActive THEN
           #IsolationValveCommand := TRUE; 
       END_IF;
   ELSE
       #SystemFault := FALSE;
       #DiagnosticCode := 0;
   END_IF;

   // Mass Balance Calculation (with drift offset)
   #AccumulatedMassIn := #AccumulatedMassIn + ((#InletFlow - #SensorDriftOffset) * #DeltaTime);
   #AccumulatedMassOut := #AccumulatedMassOut + (#OutletFlow * #DeltaTime);
   #MassImbalance := #AccumulatedMassIn - #AccumulatedMassOut;

   // Thermal Expansion Compensation
   #CompensatedImbalance := #MassImbalance - (#MassImbalance * #AvgTemperature * #ThermalCoeff);

   // Pressure Wave Transient Detection
   #PressureRateOfChange := (#PrevInletPressure - #InletPressure) / #DeltaTime;
   #PrevInletPressure := #InletPressure;

   // Leak Condition Logic
   IF (#CompensatedImbalance > #ThresholdMass) OR (#PressureRateOfChange > #ThresholdPressureDrop) OR #SimulatedLeakActive THEN
       #LeakDetected := TRUE;
       IF NOT #SimulatedLeakActive THEN
           #IsolationValveCommand := TRUE; // Physical isolation only if real leak
       ELSE
           #IsolationValveCommand := FALSE; // Suppress actuation in test mode
       END_IF;
   ELSE
       #LeakDetected := FALSE;
       #IsolationValveCommand := FALSE;
   END_IF;

   // SCADA Integration Mapping Array
   #SCADA_Map[0] := #InletFlow;
   #SCADA_Map[1] := #OutletFlow;
   #SCADA_Map[2] := #InletPressure;
   #SCADA_Map[3] := #OutletPressure;
   #SCADA_Map[4] := #CompensatedImbalance;
   #SCADA_Map[5] := #PressureRateOfChange;
   #SCADA_Map[6] := BOOL_TO_REAL(#LeakDetected);
   #SCADA_Map[7] := BOOL_TO_REAL(#IsolationValveCommand);
   #SCADA_Map[8] := BOOL_TO_REAL(#SystemFault);
   #SCADA_Map[9] := INT_TO_REAL(#DiagnosticCode);
   #SCADA_Map[10] := #SensorDriftOffset;
   #SCADA_Map[11] := BOOL_TO_REAL(#SelfTestActive);
   #SCADA_Map[12] := #HIL_SyncData;
END_FUNCTION_BLOCK

