PROGRAM pH_Neutralization
VAR
    pH_PV : REAL;
    pH_SP : REAL := 7.0;
    Error : REAL;
    Kp : REAL := 2.5;
    Ki : REAL := 0.5;
    Kd : REAL := 0.1;
    Integral : REAL;
    Derivative : REAL;
    LastError : REAL;
    dt : REAL := 0.1;
    CV : REAL;
    Acid_Valve_CMD : REAL;
    Base_Valve_CMD : REAL;
    Effluent_pH : REAL;
    Effluent_Safe : BOOL;
END_VAR

Error := pH_SP - pH_PV;

IF ABS(Error) < 1.0 THEN
    Kp := 0.5;
ELSE
    Kp := 2.5;
END_IF;

Integral := Integral + (Error * dt);
Derivative := (Error - LastError) / dt;
CV := (Kp * Error) + (Ki * Integral) + (Kd * Derivative);
LastError := Error;

IF CV > 0.0 THEN
    Acid_Valve_CMD := CV;
    IF Acid_Valve_CMD > 100.0 THEN Acid_Valve_CMD := 100.0; END_IF;
    Base_Valve_CMD := 0.0;
ELSIF CV < 0.0 THEN
    Base_Valve_CMD := ABS(CV);
    IF Base_Valve_CMD > 100.0 THEN Base_Valve_CMD := 100.0; END_IF;
    Acid_Valve_CMD := 0.0;
ELSE
    Acid_Valve_CMD := 0.0;
    Base_Valve_CMD := 0.0;
END_IF;

IF (Effluent_pH >= 6.5) AND (Effluent_pH <= 7.5) THEN
    Effluent_Safe := TRUE;
ELSE
    Effluent_Safe := FALSE;
END_IF;

END_PROGRAM
