    fSwayThreshold : LREAL := 0.5; (* degrees *)
    tSettleTimer : TON;

    (* Payload Weighing *)
    fLoadCellTorque : LREAL;
    fCalculatedWeight : LREAL;
    fMaxPayloadWeight : LREAL := 1500.0; (* kg *)
END_VAR

CASE eState OF
    IDLE:
        IF bStartMission THEN eState := MOVE_X_Y; END_IF

    MOVE_X_Y:
        fbMoveX(Execute := TRUE, Position := fTargetX, Velocity := 2000.0);
        fbMoveY(Execute := TRUE, Position := fTargetY, Velocity := 2000.0);
        IF fbMoveX.Done AND fbMoveY.Done THEN
            fbMoveX(Execute := FALSE);
            fbMoveY(Execute := FALSE);
            eState := ANTI_SWAY_SETTLE;
        END_IF

    ANTI_SWAY_SETTLE:
        tSettleTimer(IN := (ABS(fSwayAngle) < fSwayThreshold), PT := T#2S);
        IF tSettleTimer.Q THEN
            tSettleTimer(IN := FALSE);
            eState := MOVE_Z;
        END_IF

    MOVE_Z:
        fbMoveZ(Execute := TRUE, Position := fTargetZ, Velocity := 1000.0);
        IF fbMoveZ.Done THEN
            fbMoveZ(Execute := FALSE);
            eState := VERIFY_BARCODE;
        END_IF

    VERIFY_BARCODE:
        IF sReadBarcode = sTargetBarcode THEN eState := EXTEND_FORK;
        ELSE bError := TRUE; eState := FAULT; END_IF

    EXTEND_FORK:
        fbMoveFork(Execute := TRUE, Position := fMaxForkLimit, Velocity := 500.0);
        IF fbMoveFork.Done THEN
            fbMoveFork(Execute := FALSE);
            eState := WEIGH_PAYLOAD;
        END_IF

    WEIGH_PAYLOAD:
        (* Dynamic weight calculation based on torque feedback *)
        fCalculatedWeight := fLoadCellTorque * 9.81 * 0.85; (* Scale factor *)
        IF fCalculatedWeight > fMaxPayloadWeight THEN
            bError := TRUE;
            eState := FAULT; (* Overload condition *)
        ELSE
            eState := RETRACT_FORK;
        END_IF

    RETRACT_FORK:
        fbMoveFork(Execute := TRUE, Position := 0.0, Velocity := 500.0);
        IF fbMoveFork.Done THEN
            fbMoveFork(Execute := FALSE);
            eState := COMPLETE;
        END_IF

    COMPLETE:
        bStartMission := FALSE;
        eState := IDLE;

    FAULT:
        (* Handle fault state *)
END_CASE
