IF bEStop THEN
    iState := 0;
    rSteamValveCV := 0.0;
    rClampValveCV := 0.0;
    rNitrogenValveCV := 0.0;
    tonCureTime(IN:=FALSE);
    tonShapingTime(IN:=FALSE);
