    rSteamTempPV_Pri : REAL;
    rSteamTempPV_Sec : REAL;
    rSteamTempPV_Active : REAL;
    bPriSensorFail : BOOL;
    bSensorDriftDetected : BOOL;
    rDriftThreshold : REAL := 5.0; // 5 degrees variance

    rClampPressPV : REAL;
    rNitrogenPressPV : REAL;

    rSteamValveCV : REAL;
    rClampValveCV : REAL;
    rNitrogenValveCV : REAL;

