FUNCTION_BLOCK FB_MachiningCenter_M1
VAR_INPUT
    Start_Machining : BOOL;
    Stop_Machining : BOOL;
    Fluid_Flow_Sensor : REAL;
    Drill_Torque : REAL;
    Tool_Change_Req : BOOL;
    Requested_Tool : INT;
    ATC_Arm_Pos : INT; // 0=Home, 1=Spindle, 2=Magazine
END_VAR
VAR_OUTPUT
    Fluid_Pump_Cmd : BOOL;
    Conveyor_Cmd : BOOL;
    Spindle_Cmd : BOOL;
    ATC_Magazine_Index_Cmd : INT;
    ATC_Arm_Cmd : INT;
    Alarm_Fluid_Low : BOOL;
    Alarm_Tool_Break : BOOL;
    Alarm_ATC_Error : BOOL;
END_VAR
VAR
    Conveyor_Timer : TON;
    Current_Tool : INT := 1;
    ATC_State : INT := 0;
END_VAR

// Fluid logic
Fluid_Pump_Cmd := Start_Machining AND NOT Stop_Machining;
Alarm_Fluid_Low := Fluid_Pump_Cmd AND (Fluid_Flow_Sensor < 10.0);

// Conveyor logic
Conveyor_Timer(IN := Start_Machining, PT := T#5s);
Conveyor_Cmd := Conveyor_Timer.Q;

// Torque logic
IF Drill_Torque > 50.0 THEN
    Alarm_Tool_Break := TRUE;
    Spindle_Cmd := FALSE;
END_IF;

// ATC Logic (Add Depth)
CASE ATC_State OF
    0: // Idle
        IF Tool_Change_Req AND (Requested_Tool <> Current_Tool) AND (Requested_Tool >= 1) AND (Requested_Tool <= 10) THEN
            Spindle_Cmd := FALSE;
            ATC_Magazine_Index_Cmd := Requested_Tool;
            ATC_State := 1;
        END_IF;
    1: // Move to Spindle
        ATC_Arm_Cmd := 1;
        IF ATC_Arm_Pos = 1 THEN ATC_State := 2; END_IF;
    2: // Move to Magazine
        ATC_Arm_Cmd := 2;
        IF ATC_Arm_Pos = 2 THEN
            Current_Tool := Requested_Tool;
            ATC_Arm_Cmd := 0;
            ATC_State := 0;
        END_IF;
    ELSE
        Alarm_ATC_Error := TRUE;
END_CASE;

IF Start_Machining AND NOT Alarm_Tool_Break AND NOT Alarm_Fluid_Low AND ATC_State = 0 THEN
    Spindle_Cmd := TRUE;
END_IF;
END_FUNCTION_BLOCK
