```pascal
FUNCTION_BLOCK FB_MachiningCenter_M4
VAR_INPUT
    Start_Machining : BOOL;
    Stop_Machining : BOOL;
    Fluid_Flow_Sensor : REAL;
    Drill_Torque : REAL;
    Drill_Torque_Redundant : REAL; // For drift detection
    Auth_Token_Valid : BOOL;
    HIL_Sync_Req : BOOL;
    Initiate_Self_Test : BOOL;
END_VAR
VAR_OUTPUT
    Fluid_Pump_Main_Cmd : BOOL;
    Conveyor_Cmd : BOOL;
    Spindle_Cmd : BOOL;
    Global_Fault : BOOL;
    Diagnostic_Code : INT;
    SCADA_Data_Packet : STRUCT
        Machine_State : INT;
        HIL_Synced : BOOL;
        Drift_Detected : BOOL;
    END_STRUCT;
    Self_Test_Complete : BOOL;
END_VAR
VAR
    Torque_Drift : REAL;
    Self_Test_Step : INT := 0;
    HIL_Active : BOOL := FALSE;
END_VAR

// HIL Digital Twin Sync (Add Adversarial)
IF HIL_Sync_Req THEN
    HIL_Active := TRUE;
    SCADA_Data_Packet.HIL_Synced := TRUE;
END_IF;

// Security
IF NOT Auth_Token_Valid THEN
    Global_Fault := TRUE;
    Diagnostic_Code := 99;
    RETURN;
END_IF;

// Self-Test Routine
IF Initiate_Self_Test THEN
    CASE Self_Test_Step OF
        0: 
            Fluid_Pump_Main_Cmd := TRUE; 
            Self_Test_Step := 1;
        1: 
            IF Fluid_Flow_Sensor > 10.0 THEN Self_Test_Step := 2; END_IF;
        2:
            Fluid_Pump_Main_Cmd := FALSE;
            Conveyor_Cmd := TRUE;
            Self_Test_Step := 3;
        3:
            Conveyor_Cmd := FALSE;
            Self_Test_Complete := TRUE;
            Self_Test_Step := 0;
    END_CASE;
    RETURN;
END_IF;

// Sensor Drift Detection
Torque_Drift := ABS(Drill_Torque - Drill_Torque_Redundant);
IF Torque_Drift > 5.0 THEN
    SCADA_Data_Packet.Drift_Detected := TRUE;
    Global_Fault := TRUE;
    Diagnostic_Code := 5; // Sensor Drift Fault
    Spindle_Cmd := FALSE;
    RETURN;
END_IF;

// Main Logic
