```pascal
FUNCTION_BLOCK "Brewery_Mash_Lauter"
VAR_INPUT
    StartProcess : Bool;
    TempSensor : Real;
    ClaritySensor : Real;
END_VAR
VAR_OUTPUT
    HeaterValve : Real;
    AgitatorVFD_Speed : Real;
    LauterPumpRun : Bool;
END_VAR
VAR
    State : Int := 0;
    RestTimer : TON_TIME;
END_VAR
BEGIN
    CASE #State OF
        0: // Idle
            #HeaterValve := 0.0;
            #AgitatorVFD_Speed := 0.0;
            #LauterPumpRun := FALSE;
            IF #StartProcess THEN #State := 10; END_IF;
        10: // Protein Rest
            #AgitatorVFD_Speed := 50.0;
            IF #TempSensor < 50.0 THEN #HeaterValve := 100.0;
            ELSE 
                #HeaterValve := 10.0; 
                #RestTimer(IN:=TRUE, PT:=T#20m);
                IF #RestTimer.Q THEN #RestTimer(IN:=FALSE); #State := 20; END_IF;
            END_IF;
        20: // Lautering
            #LauterPumpRun := TRUE;
            IF #ClaritySensor < 5.0 THEN #State := 30; END_IF;
        30: // Done
            #LauterPumpRun := FALSE;
            #AgitatorVFD_Speed := 0.0;
    END_CASE;
END_FUNCTION_BLOCK
