```pascal
FUNCTION_BLOCK "Brewery_Mash_Lauter_Breadth"
VAR_INPUT
    PN_StatusWord : Word;
    TempSensor_Raw : Int;
    ClaritySensor_Raw : Int;
END_VAR
VAR_OUTPUT
    HeaterValve : Real;
    PN_ControlWord : Word;
    GlobalFault : Bool;
END_VAR
VAR
    TempSensor : Real;
    TempFault : Bool;
    ClarityFault : Bool;
END_VAR
BEGIN
    // Diagnostic Checks (Wire-break / Short-circuit)
    #TempFault := (#TempSensor_Raw < -27648) OR (#TempSensor_Raw > 27648);
    #ClarityFault := (#ClaritySensor_Raw < -27648) OR (#ClaritySensor_Raw > 27648);
    #GlobalFault := #TempFault OR #ClarityFault OR ( (#PN_StatusWord AND 16#0001) = 0 );

    IF #GlobalFault THEN
        #HeaterValve := 0.0;
        #PN_ControlWord := 16#0000; // Stop drives via Profinet
        RETURN;
    END_IF;

    // Scaling
    #TempSensor := INT_TO_REAL(#TempSensor_Raw) / 276.48;

    // Process Logic
    IF #TempSensor < 65.0 THEN
        #HeaterValve := 100.0;
    ELSE
        #HeaterValve := 0.0;
    END_IF;

    #PN_ControlWord := 16#047F; // Ready to operate
END_FUNCTION_BLOCK
