```pascal
FUNCTION_BLOCK "Brewery_Mash_Lauter_Reasoning"
VAR_INPUT
    ActiveController : Bool; // Hot-standby status
    UserRoleLevel : Int; // 1=Operator, 2=Admin (IEC 62443)
    OPC_SetpointUpdate : Real;
    TempSensor : Real;
END_VAR
VAR_OUTPUT
    HeaterValve : Real;
    SyncData : Real;
    SecurityAlarm : Bool;
END_VAR
VAR
    ValidatedSetpoint : Real := 65.0;
END_VAR
BEGIN
    // Role-Based Access Control for Setpoint (IEC 62443 mapping)
    IF #OPC_SetpointUpdate <> #ValidatedSetpoint THEN
        IF #UserRoleLevel >= 2 THEN
            #ValidatedSetpoint := #OPC_SetpointUpdate;
        ELSE
            #SecurityAlarm := TRUE;
        END_IF;
    END_IF;

    // Hot-Standby Failover Logic
    IF NOT #ActiveController THEN
        // Passive mode: receive state from Active
        #ValidatedSetpoint := #SyncData;
        #HeaterValve := 0.0; // Handled by active
        RETURN;
    END_IF;

    // Active mode logic
    #SyncData := #ValidatedSetpoint; // Sync to passive

    IF #TempSensor < #ValidatedSetpoint THEN
        #HeaterValve := 100.0;
    ELSE
        #HeaterValve := 0.0;
    END_IF;
END_FUNCTION_BLOCK
