```pascal
FUNCTION_BLOCK "Brewery_Mash_Lauter_Adversarial"
VAR_INPUT
    TempSensor_1 : Real;
    TempSensor_2 : Real; // Redundant for drift detection
    ClaritySensor : Real;
    HIL_SyncClock : Bool;
END_VAR
VAR_OUTPUT
    DriftAlarm : Bool;
    HIL_StateData : Real;
    FaultInjectionActive : Bool;
    SystemTripped : Bool;
