        fbCamIn(Master := MasterAxis, Slave := KnifeAxis, Execute := TRUE, CamTableID := CamTableID, Periodic := TRUE);
        IF fbCamIn.InSync THEN State := 20; END_IF

    20: // Running - Print Mark Registration
        fbTouchProbe(Axis := MasterAxis, TriggerInput := TriggerInput, Execute := TRUE);
