            PhaseError := (MasterAxis.NcToPlc.ModuloActPos + MarkDistance) - fbTouchProbe.RecordedPosition;
            fbPhasing(Master := MasterAxis, Slave := KnifeAxis, Execute := TRUE, PhaseShift := PhaseError, Velocity := 50.0, Acceleration := 1000.0, Deceleration := 1000.0);
            fbTouchProbe(Axis:=MasterAxis, TriggerInput:=TriggerInput, Execute:=FALSE);
        END_IF

        // Product Missing Detection (No product, no bag strategy)
