VAR
    MasterAxis      : AXIS_REF;
    KnifeAxis       : AXIS_REF;
    fbCamIn         : MC_CamIn;
    fbCamOut        : MC_CamOut;
    State           : INT;

    // SCADA & Security (IEC 62443)
    {attribute 'OPC.UA.DA' := '1'}
    {attribute 'OPC.UA.DA.Access' := '1'}
    MachineSpeedSCADA : LREAL;
    {attribute 'OPC.UA.DA' := '1'}
    ScadaRequestedSetpoint : LREAL := 150.0;
    CurrentUserRole : STRING := 'Operator'; // Role-Based Access Control

    // Redundancy / Failover
    PrimaryTempSensor   AT %I* : LREAL;
    BackupTempSensor    AT %I* : LREAL;
    TempMismatch        : LREAL;
    bSensorFailover     : BOOL;

    ActualTemp          : LREAL;
    DynamicSetpoint     : LREAL;
    HeaterOutput        : LREAL;
    fbSealingPID        : FB_BasicPID;

    // Diagnostics
    Alarms              : ARRAY[1..10] OF STRING;
    eMachineState       : INT;
END_VAR

// Parameter Security Change Request
IF CurrentUserRole = 'Admin' OR CurrentUserRole = 'Maintenance' THEN
    // Allow parameter updates from SCADA if role is authorized
    IF ScadaRequestedSetpoint > 100.0 AND ScadaRequestedSetpoint < 200.0 THEN
        DynamicSetpoint := ScadaRequestedSetpoint + (MasterAxis.NcToPlc.ActVelo * 0.05);
    END_IF
ELSE
    DynamicSetpoint := 150.0 + (MasterAxis.NcToPlc.ActVelo * 0.05); // Default locked
END_IF
MachineSpeedSCADA := MasterAxis.NcToPlc.ActVelo;

// Sensor Failover Logic
TempMismatch := ABS(PrimaryTempSensor - BackupTempSensor);
IF TempMismatch > 5.0 THEN
    Alarms[3] := 'Temperature Sensor Mismatch - Entering Failover';
    bSensorFailover := TRUE;
    ActualTemp := BackupTempSensor;
ELSE
    ActualTemp := PrimaryTempSensor;
    bSensorFailover := FALSE;
END_IF

// Sealing PID
fbSealingPID(fSetpointValue := DynamicSetpoint, fActualValue := ActualTemp, fKp := 2.5, fCtrlOutput => HeaterOutput);

PROGRAM MAIN
VAR
    MasterAxis      : AXIS_REF;
    KnifeAxis       : AXIS_REF;
    State           : INT;

    // SCADA & Security
    {attribute 'OPC.UA.DA' := '1'}
    MachineSpeedSCADA : LREAL;

    // Sensors & Failover
    PrimaryTempSensor   AT %I* : LREAL;
    BackupTempSensor    AT %I* : LREAL;
    bSensorFailover     : BOOL;
    ActualTemp          : LREAL;

    // HIL Digital Twin & Adversarial Detection
    bSimulationMode : BOOL; // HIL Flag
    SimulatedTemp   : LREAL;
    HIL_MasterVelo  : LREAL;

    // Drift Detection
    TempHistory     : ARRAY[1..100] OF LREAL;
    HistoryIndex    : INT := 1;
    DriftVariance   : LREAL;
    ExpectedTemp    : LREAL;

    // Pre-flight Self-Test
    bSelfTestDone   : BOOL;
    bSelfTestFail   : BOOL;
    TestState       : INT;
    Alarms          : ARRAY[1..10] OF STRING;
    HeaterOutput    : LREAL;
END_VAR

// HIL Synchronization
IF bSimulationMode THEN
    ActualTemp := SimulatedTemp; 
    MasterAxis.NcToPlc.ActVelo := HIL_MasterVelo;
ELSE
    IF ABS(PrimaryTempSensor - BackupTempSensor) > 5.0 THEN
        bSensorFailover := TRUE; ActualTemp := BackupTempSensor;
    ELSE ActualTemp := PrimaryTempSensor; bSensorFailover := FALSE; END_IF
END_IF

// Sensor Drift Detection vs Digital Twin Model
ExpectedTemp := 150.0 + (HeaterOutput * 0.5); // Simple Thermal Model
IF ABS(ActualTemp - ExpectedTemp) > 10.0 AND NOT bSimulationMode THEN
    Alarms[4] := 'Thermal Sensor Drift Detected vs Model';
END_IF

// Pre-flight Self-Test Routine
IF NOT bSelfTestDone AND NOT bSelfTestFail THEN
    CASE TestState OF
        0: // Check Heater Actuator
           HeaterOutput := 20.0;
           IF ActualTemp > 30.0 THEN TestState := 1; HeaterOutput := 0.0; END_IF
        1: // Jog Knife Actuator
           // ... (Jog Knife via MC_Jog)
           TestState := 2;
        2: // Test Pass
           bSelfTestDone := TRUE;
           State := 10; // Ready for production
    END_CASE
    RETURN; // Block normal operation until self-test completes
END_IF

// Normal Operation Logic...
MachineSpeedSCADA := MasterAxis.NcToPlc.ActVelo;

