// Base ST Program for Dairy HTST Pasteurizer

// Constants
CONST
    r_BaseTemp : REAL := 60.0;
    r_Z_Value : REAL := 10.0;
    r_HoldVolume : REAL := 50.0;
    r_LegalTempLimit : REAL := 72.0;
    r_LegalHoldTime : REAL := 15.0;
END_CONST

// Calculate Hold Time (Seconds) based on flow rate (Liters/sec)
IF r_FlowRate > 0.0 THEN
    t_HoldTime := r_HoldVolume / r_FlowRate;
ELSE
    t_HoldTime := 0.0;
END_IF;

// PU (Pasteurization Unit) Calculation
// 1 PU = 1 minute at 60C with z=10C
IF r_Temp_HoldTube >= r_BaseTemp THEN
    r_PU_Rate := (10.0 ** ((r_Temp_HoldTube - r_BaseTemp) / r_Z_Value)) / 60.0;
    r_PU_Accumulated := r_PU_Accumulated + (r_PU_Rate * (t_HoldTime / 60.0));
END_IF;

// Legal Divert Valve Interlock
IF r_Temp_HoldTube >= r_LegalTempLimit AND t_HoldTime >= r_LegalHoldTime THEN
    // Forward flow permitted
    b_LegalDivertValve_Fwd := 1;
    b_LegalDivertValve_Div := 0;
    b_Pasteurization_Complete := (r_PU_Accumulated >= r_PU_Target);
ELSE
    // Sub-legal conditions, divert flow
    b_LegalDivertValve_Fwd := 0;
    b_LegalDivertValve_Div := 1;
    b_Pasteurization_Complete := 0;
END_IF;

// Regenerative Heating Control (P-Control for Steam Valve)
r_TempError := (r_LegalTempLimit + 0.5) - r_Temp_Regen;
r_SteamValve_CV := r_TempError * 2.5;

IF r_SteamValve_CV > 100.0 THEN
    r_SteamValve_CV := 100.0;
ELSIF r_SteamValve_CV < 0.0 THEN
    r_SteamValve_CV := 0.0;
END_IF;
