    3: // Final Rinse
        b_WaterValve := 1;
        // Verify conductivity has returned to baseline (water < 2 mS/cm)
        IF r_Conductivity < 2.0 AND t_CIP_Timer.DN THEN
            i_CIP_Step := 0;
            b_WaterValve := 0;
        END_IF;
