FUNCTION_BLOCK "CIP_System"
VERSION : 0.1
VAR_INPUT
    Start_CIP : Bool;
    Stop_CIP : Bool;
    Conductivity_Raw : Real;
END_VAR
VAR_OUTPUT
    Pump_Cmd : Bool;
    Valve_Water : Bool;
    Valve_Caustic : Bool;
    Valve_Acid : Bool;
    Valve_Sanitizer : Bool;
    Valve_Drain : Bool;
    Valve_Return : Bool;
    State_Status : Int;
END_VAR
VAR
    CIP_State : Int := 0;
    Step_Timer : TON_TIME;
END_VAR
VAR_CONSTANT
    COND_WATER : Real := 0.5;
    COND_CAUSTIC : Real := 50.0;
    COND_ACID : Real := 30.0;
END_VAR

BEGIN
    IF Stop_CIP THEN
        CIP_State := 0;
    END_IF;

    CASE CIP_State OF
        0:
            IF Start_CIP THEN CIP_State := 1; END_IF;
            Valve_Water := FALSE; Valve_Caustic := FALSE; Valve_Acid := FALSE; Valve_Sanitizer := FALSE;
            Valve_Drain := FALSE; Valve_Return := FALSE; Pump_Cmd := FALSE;
        1:
            Valve_Water := TRUE; Valve_Drain := TRUE; Pump_Cmd := TRUE;
            IF Conductivity_Raw < COND_WATER THEN
                CIP_State := 2;
                Valve_Water := FALSE; Valve_Drain := FALSE;
            END_IF;
        2:
            Valve_Caustic := TRUE; Valve_Return := TRUE; Pump_Cmd := TRUE;
            IF Conductivity_Raw > COND_CAUSTIC THEN
                CIP_State := 3;
                Valve_Caustic := FALSE;
            END_IF;
        3:
            Valve_Acid := TRUE; Valve_Return := TRUE; Pump_Cmd := TRUE;
            IF Conductivity_Raw > COND_ACID THEN
                CIP_State := 4;
                Valve_Acid := FALSE;
            END_IF;
        4:
            Valve_Sanitizer := TRUE; Valve_Return := TRUE; Pump_Cmd := TRUE;
            Step_Timer(IN:=TRUE, PT:=T#5M);
            IF Step_Timer.Q THEN
                CIP_State := 5;
                Valve_Sanitizer := FALSE; Valve_Return := FALSE; Pump_Cmd := FALSE;
                Step_Timer(IN:=FALSE);
            END_IF;
        5:
            State_Status := 99;
            IF NOT Start_CIP THEN CIP_State := 0; END_IF;
    END_CASE;
    State_Status := CIP_State;
END_FUNCTION_BLOCK
