Here is the Siemens SCL base implementation for the hot steel rolling mill control.

```pascal
FUNCTION_BLOCK "HotRollingMill_Base"
VAR_INPUT
    Enable : Bool;
    SetThickness : Real;
    ActualThickness : Real;
    SetTension : Real;
    ActualTension : Real;
    SetRollGap : Real;
END_VAR
VAR_OUTPUT
    HydraulicValveCmd : Real;
    DriveSpeedCmd : Real;
    AgcError : Real;
END_VAR
VAR
    Kp_AGC : Real := 2.5;
    Ti_AGC : Real := 0.5;
    Kp_Tension : Real := 1.2;
    Integral_AGC : Real;
END_VAR
BEGIN
    IF #Enable THEN
        // AGC Control
        #AgcError := #SetThickness - #ActualThickness;
        #Integral_AGC := #Integral_AGC + (#AgcError * 0.01 / #Ti_AGC);
        #HydraulicValveCmd := (#Kp_AGC * #AgcError) + #Integral_AGC + #SetRollGap;

        // Tension Regulation
        #DriveSpeedCmd := 100.0 + (#Kp_Tension * (#SetTension - #ActualTension));
    ELSE
        #HydraulicValveCmd := 0.0;
        #DriveSpeedCmd := 0.0;
        #Integral_AGC := 0.0;
    END_IF;
END_FUNCTION_BLOCK
```

