```pascal
FUNCTION_BLOCK "HotRollingMill_Depth"
VAR_INPUT
    Enable : Bool;
    SetThickness : Real;
    ActualThickness : Real;
    SetTension : Real;
    ActualTension : Real;
    SetRollGap : Real;
    PyrometerTemp : Real;
    TargetTemp : Real;
END_VAR
VAR_OUTPUT
    HydraulicValveCmd : Real;
    DriveSpeedCmd : Real;
    CoolingSprayValve : Real;
END_VAR
VAR
    Kp_AGC : Real := 2.5;
    Integral_AGC : Real;
    Kp_Temp : Real := 0.5;
END_VAR
BEGIN
    IF #Enable THEN
        // AGC Control
        #Integral_AGC := #Integral_AGC + ((#SetThickness - #ActualThickness) * 0.01);
        #HydraulicValveCmd := (#Kp_AGC * (#SetThickness - #ActualThickness)) + #Integral_AGC + #SetRollGap;

        // Tension Regulation
        #DriveSpeedCmd := 100.0 + (1.2 * (#SetTension - #ActualTension));

        // Cooling Spray Sub-system
        IF #PyrometerTemp > #TargetTemp THEN
            #CoolingSprayValve := (#PyrometerTemp - #TargetTemp) * #Kp_Temp;
        ELSE
            #CoolingSprayValve := 0.0;
        END_IF;
    ELSE
        #HydraulicValveCmd := 0.0;
        #DriveSpeedCmd := 0.0;
        #CoolingSprayValve := 0.0;
        #Integral_AGC := 0.0;
    END_IF;
END_FUNCTION_BLOCK
