```pascal
FUNCTION_BLOCK "HotRollingMill_Breadth"
VAR_INPUT
    Enable : Bool;
    SetThickness : Real;
    ActualThickness : Real;
    SetRollGap : Real;
    Profinet_DriveStatus : Word;
    HydraulicPressSensors : Array[0..1] OF Real;
END_VAR
VAR_OUTPUT
    HydraulicValveCmd : Real;
    DriveSpeedCmd : Real;
    Profinet_DriveCmd : Word;
    Fault_HydraulicLeak : Bool;
    Fault_DriveComm : Bool;
END_VAR
VAR
    Kp_AGC : Real := 2.5;
    Integral_AGC : Real;
END_VAR
BEGIN
    // Diagnostics
    #Fault_HydraulicLeak := ABS(#HydraulicPressSensors[0] - #HydraulicPressSensors[1]) > 10.0;
    #Fault_DriveComm := (#Profinet_DriveStatus = 16#0000);

    IF #Enable AND NOT #Fault_HydraulicLeak AND NOT #Fault_DriveComm THEN
        // AGC Control
        #Integral_AGC := #Integral_AGC + ((#SetThickness - #ActualThickness) * 0.01);
        #HydraulicValveCmd := (#Kp_AGC * (#SetThickness - #ActualThickness)) + #Integral_AGC + #SetRollGap;

        // Profinet Drive Control
        #Profinet_DriveCmd := 16#047F; // Ready & Run
        #DriveSpeedCmd := 100.0;
    ELSE
        #HydraulicValveCmd := 0.0;
        #DriveSpeedCmd := 0.0;
        #Profinet_DriveCmd := 16#047E; // Stop
    END_IF;
END_FUNCTION_BLOCK
