FUNCTION_BLOCK "ContinuousCastingControl"
VERSION : 0.1
VAR_INPUT
    MoldLevelRadioactive : Real; // 0-100%
    MoldLevelEddyCurrent : Real; // 0-100%
    CastingSpeedSetpoint : Real; // m/min
    StartCasting : Bool;
    StopCasting : Bool;
END_VAR
VAR_OUTPUT
    StopperPosition : Real; // 0-100%
    OscillatorFreq : Real; // Hz
    SprayZone1Flow : Real; // L/min
    SprayZone2Flow : Real; // L/min
    SprayZone3Flow : Real; // L/min
END_VAR
VAR
    MoldLevelSetpoint : Real := 80.0;
    ActualMoldLevel : Real;
    PID_Error : Real;
    PID_Integral : Real;
    Kp : Real := 1.5;
    Ki : Real := 0.05;
    OscillatorGain : Real := 10.0; // Hz per m/min
END_VAR

BEGIN
    // Average the two sensors for better reliability
    ActualMoldLevel := (MoldLevelRadioactive + MoldLevelEddyCurrent) / 2.0;

    IF StartCasting THEN
        // Mold Level Control (PI Controller)
        PID_Error := MoldLevelSetpoint - ActualMoldLevel;
        PID_Integral := PID_Integral + (PID_Error * Ki);
        StopperPosition := (PID_Error * Kp) + PID_Integral;

        // Limits
        IF StopperPosition > 100.0 THEN StopperPosition := 100.0; END_IF;
        IF StopperPosition < 0.0 THEN StopperPosition := 0.0; END_IF;

        // Oscillation Drive Synchronization
        OscillatorFreq := CastingSpeedSetpoint * OscillatorGain;

        // Secondary Cooling Spray Zones based on casting speed
        SprayZone1Flow := CastingSpeedSetpoint * 50.0;
        SprayZone2Flow := CastingSpeedSetpoint * 40.0;
        SprayZone3Flow := CastingSpeedSetpoint * 30.0;
    ELSE
        StopperPosition := 0.0;
        OscillatorFreq := 0.0;
        SprayZone1Flow := 0.0;
        SprayZone2Flow := 0.0;
        SprayZone3Flow := 0.0;
        PID_Integral := 0.0;
    END_IF;

    IF StopCasting THEN
        StopperPosition := 0.0;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "ContinuousCastingControl_Depth"
VERSION : 0.1
VAR_INPUT
    MoldLevelRadioactive : Real; // 0-100%
    MoldLevelEddyCurrent : Real; // 0-100%
    CastingSpeedSetpoint : Real; // m/min
    StartCasting : Bool;
    StopCasting : Bool;
    ThermocouplesMoldTop : ARRAY[1..10] OF Real; // Deg C
    ThermocouplesMoldBottom : ARRAY[1..10] OF Real; // Deg C
END_VAR
VAR_OUTPUT
    StopperPosition : Real; // 0-100%
    OscillatorFreq : Real; // Hz
    SprayZone1Flow : Real; // L/min
    SprayZone2Flow : Real; // L/min
    SprayZone3Flow : Real; // L/min
    EmergencyStop : Bool;
    BreakoutAlarm : Bool;
END_VAR
VAR
    MoldLevelSetpoint : Real := 80.0;
    ActualMoldLevel : Real;
    PID_Error : Real;
    PID_Integral : Real;
    Kp : Real := 1.5;
    Ki : Real := 0.05;
    OscillatorGain : Real := 10.0;
    i : Int;
    TempDiff : Real;
    MaxTempDiff : Real := 40.0; // Threshold for sticker breakout
END_VAR

BEGIN
    // Breakout Detection Algorithm
    BreakoutAlarm := FALSE;
    FOR i := 1 TO 10 DO
        // Heat flux inversion detection (simplified sticker logic)
        TempDiff := ThermocouplesMoldBottom[i] - ThermocouplesMoldTop[i];
        IF TempDiff > MaxTempDiff THEN
            BreakoutAlarm := TRUE;
            EmergencyStop := TRUE;
        END_IF;
    END_FOR;

    // Normal Operations
    ActualMoldLevel := (MoldLevelRadioactive + MoldLevelEddyCurrent) / 2.0;

    IF StartCasting AND NOT EmergencyStop THEN
        PID_Error := MoldLevelSetpoint - ActualMoldLevel;
        PID_Integral := PID_Integral + (PID_Error * Ki);
        StopperPosition := (PID_Error * Kp) + PID_Integral;

        IF StopperPosition > 100.0 THEN StopperPosition := 100.0; END_IF;
        IF StopperPosition < 0.0 THEN StopperPosition := 0.0; END_IF;

        OscillatorFreq := CastingSpeedSetpoint * OscillatorGain;
        SprayZone1Flow := CastingSpeedSetpoint * 50.0;
        SprayZone2Flow := CastingSpeedSetpoint * 40.0;
        SprayZone3Flow := CastingSpeedSetpoint * 30.0;
    ELSE
        StopperPosition := 0.0;
        OscillatorFreq := 0.0;
        SprayZone1Flow := 0.0;
        SprayZone2Flow := 0.0;
        SprayZone3Flow := 0.0;
    END_IF;

    IF StopCasting OR EmergencyStop THEN
        StopperPosition := 0.0;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "ContinuousCastingControl_Breadth"
VERSION : 0.1
VAR_INPUT
    MoldLevelRadioactive : Real; 
    MoldLevelEddyCurrent : Real;
    CastingSpeedSetpoint : Real;
    StartCasting : Bool;
    StopCasting : Bool;
    Profinet_Turret_Status : Word;
    Profinet_Tundish_Status : Word;
END_VAR
VAR_OUTPUT
    StopperPosition : Real;
    OscillatorFreq : Real;
    SprayZone1Flow : Real;
    SprayZone2Flow : Real;
    SprayZone3Flow : Real;
    Profinet_Caster_Status : Word;
    AlarmBitmapHMI : DWord; // Bit 0: Low Level, Bit 1: High Level, Bit 2: Comms Error
END_VAR
VAR
    MoldLevelSetpoint : Real := 80.0;
    ActualMoldLevel : Real;
    PID_Error : Real;
    PID_Integral : Real;
    Kp : Real := 1.5;
    Ki : Real := 0.05;
    OscillatorGain : Real := 10.0;
END_VAR

BEGIN
    // Communication Diagnostics
    AlarmBitmapHMI := 16#00000000;
    IF (Profinet_Turret_Status AND 16#0001) = 0 OR (Profinet_Tundish_Status AND 16#0001) = 0 THEN
        AlarmBitmapHMI := AlarmBitmapHMI OR 16#00000004; // Bit 2
    END_IF;

    ActualMoldLevel := (MoldLevelRadioactive + MoldLevelEddyCurrent) / 2.0;

    // Level Diagnostics
    IF ActualMoldLevel < 20.0 THEN
        AlarmBitmapHMI := AlarmBitmapHMI OR 16#00000001; // Bit 0
    ELSIF ActualMoldLevel > 95.0 THEN
        AlarmBitmapHMI := AlarmBitmapHMI OR 16#00000002; // Bit 1
    END_IF;

    IF StartCasting THEN
        PID_Error := MoldLevelSetpoint - ActualMoldLevel;
        PID_Integral := PID_Integral + (PID_Error * Ki);
        StopperPosition := (PID_Error * Kp) + PID_Integral;

        IF StopperPosition > 100.0 THEN StopperPosition := 100.0; END_IF;
        IF StopperPosition < 0.0 THEN StopperPosition := 0.0; END_IF;

        OscillatorFreq := CastingSpeedSetpoint * OscillatorGain;
        SprayZone1Flow := CastingSpeedSetpoint * 50.0;
        SprayZone2Flow := CastingSpeedSetpoint * 40.0;
        SprayZone3Flow := CastingSpeedSetpoint * 30.0;
        Profinet_Caster_Status := 16#0003; // Running + Ready
    ELSE
        StopperPosition := 0.0;
        OscillatorFreq := 0.0;
        SprayZone1Flow := 0.0;
        SprayZone2Flow := 0.0;
        SprayZone3Flow := 0.0;
        Profinet_Caster_Status := 16#0001; // Ready
    END_IF;

    IF StopCasting THEN
        StopperPosition := 0.0;
        Profinet_Caster_Status := 16#0000; // Stopped
    END_IF;
END_FUNCTION_BLOCK

