// Sensor Drift Compensation
fbFilter(fIn := fDancerPosRaw, fTc := 0.1, fOut => fDancerPosFiltered);
IF ABS(fDancerPosFiltered - fDancerPosRaw) > 5.0 THEN
    fDriftOffset := fDriftOffset + 0.01 * (fDancerPosRaw - fDancerPosFiltered);
END_IF
fDancerPosDriftComp := fDancerPosRaw - fDriftOffset;

// Pre-Startup Self Test
IF NOT bEnable AND NOT bSelfTestPass THEN
    CASE iTestStep OF
        0: 
            fWinderSpeedRef := 10.0; // Test velocity step
            fbTestTimer(IN:=TRUE, PT:=T#100MS);
            IF fbTestTimer.Q THEN iTestStep := 1; END_IF
        1:
            IF stHIL_DataRx.fActualVelocity > 8.0 THEN
                bSelfTestPass := TRUE;
                fWinderSpeedRef := 0.0;
            ELSE
                bEStop := TRUE; // Actuator failed to respond
            END_IF
    END_CASE
END_IF

// HIL Synchronization
IF bHIL_ModeActive THEN
    stHIL_DataTx.fSpeedRef := fWinderSpeedRef;
    fbUDP_Send(bExecute := TRUE, sRemoteHost := '192.168.1.100', nRemotePort := 5000, pSrc := ADR(stHIL_DataTx), cbLen := SIZEOF(stHIL_DataTx));
END_IF

IF bSelfTestPass AND NOT bEStop THEN
    fbDancerPID(fSetpoint := 50.0, fActualValue := fDancerPosDriftComp, bEnable := bEnable, fKp := 2.5, fKi := 0.5, fOutput => fWinderSpeedRef);
END_IF
END_PROGRAM

