        ErrorCode : Int;
        Timestamp : DTL;
    END_STRUCT;
    Error_Idx : Int := 0;
    Ret_Val : Int;
END_VAR
BEGIN
    // Read upstream status from Profinet
    IF PN_Recv[0] = 16#FF THEN
        // Upstream fault detected
        Error_Buffer[Error_Idx].ErrorCode := 1001;
        Ret_Val := RD_SYS_T(Error_Buffer[Error_Idx].Timestamp);
        Error_Idx := (Error_Idx + 1) MOD 100;
    END_IF;

    // Write downstream status to Profinet
    PN_Send[0] := 16#01; // Ready signal
