FUNCTION_BLOCK "Lyophilizer_Control"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    SetPoint_Vacuum : Real;
    SetPoint_ShelfTemp : Real;
    Defrost_Req : Bool;
    Actual_Vacuum : Real;
    Actual_ShelfTemp : Real;
    Actual_CondenserTemp : Real;
END_VAR
VAR_OUTPUT
    Vacuum_Valve : Bool;
    Vacuum_Pump : Bool;
    Shelf_Heating : Real;
    Shelf_Cooling : Real;
    Condenser_Cooling : Bool;
    Defrost_Heater : Bool;
    State : Int;
END_VAR
VAR
    PID_Shelf : "PID_Compact";
    Step : Int;
END_VAR
BEGIN
    IF Stop THEN
        Step := 0;
    ELSIF Start AND Step = 0 THEN
        Step := 10;
    END_IF;
    CASE Step OF
        0: // Idle
            Vacuum_Valve := False;
            Vacuum_Pump := False;
            Condenser_Cooling := False;
            Defrost_Heater := False;
        10: // Freezing
            Condenser_Cooling := True;
            IF Actual_CondenserTemp < -40.0 THEN
                Step := 20;
            END_IF;
        20: // Sublimation
            Vacuum_Pump := True;
            IF Actual_Vacuum > SetPoint_Vacuum THEN
                Vacuum_Valve := True;
            ELSE
                Vacuum_Valve := False;
            END_IF;
            #PID_Shelf(Setpoint := SetPoint_ShelfTemp, Input := Actual_ShelfTemp);
            IF #PID_Shelf.Output > 0.0 THEN
                Shelf_Heating := #PID_Shelf.Output;
                Shelf_Cooling := 0.0;
            ELSE
                Shelf_Heating := 0.0;
                Shelf_Cooling := ABS(#PID_Shelf.Output);
            END_IF;
            IF Defrost_Req THEN
                Step := 30;
            END_IF;
        30: // Defrost
            Vacuum_Pump := False;
            Vacuum_Valve := False;
            Condenser_Cooling := False;
            Defrost_Heater := True;
            IF Actual_CondenserTemp > 20.0 THEN
                Defrost_Heater := False;
                Step := 0;
            END_IF;
    END_CASE;
    State := Step;
END_FUNCTION_BLOCK
