   VAR 
      pid_wicket : "PID_Compact";
      active_control : Bool; 
      turbine_running : Bool;
      sync_ok, alarm_water_hammer, alarm_vibration : Bool;
      sensor_drift_fault : Bool;
      self_test_step : Int;
      self_test_timer : TON;
      vibration_level : Real;
      prev_pressure, roc_pressure : Real; 
      sample_timer : TON;
   END_VAR

BEGIN
    // HIL Digital Twin Sync
    IF #hil_sim_mode THEN
        // In simulation, bypass physical sensor checks or apply model overrides
        #sensor_drift_fault := FALSE;
        #vibration_level := #vib_sensor_1; // Trust primary model input
    ELSE
        // Physical operation: Dual Sensor Drift Detection
        IF ABS(#vib_sensor_1 - #vib_sensor_2) > 1.5 THEN
            #sensor_drift_fault := TRUE;
        ELSE
            #sensor_drift_fault := FALSE;
        END_IF;
        #vibration_level := (#vib_sensor_1 + #vib_sensor_2) / 2.0;
    END_IF;

    // Failover & RBAC 
    #active_control := #is_primary OR NOT #peer_plc_alive;
    VAR 
        has_control_rights : Bool; 
