FUNCTION_BLOCK "Solar_Tracker_Cooling"
VERSION : 0.1
   VAR_INPUT
      SysTime : DTL;
      WindSpeed : REAL;
      PV_Voltage : REAL;
      PV_Current : REAL;
      IGBT_Temp : REAL;
      Ambient_Temp : REAL;
   END_VAR
   VAR_OUTPUT
      TrackerAngle : REAL;
      MPPT_Power : REAL;
      Stow_Active : BOOL;
      Fan_Stage : INT;
   END_VAR
BEGIN
   #MPPT_Power := #PV_Voltage * #PV_Current;

   IF #WindSpeed >= 15.0 THEN
      #Stow_Active := TRUE;
      #TrackerAngle := 0.0;
   ELSE
      #Stow_Active := FALSE;
      #TrackerAngle := (12.0 - USINT_TO_REAL(#SysTime.HOUR)) * 15.0;
   END_IF;

   // Active cooling control
   IF #IGBT_Temp > 80.0 THEN
      #Fan_Stage := 3;
   ELSIF #IGBT_Temp > 65.0 THEN
      #Fan_Stage := 2;
   ELSIF #IGBT_Temp > 50.0 AND #Ambient_Temp > 30.0 THEN
      #Fan_Stage := 1;
   ELSE
      #Fan_Stage := 0;
   END_IF;
END_FUNCTION_BLOCK
