FUNCTION_BLOCK "Solar_Tracker_Secure"
VERSION : 0.1
   VAR_INPUT
      Auth_Valid : BOOL;
      SCADA_Heartbeat : BOOL;
      Sensor_1_Val : REAL;
      Sensor_2_Val : REAL;
   END_VAR
   VAR_OUTPUT
      TrackerAngle : REAL;
      StatusWord : WORD;
      Failover_Active : BOOL;
   END_VAR
   VAR
      LastHeartbeat : BOOL;
      WatchdogTimer : INT;
      ActiveSensor : REAL;
   END_VAR
BEGIN
   // Cybersecurity Fallback
   IF NOT #Auth_Valid THEN
      #TrackerAngle := 0.0;
      #StatusWord := 16#F000;
      RETURN;
   END_IF;

   // Failover
   IF ABS(#Sensor_1_Val - #Sensor_2_Val) > 5.0 THEN
      #Failover_Active := TRUE;
      #ActiveSensor := #Sensor_1_Val;
   ELSE
      #Failover_Active := FALSE;
      #ActiveSensor := (#Sensor_1_Val + #Sensor_2_Val) / 2.0;
   END_IF;

   // SCADA Watchdog
   IF #SCADA_Heartbeat <> #LastHeartbeat THEN
      #WatchdogTimer := 0;
   ELSE
      #WatchdogTimer := #WatchdogTimer + 1;
   END_IF;
   #LastHeartbeat := #SCADA_Heartbeat;
   #StatusWord := 16#0001;
END_FUNCTION_BLOCK
