PROGRAM PRG_GTCC_Reasoning
VAR
    {attribute 'OPC.UA.DA' := '1'} bStart_Cmd : BOOL;
    {attribute 'OPC.UA.DA' := '1'} fCombustion_Temp_SP : REAL := 1200.0;
    {attribute 'OPC.UA.DA' := '1'} nSystem_Status : INT;

