IF nUser_Privilege < 2 AND fCombustion_Temp_SP > 1300.0 THEN fCombustion_Temp_SP := 1200.0; END_IF

fbPartner_Timeout(IN := NOT bPartner_Heartbeat, PT := T#500MS);
