FUNCTION_BLOCK "BaggageHandling_M2"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    Conv1_PE : Bool;
    Merge_PE : Bool;
    Bag_Weight : Real;
    DriveStatus : "Profinet_Drive_Status";
END_VAR
VAR_OUTPUT
    Conv1_Run : Bool;
    Diverter_Actuate : Bool;
    Alarm_DriveFault : Bool;
END_VAR
VAR
    SystemRunning : Bool;
    MergeTimer : TON;
    CascadeStop : Bool;
    IsOverweight : Bool;
END_VAR

BEGIN
    IF DriveStatus.Fault THEN
        Alarm_DriveFault := TRUE;
        SystemRunning := FALSE;
    ELSE
        Alarm_DriveFault := FALSE;
        IF Start AND NOT Stop THEN
            SystemRunning := TRUE;
        ELSIF Stop THEN
            SystemRunning := FALSE;
        END_IF;
    END_IF;

    MergeTimer(IN := Merge_PE, PT := T#2S);
    CascadeStop := MergeTimer.Q;

    IsOverweight := Bag_Weight > 23.5;
    IF IsOverweight AND Conv1_PE THEN
        Diverter_Actuate := TRUE;
    ELSE
        Diverter_Actuate := FALSE;
    END_IF;

    Conv1_Run := SystemRunning AND NOT CascadeStop AND DriveStatus.Ready;
END_FUNCTION_BLOCK

