```pascal
FUNCTION_BLOCK "SorterControl"
VAR_INPUT
    RFID_Data : DInt;
    RFID_Valid : Bool;
    PE_Entry : Bool;
    Encoder_Pulse : Bool;
    Diverter_Pulse_Dist : Int;
    Diverter_Dwell : Int;
END_VAR
VAR_OUTPUT
    Diverter_Valve : Bool;
END_VAR
VAR
    Shift_Reg : ARRAY[0..2000] OF DInt;
    PE_Entry_Prev : Bool;
    Dwell_Count : Int;
    i : Int;
END_VAR
BEGIN
    // Shift register on encoder pulse
    IF Encoder_Pulse THEN
        FOR i := 2000 TO 1 BY -1 DO
            Shift_Reg[i] := Shift_Reg[i-1];
        END_FOR;
        Shift_Reg[0] := 0;

        IF Dwell_Count > 0 THEN
            Dwell_Count := Dwell_Count - 1;
        ELSE
            Diverter_Valve := FALSE;
        END_IF;
    END_IF;

    // Enter parcel into shift register
    IF PE_Entry AND NOT PE_Entry_Prev AND RFID_Valid THEN
        Shift_Reg[0] := RFID_Data;
    END_IF;
    PE_Entry_Prev := PE_Entry;

    // Fire diverter if destination matches (e.g., dest 1)
    IF Shift_Reg[Diverter_Pulse_Dist] = 1 THEN
        Diverter_Valve := TRUE;
        Dwell_Count := Diverter_Dwell;
        Shift_Reg[Diverter_Pulse_Dist] := 0; // Clear after divert
    END_IF;
END_FUNCTION_BLOCK
```

This code tracks parcels by shifting an array every encoder pulse. When the parcel reaches the diverter distance, it fires the valve.

