```pascal
FUNCTION_BLOCK "SorterWithGapOpt"
VAR_INPUT
    RFID_Data : DInt;
    RFID_Valid : Bool;
    PE_Entry : Bool;
    Encoder_Pulse : Bool;
    LightCurtain_Val : Real; // Parcel length in mm
    Downstream_Congestion : Real; // 0.0 to 1.0 (100% full)
    Nominal_Induction_Speed : Real;
END_VAR
VAR_OUTPUT
    Diverter_Valve : Bool;
    Induction_Speed_Cmd : Real;
END_VAR
VAR
    Shift_Reg : ARRAY[0..2000] OF DInt;
    PE_Entry_Prev : Bool;
    Dwell_Count : Int;
    i : Int;
    Target_Gap : Real;
    Speed_Factor : Real;
END_VAR
BEGIN
    // Gap Optimization Control Loop
    // Target gap increases as downstream congestion increases
    Target_Gap := 500.0 + (Downstream_Congestion * 1000.0);

    // Adjust induction speed based on parcel size and required gap
    IF LightCurtain_Val > 800.0 THEN
        Speed_Factor := 0.8; // Slow down for large parcels
    ELSE
        Speed_Factor := 1.0;
    END_IF;

    // Calculate final speed command
    Induction_Speed_Cmd := Nominal_Induction_Speed * Speed_Factor * (1.0 - (Downstream_Congestion * 0.5));

    // Shift register on encoder pulse
    IF Encoder_Pulse THEN
        FOR i := 2000 TO 1 BY -1 DO
            Shift_Reg[i] := Shift_Reg[i-1];
        END_FOR;
        Shift_Reg[0] := 0;
        IF Dwell_Count > 0 THEN Dwell_Count := Dwell_Count - 1; ELSE Diverter_Valve := FALSE; END_IF;
    END_IF;

    // Enter parcel
    IF PE_Entry AND NOT PE_Entry_Prev AND RFID_Valid THEN
        Shift_Reg[0] := RFID_Data;
    END_IF;
    PE_Entry_Prev := PE_Entry;

    // Fire diverter
    IF Shift_Reg[500] = 1 THEN
        Diverter_Valve := TRUE;
        Dwell_Count := 20;
        Shift_Reg[500] := 0;
    END_IF;
END_FUNCTION_BLOCK
```

This function block integrates a gap optimization strategy by calculating a `Target_Gap` and scaling the `Induction_Speed_Cmd` based on real-time parcel dimensions from the light curtain and downstream congestion metrics.

