FUNCTION_BLOCK "OverlandConveyorBreadth"
VERSION : 0.1
   VAR_INPUT 
      StartCmd : Bool;
      StopCmd : Bool;
      AckCmd : Bool;
      EStopOK : Bool;
      BeltTearSensor : Bool;
      TailSpeedFb : Real;
      TensionLoadCell : Real;
      OreFeedRate : Real;
   END_VAR
   VAR_IN_OUT 
      VFD_PNIO : "UdtVfdProfinet";
   END_VAR
   VAR_OUTPUT 
      SystemState : Int; // 0=Stop, 1=Run, 2=Fault
   END_VAR
   VAR 
      DiagWarning : Bool;
      DiagTrip : Bool;
      DiagEStop : Bool;
      TimestampTrip : DTL;
      RunCmd : Bool;
      SlipTimer : TON;
      SpeedRefReal : Real;
   END_VAR
   VAR CONSTANT 
      CTRL_ON : Word := 16#047F;
      CTRL_OFF : Word := 16#047E;
   END_VAR

BEGIN
    // Diagnostics & Alarms
    #DiagEStop := NOT #EStopOK;

    IF #BeltTearSensor THEN
        #DiagTrip := TRUE;
    END_IF;

    #SlipTimer(IN := (INT_TO_REAL(#VFD_PNIO.ActualSpeed) > 100.0) AND (#TailSpeedFb < 50.0), PT := T#2s);
    IF #SlipTimer.Q THEN
        #DiagTrip := TRUE;
    END_IF;

    IF #TensionLoadCell > 200.0 THEN
        #DiagWarning := TRUE;
    END_IF;

    // Timestamping Trip
    IF #DiagTrip AND (#TimestampTrip.YEAR = 1970) THEN
        RD_SYS_T(#TimestampTrip);
    END_IF;

    // Acknowledgment
    IF #AckCmd THEN
        #DiagWarning := FALSE;
        #DiagTrip := FALSE;
        #DiagEStop := NOT #EStopOK; // Re-evaluate
        #TimestampTrip := DTL#1970-01-01-00:00:00;
    END_IF;

    // Control Logic
    IF #StartCmd AND NOT #DiagTrip AND NOT #DiagEStop THEN
        #RunCmd := TRUE;
    ELSIF #StopCmd OR #DiagTrip OR #DiagEStop THEN
        #RunCmd := FALSE;
    END_IF;

    // VFD Profinet Mapping
    IF #RunCmd THEN
        #VFD_PNIO.ControlWord := #CTRL_ON;
        #SpeedRefReal := #OreFeedRate * 1.5; 
        #VFD_PNIO.SpeedSetpoint := REAL_TO_INT(#SpeedRefReal);
        #SystemState := 1;
    ELSE
        #VFD_PNIO.ControlWord := #CTRL_OFF;
        #VFD_PNIO.SpeedSetpoint := 0;
        #SystemState := 0;
    END_IF;

    IF #DiagTrip OR #DiagEStop THEN
        #SystemState := 2;
    END_IF;
END_FUNCTION_BLOCK

// Rationale for Failover:
// Redundancy is handled by a heartbeat signal between PLC A and PLC B. 
// If the active PLC heartbeat times out, the standby PLC takes over bumplessly 
// by copying the last known SCADA setpoints and PID states from the shared Sync DB.

TYPE "UdtScadaInterface"
   STRUCT
      RemoteStart : Bool;
      RemoteStop : Bool;
      ActiveUserRole : Int; // 1=Operator, 2=Maint, 3=Admin (IEC 62443)
      TelemetrySpeed : Real;
      TelemetryTension : Real;
      SetpointTension : Real;
   END_STRUCT;
END_TYPE

FUNCTION_BLOCK "OverlandConveyorReasoning"
VERSION : 0.1
   VAR_INPUT 
      PartnerHeartbeat : Bool;
      IsPrimaryPLC : Bool;
   END_VAR
   VAR_IN_OUT 
      SCADA : "UdtScadaInterface";
      VFD_PNIO : "UdtVfdProfinet";
   END_VAR
   VAR 
      PlcActive : Bool;
      HeartbeatTimer : TON;
      RoleAuthorized : Bool;
   END_VAR

BEGIN
    // PLC Redundancy & Failover Logic
    #HeartbeatTimer(IN := NOT #PartnerHeartbeat, PT := T#500ms);
    IF #IsPrimaryPLC AND NOT #HeartbeatTimer.Q THEN
        #PlcActive := TRUE;
    ELSIF NOT #IsPrimaryPLC AND #HeartbeatTimer.Q THEN
        #PlcActive := TRUE; // Bumpless takeover
    ELSE
        #PlcActive := FALSE;
    END_IF;

    // Execute control only if this PLC is active
    IF #PlcActive THEN
        // IEC 62443 Role-Based Access Control
        #RoleAuthorized := (#SCADA.ActiveUserRole = 1) OR (#SCADA.ActiveUserRole = 3);

        IF #RoleAuthorized THEN
            IF #SCADA.RemoteStart THEN
                #VFD_PNIO.ControlWord := 16#047F;
                #VFD_PNIO.SpeedSetpoint := 1500;
            ELSIF #SCADA.RemoteStop THEN
                #VFD_PNIO.ControlWord := 16#047E;
                #VFD_PNIO.SpeedSetpoint := 0;
            END_IF;
        END_IF;

        // SCADA Telemetry Mapping
        #SCADA.TelemetrySpeed := INT_TO_REAL(#VFD_PNIO.ActualSpeed);
        #SCADA.TelemetryTension := 150.0; 
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "OverlandConveyorAdversarial"
VERSION : 0.1
   VAR_INPUT
      RawTensionLoad : Real;
      HIL_ModeActive : Bool; // Digital Twin Sync
      StartCmd : Bool;
   END_VAR
   VAR_IN_OUT
      VFD_PNIO : "UdtVfdProfinet";
      SCADA : "UdtScadaInterface";
   END_VAR
   VAR
      FilteredTension : Real;
      DriftReference : Real;
      DriftAlarm : Bool;
      SelfTestActive : Bool;
      SelfTestPhase : Int;
      SelfTestTimer : TON;
      PhysicalOutputFrozen : Bool;
      SimulatedFeedback : Real;
   END_VAR
   VAR CONSTANT
      DRIFT_THRESHOLD : Real := 15.0; // kN deviation
   END_VAR

BEGIN
    // 1. Sensor Drift Detection (Adversarial Robustness)
    // Compare fast-moving raw signal against a slow-moving long-term average (reference).
    #FilteredTension := #FilteredTension + 0.1 * (#RawTensionLoad - #FilteredTension); // Fast filter
    #DriftReference := #DriftReference + 0.0001 * (#RawTensionLoad - #DriftReference); // Slow filter

    IF ABS(#FilteredTension - #DriftReference) > #DRIFT_THRESHOLD THEN
        #DriftAlarm := TRUE; // Sensor is drifting unrealistically
    END_IF;

    // 2. Hardware-in-the-Loop (HIL) Digital Twin Mode
    IF #HIL_ModeActive THEN
        #PhysicalOutputFrozen := TRUE;
        // Simulate physical feedback based on SCADA commands
        IF #SCADA.RemoteStart THEN
            #SimulatedFeedback := #SimulatedFeedback + 1.0;
        END_IF;
    ELSE
        #PhysicalOutputFrozen := FALSE;
        #SimulatedFeedback := #RawTensionLoad; // Use real sensor
    END_IF;

    // 3. Automated Self-Test Routine on Startup
    IF #StartCmd AND NOT #SelfTestActive AND #SelfTestPhase = 0 THEN
        #SelfTestActive := TRUE;
        #SelfTestPhase := 1;
    END_IF;

    IF #SelfTestActive THEN
        #SelfTestTimer(IN := TRUE, PT := T#2s);
        CASE #SelfTestPhase OF
            1: // Simulate Tear
                IF #SelfTestTimer.Q THEN
                    #SelfTestPhase := 2;
                    #SelfTestTimer(IN := FALSE, PT := T#2s);
                END_IF;
            2: // Simulate Slip
                IF #SelfTestTimer.Q THEN
                    #SelfTestPhase := 3;
                END_IF;
            3: // Complete
                #SelfTestActive := FALSE;
                #SelfTestPhase := 0; // Ready for actual start
        END_CASE;
    END_IF;

    // Physical Output execution bypassed in HIL mode
    IF NOT #PhysicalOutputFrozen AND NOT #SelfTestActive THEN
        // Standard PLC control logic executes here
        IF #SCADA.RemoteStart THEN
             #VFD_PNIO.ControlWord := 16#047F;
        END_IF;
    END_IF;
END_FUNCTION_BLOCK

