    CommandBuffer : ARRAY[0..99] OF ST_GCodeCmd;
    Head, Tail : INT := 0;
    ToolLength : LREAL := 120.0;
    RotaryOffsetX : LREAL := 10.0;
    RotaryOffsetZ : LREAL := -50.0;
    MachX, MachY, MachZ, MachA, MachB : LREAL;
    TcpX, TcpY, TcpZ : LREAL;
    Execute : BOOL;
END_VAR

IF Execute AND (Head <> Tail) THEN
    TcpX := CommandBuffer[Tail].X;
    TcpY := CommandBuffer[Tail].Y;
    TcpZ := CommandBuffer[Tail].Z;
    MachA := CommandBuffer[Tail].A;
    MachB := CommandBuffer[Tail].B;

    MachX := TcpX - (ToolLength * SIN(MachB * 3.14159/180.0)) + RotaryOffsetX;
    MachY := TcpY + (ToolLength * SIN(MachA * 3.14159/180.0));
    MachZ := TcpZ + (ToolLength * COS(MachA * 3.14159/180.0) * COS(MachB * 3.14159/180.0)) + RotaryOffsetZ;
    Tail := (Tail + 1) MOD 100;
END_IF;
