FuelPressDrift := ABS(FuelPressurePV_A - FuelPressurePV_B);
IF FuelPressDrift > MaxAllowableDrift THEN
    SensorDriftAlarm := 1;
    // Failover to average or safe value
    FuelPressurePV := (FuelPressurePV_A + FuelPressurePV_B) / 2.0;
ELSE
    SensorDriftAlarm := 0;
    FuelPressurePV := FuelPressurePV_A;
END_IF;

// 3. Automated Startup Self-Test Routine
IF InitiateSelfTest THEN
    SelfTestActive := 1;
    CASE SelfTestStep OF
        0: // Test Valve Actuators
            FuelValveCmd := 10.0;
            IF FuelFlowFeedback > 0.0 THEN SelfTestStep := 1; END_IF;
        1: // Verify Air Damper
            AirDamperCmd := 10.0;
            IF AirFlowFeedback > 0.0 THEN SelfTestStep := 2; END_IF;
        2: // Conclude Test
            SelfTestActive := 0;
            InitiateSelfTest := 0;
            SelfTestPassed := 1;
    END_CASE;
END_IF;

// 4. IEC 62443 Security & PLC Redundancy
IF SCADA_Write_Req AND (CurrentUserRole = ROLE_ADMIN) THEN
    AllowSCADA_Write := 1;
ELSE
    AllowSCADA_Write := 0;
END_IF;

IF PeerPLC_Fault THEN PLC_ActiveRole := 1; END_IF;

// Execute Core Process if Active and Passed Self Test
IF PLC_ActiveRole AND SelfTestPassed AND NOT SelfTestActive THEN

    // 5. Fault Diagnostics & SCADA Tags
    SCADA_Status.DriftAlarm := SensorDriftAlarm;
    SCADA_Status.HIL_SyncLoss := HIL_Sync_Lost;
    IF SCADA_Status.HIL_SyncLoss AND SystemMode = MODE_HIL_SIM THEN BMS_Trip := 1; END_IF;

    // 6. BMS Purge & Flame Voting
    TON_Purge(IN := StartPurge AND NOT BMS_Trip, PT := 300000);
    IF TON_Purge.Q THEN PurgeComplete := 1; END_IF;

    ActiveScanners := BOOL_TO_INT(FlameScan1) + BOOL_TO_INT(FlameScan2) + BOOL_TO_INT(FlameScan3);
    MainFlameProven := (ActiveScanners >= 2);
    IF NOT MainFlameProven AND PurgeComplete THEN BMS_Trip := 1; END_IF;

    // 7. Cross-limited Ratio Control
    AirDemand := MAX(BoilerLoadDemand, FuelFlowFeedback * RatioSetpoint);
    FuelDemand := MIN(BoilerLoadDemand, AirFlowFeedback / RatioSetpoint);
    PIDE_Air(PV := AirFlowFeedback, SP := AirDemand, CV => AirDamperCmd);
    PIDE_Fuel(PV := FuelFlowFeedback, SP := FuelDemand, CV => FuelValveCmd);

    // 8. 3-Element Drum Level Control
    PIDE_DrumLevel(PV := DrumLevelPV, SP := DrumLevelSP, CV => LevelOutput);
    FeedwaterDemand := SteamFlowPV + LevelOutput;
    PIDE_Feedwater(PV := FeedwaterFlowPV, SP := FeedwaterDemand, CV => FeedwaterValveCmd);

END_IF;
