// Siemens SCL - Rollercoaster Block Zone Safety System
// Features: Block zone interlocks, friction brake modulation, anti-rollback

FUNCTION_BLOCK FB_BlockZoneSafety
TITLE = 'Rollercoaster Block Zone Safety System'
VERSION : '1.0'

VAR_INPUT
    Zone1_Occupied : BOOL; // Train present in Zone 1
    Zone2_Occupied : BOOL; // Train present in Zone 2
    TrainSpeed : REAL; // Current train speed in m/s
    TrainDirection : INT; // 1 = Forward, -1 = Backward
    E_Stop : BOOL; // Emergency stop active (Active Low)
END_VAR

VAR_OUTPUT
    FrictionBrakeLevel : REAL; // Brake pressure 0.0 - 100.0%
    AntiRollbackDeploy : BOOL; // Deploy anti-rollback dogs
    AllowProceedToZone2 : BOOL; // Interlock to allow train into Zone 2
    Zone1_Clear : BOOL; // Zone 1 is clear
    SystemFault : BOOL; // General fault indicator
END_VAR

VAR
    BrakeIntegral : REAL := 0.0;
    TargetSpeed : REAL := 5.0; // Target speed in brake zone
END_VAR

BEGIN
    // Emergency Stop Logic
    IF NOT E_Stop THEN
        FrictionBrakeLevel := 100.0;
        AntiRollbackDeploy := TRUE;
        AllowProceedToZone2 := FALSE;
        SystemFault := TRUE;
        RETURN;
    END_IF;

    // Zone Clearance Interlock
    Zone1_Clear := NOT Zone1_Occupied;

    // Train is allowed to proceed to Zone 2 ONLY if Zone 2 is unoccupied
    IF Zone1_Occupied AND NOT Zone2_Occupied THEN
        AllowProceedToZone2 := TRUE;
    ELSE
        AllowProceedToZone2 := FALSE;
    END_IF;

    // Friction Brake Modulation (Proportional Control)
    IF Zone1_Occupied AND NOT AllowProceedToZone2 THEN
        // Must stop train
        FrictionBrakeLevel := 100.0;
    ELSIF Zone1_Occupied AND AllowProceedToZone2 THEN
        // Modulate speed
        IF TrainSpeed > TargetSpeed THEN
            FrictionBrakeLevel := (TrainSpeed - TargetSpeed) * 10.0; // P-Gain 10.0
            IF FrictionBrakeLevel > 100.0 THEN
                FrictionBrakeLevel := 100.0;
            END_IF;
        ELSE
            FrictionBrakeLevel := 0.0;
        END_IF;
    ELSE
        FrictionBrakeLevel := 0.0;
    END_IF;

    // Anti-Rollback Logic
    // If train moves backward, immediately deploy anti-rollback
    IF TrainDirection = -1 AND TrainSpeed > 0.1 THEN
        AntiRollbackDeploy := TRUE;
    ELSE
        AntiRollbackDeploy := FALSE;
    END_IF;

    SystemFault := FALSE;

END_FUNCTION_BLOCK

// Siemens SCL - Rollercoaster Block Zone & Launch System
// Features: Block zones, brake modulation, anti-rollback, dynamic weighing, LSM launch sync

FUNCTION_BLOCK FB_Rollercoaster_LaunchSafety
TITLE = 'Rollercoaster Safety and Launch System'
VERSION : '2.0'

VAR_INPUT
    Zone1_Occupied : BOOL;
    Zone2_Occupied : BOOL;
    LaunchZone_Occupied : BOOL;
    TrainSpeed : REAL;
    TrainDirection : INT;
    E_Stop : BOOL;
    LoadCell1_Weight : REAL; // kg
    LoadCell2_Weight : REAL; // kg
    LoadCell3_Weight : REAL; // kg
    LoadCell4_Weight : REAL; // kg
END_VAR

VAR_OUTPUT
    FrictionBrakeLevel : REAL;
    AntiRollbackDeploy : BOOL;
    AllowProceedToZone2 : BOOL;
    TotalTrainMass : REAL; // kg
    LSM_ThrustForce : REAL; // kN
    LSM_LaunchEnable : BOOL;
    SystemFault : BOOL;
    FaultCode : INT;
END_VAR

VAR
    TargetSpeed : REAL := 5.0;
    MaxAllowableMass : REAL := 8000.0; // kg
    MinAllowableMass : REAL := 2500.0; // kg
    BaseThrust : REAL := 50.0; // kN for empty train
    MassThrustFactor : REAL := 0.01; // kN per kg
END_VAR

BEGIN
    // Fault Reset
    SystemFault := FALSE;
    FaultCode := 0;

    // E-Stop handling
    IF NOT E_Stop THEN
        FrictionBrakeLevel := 100.0;
        AntiRollbackDeploy := TRUE;
        LSM_LaunchEnable := FALSE;
        LSM_ThrustForce := 0.0;
        AllowProceedToZone2 := FALSE;
        SystemFault := TRUE;
        FaultCode := 1; // E-Stop
        RETURN;
    END_IF;

    // Dynamic Train Weighing
    IF LaunchZone_Occupied AND TrainSpeed < 0.1 THEN
        TotalTrainMass := LoadCell1_Weight + LoadCell2_Weight + LoadCell3_Weight + LoadCell4_Weight;

        IF TotalTrainMass > MaxAllowableMass THEN
            SystemFault := TRUE;
            FaultCode := 2; // Overweight
            LSM_LaunchEnable := FALSE;
        ELSIF TotalTrainMass < MinAllowableMass THEN
            SystemFault := TRUE;
            FaultCode := 3; // Underweight (sensor fault or empty car error)
            LSM_LaunchEnable := FALSE;
        ELSE
            // Calculate required LSM thrust based on mass
            LSM_ThrustForce := BaseThrust + (TotalTrainMass - MinAllowableMass) * MassThrustFactor;
            // Check next block zone before enabling launch
            IF NOT Zone1_Occupied THEN
                LSM_LaunchEnable := TRUE;
            ELSE
                LSM_LaunchEnable := FALSE;
            END_IF;
        END_IF;
    ELSE
        LSM_LaunchEnable := FALSE;
        LSM_ThrustForce := 0.0;
    END_IF;

    // Block Zone Interlock
    IF Zone1_Occupied AND NOT Zone2_Occupied THEN
        AllowProceedToZone2 := TRUE;
    ELSE
        AllowProceedToZone2 := FALSE;
    END_IF;

    // Brake Modulation
    IF Zone1_Occupied AND NOT AllowProceedToZone2 THEN
        FrictionBrakeLevel := 100.0;
    ELSIF Zone1_Occupied AND AllowProceedToZone2 THEN
        IF TrainSpeed > TargetSpeed THEN
            FrictionBrakeLevel := (TrainSpeed - TargetSpeed) * 15.0;
            IF FrictionBrakeLevel > 100.0 THEN FrictionBrakeLevel := 100.0; END_IF;
        ELSE
            FrictionBrakeLevel := 0.0;
        END_IF;
    ELSE
        FrictionBrakeLevel := 0.0;
    END_IF;

    // Anti-Rollback
    IF TrainDirection = -1 AND TrainSpeed > 0.1 THEN
        AntiRollbackDeploy := TRUE;
    ELSE
        AntiRollbackDeploy := FALSE;
    END_IF;

END_FUNCTION_BLOCK

// Siemens SCL - Rollercoaster System with PROFINET & Diagnostics
// Features: Block zones, brakes, anti-rollback, weighing, LSM, PROFINET, Diagnostics

FUNCTION_BLOCK FB_Rollercoaster_PN_Diag
TITLE = 'Rollercoaster Safety System with PROFINET'
VERSION : '3.0'

VAR_INPUT
    Zone1_Occupied : BOOL;
    Zone2_Occupied : BOOL;
    LaunchZone_Occupied : BOOL;
    TrainSpeed : REAL;
    TrainDirection : INT;
    E_Stop : BOOL;
    LoadCell_Weights : ARRAY[1..4] OF REAL; // PROFINET Input from Remote I/O
    PN_ControlWord : WORD; // Control word from main ride PLC
    PN_Heartbeat_In : INT; 
END_VAR

VAR_OUTPUT
    FrictionBrakeLevel : REAL;
    AntiRollbackDeploy : BOOL;
    AllowProceedToZone2 : BOOL;
    TotalTrainMass : REAL;
    LSM_ThrustForce : REAL;
    LSM_LaunchEnable : BOOL;
    SystemFault : BOOL;
    FaultCode : INT;
    PN_StatusWord : WORD; // Status word to main ride PLC
    PN_Heartbeat_Out : INT;
END_VAR

VAR
    TargetSpeed : REAL := 5.0;
    MaxAllowableMass : REAL := 8000.0;
    MinAllowableMass : REAL := 2500.0;
    BaseThrust : REAL := 50.0;
    MassThrustFactor : REAL := 0.01;

    LastHeartbeat : INT;
    HeartbeatTimer : INT := 0;
    CommFault : BOOL;

    Diag_LoadCell_Diff : REAL;
    i : INT;
END_VAR

BEGIN
    // PROFINET Heartbeat Monitoring
    IF PN_Heartbeat_In <> LastHeartbeat THEN
        HeartbeatTimer := 0;
        LastHeartbeat := PN_Heartbeat_In;
        CommFault := FALSE;
    ELSE
        HeartbeatTimer := HeartbeatTimer + 1;
        IF HeartbeatTimer > 100 THEN // 100 cycles timeout
            CommFault := TRUE;
        END_IF;
    END_IF;
    PN_Heartbeat_Out := PN_Heartbeat_In + 1;

    // Fault Reset
    IF (PN_ControlWord AND 16#0001) <> 0 THEN // Bit 0 is Reset
        SystemFault := FALSE;
        FaultCode := 0;
    END_IF;

    // Fail-safe state on E-Stop or Comm Fault
    IF NOT E_Stop OR CommFault THEN
        FrictionBrakeLevel := 100.0;
        AntiRollbackDeploy := TRUE;
        LSM_LaunchEnable := FALSE;
        LSM_ThrustForce := 0.0;
        AllowProceedToZone2 := FALSE;
        SystemFault := TRUE;
        IF CommFault THEN FaultCode := 10; ELSE FaultCode := 1; END_IF;
        PN_StatusWord := 16#8000; // Fault bit high
        RETURN;
    END_IF;

    // Fault Diagnostics: Load cell discrepancy check
    Diag_LoadCell_Diff := ABS(LoadCell_Weights[1] - LoadCell_Weights[2]);
    IF Diag_LoadCell_Diff > 500.0 THEN
        SystemFault := TRUE;
        FaultCode := 4; // Sensor discrepancy
        LSM_LaunchEnable := FALSE;
    END_IF;

    // Dynamic Train Weighing
    IF LaunchZone_Occupied AND TrainSpeed < 0.1 AND NOT SystemFault THEN
        TotalTrainMass := 0.0;
        FOR i := 1 TO 4 DO
            TotalTrainMass := TotalTrainMass + LoadCell_Weights[i];
        END_FOR;

        IF TotalTrainMass > MaxAllowableMass THEN
            SystemFault := TRUE;
            FaultCode := 2;
            LSM_LaunchEnable := FALSE;
        ELSIF TotalTrainMass < MinAllowableMass THEN
            SystemFault := TRUE;
            FaultCode := 3;
            LSM_LaunchEnable := FALSE;
        ELSE
            LSM_ThrustForce := BaseThrust + (TotalTrainMass - MinAllowableMass) * MassThrustFactor;
            IF NOT Zone1_Occupied AND (PN_ControlWord AND 16#0002) <> 0 THEN // Bit 1 is Launch Req
                LSM_LaunchEnable := TRUE;
            ELSE
                LSM_LaunchEnable := FALSE;
            END_IF;
        END_IF;
    ELSE
        LSM_LaunchEnable := FALSE;
        LSM_ThrustForce := 0.0;
    END_IF;

    // Block Zone Interlock
    AllowProceedToZone2 := Zone1_Occupied AND NOT Zone2_Occupied;

    // Brake Modulation
    IF Zone1_Occupied THEN
        IF NOT AllowProceedToZone2 THEN
            FrictionBrakeLevel := 100.0;
        ELSIF TrainSpeed > TargetSpeed THEN
            FrictionBrakeLevel := (TrainSpeed - TargetSpeed) * 15.0;
            IF FrictionBrakeLevel > 100.0 THEN FrictionBrakeLevel := 100.0; END_IF;
        ELSE
            FrictionBrakeLevel := 0.0;
        END_IF;
    ELSE
        FrictionBrakeLevel := 0.0;
    END_IF;

    // Anti-Rollback
    AntiRollbackDeploy := (TrainDirection = -1 AND TrainSpeed > 0.1);

    // Update Status Word
    PN_StatusWord := 0;
    IF SystemFault THEN PN_StatusWord := PN_StatusWord OR 16#8000; END_IF;
    IF AllowProceedToZone2 THEN PN_StatusWord := PN_StatusWord OR 16#0001; END_IF;
    IF LSM_LaunchEnable THEN PN_StatusWord := PN_StatusWord OR 16#0002; END_IF;

END_FUNCTION_BLOCK

// Siemens SCL - Rollercoaster System with Failover, Cybersecurity, SCADA
// Features: IEC 62443 Security, PLC Failover, SCADA, LSM, Brakes, Diagnostics

FUNCTION_BLOCK FB_Rollercoaster_Secure_Failover
TITLE = 'Secure Redundant Rollercoaster Safety System'
VERSION : '4.0'

VAR_INPUT
    Zone1_Occupied : BOOL;
    Zone2_Occupied : BOOL;
    LaunchZone_Occupied : BOOL;
    TrainSpeed : REAL;
    TrainDirection : INT;
    E_Stop : BOOL;
    LoadCell_Weights : ARRAY[1..4] OF REAL;

    // Failover Inputs
    Is_Primary_PLC : BOOL;
    Partner_PLC_Healthy : BOOL;
    Sync_Data_In : STRUCT
        Active_State : BOOL;
        Brake_Memory : REAL;
    END_STRUCT;

    // SCADA & Security Inputs (IEC 62443)
    SCADA_ControlWord : WORD;
    SCADA_Auth_Token : DWORD; // Rotating security token
    Expected_Auth_Token : DWORD; 
END_VAR

VAR_OUTPUT
    FrictionBrakeLevel : REAL;
    AntiRollbackDeploy : BOOL;
    AllowProceedToZone2 : BOOL;
    TotalTrainMass : REAL;
    LSM_ThrustForce : REAL;
    LSM_LaunchEnable : BOOL;
    SystemFault : BOOL;
    FaultCode : INT;

    // Failover & SCADA Outputs
    Sync_Data_Out : STRUCT
        Active_State : BOOL;
        Brake_Memory : REAL;
    END_STRUCT;
    SCADA_StatusWord : WORD;
    Security_Alarm : BOOL;
END_VAR

VAR
    TargetSpeed : REAL := 5.0;
    MaxAllowableMass : REAL := 8000.0;
    MinAllowableMass : REAL := 2500.0;
    BaseThrust : REAL := 50.0;

    I_Am_Active : BOOL := FALSE;
    Security_Lockout : BOOL := FALSE;
    i : INT;
END_VAR

BEGIN
    // IEC 62443 Security Token Validation
    IF SCADA_Auth_Token <> Expected_Auth_Token THEN
        Security_Alarm := TRUE;
        Security_Lockout := TRUE; // Reject unauthorized SCADA commands
    ELSE
        Security_Alarm := FALSE;
        Security_Lockout := FALSE;
    END_IF;

    // Redundancy & Failover Logic
    // Reasoning: If I am the Primary and healthy, I am active. 
    // If I am Secondary, I become active ONLY if Partner (Primary) is NOT healthy.
    IF Is_Primary_PLC THEN
        I_Am_Active := TRUE;
    ELSE
        IF NOT Partner_PLC_Healthy THEN
            I_Am_Active := TRUE;
        ELSE
            I_Am_Active := FALSE;
        END_IF;
    END_IF;

    // Sync State for Bumpless Transfer
    Sync_Data_Out.Active_State := I_Am_Active;
    Sync_Data_Out.Brake_Memory := FrictionBrakeLevel;

    // If passive standby, output safe defaults but do not drive physical I/O directly
    // Wait for failover to become active
    IF NOT I_Am_Active THEN
        FrictionBrakeLevel := Sync_Data_In.Brake_Memory; // Track active PLC's brake output
        AntiRollbackDeploy := TRUE; 
        LSM_LaunchEnable := FALSE;
        AllowProceedToZone2 := FALSE;
        RETURN;
    END_IF;

    // --- Active PLC Logic ---

    // Fault Reset from SCADA (Only if secure)
    IF NOT Security_Lockout AND (SCADA_ControlWord AND 16#0001) <> 0 THEN
        SystemFault := FALSE;
        FaultCode := 0;
    END_IF;

    // E-Stop handling
    IF NOT E_Stop THEN
        FrictionBrakeLevel := 100.0;
        AntiRollbackDeploy := TRUE;
        LSM_LaunchEnable := FALSE;
        LSM_ThrustForce := 0.0;
        AllowProceedToZone2 := FALSE;
        SystemFault := TRUE;
        FaultCode := 1; 
        SCADA_StatusWord := 16#8000;
        RETURN;
    END_IF;

    // Dynamic Train Weighing
    IF LaunchZone_Occupied AND TrainSpeed < 0.1 AND NOT SystemFault THEN
        TotalTrainMass := 0.0;
        FOR i := 1 TO 4 DO
            TotalTrainMass := TotalTrainMass + LoadCell_Weights[i];
        END_FOR;

        IF TotalTrainMass > MaxAllowableMass THEN
            SystemFault := TRUE;
            FaultCode := 2;
            LSM_LaunchEnable := FALSE;
        ELSIF TotalTrainMass < MinAllowableMass THEN
            SystemFault := TRUE;
            FaultCode := 3;
            LSM_LaunchEnable := FALSE;
        ELSE
            LSM_ThrustForce := BaseThrust + (TotalTrainMass - MinAllowableMass) * 0.01;
            // Launch only if secure SCADA requests it and zone is clear
            IF NOT Zone1_Occupied AND NOT Security_Lockout AND (SCADA_ControlWord AND 16#0002) <> 0 THEN
                LSM_LaunchEnable := TRUE;
            ELSE
                LSM_LaunchEnable := FALSE;
            END_IF;
        END_IF;
    ELSE
        LSM_LaunchEnable := FALSE;
        LSM_ThrustForce := 0.0;
    END_IF;

    // Block Zone Interlock
    AllowProceedToZone2 := Zone1_Occupied AND NOT Zone2_Occupied;

    // Brake Modulation
    IF Zone1_Occupied THEN
        IF NOT AllowProceedToZone2 THEN
            FrictionBrakeLevel := 100.0;
        ELSIF TrainSpeed > TargetSpeed THEN
            FrictionBrakeLevel := (TrainSpeed - TargetSpeed) * 15.0;
            IF FrictionBrakeLevel > 100.0 THEN FrictionBrakeLevel := 100.0; END_IF;
        ELSE
            FrictionBrakeLevel := 0.0;
        END_IF;
    ELSE
        FrictionBrakeLevel := 0.0;
    END_IF;

    // Anti-Rollback
    AntiRollbackDeploy := (TrainDirection = -1 AND TrainSpeed > 0.1);

    // SCADA Status Update
    SCADA_StatusWord := 0;
    IF SystemFault THEN SCADA_StatusWord := SCADA_StatusWord OR 16#8000; END_IF;
    IF AllowProceedToZone2 THEN SCADA_StatusWord := SCADA_StatusWord OR 16#0001; END_IF;
    IF I_Am_Active THEN SCADA_StatusWord := SCADA_StatusWord OR 16#0004; END_IF;

END_FUNCTION_BLOCK

// Siemens SCL - Ultimate Rollercoaster Safety System
// Features: Adversarial Resilience, HIL Twin, Self-Test, Sensor Drift, Failover, Security, LSM

FUNCTION_BLOCK FB_Rollercoaster_Ultimate_Safety
TITLE = 'Ultimate Resilient Rollercoaster Safety System'
VERSION : '5.0'

VAR_INPUT
    // Physical Sensors
    Zone1_Occupied : BOOL;
    Zone2_Occupied : BOOL;
    LaunchZone_Occupied : BOOL;
    Speed_Encoder_1 : REAL; // Primary speed
    Speed_Encoder_2 : REAL; // Secondary speed for drift check
    TrainDirection : INT;
    E_Stop : BOOL;
    LoadCell_Weights : ARRAY[1..4] OF REAL;

    // Failover
    Is_Primary_PLC : BOOL;
    Partner_PLC_Healthy : BOOL;
    Sync_Data_In : STRUCT
        Active_State : BOOL;
        Brake_Memory : REAL;
        Ride_Ready : BOOL;
    END_STRUCT;

    // SCADA & Security
    SCADA_ControlWord : WORD;
    SCADA_Auth_Token : DWORD;
    Expected_Auth_Token : DWORD; 

    // HIL Digital Twin
    HIL_Predicted_Speed : REAL; // Speed expected by Digital Twin physics engine
END_VAR

VAR_OUTPUT
    FrictionBrakeLevel : REAL;
    AntiRollbackDeploy : BOOL;
    AllowProceedToZone2 : BOOL;
    LSM_LaunchEnable : BOOL;
    SystemFault : BOOL;
    FaultCode : INT;

    Sync_Data_Out : STRUCT
        Active_State : BOOL;
        Brake_Memory : REAL;
        Ride_Ready : BOOL;
    END_STRUCT;
    SCADA_StatusWord : WORD;

    Self_Test_Active : BOOL;
    Self_Test_Passed : BOOL;
END_VAR

VAR
    Validated_Speed : REAL;
    Speed_Drift : REAL;
    Twin_Deviation : REAL;

    Security_Lockout : BOOL;
    I_Am_Active : BOOL;

    // Self Test State Machine
    Test_Step : INT := 0;
    Test_Timer : INT := 0;
    Ride_Ready : BOOL := FALSE;

    TargetSpeed : REAL := 5.0;
END_VAR

BEGIN
    // --- Security & Adversarial Checks ---
    Security_Lockout := (SCADA_Auth_Token <> Expected_Auth_Token);

    // Sensor Drift Detection (Encoder 1 vs Encoder 2)
    Speed_Drift := ABS(Speed_Encoder_1 - Speed_Encoder_2);
    IF Speed_Drift > 0.5 THEN
        SystemFault := TRUE;
        FaultCode := 50; // Sensor Drift Detected
    END_IF;
    Validated_Speed := (Speed_Encoder_1 + Speed_Encoder_2) / 2.0;

    // HIL Digital Twin Anomaly Detection (Is physical reality matching physics model?)
    Twin_Deviation := ABS(Validated_Speed - HIL_Predicted_Speed);
    IF Twin_Deviation > 2.0 AND Validated_Speed > 1.0 THEN
        SystemFault := TRUE;
        FaultCode := 51; // Physics anomaly (e.g., unexpected friction/wheel bearing failure)
    END_IF;

    // --- Redundancy & Failover ---
    I_Am_Active := Is_Primary_PLC OR (NOT Is_Primary_PLC AND NOT Partner_PLC_Healthy);
    Sync_Data_Out.Active_State := I_Am_Active;
    Sync_Data_Out.Brake_Memory := FrictionBrakeLevel;
    Sync_Data_Out.Ride_Ready := Ride_Ready;

    IF NOT I_Am_Active THEN
        FrictionBrakeLevel := Sync_Data_In.Brake_Memory;
        AntiRollbackDeploy := TRUE;
        LSM_LaunchEnable := FALSE;
        Ride_Ready := Sync_Data_In.Ride_Ready;
        RETURN;
    END_IF;

    // --- Morning Self-Test Routine ---
    // Initiated via SCADA Bit 8 when train is empty in launch zone
    IF NOT Ride_Ready AND NOT Security_Lockout AND (SCADA_ControlWord AND 16#0100) <> 0 THEN
        Self_Test_Active := TRUE;
        SystemFault := FALSE;
    END_IF;

    IF Self_Test_Active THEN
        Test_Timer := Test_Timer + 1;
        CASE Test_Step OF
            0:  // Test Brakes 100%
                FrictionBrakeLevel := 100.0;
                AntiRollbackDeploy := FALSE;
                IF Test_Timer > 50 THEN Test_Step := 1; Test_Timer := 0; END_IF;
            1:  // Test Anti-Rollback Deployment
                FrictionBrakeLevel := 0.0;
                AntiRollbackDeploy := TRUE;
                IF Test_Timer > 50 THEN Test_Step := 2; Test_Timer := 0; END_IF;
            2:  // Test Brakes 0%
                AntiRollbackDeploy := FALSE;
                FrictionBrakeLevel := 0.0;
                IF Test_Timer > 50 THEN 
                    Self_Test_Active := FALSE;
                    Self_Test_Passed := TRUE;
                    Ride_Ready := TRUE; // Ride is now allowed to operate
                END_IF;
        END_CASE;
        RETURN; // Do not run normal logic during self test
    END_IF;

    // --- Normal Operation (Requires Ride_Ready) ---
    IF NOT E_Stop OR SystemFault OR NOT Ride_Ready THEN
        FrictionBrakeLevel := 100.0;
        AntiRollbackDeploy := TRUE;
        LSM_LaunchEnable := FALSE;
        AllowProceedToZone2 := FALSE;
        IF NOT Ride_Ready THEN FaultCode := 99; END_IF; // 99 = Not Tested
        SCADA_StatusWord := 16#8000;
        RETURN;
    END_IF;

    // Block Zone & Launch Logic (Simplified for space, assuming mass check passed)
    AllowProceedToZone2 := Zone1_Occupied AND NOT Zone2_Occupied;

    IF Zone1_Occupied THEN
        IF NOT AllowProceedToZone2 THEN
            FrictionBrakeLevel := 100.0;
        ELSIF Validated_Speed > TargetSpeed THEN
            FrictionBrakeLevel := (Validated_Speed - TargetSpeed) * 15.0;
            IF FrictionBrakeLevel > 100.0 THEN FrictionBrakeLevel := 100.0; END_IF;
        ELSE
            FrictionBrakeLevel := 0.0;
        END_IF;
    ELSE
        FrictionBrakeLevel := 0.0;
    END_IF;

    AntiRollbackDeploy := (TrainDirection = -1 AND Validated_Speed > 0.1);

    // Status update
    SCADA_StatusWord := 0;
    IF Ride_Ready THEN SCADA_StatusWord := SCADA_StatusWord OR 16#0010; END_IF;

END_FUNCTION_BLOCK

