    i : INT;
END_VAR

HeartbeatTimeout(IN := NOT PrimaryPLC_Active, PT := T#500MS);
TakeoverActive := HeartbeatTimeout.Q;

AuthValid := (ActiveUserRole >= 2) AND (CmdSignature = ExpectedSignature);

IF TakeoverActive AND AuthValid THEN
    DepthError := DepthSetpoint - DepthSensor;
    DepthInt := DepthInt + DepthError;
    DepthControlOut := (1.5 * DepthError) + (0.1 * DepthInt) + (0.05 * (DepthError - PrevError));
