PROGRAM MAIN
VAR
    JoyCmd : ARRAY[1..6] OF REAL;
    DepthSensor1, DepthSensor2, DepthSensor3 : REAL;
    TensionSensor, DepthSetpoint : REAL;
    ThrusterCmd : ARRAY[1..8] OF REAL;
    DriftAlarm : BOOL;
    ValidDepth, MaxDeviation : REAL := 0.5;
    PostState : INT := 0;
    PostTimer : TON;
    ThrustersArmed : BOOL;
    HardwareDegradationSim : REAL := 0.95;
    HIL_Sync_Buffer AT %Q* : ARRAY[0..255] OF BYTE;
    HIL_Data_Tx : BOOL;
    DepthError, DepthInt, PrevError, DepthControlOut : REAL;
END_VAR

CASE PostState OF
    0:
        PostTimer(IN:=TRUE, PT:=T#2S);
        IF PostTimer.Q THEN PostTimer(IN:=FALSE); PostState := 1; END_IF
    1:
        ThrusterCmd[1] := 10.0;
        PostTimer(IN:=TRUE, PT:=T#2S);
        IF PostTimer.Q THEN PostTimer(IN:=FALSE); ThrusterCmd[1] := 0.0; PostState := 2; END_IF
    2:
        ThrustersArmed := TRUE;
END_CASE

IF ABS(DepthSensor1 - DepthSensor2) > MaxDeviation AND ABS(DepthSensor1 - DepthSensor3) > MaxDeviation THEN
    DriftAlarm := TRUE; ValidDepth := (DepthSensor2 + DepthSensor3) / 2.0;
ELSIF ABS(DepthSensor2 - DepthSensor1) > MaxDeviation AND ABS(DepthSensor2 - DepthSensor3) > MaxDeviation THEN
    DriftAlarm := TRUE; ValidDepth := (DepthSensor1 + DepthSensor3) / 2.0;
ELSE
    ValidDepth := DepthSensor1;
END_IF

IF ThrustersArmed THEN
    DepthError := DepthSetpoint - ValidDepth;
    DepthInt := DepthInt + DepthError;
    DepthControlOut := (1.5 * DepthError) + (0.1 * DepthInt) + (0.05 * (DepthError - PrevError));
    PrevError := DepthError;

    ThrusterCmd[1] := (JoyCmd[1] + JoyCmd[2] + JoyCmd[6]) * HardwareDegradationSim;
    ThrusterCmd[2] := (-JoyCmd[1] + JoyCmd[2] - JoyCmd[6]) * HardwareDegradationSim;
    ThrusterCmd[3] := (-JoyCmd[1] - JoyCmd[2] + JoyCmd[6]) * HardwareDegradationSim;
    ThrusterCmd[4] := (JoyCmd[1] - JoyCmd[2] - JoyCmd[6]) * HardwareDegradationSim;
    ThrusterCmd[5] := (JoyCmd[3] + DepthControlOut + JoyCmd[4] + JoyCmd[5]) * HardwareDegradationSim;
    ThrusterCmd[6] := (JoyCmd[3] + DepthControlOut - JoyCmd[4] + JoyCmd[5]) * HardwareDegradationSim;
    ThrusterCmd[7] := (JoyCmd[3] + DepthControlOut - JoyCmd[4] - JoyCmd[5]) * HardwareDegradationSim;
    ThrusterCmd[8] := (JoyCmd[3] + DepthControlOut + JoyCmd[4] - JoyCmd[5]) * HardwareDegradationSim;
END_IF

IF HIL_Data_Tx THEN HIL_Sync_Buffer[0] := 16#FF; END_IF
END_PROGRAM

Here is a basic Siemens SCL program for a Milk Pasteurizer covering the PID loop for the heat exchanger, the holding tube timer, and the flow-divert valve (FDV) safety logic:

```pascal
FUNCTION_BLOCK "MilkPasteurizer_Base"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    TempPasteurizer : REAL; // Actual temperature at holding tube inlet
    FlowRate : REAL;        // Actual flow rate
    SP_Temp : REAL := 72.0; // Setpoint for pasteurization
    HoldingTime : TIME := T#15S; // Legal holding time
END_VAR

VAR_OUTPUT
    HeaterValveControl : REAL; // PID output 0.0 - 100.0%
    PumpRun : BOOL;            // Main pump control
    FDV_Forward : BOOL;        // Flow divert valve to forward flow
    FDV_Divert : BOOL;         // Flow divert valve to divert (reject) flow
    Alarm : BOOL;              // General alarm
END_VAR

VAR
    ProcessActive : BOOL;
    PID_Inst : "PID_Compact";
    HoldingTimer : TON;
    TempOk : BOOL;
END_VAR

BEGIN
    // Process Start/Stop
    IF Start AND NOT Stop THEN
        ProcessActive := TRUE;
    ELSIF Stop THEN
        ProcessActive := FALSE;
    END_IF;

    // Main Pump Control
    PumpRun := ProcessActive;

    // PID Control for Heat Exchanger
    PID_Inst(
        sMode := 3, // Automatic mode
        Setpoint := SP_Temp,
        Input := TempPasteurizer,
        ManualEnable := FALSE,
        Output => HeaterValveControl
    );

    // Temperature Safety Check
    TempOk := (TempPasteurizer >= SP_Temp);

    // Holding Tube Timer
    HoldingTimer(
        IN := TempOk AND ProcessActive,
        PT := HoldingTime
    );

    // Flow Divert Valve Logic (Fail-Safe: Default Divert)
    IF ProcessActive AND HoldingTimer.Q THEN
        FDV_Forward := TRUE;
        FDV_Divert := FALSE;
    ELSE
        FDV_Forward := FALSE;
        FDV_Divert := TRUE;
    END_IF;

    // Alarm Logic
    Alarm := ProcessActive AND NOT TempOk;
END_FUNCTION_BLOCK
```

Here is an advanced Siemens SCL program incorporating regenerative heating, cooling sections, and critical pressure differential monitoring:

```pascal
FUNCTION_BLOCK "MilkPasteurizer_Regen"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    TempRegenOut : REAL;
    TempPastOut : REAL;
    TempCoolOut : REAL;
    PressRawSide : REAL;
    PressPastSide : REAL;
    SP_PastTemp : REAL := 72.0;
    HoldingTime : TIME := T#15S;
END_VAR

VAR_OUTPUT
    HeaterPID_Out : REAL;
    CoolerPID_Out : REAL;
    MainPump : BOOL;
    BoosterPump : BOOL;
    FDV_Forward : BOOL;
    FDV_Divert : BOOL;
    RegenPressureAlarm : BOOL;
    SystemFault : BOOL;
END_VAR

VAR
    State : INT := 0; // 0=Off, 1=WaterCirc, 2=Prod, 3=Fault
    PID_Heater : "PID_Compact";
    PID_Cooler : "PID_Compact";
    TMR_Hold : TON;
    TMR_DP : TON;
    TempOk : BOOL;
    PressOk : BOOL;
END_VAR

BEGIN
    // State Machine
    IF Stop OR SystemFault THEN
        State := 0;
    ELSIF Start AND State = 0 THEN
        State := 1; // Start with water circulation
    END_IF;

    // Pressure Differential Monitoring (Pasteurized side must be higher pressure)
    PressOk := (PressPastSide > PressRawSide + 0.5);
    TMR_DP(IN := NOT PressOk AND (State > 0), PT := T#2S);
    IF TMR_DP.Q THEN
        RegenPressureAlarm := TRUE;
        SystemFault := TRUE;
    END_IF;

    // Temperature Control
    PID_Heater(
        sMode := 3,
        Setpoint := SP_PastTemp,
        Input := TempPastOut,
        Output => HeaterPID_Out
    );

    PID_Cooler(
        sMode := 3,
        Setpoint := 4.0, // 4C target
        Input := TempCoolOut,
        Output => CoolerPID_Out
    );

    // Holding Logic
    TempOk := (TempPastOut >= SP_PastTemp);
    TMR_Hold(IN := TempOk AND State > 0, PT := HoldingTime);

    // Outputs
    MainPump := (State > 0);
    BoosterPump := MainPump AND PressOk;

    // FDV Logic
    IF State = 2 AND TMR_Hold.Q AND PressOk THEN
        FDV_Forward := TRUE;
        FDV_Divert := FALSE;
    ELSE
        FDV_Forward := FALSE;
        FDV_Divert := TRUE;
    END_IF;
END_FUNCTION_BLOCK
```

Here is the Siemens SCL program integrating Profinet IO diagnostics and fault handling for a Milk Pasteurizer:

```pascal
FUNCTION_BLOCK "MilkPasteurizer_Profinet"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    TempPastOut : REAL;
    HW_IO_ValveTerminal : HW_DEVICE; // Profinet Hardware ID
END_VAR

VAR_OUTPUT
    HeaterPID_Out : REAL;
    FDV_Forward : BOOL;
    FDV_Divert : BOOL;
    ErrorCode : WORD;
    AlarmActive : BOOL;
END_VAR

VAR
    ProcessActive : BOOL;
    PID_Heater : "PID_Compact";
    TMR_Hold : TON;
    TempOk : BOOL;
    DeviceStatus : DINT;
    PN_Diag : "DeviceStates";
    DeviceFault : BOOL;
END_VAR

BEGIN
    // Profinet Device Diagnostics
    PN_Diag(
        LADDR := HW_IO_ValveTerminal,
        MODE := 2, // Check for faults
        STATE := DeviceStatus
    );
    DeviceFault := (DeviceStatus <> 0);

    // Start/Stop Logic
    IF Start AND NOT Stop AND NOT DeviceFault THEN
        ProcessActive := TRUE;
    ELSIF Stop OR DeviceFault THEN
        ProcessActive := FALSE;
    END_IF;

    // PID Loop
    PID_Heater(
        sMode := 3,
        Setpoint := 72.0,
        Input := TempPastOut,
        Output => HeaterPID_Out
    );

    // Safety Timer
    TempOk := (TempPastOut >= 72.0);
    TMR_Hold(IN := TempOk AND ProcessActive, PT := T#15S);

    // FDV Control with Profinet Safety Interlock
    IF ProcessActive AND TMR_Hold.Q AND NOT DeviceFault THEN
        FDV_Forward := TRUE;
        FDV_Divert := FALSE;
    ELSE
        FDV_Forward := FALSE;
        FDV_Divert := TRUE;
    END_IF;

    // Fault Diagnostics
    IF DeviceFault THEN
        ErrorCode := 16#0001; // PN Device Fault
        AlarmActive := TRUE;
    ELSIF ProcessActive AND NOT TempOk THEN
        ErrorCode := 16#0002; // Low Temp Divert
        AlarmActive := TRUE;
    ELSE
        ErrorCode := 16#0000;
        AlarmActive := FALSE;
    END_IF;
END_FUNCTION_BLOCK
