PROGRAM SugarCentrifuge
VAR
    Start_PB : BOOL;
    Stop_PB : BOOL;
    State : DINT := 0; 

    VFD_Speed_Ref : REAL;
    VFD_Torque_Act : REAL;
    Max_Torque : REAL := 150.0;

    Wash_Valve : BOOL;
    Wash_Timer : TON;
    Wash_Profile_Time : TIME := T#30s;

    Plow_Advance : BOOL;
    Plow_Retract : BOOL;
    Plow_Pos_Limit : BOOL;

    Centrifuge_Speed : REAL;
END_VAR

CASE State OF
    0: // Stopped
        VFD_Speed_Ref := 0.0;
        Wash_Valve := FALSE;
        Plow_Advance := FALSE;
        Plow_Retract := TRUE;
        IF Start_PB THEN State := 1; END_IF;

    1: // Acceleration
        VFD_Speed_Ref := 1200.0;
        IF Centrifuge_Speed >= 1150.0 THEN State := 2; END_IF;

    2: // Spin & Monitor Torque
        IF VFD_Torque_Act > Max_Torque THEN
            State := 3;
            Wash_Timer(IN:=FALSE);
        END_IF;

    3: // Wash Profiling
        VFD_Speed_Ref := 1000.0;
        Wash_Valve := TRUE;
        Wash_Timer(IN:=TRUE, PT:=Wash_Profile_Time);
        IF Wash_Timer.Q THEN
            Wash_Valve := FALSE;
            State := 4;
        END_IF;

    4: // Deceleration for Plow
        VFD_Speed_Ref := 50.0;
        IF Centrifuge_Speed <= 55.0 THEN State := 5; END_IF;

    5: // Plow Extraction
        Plow_Retract := FALSE;
        Plow_Advance := TRUE;
        IF Plow_Pos_Limit THEN
            Plow_Advance := FALSE;
            Plow_Retract := TRUE;
            State := 0;
        END_IF;
END_CASE;

IF Stop_PB THEN State := 0; END_IF;
END_PROGRAM

