PROGRAM SugarCentrifuge_M2
VAR
    Start_PB : BOOL;
    Stop_PB : BOOL;
    State : DINT := 0; 

    // Core Process
    VFD_Speed_Ref : REAL;
    VFD_Torque_Act : REAL;
    Wash_Valve : BOOL;
    Plow_Advance : BOOL;
    Plow_Retract : BOOL;
    Centrifuge_Speed : REAL;

    // Mutation 1: Vibration
    Vibration_Sensor_X : REAL;
    Vibration_Sensor_Y : REAL;
    Vibration_Trip : BOOL;

    // Mutation 2: Ethernet/IP & Diagnostics
    EIP_Comm_Status : DINT; // 0=OK, <0 = Error
    EIP_Node_Alive : BOOL;
    Fault_Code : DINT := 0;
    Diagnostic_Array : ARRAY[0..9] OF BOOL;
    Heartbeat_Timer : TON;
END_VAR

// Ethernet/IP Diagnostics
Heartbeat_Timer(IN:=NOT Heartbeat_Timer.Q, PT:=T#1s);
IF Heartbeat_Timer.Q THEN
    IF EIP_Comm_Status < 0 THEN
        Diagnostic_Array[0] := TRUE; // Comm Loss
        Fault_Code := 1001;
        State := 99;
    ELSE
        Diagnostic_Array[0] := FALSE;
    END_IF;
END_IF;

// Equipment Diagnostics
IF VFD_Torque_Act > 200.0 THEN
    Diagnostic_Array[1] := TRUE; // Torque Overload Fault
    Fault_Code := 2001;
    State := 99;
END_IF;

IF (Vibration_Sensor_X > 8.0) OR (Vibration_Sensor_Y > 8.0) THEN
    Diagnostic_Array[2] := TRUE; // Vibration Fault
    Fault_Code := 3001;
    Vibration_Trip := TRUE;
    State := 99;
END_IF;

CASE State OF
    0: // Stopped
        VFD_Speed_Ref := 0.0;
        Wash_Valve := FALSE;
        Plow_Retract := TRUE;
        Plow_Advance := FALSE;
        IF Start_PB AND Fault_Code = 0 THEN State := 1; END_IF;

    1: // Acceleration
        VFD_Speed_Ref := 1200.0;
        IF Centrifuge_Speed >= 1150.0 THEN State := 2; END_IF;

    2: // Spin
        IF VFD_Torque_Act > 150.0 THEN State := 3; END_IF;

    3: // Wash
        VFD_Speed_Ref := 1000.0;
        Wash_Valve := TRUE;
        State := 4; // Simplified transition

    4: // Decel
        Wash_Valve := FALSE;
        VFD_Speed_Ref := 50.0;
        IF Centrifuge_Speed <= 55.0 THEN State := 5; END_IF;

    5: // Plow
        Plow_Retract := FALSE;
        Plow_Advance := TRUE;
        State := 0;

    99: // Fault
        VFD_Speed_Ref := 0.0;
        Wash_Valve := FALSE;
        Plow_Advance := FALSE;
        Plow_Retract := TRUE;
END_CASE;
END_PROGRAM

PROGRAM SugarCentrifuge_M3
VAR
    Start_PB : BOOL;
    State : DINT := 0; 

    // Core
    VFD_Speed_Ref : REAL;
    VFD_Torque_Act : REAL;

    // Mutation 3: Redundant Sensors & Failover
    Speed_Sensor_A : REAL;
    Speed_Sensor_B : REAL;
    Active_Speed : REAL;
    Sensor_Dev_Limit : REAL := 10.0;
    Sensor_Fault : BOOL;

    // Mutation 3: Cyber Security & SCADA
    SCADA_Auth_Token : DINT;
    Expected_Token : DINT := 16#A5A5;
    Cyber_Alert : BOOL;
    Remote_Start_Cmd : BOOL;

    // Previous Mutations...
    EIP_Comm_Status : DINT;
    Fault_Code : DINT;
END_VAR

// IEC 62443 Security Check
IF SCADA_Auth_Token <> Expected_Token AND Remote_Start_Cmd THEN
    Cyber_Alert := TRUE;
    Fault_Code := 9001; // Security Breach
    State := 99;
ELSE
    Cyber_Alert := FALSE;
END_IF;

// Failover Logic for Speed Sensors
IF ABS(Speed_Sensor_A - Speed_Sensor_B) > Sensor_Dev_Limit THEN
    Sensor_Fault := TRUE;
    Fault_Code := 4001; // Sensor Mismatch
    State := 99;
ELSE
    Active_Speed := (Speed_Sensor_A + Speed_Sensor_B) / 2.0;
END_IF;

CASE State OF
    0:
        VFD_Speed_Ref := 0.0;
        IF (Start_PB OR Remote_Start_Cmd) AND NOT Cyber_Alert AND NOT Sensor_Fault THEN
            State := 1;
        END_IF;

    1:
        VFD_Speed_Ref := 1200.0;
        IF Active_Speed >= 1150.0 THEN State := 2; END_IF;

    2:
        IF VFD_Torque_Act > 150.0 THEN State := 3; END_IF;

    3:
        VFD_Speed_Ref := 50.0;
        IF Active_Speed <= 55.0 THEN State := 0; END_IF;

    99:
        VFD_Speed_Ref := 0.0;
END_CASE;
END_PROGRAM

PROGRAM SugarCentrifuge_M4
VAR
    Start_PB : BOOL;
    State : DINT := -1; // -1 = PowerUp/SelfTest

    // Core & Prev Mutations
    VFD_Speed_Ref : REAL;
    VFD_Torque_Act : REAL;
    Active_Speed : REAL;
    Speed_Sensor_A : REAL;
    Speed_Sensor_B : REAL;
    SCADA_Auth_Token : DINT;
    Expected_Token : DINT := 16#A5A5;
    Remote_Start_Cmd : BOOL;
    Fault_Code : DINT;

    // Mutation 4: Adversarial Robustness & HIL
    HIL_Sync_Mode : BOOL;
    Digital_Twin_Speed_Est : REAL;
    Twin_Deviation : REAL;

    // Mutation 4: Sensor Drift
    Drift_Accumulator : REAL := 0.0;
    Max_Drift_Allowed : REAL := 2.5;

    // Self-Test
    Self_Test_Step : INT := 0;
    Self_Test_Complete : BOOL := FALSE;
END_VAR

// Cyber Check
IF SCADA_Auth_Token <> Expected_Token AND Remote_Start_Cmd THEN
    Fault_Code := 9001;
    State := 99;
END_IF;

// Sensor Drift Detection (Long term divergence)
Drift_Accumulator := Drift_Accumulator + (Speed_Sensor_A - Speed_Sensor_B) * 0.001; // Simplified I-term
IF ABS(Drift_Accumulator) > Max_Drift_Allowed THEN
    Fault_Code := 4002; // Sensor Drift Fault
    State := 99;
END_IF;

// HIL Digital Twin Sync
IF HIL_Sync_Mode THEN
    Twin_Deviation := ABS(Active_Speed - Digital_Twin_Speed_Est);
    IF Twin_Deviation > 50.0 THEN
        Fault_Code := 5001; // Physical/Model mismatch
        State := 99;
    END_IF;
END_IF;

CASE State OF
    -1: // Self-Test Routine
        CASE Self_Test_Step OF
            0: 
                VFD_Speed_Ref := 10.0; 
                Self_Test_Step := 1;
            1:
                IF Speed_Sensor_A > 5.0 AND Speed_Sensor_B > 5.0 THEN
                    Self_Test_Complete := TRUE;
                    VFD_Speed_Ref := 0.0;
                    State := 0;
                END_IF;
        END_CASE;

    0: // Stopped
        VFD_Speed_Ref := 0.0;
        IF (Start_PB OR Remote_Start_Cmd) AND Self_Test_Complete THEN
            State := 1;
        END_IF;

    1: // Spin
        VFD_Speed_Ref := 1200.0;
        IF Active_Speed > 1150.0 THEN State := 0; END_IF;

    99: // Fault
        VFD_Speed_Ref := 0.0;
END_CASE;
END_PROGRAM

