   END_IF;

   // Redundant Sensor Failover Logic
   IF NOT #Temp1_Primary_Err THEN
       #Active_Temp_PV := #Temp1_Primary_PV;
       #Sensor_Failover_Active := FALSE;
   ELSIF NOT #Temp1_Secondary_Err THEN
       #Active_Temp_PV := #Temp1_Secondary_PV;
       #Sensor_Failover_Active := TRUE;
   ELSE
       // Both sensors failed, trigger critical shutdown
       #Active_Temp_PV := 9999.0; // Fail-safe value
   END_IF;

   // SCADA Communication Loss Handling (Heartbeat toggle monitor)
   #Heartbeat_Timer(IN := (#SCADA_Heartbeat = #Last_Heartbeat), PT := T#5s);
   IF #Heartbeat_Timer.Q THEN
       #SCADA_Comms_Loss := TRUE;
       // Trigger safe fallback parameters here
   ELSE
       #SCADA_Comms_Loss := FALSE;
   END_IF;
   #Last_Heartbeat := #SCADA_Heartbeat;

END_FUNCTION_BLOCK
