    IRTestDone: BOOL;
    IRTestValue: REAL; 

    // Thermal Imaging
    ThermalTrigger: BOOL;
    ThermalDone: BOOL;
    ThermalPass: BOOL;

    // HV Busbar Welding
    WeldStart: BOOL;
    WeldDone: BOOL;
    MeltPoolOk: BOOL;
    ArgonFlowValve: BOOL;
    ArgonFlowSensor: REAL; // L/min
    ArgonMinFlow: REAL := 12.0;
    WeldPower: REAL;

    // Station Status
    PackAssembled: BOOL;
    PackFailed: BOOL;
END_VAR

CASE Step OF
    0: // Start
        Step := 10;

    10: // Torque
        TorqueToolStart := TRUE;
        IF TorqueToolDone THEN
            TorqueToolStart := FALSE;
            Step := SEL(TorqueToolOk, 999, 20);
        END_IF

    20: // Purge Argon
        ArgonFlowValve := TRUE;
        IF ArgonFlowSensor > ArgonMinFlow THEN
            Step := 25;
        END_IF

    25: // Weld Busbar
        WeldStart := TRUE;
        WeldPower := 2500.0;
        IF WeldDone THEN
            WeldStart := FALSE;
            ArgonFlowValve := FALSE;
            Step := SEL(MeltPoolOk, 999, 30);
        END_IF

    30: // IR Testing
        IRTestStart := TRUE;
        IF IRTestDone THEN
            IRTestStart := FALSE;
            Step := SEL(IRTestValue <= 2.5, 999, 40);
        END_IF

    40: // Thermal Imaging
        ThermalTrigger := TRUE;
        IF ThermalDone THEN
            ThermalTrigger := FALSE;
            Step := SEL(ThermalPass, 999, 100);
        END_IF

    100: // Success
        PackAssembled := TRUE;

    999: // Fail
        PackFailed := TRUE;
END_CASE
