   // Sensor Drift Detection (Moving Average vs Current)
   LoadBuffer[BufferIndex] := ActiveLoad;
   BufferIndex := (BufferIndex + 1) MOD 10;

   SumLoad := 0.0;
   FOR i := 0 TO 9 DO
      SumLoad := SumLoad + LoadBuffer[i];
   END_FOR;
   LoadAvg := SumLoad / 10.0;

   Alarms[4] := (ABS(ActiveLoad - LoadAvg) > 15.0); // Drift detected

   // Pre-operation Self-Test State Machine
   CASE SysState OF
      0: // Init
         SysState := 1;
         SelfTestStep := 0;
      1: // SelfTest
         SelfTestTimer(IN := TRUE, PT := T#2S);
         IF SelfTestTimer.Q THEN
            SelfTestStep := SelfTestStep + 1;
            SelfTestTimer(IN := FALSE, PT := T#2S);
         END_IF;
         IF SelfTestStep >= 3 THEN
            SysState := 2; // Ready
         END_IF;
      2: // Ready
         IF StartCycle AND NOT Alarms[4] THEN
            SysState := 3;
         END_IF;
      3: // Run
         IF NOT StartCycle THEN SysState := 2; END_IF;
   END_CASE;
END_FUNCTION_BLOCK
