FUNCTION_BLOCK "DistrictHeatingSubstation"
VAR_INPUT
    OutdoorTemp : REAL;
    SupplyTemp : REAL;
    SupplyPress : REAL;
    ReturnPress : REAL;
    DiffPressSP : REAL;
END_VAR
VAR_OUTPUT
    ValveCmd : REAL;
    PumpSpeed : REAL;
END_VAR
VAR
    PID_Temp : "PID_Compact";
    PID_Press : "PID_Compact";
    TargetSupplyTemp : REAL;
    DiffPress : REAL;
END_VAR
BEGIN
    // Weather Compensation
    IF OutdoorTemp <= -15.0 THEN
        TargetSupplyTemp := 95.0;
    ELSIF OutdoorTemp >= 20.0 THEN
        TargetSupplyTemp := 20.0;
    ELSE
        TargetSupplyTemp := 95.0 - ((OutdoorTemp + 15.0) * (75.0 / 35.0));
    END_IF;

    // Temperature Control
    PID_Temp(Setpoint := TargetSupplyTemp, ProcessValue := SupplyTemp, Output => ValveCmd);

    // Differential Pressure Control
    DiffPress := SupplyPress - ReturnPress;
    PID_Press(Setpoint := DiffPressSP, ProcessValue := DiffPress, Output => PumpSpeed);
END_FUNCTION_BLOCK
