FUNCTION_BLOCK "DistrictHeatingSubstation_M2"
VAR_INPUT
    OutdoorTemp, SupplyTemp, SupplyPress, ReturnPress, DiffPressSP : REAL;
    TES_TopTemp, TES_BottomTemp, LoadDemand : REAL;
    VFD_StatusWord : WORD;
END_VAR
VAR_OUTPUT
    ValveCmd_HX1, ValveCmd_HX2, PumpSpeed : REAL;
    TES_ChargeCmd : BOOL;
    VFD_ControlWord : WORD;
    Alarms : ARRAY[0..7] OF BOOL;
END_VAR
VAR
    PID_Temp_HX1, PID_Temp_HX2, PID_Press : "PID_Compact";
    TargetSupplyTemp, DiffPress : REAL;
    VFD_Fault : BOOL;
END_VAR
BEGIN
    // Weather Comp & TES SOC
    TargetSupplyTemp := LIMIT(MN:=20.0, IN:=(95.0 - ((OutdoorTemp + 15.0) * (75.0 / 35.0))), MX:=95.0);
    TES_ChargeCmd := ((TES_TopTemp + TES_BottomTemp)/2.0 < 50.0) AND (LoadDemand < 60.0);

    // Cascade HX
    PID_Temp_HX1(Setpoint:=TargetSupplyTemp, ProcessValue:=SupplyTemp, Output=>ValveCmd_HX1);
    IF LoadDemand >= 50.0 THEN
        PID_Temp_HX2(Setpoint:=TargetSupplyTemp, ProcessValue:=SupplyTemp, Output=>ValveCmd_HX2);
    ELSE
        ValveCmd_HX2 := 0.0;
    END_IF;

    // Diff Pressure & Profinet VFD
    DiffPress := SupplyPress - ReturnPress;
    PID_Press(Setpoint:=DiffPressSP, ProcessValue:=DiffPress, Output=>PumpSpeed);

    // VFD Diagnostics & Control via Profinet
    VFD_Fault := (VFD_StatusWord AND 16#0008) <> 0;
    Alarms[0] := VFD_Fault;
    IF NOT VFD_Fault THEN
        VFD_ControlWord := 16#047F; // Ready to operate
    ELSE
        VFD_ControlWord := 16#047E; // Fault reset / OFF
        PumpSpeed := 0.0;
    END_IF;
    Alarms[1] := (SupplyPress > 10.0); // High pressure alarm
END_FUNCTION_BLOCK
