FUNCTION_BLOCK "BioreactorControl"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT
      startProcess : Bool;
      stopProcess : Bool;
      doLevel_PV : Real; // Dissolved Oxygen Process Value (%)
      doLevel_SP : Real; // Dissolved Oxygen Setpoint (%)
      pH_PV : Real;      // pH Process Value
      pH_SP : Real;      // pH Setpoint
      foamDetected : Bool; // Antifoam sensor
   END_VAR
   VAR_OUTPUT
      agitatorSpeed_CV : Real; // Agitator Speed Control Value (%)
      acidPumpCommand : Bool;
      basePumpCommand : Bool;
      antifoamPumpCommand : Bool;
   END_VAR
   VAR_IN_OUT
      doPID : "PID_Compact";
      pH_Deadband : Real := 0.2;
   END_VAR
   VAR
      processActive : Bool;
      antifoamTimer : TON;
   END_VAR

BEGIN
   // Start/Stop Logic
   IF #startProcess AND NOT #stopProcess THEN
       #processActive := TRUE;
   ELSIF #stopProcess THEN
       #processActive := FALSE;
   END_IF;

   IF NOT #processActive THEN
       #agitatorSpeed_CV := 0.0;
       #acidPumpCommand := FALSE;
       #basePumpCommand := FALSE;
       #antifoamPumpCommand := FALSE;
       RETURN;
   END_IF;

   // 1. Cascaded DO/Agitator PID Control
   #doPID(Setpoint:=#doLevel_SP,
          Input:=#doLevel_PV);
   #agitatorSpeed_CV := #doPID.Output;

   // 2. pH Deadband Dosing
   IF #pH_PV > (#pH_SP + #pH_Deadband) THEN
       #acidPumpCommand := TRUE;
       #basePumpCommand := FALSE;
   ELSIF #pH_PV < (#pH_SP - #pH_Deadband) THEN
       #acidPumpCommand := FALSE;
       #basePumpCommand := TRUE;
   ELSE
       #acidPumpCommand := FALSE;
       #basePumpCommand := FALSE;
   END_IF;

   // 3. Automatic Antifoam Injection
   #antifoamTimer(IN := #foamDetected, PT := T#5s);
   IF #antifoamTimer.Q THEN
       #antifoamPumpCommand := TRUE;
   ELSE
       #antifoamPumpCommand := FALSE;
   END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "BioreactorControl_Mut1"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT
      startProcess : Bool;
      stopProcess : Bool;
      doLevel_PV : Real;
      doLevel_SP : Real;
      pH_PV : Real;
      pH_SP : Real;
      foamDetected : Bool;
      temp_PV : Real; // Temperature Process Value
      temp_SP : Real; // Temperature Setpoint
   END_VAR
   VAR_OUTPUT
      agitatorSpeed_CV : Real;
      acidPumpCommand : Bool;
      basePumpCommand : Bool;
      antifoamPumpCommand : Bool;
      coolingValve_CV : Real; // 0-100%
      heatingValve_CV : Real; // 0-100%
   END_VAR
   VAR_IN_OUT
      doPID : "PID_Compact";
      tempPID : "PID_Compact";
      pH_Deadband : Real := 0.2;
   END_VAR
   VAR
      processActive : Bool;
      antifoamTimer : TON;
      tempPID_Out : Real;
   END_VAR

BEGIN
   IF #startProcess THEN #processActive := TRUE; END_IF;
   IF #stopProcess THEN #processActive := FALSE; END_IF;

   IF NOT #processActive THEN
       #agitatorSpeed_CV := 0.0;
       #acidPumpCommand := FALSE;
       #basePumpCommand := FALSE;
       #antifoamPumpCommand := FALSE;
       #coolingValve_CV := 0.0;
       #heatingValve_CV := 0.0;
       RETURN;
   END_IF;

   // Cascaded DO/Agitator
   #doPID(Setpoint:=#doLevel_SP, Input:=#doLevel_PV);
   #agitatorSpeed_CV := #doPID.Output;

   // pH Deadband
   #acidPumpCommand := #pH_PV > (#pH_SP + #pH_Deadband);
   #basePumpCommand := #pH_PV < (#pH_SP - #pH_Deadband);

   // Antifoam
   #antifoamTimer(IN := #foamDetected, PT := T#5s);
   #antifoamPumpCommand := #antifoamTimer.Q;

   // Temperature Split Range Control (-100 to 100 PID output mapped to two valves)
   #tempPID(Setpoint:=#temp_SP, Input:=#temp_PV);
   #tempPID_Out := #tempPID.Output;

   IF #tempPID_Out > 0.0 THEN // Heating required
       #heatingValve_CV := #tempPID_Out;
       #coolingValve_CV := 0.0;
   ELSIF #tempPID_Out < 0.0 THEN // Cooling required
       #heatingValve_CV := 0.0;
       #coolingValve_CV := ABS(#tempPID_Out);
   ELSE
       #heatingValve_CV := 0.0;
       #coolingValve_CV := 0.0;
   END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "BioreactorControl_Mut2"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT
      startProcess : Bool; stopProcess : Bool;
      doLevel_PV : Real; doLevel_SP : Real;
      pH_PV : Real; pH_SP : Real;
      foamDetected : Bool;
      temp_PV : Real; temp_SP : Real;
      profinetNodeStatus : Word; // 1 = OK, 0 = Fault for each bit
      agitatorFault : Bool;
      pumpFaults : Byte; // Bit 0: Acid, Bit 1: Base, Bit 2: Antifoam
   END_VAR
   VAR_OUTPUT
      agitatorSpeed_CV : Real;
      acidPumpCommand : Bool; basePumpCommand : Bool; antifoamPumpCommand : Bool;
      coolingValve_CV : Real; heatingValve_CV : Real;
      systemFault : Bool;
      faultCode : Word;
