   VAR_IN_OUT
      doPID : "PID_Compact"; tempPID : "PID_Compact";
   END_VAR
   VAR
      processActive : Bool; antifoamTimer : TON;
   END_VAR

BEGIN
   // Diagnostics & Profinet Health
   #systemFault := FALSE;
   #faultCode := 16#0000;

   IF #profinetNodeStatus <> 16#FFFF THEN
       #systemFault := TRUE;
       #faultCode := 16#1001; // Profinet IO Loss
   ELSIF #agitatorFault THEN
       #systemFault := TRUE;
       #faultCode := 16#2001; // Agitator Drive Fault
   ELSIF #pumpFaults > 0 THEN
       #systemFault := TRUE;
       #faultCode := 16#3001; // Dosing Pump Fault
   END_IF;

   IF #startProcess AND NOT #systemFault THEN #processActive := TRUE; END_IF;
   IF #stopProcess OR #systemFault THEN #processActive := FALSE; END_IF;

   IF NOT #processActive THEN
       #agitatorSpeed_CV := 0.0;
       #acidPumpCommand := FALSE; #basePumpCommand := FALSE; #antifoamPumpCommand := FALSE;
       #coolingValve_CV := 0.0; #heatingValve_CV := 0.0;
       RETURN;
   END_IF;

   #doPID(Setpoint:=#doLevel_SP, Input:=#doLevel_PV);
   #agitatorSpeed_CV := #doPID.Output;

   #acidPumpCommand := (#pH_PV > (#pH_SP + 0.2)) AND NOT #systemFault;
   #basePumpCommand := (#pH_PV < (#pH_SP - 0.2)) AND NOT #systemFault;

   #antifoamTimer(IN := #foamDetected, PT := T#5s);
   #antifoamPumpCommand := #antifoamTimer.Q AND NOT #systemFault;

   #tempPID(Setpoint:=#temp_SP, Input:=#temp_PV);
   IF #tempPID.Output > 0.0 THEN
       #heatingValve_CV := #tempPID.Output; #coolingValve_CV := 0.0;
   ELSIF #tempPID.Output < 0.0 THEN
       #heatingValve_CV := 0.0; #coolingValve_CV := ABS(#tempPID.Output);
   ELSE
       #heatingValve_CV := 0.0; #coolingValve_CV := 0.0;
   END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "BioreactorControl_Mut3"
