```iecst
PROGRAM PRG_Lyophilizer
VAR
    eState : (IDLE, FREEZING, PRIMARY_DRYING, SECONDARY_DRYING, DEFROST, ERROR);
    fPiraniVacuum : LREAL;
    fShelfTemp : LREAL;
    fCondenserTemp : LREAL;
    fVacuumValve : LREAL;
    fShelfHeating : LREAL;
    fCondenserCooling : LREAL;
    bDefrostHeater : BOOL;
    bVacuumPump : BOOL;
    bStartProcess : BOOL;
    fbVacuumPID : FB_BasicPID;
    fbTimerProcess : TON;
    fbTimerDefrost : TON;
    tPrimaryDryingTime : TIME := T#24H;
    tSecondaryDryingTime : TIME := T#6H;
    bInit : BOOL := TRUE;
END_VAR

IF bInit THEN
    fbVacuumPID.fKp := 2.0; fbVacuumPID.fKi := 0.5; fbVacuumPID.fKd := 0.1;
    bInit := FALSE;
END_IF

CASE eState OF
    IDLE:
        fShelfHeating := 0.0;
        fCondenserCooling := 0.0;
        bVacuumPump := FALSE;
        bDefrostHeater := FALSE;
        fbVacuumPID.bEnable := FALSE;
        IF bStartProcess THEN
            eState := FREEZING;
        END_IF

    FREEZING:
        fCondenserCooling := 100.0;
        fShelfHeating := -40.0;
        IF fShelfTemp <= -35.0 AND fCondenserTemp <= -50.0 THEN
            bVacuumPump := TRUE;
            fbTimerProcess(IN:=FALSE);
            eState := PRIMARY_DRYING;
        END_IF

    PRIMARY_DRYING:
        fbTimerProcess(IN:=TRUE, PT:=tPrimaryDryingTime);
        fbVacuumPID(fSetpoint:=0.1, fActual:=fPiraniVacuum, bEnable:=TRUE, fOut=>fVacuumValve);
        fShelfHeating := -20.0;
        IF fbTimerProcess.Q THEN
            fbTimerProcess(IN:=FALSE);
            eState := SECONDARY_DRYING;
        END_IF

    SECONDARY_DRYING:
        fbTimerProcess(IN:=TRUE, PT:=tSecondaryDryingTime);
        fbVacuumPID(fSetpoint:=0.05, fActual:=fPiraniVacuum, bEnable:=TRUE, fOut=>fVacuumValve);
        fShelfHeating := 20.0;
        IF fbTimerProcess.Q THEN
            bVacuumPump := FALSE;
            fbVacuumPID.bEnable := FALSE;
            fbTimerDefrost(IN:=FALSE);
            eState := DEFROST;
        END_IF

    DEFROST:
        fCondenserCooling := 0.0;
        bDefrostHeater := TRUE;
        fbTimerDefrost(IN:=TRUE, PT:=T#2H);
        IF fbTimerDefrost.Q THEN
            bDefrostHeater := FALSE;
            bStartProcess := FALSE;
            eState := IDLE;
        END_IF

    ERROR:
        bVacuumPump := FALSE;
        bDefrostHeater := FALSE;
        fShelfHeating := 0.0;
        fCondenserCooling := 0.0;
        fbVacuumPID.bEnable := FALSE;
END_CASE
