Here is the comprehensive code featuring sensor drift detection, HIL digital twin mode, and an automated self-test routine:

```iecst
PROGRAM PRG_Lyophilizer
VAR
    eState : (IDLE, SELF_TEST, COMPRESSOR1_START, COMPRESSOR2_START, FREEZING, PRIMARY_DRYING, SECONDARY_DRYING, DEFROST, ERROR);
    eTestState : (TEST_PUMP, TEST_HEATERS, TEST_VALVES, TEST_COMPLETE);

    // HIL Mode & I/O
    bHIL_Mode : BOOL;
    fShelfRTD1_Physical AT %I* : LREAL;
    fShelfRTD2_Physical AT %I* : LREAL;
    fShelfRTD1_HIL, fShelfRTD2_HIL : LREAL;
    fShelfRTD1, fShelfRTD2, fShelfTemp : LREAL;
    bSensorDriftAlarm : BOOL;
    fMaxDriftAllowed : LREAL := 2.0; // deg C

    // Other variables
    fActiveVacuum, fVacuumValve, fShelfHeating : LREAL;
    bComp1, bComp2, bDefrostHeater, bVacuumPump1, bStartProcess, bSelfTestPass : BOOL;
    fbVacuumPID : FB_BasicPID;
    fbTimerTest : TON;
END_VAR

// HIL Synchronization
IF bHIL_Mode THEN
    fShelfRTD1 := fShelfRTD1_HIL;
    fShelfRTD2 := fShelfRTD2_HIL;
ELSE
    fShelfRTD1 := fShelfRTD1_Physical;
    fShelfRTD2 := fShelfRTD2_Physical;
END_IF

// Sensor Drift Detection (Adversarial Check)
IF ABS(fShelfRTD1 - fShelfRTD2) > fMaxDriftAllowed THEN
    bSensorDriftAlarm := TRUE;
    eState := ERROR;
ELSE
    bSensorDriftAlarm := FALSE;
    fShelfTemp := (fShelfRTD1 + fShelfRTD2) / 2.0;
END_IF

CASE eState OF
    IDLE:
        IF bStartProcess THEN 
            eState := SELF_TEST;
            eTestState := TEST_PUMP;
        END_IF

    SELF_TEST:
        // Automated pre-batch diagnostic routine
        CASE eTestState OF
            TEST_PUMP:
                bVacuumPump1 := TRUE;
                fbTimerTest(IN:=TRUE, PT:=T#5S);
                IF fbTimerTest.Q THEN 
                    bVacuumPump1 := FALSE; fbTimerTest(IN:=FALSE); eTestState := TEST_HEATERS;
                END_IF
            TEST_HEATERS:
                fShelfHeating := 10.0; // 10%
                fbTimerTest(IN:=TRUE, PT:=T#5S);
                IF fbTimerTest.Q THEN 
                    fShelfHeating := 0.0; fbTimerTest(IN:=FALSE); eTestState := TEST_COMPLETE;
                END_IF
            TEST_COMPLETE:
                bSelfTestPass := TRUE;
                eState := COMPRESSOR1_START;
        END_CASE

    COMPRESSOR1_START:
        bComp1 := TRUE; eState := COMPRESSOR2_START;
    COMPRESSOR2_START:
        bComp2 := TRUE; eState := FREEZING;
    FREEZING:
        fShelfHeating := -40.0;
        IF fShelfTemp <= -35.0 THEN eState := PRIMARY_DRYING; END_IF
    PRIMARY_DRYING:
        bVacuumPump1 := TRUE;
        fbVacuumPID(fSetpoint:=0.1, fActual:=fActiveVacuum, bEnable:=TRUE, fOut=>fVacuumValve);
        // Additional drying logic...
    ERROR:
        bComp1 := FALSE; bComp2 := FALSE; bVacuumPump1 := FALSE; fShelfHeating := 0.0;
END_CASE
