    fHIL_MainForce_Sim, fHIL_Weight_Sim : REAL;

    // Drift Detection
    fMainForce_Raw : REAL;
    aForceHistory : ARRAY[1..100] OF REAL;
    nHistIdx : INT := 1;
    fMovingAverage, fDriftThreshold : REAL := 2.5;
    bDriftDetected : BOOL;
    bDegradedMode : BOOL;

    // Control
    fbWeightPID : FB_BasicPID;
    fTargetSpeed, fActualWeight : REAL;
END_VAR

// Redundancy
IF NOT bIsPrimaryPLC THEN RETURN; END_IF

// HIL Muxing
IF bHIL_Mode THEN
    fMainForce_Raw := fHIL_MainForce_Sim;
    fActualWeight := fHIL_Weight_Sim;
END_IF

// Sensor Drift Detection
aForceHistory[nHistIdx] := fMainForce_Raw;
nHistIdx := (nHistIdx MOD 100) + 1;
fMovingAverage := F_CalculateAverage(aForceHistory);
IF ABS(fMainForce_Raw - fMovingAverage) > fDriftThreshold THEN
    bDriftDetected := TRUE;
END_IF

CASE eState OF
    E_MachineState.SELF_TEST:
        IF F_RunSelfDiagnostics() THEN eState := E_MachineState.READY; END_IF
    E_MachineState.READY:
        IF bStart AND nActiveUserRole >= 2 THEN eState := E_MachineState.RUN; END_IF
    E_MachineState.RUN:
        // Graceful Degradation
        IF bDriftDetected THEN
            bDegradedMode := TRUE;
            fTargetSpeed := fTargetSpeed * 0.5; // Slow down
        END_IF

        IF fMainForce_Raw > 80.0 THEN eState := E_MachineState.FAULT; END_IF
        fbWeightPID(fActualValue := fActualWeight, fSetpointValue := 500.0, bEnable := TRUE);
    E_MachineState.FAULT:
        fbWeightPID(bEnable := FALSE);
        fTargetSpeed := 0.0;
END_CASE
END_PROGRAM

