```iecst
TYPE ST_Parcel :
STRUCT
	bActive       : BOOL;
	uiDestination : UINT;
	uiLength      : UINT;
	udiInductTick : UDINT;
	lrWeightKg    : LREAL;
END_STRUCT
END_TYPE

VAR_GLOBAL
	udiEncoderTicks   AT %I* : UDINT;
	arrShiftRegister         : ARRAY[0..999] OF ST_Parcel;
END_VAR

PROGRAM MAIN
VAR
	bInductEye        AT %I* : BOOL;
	lrLoadCellInput   AT %I* : LREAL; // Weight during induction
	uiTargetDest      AT %I* : UINT;

	// Diverters
	arrDivertPositions       : ARRAY[1..10] OF UDINT := [1000, 2500, 4000, 5500, 7000, 8500, 10000, 11500, 13000, 14500];
	arrDivertSpeeds   AT %Q* : ARRAY[1..10] OF INT; // Speed reference for cross-belts

	bInductEye_RT : R_TRIG;
	bInductEye_FT : F_TRIG;
	udiParcelStartTick : UDINT;
	udiCurrentTick : UDINT;
	i : INT;
END_VAR

udiCurrentTick := udiEncoderTicks;

// Induction
bInductEye_RT(CLK := bInductEye);
bInductEye_FT(CLK := bInductEye);

IF bInductEye_RT.Q THEN
	udiParcelStartTick := udiCurrentTick;
END_IF

IF bInductEye_FT.Q THEN
	FOR i := 0 TO 999 DO
		IF NOT arrShiftRegister[i].bActive THEN
			arrShiftRegister[i].bActive := TRUE;
			arrShiftRegister[i].uiDestination := uiTargetDest;
			arrShiftRegister[i].udiInductTick := udiParcelStartTick;
			arrShiftRegister[i].lrWeightKg := lrLoadCellInput;
			EXIT;
		END_IF
	END_FOR
END_IF

// Tracking and Dynamic Divert
FOR i := 0 TO 999 DO
	IF arrShiftRegister[i].bActive THEN
		VAR
			udiDistance : UDINT;
		END_VAR
		udiDistance := udiCurrentTick - arrShiftRegister[i].udiInductTick;

		IF arrShiftRegister[i].uiDestination >= 1 AND arrShiftRegister[i].uiDestination <= 10 THEN
			// Anticipate divert by 50 ticks to ramp up speed
			IF udiDistance >= (arrDivertPositions[arrShiftRegister[i].uiDestination] - 50) AND udiDistance < arrDivertPositions[arrShiftRegister[i].uiDestination] THEN
				// Calculate required speed based on weight (heavier = slower divert to prevent tumbling)
				IF arrShiftRegister[i].lrWeightKg > 20.0 THEN
					arrDivertSpeeds[arrShiftRegister[i].uiDestination] := 1500; // Slower profile
				ELSIF arrShiftRegister[i].lrWeightKg > 5.0 THEN
					arrDivertSpeeds[arrShiftRegister[i].uiDestination] := 2500; // Medium profile
				ELSE
					arrDivertSpeeds[arrShiftRegister[i].uiDestination] := 4000; // Fast profile
				END_IF
			ELSIF udiDistance >= arrDivertPositions[arrShiftRegister[i].uiDestination] THEN
				arrDivertSpeeds[arrShiftRegister[i].uiDestination] := 0; // Stop divert
				arrShiftRegister[i].bActive := FALSE;
			END_IF
		END_IF
	END_IF
END_FOR
