FUNCTION_BLOCK "Escalator_Controller_M4"
VERSION : 0.1
   VAR_INPUT 
      Start_Up : Bool;
      Stop : Bool;
      E_Stop : Bool;
      Step_Sensor_1 : Bool;
      Motor_Speed_1 : Real;
      Motor_Speed_2 : Real;
      Passenger_Radar : Bool;
      Security_Token : DWord;
      Partner_PLC_Alive : Bool;
      Is_Primary : Bool;
      HIL_Sync_Data : Array[0..9] of Real;
   END_VAR

   VAR_OUTPUT 
      Motor_Fwd : Bool;
      Brake_Release : Bool;
      VFD_Speed_Ref : Real;
      System_Fault : Bool;
      Brake_Test_Active : Bool;
      HIL_Response : Array[0..9] of Real;
   END_VAR

   VAR 
      State : Int;
      Step_Timer : TON;
      Speed_Timer : TON;
      Brake_Test_Timer : TON;
      Drift_Fault : Bool;
      Test_Passed : Bool;
   END_VAR

BEGIN
    // Sensor Drift Detection
    IF ABS("Motor_Speed_1" - "Motor_Speed_2") > 5.0 THEN
        "Drift_Fault" := TRUE;
    END_IF;

    // HIL Digital Twin Sync
    "HIL_Response"[0] := "Motor_Speed_1";
    "HIL_Response"[1] := "Motor_Speed_2";

    IF "E_Stop" OR "System_Fault" OR "Drift_Fault" THEN
        "Motor_Fwd" := FALSE; "Brake_Release" := FALSE; "VFD_Speed_Ref" := 0.0; "State" := 0;
        RETURN;
    END_IF;

    "Step_Timer"(IN := "Motor_Fwd" AND NOT "Step_Sensor_1", PT := T#1s);
    IF "Step_Timer".Q THEN "System_Fault" := TRUE; END_IF;

    "Speed_Timer"(IN := "Motor_Fwd" AND ("Motor_Speed_1" < 80.0), PT := T#2s);
    IF "Speed_Timer".Q THEN "System_Fault" := TRUE; END_IF;

    CASE "State" OF
        0: 
            "Motor_Fwd" := FALSE; "Brake_Release" := FALSE; "VFD_Speed_Ref" := 0.0; "Brake_Test_Active" := FALSE;
            IF NOT "Stop" AND "Start_Up" AND NOT "Test_Passed" THEN "State" := 5; 
            ELSIF NOT "Stop" AND "Start_Up" AND "Test_Passed" THEN "State" := 10; END_IF;
        5: // Pre-Startup Self-Test (Brake Torque)
            "Brake_Test_Active" := TRUE;
            "Motor_Fwd" := TRUE;
            "Brake_Release" := FALSE; // Try to move against closed brake
            "VFD_Speed_Ref" := 10.0;
            "Brake_Test_Timer"(IN := TRUE, PT := T#3s);
            IF "Brake_Test_Timer".Q THEN
                IF "Motor_Speed_1" < 1.0 THEN 
                    "Test_Passed" := TRUE; "State" := 0; // Passed
                ELSE
                    "System_Fault" := TRUE; // Brake slipped
                END_IF;
                "Brake_Test_Active" := FALSE;
                "Brake_Test_Timer"(IN := FALSE, PT := T#3s);
            END_IF;
        10: 
            "Brake_Release" := TRUE; "Motor_Fwd" := TRUE; "VFD_Speed_Ref" := 100.0;
            IF "Stop" THEN "State" := 0; END_IF;
    END_CASE;
END_FUNCTION_BLOCK
