FUNCTION_BLOCK "FB_BatchReactor_Adversarial"
VERSION : 0.1
   VAR_INPUT 
      start_batch : Bool;
      reactor_temp_1 : Real; // Redundant sensors for drift
      reactor_temp_2 : Real;
      reactor_press_1 : Real;
      reactor_press_2 : Real;
      catalyst_flow : Real;
      agitator_load : Real;
      setpoint_temp : Real;
      setpoint_dosing : Real;
      pn_io_status : Word;
      user_access_level : Int;
      cpu_primary_active : Bool;
      hil_twin_temp : Real; // HIL twin expected temp
      self_test_init : Bool;
   END_VAR

   VAR_OUTPUT 
      cooling_valve : Real;
      dosing_pump : Bool;
      agitator_speed_ref : Real;
      alarm_high_press : Bool;
      interlock_rupture : Bool;
      fault_io_module : Bool;
      fault_code : Word;
      drift_alarm : Bool;
      self_test_pass : Bool;
      scada_interface : "SCADA_Data";
   END_VAR

   VAR 
      pid_cooling : "PID_Compact";
      total_catalyst : Real;
      batch_active : Bool;
      avg_temp : Real;
      avg_press : Real;
      self_test_active : Bool;
      self_test_timer : Int;
   END_VAR

BEGIN
   // Automated Start-up Self-Test Routine
   IF #self_test_init AND NOT #batch_active THEN
       #self_test_active := TRUE;
       #self_test_timer := 0;
   END_IF;
   IF #self_test_active THEN
       #self_test_timer := #self_test_timer + 1;
       #cooling_valve := 50.0; // Stroke valve
       #agitator_speed_ref := 10.0; // Jog motor
       IF #self_test_timer > 100 THEN
           #self_test_pass := TRUE;
           #self_test_active := FALSE;
           #cooling_valve := 0.0;
           #agitator_speed_ref := 0.0;
       END_IF;
       RETURN;
   END_IF;

   // Redundancy Handling
   IF NOT #cpu_primary_active THEN
       RETURN;
   END_IF;

   // Security
   IF #user_access_level < 2 AND #start_batch THEN
       #scada_interface.Security_Alert := TRUE;
       RETURN;
   END_IF;

   // Sensor Drift Detection & HIL Sync
   IF ABS(#reactor_temp_1 - #reactor_temp_2) > 2.0 OR ABS(#reactor_press_1 - #reactor_press_2) > 0.5 THEN
       #drift_alarm := TRUE;
       #fault_code := 16#DF01;
   ELSE
       #drift_alarm := FALSE;
   END_IF;

   #avg_temp := (#reactor_temp_1 + #reactor_temp_2) / 2.0;
   #avg_press := (#reactor_press_1 + #reactor_press_2) / 2.0;

   // HIL sync deviation check
   IF ABS(#avg_temp - #hil_twin_temp) > 5.0 THEN
       #scada_interface.HIL_Sync_Active := FALSE; // Deviation detected
   ELSE
       #scada_interface.HIL_Sync_Active := TRUE;
   END_IF;

   // Interlocks
   IF #avg_press > 10.0 OR #drift_alarm THEN
       #interlock_rupture := TRUE;
       #alarm_high_press := TRUE;
       #batch_active := FALSE;
   END_IF;

   IF #interlock_rupture THEN
       #cooling_valve := 100.0;
       #dosing_pump := FALSE;
       #agitator_speed_ref := 0.0;
   ELSIF #start_batch AND #self_test_pass THEN
       #batch_active := TRUE;
   END_IF;

   IF #batch_active THEN
       #pid_cooling(Setpoint := #setpoint_temp, Input := #avg_temp, Output => #cooling_valve);
       IF #total_catalyst < #setpoint_dosing THEN
           #dosing_pump := TRUE;
           #total_catalyst := #total_catalyst + (#catalyst_flow * 0.1);
       ELSE
           #dosing_pump := FALSE;
       END_IF;
       IF #agitator_load > 85.0 THEN
           #agitator_speed_ref := 40.0;
       ELSE
           #agitator_speed_ref := 100.0;
       END_IF;
   ELSE
       #cooling_valve := 0.0;
       #dosing_pump := FALSE;
       #agitator_speed_ref := 0.0;
   END_IF;

   // SCADA Update
   #scada_interface.Active := #batch_active;
   #scada_interface.Temp_PV := #avg_temp;
   #scada_interface.Press_PV := #avg_press;
   #scada_interface.Fault_Code := #fault_code;
END_FUNCTION_BLOCK

PROGRAM PRG_DistillationBase
VAR
    fRefluxFlow : REAL; // [L/h]
    fDistillateFlow : REAL; // [L/h]
    fRefluxRatio : REAL;

    fbBottomLevelPID : FB_BasicPID;
    fLevelSetpoint : REAL := 50.0; // [%]
    fLevelActual : REAL; // [%]
    fBottomValveOut : REAL; // [0-100%]

    eReboilerState : (INIT, HEATING, RUNNING, SHUTDOWN) := INIT;
    bStartSeq : BOOL;
    bStopSeq : BOOL;
    bSteamValveOpen : BOOL;
    fSteamPressure : REAL;
END_VAR

// Reflux Ratio Calculation
IF fDistillateFlow > 0.0 THEN
    fRefluxRatio := fRefluxFlow / fDistillateFlow;
ELSE
    fRefluxRatio := 0.0;
END_IF

// Bottoms Level PID
fbBottomLevelPID(
    fSetpoint := fLevelSetpoint,
    fActual := fLevelActual,
    bEnable := TRUE,
    fKp := 1.5,
    fTn := 20.0,
    fTv := 0.0,
    fOutput => fBottomValveOut
);

// Reboiler Valve Sequencing
CASE eReboilerState OF
    INIT:
        bSteamValveOpen := FALSE;
        IF bStartSeq THEN
            eReboilerState := HEATING;
        END_IF

    HEATING:
        bSteamValveOpen := TRUE;
        IF fSteamPressure > 3.0 THEN // Bar
            eReboilerState := RUNNING;
        END_IF
        IF bStopSeq THEN
            eReboilerState := SHUTDOWN;
        END_IF

    RUNNING:
        bSteamValveOpen := TRUE;
        // Normal operation
        IF bStopSeq THEN
            eReboilerState := SHUTDOWN;
        END_IF

    SHUTDOWN:
        bSteamValveOpen := FALSE;
        IF NOT bStartSeq THEN
            eReboilerState := INIT;
        END_IF
END_CASE

PROGRAM PRG_DistillationMutation1
VAR
    fRefluxFlow : REAL;
    fDistillateFlow : REAL;
    fRefluxRatio : REAL;

    fbBottomLevelPID : FB_BasicPID;
    fLevelSetpoint : REAL := 50.0;
    fLevelActual : REAL;
    fBottomValveOut : REAL;

    eReboilerState : (INIT, HEATING, RUNNING, SHUTDOWN) := INIT;
    bStartSeq : BOOL;
    bStopSeq : BOOL;
    bSteamValveOpen : BOOL;
    fSteamPressure : REAL;

    // Mutation 1 Additions: Feed Preheater Cascade
    fbTempPID : FB_BasicPID; // Master
    fbFlowPID : FB_BasicPID; // Slave
    fTempSetpoint : REAL := 85.0; // [C]
    fTempActual : REAL; // [C]
    fFlowActual : REAL; // [L/h]
    fCascadeFlowSP : REAL;
    fPreheaterValveOut : REAL;

    // Override Control
    fbPressOverridePID : FB_BasicPID;
    fColumnPressActual : REAL;
    fColumnPressHighLimit : REAL := 5.0; // Bar
    fPressOverrideOut : REAL;
    fFinalSteamValvePos : REAL;
END_VAR

// Reflux Ratio
IF fDistillateFlow > 0.0 THEN fRefluxRatio := fRefluxFlow / fDistillateFlow; ELSE fRefluxRatio := 0.0; END_IF

// Bottoms Level
fbBottomLevelPID(fSetpoint := fLevelSetpoint, fActual := fLevelActual, bEnable := TRUE, fKp := 1.5, fTn := 20.0, fOutput => fBottomValveOut);

// Preheater Cascade
fbTempPID(fSetpoint := fTempSetpoint, fActual := fTempActual, bEnable := TRUE, fKp := 2.0, fTn := 60.0, fOutput => fCascadeFlowSP);
fbFlowPID(fSetpoint := fCascadeFlowSP, fActual := fFlowActual, bEnable := TRUE, fKp := 0.5, fTn := 5.0, fOutput => fPreheaterValveOut);

// Pressure Override Control (Select Low)
fbPressOverridePID(fSetpoint := fColumnPressHighLimit, fActual := fColumnPressActual, bEnable := TRUE, fKp := -3.0, fTn := 10.0, fOutput => fPressOverrideOut);

IF fPressOverrideOut < fPreheaterValveOut THEN
    fFinalSteamValvePos := fPressOverrideOut;
ELSE
    fFinalSteamValvePos := fPreheaterValveOut;
END_IF

// Reboiler Valve Sequencing
CASE eReboilerState OF
    INIT:
        bSteamValveOpen := FALSE;
        IF bStartSeq THEN eReboilerState := HEATING; END_IF
    HEATING:
        bSteamValveOpen := TRUE;
        IF fSteamPressure > 3.0 THEN eReboilerState := RUNNING; END_IF
        IF bStopSeq THEN eReboilerState := SHUTDOWN; END_IF
    RUNNING:
        bSteamValveOpen := TRUE;
        IF bStopSeq THEN eReboilerState := SHUTDOWN; END_IF
    SHUTDOWN:
        bSteamValveOpen := FALSE;
        IF NOT bStartSeq THEN eReboilerState := INIT; END_IF
END_CASE

