PROGRAM Extruder_Base
VAR
    MeltPressure : REAL;
    ScrewSpeedSP : REAL;
    ScrewTorque : REAL;
    TempZone_PV : ARRAY[1..5] OF REAL;
    TempZone_SP : ARRAY[1..5] OF REAL := [180.0, 190.0, 200.0, 210.0, 210.0];
    ExtruderRun : BOOL;
