    Alarm_HighPressure : BOOL;
    Alarm_HighTorque : BOOL;
    MaxPressure : REAL := 4500.0;
    MaxTorque : REAL := 90.0;
    i : DINT;
END_VAR

// Safety limits and drive control
Alarm_HighPressure := MeltPressure >= MaxPressure;
Alarm_HighTorque := ScrewTorque >= MaxTorque;

IF Alarm_HighPressure OR Alarm_HighTorque THEN
    DriveEnable := 0;
    ScrewSpeedCV := 0.0;
ELSIF ExtruderRun THEN
    DriveEnable := 1;
    ScrewSpeedCV := ScrewSpeedSP;
ELSE
    DriveEnable := 0;
    ScrewSpeedCV := 0.0;
END_IF;

// Multi-zone PID heating arrays
FOR i := 1 TO 5 DO
    // Simplified PID logic representing PIDE execution
    IF TempZone_PV[i] < TempZone_SP[i] THEN
        HeaterOutput[i] := 100.0;
    ELSE
        HeaterOutput[i] := 0.0;
    END_IF;
END_FOR;
END_PROGRAM
