// Calculate Differential Pressure
ScreenDP := MeltPressure_PreScreen - MeltPressure_PostScreen;

// Hydraulic Accumulator Management
IF HydraulicAccumulatorPressure < HydraulicMinPressure THEN
    HydraulicPumpCmd := 1;
ELSIF HydraulicAccumulatorPressure > (HydraulicMinPressure + 500.0) THEN
    HydraulicPumpCmd := 0;
END_IF;

// Screen Changer Trigger Logic
IF ScreenDP >= ScreenDP_Trigger AND NOT ScreenChangeInProgress AND HydraulicAccumulatorPressure >= HydraulicMinPressure THEN
    ScreenChangeInProgress := 1;
    ScreenAdvanceCmd := 1;
END_IF;

// Screen Change Timing
ScreenChangeTimer(IN := ScreenAdvanceCmd, PT := T#2S);
IF ScreenChangeTimer.Q THEN
    ScreenAdvanceCmd := 0;
    ScreenChangeInProgress := 0;
END_IF;
END_PROGRAM
