```scl
FUNCTION_BLOCK "FB_CentrifugalSeparator_Depth"
TITLE = 'Centrifugal Separator with Lube & Cooling'

VAR_INPUT
    bStart : BOOL;
    bStop : BOOL;
    bReset : BOOL;
    rSpeedSetpoint : REAL;
    rActualSpeed : REAL;
    rVibration : REAL;
    rVibrationLimit : REAL := 5.0;
    tDischargeInterval : TIME := T#30M;
    tDischargeDuration : TIME := T#5S;
    rBearingTemp : REAL;
    rBearingTempLimit : REAL := 80.0;
    rLubePressure : REAL;
    rMinLubePressure : REAL := 1.5;
END_VAR

VAR_OUTPUT
    bVFD_Run : BOOL;
    rVFD_SpeedRef : REAL;
    bDischargeValve : BOOL;
    bLubePumpRun : BOOL;
    rCoolingValveCmd : REAL;
    bFault : BOOL;
    iState : INT;
END_VAR

VAR
    tonDischargeInt : TON;
    tonDischargeDur : TON;
    tonLubeDelay : TON;
    PID_Cooling : "PID_Compact";
    bVibrationFault : BOOL;
    bBearingTempFault : BOOL;
    bLubePressureFault : BOOL;
END_VAR

BEGIN
    IF rVibration > rVibrationLimit THEN bVibrationFault := TRUE; END_IF;
    IF rBearingTemp > rBearingTempLimit THEN bBearingTempFault := TRUE; END_IF;

    tonLubeDelay(IN := bLubePumpRun, PT := T#5S);
    IF tonLubeDelay.Q AND (rLubePressure < rMinLubePressure) THEN
        bLubePressureFault := TRUE;
    END_IF;

    IF bVibrationFault OR bBearingTempFault OR bLubePressureFault THEN
        bFault := TRUE;
        iState := 3;
    END_IF;

    IF bReset THEN
        bVibrationFault := FALSE;
        bBearingTempFault := FALSE;
        bLubePressureFault := FALSE;
        bFault := FALSE;
        IF iState = 3 THEN iState := 0; END_IF;
    END_IF;

    CASE iState OF
        0:
            bVFD_Run := FALSE;
            rVFD_SpeedRef := 0.0;
            bLubePumpRun := FALSE;
            IF bStart AND NOT bFault THEN
                bLubePumpRun := TRUE;
                iState := 1;
            END_IF;
        1:
            bLubePumpRun := TRUE;
            IF tonLubeDelay.Q AND NOT bLubePressureFault THEN
                bVFD_Run := TRUE;
                rVFD_SpeedRef := rSpeedSetpoint;
                IF ABS(rActualSpeed - rSpeedSetpoint) < 20.0 THEN iState := 2; END_IF;
            END_IF;
            IF bStop THEN iState := 0; END_IF;
        2:
            bVFD_Run := TRUE;
            rVFD_SpeedRef := rSpeedSetpoint;
            IF bStop THEN iState := 0; END_IF;
        3:
            bVFD_Run := FALSE;
            rVFD_SpeedRef := 0.0;
            bLubePumpRun := TRUE;
            IF rActualSpeed < 5.0 THEN bLubePumpRun := FALSE; END_IF;
    END_CASE;

    tonDischargeInt(IN := (iState = 2) AND NOT tonDischargeDur.Q, PT := tDischargeInterval);
    tonDischargeDur(IN := tonDischargeInt.Q, PT := tDischargeDuration);
    bDischargeValve := tonDischargeInt.Q;

    PID_Cooling(
        Setpoint := 50.0,
        Input := rBearingTemp,
        ManualEnable := FALSE,
        Output => rCoolingValveCmd
    );
END_FUNCTION_BLOCK
```

