```scl
FUNCTION_BLOCK "FB_CentrifugalSeparator_Breadth"
TITLE = 'Centrifugal Separator with Profinet & Diagnostics'

TYPE
    udtProfinetCmd : STRUCT
        RemoteStart : BOOL;
        RemoteStop : BOOL;
        RemoteReset : BOOL;
        SpeedSpLimit : REAL;
    END_STRUCT;

    udtProfinetStatus : STRUCT
        Running : BOOL;
        FaultActive : BOOL;
        ErrorCode : WORD;
        ActualSpeed : REAL;
        ActualBearingTemp : REAL;
    END_STRUCT;
END_TYPE

VAR_INPUT
    PN_Cmd : "udtProfinetCmd";
    bLocalMode : BOOL;
    bLocalStart : BOOL;
    bLocalStop : BOOL;
    rSpeedSetpoint : REAL;
    rActualSpeed : REAL;
    rVibration : REAL;
    rBearingTemp : REAL;
    rLubePressure : REAL;
END_VAR

VAR_OUTPUT
    PN_Status : "udtProfinetStatus";
    bVFD_Run : BOOL;
    rVFD_SpeedRef : REAL;
    bLubePumpRun : BOOL;
    iState : INT;
END_VAR

VAR
    wErrorCode : WORD;
    bStartReq : BOOL;
    bStopReq : BOOL;
    bResetReq : BOOL;
END_VAR

BEGIN
    IF bLocalMode THEN
        bStartReq := bLocalStart;
        bStopReq := bLocalStop;
        bResetReq := bLocalStart;
    ELSE
        bStartReq := PN_Cmd.RemoteStart;
        bStopReq := PN_Cmd.RemoteStop;
        bResetReq := PN_Cmd.RemoteReset;
    END_IF;

    IF rVibration > 5.0 THEN wErrorCode := wErrorCode OR 16#0001; END_IF;
    IF rBearingTemp > 80.0 THEN wErrorCode := wErrorCode OR 16#0002; END_IF;

    IF bResetReq THEN
        wErrorCode := 16#0000;
        IF iState = 3 THEN iState := 0; END_IF;
    END_IF;

    IF wErrorCode <> 16#0000 THEN iState := 3; END_IF;

    CASE iState OF
        0:
            bVFD_Run := FALSE;
            IF bStartReq AND wErrorCode = 16#0000 THEN iState := 1; END_IF;
        1, 2:
            bVFD_Run := TRUE;
            IF NOT bLocalMode AND rSpeedSetpoint > PN_Cmd.SpeedSpLimit THEN
                rVFD_SpeedRef := PN_Cmd.SpeedSpLimit;
            ELSE
                rVFD_SpeedRef := rSpeedSetpoint;
            END_IF;
            IF bStopReq THEN iState := 0; END_IF;
        3:
            bVFD_Run := FALSE;
    END_CASE;

    PN_Status.Running := bVFD_Run;
    PN_Status.FaultActive := (wErrorCode <> 16#0000);
    PN_Status.ErrorCode := wErrorCode;
    PN_Status.ActualSpeed := rActualSpeed;
    PN_Status.ActualBearingTemp := rBearingTemp;
END_FUNCTION_BLOCK
