```scl
FUNCTION_BLOCK "FB_CentrifugalSeparator_Adversarial"
TITLE = 'Centrifugal Separator with Adversarial Defense'

VAR_INPUT
    rVibration_Sensor1 : REAL;
    rVibration_Sensor2 : REAL;
    rActualSpeed : REAL;
    rHIL_ExpectedVibration : REAL;
    bHIL_SyncPulse : BOOL;
    bStart : BOOL;
    iUserRole : INT;
END_VAR

VAR_OUTPUT
    bVFD_Run : BOOL;
    iState : INT;
    wErrorCode : WORD;
    bHIL_DeviationAlarm : BOOL;
END_VAR

VAR
    tonSelfTest : TON;
    rVibrationAvg : REAL;
    bSensorDriftFault : BOOL;
    bSelfTestPassed : BOOL;
    tonHIL_Watchdog : TON;
END_VAR

BEGIN
    IF ABS(rVibration_Sensor1 - rVibration_Sensor2) > 1.5 THEN
        bSensorDriftFault := TRUE;
        wErrorCode := wErrorCode OR 16#0100;
    ELSE
        bSensorDriftFault := FALSE;
        rVibrationAvg := (rVibration_Sensor1 + rVibration_Sensor2) / 2.0;
    END_IF;

    tonHIL_Watchdog(IN := NOT bHIL_SyncPulse, PT := T#2S);
    IF tonHIL_Watchdog.Q THEN
        wErrorCode := wErrorCode OR 16#0200;
    END_IF;

    IF (iState = 3) AND (ABS(rVibrationAvg - rHIL_ExpectedVibration) > 2.0) THEN
        bHIL_DeviationAlarm := TRUE;
    END_IF;

    CASE iState OF
        0:
            bVFD_Run := FALSE;
            bSelfTestPassed := FALSE;
            IF bStart AND (iUserRole >= 1) AND wErrorCode = 0 THEN iState := 1; END_IF;
        1:
            bVFD_Run := TRUE;
            tonSelfTest(IN := TRUE, PT := T#10S);
            IF rVibrationAvg > 2.0 THEN
                wErrorCode := wErrorCode OR 16#0400;
                iState := 99;
            END_IF;
            IF tonSelfTest.Q AND rActualSpeed > 40.0 THEN
                bSelfTestPassed := TRUE;
                tonSelfTest(IN := FALSE, PT := T#10S);
                iState := 2;
            END_IF;
        2:
            iState := 3;
        3:
            bVFD_Run := TRUE;
            IF wErrorCode <> 0 THEN iState := 99; END_IF;
        99:
            bVFD_Run := FALSE;
            bSelfTestPassed := FALSE;
    END_CASE;
END_FUNCTION_BLOCK
