```pascal
PROGRAM PRG_BWTS_Reasoning
VAR
    fFlowRate, fUvPowerOutput, fDosingPumpSpeed : LREAL;

    // Security & Failover
    nCurrentRoleLevel : INT; // 0=Guest, 1=Operator, 2=Admin
    bIsPrimaryPLC : BOOL := TRUE;
    fbHeartbeatPulse : TON;
    bPartnerHeartbeat : BOOL;
    bTakeoverActive : BOOL;

    // SCADA OPC UA
    {attribute 'OPC.UA.DA' := '1'}
    stScadaData : STRUCT
        SystemStatus : INT;
        TotalFlow : LREAL;
        ActiveAlarms : DWORD;
    END_STRUCT;
END_VAR

// IEC 62443 RBAC Checking
IF nCurrentRoleLevel < 1 THEN
    // No process control allowed
    fUvPowerOutput := 0.0; fDosingPumpSpeed := 0.0;
    RETURN;
END_IF

// Redundancy Logic
fbHeartbeatPulse(IN:=NOT fbHeartbeatPulse.Q, PT:=T#500MS);
IF NOT bPartnerHeartbeat AND NOT bIsPrimaryPLC THEN
    bTakeoverActive := TRUE;
    bIsPrimaryPLC := TRUE; // Promote to primary
END_IF

IF bIsPrimaryPLC THEN
    // Execute control logic
    fUvPowerOutput := fFlowRate * 0.5;
    stScadaData.SystemStatus := 1; // Running
    stScadaData.TotalFlow := stScadaData.TotalFlow + fFlowRate;
ELSE
