    Average_Load : REAL;
    Load_Error : REAL;
    Base_Fuel_Cmd : REAL;

    // Surge control params
    Surge_Line_Limit : REAL;
    Surge_Margin : REAL := 0.1; // 10% margin

    // Fuel Temp Comp
    Fuel_Density_Nominal : REAL := 840.0; // kg/m3 at 15C
    Fuel_Temp_Coeff : REAL := 0.7;
    Density_Actual : REAL;
    Density_Comp_Factor : REAL;
    i : DINT;
