Speed_Error := Rated_Speed - Speed_Feedback;
Speed_Integral := Speed_Integral + (Speed_Error * Ki);
IF Speed_Integral > 100.0 THEN Speed_Integral := 100.0; END_IF;
IF Speed_Integral < 0.0 THEN Speed_Integral := 0.0; END_IF;
Base_Fuel_Cmd := (Speed_Error * Kp) + Speed_Integral + (Load_Error * Kp_Load);

