        #MotorSpeedRef := 0.0;
        #BrakeCommand := FALSE;
        IF #Enable THEN #State := 1; END_IF;
    1: 
        #MotorSpeedRef := 0.0;
        #BrakeCommand := FALSE;
        IF #ActualTension > (#SetpointTension + #RenderThreshold) THEN #State := 2;
        ELSIF #ActualTension < (#SetpointTension - #RecoverThreshold) THEN #State := 3;
        END_IF;
    2:
        #MotorSpeedRef := -10.0;
        #BrakeCommand := TRUE;
        IF #ActualTension <= #SetpointTension THEN #State := 1; END_IF;
    3:
        #MotorSpeedRef := 10.0;
        #BrakeCommand := TRUE;
        IF #ActualTension >= #SetpointTension THEN #State := 1; END_IF;
END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "ASD_Winch_Control_DualMotor"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.2
   VAR_INPUT 
      Motor1Torque : Real;
      Motor2Torque : Real;
   END_VAR
   VAR_OUTPUT 
      Motor1SpeedRef : Real;
      Motor2SpeedRef : Real;
   END_VAR
   VAR 
      BaseSpeed : Real := 0.0;
      TorqueDiff : Real;
      BalanceTrim : Real;
   END_VAR
BEGIN
// Dual Motor Load Sharing
#TorqueDiff := #Motor1Torque - #Motor2Torque;
#BalanceTrim := #TorqueDiff * 0.1;
#Motor1SpeedRef := #BaseSpeed - #BalanceTrim;
#Motor2SpeedRef := #BaseSpeed + #BalanceTrim;
END_FUNCTION_BLOCK

