```pascal
// User Data Types for SCADA and Security
TYPE "SCADA_Control_Type"
   STRUCT
      Secure_Token : DWord;
      Start_Cast_Cmd : Bool;
      Stop_Cast_Cmd : Bool;
      Setpoint_Level : Real;
   END_STRUCT
END_TYPE

TYPE "SCADA_Status_Type"
   STRUCT
      System_State : Int;
      Active_PLC_ID : Int;
      Mould_Level : Real;
      Alarms : DWord;
   END_STRUCT
END_TYPE

FUNCTION_BLOCK "CC_Robust_Control"
VERSION : 0.4
   VAR_INPUT
      Mould_Level_Raw : Real;
      Casting_Speed : Real; 
      Thermocouple_Grid : Array[1..20] of Real;
      Steel_Grade_ID : Int;
      PN_Node_Status : DWord;
      Partner_PLC_Alive : Bool; // Hot-Standby Heartbeat
      Partner_PLC_Active : Bool;
      SCADA_In : "SCADA_Control_Type";
   END_VAR

   VAR_OUTPUT
      Stopper_Rod_Pos : Real;
      Oscillator_Freq : Real;
      Oscillator_Amp : Real;
      Spray_Zone_1_Flow : Real;
      Spray_Zone_2_Flow : Real;
      Is_Active_PLC : Bool;
      SCADA_Out : "SCADA_Status_Type";
   END_VAR

   VAR_IN_OUT
      PID_Instance : "PID_Compact";
   END_VAR

   VAR
      Cast_Active : Bool;
      Breakout_Alarm : Bool;
      System_Fault : Bool;
      i : Int;
      Security_Lockout : Bool;
   END_VAR

BEGIN
   // 1. IEC 62443 Cybersecurity: Authentication & Input Validation
   IF #SCADA_In.Secure_Token <> 16#A5A5_5A5A THEN
      #Security_Lockout := TRUE; 
   ELSE
      #Security_Lockout := FALSE;
   END_IF;

   IF #SCADA_In.Setpoint_Level < 50.0 OR #SCADA_In.Setpoint_Level > 95.0 THEN
      #Security_Lockout := TRUE;
   END_IF;

   // 2. Hot-Standby Failover Logic
   IF NOT #Partner_PLC_Alive AND NOT #System_Fault THEN
      #Is_Active_PLC := TRUE;
   ELSIF #Partner_PLC_Active THEN
      #Is_Active_PLC := FALSE;
   END_IF;

   IF NOT #Is_Active_PLC THEN
      #Stopper_Rod_Pos := 0.0;
      RETURN;
   END_IF;

   // 3. Process Control 
   IF NOT #Security_Lockout AND #SCADA_In.Start_Cast_Cmd THEN #Cast_Active := TRUE;
   ELSIF #SCADA_In.Stop_Cast_Cmd THEN #Cast_Active := FALSE; END_IF;

   #Breakout_Alarm := FALSE;
   FOR #i := 2 TO 20 DO
      IF (#Thermocouple_Grid[#i] - #Thermocouple_Grid[#i-1]) > 50.0 AND #Cast_Active THEN 
         #Breakout_Alarm := TRUE; #Cast_Active := FALSE;
      END_IF;
   END_FOR;

   #PID_Instance(Setpoint := #SCADA_In.Setpoint_Level, Input := #Mould_Level_Raw, Reset := NOT #Cast_Active, Output => #Stopper_Rod_Pos);
   IF NOT #Cast_Active THEN #Stopper_Rod_Pos := 0.0; END_IF;

   IF #Cast_Active THEN
      #Oscillator_Freq := #Casting_Speed * 1.5; 
      #Oscillator_Amp := 4.0;
      #Spray_Zone_1_Flow := #Casting_Speed * 100.0;
      #Spray_Zone_2_Flow := #Casting_Speed * 80.0;
   ELSE
      #Oscillator_Freq := 0.0; #Oscillator_Amp := 0.0;
      #Spray_Zone_1_Flow := 0.0; #Spray_Zone_2_Flow := 0.0;
   END_IF;

   // 4. SCADA Integration Mapping
   #SCADA_Out.Active_PLC_ID := 1;
   #SCADA_Out.Mould_Level := #Mould_Level_Raw;
   #SCADA_Out.System_State := BOOL_TO_INT(#Cast_Active);
   #SCADA_Out.Alarms.%X0 := #Breakout_Alarm;
   #SCADA_Out.Alarms.%X1 := #Security_Lockout;
END_FUNCTION_BLOCK
