      HIL_Sensor_Data : Real; // Simulated sensor data from Digital Twin
   END_VAR

   VAR_OUTPUT
      Stopper_Rod_Pos : Real;
      Oscillator_Freq : Real;
      Spray_Zone_Flow : Real;
      System_State : String[20];
      Drift_Alarm : Bool;
   END_VAR

   VAR_IN_OUT
      PID_Instance : "PID_Compact";
   END_VAR

   VAR
      Cast_Active : Bool;
      Self_Test_Phase : Int := 0;
      Self_Test_Timer : Int := 0;
      Validated_Mould_Level : Real;
   END_VAR

BEGIN
   // 1. HIL Digital Twin Synchronization Hooks
   IF #HIL_Active THEN
      #Validated_Mould_Level := #HIL_Sensor_Data;
      #System_State := 'HIL_SIMULATION';
   ELSE
      // 2. Sensor Drift Detection (Adversarial/Degradation check)
      IF ABS(#Mould_Level_Rad - #Mould_Level_Opt) > 5.0 THEN
         #Drift_Alarm := TRUE;
         #System_State := 'SENSOR_DRIFT_ERROR';
         #Validated_Mould_Level := #Mould_Level_Opt;
      ELSE
         #Drift_Alarm := FALSE;
         #Validated_Mould_Level := (#Mould_Level_Rad + #Mould_Level_Opt) / 2.0;
      END_IF;
   END_IF;

   // 3. Pre-Cast Actuator Self-Test Routine
   IF #SCADA_In.Start_Cast_Cmd AND NOT #Cast_Active AND #Self_Test_Phase = 0 THEN
      #Self_Test_Phase := 1;
      #System_State := 'SELF_TESTING';
   END_IF;

   IF #Self_Test_Phase > 0 THEN
      #Self_Test_Timer := #Self_Test_Timer + 1;
      CASE #Self_Test_Phase OF
         1: // Test Stopper Rod full stroke
            #Stopper_Rod_Pos := 100.0;
            IF #Self_Test_Timer > 100 THEN #Self_Test_Phase := 2; #Self_Test_Timer := 0; END_IF;
         2: // Close Stopper Rod
            #Stopper_Rod_Pos := 0.0;
            IF #Self_Test_Timer > 100 THEN #Self_Test_Phase := 3; #Self_Test_Timer := 0; END_IF;
         3: // Test Oscillator
            #Oscillator_Freq := 1.0;
            IF #Self_Test_Timer > 100 THEN 
               #Self_Test_Phase := 0; // Test Complete
               #Self_Test_Timer := 0;
               #Cast_Active := TRUE;
               #System_State := 'CASTING';
            END_IF;
      END_CASE;
      RETURN;
   END_IF;

   // 4. Core Robust Process Control
   IF #SCADA_In.Stop_Cast_Cmd THEN 
      #Cast_Active := FALSE; 
      #System_State := 'STOPPED';
   END_IF;

   IF #Cast_Active THEN
      #PID_Instance(Setpoint := #SCADA_In.Setpoint_Level, Input := #Validated_Mould_Level, Reset := FALSE, Output => #Stopper_Rod_Pos);
      #Oscillator_Freq := #Casting_Speed * 1.5;
      #Spray_Zone_Flow := #Casting_Speed * 100.0;
   ELSE
      #Stopper_Rod_Pos := 0.0;
      #Oscillator_Freq := 0.0;
      #Spray_Zone_Flow := 0.0;
      #PID_Instance(Setpoint := 0.0, Input := 0.0, Reset := TRUE, Output => #Stopper_Rod_Pos);
   END_IF;
END_FUNCTION_BLOCK
