FUNCTION_BLOCK "FB_EngineBlockCNC_ATC"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      startMachining : Bool;
      spindleTempSensor : Real;
      toolWearValue : Real;
      conveyorStart : Bool;

      // ATC Inputs
      reqToolChange : Bool;
      targetToolSlot : Int; // 1-12
      carouselInPosition : Bool;
      armAtSpindle : Bool;
      armAtCarousel : Bool;
   END_VAR

   VAR_OUTPUT 
      spindleCoolantValve : Real;
      toolOffsetActive : Real;
      conveyorMotorFwd : Bool;
      conveyorMotorRev : Bool;

      // ATC Outputs
      carouselIndexFwd : Bool;
      carouselIndexRev : Bool;
      armRotate : Bool;
      spindleUnclamp : Bool;
      atcReady : Bool;
   END_VAR

   VAR 
      pidCoolant : "PID_Compact";
      conveyorState : Int;
      timerConveyor : TON_TIME;

      // ATC Vars
      atcState : Int; // 0=Idle, 1=Index, 2=Swap
      currentSlot : Int := 1;
      timerATC : TON_TIME;
   END_VAR

BEGIN
    // 1. Tool Wear Compensation
    IF #toolWearValue > 0.05 THEN
        #toolOffsetActive := #toolWearValue;
    ELSE
        #toolOffsetActive := 0.0;
    END_IF;

    // 2. PID Control for Spindle Coolant
    #pidCoolant(
        Setpoint := 22.0,
        Input := #spindleTempSensor,
        Output => #spindleCoolantValve
    );

    // 3. Chip Conveyor Sequencing
    IF #conveyorStart THEN
        CASE #conveyorState OF
            0: 
                #conveyorState := 1;
            1:
                #conveyorMotorFwd := TRUE;
                #conveyorMotorRev := FALSE;
                #timerConveyor(IN := TRUE, PT := T#15s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 2;
                    #timerConveyor(IN := FALSE, PT := T#15s);
                END_IF;
            2:
                #conveyorMotorFwd := FALSE;
                #conveyorMotorRev := TRUE;
                #timerConveyor(IN := TRUE, PT := T#2s);
                IF #timerConveyor.Q THEN
                    #conveyorState := 1;
                    #timerConveyor(IN := FALSE, PT := T#2s);
                END_IF;
        END_CASE;
    ELSE
        #conveyorState := 0;
        #conveyorMotorFwd := FALSE;
        #conveyorMotorRev := FALSE;
        #timerConveyor(IN := FALSE, PT := T#15s);
    END_IF;

    // 4. Automated Tool Changer (ATC) Logic
    CASE #atcState OF
        0: // Idle
            #atcReady := TRUE;
            #carouselIndexFwd := FALSE;
            #armRotate := FALSE;
            #spindleUnclamp := FALSE;
            IF #reqToolChange AND (#targetToolSlot <> #currentSlot) AND (#targetToolSlot >= 1) AND (#targetToolSlot <= 12) THEN
                #atcReady := FALSE;
                #atcState := 1;
            END_IF;

        1: // Indexing Carousel
            IF NOT #carouselInPosition THEN
                #carouselIndexFwd := TRUE; // Simple fwd index logic
            ELSE
                #carouselIndexFwd := FALSE;
                #currentSlot := #targetToolSlot;
                #atcState := 2;
            END_IF;

        2: // Arm Swap Sequence
            #spindleUnclamp := TRUE;
            #armRotate := TRUE;
            #timerATC(IN := TRUE, PT := T#3s);
            IF #timerATC.Q AND #armAtSpindle AND #armAtCarousel THEN
                #spindleUnclamp := FALSE;
                #armRotate := FALSE;
                #atcState := 0;
                #timerATC(IN := FALSE, PT := T#3s);
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
