    BottomPlatenPressure : REAL;
    BladderPressure : REAL;

    // Outputs
    SteamValve : BOOL;
    BlowDownValve : BOOL;
    TopPlatenValve : REAL; // 0-100%
    BottomPlatenValve : REAL; // 0-100%
    CycleComplete : BOOL;

    // State
    State : INT := 0;
    Timer : TON;
    TempCurve : ARRAY[0..4] OF REAL := [100.0, 150.0, 175.0, 150.0, 100.0];
    TimeCurve : ARRAY[0..4] OF DINT := [60000, 120000, 300000, 120000, 60000];
    CurveIndex : INT := 0;

    // PID
    TopPID : PID;
    BottomPID : PID;
    TargetPressure : REAL := 500.0;
END_VAR

// E-Stop handling
IF EStop THEN
    State := 99;
END_IF;

CASE State OF
    0: // Idle
        SteamValve := FALSE;
        BlowDownValve := FALSE;
        CycleComplete := FALSE;
        CurveIndex := 0;
        IF StartCycle AND NOT StopCycle THEN
            State := 10;
        END_IF;

    10: // Bladder Inflation & Heating
        SteamValve := TRUE;
        BlowDownValve := FALSE;
        Timer(IN:=TRUE, PT:=TimeCurve[CurveIndex]);

        // Temperature check (simplified profiling)
        IF Timer.Q THEN
            Timer(IN:=FALSE);
            CurveIndex := CurveIndex + 1;
            IF CurveIndex > 4 THEN
                State := 20;
            END_IF;
        END_IF;

        // Platen Pressure PID (mocked ST implementation for Studio 5000)
        TopPID(SetPoint:=TargetPressure, ProcessVariable:=TopPlatenPressure, ControlVariable=>TopPlatenValve);
        BottomPID(SetPoint:=TargetPressure, ProcessVariable:=BottomPlatenPressure, ControlVariable=>BottomPlatenValve);

    20: // Blow-down
        SteamValve := FALSE;
        BlowDownValve := TRUE;
        TopPlatenValve := 0.0;
        BottomPlatenValve := 0.0;

        IF BladderPressure < 5.0 THEN
            State := 30;
        END_IF;

    30: // Complete
        BlowDownValve := FALSE;
        CycleComplete := TRUE;
        State := 0;

    99: // Fault/E-Stop
        SteamValve := FALSE;
        BlowDownValve := TRUE;
        TopPlatenValve := 0.0;
        BottomPlatenValve := 0.0;
        IF NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;
END_PROGRAM

