    // Existing I/O
    StartCycle : BOOL; EStop : BOOL;
    CurrentTemp, TopPlatenPressure, BottomPlatenPressure, BladderPressure : REAL;
    SteamValve, BlowDownValve : BOOL;
    TopPlatenValve, BottomPlatenValve : REAL;

    // Nitrogen Sub-system I/O
    NitrogenInletValve : BOOL;
    NitrogenRecoveryValve : BOOL;
    N2Pressure : REAL;

    State : INT := 0;
    Timer : TON;
    TempCurve : ARRAY[0..4] OF REAL := [100.0, 150.0, 175.0, 150.0, 100.0];
    TimeCurve : ARRAY[0..4] OF DINT := [60000, 120000, 300000, 120000, 60000];
    CurveIndex : INT := 0;

    TopPID, BottomPID : PID;
    TargetPressure : REAL := 500.0;
END_VAR

IF EStop THEN State := 99; END_IF;

CASE State OF
    0: // Idle
        SteamValve := FALSE; BlowDownValve := FALSE;
        NitrogenInletValve := FALSE; NitrogenRecoveryValve := FALSE;
        IF StartCycle THEN State := 10; END_IF;

    10: // Vulcanization & Heating
        SteamValve := TRUE;
        Timer(IN:=TRUE, PT:=TimeCurve[CurveIndex]);
