Here is a Siemens SCL program that implements the Base Code for a Utility-Scale Solar Inverter with MPPT and Grid Synchronization.

```pascal
FUNCTION_BLOCK "SolarInverter_Base"
VERSION : 1.0
VAR_INPUT
    Enable : Bool;
    PV_Voltage : Real;
    PV_Current : Real;
    Grid_Voltage : Real;
    Grid_Freq : Real;
END_VAR
VAR_OUTPUT
    PWM_Duty_Cycle : Real;
    Grid_Connected : Bool;
    MPPT_Active : Bool;
END_VAR
VAR
    Prev_Power : Real := 0.0;
    Prev_Voltage : Real := 0.0;
    Duty_Cycle : Real := 0.5;
    Step_Size : Real := 0.005;
END_VAR
BEGIN
    IF NOT Enable THEN
        Grid_Connected := FALSE;
        MPPT_Active := FALSE;
        PWM_Duty_Cycle := 0.0;
        RETURN;
    END_IF;

    // Grid Synchronization (Assuming 400V, 50Hz)
    IF (Grid_Voltage > 360.0) AND (Grid_Voltage < 440.0) AND (Grid_Freq > 49.5) AND (Grid_Freq < 50.5) THEN
        Grid_Connected := TRUE;
    ELSE
        Grid_Connected := FALSE;
        MPPT_Active := FALSE;
        PWM_Duty_Cycle := 0.0;
        RETURN;
    END_IF;

    // MPPT (Perturb and Observe)
    MPPT_Active := TRUE;
    VAR Temp_Power : Real;
    Temp_Power := PV_Voltage * PV_Current;

    IF (Temp_Power - Prev_Power) > 0.0 THEN
        IF (PV_Voltage - Prev_Voltage) > 0.0 THEN
            Duty_Cycle := Duty_Cycle - Step_Size;
        ELSE
            Duty_Cycle := Duty_Cycle + Step_Size;
        END_IF;
    ELSIF (Temp_Power - Prev_Power) < 0.0 THEN
        IF (PV_Voltage - Prev_Voltage) > 0.0 THEN
            Duty_Cycle := Duty_Cycle + Step_Size;
        ELSE
            Duty_Cycle := Duty_Cycle - Step_Size;
        END_IF;
    END_IF;

    IF Duty_Cycle > 0.95 THEN Duty_Cycle := 0.95; END_IF;
    IF Duty_Cycle < 0.05 THEN Duty_Cycle := 0.05; END_IF;

    Prev_Power := Temp_Power;
    Prev_Voltage := PV_Voltage;
    PWM_Duty_Cycle := Duty_Cycle;
END_FUNCTION_BLOCK
```

