        MPPT_Active := FALSE;
        Derating_Active := FALSE;
        PWM_Duty_Cycle := 0.0;
        RETURN;
    END_IF;

    // Thermal Management
    IF IGBT_Temp > 90.0 THEN
        Thermal_Fault := TRUE;
        Grid_Connected := FALSE;
        MPPT_Active := FALSE;
        PWM_Duty_Cycle := 0.0;
        RETURN;
    ELSIF IGBT_Temp > 75.0 THEN
        Derating_Active := TRUE;
        Power_Limit := (90.0 - IGBT_Temp) / 15.0; // Linear derating from 100% to 0%
        Thermal_Fault := FALSE;
    ELSE
        Derating_Active := FALSE;
        Power_Limit := 1.0;
        Thermal_Fault := FALSE;
    END_IF;

    // Grid Synchronization
    IF (Grid_Voltage > 360.0) AND (Grid_Voltage < 440.0) AND (Grid_Freq > 49.5) AND (Grid_Freq < 50.5) THEN
        Grid_Connected := TRUE;
    ELSE
        Grid_Connected := FALSE;
        MPPT_Active := FALSE;
        PWM_Duty_Cycle := 0.0;
        RETURN;
    END_IF;

    // MPPT (Perturb and Observe)
    MPPT_Active := TRUE;
    VAR Temp_Power : Real;
    Temp_Power := PV_Voltage * PV_Current;

    IF (Temp_Power - Prev_Power) > 0.0 THEN
        IF (PV_Voltage - Prev_Voltage) > 0.0 THEN
            Duty_Cycle := Duty_Cycle - Step_Size;
        ELSE
            Duty_Cycle := Duty_Cycle + Step_Size;
        END_IF;
    ELSIF (Temp_Power - Prev_Power) < 0.0 THEN
        IF (PV_Voltage - Prev_Voltage) > 0.0 THEN
            Duty_Cycle := Duty_Cycle + Step_Size;
        ELSE
            Duty_Cycle := Duty_Cycle - Step_Size;
        END_IF;
    END_IF;

    // Apply Limits and Derating
    IF Duty_Cycle > (0.95 * Power_Limit) THEN Duty_Cycle := 0.95 * Power_Limit; END_IF;
    IF Duty_Cycle < 0.05 THEN Duty_Cycle := 0.05; END_IF;

    Prev_Power := Temp_Power;
    Prev_Voltage := PV_Voltage;
    PWM_Duty_Cycle := Duty_Cycle;
END_FUNCTION_BLOCK
