FUNCTION_BLOCK "SolarInverter_Profinet_Diag"
VERSION : 1.2
VAR_INPUT
    Enable : Bool;
    PV_Voltage : Real;
    PV_Current : Real;
    Grid_Voltage : Real;
    Grid_Freq : Real;
    IGBT_Temp : Real;
    Profinet_Ctrl_Word : Word;
