        Grid_Connected := FALSE;
        MPPT_Active := FALSE;
        PWM_Duty_Cycle := 0.0;
        Profinet_Stat_Word := Profinet_Stat_Word AND 16#FFFE; // Clear running bit
        RETURN;
    END_IF;

    // Thermal Management & Diagnostics
    IF IGBT_Temp > 90.0 THEN
        Fault_Active := TRUE;
        IF Error_Index < 10 THEN Error_Buffer[Error_Index] := 101; Error_Index := Error_Index + 1; END_IF;
        Grid_Connected := FALSE;
        PWM_Duty_Cycle := 0.0;
        RETURN;
    ELSIF IGBT_Temp > 75.0 THEN
        Power_Limit := (90.0 - IGBT_Temp) / 15.0;
        Profinet_Stat_Word := Profinet_Stat_Word OR 16#0004; // Derating bit
    ELSE
        Power_Limit := 1.0;
        Profinet_Stat_Word := Profinet_Stat_Word AND 16#FFFB; // Clear derating bit
    END_IF;

    // Grid Synchronization
    IF (Grid_Voltage < 360.0) OR (Grid_Voltage > 440.0) THEN
        Fault_Active := TRUE;
        IF Error_Index < 10 THEN Error_Buffer[Error_Index] := 201; Error_Index := Error_Index + 1; END_IF;
        Grid_Connected := FALSE;
        RETURN;
    END_IF;

    Grid_Connected := TRUE;
    Profinet_Stat_Word := Profinet_Stat_Word OR 16#0001; // Running bit

    // MPPT Logic
    MPPT_Active := TRUE;
    VAR Temp_Power : Real;
    Temp_Power := PV_Voltage * PV_Current;

    IF (Temp_Power - Prev_Power) > 0.0 THEN
        IF (PV_Voltage - Prev_Voltage) > 0.0 THEN
            Duty_Cycle := Duty_Cycle - Step_Size;
        ELSE
            Duty_Cycle := Duty_Cycle + Step_Size;
        END_IF;
    ELSIF (Temp_Power - Prev_Power) < 0.0 THEN
        IF (PV_Voltage - Prev_Voltage) > 0.0 THEN
            Duty_Cycle := Duty_Cycle + Step_Size;
        ELSE
            Duty_Cycle := Duty_Cycle - Step_Size;
        END_IF;
    END_IF;

    IF Duty_Cycle > (0.95 * Power_Limit) THEN Duty_Cycle := 0.95 * Power_Limit; END_IF;
    IF Duty_Cycle < 0.05 THEN Duty_Cycle := 0.05; END_IF;

    Prev_Power := Temp_Power;
    Prev_Voltage := PV_Voltage;
    PWM_Duty_Cycle := Duty_Cycle;
END_FUNCTION_BLOCK
