    stScadaData : ST_SCADA_Data;

    // Cybersecurity & RBAC
    iUserLevel AT %I* : INT; // 0=Guest, 1=Operator, 2=Admin
    bManualOverrideCmd AT %I* : BOOL;
    rManualPitchCmd AT %I* : REAL;

    // Redundancy & Failover
    bPrimaryActive : BOOL := TRUE;
    iHeartbeatIn AT %I* : INT;
    iHeartbeatOut AT %Q* : INT;
    iLastHeartbeat : INT;
    tHeartbeatTimer : TON;
    bRedundancyFailover : BOOL;

    // Core Inputs
    rRotorSpeed AT %I* : REAL; 
