FUNCTION_BLOCK "HydroDam_Profinet_Diag"
VAR_INPUT
    PN_In : "PN_Data_In";
    Act_Freq : REAL;
    Valve_Feedback : REAL;
END_VAR
VAR_OUTPUT
    Valve_Pos : REAL;
    Fault_Valve : BOOL;
    Fault_Sensor : BOOL;
END_VAR
VAR
    Set_Freq : REAL;
END_VAR
BEGIN
    IF #PN_In.SCADA_Mode THEN #Set_Freq := #PN_In.Target_Freq; ELSE #Set_Freq := 50.0; END_IF;
    IF #Act_Freq < 0.0 OR #Act_Freq > 100.0 THEN #Fault_Sensor := TRUE; ELSE #Fault_Sensor := FALSE; END_IF;
    IF ABS(#Valve_Pos - #Valve_Feedback) > 10.0 THEN #Fault_Valve := TRUE; ELSE #Fault_Valve := FALSE; END_IF;
    IF NOT #Fault_Sensor AND NOT #Fault_Valve THEN
        #Valve_Pos := 50.0; // Normal logic
    ELSE
        #Valve_Pos := 0.0; // Fail-safe
    END_IF;
END_FUNCTION_BLOCK
