```scl
FUNCTION_BLOCK "HydroDam_Adversarial_Control"
VAR_INPUT
    HIL_Mode : BOOL;
    Pressure_In : REAL;
    Start_Self_Test : BOOL;
END_VAR
VAR_OUTPUT
    Drift_Detected : BOOL;
    Test_State : INT;
END_VAR
VAR
    Pres_Arr : ARRAY[0..9] OF REAL;
    Pres_Sum : REAL;
    Idx : INT;
    Pres_Avg : REAL;
END_VAR
BEGIN
    IF NOT #HIL_Mode THEN
        #Pres_Sum := #Pres_Sum - #Pres_Arr[#Idx] + #Pressure_In;
        #Pres_Arr[#Idx] := #Pressure_In;
        #Idx := (#Idx + 1) MOD 10;
        #Pres_Avg := #Pres_Sum / 10.0;
        IF ABS(#Pressure_In - #Pres_Avg) > 5.0 THEN
            #Drift_Detected := TRUE;
        END_IF;
    END_IF;
    IF #Start_Self_Test THEN
        CASE #Test_State OF
            0: #Test_State := 1; // Start test
            1: #Test_State := 2; // Stroke valve
            2: #Test_State := 3; // Verify feedback
            3: #Test_State := 0; // Complete
        END_CASE;
    END_IF;
END_FUNCTION_BLOCK
