PROGRAM PRG_Electrolyzer_M4
VAR
    // HIL Digital Twin Sync
    bHILMode : BOOL;
    fSimH2Purity : REAL;
    fRealH2Purity_S1 AT %I* : REAL;
    fRealH2Purity_S2 AT %I* : REAL;
    fActiveH2Purity_S1, fActiveH2Purity_S2 : REAL;

    // Drift Detection
    fDriftTolerance : REAL := 0.5;
    bSensorDriftAlarm : BOOL;

    // Self-Test State Machine
    eState : (INIT, SELF_TEST_PUMPS, SELF_TEST_VALVES, READY, RUNNING, FAULT);
    tTestTimer : TON;

    bStartCommand : BOOL;
END_VAR

// HIL Synchronization
IF bHILMode THEN
    fActiveH2Purity_S1 := fSimH2Purity;
    fActiveH2Purity_S2 := fSimH2Purity;
ELSE
    fActiveH2Purity_S1 := fRealH2Purity_S1;
    fActiveH2Purity_S2 := fRealH2Purity_S2;
END_IF

// Sensor Drift Detection
IF ABS(fActiveH2Purity_S1 - fActiveH2Purity_S2) > fDriftTolerance THEN
    bSensorDriftAlarm := TRUE;
ELSE
    bSensorDriftAlarm := FALSE;
END_IF

// Pre-Startup Automated Self-Test Routine
CASE eState OF
    INIT:
        eState := SELF_TEST_PUMPS;

    SELF_TEST_PUMPS:
        // Activate pumps and verify flow feedback (mocked with timer)
        tTestTimer(IN:=TRUE, PT:=T#5S);
        IF tTestTimer.Q THEN
            tTestTimer(IN:=FALSE);
            eState := SELF_TEST_VALVES;
        END_IF

    SELF_TEST_VALVES:
        // Cycle critical interlock valves
        tTestTimer(IN:=TRUE, PT:=T#5S);
        IF tTestTimer.Q THEN
            tTestTimer(IN:=FALSE);
            eState := READY;
        END_IF

    READY:
        IF bStartCommand AND NOT bSensorDriftAlarm THEN 
            eState := RUNNING; 
        END_IF

    RUNNING:
        // Standard operational logic...
        IF bSensorDriftAlarm THEN
            eState := FAULT;
        END_IF

    FAULT:
        // Shutdown sequence...
END_CASE
