FUNCTION_BLOCK "FB_Clarifier_Dosing_Control"
TITLE = 'Municipal Water Clarifier Control with Dosing'
VERSION : '1.1'

VAR_INPUT
    Start_System : Bool;
    Stop_System : Bool;
    Reset_Faults : Bool;
    Rake_Torque : Real; // Current torque in %
    Sludge_Blanket_Level : Real; // Current sludge blanket level in meters
    Influent_Flow : Real; // Influent flow rate m3/h
    Influent_Turbidity : Real; // Influent turbidity NTU
    Torque_High_Limit : Real := 80.0;
    Torque_HH_Limit : Real := 95.0;
    Sludge_Pump_Start_Level : Real := 2.5;
    Sludge_Pump_Stop_Level : Real := 1.0;
    Dosing_Ratio : Real := 0.5; // ml polymer per m3 flow per NTU
END_VAR

VAR_OUTPUT
    Rake_Motor_Run : Bool;
    Sludge_Pump_Run : Bool;
    Dosing_Pump_Speed : Real; // 0-100%
    Torque_Warning : Bool;
    Torque_Trip_Fault : Bool;
    System_Running : Bool;
END_VAR

VAR
    System_Active : Bool;
    Pump_Active : Bool;
    Required_Dosing : Real;
END_VAR

BEGIN
    // System Start/Stop logic
    IF #Stop_System THEN
        #System_Active := FALSE;
    ELSIF #Start_System AND NOT #Torque_Trip_Fault THEN
        #System_Active := TRUE;
    END_IF;

    // Fault Reset
    IF #Reset_Faults THEN
        #Torque_Trip_Fault := FALSE;
        #Torque_Warning := FALSE;
    END_IF;

    // Torque Monitoring
    IF #Rake_Torque >= #Torque_HH_Limit THEN
        #Torque_Trip_Fault := TRUE;
        #System_Active := FALSE;
    END_IF;

    IF #Rake_Torque >= #Torque_High_Limit AND NOT #Torque_Trip_Fault THEN
        #Torque_Warning := TRUE;
    ELSIF #Rake_Torque < (#Torque_High_Limit - 5.0) THEN
        #Torque_Warning := FALSE;
    END_IF;

    // Rake Motor Control
    #Rake_Motor_Run := #System_Active;

    // Sludge Pumping Control
    IF #System_Active THEN
        IF #Sludge_Blanket_Level >= #Sludge_Pump_Start_Level THEN
            #Pump_Active := TRUE;
        ELSIF #Sludge_Blanket_Level <= #Sludge_Pump_Stop_Level THEN
            #Pump_Active := FALSE;
        END_IF;
    ELSE
        #Pump_Active := FALSE;
    END_IF;
    #Sludge_Pump_Run := #Pump_Active;

    // Polymer Dosing Calculation (Feed-forward control)
    IF #System_Active THEN
        // Calculate required polymer dosing rate
        #Required_Dosing := #Influent_Flow * #Influent_Turbidity * #Dosing_Ratio;
        // Normalize to pump speed 0-100% (Assuming 100% = 1000 ml/h)
        #Dosing_Pump_Speed := LIMIT(MN:=0.0, IN:=(#Required_Dosing / 1000.0) * 100.0, MX:=100.0);
    ELSE
        #Dosing_Pump_Speed := 0.0;
    END_IF;

    #System_Running := #System_Active;
END_FUNCTION_BLOCK
