FUNCTION_BLOCK "FB_Clarifier_Diagnostic_Control"
TITLE = 'Municipal Water Clarifier Control with Profinet & Diagnostics'
VERSION : '1.2'

VAR_INPUT
    Start_System : Bool;
    Stop_System : Bool;
    Reset_Faults : Bool;
    Sludge_Blanket_Level : Real; // m
    Level_Sensor_Error : Bool; // 4-20mA wire break
    Influent_Flow : Real; // m3/h
    Influent_Turbidity : Real; // NTU
    VFD_Rake_In : "UDT_Profinet_VFD_In";
    VFD_Pump_In : "UDT_Profinet_VFD_In";
    Torque_High_Limit : Real := 80.0;
    Torque_HH_Limit : Real := 95.0;
END_VAR

VAR_OUTPUT
    VFD_Rake_Out : "UDT_Profinet_VFD_Out";
    VFD_Pump_Out : "UDT_Profinet_VFD_Out";
    Dosing_Pump_Speed : Real; 
    Torque_Warning : Bool;
    System_Fault : Bool;
    Diagnostic_Code : Int; // 0=OK, 1=Torque Trip, 2=Rake VFD Fault, 3=Pump VFD Fault, 4=Sensor Error, 5=Comm Loss
END_VAR

VAR
    System_Active : Bool;
    Pump_Active : Bool;
    Required_Dosing : Real;
    Rake_Torque : Real;
END_VAR

BEGIN
    #Rake_Torque := #VFD_Rake_In.Actual_Torque;

    // Fault Diagnostics
    IF #VFD_Rake_In.Comm_Error OR #VFD_Pump_In.Comm_Error THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 5;
    ELSIF #Level_Sensor_Error THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 4;
    ELSIF #Rake_Torque >= #Torque_HH_Limit THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 1;
    ELSIF #VFD_Rake_In.Fault_Active THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 2;
    ELSIF #VFD_Pump_In.Fault_Active THEN
        #System_Fault := TRUE;
        #Diagnostic_Code := 3;
    END_IF;

    IF #Reset_Faults AND NOT (#VFD_Rake_In.Comm_Error OR #VFD_Pump_In.Comm_Error OR #Level_Sensor_Error OR #VFD_Rake_In.Fault_Active OR #VFD_Pump_In.Fault_Active OR (#Rake_Torque >= #Torque_HH_Limit)) THEN
        #System_Fault := FALSE;
        #Diagnostic_Code := 0;
        #Torque_Warning := FALSE;
    END_IF;

    // Start/Stop Logic
    IF #Stop_System OR #System_Fault THEN
        #System_Active := FALSE;
    ELSIF #Start_System AND NOT #System_Fault THEN
        #System_Active := TRUE;
    END_IF;

    // Torque Warning
    IF #Rake_Torque >= #Torque_High_Limit AND NOT #System_Fault THEN
        #Torque_Warning := TRUE;
    ELSIF #Rake_Torque < (#Torque_High_Limit - 5.0) THEN
        #Torque_Warning := FALSE;
    END_IF;

    // Rake VFD Control (Profinet)
    IF #System_Active THEN
        #VFD_Rake_Out.Control_Word := 16#047F; // ON command
        #VFD_Rake_Out.Speed_Setpoint := 16#4000; // 100% nominal speed
    ELSE
        #VFD_Rake_Out.Control_Word := 16#047E; // OFF command
        #VFD_Rake_Out.Speed_Setpoint := 0;
    END_IF;

    // Sludge Pump Control (Profinet)
    IF #System_Active THEN
        IF #Sludge_Blanket_Level >= 2.5 THEN
            #Pump_Active := TRUE;
        ELSIF #Sludge_Blanket_Level <= 1.0 THEN
            #Pump_Active := FALSE;
        END_IF;
    ELSE
        #Pump_Active := FALSE;
    END_IF;

    IF #Pump_Active THEN
        #VFD_Pump_Out.Control_Word := 16#047F;
        #VFD_Pump_Out.Speed_Setpoint := 16#4000;
    ELSE
        #VFD_Pump_Out.Control_Word := 16#047E;
        #VFD_Pump_Out.Speed_Setpoint := 0;
    END_IF;

    // Polymer Dosing Control
    IF #System_Active THEN
        #Required_Dosing := #Influent_Flow * #Influent_Turbidity * 0.5;
        #Dosing_Pump_Speed := LIMIT(MN:=0.0, IN:=(#Required_Dosing / 1000.0) * 100.0, MX:=100.0);
    ELSE
        #Dosing_Pump_Speed := 0.0;
    END_IF;

END_FUNCTION_BLOCK
