PROGRAM MAIN
VAR
    // State Machine
    eState : (INIT, STANDBY, PRIMING, PRESSURIZING, RUNNING, SHUTDOWN, FAULT);

    // Inputs
    bStartCmd : BOOL;
    bStopCmd : BOOL;
    bResetCmd : BOOL;
    fInletPressure : REAL; // bar
    fPermeateFlow : REAL;  // m3/h
    fBrinePressure : REAL; // bar

    // Outputs
    bFeedPumpCmd : BOOL;
    bHighPressurePumpCmd : BOOL;
    fERDSpeedCmd : REAL; // 0-100%
    bPermeateValve : BOOL;

    // Timers
    fbTimerPriming : TON;
    fbTimerRampUp : TON;

    // Parameters
    fTargetERDSpeed : REAL := 75.0;
    fPressureSetPoint : REAL := 60.0;
END_VAR

CASE eState OF
    INIT:
        bFeedPumpCmd := FALSE;
        bHighPressurePumpCmd := FALSE;
        fERDSpeedCmd := 0.0;
        bPermeateValve := FALSE;
        eState := STANDBY;

    STANDBY:
        IF bStartCmd THEN
            eState := PRIMING;
        END_IF

    PRIMING:
        bFeedPumpCmd := TRUE;
        fbTimerPriming(IN := TRUE, PT := T#10S);
        IF fbTimerPriming.Q AND fInletPressure > 2.0 THEN
            fbTimerPriming(IN := FALSE);
            eState := PRESSURIZING;
        ELSIF fbTimerPriming.Q AND fInletPressure <= 2.0 THEN
            eState := FAULT;
        END_IF

    PRESSURIZING:
        bHighPressurePumpCmd := TRUE;
        fbTimerRampUp(IN := TRUE, PT := T#30S);
        // Ramp ERD Speed
        IF fERDSpeedCmd < fTargetERDSpeed THEN
            fERDSpeedCmd := fERDSpeedCmd + 0.1;
        END_IF

        IF fbTimerRampUp.Q THEN
            fbTimerRampUp(IN := FALSE);
            bPermeateValve := TRUE;
            eState := RUNNING;
        END_IF

    RUNNING:
        IF bStopCmd THEN
            eState := SHUTDOWN;
        END_IF
        // ERD closed loop placeholder
        IF fBrinePressure > 65.0 THEN
            fERDSpeedCmd := fERDSpeedCmd + 0.1;
        ELSIF fBrinePressure < 55.0 THEN
            fERDSpeedCmd := fERDSpeedCmd - 0.1;
        END_IF

    SHUTDOWN:
        bHighPressurePumpCmd := FALSE;
        fERDSpeedCmd := 0.0;
        bPermeateValve := FALSE;
        // Wait for pressure to drop before stopping feed pump
        IF fBrinePressure < 5.0 THEN
            bFeedPumpCmd := FALSE;
            eState := STANDBY;
        END_IF

    FAULT:
        bFeedPumpCmd := FALSE;
        bHighPressurePumpCmd := FALSE;
        fERDSpeedCmd := 0.0;
        bPermeateValve := FALSE;
        IF bResetCmd THEN
            eState := INIT;
        END_IF
END_CASE
