PROGRAM Sewage_Lift_Station
VAR
    Level_Wet_Well : REAL;
    SP_Lead_Start : REAL := 60.0;
    SP_Lag_Start : REAL := 75.0;
    SP_Standby_Start : REAL := 85.0;
    SP_All_Stop : REAL := 30.0;
    Pump1_Run, Pump2_Run, Pump3_Run : BOOL;
    Sequence_Step : INT := 1;
    Pumps_Required : INT := 0;
END_VAR

IF Level_Wet_Well <= SP_All_Stop THEN
    Pumps_Required := 0;
ELSIF Level_Wet_Well >= SP_Standby_Start THEN
    Pumps_Required := 3;
ELSIF Level_Wet_Well >= SP_Lag_Start THEN
    Pumps_Required := 2;
ELSIF Level_Wet_Well >= SP_Lead_Start THEN
    Pumps_Required := 1;
END_IF;

IF Pumps_Required = 0 THEN
    IF Pump1_Run OR Pump2_Run OR Pump3_Run THEN
        Sequence_Step := Sequence_Step + 1;
        IF Sequence_Step > 3 THEN Sequence_Step := 1; END_IF;
    END_IF;
    Pump1_Run := FALSE; Pump2_Run := FALSE; Pump3_Run := FALSE;
END_IF;

IF Pumps_Required >= 1 THEN
    CASE Sequence_Step OF
        1: Pump1_Run := TRUE;
        2: Pump2_Run := TRUE;
        3: Pump3_Run := TRUE;
    END_CASE;
END_IF;
IF Pumps_Required >= 2 THEN
    CASE Sequence_Step OF
        1: Pump2_Run := TRUE;
        2: Pump3_Run := TRUE;
        3: Pump1_Run := TRUE;
    END_CASE;
END_IF;
IF Pumps_Required = 3 THEN
    Pump1_Run := TRUE; Pump2_Run := TRUE; Pump3_Run := TRUE;
END_IF;
END_PROGRAM

PROGRAM Sewage_Lift_Station_PID
VAR
    Level_Wet_Well, Flow_Rate : REAL;
    SP_Lead_Start : REAL := 60.0;
    SP_Lag_Start : REAL := 75.0;
    SP_All_Stop : REAL := 30.0;
    SP_Flow : REAL := 500.0;
    Pump1_Cmd, Pump2_Cmd, Pump3_Cmd : BOOL;
    Pump1_Speed, Pump2_Speed, Pump3_Speed : REAL;
    Sequence_Step : INT := 1;
    Pumps_Required : INT := 0;
    PID_Out : REAL;
    PID_Inst : PID;
END_VAR

PID_Inst(Enable := (Pumps_Required > 0), SP := SP_Flow, PV := Flow_Rate, Kp := 1.5, Ki := 0.2, Kd := 0.0);
PID_Out := PID_Inst.CV;

IF Level_Wet_Well <= SP_All_Stop THEN
    Pumps_Required := 0;
    IF Pump1_Cmd THEN Sequence_Step := (Sequence_Step MOD 3) + 1; END_IF;
ELSIF Level_Wet_Well >= SP_Lag_Start THEN Pumps_Required := 2;
ELSIF Level_Wet_Well >= SP_Lead_Start THEN Pumps_Required := 1;
END_IF;

Pump1_Cmd := FALSE; Pump2_Cmd := FALSE; Pump3_Cmd := FALSE;
Pump1_Speed := 0.0; Pump2_Speed := 0.0; Pump3_Speed := 0.0;

IF Pumps_Required >= 1 THEN
    IF Sequence_Step = 1 THEN Pump1_Cmd := TRUE; Pump1_Speed := PID_Out;
    ELSIF Sequence_Step = 2 THEN Pump2_Cmd := TRUE; Pump2_Speed := PID_Out;
    ELSE Pump3_Cmd := TRUE; Pump3_Speed := PID_Out; END_IF;
END_IF;

IF Pumps_Required >= 2 THEN
    IF Sequence_Step = 1 THEN Pump2_Cmd := TRUE; Pump2_Speed := PID_Out;
    ELSIF Sequence_Step = 2 THEN Pump3_Cmd := TRUE; Pump3_Speed := PID_Out;
    ELSE Pump1_Cmd := TRUE; Pump1_Speed := PID_Out; END_IF;
END_IF;
END_PROGRAM

