    HIL_Mismatch := TRUE;
END_IF;

IF System_Hour = 2 AND NOT Self_Test_Active THEN
    Self_Test_Active := TRUE;
    Pump_Start_Cmd := TRUE;
END_IF;

IF Self_Test_Active AND System_Hour = 3 THEN
    Self_Test_Active := FALSE;
    Pump_Start_Cmd := FALSE;
END_IF;
END_PROGRAM

FUNCTION_BLOCK "Ozone_Control"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    O3_SetPoint : REAL;
    O3_Actual : REAL;
END_VAR
VAR_OUTPUT
    Generator_Enable : BOOL;
    Power_Scale_Out : REAL;
    System_Fault : BOOL;
END_VAR
VAR
    PID_Out : REAL;
    Run_Cmd : BOOL;
END_VAR

BEGIN
    // Start/Stop Logic
    IF Start AND NOT Stop THEN
        Run_Cmd := TRUE;
    ELSIF Stop THEN
        Run_Cmd := FALSE;
    END_IF;

    Generator_Enable := Run_Cmd;

    // Simple PID simulation for Power Scaling
    IF Run_Cmd THEN
        IF O3_Actual < O3_SetPoint THEN
            PID_Out := PID_Out + 1.0;
        ELSIF O3_Actual > O3_SetPoint THEN
            PID_Out := PID_Out - 1.0;
        END_IF;

        // Limit scaling
        IF PID_Out > 100.0 THEN PID_Out := 100.0; END_IF;
        IF PID_Out < 0.0 THEN PID_Out := 0.0; END_IF;

        Power_Scale_Out := PID_Out;
    ELSE
        Power_Scale_Out := 0.0;
        PID_Out := 0.0;
    END_IF;

    // Fault logic
    System_Fault := (O3_Actual > (O3_SetPoint + 5.0));
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Ozone_FeedGas_Control"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    O3_SetPoint : REAL;
    O3_Actual : REAL;
    Dew_Point : REAL;
    Compressor_1_Ok : BOOL;
    Compressor_2_Ok : BOOL;
END_VAR
VAR_OUTPUT
    Generator_Enable : BOOL;
    Power_Scale_Out : REAL;
    Compressor_1_Run : BOOL;
    Compressor_2_Run : BOOL;
    DewPoint_Alarm : BOOL;
    System_Fault : BOOL;
END_VAR
VAR
    Run_Cmd : BOOL;
    PID_Out : REAL;
    Duty_Cycle : BOOL;
END_VAR

BEGIN
    // Feed Gas Dew Point Monitoring (must be < -60 C)
    DewPoint_Alarm := Dew_Point > -60.0;

    // Start/Stop Logic
    IF Start AND NOT Stop AND NOT DewPoint_Alarm THEN
        Run_Cmd := TRUE;
    ELSIF Stop OR DewPoint_Alarm THEN
        Run_Cmd := FALSE;
    END_IF;

    // Compressor Sequencing (Lead/Lag)
    IF Run_Cmd THEN
        IF Compressor_1_Ok AND NOT Duty_Cycle THEN
            Compressor_1_Run := TRUE;
            Compressor_2_Run := FALSE;
        ELSIF Compressor_2_Ok AND Duty_Cycle THEN
            Compressor_2_Run := TRUE;
            Compressor_1_Run := FALSE;
        ELSE
            Compressor_1_Run := Compressor_1_Ok;
            Compressor_2_Run := Compressor_2_Ok;
        END_IF;
    ELSE
        Compressor_1_Run := FALSE;
        Compressor_2_Run := FALSE;
    END_IF;

    Generator_Enable := Run_Cmd AND (Compressor_1_Run OR Compressor_2_Run);

    // O3 Control Loop
    IF Generator_Enable THEN
        IF O3_Actual < O3_SetPoint THEN
            PID_Out := PID_Out + 0.5;
        ELSIF O3_Actual > O3_SetPoint THEN
            PID_Out := PID_Out - 0.5;
        END_IF;

        IF PID_Out > 100.0 THEN PID_Out := 100.0; END_IF;
        IF PID_Out < 0.0 THEN PID_Out := 0.0; END_IF;
        Power_Scale_Out := PID_Out;
    ELSE
        Power_Scale_Out := 0.0;
    END_IF;

    System_Fault := DewPoint_Alarm OR (NOT Compressor_1_Ok AND NOT Compressor_2_Ok);
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Ozone_Profinet_Diag"
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    O3_SetPoint : REAL;
    O3_Actual : REAL;
    Dew_Point : REAL;
    // Profinet Inputs
    VFD_Status_Word : WORD;
    VFD_Actual_Freq : REAL;
END_VAR
VAR_OUTPUT
    Generator_Enable : BOOL;
    Power_Scale_Out : REAL;
    // Profinet Outputs
    VFD_Control_Word : WORD;
    VFD_Freq_Setpoint : REAL;
    // Diagnostics
    Alarm_Critical : BOOL;
    Alarm_Warning : BOOL;
    Alarm_Code : INT;
END_VAR
VAR
    Run_Cmd : BOOL;
    VFD_Ready : BOOL;
    VFD_Fault : BOOL;
END_VAR

BEGIN
    // Decode Profinet VFD Status
    VFD_Ready := (VFD_Status_Word AND 16#0001) > 0;
    VFD_Fault := (VFD_Status_Word AND 16#0008) > 0;

    // Diagnostics & Alarm Prioritization
    Alarm_Critical := FALSE;
    Alarm_Warning := FALSE;
    Alarm_Code := 0;

    IF Dew_Point > -60.0 THEN
        Alarm_Critical := TRUE;
        Alarm_Code := 101;
    ELSIF VFD_Fault THEN
        Alarm_Critical := TRUE;
        Alarm_Code := 102;
    ELSIF O3_Actual > (O3_SetPoint * 1.2) THEN
        Alarm_Warning := TRUE;
        Alarm_Code := 201;
    END_IF;

    // System Control
    IF Start AND NOT Stop AND NOT Alarm_Critical AND VFD_Ready THEN
        Run_Cmd := TRUE;
    ELSIF Stop OR Alarm_Critical THEN
        Run_Cmd := FALSE;
    END_IF;

    // Encode Profinet VFD Control
    IF Run_Cmd THEN
        VFD_Control_Word := 16#047F; // Start and Ready
        VFD_Freq_Setpoint := 50.0; // Fixed nominal for demo
    ELSE
        VFD_Control_Word := 16#047E; // Stop
        VFD_Freq_Setpoint := 0.0;
    END_IF;

    Generator_Enable := Run_Cmd;

    // O3 Power Scaling
    IF Generator_Enable THEN
        Power_Scale_Out := O3_SetPoint - O3_Actual; // Proportional base
        IF Power_Scale_Out > 100.0 THEN Power_Scale_Out := 100.0; END_IF;
        IF Power_Scale_Out < 0.0 THEN Power_Scale_Out := 0.0; END_IF;
    ELSE
        Power_Scale_Out := 0.0;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Ozone_Cyber_Redundancy"
VAR_INPUT
    // Cyber & SCADA
    User_Role : INT; // 1=Operator, 2=Admin, 3=Maintenance
    SCADA_Heartbeat : INT;
    Partner_PLC_Active : BOOL;
    PLC_Is_Primary : BOOL;

    // Process Variables
    Start_Req : BOOL;
    Stop_Req : BOOL;
    O3_SetPoint : REAL;
    O3_Actual : REAL;
END_VAR
VAR_OUTPUT
    Control_Active : BOOL;
    Generator_Enable : BOOL;
    Power_Scale_Out : REAL;
    SCADA_Heartbeat_Echo : INT;
    Security_Lockout : BOOL;
    Comm_Loss : BOOL;
END_VAR
VAR
    Last_Heartbeat : INT;
    Heartbeat_Timer : INT;
    Run_Cmd : BOOL;
END_VAR

BEGIN
    // IEC 62443 Role-based Access Control (RBAC)
    IF User_Role < 1 THEN
        Security_Lockout := TRUE;
        Run_Cmd := FALSE;
    ELSE
        Security_Lockout := FALSE;
    END_IF;

    // SCADA Heartbeat Watchdog
    IF SCADA_Heartbeat <> Last_Heartbeat THEN
        Heartbeat_Timer := 0;
        Last_Heartbeat := SCADA_Heartbeat;
        Comm_Loss := FALSE;
    ELSE
        Heartbeat_Timer := Heartbeat_Timer + 1;
        IF Heartbeat_Timer > 100 THEN
            Comm_Loss := TRUE;
        END_IF;
    END_IF;
    SCADA_Heartbeat_Echo := SCADA_Heartbeat;

    // Redundant PLC Failover Logic
    Control_Active := PLC_Is_Primary OR NOT Partner_PLC_Active;

    IF Control_Active AND NOT Security_Lockout AND NOT Comm_Loss THEN
        IF Start_Req AND NOT Stop_Req THEN
            Run_Cmd := TRUE;
        ELSIF Stop_Req THEN
            Run_Cmd := FALSE;
        END_IF;
    ELSE
        Run_Cmd := FALSE;
    END_IF;

    Generator_Enable := Run_Cmd;

    IF Run_Cmd THEN
        Power_Scale_Out := 50.0 + (O3_SetPoint - O3_Actual) * 10.0;
        IF Power_Scale_Out > 100.0 THEN Power_Scale_Out := 100.0; END_IF;
        IF Power_Scale_Out < 0.0 THEN Power_Scale_Out := 0.0; END_IF;
    ELSE
        Power_Scale_Out := 0.0;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Ozone_Adversarial_Resilience"
VAR_INPUT
    Start_Req : BOOL;
    O3_Actual_Sensor1 : REAL;
    O3_Actual_Sensor2 : REAL;
    HIL_Twin_O3_Est : REAL;
    HIL_Sync_Pulse : BOOL;
END_VAR
VAR_OUTPUT
    System_Ready : BOOL;
    Self_Test_Active : BOOL;
    Sensor_Drift_Fault : BOOL;
    HIL_Desync_Fault : BOOL;
    Generator_Enable : BOOL;
END_VAR
VAR
    State : INT; // 0=Off, 1=SelfTest, 2=Running, 3=Fault
    O3_Moving_Avg1 : REAL;
    O3_Moving_Avg2 : REAL;
    Test_Timer : INT;
END_VAR

BEGIN
    // Sensor Drift Detection (Moving Average Deviation)
    O3_Moving_Avg1 := O3_Moving_Avg1 * 0.9 + O3_Actual_Sensor1 * 0.1;
    O3_Moving_Avg2 := O3_Moving_Avg2 * 0.9 + O3_Actual_Sensor2 * 0.1;

    IF ABS(O3_Moving_Avg1 - O3_Moving_Avg2) > 2.0 THEN
        Sensor_Drift_Fault := TRUE;
    ELSE
        Sensor_Drift_Fault := FALSE;
    END_IF;

    // HIL Digital Twin Sync Check
    IF ABS(O3_Moving_Avg1 - HIL_Twin_O3_Est) > 5.0 THEN
        HIL_Desync_Fault := TRUE;
    ELSE
        HIL_Desync_Fault := FALSE;
    END_IF;

    // State Machine with Pre-startup Self-Test
    CASE State OF
        0: // OFF
            System_Ready := FALSE;
            Generator_Enable := FALSE;
            Self_Test_Active := FALSE;
            IF Start_Req AND NOT Sensor_Drift_Fault THEN
                State := 1;
                Test_Timer := 0;
            END_IF;

        1: // SELF TEST
            Self_Test_Active := TRUE;
            Test_Timer := Test_Timer + 1;
            // Simulate checking valves, comms, I/O
            IF Test_Timer > 50 THEN
                Self_Test_Active := FALSE;
                System_Ready := TRUE;
                State := 2;
            END_IF;
            IF Sensor_Drift_Fault OR HIL_Desync_Fault THEN
                State := 3;
            END_IF;

        2: // RUNNING
            Generator_Enable := TRUE;
            IF NOT Start_Req OR Sensor_Drift_Fault OR HIL_Desync_Fault THEN
                State := 0;
            END_IF;

        3: // FAULT
            Generator_Enable := FALSE;
            System_Ready := FALSE;
            IF NOT Start_Req THEN
                State := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK

