    rTargetTorque       : REAL := 5.0;
    rActualTorque       : REAL;
    bCapperDown         : BOOL;
    bCapAppliedOk       : BOOL;
    bRejectGate         : BOOL;
END_VAR

IF bEmergencyStop THEN
    eState := STOPPED;
    bPumpActive := FALSE;
    bFillerValveOpen := FALSE;
    bConveyorActive := FALSE;
    bCapSorterActive := FALSE;
    bCapperDown := FALSE;
