        bFillerValveOpen := FALSE;
        bConveyorActive := FALSE;
        bCapSorterActive := FALSE;
        bCapperDown := FALSE;
        IF bStartProcess AND NOT bCIPMode THEN
            eState := PRODUCTION;
        ELSIF bStartProcess AND bCIPMode THEN
            eState := CIP_INIT;
