    nEcSlaveState   AT %I* : ARRAY[1..10] OF WORD;
    bEcNetworkOk        : BOOL;
    i                   : INT;
    nFaultCode          : INT;
END_VAR

bEcNetworkOk := (stEcMasterState = 16#0008);
