FUNCTION_BLOCK "WetBench_Temp_Interlock"
VAR_INPUT
    bStart_Process : Bool;
    bStop_Process : Bool;
    bWafer_Present : Bool;
    bExhaust_Running : Bool;
    rTemp_PV : Real;
    rRinse_Time_SP : Time;
END_VAR
VAR_OUTPUT
    bHF_Valve : Bool;
    bDI_Valve : Bool;
    bDrain_Valve : Bool;
    rHeater_Output : Real;
    bProcess_Complete : Bool;
    bError_Interlock : Bool;
    iState : Int;
END_VAR
VAR
    tTimer : TON;
    PID_Temp : PID_Compact;
END_VAR

BEGIN
    // PID Temperature Control
    PID_Temp(Setpoint := 25.0,
             Input := rTemp_PV,
             Output => rHeater_Output);

    // Interlock Check
    IF NOT bExhaust_Running THEN
        bError_Interlock := TRUE;
        iState := 99; // Error state
    ELSE
        bError_Interlock := FALSE;
    END_IF;

    IF bStop_Process THEN
        iState := 0;
    END_IF;

    CASE iState OF
        0: // Idle
            bHF_Valve := FALSE;
            bDI_Valve := FALSE;
            bDrain_Valve := TRUE;
            bProcess_Complete := FALSE;
            IF bStart_Process AND bWafer_Present AND NOT bError_Interlock THEN
                iState := 10;
                bDrain_Valve := FALSE;
            END_IF;

        10: // HF Dosing
            bHF_Valve := TRUE;
            tTimer(IN:=TRUE, PT:=T#30s);
            IF tTimer.Q THEN
                bHF_Valve := FALSE;
                tTimer(IN:=FALSE, PT:=T#30s);
                iState := 20;
            END_IF;

        20: // DI Rinse
            bDI_Valve := TRUE;
            bDrain_Valve := TRUE;
            tTimer(IN:=TRUE, PT:=rRinse_Time_SP);
            IF tTimer.Q THEN
                bDI_Valve := FALSE;
                tTimer(IN:=FALSE, PT:=rRinse_Time_SP);
                iState := 30;
            END_IF;

        30: // Complete
            bProcess_Complete := TRUE;
            bDrain_Valve := TRUE;
            IF NOT bStart_Process THEN
                iState := 0;
            END_IF;

        99: // Error handling
            bHF_Valve := FALSE;
            bDI_Valve := FALSE;
            bDrain_Valve := TRUE;
            IF bExhaust_Running AND NOT bStart_Process THEN
                iState := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
