PROGRAM Cleanroom_HVAC_M1
VAR
    // Inputs
    Room_Pressure : REAL;
    Target_Pressure : REAL := 15.0;
    HEPA_Diff_Pressure : REAL;
    HEPA_Max_DP : REAL := 500.0;
    Supply_Fan_Start : BOOL;

    // Depth: Temp & Humidity
    Room_Temp : REAL;
    Target_Temp : REAL := 21.0;
    Room_Humidity : REAL;
    Target_Humidity : REAL := 45.0;

    // Outputs
    Supply_Fan_Run : BOOL;
    Supply_Fan_Speed : REAL;
    Cooling_Valve : REAL; // 0-100%
    Heating_Valve : REAL; // 0-100%
    Humidifier : REAL;    // 0-100%

    HEPA_Alarm : BOOL;
    Pressure_Alarm : BOOL;

    // PIDs
    PID_Pressure : PID;
    PID_Temp : PID;
    PID_Humidity : PID;
END_VAR

// HEPA Filter Monitoring
HEPA_Alarm := (HEPA_Diff_Pressure >= HEPA_Max_DP);

// Pressure Control
IF Supply_Fan_Start AND NOT HEPA_Alarm THEN
    Supply_Fan_Run := TRUE;

    // Cascading Pressure PID
    PID_Pressure.PV := Room_Pressure;
    PID_Pressure.SP := Target_Pressure;
    PID_Pressure();
    Supply_Fan_Speed := PID_Pressure.CV;

    // Temperature PID
    PID_Temp.PV := Room_Temp;
    PID_Temp.SP := Target_Temp;
    PID_Temp();

    // Humidity PID
    PID_Humidity.PV := Room_Humidity;
    PID_Humidity.SP := Target_Humidity;
    PID_Humidity();

    // Dehumidification & Reheat logic
    IF Room_Humidity > Target_Humidity + 5.0 THEN
        // Overcool to dehumidify
        Cooling_Valve := PID_Humidity.CV; 
        Heating_Valve := PID_Temp.CV; // Reheat
        Humidifier := 0.0;
    ELSE
        Cooling_Valve := MAX(0.0, -PID_Temp.CV);
        Heating_Valve := MAX(0.0, PID_Temp.CV);
        Humidifier := MAX(0.0, PID_Humidity.CV);
    END_IF;

ELSE
    Supply_Fan_Run := FALSE;
    Supply_Fan_Speed := 0.0;
    Cooling_Valve := 0.0;
    Heating_Valve := 0.0;
    Humidifier := 0.0;
END_IF;

Pressure_Alarm := ABS(Room_Pressure - Target_Pressure) > 5.0;
END_PROGRAM
