```pascal
PROGRAM Cleanroom_HVAC_M4
VAR
    // Core Inputs
    Room_Pressure : REAL;
    Room_Pressure_Raw : ARRAY[0..9] OF REAL; // Rolling buffer
    Target_Pressure : REAL := 15.0;
    HEPA_DP : REAL;

    // Adversarial: Drift, HIL, Self-Test
    Sensor_Drift_Alarm : BOOL;
    HIL_Mode_Active : BOOL;
    HIL_Room_Pressure : REAL; // Twin injected value

    Self_Test_Active : BOOL;
    Self_Test_Step : INT := 0;
    Self_Test_Passed : BOOL;

    Sys_Start_Cmd : BOOL;
    Fan_Cmd : BOOL;
    Fan_Speed : REAL;

    // Internal
    i : INT;
    Sum_Pressure : REAL;
    Avg_Pressure : REAL;

    PID_Pressure : PID;
END_VAR

// Digital Twin Sync
IF HIL_Mode_Active THEN
    Room_Pressure := HIL_Room_Pressure; // Use injected value
END_IF;

// Sensor Drift Detection (Rolling Average)
Sum_Pressure := 0.0;
FOR i := 0 TO 8 DO
    Room_Pressure_Raw[i] := Room_Pressure_Raw[i+1];
    Sum_Pressure := Sum_Pressure + Room_Pressure_Raw[i];
END_FOR;
Room_Pressure_Raw[9] := Room_Pressure;
Sum_Pressure := Sum_Pressure + Room_Pressure_Raw[9];
Avg_Pressure := Sum_Pressure / 10.0;

IF ABS(Room_Pressure - Avg_Pressure) > 2.0 THEN
    Sensor_Drift_Alarm := TRUE;
ELSE
    Sensor_Drift_Alarm := FALSE;
END_IF;

// Startup Self-Test Routine
IF Sys_Start_Cmd AND NOT Self_Test_Passed THEN
    Self_Test_Active := TRUE;
    CASE Self_Test_Step OF
        0: // Check Sensors
            IF NOT Sensor_Drift_Alarm THEN Self_Test_Step := 1; END_IF;
        1: // Bump Fan
            Fan_Cmd := TRUE;
            Fan_Speed := 10.0;
            // Wait for DP to rise (timer omitted for brevity)
            IF Room_Pressure > 5.0 THEN 
                Self_Test_Step := 2;
                Self_Test_Passed := TRUE;
                Self_Test_Active := FALSE;
            END_IF;
    END_CASE;
END_IF;

// Normal Operation
IF Sys_Start_Cmd AND Self_Test_Passed AND NOT Self_Test_Active THEN
    Fan_Cmd := TRUE;
    PID_Pressure.PV := Room_Pressure;
    PID_Pressure.SP := Target_Pressure;
    PID_Pressure();
    Fan_Speed := PID_Pressure.CV;
ELSIF NOT Self_Test_Active THEN
    Fan_Cmd := FALSE;
    Fan_Speed := 0.0;
    Self_Test_Passed := FALSE;
    Self_Test_Step := 0;
END_IF;

END_PROGRAM
