PROGRAM MAIN
VAR
    bStart : BOOL;
    bStop : BOOL;
    bReset : BOOL;

    nState : INT; // 0: Idle, 1: Accel, 2: Run, 3: Discharge, 4: Decel, 5: Fault
    fSpeed : LREAL;
    fTargetSpeed : LREAL := 3000.0;

    fVibrationLevel : LREAL;
    fVibWarningLimit : LREAL := 5.0; // mm/s
    fVibAlarmLimit : LREAL := 8.0; // mm/s
    bVibWarning : BOOL;
    bVibAlarm : BOOL;

    tRunTime : TON;
    tDischargeInterval : TIME := T#10M;
    tDischargeDuration : TON;
    bDischargeValve : BOOL;
END_VAR

// Vibration Monitoring Envelope
bVibWarning := fVibrationLevel > fVibWarningLimit;
IF fVibrationLevel > fVibAlarmLimit THEN
    bVibAlarm := TRUE;
    nState := 5; // Trigger Fault
END_IF

CASE nState OF
    0: // Idle
        bDischargeValve := FALSE;
        fSpeed := 0.0;
        IF bStart AND NOT bVibAlarm THEN
            nState := 1;
        END_IF

    1: // Accel
        fSpeed := fSpeed + 5.0;
        IF fSpeed >= fTargetSpeed THEN
            fSpeed := fTargetSpeed;
            nState := 2;
            tRunTime(IN := FALSE);
        END_IF

    2: // Run
        tRunTime(IN := TRUE, PT := tDischargeInterval);
        IF tRunTime.Q THEN
            nState := 3; // Start Discharge
        END_IF
        IF bStop THEN
            nState := 4;
        END_IF

    3: // Discharge
        bDischargeValve := TRUE;
        tDischargeDuration(IN := TRUE, PT := T#5S);
        IF tDischargeDuration.Q THEN
            bDischargeValve := FALSE;
            tDischargeDuration(IN := FALSE);
            tRunTime(IN := FALSE);
            nState := 2; // Return to Run
        END_IF

    4: // Decel
        fSpeed := fSpeed - 5.0;
        IF fSpeed <= 0.0 THEN
            fSpeed := 0.0;
            nState := 0;
        END_IF

    5: // Fault
        fSpeed := fSpeed - 15.0; // Rapid decel
        bDischargeValve := FALSE;
        IF fSpeed <= 0.0 THEN
            fSpeed := 0.0;
        END_IF
        IF bReset AND fVibrationLevel < fVibWarningLimit THEN
            bVibAlarm := FALSE;
            nState := 0;
        END_IF
END_CASE

PROGRAM MAIN
VAR
    bStart, bStop, bReset : BOOL;
    nState : INT;
    fSpeed, fTargetSpeed : LREAL := 3000.0;

    // Vibration & Envelopes
    fVibAmp : LREAL; // Amplitude mm/s
    fVibPhase : LREAL; // Phase degrees
    fVibWarningLimit : LREAL := 5.0;
    fVibAlarmLimit : LREAL := 8.0;
    bVibAlarm : BOOL;

    // Sludge Discharge
    tRunTime : TON;
    tDischargeDuration : TON;
    bDischargeValve : BOOL;

    // Dynamic Unbalance Compensation
    bFluidInjectionActive : BOOL;
    fInjectionVolume : LREAL;
    nInjectionChamber : INT; // 1 to 4 based on quadrant
END_VAR

// Vibration Monitoring
IF fVibAmp > fVibAlarmLimit THEN
    bVibAlarm := TRUE;
    nState := 5;
END_IF

// Dynamic Unbalance Compensation Logic
IF fVibAmp > 2.0 AND fVibAmp <= fVibWarningLimit AND nState = 2 THEN
    bFluidInjectionActive := TRUE;
    // Determine chamber based on phase angle (0-360)
    IF fVibPhase >= 0.0 AND fVibPhase < 90.0 THEN nInjectionChamber := 3;
    ELSIF fVibPhase >= 90.0 AND fVibPhase < 180.0 THEN nInjectionChamber := 4;
    ELSIF fVibPhase >= 180.0 AND fVibPhase < 270.0 THEN nInjectionChamber := 1;
    ELSE nInjectionChamber := 2;
    END_IF
    fInjectionVolume := fVibAmp * 0.5; // Proportional injection
ELSE
    bFluidInjectionActive := FALSE;
    fInjectionVolume := 0.0;
END_IF

CASE nState OF
    0: // Idle
        IF bStart AND NOT bVibAlarm THEN nState := 1; END_IF
    1: // Accel
        fSpeed := fSpeed + 10.0;
        IF fSpeed >= fTargetSpeed THEN nState := 2; tRunTime(IN:=FALSE); END_IF
    2: // Run
        tRunTime(IN := TRUE, PT := T#10M);
        IF tRunTime.Q THEN nState := 3; END_IF
        IF bStop THEN nState := 4; END_IF
    3: // Discharge
        bDischargeValve := TRUE;
        tDischargeDuration(IN := TRUE, PT := T#5S);
        IF tDischargeDuration.Q THEN
            bDischargeValve := FALSE;
            tDischargeDuration(IN := FALSE);
            tRunTime(IN := FALSE);
            nState := 2;
        END_IF
    4: // Decel
        fSpeed := fSpeed - 10.0;
        IF fSpeed <= 0.0 THEN nState := 0; END_IF
    5: // Fault
        fSpeed := fSpeed - 20.0;
        bDischargeValve := FALSE;
        IF bReset AND fVibAmp < fVibWarningLimit THEN
            bVibAlarm := FALSE;
            nState := 0;
        END_IF
END_CASE

