    ELSE bFluidInjectionValve[2] := TRUE;
    END_IF
END_IF

CASE nState OF
    0: // Idle
        bDriveEnable := FALSE;
        IF bStart AND NOT bVibAlarm THEN nState := 1; END_IF
    1: // Accel
        bDriveEnable := TRUE;
        fSpeedSetpoint := fSpeedSetpoint + 10.0;
        IF fSpeedFeedback >= fTargetSpeed * 0.98 THEN nState := 2; END_IF
    2: // Run
