   VAR 
      State : Int;
      TestTimer : "TON";
      TempArray : ARRAY[1..10] OF Real;
      TempIndex : Int := 1;
      TempSum : Real;
      TempAvg : Real;
   END_VAR

BEGIN
   #TempSum := #TempSum - #TempArray[#TempIndex] + #TempZ1_PV;
   #TempArray[#TempIndex] := #TempZ1_PV;
   #TempIndex := #TempIndex + 1;
   IF #TempIndex > 10 THEN #TempIndex := 1; END_IF;
   #TempAvg := #TempSum / 10.0;

   #DigTwin_Out.SyncError := ABS(#TempAvg - #DigTwin_In.SimTempZ1);
   IF #DigTwin_Out.SyncError > 5.0 THEN
      #DriftAlarm := TRUE;
