### Main Program (`PRG_FluidBedDryer`)
```pascal
PROGRAM PRG_FluidBedDryer
VAR
    // I/O
    bStart          : BOOL;
    bStop           : BOOL;
    fInletTemp      : LREAL;
    fExhaustHumid   : LREAL;
    bHeaterOn       : BOOL;
    fHeaterCmd      : LREAL;
    bBlowerOn       : BOOL;

    // Setpoints
    fTempSetpoints  : ARRAY[1..3] OF LREAL := [40.0, 60.0, 80.0];
    tProfileTimes   : ARRAY[1..3] OF TIME := [T#5M, T#10M, T#15M];
    fTargetHumid    : LREAL := 15.0;

    // State & Control
    nState          : INT := 0;
    nProfileStep    : INT := 1;
    fbTimer         : TON;
    fbPID_Temp      : FB_BasicPID;
END_VAR

CASE nState OF
    0: // IDLE
        bHeaterOn := FALSE;
        bBlowerOn := FALSE;
        nProfileStep := 1;
        IF bStart THEN nState := 1; END_IF

    1: // HEATING
        bBlowerOn := TRUE;
        bHeaterOn := TRUE;
        fbPID_Temp(fSetpoint:=fTempSetpoints[nProfileStep], fActual:=fInletTemp, bEnable:=TRUE, fOut=>fHeaterCmd);

        fbTimer(IN:=TRUE, PT:=tProfileTimes[nProfileStep]);
        IF fbTimer.Q THEN
            fbTimer(IN:=FALSE);
            IF nProfileStep < 3 THEN nProfileStep := nProfileStep + 1;
            ELSE nState := 2; END_IF
        END_IF

    2: // DRYING
        bBlowerOn := TRUE;
        bHeaterOn := TRUE;
        fbPID_Temp(fSetpoint:=fTempSetpoints[3], fActual:=fInletTemp, bEnable:=TRUE, fOut=>fHeaterCmd);

        IF fExhaustHumid <= fTargetHumid THEN nState := 3; END_IF

    3: // COOLING
        bHeaterOn := FALSE;
        bBlowerOn := TRUE;
        IF fInletTemp < 30.0 THEN nState := 4; END_IF

    4: // DONE
        bBlowerOn := FALSE;
        IF NOT bStart THEN nState := 0; END_IF
END_CASE

IF bStop THEN nState := 0; END_IF
```

