FUNCTION_BLOCK "FB_Autoclave_Cure_M4"
TITLE = 'Autoclave with Adversarial Conditions & Digital Twin'
VERSION : '2.0'

VAR_INPUT
    bStart_Cycle : Bool;
    rAct_Temp_Array : ARRAY[1..3] OF Real; // TMR (Triple Modular Redundancy)
    rHIL_Twin_Temp : Real; // HIL Digital Twin Input
    rAct_Pressure : Real;
    rAct_N2_Level : Real;
    rAct_Vac_Pressure : Real;
    wPN_Device_Status : Word;
    iUser_Role : Int; // IEC 62443 RBAC
    bSCADA_Override : Bool;
END_VAR

VAR_OUTPUT
    bCmd_Heater : Bool;
    bCmd_PressValve : Bool;
    bCmd_N2_Purge : Bool;
    bCmd_Vac_Pump : Bool;
    bAlarm_Abort : Bool;
    wDiag_Code : Word;
    iSCADA_State_Tag : Int;
    bCyberSec_Alarm : Bool;
    bDrift_Alarm : Bool;
    bTwin_Desync_Alarm : Bool;
    bSelf_Test_Pass : Bool;
END_VAR

VAR
    iState : Int;
    tDwell_Timer : TON_TIME;
    rAvg_Temp : Real;
    i : Int;
    iDrift_Count : Int;
END_VAR

BEGIN
    // Pre-flight Self Test
    IF iState = 0 AND bStart_Cycle THEN
        IF rAct_Temp_Array[1] > -50.0 AND rAct_Temp_Array[1] < 500.0 THEN
            bSelf_Test_Pass := TRUE;
            iState := 5; // Ready State
        ELSE
            bSelf_Test_Pass := FALSE;
            wDiag_Code := 16#A001; // Self-test failed
            RETURN;
        END_IF;
    END_IF;

    // Sensor Drift Detection Algorithm (Triple Modular Redundancy)
    rAvg_Temp := (rAct_Temp_Array[1] + rAct_Temp_Array[2] + rAct_Temp_Array[3]) / 3.0;
    iDrift_Count := 0;
    FOR i := 1 TO 3 DO
        IF ABS(rAct_Temp_Array[i] - rAvg_Temp) > 2.5 THEN
            iDrift_Count := iDrift_Count + 1;
        END_IF;
    END_FOR;
    bDrift_Alarm := (iDrift_Count > 0);

    // HIL Digital Twin Synchronization Check
    IF (iState > 0) AND (ABS(rAvg_Temp - rHIL_Twin_Temp) > 10.0) THEN
        bTwin_Desync_Alarm := TRUE;
        wDiag_Code := 16#A002; // Digital Twin Desync
        iState := 99;
    ELSE
        bTwin_Desync_Alarm := FALSE;
    END_IF;

    // IEC 62443 RBAC
    IF (iUser_Role < 3) AND NOT bSCADA_Override THEN
        bCyberSec_Alarm := TRUE;
        wDiag_Code := 16#C001;
        iState := 99;
    ELSE
        bCyberSec_Alarm := FALSE;
    END_IF;

    // State Machine
    CASE iState OF
        5: // Ready
            iState := 10;
        10: // Purge & Vacuum
            bCmd_N2_Purge := TRUE;
            bCmd_Vac_Pump := TRUE;
            IF (rAct_N2_Level > 95.0) AND (rAct_Vac_Pressure < 0.1) THEN
                bCmd_N2_Purge := FALSE;
                iState := 20;
            END_IF;
        20: // Heat & Pressurize
            bCmd_Heater := (rAvg_Temp < 180.0);
            bCmd_PressValve := (rAct_Pressure < 7.0);
            IF (rAvg_Temp >= 180.0) AND (rAct_Pressure >= 7.0) THEN iState := 30; END_IF;
        30: // Dwell
            tDwell_Timer(IN := TRUE, PT := T#120M);
            bCmd_Heater := (rAvg_Temp < 180.0);
            IF tDwell_Timer.Q THEN
                bCmd_Heater := FALSE;
                bCmd_PressValve := FALSE;
                iState := 40;
            END_IF;
        40: // Cool
            bCmd_Vac_Pump := FALSE;
            IF rAvg_Temp < 50.0 THEN iState := 0; tDwell_Timer(IN := FALSE, PT := T#0S); END_IF;
        99: // Abort
            bCmd_Heater := FALSE;
            bCmd_PressValve := FALSE;
            bAlarm_Abort := TRUE;
    END_CASE;

    iSCADA_State_Tag := iState;
END_FUNCTION_BLOCK
