    DriftAlarm  : BOOL;
END_STRUCT
END_TYPE

PROGRAM MAIN
VAR
    ScadaData     : ST_SCADA_Data;
    UserRoleID    : INT; 
    HeartbeatIn   AT %I* : BOOL;
    HeartbeatOut  AT %Q* : BOOL;
    fbHeartbeatTimer : TON;
    bPrimaryActive   : BOOL := TRUE;
    ThrustSensorX : REAL;
    ThrustSensorY : REAL;
    ThrustSensorZ : REAL;
    FuelFlowAct   : REAL;
    EGT_Zones     : ARRAY[1..4] OF REAL;
    EcMasterState    AT %I* : UINT;
    EcSlaveStates    AT %I* : ARRAY[1..10] OF UINT;
    EcWcState        AT %I* : BOOL;
    HIL_ThrustPredictedX : REAL;
    HIL_ThrustPredictedY : REAL;
    HIL_ThrustPredictedZ : REAL;
    MaxDriftTolerance    : REAL := 15.0;
    bDriftDetected       : BOOL := FALSE;
    bStartSelfTest : BOOL;
    nTestStep      : INT := 0;
    fbTestTimer    : TON;
    bTestPassed    : BOOL := FALSE;
    FuelFlowSetRequest : REAL;
    FuelFlowSet   : REAL := 0.0;
    EGTCriticalLimit : REAL := 950.0;
    FuelValveCmd  : REAL;
    bEmergencyShutoff : BOOL := FALSE;
    bSystemAlarm      : BOOL := FALSE;
    bDegradedMode     : BOOL := FALSE;
    bEnable : BOOL := FALSE;
    fbFuelPID : FB_BasicPID;
    i : INT;
    SumEGT : REAL;
END_VAR

HeartbeatOut := NOT HeartbeatOut;
fbHeartbeatTimer(IN := HeartbeatIn, PT := T#500MS);
bPrimaryActive := NOT fbHeartbeatTimer.Q;

IF UserRoleID = 2 THEN FuelFlowSet := FuelFlowSetRequest; END_IF

IF NOT bPrimaryActive THEN RETURN; END_IF

IF bStartSelfTest THEN
    CASE nTestStep OF
        0:
            FuelFlowSet := 0.0;
            FuelValveCmd := 0.0;
            nTestStep := 1;
            fbTestTimer(IN:=FALSE);
        1:
            FuelValveCmd := 10.0;
            fbTestTimer(IN:=TRUE, PT:=T#2S);
            IF fbTestTimer.Q THEN
                IF FuelFlowAct > 0.5 AND FuelFlowAct < 2.0 THEN
                    nTestStep := 2;
                    fbTestTimer(IN:=FALSE);
                ELSE
                    nTestStep := 99;
                END_IF
            END_IF
        2:
            FuelValveCmd := 0.0;
            fbTestTimer(IN:=TRUE, PT:=T#2S);
            IF fbTestTimer.Q THEN
                IF FuelFlowAct < 0.1 THEN
                    bTestPassed := TRUE;
                    bStartSelfTest := FALSE;
                    bEnable := TRUE;
                    nTestStep := 0;
                ELSE
                    nTestStep := 99;
                END_IF
            END_IF
        99:
            bTestPassed := FALSE;
            bStartSelfTest := FALSE;
            bEnable := FALSE;
            nTestStep := 0;
    END_CASE
    RETURN;
END_IF

IF NOT bTestPassed THEN RETURN; END_IF

bSystemAlarm := (EcMasterState <> 8 OR EcWcState);
bDegradedMode := bSystemAlarm;
FOR i := 1 TO 10 DO
    IF EcSlaveStates[i] <> 8 THEN
        bSystemAlarm := TRUE; bDegradedMode := TRUE;
    END_IF
END_FOR

IF bDegradedMode THEN FuelFlowSet := MIN(FuelFlowSet, 5.0); END_IF

IF ABS(ThrustSensorX - HIL_ThrustPredictedX) > MaxDriftTolerance OR
   ABS(ThrustSensorY - HIL_ThrustPredictedY) > MaxDriftTolerance OR
   ABS(ThrustSensorZ - HIL_ThrustPredictedZ) > MaxDriftTolerance THEN
    bDriftDetected := TRUE;
    bDegradedMode := TRUE;
ELSE
    bDriftDetected := FALSE;
END_IF

SumEGT := 0.0;
bEmergencyShutoff := FALSE;
FOR i := 1 TO 4 DO
    SumEGT := SumEGT + EGT_Zones[i];
    IF EGT_Zones[i] > EGTCriticalLimit THEN bEmergencyShutoff := TRUE; END_IF
END_FOR
ScadaData.EGTAverage := SumEGT / 4.0;

IF bEmergencyShutoff THEN
    bEnable := FALSE;
    FuelValveCmd := 0.0;
    FuelFlowSet := 0.0;
END_IF

ScadaData.TotalThrust := SQRT(EXPT(ThrustSensorX, 2) + EXPT(ThrustSensorY, 2) + EXPT(ThrustSensorZ, 2));
ScadaData.FuelFlowAct := FuelFlowAct;
ScadaData.AlarmActive := bSystemAlarm OR bEmergencyShutoff;
ScadaData.DriftAlarm := bDriftDetected;

IF bEmergencyShutoff THEN ScadaData.SystemState := 'SHUTDOWN';
ELSIF bDegradedMode THEN ScadaData.SystemState := 'DEGRADED';
ELSE ScadaData.SystemState := 'RUNNING'; END_IF

fbFuelPID(
    fSetpointValue := FuelFlowSet,
    fActualValue   := FuelFlowAct,
    bReset         := NOT bEnable,
    fCtrlCycleTime := 0.01,
    fKp := 2.5, fTn := 1.2, fTv := 0.05, fTd := 0.05,
    fCtrlOutput    => FuelValveCmd
);

IF bEnable THEN
    IF FuelValveCmd > 100.0 THEN FuelValveCmd := 100.0;
    ELSIF FuelValveCmd < 0.0 THEN FuelValveCmd := 0.0; END_IF
END_IF
