Here is a Siemens SCL (Structured Control Language) program for a Pharmaceutical API assembly line controlling micro-dosing scales and visual defect rejection logic. It uses a state machine for the dosing process and evaluates camera signals for rejection.

```pascal
FUNCTION_BLOCK "API_Dosing_Control"
VERSION : 0.1
   VAR_INPUT
      Start_Production : Bool;
      Stop_Production : Bool;
      Scale_Weight : Real; // Current weight from micro-dosing scale (mg)
      Target_Weight : Real; // Target dose (mg)
      Tolerance : Real; // Acceptable tolerance (+/- mg)
      Camera_Defect_Detected : Bool; // Signal from vision system
      Vial_Present : Bool; // Sensor detecting vial at dosing station
   END_VAR

   VAR_OUTPUT
      Dosing_Valve_Open : Bool; // Control for micro-dosing valve
      Reject_Pusher : Bool; // Control for pneumatic reject pusher
      Conveyor_Run : Bool; // Control for main conveyor
      System_Ready : Bool;
      System_Fault : Bool;
   END_VAR

   VAR
      State : Int;
      S_IDLE : Int := 0;
      S_CONVEYOR_MOVE : Int := 1;
      S_DOSING : Int := 2;
      S_INSPECTION : Int := 3;
      S_REJECT : Int := 4;
      S_FAULT : Int := 99;
   END_VAR

BEGIN
    // E-Stop / Stop logic
    IF Stop_Production THEN
        State := S_IDLE;
        Dosing_Valve_Open := FALSE;
        Reject_Pusher := FALSE;
        Conveyor_Run := FALSE;
        System_Ready := FALSE;
    END_IF;

    // State Machine
    CASE State OF
        S_IDLE:
            System_Ready := TRUE;
            Conveyor_Run := FALSE;
            Dosing_Valve_Open := FALSE;
            Reject_Pusher := FALSE;
            IF Start_Production THEN
                State := S_CONVEYOR_MOVE;
            END_IF;

        S_CONVEYOR_MOVE:
            System_Ready := TRUE;
            Conveyor_Run := TRUE;
            IF Vial_Present THEN
                Conveyor_Run := FALSE;
                State := S_DOSING;
            END_IF;

        S_DOSING:
            IF Scale_Weight < Target_Weight THEN
                Dosing_Valve_Open := TRUE;
            ELSE
                Dosing_Valve_Open := FALSE;
                State := S_INSPECTION;
            END_IF;

            // Fault if weight exceeds target + tolerance significantly during dosing
            IF Scale_Weight > (Target_Weight + (Tolerance * 2.0)) THEN
                Dosing_Valve_Open := FALSE;
                System_Fault := TRUE;
                State := S_FAULT;
            END_IF;

        S_INSPECTION:
            IF Camera_Defect_Detected OR 
               (Scale_Weight < (Target_Weight - Tolerance)) OR 
               (Scale_Weight > (Target_Weight + Tolerance)) THEN
                State := S_REJECT;
            ELSE
                State := S_CONVEYOR_MOVE; // Pass
            END_IF;

        S_REJECT:
            Reject_Pusher := TRUE;
            // Assuming a timer or sensor clears the pusher in a real system
            // For simplicity, we just trigger it and move on
            State := S_CONVEYOR_MOVE;

        S_FAULT:
            System_Fault := TRUE;
            Dosing_Valve_Open := FALSE;
            Conveyor_Run := FALSE;
            Reject_Pusher := FALSE;
            // Requires manual reset
    END_CASE;
END_FUNCTION_BLOCK
```

Here is the expanded Siemens SCL code integrating a CIP (Clean-In-Place) and SIP (Sterilization-In-Place) sequence, which is critical in pharmaceutical environments to prevent cross-contamination.

```pascal
FUNCTION_BLOCK "API_Dosing_CIP_SIP"
VERSION : 0.1
   VAR_INPUT
      Start_Production : Bool;
      Stop_Production : Bool;
      Start_CIP_SIP : Bool;
      Scale_Weight : Real;
      Target_Weight : Real;
      Tolerance : Real;
      Camera_Defect_Detected : Bool;
      Vial_Present : Bool;

      // CIP/SIP Inputs
      Water_Temp : Real;
      Steam_Pressure : Real;
      CIP_Return_Conductivity : Real;
   END_VAR

   VAR_OUTPUT
      Dosing_Valve_Open : Bool;
      Reject_Pusher : Bool;
      Conveyor_Run : Bool;
      System_Ready : Bool;
      System_Fault : Bool;

      // CIP/SIP Outputs
      CIP_Pump_Run : Bool;
      Steam_Valve_Open : Bool;
      Drain_Valve_Open : Bool;
   END_VAR

   VAR
      State : Int;
      S_IDLE : Int := 0;
      S_CIP_RINSE : Int := 10;
      S_SIP_STERILIZE : Int := 11;
      S_CIP_SIP_DONE : Int := 12;
      S_CONVEYOR_MOVE : Int := 20;
      S_DOSING : Int := 21;
      S_INSPECTION : Int := 22;
      S_REJECT : Int := 23;
      S_FAULT : Int := 99;

      Timer_CIP : TON_TIME;
      Timer_SIP : TON_TIME;
      System_Sterile : Bool := FALSE;
   END_VAR

BEGIN
    Timer_CIP(IN := (State = S_CIP_RINSE), PT := T#10m);
    Timer_SIP(IN := (State = S_SIP_STERILIZE), PT := T#20m);

    IF Stop_Production THEN
        State := S_IDLE;
        Dosing_Valve_Open := FALSE;
        Conveyor_Run := FALSE;
        CIP_Pump_Run := FALSE;
        Steam_Valve_Open := FALSE;
        Drain_Valve_Open := FALSE;
    END_IF;

    CASE State OF
        S_IDLE:
            System_Ready := System_Sterile;
            IF Start_CIP_SIP THEN
                State := S_CIP_RINSE;
                System_Sterile := FALSE;
            ELSIF Start_Production AND System_Sterile THEN
                State := S_CONVEYOR_MOVE;
            END_IF;

        S_CIP_RINSE:
            CIP_Pump_Run := TRUE;
            Drain_Valve_Open := TRUE;
            Steam_Valve_Open := FALSE;
            IF Timer_CIP.Q AND (CIP_Return_Conductivity < 10.0) THEN
                CIP_Pump_Run := FALSE;
                Drain_Valve_Open := FALSE;
                State := S_SIP_STERILIZE;
            END_IF;

        S_SIP_STERILIZE:
            Steam_Valve_Open := TRUE;
            Drain_Valve_Open := TRUE;
            // Require minimum 121C / 2.0 bar for sterilization
            IF Timer_SIP.Q AND (Steam_Pressure >= 2.0) THEN
                Steam_Valve_Open := FALSE;
                Drain_Valve_Open := FALSE;
                System_Sterile := TRUE;
                State := S_IDLE;
            END_IF;

        S_CONVEYOR_MOVE:
            Conveyor_Run := TRUE;
            IF Vial_Present THEN
                Conveyor_Run := FALSE;
                State := S_DOSING;
            END_IF;

        S_DOSING:
            IF Scale_Weight < Target_Weight THEN
                Dosing_Valve_Open := TRUE;
            ELSE
                Dosing_Valve_Open := FALSE;
                State := S_INSPECTION;
            END_IF;

        S_INSPECTION:
            IF Camera_Defect_Detected OR (ABS(Scale_Weight - Target_Weight) > Tolerance) THEN
                State := S_REJECT;
            ELSE
                State := S_CONVEYOR_MOVE;
            END_IF;

        S_REJECT:
            Reject_Pusher := TRUE;
            State := S_CONVEYOR_MOVE;
            Reject_Pusher := FALSE;

        S_FAULT:
            System_Fault := TRUE;
            Dosing_Valve_Open := FALSE;
            Conveyor_Run := FALSE;
    END_CASE;
END_FUNCTION_BLOCK
```

