    99:
        bMillMotorOn := FALSE; bFeedConveyorOn := FALSE;
        IF rMillSpeedActual < 0.1 THEN bLubePump1On := FALSE; bLubePump2On := FALSE; END_IF
        IF nScadaCommand = 3 THEN bStart := FALSE; bStop := FALSE; nState := 0; nScadaCommand:=0; END_IF
END_CASE

PROGRAM MAIN
VAR
    bHIL_Mode : BOOL;
    {attribute 'OPC.UA.DA' := '1'} nScadaCommand : INT;
    {attribute 'OPC.UA.DA' := '1'} nCurrentState : INT;
    nUserRole : INT;
    rLubePressure_Tx1, rLubePressure_Tx2 : REAL;
    rLubePressure : REAL;
    bSensorDriftFault : BOOL;
    rMaxDrift : REAL := 5.0;
    bLubePump1On, bLubePump2On : BOOL;
    bPump1Fault : BOOL;
    rMillSpeedActual : REAL;
    bMillMotorOn, bFeedConveyorOn : BOOL;
    bSelfTestPassed : BOOL;
    nTestStep : INT;
    tTestTimer : TON;
    nState : INT := 0;
END_VAR

IF ABS(rLubePressure_Tx1 - rLubePressure_Tx2) > rMaxDrift AND NOT bHIL_Mode THEN
    bSensorDriftFault := TRUE;
END_IF
rLubePressure := (rLubePressure_Tx1 + rLubePressure_Tx2) / 2.0;

IF bHIL_Mode THEN bSensorDriftFault := FALSE; END_IF

IF nUserRole >= 1 THEN
    IF nScadaCommand = 1 THEN nState := 5; nScadaCommand := 0; END_IF
    IF nScadaCommand = 2 THEN nState := 90; nScadaCommand := 0; END_IF
END_IF

nCurrentState := nState;
IF bSensorDriftFault THEN nState := 99; END_IF

CASE nState OF
    0:
        bLubePump1On := FALSE; bLubePump2On := FALSE;
        bMillMotorOn := FALSE; bFeedConveyorOn := FALSE;
    5:
        nTestStep := 1;
        bLubePump1On := TRUE;
        tTestTimer(IN:=TRUE, PT:=T#2S);
        IF tTestTimer.Q THEN
            IF rLubePressure > 50.0 OR bHIL_Mode THEN
                bSelfTestPassed := TRUE;
                nState := 10;
            ELSE
                bPump1Fault := TRUE;
                nState := 10;
            END_IF
            tTestTimer(IN:=FALSE);
        END_IF
    10:
        IF NOT bPump1Fault THEN bLubePump1On := TRUE; ELSE bLubePump2On := TRUE; END_IF
        IF rLubePressure > 135.0 OR bHIL_Mode THEN nState := 20; END_IF
    20:
        bMillMotorOn := TRUE;
        IF rMillSpeedActual > 11.0 OR bHIL_Mode THEN nState := 30; END_IF
    30:
        bFeedConveyorOn := TRUE;
    90:
        bFeedConveyorOn := FALSE;
        bMillMotorOn := FALSE;
        IF rMillSpeedActual < 0.1 OR bHIL_Mode THEN nState := 0; END_IF
    99:
        bMillMotorOn := FALSE; bFeedConveyorOn := FALSE;
        IF rMillSpeedActual < 0.1 THEN bLubePump1On := FALSE; bLubePump2On := FALSE; END_IF
        IF nScadaCommand = 3 THEN bSensorDriftFault := FALSE; nState := 0; nScadaCommand:=0; END_IF
END_CASE

