FUNCTION_BLOCK "FlotationCell_M1"
VERSION : 0.1
   VAR_INPUT 
      StartCmd : Bool;
      Level_PV : Real; 
      Level_SP : Real; 
      Dosing_SP : Real;
      Agitator_Speed_SP : Real; // VFD Speed Setpoint
      Agitator_Torque_PV : Real; // Actual torque from VFD
   END_VAR

   VAR_OUTPUT 
      Valve_CV : Real; 
      DosingPump_Cmd : Bool; 
      DosingPump_Speed : Real;
      Agitator_Run_Cmd : Bool;
      Agitator_Speed_CV : Real;
      Alarm_LowLevel : Bool;
      Alarm_Overload : Bool;
   END_VAR

   VAR 
      instPID : "PID_Compact"; 
      Running : Bool;
   END_VAR

   VAR_CONSTANT
      MIN_LEVEL_AGITATOR : Real := 15.0; // Minimum level to run agitator (%)
      MAX_TORQUE_LIMIT : Real := 90.0;   // Maximum allowed torque (%)
   END_VAR

BEGIN
    // Evaluate Safety Interlocks
    #Alarm_LowLevel := (#Level_PV < #MIN_LEVEL_AGITATOR);
    #Alarm_Overload := (#Agitator_Torque_PV > #MAX_TORQUE_LIMIT);

    // Main state with interlocks
    IF #StartCmd AND NOT #Alarm_LowLevel AND NOT #Alarm_Overload THEN
        #Running := TRUE;
    ELSE
        #Running := FALSE;
    END_IF;

    // Froth Level PID Control
    #instPID(Setpoint := #Level_SP,
             Input := #Level_PV,
             ManualEnable := NOT #Running,
             ManualValue := 0.0,
             Output => #Valve_CV);

    // Reagent Dosing Logic
    IF #Running THEN
        #DosingPump_Cmd := TRUE;
        #DosingPump_Speed := #Dosing_SP; 
    ELSE
        #DosingPump_Cmd := FALSE;
        #DosingPump_Speed := 0.0;
    END_IF;

    // Agitator VFD Control
    IF #Running THEN
        #Agitator_Run_Cmd := TRUE;
        #Agitator_Speed_CV := #Agitator_Speed_SP;
    ELSE
        #Agitator_Run_Cmd := FALSE;
        #Agitator_Speed_CV := 0.0;
    END_IF;

END_FUNCTION_BLOCK
