FUNCTION_BLOCK "FlotationCell_M3"
VERSION : 0.1
   VAR_INPUT 
      PN_Raw_Ultrasonic_A : Int; // Primary
      PN_Raw_Ultrasonic_B : Int; // Redundant
      PN_VFD_Status : Word;
      PN_VFD_Torque : Int;
   VAR_IN_OUT
      SCADA : "UDT_SCADA_Interface";
