      Level_A_PV : Real;
      Level_B_PV : Real;
      Fault_SensorA : Bool;
      Fault_SensorB : Bool;
      State_Running : Bool;

      // Secured Setpoints
      Secure_SP_Level : Real;
      Secure_SP_Dosing : Real;
      Secure_SP_AgitatorSpeed : Real;
   END_VAR

BEGIN
    // 1. IEC 62443 Role-Based Access Control (RBAC)
    // Only Engineers (2) and Admins (3) can change critical setpoints
    IF (#SCADA.ActiveUserRole >= 2) THEN
        #Secure_SP_Level := #SCADA.SP_Level;
        #Secure_SP_Dosing := #SCADA.SP_Dosing;
        #Secure_SP_AgitatorSpeed := #SCADA.SP_AgitatorSpeed;
        #SCADA.Alm_SecurityViolation := FALSE;
    ELSE
        // Revert SCADA inputs if unauthorized attempt is made
        IF (#SCADA.SP_Level <> #Secure_SP_Level) OR 
           (#SCADA.SP_Dosing <> #Secure_SP_Dosing) THEN
            #SCADA.Alm_SecurityViolation := TRUE;
            #SCADA.SP_Level := #Secure_SP_Level;
            #SCADA.SP_Dosing := #Secure_SP_Dosing;
            #SCADA.SP_AgitatorSpeed := #Secure_SP_AgitatorSpeed;
        END_IF;
    END_IF;

    // 2. Redundant Sensor Failover Logic
    #Fault_SensorA := (#PN_Raw_Ultrasonic_A < 0) OR (#PN_Raw_Ultrasonic_A > 27648);
    #Fault_SensorB := (#PN_Raw_Ultrasonic_B < 0) OR (#PN_Raw_Ultrasonic_B > 27648);

    #Level_A_PV := INT_TO_REAL(#PN_Raw_Ultrasonic_A) / 276.48;
    #Level_B_PV := INT_TO_REAL(#PN_Raw_Ultrasonic_B) / 276.48;

    IF NOT #Fault_SensorA THEN
        #Active_Level_PV := #Level_A_PV;
        #SCADA.Alm_FailoverActive := FALSE;
    ELSIF NOT #Fault_SensorB THEN
        #Active_Level_PV := #Level_B_PV;
        #SCADA.Alm_FailoverActive := TRUE;
    ELSE
        #Active_Level_PV := 0.0; // Both failed
    END_IF;

    // 3. Main State Machine
    IF #SCADA.Cmd_Start AND NOT (#Fault_SensorA AND #Fault_SensorB) THEN
        #State_Running := TRUE;
    END_IF;
    IF #SCADA.Cmd_Stop THEN
        #State_Running := FALSE;
    END_IF;

    // 4. PID & Actuator Control
    #instPID(Setpoint := #Secure_SP_Level,
             Input := #Active_Level_PV,
             ManualEnable := NOT #State_Running,
             ManualValue := 0.0,
             Output => #Valve_CV);

    IF #State_Running THEN
        #PN_VFD_Control := 16#047F;
        #PN_VFD_Speed := REAL_TO_INT(#Secure_SP_AgitatorSpeed * 163.84);
        #Dosing_Run := TRUE;
    ELSE
        #PN_VFD_Control := 16#047E;
        #PN_VFD_Speed := 0;
