    fMaxLuffAngle       : LREAL := 15.0;
    fMinLuffAngle       : LREAL := -10.0;
    fSlewLimitLeft      : LREAL := -120.0;
    fSlewLimitRight     : LREAL := 120.0;

    // State
    bCollisionWarning   : BOOL;
    bCollisionFault     : BOOL;
END_VAR

// Anti-Collision Tracking
bCollisionWarning := FALSE;
bCollisionFault := FALSE;

IF fBoomAngle_Deg > fMaxLuffAngle OR fBoomAngle_Deg < fMinLuffAngle THEN
    bCollisionFault := TRUE;
ELSIF fBoomAngle_Deg > (fMaxLuffAngle - 2.0) OR fBoomAngle_Deg < (fMinLuffAngle + 2.0) THEN
    bCollisionWarning := TRUE;
END_IF

IF fSlewAngle_Deg > fSlewLimitRight OR fSlewAngle_Deg < fSlewLimitLeft THEN
    bCollisionFault := TRUE;
ELSIF fSlewAngle_Deg > (fSlewLimitRight - 5.0) OR fSlewAngle_Deg < (fSlewLimitLeft + 5.0) THEN
    bCollisionWarning := TRUE;
END_IF

// Kinematics Coordination
IF bEnable AND NOT bCollisionFault THEN
    // Reduce speed if in warning zone
    IF bCollisionWarning THEN
        fLuffOut_Speed := fLuffCmd_Speed * 0.5;
        fSlewOut_Speed := fSlewCmd_Speed * 0.5;
    ELSE
        fLuffOut_Speed := fLuffCmd_Speed;
        fSlewOut_Speed := fSlewCmd_Speed;
    END_IF
ELSE
    fLuffOut_Speed := 0.0;
    fSlewOut_Speed := 0.0;
END_IF
