// Overload Protection & Payload Compensation
IF fPayloadWeight_kg > fMaxPayload THEN
    bOverloadFault := TRUE;
    fPayloadDeratingFactor := 0.0;
ELSE
    bOverloadFault := FALSE;
    // Calculate derating: scale down speed linearly from 3000kg to 5000kg
    IF fPayloadWeight_kg > 3000.0 THEN
        fPayloadDeratingFactor := 1.0 - ((fPayloadWeight_kg - 3000.0) / 2000.0);
    ELSE
        fPayloadDeratingFactor := 1.0;
    END_IF
