// Anti-Collision Tracking
IF fBoomAngle_Deg > fMaxLuffAngle OR fBoomAngle_Deg < fMinLuffAngle THEN
    bCollisionFault := TRUE;
ELSE
    bCollisionFault := FALSE;
END_IF

// Kinematics Coordination
IF bEnable AND NOT bCollisionFault AND NOT bOverloadFault THEN
    // Apply derating factor to luffing speed based on payload
    fLuffOut_Speed := fLuffCmd_Speed * fPayloadDeratingFactor;
    fSlewOut_Speed := fSlewCmd_Speed * fPayloadDeratingFactor;
ELSE
    fLuffOut_Speed := 0.0;
    fSlewOut_Speed := 0.0;
END_IF
