```scl
FUNCTION_BLOCK "FB_AGV_SLAM_Base"
VERSION : 1.0
VAR_INPUT
    LidarData : ARRAY[0..359] OF REAL; // Distances in meters
    CurrentX : REAL;
    CurrentY : REAL;
    TargetX : REAL;
    TargetY : REAL;
END_VAR
VAR_OUTPUT
    CmdVelocity : REAL;
    CmdSteering : REAL;
END_VAR
VAR
    i : INT;
    MinDistance : REAL;
    ObstacleDetected : BOOL;
    DistanceToTarget : REAL;
END_VAR
BEGIN
    MinDistance := 999.0;
    FOR i := 0 TO 359 DO
        IF LidarData[i] < MinDistance THEN
            MinDistance := LidarData[i];
        END_IF;
    END_FOR;

    IF MinDistance < 1.5 THEN
        ObstacleDetected := TRUE;
        CmdVelocity := 0.0;
        CmdSteering := 90.0; // Evasive maneuver
    ELSE
        ObstacleDetected := FALSE;
        DistanceToTarget := SQRT(SQR(TargetX - CurrentX) + SQR(TargetY - CurrentY));
        IF DistanceToTarget > 0.1 THEN
            CmdVelocity := 1.5;
            CmdSteering := 0.0; // Straight to target
        ELSE
            CmdVelocity := 0.0;
        END_IF;
    END_IF;
END_FUNCTION_BLOCK
