```scl
FUNCTION_BLOCK "FB_AGV_SLAM_Depth"
VERSION : 1.0
VAR_INPUT
    LidarData : ARRAY[0..359] OF REAL;
    BatteryLevel : REAL;
    SafetyZoneActive : ARRAY[1..3] OF BOOL;
END_VAR
VAR_OUTPUT
    CmdVelocity : REAL;
    CmdSteering : REAL;
    ChargeRequest : BOOL;
    EmergencyStop : BOOL;
END_VAR
VAR
    MinDistance : REAL;
    i : INT;
    SafetyTripped : BOOL;
    PredictedDrain : REAL;
END_VAR
BEGIN
    // Multi-zone safety interlocks
    SafetyTripped := SafetyZoneActive[1] OR SafetyZoneActive[2] OR SafetyZoneActive[3];
    IF SafetyTripped THEN
        EmergencyStop := TRUE;
        CmdVelocity := 0.0;
        RETURN;
    END_IF;

    // Battery predictive charge scheduling
    PredictedDrain := 5.0; // Assumed drain to next node
    IF (BatteryLevel - PredictedDrain) < 20.0 THEN
        ChargeRequest := TRUE;
        CmdVelocity := 0.5; // Slow down to save power
    ELSE
        ChargeRequest := FALSE;
    END_IF;

    // Lidar Processing
    MinDistance := 999.0;
    FOR i := 0 TO 359 DO
        IF LidarData[i] < MinDistance THEN
            MinDistance := LidarData[i];
        END_IF;
    END_FOR;

    IF MinDistance < 1.0 THEN
        CmdVelocity := 0.0;
    ELSIF NOT ChargeRequest THEN
        CmdVelocity := 1.5;
    END_IF;
END_FUNCTION_BLOCK
