        PN_FaultDiag := 16#0000;
        SysFault := FALSE;
    END_IF;

    IF SysFault OR SafetyZoneActive[1] THEN
        CmdVelocity := 0.0;
        RETURN;
    END_IF;

    IF BatteryLevel < 20.0 THEN
        ChargeRequest := TRUE;
        CmdVelocity := 0.5;
    ELSE
        ChargeRequest := FALSE;
        MinDistance := 999.0;
        FOR i := 0 TO 359 DO
            IF LidarData[i] < MinDistance THEN MinDistance := LidarData[i]; END_IF;
        END_FOR;
        IF MinDistance < 1.2 THEN CmdVelocity := 0.0; ELSE CmdVelocity := 2.0; END_IF;
    END_IF;
END_FUNCTION_BLOCK
