```pascal
FUNCTION_BLOCK "HVDC_Control_Profinet_Diag"
VERSION : 1.0
VAR_INPUT
    SetAlpha : REAL; 
    GridFreq : REAL; 
    PhaseA_Current : REAL;
    PhaseB_Current : REAL;
    PhaseC_Current : REAL;
    PhaseA_Volt : REAL;
    PhaseB_Volt : REAL;
    PhaseC_Volt : REAL;
END_VAR
VAR_OUTPUT
    AlphaOut : REAL; 
    FilterSync : BOOL; 
    // Profinet Status Word
    PN_StatusWord : WORD;
    // Alarms
    Alarm_PhaseLoss : BOOL;
    Alarm_OverCurrent : BOOL;
    Alarm_FilterDetune : BOOL;
END_VAR
VAR
    AlphaFiltered : REAL;
    CurrentThreshold : REAL := 2000.0;
    VoltMinThreshold : REAL := 0.8 * 400.0; // Assuming 400kV base
END_VAR
BEGIN
    // Fault Diagnostics: Overcurrent
    IF PhaseA_Current > CurrentThreshold OR PhaseB_Current > CurrentThreshold OR PhaseC_Current > CurrentThreshold THEN
        Alarm_OverCurrent := TRUE;
    ELSE
        Alarm_OverCurrent := FALSE;
    END_IF;

    // Fault Diagnostics: Phase Loss
    IF PhaseA_Volt < VoltMinThreshold OR PhaseB_Volt < VoltMinThreshold OR PhaseC_Volt < VoltMinThreshold THEN
        Alarm_PhaseLoss := TRUE;
    ELSE
        Alarm_PhaseLoss := FALSE;
    END_IF;

    // Firing Angle Control
    AlphaFiltered := (AlphaFiltered * 0.9) + (SetAlpha * 0.1);
    IF Alarm_PhaseLoss OR Alarm_OverCurrent THEN
        AlphaOut := 180.0; // Block firing
    ELSE
        AlphaOut := AlphaFiltered;
    END_IF;

    // Harmonics filter synchronization logic
    IF GridFreq > 49.8 AND GridFreq < 50.2 AND NOT Alarm_PhaseLoss THEN
        FilterSync := TRUE;
        Alarm_FilterDetune := FALSE;
    ELSE
        FilterSync := FALSE;
        Alarm_FilterDetune := TRUE;
    END_IF;

    // Profinet Mapping (Bit packing)
    PN_StatusWord.%X0 := FilterSync;
    PN_StatusWord.%X1 := Alarm_PhaseLoss;
    PN_StatusWord.%X2 := Alarm_OverCurrent;
    PN_StatusWord.%X3 := Alarm_FilterDetune;
END_FUNCTION_BLOCK
