    AlphaOut : REAL;
    FilterSync : BOOL;
    SensorDrift_Alarm : BOOL;
    SelfTest_Passed : BOOL;
    SelfTest_Active : BOOL;
END_VAR
VAR
    State : INT := 0; // 0=Init, 1=SelfTest, 2=Run, 3=Fault
    TestTimer : DINT := 0;
    EffectiveVolt : REAL;
END_VAR
BEGIN
    // Sensor Drift Detection
    IF ABS(GridVolt_Sensor1 - GridVolt_Sensor2) > 5.0 THEN
        SensorDrift_Alarm := TRUE;
    ELSE
        SensorDrift_Alarm := FALSE;
    END_IF;

    // HIL Digital Twin Sync
    IF HIL_Mode_Active THEN
        EffectiveVolt := HIL_GridVolt_Sim;
        SensorDrift_Alarm := FALSE; // Bypass sensor check in HIL
    ELSE
        EffectiveVolt := (GridVolt_Sensor1 + GridVolt_Sensor2) / 2.0;
    END_IF;

    // State Machine
    CASE State OF
        0: // Init
            IF Start_SelfTest THEN
                State := 1;
                TestTimer := 0;
            END_IF;
        1: // Self-Test Routine
            SelfTest_Active := TRUE;
            TestTimer := TestTimer + 1;
            // Simulate test conditions
            IF TestTimer > 100 THEN
                IF NOT SensorDrift_Alarm THEN
                    SelfTest_Passed := TRUE;
                    State := 2;
                ELSE
                    SelfTest_Passed := FALSE;
                    State := 3;
                END_IF;
                SelfTest_Active := FALSE;
            END_IF;
            AlphaOut := 180.0; // Block during test
        2: // Run
            IF SensorDrift_Alarm THEN
                State := 3; // Trip on drift
            ELSE
                AlphaOut := SetAlpha;
                IF GridFreq > 49.8 AND GridFreq < 50.2 THEN
                    FilterSync := TRUE;
                ELSE
                    FilterSync := FALSE;
                END_IF;
            END_IF;
        3: // Fault
            AlphaOut := 180.0;
            FilterSync := FALSE;
    END_CASE;
END_FUNCTION_BLOCK
