PROGRAM MAIN
VAR
    // Inputs
    fWindSpeed : REAL; // Anemometer reading in m/s
    fTargetPitch : REAL; // Calculated target pitch in degrees
    fActualPitch : REAL; // Actual pitch from hydraulic sensor in degrees
    bSystemEnable : BOOL; // System run signal

    // Parameters
    fCutInSpeed : REAL := 3.0;
    fRatedSpeed : REAL := 12.0;
    fCutOutSpeed : REAL := 25.0;

    // Hydraulic Control Outputs
    bHydraulicPumpOn : BOOL;
    fHydraulicValveCmd : REAL; // -10V to 10V cmd to proportional valve

    // Internal Variables
    fbPID : FB_BasicPID;
    eState : (INIT, IDLE, RUNNING, BRAKING, FAULT);
END_VAR

CASE eState OF
    INIT:
        bHydraulicPumpOn := FALSE;
        fHydraulicValveCmd := 0.0;
        IF bSystemEnable THEN
            eState := IDLE;
        END_IF

    IDLE:
        bHydraulicPumpOn := TRUE;
        fTargetPitch := 90.0; // Feathered position
        IF fWindSpeed >= fCutInSpeed AND fWindSpeed <= fCutOutSpeed THEN
            eState := RUNNING;
        END_IF
        IF NOT bSystemEnable THEN
            eState := INIT;
        END_IF

    RUNNING:
        IF fWindSpeed > fRatedSpeed AND fWindSpeed <= fCutOutSpeed THEN
            // Pitch control logic to maintain rated power
            fTargetPitch := (fWindSpeed - fRatedSpeed) * 2.5; // Simplified linear model
        ELSIF fWindSpeed <= fRatedSpeed THEN
            fTargetPitch := 0.0; // Max capture
        END_IF

        IF fWindSpeed > fCutOutSpeed OR NOT bSystemEnable THEN
            eState := BRAKING;
        END_IF

    BRAKING:
        fTargetPitch := 90.0; // Feather to stop
        IF fActualPitch >= 89.0 THEN
            eState := IDLE;
        END_IF

    FAULT:
        bHydraulicPumpOn := FALSE;
        fHydraulicValveCmd := 0.0;
        // Require reset
END_CASE

// Hydraulic Pitch PID Control
fbPID(
    fSetpoint := fTargetPitch,
    fActualValue := fActualPitch,
    bEnable := (eState = RUNNING) OR (eState = BRAKING) OR (eState = IDLE),
    fKp := 1.5,
    fTn := 0.5,
    fTv := 0.0,
    fOutput => fHydraulicValveCmd
);

