END_VAR

// Critical Subsystem: Accumulator Pressure Monitoring
IF fHydraulicPressure < fMinSafePressure THEN
    bLowPressureFault := TRUE;
    eState := FAULT;
END_IF

IF bSafetyReset AND fHydraulicPressure >= fMinSafePressure THEN
    bLowPressureFault := FALSE;
END_IF

CASE eState OF
    INIT:
        bHydraulicPumpOn := FALSE;
        fHydraulicValveCmd := 0.0;
        bSafetyFeatherSolenoid := FALSE;
        IF bSystemEnable AND NOT bLowPressureFault THEN
            eState := IDLE;
        END_IF

    IDLE:
        bHydraulicPumpOn := TRUE;
        bSafetyFeatherSolenoid := TRUE; // Energize to run (fail-safe)
        fTargetPitch := 90.0;
        IF fWindSpeed >= fCutInSpeed AND fWindSpeed <= fCutOutSpeed AND fHydraulicPressure >= fNominalPressure THEN
            eState := RUNNING;
        END_IF

    RUNNING:
        IF fWindSpeed > fRatedSpeed THEN
            fTargetPitch := (fWindSpeed - fRatedSpeed) * 2.5;
        ELSE
            fTargetPitch := 0.0;
        END_IF

        IF fWindSpeed > fCutOutSpeed OR NOT bSystemEnable THEN
            eState := BRAKING;
        END_IF

    BRAKING:
        fTargetPitch := 90.0;
        IF fActualPitch >= 89.0 THEN
            eState := IDLE;
        END_IF

    FAULT:
        bHydraulicPumpOn := TRUE; // Try to build pressure if possible
        fHydraulicValveCmd := 0.0;
        IF bLowPressureFault THEN
            // De-energize solenoid to mechanically force pitch to 90 degrees using accumulator pressure
            bSafetyFeatherSolenoid := FALSE; 
        END_IF
END_CASE

fbPID(
    fSetpoint := fTargetPitch,
    fActualValue := fActualPitch,
    bEnable := (eState <> FAULT) AND bSafetyFeatherSolenoid,
    fKp := 1.5, fTn := 0.5, fOutput => fHydraulicValveCmd
);

