END_IF;

IF (SCADA_Data.Sys_Mode = 2) AND NOT (Role_Operator OR Role_Admin) THEN
    SCADA_Data.Sys_Mode := 1;
    Sec_Audit_Event := TRUE;
END_IF;

Sensor_Discrepancy := ABS(V_Sensor_Primary - V_Sensor_Backup) > 5.0;
