FUNCTION_BLOCK "FrancisTurbine_GuideVane_Mut4"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Enable_Control : Bool;
      Target_Gate_Position : Real; 
      Actual_Gate_Position_LVDT1 : Real; 
      Actual_Gate_Position_LVDT2 : Real; 
