    fMicrogridFreq : REAL;
    fPhaseAngleDiff : REAL;
    bSyncReady : BOOL;
    bCloseBreaker : BOOL;
    bOpenBreaker : BOOL;

    fTotalLoad : REAL;
    fMaxGeneration : REAL;
    bLoadShedding1 : BOOL;
    bLoadShedding2 : BOOL;
    bLoadShedding3 : BOOL;

    fBessSoC : REAL;
    fBessChargePower : REAL;
    fBessDischargePower : REAL;
    fPvPower : REAL;
    fPvCurtailmentLimit : REAL;
END_VAR

// Island Mode Detection & Transition
IF bIslandModeCommand AND bGridConnected THEN
    bOpenBreaker := TRUE;
    bCloseBreaker := FALSE;
    bGridConnected := FALSE;
END_IF

// Synchronization for Grid Reconnection
IF NOT bGridConnected AND NOT bIslandModeCommand THEN
    IF ABS(fGridVoltage - fMicrogridVoltage) < 5.0 AND 
       ABS(fGridFreq - fMicrogridFreq) < 0.1 AND
       ABS(fPhaseAngleDiff) < 5.0 THEN
       bSyncReady := TRUE;
    ELSE
       bSyncReady := FALSE;
    END_IF

    IF bSyncReady THEN
        bCloseBreaker := TRUE;
        bOpenBreaker := FALSE;
        bGridConnected := TRUE;
    END_IF
END_IF

// Load Shedding Logic (in Island Mode)
IF NOT bGridConnected THEN
    IF fTotalLoad > fMaxGeneration THEN
        bLoadShedding1 := TRUE;
    END_IF
    IF fTotalLoad > (fMaxGeneration * 1.1) THEN
        bLoadShedding2 := TRUE;
    END_IF
    IF fTotalLoad > (fMaxGeneration * 1.2) THEN
        bLoadShedding3 := TRUE;
    END_IF
ELSE
    bLoadShedding1 := FALSE;
    bLoadShedding2 := FALSE;
    bLoadShedding3 := FALSE;
END_IF

// BESS & PV Management (Island Mode)
IF NOT bGridConnected THEN
    IF fTotalLoad < fPvPower AND fBessSoC < 95.0 THEN
        fBessChargePower := fPvPower - fTotalLoad;
        fBessDischargePower := 0.0;
        fPvCurtailmentLimit := fPvPower; // No curtailment
    ELSIF fTotalLoad < fPvPower AND fBessSoC >= 95.0 THEN
        fBessChargePower := 0.0;
        fBessDischargePower := 0.0;
        fPvCurtailmentLimit := fTotalLoad; // Curtail PV
    ELSIF fTotalLoad > fPvPower THEN
        fBessChargePower := 0.0;
        fBessDischargePower := MIN(fTotalLoad - fPvPower, 500.0); // max discharge limit
    END_IF
END_IF
