The failover mechanism uses dual redundancy to ensure high availability and safety. If the primary speed sensor fails or provides out-of-range data, the system automatically switches to the secondary sensor. If both fail or diverge significantly without a clear winner, a critical fault is raised, triggering an emergency safe state. This is crucial for high-speed rail, where an undetected speed sensor failure during traction or braking could lead to catastrophic wheel slip/slide or derailment.

```scl
TYPE "Security_Credentials"
    STRUCT
        AccessLevel : Int;
        SessionKey : DWord;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK "TractionControl_SecFailover"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      TargetSpeed_kmh : Real;
      ActualSpeed1_kmh : Real;
      ActualSpeed2_kmh : Real;
      SensorValid1 : Bool;
      SensorValid2 : Bool;
      WheelSpeed_rpm : Real;
      WheelDiameter_m : Real;
      BrakeCommand : Real;
      SCADA_Heartbeat : Bool;
      SecurityContext : "Security_Credentials";
   END_VAR
   VAR_OUTPUT 
      TorqueCmd_Nm : Real;
      FaultCode : DInt;
   END_VAR
   VAR_IN_OUT
      MaxTorqueParam : Real;
   END_VAR
   VAR 
      ActualSpeed_kmh : Real;
      HeartbeatTimer : TON_TIME;
   END_VAR
   CONST
      AUTH_LEVEL_ADMIN := 99;
      SPEED_TOLERANCE := 10.0;
      ERR_BOTH_SENSORS := 201;
      ERR_SENSOR_DIVERGE := 202;
      ERR_COMM_LOST := 203;
   END_CONST
BEGIN
    IF #SecurityContext.AccessLevel < #AUTH_LEVEL_ADMIN THEN
        #MaxTorqueParam := 10000.0; 
    END_IF;
    #HeartbeatTimer(IN := NOT #SCADA_Heartbeat, PT := T#2S);
    IF #HeartbeatTimer.Q THEN
        #FaultCode := #ERR_COMM_LOST;
        #TorqueCmd_Nm := 0.0;
        RETURN;
    END_IF;
    IF #SensorValid1 AND #SensorValid2 THEN
        IF ABS(#ActualSpeed1_kmh - #ActualSpeed2_kmh) > #SPEED_TOLERANCE THEN
            #FaultCode := #ERR_SENSOR_DIVERGE;
            #TorqueCmd_Nm := 0.0;
            RETURN;
        ELSE
            #ActualSpeed_kmh := (#ActualSpeed1_kmh + #ActualSpeed2_kmh) / 2.0;
        END_IF;
    ELSIF #SensorValid1 THEN
        #ActualSpeed_kmh := #ActualSpeed1_kmh;
    ELSIF #SensorValid2 THEN
        #ActualSpeed_kmh := #ActualSpeed2_kmh;
    ELSE
        #FaultCode := #ERR_BOTH_SENSORS;
        #TorqueCmd_Nm := 0.0;
        RETURN;
    END_IF;
    #FaultCode := 0;
    IF #BrakeCommand > 0.0 THEN
        #TorqueCmd_Nm := - (#BrakeCommand / 100.0 * #MaxTorqueParam);
    ELSE
        #TorqueCmd_Nm := ((#TargetSpeed_kmh - #ActualSpeed_kmh) * 50.0);
        IF #TorqueCmd_Nm > #MaxTorqueParam THEN #TorqueCmd_Nm := #MaxTorqueParam; END_IF;
        IF #TorqueCmd_Nm < 0.0 THEN #TorqueCmd_Nm := 0.0; END_IF;
    END_IF;
END_FUNCTION_BLOCK
