Here is the base Beckhoff ST program for a Marine Propulsion system that handles Azimuth Thruster vectoring and engine load sharing.

```pascal
PROGRAM PRG_MarinePropulsion
VAR
    // Inputs: Joystick control commands
    fJoyStickX : REAL; // Forward/Backward thrust demand (-100.0 to 100.0)
    fJoyStickY : REAL; // Port/Starboard thrust demand (-100.0 to 100.0)

    // Outputs: Thruster vectoring and speed commands
    fThrusterPortAngle : REAL; // Degrees (0-360)
    fThrusterPortSpeed : REAL; // RPM
    fThrusterStbdAngle : REAL; // Degrees (0-360)
    fThrusterStbdSpeed : REAL; // RPM

    // Engine Load Sharing
    fEngine1LoadCmd : REAL; // kW or %
    fEngine2LoadCmd : REAL; // kW or %
    fTotalPowerDemand : REAL; // Total required propulsion power

    // Constants & Limits
    fMaxThrusterSpeed : REAL := 1500.0; // Max RPM
    fPowerPerRpm : REAL := 2.5; // kW per RPM factor
END_VAR

// 1. Azimuth Vectoring Logic
// Calculate the thrust angle based on X and Y joystick inputs using ATAN2
IF fJoyStickX <> 0.0 OR fJoyStickY <> 0.0 THEN
    // Convert radians to degrees (0 to 360)
    fThrusterPortAngle := (ATAN2(fJoyStickY, fJoyStickX) * 180.0 / 3.14159265359);
    IF fThrusterPortAngle < 0.0 THEN
        fThrusterPortAngle := fThrusterPortAngle + 360.0;
    END_IF;

    // Synchronize starboard thruster angle for parallel vectoring
    fThrusterStbdAngle := fThrusterPortAngle;
ELSE
    // Maintain current angle if no joystick input
    fThrusterPortAngle := fThrusterPortAngle;
    fThrusterStbdAngle := fThrusterStbdAngle;
END_IF;

// 2. Thrust Demand Calculation
// Calculate the magnitude of the thrust vector (0 to 100%)
fTotalPowerDemand := SQRT(EXPT(fJoyStickX, 2.0) + EXPT(fJoyStickY, 2.0));
IF fTotalPowerDemand > 100.0 THEN
    fTotalPowerDemand := 100.0;
END_IF;

// Map power demand to thruster speed
fThrusterPortSpeed := (fTotalPowerDemand / 100.0) * fMaxThrusterSpeed;
fThrusterStbdSpeed := fThrusterPortSpeed;

// 3. Engine Load Sharing
// Split the total required power equally across both engines (Symmetrical Load Sharing)
fEngine1LoadCmd := (fThrusterPortSpeed + fThrusterStbdSpeed) * fPowerPerRpm / 2.0;
fEngine2LoadCmd := fEngine1LoadCmd;
```
This base code computes the required steering angle and thrust magnitude from joystick inputs and distributes the required load symmetrically across two engines.

Here is the enhanced Beckhoff ST program incorporating Azimuth Thruster vectoring, engine load sharing, and a Dynamic Positioning (DP) sub-system.

```pascal
PROGRAM PRG_MarinePropulsion_DP
VAR
    // Control Modes
    bEnableDPMode : BOOL; // TRUE = DP Mode, FALSE = Manual Joystick

    // Manual Inputs
    fJoyStickX, fJoyStickY : REAL;

    // DP Inputs (GPS, Gyro, Anemometer, Log)
    fTargetLat, fTargetLon, fTargetHeading : LREAL;
    fCurrentLat, fCurrentLon, fCurrentHeading : LREAL;
    fWindSpeed, fWindDir : REAL; // m/s and degrees
    fCurrentSpeed, fCurrentDir : REAL; // m/s and degrees

    // DP PID Controller Variables
    fPosErrorX, fPosErrorY, fHeadingError : REAL;
    fKp_Pos : REAL := 5.0; // Proportional gain for position
    fKp_Heading : REAL := 2.0; // Proportional gain for heading

    // Outputs
    fThrusterPortAngle, fThrusterStbdAngle : REAL;
    fThrusterPortSpeed, fThrusterStbdSpeed : REAL;
    fEngine1LoadCmd, fEngine2LoadCmd : REAL;

    // Internal Variables
    fDemandX, fDemandY, fDemandHeading : REAL;
    fTotalDemandMagnitude : REAL;
END_VAR

// 1. Operational Mode Selection & Demand Calculation
IF bEnableDPMode THEN
    // --- Dynamic Positioning (DP) Sub-system ---

    // Calculate Position Errors (Simplified conversion: 1 deg lat ~ 111320 meters)
    fPosErrorX := LREAL_TO_REAL(fTargetLat - fCurrentLat) * 111320.0;
    fPosErrorY := LREAL_TO_REAL(fTargetLon - fCurrentLon) * 111320.0 * COS(fCurrentLat * 3.14159 / 180.0);
    fHeadingError := LREAL_TO_REAL(fTargetHeading - fCurrentHeading);

    // Normalize heading error to -180 to 180
    IF fHeadingError > 180.0 THEN fHeadingError := fHeadingError - 360.0; END_IF;
    IF fHeadingError < -180.0 THEN fHeadingError := fHeadingError + 360.0; END_IF;

    // Feedforward Environmental Compensation (Wind & Current)
    // Decompose environmental forces into X/Y vectors opposing the disturbance
    fDemandX := (fPosErrorX * fKp_Pos) - (fWindSpeed * COS(fWindDir * 3.14159 / 180.0)) - (fCurrentSpeed * COS(fCurrentDir * 3.14159 / 180.0));
    fDemandY := (fPosErrorY * fKp_Pos) - (fWindSpeed * SIN(fWindDir * 3.14159 / 180.0)) - (fCurrentSpeed * SIN(fCurrentDir * 3.14159 / 180.0));
    fDemandHeading := fHeadingError * fKp_Heading;

ELSE
    // --- Manual Joystick Mode ---
    fDemandX := fJoyStickX;
    fDemandY := fJoyStickY;
    fDemandHeading := 0.0; // Assuming basic X/Y for this example
END_IF;

// 2. Azimuth Vectoring & Speed Allocation
fTotalDemandMagnitude := SQRT(EXPT(fDemandX, 2.0) + EXPT(fDemandY, 2.0));
IF fTotalDemandMagnitude > 100.0 THEN fTotalDemandMagnitude := 100.0; END_IF;

IF fDemandX <> 0.0 OR fDemandY <> 0.0 THEN
    fThrusterPortAngle := (ATAN2(fDemandY, fDemandX) * 180.0 / 3.14159265359);
    IF fThrusterPortAngle < 0.0 THEN fThrusterPortAngle := fThrusterPortAngle + 360.0; END_IF;

    // Offset Starboard angle slightly based on heading demand for yaw control
    fThrusterStbdAngle := fThrusterPortAngle + fDemandHeading; 
    IF fThrusterStbdAngle > 360.0 THEN fThrusterStbdAngle := fThrusterStbdAngle - 360.0; END_IF;
END_IF;

fThrusterPortSpeed := fTotalDemandMagnitude * 15.0; // Assuming 1500 RPM max
fThrusterStbdSpeed := fTotalDemandMagnitude * 15.0;

// 3. Engine Load Sharing
fEngine1LoadCmd := (fThrusterPortSpeed + fThrusterStbdSpeed) * 1.25;
fEngine2LoadCmd := fEngine1LoadCmd;
```
This version introduces a DP control loop that calculates positional/heading errors in meters/degrees, adds feedforward compensation for environmental sensors (anemometer and water speed log), and overrides the manual joystick logic when active.

