PROGRAM PRG_MarinePropulsion_ECAT
VAR
    // Hardware I/O (EtherCAT Mapping)
    uiEcatMasterState AT %I* : UINT; // EtherCAT Master State
    uiDrivePortState AT %I* : UINT;  // Port Drive State word
    uiDriveStbdState AT %I* : UINT;  // Stbd Drive State word
    bDrivePortReady AT %I* : BOOL;
    bDriveStbdReady AT %I* : BOOL;

    fThrusterPortSpeedCmd AT %Q* : REAL;
