    fInternalSpeedPort, fInternalSpeedStbd : REAL;

    // Fault Diagnostics System
    astAlarms : ARRAY[1..20] OF ST_Alarm;
    bSystemCriticalFault : BOOL;
    bSystemErrorFault : BOOL;

    i : INT;
END_VAR

// 1. Fault Diagnostics & EtherCAT Monitoring
// Check EtherCAT Master State (8 = OP State)
astAlarms[1].bActive := (uiEcatMasterState <> 8);
astAlarms[1].eSeverity := E_AlarmSeverity.CRITICAL;
astAlarms[1].sMessage := 'EtherCAT Master Not in OP State - Fieldbus Failure';

// Drive Trips / Ready Signals
astAlarms[2].bActive := NOT bDrivePortReady;
astAlarms[2].eSeverity := E_AlarmSeverity.ERROR;
astAlarms[2].sMessage := 'Port Azimuth Drive Not Ready or Tripped';

astAlarms[3].bActive := NOT bDriveStbdReady;
astAlarms[3].eSeverity := E_AlarmSeverity.ERROR;
astAlarms[3].sMessage := 'Starboard Azimuth Drive Not Ready or Tripped';

// Evaluate System Fault Level
bSystemCriticalFault := FALSE;
bSystemErrorFault := FALSE;
FOR i := 1 TO 20 DO
    IF astAlarms[i].bActive THEN
        IF astAlarms[i].eSeverity = E_AlarmSeverity.CRITICAL THEN
            bSystemCriticalFault := TRUE;
        ELSIF astAlarms[i].eSeverity = E_AlarmSeverity.ERROR THEN
            bSystemErrorFault := TRUE;
        END_IF;
    END_IF;
END_FOR;

// 2. Core Propulsion & DP Logic
IF NOT bSystemCriticalFault THEN
    // [DP and Vectoring logic resides here, calculating fInternalSpeedPort and Stbd]
    // ...
    // Simulated calculation:
    fInternalSpeedPort := fDemandX * 10.0; 
    fInternalSpeedStbd := fDemandX * 10.0;

    // Apply Interlocks for Errors
    IF bSystemErrorFault THEN
        // Reduce max output if in Error state (Limp Mode)
        fInternalSpeedPort := LIMIT(0.0, fInternalSpeedPort, 500.0);
        fInternalSpeedStbd := LIMIT(0.0, fInternalSpeedStbd, 500.0);
    END_IF;

    // Map to EtherCAT Physical Outputs
    fThrusterPortSpeedCmd := fInternalSpeedPort;
    fThrusterStbdSpeedCmd := fInternalSpeedStbd;
ELSE
    // Critical Fault - Safe State (Zero Thrust)
    fThrusterPortSpeedCmd := 0.0;
    fThrusterStbdSpeedCmd := 0.0;
    bEnableDPMode := FALSE; // Force disable DP
END_IF;
