PROGRAM PRG_MarinePropulsion_Ultimate
VAR
    // Sensor Drift Detection (2oo3 Voting for GPS)
    fGPS1_Lat AT %I*, fGPS2_Lat AT %I*, fGPS3_Lat AT %I* : LREAL;
    fDriftTolerance : LREAL := 0.00005; // Approx 5 meters
    bGPS1_Fault, bGPS2_Fault, bGPS3_Fault : BOOL;
    fValidatedLat : LREAL;

    // Hardware-in-the-Loop (HIL) Digital Twin Sync
    {attribute 'TcRpcEnable'}
    bHIL_ModeActive : BOOL;
    fHIL_PredictedLoad : REAL;
    fActualThrusterLoad : REAL;
    bPredictiveMaintenanceAlert : BOOL;

    // Automated Self-Test Routine
    eTestState : E_SelfTestState := E_SelfTestState.INIT;
    bStartSelfTest : BOOL;
    bSelfTestPassed : BOOL;
    bSystemReadyToEngage : BOOL;
    tTestTimeout : TON;

    // Inherited Subsystems (Abstracted)
    bSystemCriticalFault, bSecureStateActive : BOOL;
    fThrusterSpeedCmd AT %Q* : REAL;
END_VAR

// 1. Adversarial Sensor Drift Detection (2-out-of-3 Validation)
// Cross-validate redundant positioning sensors to identify and isolate slowly drifting adversaries
bGPS1_Fault := (ABS(fGPS1_Lat - fGPS2_Lat) > fDriftTolerance) AND (ABS(fGPS1_Lat - fGPS3_Lat) > fDriftTolerance);
bGPS2_Fault := (ABS(fGPS2_Lat - fGPS1_Lat) > fDriftTolerance) AND (ABS(fGPS2_Lat - fGPS3_Lat) > fDriftTolerance);
bGPS3_Fault := (ABS(fGPS3_Lat - fGPS1_Lat) > fDriftTolerance) AND (ABS(fGPS3_Lat - fGPS2_Lat) > fDriftTolerance);

// Select valid sensor data
IF NOT bGPS1_Fault THEN fValidatedLat := fGPS1_Lat;
ELSIF NOT bGPS2_Fault THEN fValidatedLat := fGPS2_Lat;
ELSIF NOT bGPS3_Fault THEN fValidatedLat := fGPS3_Lat;
ELSE bSystemCriticalFault := TRUE; // Loss of all positional truth
END_IF;

// 2. Digital Twin (HIL) Synchronization
// Compare physical operational data against the digital twin's model output
IF bHIL_ModeActive THEN
    // If the actual physical load deviates by > 15% from the digital twin's prediction, flag for maintenance
    IF ABS(fActualThrusterLoad - fHIL_PredictedLoad) > (fHIL_PredictedLoad * 0.15) THEN
        bPredictiveMaintenanceAlert := TRUE; 
    END_IF;
END_IF;

// 3. Automated Pre-Engagement Self-Test Routine
tTestTimeout(IN := (eTestState > E_SelfTestState.INIT) AND (eTestState < E_SelfTestState.DONE), PT := T#10S);

IF bStartSelfTest AND NOT bSelfTestPassed THEN
    CASE eTestState OF
        E_SelfTestState.INIT:
            bSelfTestPassed := FALSE;
            eTestState := E_SelfTestState.CHECK_IO_COMMS;

        E_SelfTestState.CHECK_IO_COMMS:
            IF NOT bSystemCriticalFault THEN eTestState := E_SelfTestState.CHECK_INTERLOCKS; END_IF;

        E_SelfTestState.CHECK_INTERLOCKS:
            // Verify cooling pumps, lube oil pressure, etc.
            IF TRUE (* Interlocks OK *) THEN eTestState := E_SelfTestState.CHECK_DRIVE_READY; END_IF;

        E_SelfTestState.CHECK_DRIVE_READY:
            // Send test pulse to drives and await ready bit
            IF TRUE (* Drives Ready *) THEN eTestState := E_SelfTestState.DONE; END_IF;

        E_SelfTestState.DONE:
            bSelfTestPassed := TRUE;
            bStartSelfTest := FALSE;

        E_SelfTestState.FAILED:
            bSelfTestPassed := FALSE;
            bStartSelfTest := FALSE;
    END_CASE;

    // Timeout handler
    IF tTestTimeout.Q THEN
        eTestState := E_SelfTestState.FAILED;
    END_IF;
END_IF;

// 4. Final Output Engagement Interlock
bSystemReadyToEngage := bSelfTestPassed AND NOT bSystemCriticalFault AND NOT bSecureStateActive;

IF bSystemReadyToEngage THEN
    fThrusterSpeedCmd := 50.0; // Normal operation
ELSE
    fThrusterSpeedCmd := 0.0; // Fail-safe
END_IF;
