```pascal
FUNCTION_BLOCK "CBTC_ATO_System"
VERSION : 1.1
VAR_INPUT
    Train_Position : REAL;
    Train_Speed : REAL;
    Ahead_Train_Pos : REAL;
    Switch_Req : BOOL;
    Track_Gradient : REAL;   // Gradient in %
    Speed_Limit : REAL;      // Track speed limit [m/s]
END_VAR

VAR_OUTPUT
    Brake_Apply : BOOL;
    Switch_Pos : INT;
    ATO_Accel_Cmd : REAL;    // Acceleration command [m/s^2]
    ATO_Brake_Cmd : REAL;    // Brake command [m/s^2]
END_VAR

VAR
    Safety_Margin : REAL := 50.0;
    Target_Stopping_Pos : REAL;
    Dist_To_Stop : REAL;
    Req_Decel : REAL;
END_VAR

BEGIN
    // 1. Point Machine Switching
    IF Switch_Req AND (Train_Speed < 0.1) THEN
        Switch_Pos := 1;
    ELSE
        Switch_Pos := 0;
    END_IF;

    // 2. CBTC Moving Block Authority
    Target_Stopping_Pos := Ahead_Train_Pos - Safety_Margin;
    Dist_To_Stop := Target_Stopping_Pos - Train_Position;

    IF Dist_To_Stop <= 0.0 THEN
        Brake_Apply := TRUE;
        ATO_Accel_Cmd := 0.0;
        ATO_Brake_Cmd := 2.5; // Max emergency brake
        RETURN;
    ELSE
        Brake_Apply := FALSE;
    END_IF;

    // 3. ATO Velocity Profile Generator
    // Calculate required deceleration to stop at the target position
    Req_Decel := (Train_Speed * Train_Speed) / (2.0 * Dist_To_Stop);

    // Compensate for track gradient (gravity effect ~9.81 * gradient/100)
    Req_Decel := Req_Decel - (9.81 * (Track_Gradient / 100.0));

    IF Req_Decel > 0.5 THEN
        // Need to brake
        ATO_Brake_Cmd := LIMIT(MN:=0.0, IN:=Req_Decel, MX:=1.5);
        ATO_Accel_Cmd := 0.0;
    ELSIF Train_Speed < Speed_Limit THEN
        // Safe to accelerate
        ATO_Brake_Cmd := 0.0;
        ATO_Accel_Cmd := LIMIT(MN:=0.0, IN:=(Speed_Limit - Train_Speed)*0.5, MX:=1.0);
    ELSE
        // Coasting / Maintaining speed
        ATO_Accel_Cmd := 0.0;
        ATO_Brake_Cmd := 0.0;
    END_IF;
END_FUNCTION_BLOCK
```

