    IF (fHeelAngle - fHeelSetpoint) > fDeadband THEN
        // Ship tilted starboard: fill port, empty starboard
        bValvePortBow := TRUE; bValvePortAft := TRUE;
        bValveStbdBow := FALSE; bValveStbdAft := FALSE;
        bPump1Cmd := TRUE; bPump2Cmd := TRUE; // Pump 1 Port, Pump 2 Stbd
    ELSIF (fHeelSetpoint - fHeelAngle) > fDeadband THEN
