        bValvePortBow := FALSE; bValvePortAft := FALSE;
        bValveStbdBow := TRUE; bValveStbdAft := TRUE;
        bPump1Cmd := TRUE; bPump2Cmd := TRUE;
    ELSE
        // Priority 2: Trim Control (Pitch)
        IF (fTrimAngle - fTrimSetpoint) > fDeadband THEN
            // Bow down: fill aft, empty bow
