FUNCTION_BLOCK "Bottling_RotaryFiller_PN_Diag"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    CIP_Start : Bool;
    Bottle_Present : Bool;
    Cap_Level_Low : Bool;
    Speed_Setpoint : Real;
    PN_Status_Word : Word; // Profinet Status from Drives
END_VAR
VAR_OUTPUT
    Filler_Running : Bool;
    CIP_Active : Bool;
    Valve_Open : Bool;
    Pump_Speed : Real;
    Cap_Sorter_Running : Bool;
    Cap_Sorter_Speed : Real;
    Fault_Active : Bool;
    Fault_Code : Int;
END_VAR
VAR
    State : Int; // 0: Idle, 1: Filling, 2: CIP, 99: Fault
    CIP_Step : Int;
    Timer : TON;
    Drive_Fault : Bool;
END_VAR

BEGIN
    // Profinet Diagnostics
    Drive_Fault := (PN_Status_Word AND 16#0008) <> 0; // Check bit 3 for drive fault

    IF Drive_Fault THEN
        State := 99;
        Fault_Code := 101; // Drive Fault
    ELSIF Stop THEN
        State := 0;
    ELSIF CIP_Start AND State = 0 THEN
        State := 2;
    ELSIF Start AND State = 0 THEN
        State := 1;
    END_IF;

    CASE State OF
        0: // Idle
            Filler_Running := FALSE;
            CIP_Active := FALSE;
            Valve_Open := FALSE;
            Pump_Speed := 0.0;
            Cap_Sorter_Running := FALSE;
            Cap_Sorter_Speed := 0.0;
            Fault_Active := FALSE;
            Fault_Code := 0;
        1: // Filling
            Filler_Running := TRUE;
            CIP_Active := FALSE;
            Pump_Speed := Speed_Setpoint;
            Valve_Open := Bottle_Present;

            IF NOT Cap_Level_Low THEN
                Cap_Sorter_Running := TRUE;
                Cap_Sorter_Speed := Speed_Setpoint * 1.1;
            ELSE
                Cap_Sorter_Running := FALSE;
                Cap_Sorter_Speed := 0.0;
                State := 99;
                Fault_Code := 201; // Cap Starvation
            END_IF;
        2: // CIP Sequence
            Filler_Running := FALSE;
            CIP_Active := TRUE;
            Pump_Speed := 50.0;
            Cap_Sorter_Running := FALSE;
            Cap_Sorter_Speed := 0.0;
            CASE CIP_Step OF
                0:
                    Valve_Open := TRUE;
                    Timer(IN:=TRUE, PT:=T#5m);
                    IF Timer.Q THEN CIP_Step := 1; Timer(IN:=FALSE, PT:=T#5m); END_IF;
                1:
                    Valve_Open := TRUE;
                    Timer(IN:=TRUE, PT:=T#10m);
                    IF Timer.Q THEN CIP_Step := 2; Timer(IN:=FALSE, PT:=T#10m); END_IF;
                2:
                    Valve_Open := TRUE;
                    Timer(IN:=TRUE, PT:=T#5m);
                    IF Timer.Q THEN CIP_Step := 0; State := 0; Timer(IN:=FALSE, PT:=T#5m); END_IF;
            END_CASE;
        99: // Fault
            Filler_Running := FALSE;
            CIP_Active := FALSE;
            Valve_Open := FALSE;
            Pump_Speed := 0.0;
            Cap_Sorter_Running := FALSE;
            Cap_Sorter_Speed := 0.0;
            Fault_Active := TRUE;
            IF NOT Drive_Fault AND Stop THEN
                State := 0; // Reset fault via Stop button once condition clears
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK
