            Filler_Running := FALSE; CIP_Active := TRUE;
            Pump1_Speed := 50.0; Pump2_Speed := 50.0; // Both pumps run for CIP
            CASE CIP_Step OF
                0: Valve_Open := TRUE; Timer(IN:=TRUE, PT:=T#5m); IF Timer.Q THEN CIP_Step:=1; Timer(IN:=FALSE, PT:=T#5m); END_IF; SCADA_Diag := 'CIP: PRE-RINSE';
