Here is the Base Code for the packaging machine coordinating a flying shear and Form-Fill-Seal synchronization in IEC 61131-3 Beckhoff Structured Text (ST):

```iecst
PROGRAM MAIN
VAR
    MasterAxis : AXIS_REF;
    ShearAxis : AXIS_REF;
    FfsAxis : AXIS_REF;

    fbGearInShear : MC_GearIn;
    fbGearInFfs : MC_GearIn;
    fbCamInShear : MC_CamIn;
    fbPowerMaster : MC_Power;
    fbPowerShear : MC_Power;
    fbPowerFfs : MC_Power;

    bEnable : BOOL;
    eState : (INIT, POWER_ON, SYNC, RUNNING, STOPPING, ERROR);
END_VAR

CASE eState OF
    INIT:
        bEnable := TRUE;
        eState := POWER_ON;

    POWER_ON:
        fbPowerMaster(Axis := MasterAxis, Enable := bEnable, Enable_Positive := bEnable, Enable_Negative := bEnable);
        fbPowerShear(Axis := ShearAxis, Enable := bEnable, Enable_Positive := bEnable, Enable_Negative := bEnable);
        fbPowerFfs(Axis := FfsAxis, Enable := bEnable, Enable_Positive := bEnable, Enable_Negative := bEnable);

        IF fbPowerMaster.Status AND fbPowerShear.Status AND fbPowerFfs.Status THEN
            eState := SYNC;
        END_IF

    SYNC:
        // Synchronize FFS axis to master
        fbGearInFfs(
            Master := MasterAxis, 
            Slave := FfsAxis, 
            Execute := TRUE, 
            RatioNumerator := 1, 
            RatioDenominator := 1);

        // Synchronize Shear axis using Cam for flying shear profile
        fbCamInShear(
            Master := MasterAxis,
            Slave := ShearAxis,
            Execute := TRUE,
            CamTableID := 1);

        IF fbGearInFfs.InGear AND fbCamInShear.InSync THEN
            eState := RUNNING;
        END_IF

    RUNNING:
        // Machine is running
        IF NOT bEnable THEN
            eState := STOPPING;
        END_IF

    STOPPING:
        // Halt logic here
        eState := INIT;

    ERROR:
        // Error handling
END_CASE
