CASE CIP_State OF
    0: // Idle
        IF CIP_Start THEN CIP_State := 1; END_IF;
    1: // Pre-Rinse
        Valve_FDV_Divert := 1;
        IF Rinse_Complete THEN CIP_State := 2; END_IF;
    2: // Wash (Caustic)
        IF Wash_Complete THEN CIP_State := 3; END_IF;
    3: // Post-Rinse
        IF Post_Rinse_Complete THEN CIP_State := 4; END_IF;
    4: // Sanitize
        IF Sanitize_Complete THEN CIP_State := 0; END_IF;
END_CASE;

// 3. Lethality (F0) Tracking (Only during Production)
IF Mode_Production AND Temp_Hold_Tube > 100.0 THEN
    Lethality_Rate := 10.0 ** ((Temp_Hold_Tube - 121.1) / 10.0);
    F0_Accumulation := F0_Accumulation + (Lethality_Rate * (D_t / 60.0));
ELSIF Mode_CIP OR Mode_Idle THEN
    F0_Accumulation := 0.0;
END_IF;

// 4. Flow Diversion Valve (FDV) Logic
// Legal pasteurization requires Temp > Min_Temp OR F0 > Target_F0
IF Mode_Production THEN
    IF (Temp_Hold_Tube >= Min_Pasteurization_Temp) AND (F0_Accumulation >= F0_Target) THEN
        // Forward Flow
        Valve_FDV_Forward := 1;
        Valve_FDV_Divert := 0;
        Legal_Flow_Time := Legal_Flow_Time + D_t;
    ELSE
        // Divert Flow (Sub-legal)
        Valve_FDV_Forward := 0;
        Valve_FDV_Divert := 1;
        Legal_Flow_Time := 0;
    END_IF;
ELSE
    // Default to divert if not in production
    Valve_FDV_Forward := 0;
    Valve_FDV_Divert := 1;
END_IF;

// Allen-Bradley ST: Pasteurizer with Cascade Control, F0 Tracking, CIP, MSG Ethernet/IP, and Diagnostics
// 1. Sensor Diagnostics
Fault_Temp_Hold_Tube := (Temp_Hold_Tube < -50.0) OR (Temp_Hold_Tube > 200.0) OR (Temp_Hold_Tube_Status <> 16#0000);
Fault_Temp_Prod := (Temp_Product < -50.0) OR (Temp_Product > 200.0);
Fault_Flow_Meter := (Flow_Rate < 0.0) OR (Flow_Rate > Max_Flow);

IF Fault_Temp_Hold_Tube OR Fault_Temp_Prod OR Fault_Flow_Meter THEN
    System_Fault := 1;
    Mode_Production := 0; // Abort production
END_IF;

// 2. Cascade Control
IF NOT System_Fault THEN
    Master_PID.PV := Temp_Product;
    Master_PID.SP := Product_Temp_SP;
    Master_PID();
    Slave_PID.PV := Temp_Heating_Medium;
    Slave_PID.SP := Master_PID.CVEU;
    Slave_PID();
    Valve_Steam := Slave_PID.CVEU;
ELSE
    Valve_Steam := 0.0; // Fail-safe closed
END_IF;

// 3. F0 Tracking & FDV Logic
IF Mode_Production AND NOT System_Fault THEN
    IF Temp_Hold_Tube > 100.0 THEN
        Lethality_Rate := 10.0 ** ((Temp_Hold_Tube - 121.1) / 10.0);
        F0_Accumulation := F0_Accumulation + (Lethality_Rate * (D_t / 60.0));
    END_IF;

    IF (Temp_Hold_Tube >= Min_Past_Temp) AND (F0_Accumulation >= F0_Target) THEN
        Valve_FDV_Forward := 1; Valve_FDV_Divert := 0;
    ELSE
        Valve_FDV_Forward := 0; Valve_FDV_Divert := 1;
    END_IF;
ELSE
    Valve_FDV_Forward := 0; Valve_FDV_Divert := 1;
    IF NOT Mode_Production THEN F0_Accumulation := 0.0; END_IF;
END_IF;

// 4. Ethernet/IP Messaging to Historian
// Send F0, Temp, and Status to Historian PLC using MSG
MSG_Historian.MessageCode := 16#004C; // CIP Data Table Write
MSG_Historian.TargetNode := Historian_IP_Address;
// Setup Payload
Historian_Payload.F0 := F0_Accumulation;
Historian_Payload.Temp := Temp_Hold_Tube;
Historian_Payload.Fault := System_Fault;
// Trigger MSG periodically
Timer_MSG(IN := NOT Timer_MSG.Q, PT := 1000); // 1 sec interval
IF Timer_MSG.Q AND NOT MSG_Historian.EN THEN
    MSG_Historian();
END_IF;

// Allen-Bradley ST: Pasteurizer System with Cybersecurity, Failover, and SCADA heartbeat
// REASONING: 
// 1. IEC 62443 specifies Role-Based Access Control (RBAC). Changes to critical parameters like F0 target 
//    require an operator with Supervisor credentials (Level 2).
// 2. Redundancy: A pasteurizer is a critical CCP (Critical Control Point). Dual sensors with deviation 
//    alarms ensure safety. If deviation exceeds tolerance, we fail to the lowest temp (safest for pasteurization).
// 3. SCADA Heartbeat: Ensures we do not continue forward flow if SCADA loses connection and cannot record legal data.

// 1. Cybersecurity (IEC 62443 RBAC)
IF HMI_SecurityLevel >= 2 THEN
    // Supervisor Access
    IF HMI_Change_Target_Req THEN
        F0_Target := HMI_New_F0_Target;
        Min_Past_Temp := HMI_New_Min_Temp;
        HMI_Change_Target_Req := 0;
    END_IF;
ELSE
    HMI_Change_Target_Req := 0; // Deny access
    Security_Violation := 1;
END_IF;

// 2. Sensor Redundancy & Failover
Diff_Hold_Temp := ABS(Temp_Hold_Tube_A - Temp_Hold_Tube_B);
IF Diff_Hold_Temp > Max_Deviation THEN
    Alarm_Sensor_Deviation := 1;
    // Fail-safe logic: Use the lowest reading for F0 calc to ensure lethality is met
    Active_Temp_Hold := MIN(Temp_Hold_Tube_A, Temp_Hold_Tube_B);
