TON_SCADA_Loss(IN := (SCADA_Heartbeat = Last_SCADA_Heartbeat), PT := 5000); // 5 sec timeout
Last_SCADA_Heartbeat := SCADA_Heartbeat;
IF TON_SCADA_Loss.Q THEN
    Alarm_SCADA_Comm_Loss := 1;
ELSE
    Alarm_SCADA_Comm_Loss := 0;
END_IF;

// 4. Cascade Control (Using Active Temp)
Master_PID.PV := Active_Temp_Hold; // Using active hold tube temp as proxy or prod temp
Master_PID.SP := Product_Temp_SP;
Master_PID();
Slave_PID.PV := Temp_Heating_Medium;
Slave_PID.SP := Master_PID.CVEU;
Slave_PID();
Valve_Steam := Slave_PID.CVEU;

// 5. F0 Tracking & FDV with SCADA Interlock
IF Mode_Production AND NOT Alarm_SCADA_Comm_Loss THEN
    IF Active_Temp_Hold > 100.0 THEN
        Lethality_Rate := 10.0 ** ((Active_Temp_Hold - 121.1) / 10.0);
        F0_Accumulation := F0_Accumulation + (Lethality_Rate * (D_t / 60.0));
    END_IF;

    IF (Active_Temp_Hold >= Min_Past_Temp) AND (F0_Accumulation >= F0_Target) THEN
        Valve_FDV_Forward := 1; Valve_FDV_Divert := 0;
    ELSE
        Valve_FDV_Forward := 0; Valve_FDV_Divert := 1;
    END_IF;
ELSE
    Valve_FDV_Forward := 0; Valve_FDV_Divert := 1; // Divert on SCADA loss
END_IF;

// Allen-Bradley ST: Pasteurizer with Cascade Control, F0, FDV, CIP, Diagnostics, RBAC, SCADA, Drift Detection, Self-Test
// 1. Digital Twin Sync & Sensor Drift Detection
// Digital_Twin_Temp is calculated by HIL simulation based on steam flow and product flow energy balance.
Drift_Sensor_A := ABS(Temp_Hold_Tube_A - Digital_Twin_Temp);
Drift_Sensor_B := ABS(Temp_Hold_Tube_B - Digital_Twin_Temp);

IF (Drift_Sensor_A > Drift_Threshold) AND (Drift_Sensor_B > Drift_Threshold) THEN
    // Both sensors deviated from digital twin -> Process Anomaly / Adversarial condition
    Critical_Drift_Alarm := 1;
ELSIF Drift_Sensor_A > Drift_Threshold THEN
    Active_Temp_Hold := Temp_Hold_Tube_B; // Isolate A
    Warning_Drift_A := 1;
ELSIF Drift_Sensor_B > Drift_Threshold THEN
    Active_Temp_Hold := Temp_Hold_Tube_A; // Isolate B
    Warning_Drift_B := 1;
ELSE
    Active_Temp_Hold := MIN(Temp_Hold_Tube_A, Temp_Hold_Tube_B); // Safe baseline
