Here is the Base Code for an Industrial Dough Mixer in Beckhoff ST (TwinCAT 3):

```iecst
TYPE E_MixerState :
(
    INIT,
    IDLE,
    PHASE_EXECUTION,
    DONE,
    ERROR
);
END_TYPE

TYPE ST_RecipePhase :
STRUCT
    nDurationMs   : UDINT;
    rTargetSpeed  : REAL; // rpm
    rTargetViscosity : REAL; // Pas
END_STRUCT
END_TYPE

PROGRAM MAIN
VAR
    eState        : E_MixerState := E_MixerState.INIT;
    aRecipe       : ARRAY[1..3] OF ST_RecipePhase;
    nCurrentPhase : INT := 1;

    // I/O
    bStart        AT %I* : BOOL;
    rMotorTorque  AT %I* : REAL;
    rMotorSpeed   AT %Q* : REAL;

    // Viscosity calculation
    rCalculatedViscosity : REAL;

    fbTimer : TON;
END_VAR

CASE eState OF
    E_MixerState.INIT:
        aRecipe[1].nDurationMs := 60000; aRecipe[1].rTargetSpeed := 30.0; aRecipe[1].rTargetViscosity := 50.0;
        aRecipe[2].nDurationMs := 120000; aRecipe[2].rTargetSpeed := 60.0; aRecipe[2].rTargetViscosity := 80.0;
        aRecipe[3].nDurationMs := 30000; aRecipe[3].rTargetSpeed := 15.0; aRecipe[3].rTargetViscosity := 40.0;
        eState := E_MixerState.IDLE;

    E_MixerState.IDLE:
        rMotorSpeed := 0.0;
        nCurrentPhase := 1;
        IF bStart THEN
            eState := E_MixerState.PHASE_EXECUTION;
        END_IF

    E_MixerState.PHASE_EXECUTION:
        rMotorSpeed := aRecipe[nCurrentPhase].rTargetSpeed;

        // Pseudo-viscosity profile: Viscosity is proportional to Torque / Speed
        IF rMotorSpeed > 0.1 THEN
            rCalculatedViscosity := rMotorTorque / rMotorSpeed * 9.55; 
        END_IF

        fbTimer(IN := TRUE, PT := UDINT_TO_TIME(aRecipe[nCurrentPhase].nDurationMs));

        IF fbTimer.Q THEN
            fbTimer(IN := FALSE);
            nCurrentPhase := nCurrentPhase + 1;
            IF nCurrentPhase > 3 THEN
                eState := E_MixerState.DONE;
            END_IF
        END_IF

    E_MixerState.DONE:
        rMotorSpeed := 0.0;
        IF NOT bStart THEN
            eState := E_MixerState.IDLE;
        END_IF

    E_MixerState.ERROR:
        rMotorSpeed := 0.0;
END_CASE
```

