    rMotorTorque  AT %I* : REAL;
    rDoughTemp    AT %I* : REAL;
    rMotorSpeed   AT %Q* : REAL;
    rJacketValve  AT %Q* : REAL; // -100 (cooling) to 100 (heating)

    rCalculatedViscosity : REAL;
    fbTimer : TON;

    // PID Temp Control
    fbPidTemp : FB_BasicPID;
END_VAR

CASE eState OF
    E_MixerState.INIT:
        aRecipe[1].nDurationMs := 60000; aRecipe[1].rTargetSpeed := 30.0; aRecipe[1].rTargetTemp := 24.0;
        aRecipe[2].nDurationMs := 120000; aRecipe[2].rTargetSpeed := 60.0; aRecipe[2].rTargetTemp := 26.0;
        aRecipe[3].nDurationMs := 30000; aRecipe[3].rTargetSpeed := 15.0; aRecipe[3].rTargetTemp := 22.0;
        eState := E_MixerState.IDLE;

    E_MixerState.IDLE:
        rMotorSpeed := 0.0;
        rJacketValve := 0.0;
        nCurrentPhase := 1;
        fbPidTemp(bReset := TRUE);
        IF bStart THEN
            eState := E_MixerState.PHASE_EXECUTION;
        END_IF

    E_MixerState.PHASE_EXECUTION:
        rMotorSpeed := aRecipe[nCurrentPhase].rTargetSpeed;
        IF rMotorSpeed > 0.1 THEN rCalculatedViscosity := rMotorTorque / rMotorSpeed * 9.55; END_IF

        fbPidTemp(
            fSetpointValue := aRecipe[nCurrentPhase].rTargetTemp,
            fActualValue   := rDoughTemp,
            bReset         := FALSE,
            fCtrlCycleTime := 0.01,
            fKp := 2.5, fTn := 10.0, fTv := 0.0,
            fCtrlOutput    => rJacketValve
        );

        fbTimer(IN := TRUE, PT := UDINT_TO_TIME(aRecipe[nCurrentPhase].nDurationMs));
        IF fbTimer.Q THEN
            fbTimer(IN := FALSE);
            nCurrentPhase := nCurrentPhase + 1;
            IF nCurrentPhase > 3 THEN eState := E_MixerState.DONE; END_IF
        END_IF

    E_MixerState.DONE:
        rMotorSpeed := 0.0;
        fbPidTemp(bReset := TRUE);
        IF NOT bStart THEN eState := E_MixerState.IDLE; END_IF

    E_MixerState.ERROR:
        rMotorSpeed := 0.0;
        rJacketValve := 0.0;
END_CASE
