PROGRAM MAIN
VAR
    eState : E_MixerState := E_MixerState.INIT;
    // ... [Previous variables] ...

    // Diagnostics & Faults
    fbEcMasterState : FB_EcGetMasterState;
    sNetId          : T_AmsNetId := '192.168.1.2.1.1';
    bEcError        : BOOL;
    aFaults         : ARRAY[1..10] OF BOOL;
    bAckFault       AT %I* : BOOL;
END_VAR

// Diagnostic cyclic call
fbEcMasterState(sNetId := sNetId, bExecute := TRUE);
IF fbEcMasterState.bError OR fbEcMasterState.state <> 8 THEN // 8 = OP state
    aFaults[1] := TRUE; // EtherCAT Bus Fault
END_IF

// Fault Management
IF aFaults[1] OR aFaults[2] THEN // E.g., aFaults[2] could be motor over-temp
    eState := E_MixerState.ERROR;
END_IF

CASE eState OF
    // ... [INIT and IDLE states similar to Mutation 1] ...
    E_MixerState.IDLE:
        IF bStart AND NOT bEcError THEN eState := E_MixerState.PHASE_EXECUTION; END_IF

    E_MixerState.PHASE_EXECUTION:
        // [Viscosity and PID logic]
        // Watchdog on temperature
        IF rDoughTemp > 45.0 THEN
            aFaults[2] := TRUE; // Critical temp fault
        END_IF
        // [Timer logic]

    E_MixerState.ERROR:
        rMotorSpeed := 0.0;
        rJacketValve := 0.0;
        IF bAckFault THEN
            MEMSET(ADR(aFaults), 0, SIZEOF(aFaults));
            IF NOT bEcError THEN eState := E_MixerState.IDLE; END_IF
        END_IF
END_CASE
