```iecst
TYPE ST_ScadaTelemetry :
STRUCT {attribute 'OPC.UA.DA' := '1'}
    eCurrentState    : E_MixerState;
    rViscosity       : REAL;
    rDoughTemp       : REAL;
    nCurrentPhase    : INT;
    bFailoverActive  : BOOL;
END_STRUCT
END_TYPE

PROGRAM MAIN
VAR
    stScadaData      : ST_ScadaTelemetry;
    nUserRole AT %I* : INT; // 0=Guest, 1=Operator, 2=Admin (IEC 62443 RBAC concept)

    // Failover Heartbeat
    bPrimaryHeartbeat AT %I* : BOOL;
    bIsSecondary      AT %I* : BOOL;
    fbHeartbeatTimer  : TON;
    bTakeover         : BOOL;

    // ... [Previous variables] ...
END_VAR

// Failover Logic
fbHeartbeatTimer(IN := NOT bPrimaryHeartbeat, PT := T#500MS);
IF bIsSecondary AND fbHeartbeatTimer.Q THEN
    bTakeover := TRUE;
    stScadaData.bFailoverActive := TRUE;
END_IF

// SCADA Telemetry Update
stScadaData.eCurrentState := eState;
stScadaData.rViscosity := rCalculatedViscosity;
stScadaData.rDoughTemp := rDoughTemp;
stScadaData.nCurrentPhase := nCurrentPhase;

CASE eState OF
    E_MixerState.IDLE:
        // RBAC: Only Operator(1) or Admin(2) can start the mixer
        IF bStart AND (nUserRole >= 1) AND (NOT bIsSecondary OR bTakeover) THEN
            eState := E_MixerState.PHASE_EXECUTION;
        END_IF

    E_MixerState.PHASE_EXECUTION:
        // [Viscosity, PID, Timer, Faults]
        // RBAC: Admin can force next phase
        IF bForceNext AT %I* AND nUserRole = 2 THEN
            fbTimer(IN := FALSE);
            nCurrentPhase := nCurrentPhase + 1;
        END_IF

    E_MixerState.ERROR:
        // RBAC: Only Admin can acknowledge critical faults
        IF bAckFault AND nUserRole = 2 THEN
            MEMSET(ADR(aFaults), 0, SIZEOF(aFaults));
            eState := E_MixerState.IDLE;
        END_IF
END_CASE
