    rMotorTorque := stHil.rSimTorque;
    rDoughTemp   := stHil.rSimTemp;
END_IF

// Sensor Drift Detection (Comparing duplicated sensors or simulated drift)
rTempDrift := ABS(rDoughTemp - rBaselineTemp); // Simplified drift check vs known ambient
IF eState = IDLE AND rTempDrift > 5.0 THEN
    bDriftFault := TRUE;
    eState := ERROR;
END_IF

CASE eState OF
