FUNCTION_BLOCK "RO_Skid_Control"
VERSION : 0.1
   VAR_INPUT
      Start : Bool;
      Stop : Bool;
      Feed_Pressure : Real;
      Permeate_Pressure : Real;
      Permeate_Flow : Real;
      Pressure_Setpoint : Real;
      Backwash_Req : Bool;
   END_VAR

   VAR_OUTPUT
      High_Pressure_Pump : Bool;
      Permeate_Valve : Real;
      Backwash_Pump : Bool;
      Backwash_Valve : Bool;
      Status : Int;
   END_VAR

   VAR
      State : Int;
      PID_Ctrl : "PID_Compact";
      Tmr_Backwash : TON;
   END_VAR

BEGIN
    IF Stop THEN
        State := 0;
    ELSIF Start AND State = 0 THEN
        State := 1;
    ELSIF Backwash_Req AND State = 1 THEN
        State := 2;
    END_IF;

    #PID_Ctrl(Setpoint := Pressure_Setpoint, Input := Permeate_Pressure, Reset := (State <> 1));

    CASE State OF
        0:
            High_Pressure_Pump := FALSE;
            Permeate_Valve := 0.0;
            Backwash_Pump := FALSE;
            Backwash_Valve := FALSE;
            Status := 0;
        1:
            High_Pressure_Pump := TRUE;
            Permeate_Valve := #PID_Ctrl.Output;
            Backwash_Pump := FALSE;
            Backwash_Valve := FALSE;
            Status := 1;
        2:
            High_Pressure_Pump := FALSE;
            Permeate_Valve := 0.0;
            Backwash_Valve := TRUE;
            Tmr_Backwash(IN:=TRUE, PT:=T#5m);
            IF Tmr_Backwash.Q THEN
                Backwash_Pump := FALSE;
                Backwash_Valve := FALSE;
                Tmr_Backwash(IN:=FALSE, PT:=T#5m);
                State := 0;
            ELSE
                Backwash_Pump := TRUE;
            END_IF;
            Status := 2;
    END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "RO_Skid_Control_M1"
VERSION : 0.1
   VAR_INPUT
      Start : Bool;
      Stop : Bool;
      Feed_Pressure : Real;
      Feed_Flow : Real;
      Permeate_Pressure : Real;
      Pressure_Setpoint : Real;
      Backwash_Req : Bool;
      Target_Dosing_Conc : Real;
      Pump_Capacity : Real;
   END_VAR

   VAR_OUTPUT
      High_Pressure_Pump : Bool;
      Permeate_Valve : Real;
      Backwash_Pump : Bool;
      Backwash_Valve : Bool;
      Dosing_Pump_Speed : Real;
      Status : Int;
   END_VAR

   VAR
      State : Int;
      PID_Ctrl : "PID_Compact";
      Tmr_Backwash : TON;
      Req_Dosing_Flow : Real;
   END_VAR

BEGIN
    IF Stop THEN
        State := 0;
    ELSIF Start AND State = 0 THEN
        State := 1;
    ELSIF Backwash_Req AND State = 1 THEN
        State := 2;
    END_IF;

    Req_Dosing_Flow := (Feed_Flow * Target_Dosing_Conc) / 1000.0;
    IF Pump_Capacity > 0.0 THEN
        Dosing_Pump_Speed := (Req_Dosing_Flow / Pump_Capacity) * 100.0;
    ELSE
        Dosing_Pump_Speed := 0.0;
    END_IF;

    #PID_Ctrl(Setpoint := Pressure_Setpoint, Input := Permeate_Pressure, Reset := (State <> 1));

    CASE State OF
        0:
            High_Pressure_Pump := FALSE;
            Permeate_Valve := 0.0;
            Backwash_Pump := FALSE;
            Backwash_Valve := FALSE;
            Dosing_Pump_Speed := 0.0;
            Status := 0;
        1:
            High_Pressure_Pump := TRUE;
            Permeate_Valve := #PID_Ctrl.Output;
            Backwash_Pump := FALSE;
            Backwash_Valve := FALSE;
            Status := 1;
        2:
            High_Pressure_Pump := FALSE;
            Permeate_Valve := 0.0;
            Backwash_Valve := TRUE;
            Dosing_Pump_Speed := 0.0;
            Tmr_Backwash(IN:=TRUE, PT:=T#5m);
            IF Tmr_Backwash.Q THEN
                Backwash_Pump := FALSE;
                Backwash_Valve := FALSE;
                Tmr_Backwash(IN:=FALSE, PT:=T#5m);
                State := 0;
            ELSE
                Backwash_Pump := TRUE;
            END_IF;
            Status := 2;
    END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "RO_Skid_Control_M2"
VERSION : 0.1
   VAR_INPUT
      Start : Bool;
      Stop : Bool;
      Feed_Pressure : Real;
      Permeate_Pressure : Real;
      Concentrate_Pressure : Real;
      Feed_Flow : Real;
      Pressure_Setpoint : Real;
      Target_Dosing_Conc : Real;
      Pump_Capacity : Real;
      VFD_Status_Word : Word;
      Ack_Faults : Bool;
   END_VAR

   VAR_OUTPUT
      VFD_Control_Word : Word;
      VFD_Speed_Ref : Real;
      Permeate_Valve : Real;
      Backwash_Pump : Bool;
      Backwash_Valve : Bool;
      Dosing_Pump_Speed : Real;
      Fault_DryRun : Bool;
      Fault_Fouling : Bool;
      Fault_VFD : Bool;
      Status : Int;
   END_VAR

   VAR
      State : Int;
      PID_Ctrl : "PID_Compact";
      Tmr_Backwash : TON;
      Tmr_DryRun : TON;
      Diff_Pressure : Real;
   END_VAR

BEGIN
    Fault_VFD := (VFD_Status_Word AND 16#0008) <> 0;

    Tmr_DryRun(IN := (Feed_Pressure < 1.0) AND (State = 1), PT := T#5s);
    IF Tmr_DryRun.Q THEN
        Fault_DryRun := TRUE;
    END_IF;

    Diff_Pressure := Feed_Pressure - Concentrate_Pressure;
    IF Diff_Pressure > 5.0 THEN
        Fault_Fouling := TRUE;
    END_IF;

    IF Ack_Faults THEN
        Fault_DryRun := FALSE;
        Fault_Fouling := FALSE;
        Fault_VFD := FALSE;
    END_IF;

    IF Fault_DryRun OR Fault_Fouling OR Fault_VFD OR Stop THEN
        State := 0;
    ELSIF Start AND State = 0 THEN
        State := 1;
    END_IF;

    IF State = 1 AND Pump_Capacity > 0.0 THEN
        Dosing_Pump_Speed := ((Feed_Flow * Target_Dosing_Conc) / 1000.0 / Pump_Capacity) * 100.0;
    ELSE
        Dosing_Pump_Speed := 0.0;
    END_IF;

    #PID_Ctrl(Setpoint := Pressure_Setpoint, Input := Permeate_Pressure, Reset := (State <> 1));

    CASE State OF
        0:
            VFD_Control_Word := 16#047E;
            VFD_Speed_Ref := 0.0;
            Permeate_Valve := 0.0;
            Status := 0;
        1:
            VFD_Control_Word := 16#047F;
            VFD_Speed_Ref := 100.0;
            Permeate_Valve := #PID_Ctrl.Output;
            Status := 1;
    END_CASE;
END_FUNCTION_BLOCK

TYPE "SCADA_Event"
   STRUCT
      EventID : Int;
      Timestamp : DTL;
      Active : Bool;
   END_STRUCT;
END_TYPE

FUNCTION_BLOCK "RO_Skid_Control_M3"
   VAR_INPUT
      Start : Bool;
      Stop : Bool;
      Manual_Override : Bool;
      User_Role_Level : Int;
      Partner_PLC_Heartbeat : Bool;
   END_VAR

   VAR_OUTPUT
      SCADA_Events : Array[1..10] of "SCADA_Event";
      Primary_Active : Bool;
   END_VAR

   VAR
      State : Int;
      Heartbeat_Tmr : TON;
      Prev_Heartbeat : Bool;
   END_VAR

BEGIN
    Heartbeat_Tmr(IN := (Partner_PLC_Heartbeat = Prev_Heartbeat), PT := T#2s);
    IF Heartbeat_Tmr.Q THEN
        Primary_Active := TRUE;
    END_IF;
    Prev_Heartbeat := Partner_PLC_Heartbeat;

    IF Manual_Override THEN
        IF User_Role_Level >= 2 THEN
            State := 99;
        ELSE
            SCADA_Events[1].EventID := 403;
            SCADA_Events[1].Timestamp := RD_SYS_T();
            SCADA_Events[1].Active := TRUE;
        END_IF;
    END_IF;

    IF State = 99 THEN
        ;
    ELSIF Stop THEN
        State := 0;
    ELSIF Start AND Primary_Active THEN
        State := 1;
    END_IF;

    SCADA_Events[2].EventID := 100 + State;
    SCADA_Events[2].Timestamp := RD_SYS_T();
    SCADA_Events[2].Active := (State = 1);
END_FUNCTION_BLOCK

FUNCTION_BLOCK "RO_Skid_Control_M4"
   VAR_INPUT
      Start : Bool;
      HIL_Simulation_Mode : Bool;
      Permeate_Press_Tx1 : Real;
      Permeate_Press_Tx2 : Real;
      Valve_Feedback_Open : Bool;
      User_Role_Level : Int;
   END_VAR

   VAR_OUTPUT
      Valve_Cmd : Bool;
      Fault_Sensor_Drift : Bool;
      Fault_SelfTest : Bool;
      State : Int;
   END_VAR

   VAR
      Sim_Permeate_Press : Real;
      Active_Press : Real;
      Test_Tmr : TON;
   END_VAR

BEGIN
    IF HIL_Simulation_Mode THEN
        Active_Press := Sim_Permeate_Press;
        Valve_Feedback_Open := Valve_Cmd;
    ELSE
        IF ABS(Permeate_Press_Tx1 - Permeate_Press_Tx2) > 0.5 THEN
            Fault_Sensor_Drift := TRUE;
            Active_Press := (Permeate_Press_Tx1 + Permeate_Press_Tx2) / 2.0;
        ELSE
            Fault_Sensor_Drift := FALSE;
            Active_Press := Permeate_Press_Tx1;
        END_IF;
    END_IF;

    CASE State OF
        0:
            IF Start THEN
                State := 10;
                Valve_Cmd := TRUE;
            END_IF;
        10:
            Test_Tmr(IN := TRUE, PT := T#3s);
            IF Valve_Feedback_Open THEN
                State := 1;
                Test_Tmr(IN := FALSE, PT := T#3s);
            ELSIF Test_Tmr.Q THEN
                Fault_SelfTest := TRUE;
