```pascal
FUNCTION_BLOCK "FB_FumeHood_Adversarial"
VAR_INPUT
    SCADA_Enable : Bool;
    FaceVelocity_PV : Real;
    SashHeight_PV : Real;
    VFD_FeedbackSpeed : Real;
    HIL_Mode_Active : Bool;
    HIL_Simulated_PV : Real;
    Unoccupied_Hours : Bool;
END_VAR
VAR_OUTPUT
    Exhaust_VFD_CV : Real;
    SensorDrift_Alarm : Bool;
    SelfTest_Active : Bool;
END_VAR
VAR
    PID_Controller : "PID_Compact";
    Active_PV : Real;
    Calculated_Velocity : Real;
    SashArea : Real;
    SelfTest_Step : Int;
    SelfTest_Timer : TON;
END_VAR

BEGIN
    // HIL Digital Twin Synchronization
    IF #HIL_Mode_Active THEN
        #Active_PV := #HIL_Simulated_PV;
    ELSE
        #Active_PV := #FaceVelocity_PV;
    END_IF;

    // Adversarial Sensor Drift Detection
    // Area = Height * Width (1.2m)
    #SashArea := #SashHeight_PV * 1.2;
    IF #SashArea > 0.05 THEN
        // Simplified aerodynamic calculation: Velocity = Flow(VFD_Speed) / Area
        #Calculated_Velocity := (#VFD_FeedbackSpeed * 0.02) / #SashArea;
        IF ABS(#Calculated_Velocity - #Active_PV) > 0.15 THEN
            #SensorDrift_Alarm := TRUE;
        ELSE
            #SensorDrift_Alarm := FALSE;
        END_IF;
    END_IF;

    // Automated Self-Test Routine during unoccupied hours
    IF #Unoccupied_Hours AND NOT #HIL_Mode_Active THEN
        #SelfTest_Active := TRUE;
        #SelfTest_Timer(IN := TRUE, PT := T#5s);

        IF #SelfTest_Timer.Q THEN
            #SelfTest_Step := #SelfTest_Step + 1;
            #SelfTest_Timer(IN := FALSE);
        END_IF;

        CASE #SelfTest_Step OF
            0: #Exhaust_VFD_CV := 20.0;
            1: #Exhaust_VFD_CV := 50.0;
            2: #Exhaust_VFD_CV := 100.0;
            3: 
               #Exhaust_VFD_CV := 0.0;
               #SelfTest_Step := 0;
               #SelfTest_Active := FALSE;
        END_CASE;

        #PID_Controller(Reset := TRUE);
    ELSE
        // Standard PID Control
        #SelfTest_Active := FALSE;
        #PID_Controller(
            Setpoint := 0.5,
            Input := #Active_PV,
            Reset := NOT #SCADA_Enable,
            Output => #Exhaust_VFD_CV
        );
    END_IF;
END_FUNCTION_BLOCK
