    bZoneActive : BOOL;
    aFaults : ARRAY[1..64] OF BOOL;
    i : INT;

    fDriftThreshold : REAL := 50.0; // Max acceptable deviation in Lux
END_VAR

// Update Real-Time Clock
fbRTC(EN := TRUE, PDT := dtCurrentTime);

// IEC 62443 Parameter Validation
IF fTargetLightLevel < 100.0 THEN fTargetLightLevel := 100.0; END_IF
IF fTargetLightLevel > 1000.0 THEN fTargetLightLevel := 1000.0; END_IF

// Sensor Drift Detection & Failover / HIL Sync
IF bHIL_Mode THEN
    fActiveAmbientLight := fAmbientLightHIL; // Digital Twin takes over
    bSensorDriftAlarm := FALSE;
ELSE
    bSensorDriftAlarm := ABS(fAmbientLightPrimary - fAmbientLightSecondary) > fDriftThreshold;

    IF NOT bPrimarySensorFault AND NOT bSensorDriftAlarm THEN
        fActiveAmbientLight := fAmbientLightPrimary;
    ELSIF NOT bPrimarySensorFault AND bSensorDriftAlarm THEN
        fActiveAmbientLight := (fAmbientLightPrimary + fAmbientLightSecondary) / 2.0; // Average if drifting
    ELSE
        fActiveAmbientLight := fAmbientLightSecondary;
    END_IF
END_IF

// Midnight Self-Test Routine
IF DT_TO_TOD(dtCurrentTime) = TOD#00:00:00 THEN
    bSelfTestActive := TRUE;
    nTestStep := 1;
END_IF

fbTestTimer(IN := bSelfTestActive, PT := T#5S);
IF bSelfTestActive THEN
    IF fbTestTimer.Q THEN
        IF nTestStep = 1 THEN
            nTestStep := 2; // Step 2: Test 100%
            fbTestTimer(IN := FALSE);
        ELSIF nTestStep = 2 THEN
            bSelfTestActive := FALSE; // End Test
            fbTestTimer(IN := FALSE);
        END_IF
    END_IF
END_IF

// Fault Diagnostics
bGlobalFault := FALSE;
FOR i := 1 TO 64 DO
    IF (aDALI_Status[i] AND 16#03) <> 0 THEN
        aFaults[i] := TRUE;
        bGlobalFault := TRUE;
    ELSE
        aFaults[i] := FALSE;
    END_IF
END_FOR

fbTimerOffDelay(IN := bPresenceDetected, PT := T#15M, Q => bZoneActive);

fbPID(
    fSetpoint := fTargetLightLevel,
    fActualValue := fActiveAmbientLight,
    bReset := NOT bZoneActive OR bSelfTestActive,
    fKp := 0.5, fTn := 2.0, fTv := 0.0,
    fOutMaxLimit := 100.0, fOutMinLimit := 10.0,
    fCtrlOutput => fPIDOutput
);

// Output Generation
FOR i := 1 TO 64 DO
    IF aFaults[i] THEN
        aDALI_ControlLevels[i] := 0;
    ELSIF bSelfTestActive THEN
        IF nTestStep = 1 THEN
            aDALI_ControlLevels[i] := 0; // 0%
        ELSE
            aDALI_ControlLevels[i] := 255; // 100%
        END_IF
    ELSIF bZoneActive THEN
        aDALI_ControlLevels[i] := REAL_TO_BYTE(fPIDOutput * 2.55);
    ELSE
        aDALI_ControlLevels[i] := 0;
    END_IF
END_FOR
