    fCondenserVaporTempSP : LREAL := 45.0;

    // Controllers
    fbRefluxPID           : FB_BasicPID;
    fbReboilerPID         : FB_BasicPID;
    fbCondMasterPID       : FB_BasicPID; // Master: Vapor Temp
    fbCondSlavePID        : FB_BasicPID; // Slave: Cooling Water Temp

    // Intermediate Variables
    fCoolingWaterTempSP   : LREAL; // Output of Master PID

    // Control Outputs
    fRefluxValve          AT %Q* : LREAL;
    fReboilerValve        AT %Q* : LREAL;
    fCoolingWaterValve    AT %Q* : LREAL;
END_VAR

// 1. Reflux Ratio Control
fbRefluxPID(fSetpointValue := fTopTempSP, fActualValue := fTopTemp, fKp := 2.5, fTn := 15.0, bReverseAction := TRUE, fCtrlOutput => fRefluxValve);

// 2. Reboiler Steam Control
fbReboilerPID(fSetpointValue := fBottomTempSP, fActualValue := fBottomTemp, fKp := 1.8, fTn := 20.0, bReverseAction := FALSE, fCtrlOutput => fReboilerValve);

// 3. Condenser Cascade Control
// Master loop: Regulates Vapor Temp, outputs a setpoint for water temp (e.g., 20 to 40 C limit)
fbCondMasterPID(
    fSetpointValue := fCondenserVaporTempSP,
    fActualValue   := fCondenserVaporTemp,
    fKp            := 1.2,
    fTn            := 30.0,
    fOutMinLimit   := 20.0,
    fOutMaxLimit   := 40.0,
    fCtrlOutput    => fCoolingWaterTempSP
);

// Slave loop: Achieves the desired cooling water return temperature
fbCondSlavePID(
    fSetpointValue := fCoolingWaterTempSP,
    fActualValue   := fCoolingWaterRetTemp,
    fKp            := 4.0,
    fTn            := 5.0,
    bReverseAction := TRUE,
    fCtrlOutput    => fCoolingWaterValve
);
