    nState                : INT := 0; // 0=Self-Test, 1=HIL Sync, 2=Run, 3=Fault

    // Sensor Drift Detection
    fTopTemp_A            AT %I* : LREAL;
    fTopTemp_B            AT %I* : LREAL;
    fDriftThreshold       : LREAL := 2.5; // Max allowed deviation [C]
    bDriftAlarm           : BOOL;
