Fault_pH_1 := (pH_PV_1 < 0.0) OR (pH_PV_1 > 14.0);
Fault_pH_2 := (pH_PV_2 < 0.0) OR (pH_PV_2 > 14.0);

IF NOT Fault_pH_1 THEN
