FUNCTION_BLOCK FB_ExtruderControl
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    MeltPressure_SP : REAL; // Setpoint for melt pressure (bar)
    MeltPressure_PV : REAL; // Process value for melt pressure (bar)
    ScrewSpeed_Manual : REAL; // Manual screw speed (rpm)
    AutoMode : BOOL;
END_VAR
VAR_OUTPUT
    ScrewSpeed_CV : REAL; // Control variable to drive (rpm)
    Running : BOOL;
    Fault : BOOL;
END_VAR
VAR
    PID_Ctrl : PID_Compact;
    State : INT := 0;
END_VAR

BEGIN
    // State machine for basic control
    IF Stop THEN
        State := 0;
    ELSIF Start AND State = 0 THEN
        State := 1;
    END_IF;

    Running := (State = 1);

    IF State = 1 THEN
        IF AutoMode THEN
            // Cascade control: Melt pressure dictates screw speed
            PID_Ctrl(
                Setpoint := MeltPressure_SP,
                Input := MeltPressure_PV,
                Reset := FALSE
            );
            ScrewSpeed_CV := PID_Ctrl.Output;
        ELSE
            ScrewSpeed_CV := ScrewSpeed_Manual;
        END_IF;
    ELSE
        ScrewSpeed_CV := 0.0;
        PID_Ctrl(Reset := TRUE);
    END_IF;
END_FUNCTION_BLOCK
