FUNCTION_BLOCK FB_ExtruderControl_Mut4
VAR_INPUT
    MeltPressure_PV_1 : REAL;
    MeltPressure_PV_2 : REAL;
    Alpha_EWMA : REAL;
    HIL_Sync_Req : BOOL;
    StartSelfTest : BOOL;
END_VAR
VAR_OUTPUT
    DriftAlarm : BOOL;
    HIL_DataBlock : ARRAY[1..10] OF REAL;
    SelfTestPass : BOOL;
    SelfTestActive : BOOL;
END_VAR
VAR
    EWMA_Diff : REAL;
    InstDiff : REAL;
    TestStep : INT := 0;
    Safe_Alpha : REAL;
END_VAR

BEGIN
    // Adversarial Check: Prevent divide by zero or extreme alpha coefficients
    IF Alpha_EWMA <= 0.001 OR Alpha_EWMA > 1.0 THEN
        Safe_Alpha := 0.1; // Default fallback
    ELSE
        Safe_Alpha := Alpha_EWMA;
    END_IF;

    // Sensor Drift Detection via EWMA filter
    InstDiff := ABS(MeltPressure_PV_1 - MeltPressure_PV_2);
    EWMA_Diff := (Safe_Alpha * InstDiff) + ((1.0 - Safe_Alpha) * EWMA_Diff);
    DriftAlarm := (EWMA_Diff > 5.0); // Alarm if difference exceeds 5 bar

    // Automated Self-Test Routine (e.g., verifying sensor plausibility before start)
    IF StartSelfTest AND TestStep = 0 THEN
        SelfTestActive := TRUE;
        SelfTestPass := FALSE;
        TestStep := 1;
    END_IF;

    IF SelfTestActive THEN
        CASE TestStep OF
            1: // Check static pressure bounds at standstill
                IF (MeltPressure_PV_1 > -1.0) AND (MeltPressure_PV_1 < 5.0) THEN
                    TestStep := 2;
                ELSE
                    TestStep := 99; // Fail
                END_IF;
            2: // Next test steps...
                SelfTestPass := TRUE;
                SelfTestActive := FALSE;
                TestStep := 0;
            99: // Failed state
                SelfTestPass := FALSE;
                SelfTestActive := FALSE;
                TestStep := 0;
        END_CASE;
    END_IF;

    // HIL Digital Twin State Synchronization via arrays for OPC UA
    IF HIL_Sync_Req THEN
        HIL_DataBlock[1] := MeltPressure_PV_1;
        HIL_DataBlock[2] := MeltPressure_PV_2;
        HIL_DataBlock[3] := EWMA_Diff;
        // Additional state variables mapped here
    END_IF;
END_FUNCTION_BLOCK
