END_VAR
VAR
    Allowed_IP : STRING := '192.168.1.100';
    Valid_Token : DWORD := 16#A5A5_5A5A;
    HeartbeatTimeout : INT;
END_VAR

BEGIN
    // IEC 62443: Source IP & Token Authentication
    IF SCADA_IP <> Allowed_IP OR SCADA_In.AuthToken <> Valid_Token THEN
        SecurityAlert := TRUE;
        ActivePLC := FALSE;
        RETURN;
    ELSE
        SecurityAlert := FALSE;
    END_IF;

    // Failover Logic
    IF NOT PartnerPLC_Heartbeat THEN
        HeartbeatTimeout := HeartbeatTimeout + 1;
        IF HeartbeatTimeout > 50 THEN ActivePLC := TRUE; END_IF;
    ELSE
        HeartbeatTimeout := 0;
        ActivePLC := FALSE; // Assume slave unless partner dead
    END_IF;

    // SCADA Watchdog
    SCADA_Out.Watchdog_Res := SCADA_In.Watchdog_Req;

    IF ActivePLC THEN
        // Simplified Control logic for brevity
        ValvePos[0] := LIMIT(MN:=0.0, IN:=(SCADA_In.Command_SP - ProcessValues[0])*1.5, MX:=100.0);
        ValvePos[1] := LIMIT(MN:=0.0, IN:=(SCADA_In.Command_SP - ProcessValues[1])*1.5, MX:=100.0);
    ELSE
        ValvePos[0] := 0.0; ValvePos[1] := 0.0;
