    rError : REAL;
    rLastError : REAL;
    rIntegral : REAL;
    rDerivative : REAL;

    // State machine
    eState : (IDLE, CASTING, STOPPING) := IDLE;
END_VAR

CASE eState OF
    IDLE:
        rStopperPosition := 0.0;
        rOscillatorFreq := 0.0;
        rOscillatorStroke := 0.0;
        rIntegral := 0.0;

        IF bStartCasting THEN
            eState := CASTING;
