        rError := rMouldLevelSetpoint - rMouldLevelSensor;
        rIntegral := rIntegral + (rError * 0.01); // Assuming 10ms cycle
        rDerivative := (rError - rLastError) / 0.01;

        rStopperPosition := (rKp * rError) + (rKi * rIntegral) + (rKd * rDerivative);

        // Anti-windup and limits
        IF rStopperPosition > 100.0 THEN
            rStopperPosition := 100.0;
            rIntegral := rIntegral - (rError * 0.01); // Anti-windup
        ELSIF rStopperPosition < 0.0 THEN
            rStopperPosition := 0.0;
            rIntegral := rIntegral - (rError * 0.01);
        END_IF

        rLastError := rError;

        // Oscillation logic (synchronized with casting speed in a real system)
        rOscillatorFreq := 2.5; // Nominal 2.5 Hz
        rOscillatorStroke := 6.0; // Nominal 6 mm stroke

        IF bStopCasting THEN
            eState := STOPPING;
        END_IF

    STOPPING:
        // Graceful shutdown
        rStopperPosition := rStopperPosition - 1.0;
        IF rStopperPosition <= 0.0 THEN
            rStopperPosition := 0.0;
            eState := IDLE;
        END_IF
END_CASE
