PROGRAM PRG_ContinuousCasting
VAR
    // Inputs
    rMouldLevelSensor : REAL;
    rCastingSpeed : REAL; // Current casting speed m/min
    rStrandTemp : ARRAY[1..3] OF REAL; // Pyrometer readings for 3 zones
    bStartCasting : BOOL;
    bStopCasting : BOOL;

    // Outputs
    rStopperPosition : REAL;
    rOscillatorFreq : REAL;
    rOscillatorStroke : REAL;
    rCoolingWaterFlow : ARRAY[1..3] OF REAL; // Flow setpoints for 3 spray zones (L/min)

    // Control Variables
    rMouldLevelSetpoint : REAL := 100.0;
    rKp : REAL := 2.5; rKi : REAL := 0.5; rKd : REAL := 0.1;
    rError : REAL; rLastError : REAL; rIntegral : REAL; rDerivative : REAL;

    // Cooling parameters
    rTargetTemp : ARRAY[1..3] OF REAL := [950.0, 850.0, 750.0]; // Target surface temps
    rSpecificWaterFlow : REAL := 1.2; // L/kg of steel
    iZone : INT;

    eState : (IDLE, CASTING, STOPPING) := IDLE;
END_VAR

CASE eState OF
    IDLE:
        rStopperPosition := 0.0;
        rOscillatorFreq := 0.0;
        FOR iZone := 1 TO 3 DO
            rCoolingWaterFlow[iZone] := 0.0;
        END_FOR
        rIntegral := 0.0;
        IF bStartCasting THEN eState := CASTING; END_IF

    CASTING:
        // Mould Level Control (PID)
        rError := rMouldLevelSetpoint - rMouldLevelSensor;
        rIntegral := rIntegral + (rError * 0.01);
        rDerivative := (rError - rLastError) / 0.01;
        rStopperPosition := LIMIT(0.0, (rKp * rError) + (rKi * rIntegral) + (rKd * rDerivative), 100.0);
        rLastError := rError;

        // Oscillation Control
        rOscillatorFreq := 1.5 + (rCastingSpeed * 0.5); // Frequency tied to speed
        rOscillatorStroke := 6.0;

        // Secondary Cooling Control
        FOR iZone := 1 TO 3 DO
            // Base flow calculated from casting speed and specific water flow
            rCoolingWaterFlow[iZone] := rCastingSpeed * rSpecificWaterFlow * 50.0; 

            // Trim flow based on temperature feedback (simple P control for trim)
            IF rStrandTemp[iZone] > rTargetTemp[iZone] THEN
                rCoolingWaterFlow[iZone] := rCoolingWaterFlow[iZone] + ((rStrandTemp[iZone] - rTargetTemp[iZone]) * 0.5);
            ELSIF rStrandTemp[iZone] < rTargetTemp[iZone] THEN
                rCoolingWaterFlow[iZone] := rCoolingWaterFlow[iZone] - ((rTargetTemp[iZone] - rStrandTemp[iZone]) * 0.5);
            END_IF

            // Saturation limits
            rCoolingWaterFlow[iZone] := LIMIT(10.0, rCoolingWaterFlow[iZone], 500.0);
        END_FOR

        IF bStopCasting THEN eState := STOPPING; END_IF

    STOPPING:
        rStopperPosition := MAX(0.0, rStopperPosition - 1.0);
        // Maintain cooling until fully stopped
        IF rStopperPosition = 0.0 AND rCastingSpeed < 0.05 THEN
            FOR iZone := 1 TO 3 DO rCoolingWaterFlow[iZone] := 0.0; END_FOR
            eState := IDLE;
        END_IF
END_CASE
