PROGRAM PRG_ContinuousCasting
VAR
    // Inputs
    rMouldLevelSensor : REAL;
    rHIL_PredictedLevel : REAL; // Level predicted by the Digital Twin

    // Outputs
    rStopperPosition : REAL;

    // Self-Test Variables
    bInitiateSelfTest : BOOL;
    bSelfTestPassed : BOOL;
    iTestStep : INT;
    tTestTimer : TON;
    rTestFeedback : REAL; // Stopper position feedback

    // Drift Detection
    rDriftAccumulator : REAL;
    tDriftTimer : TON;
    bDriftWarning : BOOL;

    // Control
    rMouldLevelSetpoint : REAL := 100.0;
    rIntegral : REAL;
    bStartCasting : BOOL;

    eState : (INIT, SELF_TEST, IDLE, CASTING, STOPPING, ABORT) := INIT;
END_VAR

CASE eState OF
    INIT:
        IF bInitiateSelfTest THEN
            eState := SELF_TEST;
            iTestStep := 1;
        END_IF

    SELF_TEST:
        // Actuator pre-cast signature analysis
        CASE iTestStep OF
            1: // Command 50% open
                rStopperPosition := 50.0;
                tTestTimer(IN:=TRUE, PT:=T#2S);
                IF tTestTimer.Q THEN
                    IF ABS(rTestFeedback - 50.0) < 2.0 THEN
                        iTestStep := 2;
                        tTestTimer(IN:=FALSE);
                    ELSE
                        eState := ABORT; // Actuator sticking
                    END_IF
                END_IF
            2: // Command close
                rStopperPosition := 0.0;
                tTestTimer(IN:=TRUE, PT:=T#2S);
                IF tTestTimer.Q THEN
                    IF ABS(rTestFeedback - 0.0) < 1.0 THEN
                        bSelfTestPassed := TRUE;
                        tTestTimer(IN:=FALSE);
                        eState := IDLE;
                    ELSE
                        eState := ABORT;
                    END_IF
                END_IF
        END_CASE

    IDLE:
        IF bStartCasting AND bSelfTestPassed THEN
            eState := CASTING;
            rDriftAccumulator := 0.0;
        END_IF

    CASTING:
        // Adversarial Defense: Sensor Drift vs HIL Digital Twin
        // The twin models physics (inflow vs casting speed). If sensor deviates slowly over time, it's drift.
        rDriftAccumulator := rDriftAccumulator + (rMouldLevelSensor - rHIL_PredictedLevel) * 0.01;

        tDriftTimer(IN:=TRUE, PT:=T#1M);
        IF tDriftTimer.Q THEN
            IF ABS(rDriftAccumulator) > 300.0 THEN // Significant divergence over 1 minute
                bDriftWarning := TRUE;
                // Adjust setpoint dynamically or switch to HIL open-loop control
            END_IF
            rDriftAccumulator := 0.0;
            tDriftTimer(IN:=FALSE);
        END_IF

        // Immediate adversarial spike detection (e.g. sensor spoofing / EMI)
        IF ABS(rMouldLevelSensor - rHIL_PredictedLevel) > 40.0 THEN
            eState := ABORT; // Discrepancy too large, unphysical behavior
        END_IF

        // Control Logic
        rIntegral := rIntegral + ((rMouldLevelSetpoint - rMouldLevelSensor) * 0.01);
        rStopperPosition := LIMIT(0.0, (2.0 * (rMouldLevelSetpoint - rMouldLevelSensor)) + (0.5 * rIntegral), 100.0);

    STOPPING:
        rStopperPosition := 0.0;
        eState := IDLE;

    ABORT:
        // Failsafe execution
        rStopperPosition := 0.0;
        // Require manual maintenance override to exit ABORT
END_CASE
