PROGRAM OreCrusher_Base
VAR
    // Inputs
    Cmd_Start : BOOL;
    Cmd_Stop : BOOL;
    Load_Torque : REAL; // Current torque in %
    Lube_Pressure_OK : BOOL;
    Reset_Faults : BOOL;

    // Outputs
    Motor_Run : BOOL;
    Lube_Pump_Run : BOOL;
    Fault_Crusher : BOOL;

    // Parameters
    Limit_Torque : REAL := 95.0;
END_VAR

// Fault Reset
IF Reset_Faults THEN
    Fault_Crusher := FALSE;
END_IF;

// Lubrication Control
IF Cmd_Start AND NOT Fault_Crusher THEN
    Lube_Pump_Run := TRUE;
END_IF;

// Motor Control Interlocks
IF Lube_Pump_Run AND Lube_Pressure_OK AND NOT Fault_Crusher THEN
    Motor_Run := TRUE;
ELSE
    Motor_Run := FALSE;
END_IF;

// Torque Limit Protection
IF Motor_Run AND (Load_Torque > Limit_Torque) THEN
    Fault_Crusher := TRUE;
    Motor_Run := FALSE;
    Lube_Pump_Run := FALSE;
END_IF;

// Stop Command
IF Cmd_Stop THEN
    Motor_Run := FALSE;
    Lube_Pump_Run := FALSE;
END_IF;
END_PROGRAM
```

