```pascal
FUNCTION_BLOCK "FB_ReheatFurnace_Base"
VERSION : 0.1
VAR_INPUT
    xStartSeq : BOOL;
    xStopSeq : BOOL;
    rZone1_PV : REAL;
    rZone1_SP : REAL;
END_VAR
VAR_OUTPUT
    xLift : BOOL;
    xForward : BOOL;
    xLower : BOOL;
    xBackward : BOOL;
    rHeatCmd : REAL;
END_VAR
VAR
    iStep : INT;
    fbTimer : TON;
    fbPID : "PID_Compact";
END_VAR
BEGIN
    fbPID(Setpoint:=rZone1_SP, Input:=rZone1_PV, Output=>rHeatCmd);
    IF xStopSeq THEN
        iStep := 0; xLift:=FALSE; xForward:=FALSE; xLower:=FALSE; xBackward:=FALSE;
    ELSIF xStartSeq AND iStep=0 THEN
        iStep := 10;
    END_IF;
    CASE iStep OF
        10: xLift:=TRUE; xBackward:=FALSE; fbTimer(IN:=TRUE,PT:=T#3S); IF fbTimer.Q THEN fbTimer(IN:=FALSE); iStep:=20; END_IF;
        20: xForward:=TRUE; fbTimer(IN:=TRUE,PT:=T#4S); IF fbTimer.Q THEN fbTimer(IN:=FALSE); iStep:=30; END_IF;
        30: xLift:=FALSE; xLower:=TRUE; xForward:=FALSE; fbTimer(IN:=TRUE,PT:=T#3S); IF fbTimer.Q THEN fbTimer(IN:=FALSE); iStep:=40; END_IF;
        40: xLower:=FALSE; xBackward:=TRUE; fbTimer(IN:=TRUE,PT:=T#4S); IF fbTimer.Q THEN fbTimer(IN:=FALSE); iStep:=10; END_IF;
    END_CASE;
END_FUNCTION_BLOCK
```

