```st
PROGRAM PRG_SAG_Mill_Monitor_M1
VAR
    // Inputs
    rTrunnionFeedEndPressure : REAL; // bar
    rTrunnionDischargeEndPressure : REAL; // bar
    rTrunnionBearingTemp : REAL; // Celsius
    rMillMotorPower : REAL; // kW
    rMillSpeed : REAL; // RPM

    // Lube Oil Cooling parameters
    rTempSetpoint : REAL := 45.0; // Celsius
    rKp : REAL := 2.5;
    rKi : REAL := 0.1;

    // Parameters
    rMaxPressure : REAL := 150.0; // max safe pressure
    rNominalPower : REAL := 12000.0;

    // Outputs
    bHighPressureAlarm : BOOL;
    rEstimatedChargeVolume : REAL; // %
    rCoolingValveCommand : REAL; // 0-100%

    // Internal
    rAvgPressure : REAL;
    rTempError : REAL;
    rIntegralTemp : REAL;
END_VAR

// Calculate average pressure
rAvgPressure := (rTrunnionFeedEndPressure + rTrunnionDischargeEndPressure) / 2.0;
bHighPressureAlarm := rAvgPressure > rMaxPressure;

// Charge volume estimation
IF rMillSpeed > 0 THEN
    rEstimatedChargeVolume := LIMIT(0.0, (rMillMotorPower / rNominalPower) * 100.0 * (rAvgPressure / 100.0), 100.0);
ELSE
    rEstimatedChargeVolume := 0.0;
END_IF

// Lube Oil Cooling PI Control
rTempError := rTrunnionBearingTemp - rTempSetpoint;
IF rTempError > 0.0 THEN
    rIntegralTemp := LIMIT(0.0, rIntegralTemp + rTempError, 1000.0);
    rCoolingValveCommand := LIMIT(0.0, (rKp * rTempError) + (rKi * rIntegralTemp), 100.0);
ELSE
    rCoolingValveCommand := 0.0;
    rIntegralTemp := 0.0;
END_IF
