    stScadaDataPackage.SystemFaults := stScadaDataPackage.SystemFaults OR 16#01;
ELSE
    rActiveFeedPressure := rPressureFeed;
    bFeedPressureFailover := FALSE;
    stScadaDataPackage.SystemFaults := stScadaDataPackage.SystemFaults AND NOT 16#01;
END_IF

// Core Logic
