ELSE
    stScadaDataPackage.ChargeVol := 0.0;
END_IF
rChargeVolume := stScadaDataPackage.ChargeVol; // Local output

// Lube Oil Cooling PI
IF rBearingTemp > 45.0 THEN
    rIntegralTemp := LIMIT(0.0, rIntegralTemp + (rBearingTemp - 45.0), 1000.0);
    rCoolingValve := LIMIT(0.0, (2.5 * (rBearingTemp - 45.0)) + (0.1 * rIntegralTemp), 100.0);
ELSE
    rCoolingValve := 0.0;
    rIntegralTemp := 0.0;
END_IF
