    // Digital Twin HIL Sync
    bSimModeActive AT %I* : BOOL;
    rSimPressureFeed AT %I* : REAL;
    rTwinChargeVol AT %I* : REAL;

    // Security & SCADA
    nActiveRoleLevel : INT;
    stScada : STRUCT
        AvgPressure : REAL;
        ChargeVol : REAL;
        TwinVariance : REAL;
        Faults : DWORD;
    END_STRUCT;

    // Self-Test Routine
    eState : (INIT, SELF_TEST, RUNNING, FAULT);
    nTestTimer : INT;
    bTestPass : BOOL;

    // Outputs
    bHighPressureAlarm : BOOL;
    rChargeVolume : REAL;
    rCoolingValve AT %Q* : REAL;

    // Internal
    rActiveFeedPressure : REAL;
    rDriftError : REAL;
    bDriftAlarm : BOOL;
    rIntegralTemp : REAL;
END_VAR

CASE eState OF
    INIT:
        nTestTimer := 0;
        stScada.Faults := 0;
        eState := SELF_TEST;

    SELF_TEST:
        // Simulate valve opening to check feedback (mocked here)
        rCoolingValve := 50.0;
        nTestTimer := nTestTimer + 1;
        IF nTestTimer > 100 THEN
            bTestPass := (rPressureFeed > 0 AND rBearingTemp > 0);
            IF bTestPass THEN
                rCoolingValve := 0.0;
                eState := RUNNING;
            ELSE
                eState := FAULT;
                stScada.Faults := stScada.Faults OR 16#10;
            END_IF
        END_IF

    RUNNING:
        // HIL Override
        IF bSimModeActive THEN
            rActiveFeedPressure := rSimPressureFeed;
        ELSE
            // Failover & Drift Detection
            rDriftError := ABS(rPressureFeed - rPressureFeed_Redundant);
            IF rDriftError > 5.0 THEN
                bDriftAlarm := TRUE;
                stScada.Faults := stScada.Faults OR 16#02;
            END_IF

            IF rPressureFeed < -1.0 OR bDriftAlarm THEN
                rActiveFeedPressure := rPressureFeed_Redundant;
            ELSE
                rActiveFeedPressure := rPressureFeed;
            END_IF
        END_IF

        stScada.AvgPressure := (rActiveFeedPressure + rPressureDischarge) / 2.0;
        bHighPressureAlarm := stScada.AvgPressure > 150.0;

        // Charge Vol vs Twin
        stScada.ChargeVol := LIMIT(0.0, (rMillPower / 12000.0) * 100.0 * (stScada.AvgPressure / 100.0), 100.0);
        stScada.TwinVariance := ABS(stScada.ChargeVol - rTwinChargeVol);
        rChargeVolume := stScada.ChargeVol;

        // Cooling PI
        IF rBearingTemp > 45.0 THEN
            rIntegralTemp := LIMIT(0.0, rIntegralTemp + (rBearingTemp - 45.0), 1000.0);
            rCoolingValve := LIMIT(0.0, (2.5 * (rBearingTemp - 45.0)) + (0.1 * rIntegralTemp), 100.0);
        ELSE
            rCoolingValve := 0.0;
            rIntegralTemp := 0.0;
        END_IF

    FAULT:
        rCoolingValve := 100.0; // Fail-safe
        bHighPressureAlarm := TRUE;
END_CASE
