FUNCTION_BLOCK "Lyophilizer_Base"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    VacuumSetPoint : Real;
    TempSetPoint : Real;
    ActualVacuum : Real;
    ActualTemp : Real;
END_VAR
VAR_OUTPUT
    VacuumValveControl : Real;
    HeaterControl : Real;
    CoolingControl : Real;
END_VAR
VAR
    PID_Vacuum : "PID_Compact";
    PID_Temp : "PID_Compact";
    State : Int;
END_VAR

BEGIN
    IF Start AND NOT Stop THEN
        State := 1;
    ELSIF Stop THEN
        State := 0;
    END_IF;

    IF State = 1 THEN
        PID_Vacuum(Setpoint:=VacuumSetPoint, Input:=ActualVacuum, Output=>VacuumValveControl);
        PID_Temp(Setpoint:=TempSetPoint, Input:=ActualTemp, Output=>HeaterControl);
        CoolingControl := 100.0 - HeaterControl;
    ELSE
        VacuumValveControl := 0.0;
        HeaterControl := 0.0;
        CoolingControl := 0.0;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "Lyophilizer_Mut1"
VAR_INPUT
    Start : Bool;
    Stop : Bool;
    StartDefrost : Bool;
    VacuumSetPoint : Real;
    TempSetPoint : Real;
    ActualVacuum : Real;
    ActualTemp : Real;
    CondenserTemp : Real;
END_VAR
VAR_OUTPUT
    VacuumValveControl : Real;
    HeaterControl : Real;
    CoolingControl : Real;
    DefrostHeater : Bool;
    DrainValve : Bool;
END_VAR
VAR
    PID_Vacuum : "PID_Compact";
    PID_Temp : "PID_Compact";
    State : Int;
    DefrostTimer : TON;
END_VAR

BEGIN
    IF Stop THEN
        State := 0;
    ELSIF Start AND State = 0 THEN
        State := 1;
    ELSIF StartDefrost AND State = 0 THEN
        State := 2;
    END_IF;

    CASE State OF
        0: 
            VacuumValveControl := 0.0;
            HeaterControl := 0.0;
            CoolingControl := 0.0;
            DefrostHeater := FALSE;
            DrainValve := FALSE;
        1: 
