```pascal
FUNCTION_BLOCK "CIP_Skid_Reasoning"
VERSION : 1.2
VAR_INPUT
    SCADA_Cmd : Int;
    SCADA_Heartbeat : Int;
    User_Role : Int; // 1=Operator, 2=Admin for IEC 62443
    Pump1_Fault : Bool;
    Pump2_Fault : Bool;
END_VAR
VAR_OUTPUT
    Pump1_Cmd : Bool;
    Pump2_Cmd : Bool;
    SCADA_Echo : Int;
    Security_Alarm : Bool;
END_VAR
VAR
    Active_Pump : Int := 1;
    Last_Heartbeat : Int;
    Watchdog_Timer : Int;
END_VAR

BEGIN
    // IEC 62443 Security & Command Validation
    Security_Alarm := FALSE;
    IF SCADA_Cmd = 99 AND User_Role < 2 THEN
        Security_Alarm := TRUE; // Unauthorized bypass attempt
        SCADA_Cmd := 0; 
    END_IF;

    // SCADA Heartbeat
    IF SCADA_Heartbeat <> Last_Heartbeat THEN
        Watchdog_Timer := 0;
        Last_Heartbeat := SCADA_Heartbeat;
    ELSE
        Watchdog_Timer := Watchdog_Timer + 1;
    END_IF;

    IF Watchdog_Timer > 1000 THEN
        // SCADA Comm Loss - Fail Safe
        Pump1_Cmd := FALSE;
        Pump2_Cmd := FALSE;
    ELSE
        // Failover Logic
        IF Active_Pump = 1 AND Pump1_Fault THEN
            Active_Pump := 2;
        ELSIF Active_Pump = 2 AND Pump2_Fault THEN
            Active_Pump := 1;
        END_IF;

        IF SCADA_Cmd = 1 THEN
            Pump1_Cmd := (Active_Pump = 1) AND NOT Pump1_Fault;
            Pump2_Cmd := (Active_Pump = 2) AND NOT Pump2_Fault;
        ELSE
            Pump1_Cmd := FALSE; Pump2_Cmd := FALSE;
        END_IF;
    END_IF;

    SCADA_Echo := SCADA_Cmd;
END_FUNCTION_BLOCK
