TYPE E_MachineState : (
    INIT := 0,
    SELF_TEST := 10,
    HIL_SYNC := 20,
    READY := 30,
    RUNNING := 40,
    FAULT := 99
);
END_TYPE

PROGRAM PRG_ReactionVessel_Ultimate
VAR
    eState : E_MachineState := E_MachineState.INIT;

    // Redundant Sensors for Drift Detection
    rTemp_SensorA      AT %I* : REAL;
    rTemp_SensorB      AT %I* : REAL;
    rTemp_Validated    : REAL;
    rDriftTolerance    : REAL := 2.0; // Max allowed drift in DegC
    bSensorDriftAlarm  : BOOL;

    // HIL Digital Twin (MQTT Payload Mapping)
    stHIL_Data : STRUCT
        rSimPressure   : REAL;
        rSimTemp       : REAL;
        bSyncFlag      : BOOL;
    END_STRUCT;
    bDigitalTwinSync   : BOOL;

    // Self Test
    fbTestTimer        : TON;
    bValveTestPass     : BOOL;

    // SCADA, Security & Failover
    bIsPrimary         : BOOL := TRUE;
    eUserRole          : INT := 3; // Admin
END_VAR

// State Machine
CASE eState OF
    E_MachineState.INIT:
        bSensorDriftAlarm := FALSE;
        eState := E_MachineState.SELF_TEST;

    E_MachineState.SELF_TEST:
        // Actuate valves 0-100% and check feedback
        fbTestTimer(IN := TRUE, PT := T#2S);
        IF fbTestTimer.Q THEN
            bValveTestPass := TRUE; // Mock test pass
            eState := E_MachineState.HIL_SYNC;
            fbTestTimer(IN := FALSE);
        END_IF

    E_MachineState.HIL_SYNC:
        // Synchronize state with Digital Twin
        IF stHIL_Data.bSyncFlag THEN
            bDigitalTwinSync := TRUE;
            eState := E_MachineState.READY;
        END_IF

    E_MachineState.READY:
        // Wait for Start Command
        eState := E_MachineState.RUNNING;

    E_MachineState.RUNNING:
        // 1. Sensor Drift Detection
        IF ABS(rTemp_SensorA - rTemp_SensorB) > rDriftTolerance THEN
            bSensorDriftAlarm := TRUE;
            eState := E_MachineState.FAULT;
        ELSE
            rTemp_Validated := (rTemp_SensorA + rTemp_SensorB) / 2.0;
        END_IF

        // 2. Core Exothermic Control (using rTemp_Validated)
        // ...

    E_MachineState.FAULT:
        // Safe Shutdown Sequence
        // Disconnect HIL, force cooling max, alert SCADA
        bDigitalTwinSync := FALSE;
END_CASE
