// Base Code: Hydroelectric Turbine - Penstock Valve and Governor PID
PROGRAM TurbineControl
VAR
    // Inputs
    Turbine_Speed_RPM : REAL;
    Set_Speed_RPM : REAL := 300.0;
    Valve_Position_FB : REAL;
    Start_Command : BOOL;
    Stop_Command : BOOL;

    // Outputs
    Penstock_Valve_Cmd : REAL;
    Governor_PID_Output : REAL;
    Valve_Open_Cmd : BOOL;
    Valve_Close_Cmd : BOOL;

    // Internal Variables
    State : INT := 0; // 0=Stop, 1=Opening, 2=Running, 3=Stopping
    PID_Error : REAL;
    PID_Integral : REAL := 0.0;
    PID_Derivative : REAL := 0.0;
    Last_Error : REAL := 0.0;

    // PID Gains
    Kp : REAL := 1.5;
    Ki : REAL := 0.5;
    Kd : REAL := 0.1;
    dt : REAL := 0.1; // Scan time in seconds
END_VAR

// State Machine
CASE State OF
    0: // Stop
        Valve_Open_Cmd := FALSE;
        Valve_Close_Cmd := TRUE;
        Governor_PID_Output := 0.0;
        IF Start_Command THEN
            State := 1;
        END_IF;

    1: // Opening Penstock
        Valve_Close_Cmd := FALSE;
        Valve_Open_Cmd := TRUE;
        IF Valve_Position_FB > 95.0 THEN
            State := 2;
        END_IF;

    2: // Running
        // Governor Speed PID
        PID_Error := Set_Speed_RPM - Turbine_Speed_RPM;
        PID_Integral := PID_Integral + (PID_Error * dt);
        PID_Derivative := (PID_Error - Last_Error) / dt;

        Governor_PID_Output := (Kp * PID_Error) + (Ki * PID_Integral) + (Kd * PID_Derivative);
        Last_Error := PID_Error;

        // Output limits
        IF Governor_PID_Output > 100.0 THEN Governor_PID_Output := 100.0; END_IF;
        IF Governor_PID_Output < 0.0 THEN Governor_PID_Output := 0.0; END_IF;

        IF Stop_Command THEN
            State := 3;
        END_IF;

    3: // Stopping
        Valve_Open_Cmd := FALSE;
        Valve_Close_Cmd := TRUE;
        Governor_PID_Output := 0.0;
        IF Valve_Position_FB < 5.0 THEN
            State := 0;
        END_IF;
END_CASE;
END_PROGRAM

// Mutation 1 (Add Depth): Added Lube Oil Cooling System
PROGRAM TurbineControl_Depth
VAR
    // Inputs
    Turbine_Speed_RPM : REAL;
    Set_Speed_RPM : REAL := 300.0;
    Valve_Position_FB : REAL;
    Start_Command : BOOL;
    Stop_Command : BOOL;

    // Lube Oil Inputs
    Lube_Oil_Temp : REAL;
    Lube_Oil_Pressure : REAL;

    // Outputs
    Penstock_Valve_Cmd : REAL;
    Governor_PID_Output : REAL;
    Valve_Open_Cmd : BOOL;
    Valve_Close_Cmd : BOOL;

    // Lube Oil Outputs
    Lube_Oil_Pump_Run : BOOL;
    Cooling_Water_Valve : REAL;

    // Internal Variables
    State : INT := 0; // 0=Stop, 1=Prep, 2=Opening, 3=Running, 4=Stopping
    PID_Error, PID_Integral, PID_Derivative, Last_Error : REAL;
    Kp : REAL := 1.5; Ki : REAL := 0.5; Kd : REAL := 0.1; dt : REAL := 0.1;

    // Alarms
    Lube_Oil_Alarm : BOOL;
END_VAR

// Lube Oil Cooling Control
IF Lube_Oil_Temp > 60.0 THEN
    Cooling_Water_Valve := 100.0;
ELSIF Lube_Oil_Temp > 40.0 THEN
    Cooling_Water_Valve := (Lube_Oil_Temp - 40.0) * 5.0; // Proportional cooling
ELSE
    Cooling_Water_Valve := 0.0;
END_IF;

Lube_Oil_Alarm := Lube_Oil_Pressure < 2.0 OR Lube_Oil_Temp > 75.0;

// State Machine
CASE State OF
    0: // Stop
        Valve_Open_Cmd := FALSE; Valve_Close_Cmd := TRUE;
        Governor_PID_Output := 0.0;
        Lube_Oil_Pump_Run := FALSE;
        IF Start_Command THEN State := 1; END_IF;

    1: // Prep (Start Lube Oil)
        Lube_Oil_Pump_Run := TRUE;
        IF Lube_Oil_Pressure >= 2.5 THEN State := 2; END_IF;

    2: // Opening Penstock
        Valve_Close_Cmd := FALSE; Valve_Open_Cmd := TRUE;
        IF Valve_Position_FB > 95.0 THEN State := 3; END_IF;
        IF Lube_Oil_Alarm THEN State := 4; END_IF; // Abort

    3: // Running
        IF Lube_Oil_Alarm OR Stop_Command THEN
            State := 4;
        ELSE
            PID_Error := Set_Speed_RPM - Turbine_Speed_RPM;
            PID_Integral := PID_Integral + (PID_Error * dt);
            PID_Derivative := (PID_Error - Last_Error) / dt;
            Governor_PID_Output := (Kp * PID_Error) + (Ki * PID_Integral) + (Kd * PID_Derivative);
            Last_Error := PID_Error;
            IF Governor_PID_Output > 100.0 THEN Governor_PID_Output := 100.0; END_IF;
            IF Governor_PID_Output < 0.0 THEN Governor_PID_Output := 0.0; END_IF;
        END_IF;

    4: // Stopping
        Valve_Open_Cmd := FALSE; Valve_Close_Cmd := TRUE;
        Governor_PID_Output := 0.0;
        IF Valve_Position_FB < 5.0 AND Turbine_Speed_RPM < 10.0 THEN
            State := 0;
        END_IF;
END_CASE;
END_PROGRAM

// Mutation 2 (Add Breadth): Ethernet/IP and Fault Diagnostics
PROGRAM TurbineControl_Breadth
VAR
    // Ethernet/IP Mapped Tags (DCS Comm)
    EIP_Start_Cmd : BOOL;
    EIP_Stop_Cmd : BOOL;
    EIP_Ack_Cmd : BOOL;
    EIP_Set_Speed : REAL;
    EIP_Turbine_Status : DINT;
    EIP_Active_Alarms : DINT;

    // I/O
    Turbine_Speed_RPM, Valve_Position_FB : REAL;
    Lube_Oil_Temp, Lube_Oil_Pressure : REAL;
    Valve_Open_Cmd, Valve_Close_Cmd, Lube_Oil_Pump_Run : BOOL;
    Governor_PID_Output, Cooling_Water_Valve : REAL;

    // Diagnostics
    Flt_OverSpeed, Flt_ValveStuck, Flt_LubePress, Flt_LubeTemp : BOOL;
    Global_Fault : BOOL;
    Valve_Timer : DINT;

    // State and Control
    State : INT := 0;
    PID_Error, PID_Integral, PID_Derivative, Last_Error : REAL;
    Kp : REAL := 1.5; Ki : REAL := 0.5; Kd : REAL := 0.1; dt : REAL := 0.1;
END_VAR

// Fault Diagnostics
Flt_OverSpeed := Turbine_Speed_RPM > (EIP_Set_Speed * 1.15); // 115% Overspeed
Flt_LubePress := Lube_Oil_Pump_Run AND (Lube_Oil_Pressure < 2.0);
Flt_LubeTemp := Lube_Oil_Temp > 75.0;

// Valve stuck detection
IF (State = 2 AND Valve_Position_FB < 95.0) OR (State = 4 AND Valve_Position_FB > 5.0) THEN
    Valve_Timer := Valve_Timer + 1;
    IF Valve_Timer > 100 THEN Flt_ValveStuck := TRUE; END_IF;
ELSE
    Valve_Timer := 0;
END_IF;

IF EIP_Ack_Cmd THEN
    Flt_OverSpeed := FALSE; Flt_ValveStuck := FALSE;
    Flt_LubePress := FALSE; Flt_LubeTemp := FALSE;
END_IF;

Global_Fault := Flt_OverSpeed OR Flt_ValveStuck OR Flt_LubePress OR Flt_LubeTemp;

// Lube Oil Control
IF Lube_Oil_Temp > 60.0 THEN Cooling_Water_Valve := 100.0;
ELSIF Lube_Oil_Temp > 40.0 THEN Cooling_Water_Valve := (Lube_Oil_Temp - 40.0) * 5.0;
ELSE Cooling_Water_Valve := 0.0; END_IF;

// State Machine
CASE State OF
    0: // Stop
        Valve_Open_Cmd := FALSE; Valve_Close_Cmd := TRUE;
        Governor_PID_Output := 0.0; Lube_Oil_Pump_Run := FALSE;
        IF EIP_Start_Cmd AND NOT Global_Fault THEN State := 1; END_IF;

    1: // Prep
        Lube_Oil_Pump_Run := TRUE;
        IF Lube_Oil_Pressure >= 2.5 THEN State := 2; END_IF;

    2: // Opening
        Valve_Close_Cmd := FALSE; Valve_Open_Cmd := TRUE;
        IF Valve_Position_FB > 95.0 THEN State := 3; END_IF;
        IF Global_Fault THEN State := 4; END_IF;

    3: // Running
        IF Global_Fault OR EIP_Stop_Cmd THEN
            State := 4;
        ELSE
            PID_Error := EIP_Set_Speed - Turbine_Speed_RPM;
            PID_Integral := PID_Integral + (PID_Error * dt);
            PID_Derivative := (PID_Error - Last_Error) / dt;
            Governor_PID_Output := (Kp * PID_Error) + (Ki * PID_Integral) + (Kd * PID_Derivative);
            Last_Error := PID_Error;
            IF Governor_PID_Output > 100.0 THEN Governor_PID_Output := 100.0; END_IF;
            IF Governor_PID_Output < 0.0 THEN Governor_PID_Output := 0.0; END_IF;
        END_IF;

    4: // Stopping
        Valve_Open_Cmd := FALSE; Valve_Close_Cmd := TRUE;
        Governor_PID_Output := 0.0;
        IF Valve_Position_FB < 5.0 AND Turbine_Speed_RPM < 10.0 THEN State := 0; END_IF;
END_CASE;

// Map Status to EIP
EIP_Turbine_Status := State;
EIP_Active_Alarms.0 := Flt_OverSpeed;
EIP_Active_Alarms.1 := Flt_ValveStuck;
EIP_Active_Alarms.2 := Flt_LubePress;
EIP_Active_Alarms.3 := Flt_LubeTemp;
END_PROGRAM

// Mutation 3 (Add Reasoning): Cyber, Failover, SCADA
PROGRAM TurbineControl_Reasoning
VAR
    // Redundancy / Failover
    Primary_Active : BOOL := TRUE;
    Heartbeat_Tx : DINT;
    Heartbeat_Rx : DINT;
    Partner_Missed_Beats : INT;
    Takeover_Cmd : BOOL;

    // Cyber & SCADA Security (IEC 62443 principles)
    SCADA_Payload_Rx : DINT;
    SCADA_Role_ID : INT;     // 1=Operator, 2=Eng, 3=Admin
    SCADA_Token : DINT;
    Cmd_Validated : BOOL;
    Security_Alarm : BOOL;
    Invalid_Attempts : INT;

    EIP_Start_Cmd, EIP_Stop_Cmd, EIP_Set_Speed_Cmd : BOOL;
    Target_Speed : REAL := 300.0;

    // Core I/O
    Turbine_Speed_RPM, Valve_Position_FB : REAL;
    Valve_Open_Cmd, Valve_Close_Cmd, Lube_Oil_Pump_Run : BOOL;
    Governor_PID_Output, Cooling_Water_Valve : REAL;
    State : INT := 0;

    // Internal
    Global_Fault : BOOL;
END_VAR

// Failover Logic (Heartbeat Monitoring)
Heartbeat_Tx := Heartbeat_Tx + 1;
IF Heartbeat_Rx = 0 THEN // Pseudo-check for partner timeout
    Partner_Missed_Beats := Partner_Missed_Beats + 1;
ELSE
    Partner_Missed_Beats := 0;
END_IF;

IF NOT Primary_Active AND (Partner_Missed_Beats > 5) THEN
    Takeover_Cmd := TRUE;
    Primary_Active := TRUE;
END_IF;

IF Primary_Active THEN
    // Cybersecurity - Command Validation
    Cmd_Validated := FALSE;
    IF SCADA_Role_ID >= 1 AND SCADA_Role_ID <= 3 THEN
        // Verify Token payload matches expected rolling hash (mocked as Token > 1000)
        IF SCADA_Token > 1000 THEN
            Cmd_Validated := TRUE;
            Invalid_Attempts := 0;
        ELSE
            Invalid_Attempts := Invalid_Attempts + 1;
        END_IF;
    END_IF;

    IF Invalid_Attempts > 3 THEN
        Security_Alarm := TRUE; // Lockout/Alert
    END_IF;

    // Process Validated SCADA Commands
    IF Cmd_Validated AND NOT Security_Alarm THEN
        IF EIP_Start_Cmd THEN State := 1; END_IF;
        IF EIP_Stop_Cmd THEN State := 4; END_IF;
    END_IF;

    // Core Machine State Logic
    CASE State OF
        0: // Stop
            Valve_Open_Cmd := FALSE; Valve_Close_Cmd := TRUE;
            Governor_PID_Output := 0.0; Lube_Oil_Pump_Run := FALSE;
        1: // Start Lube
            Lube_Oil_Pump_Run := TRUE; State := 2;
        2: // Open Valve
            Valve_Close_Cmd := FALSE; Valve_Open_Cmd := TRUE;
            IF Valve_Position_FB > 95.0 THEN State := 3; END_IF;
        3: // Run - Simple P-Control for brevity
            Governor_PID_Output := (Target_Speed - Turbine_Speed_RPM) * 1.5;
            IF Governor_PID_Output > 100.0 THEN Governor_PID_Output := 100.0; END_IF;
            IF Governor_PID_Output < 0.0 THEN Governor_PID_Output := 0.0; END_IF;
            IF Global_Fault THEN State := 4; END_IF;
        4: // Stop
            Valve_Open_Cmd := FALSE; Valve_Close_Cmd := TRUE;
            Governor_PID_Output := 0.0;
            IF Valve_Position_FB < 5.0 THEN State := 0; END_IF;
    END_CASE;
ELSE
    // Secondary Standby Mode: Track state from Primary via network sync, output disabled
    Valve_Open_Cmd := FALSE; Valve_Close_Cmd := FALSE; Lube_Oil_Pump_Run := FALSE;
END_IF;
END_PROGRAM

// Mutation 4 (Add Adversarial): Drift, HIL Sync, Self-Test
PROGRAM TurbineControl_Adversarial
VAR
    // Redundant Sensors & Drift Detection
    Speed_Sensor_A, Speed_Sensor_B : REAL;
    Speed_Validated : REAL;
    Sensor_Drift_Fault : BOOL;
    Max_Allowed_Drift : REAL := 5.0; // RPM

    // HIL Digital Twin Sync
    Expected_Speed_HIL : REAL;
    Inertia_Anomaly : BOOL;
    HIL_Deviation_Threshold : REAL := 15.0;

    // I/O & Control
    Target_Speed : REAL := 300.0;
    Valve_Position_FB : REAL;
    Valve_Open_Cmd, Valve_Close_Cmd : BOOL;
    Governor_PID_Output : REAL;
    Start_Cmd, Stop_Cmd : BOOL;

    // State and Self-Test
    State : INT := 0; 
    // 0=Stop, 1=Self-Test Open, 2=Self-Test Close, 3=Self-Test Eval, 4=Open, 5=Run, 6=Stop
    SelfTest_Pass : BOOL;
    SelfTest_Timer : DINT;
END_VAR

// 1. Dual-Redundant Sensor Drift Detection
IF ABS(Speed_Sensor_A - Speed_Sensor_B) > Max_Allowed_Drift THEN
    Sensor_Drift_Fault := TRUE;
    // Fallback to highest reading for safety (overspeed protection)
    Speed_Validated := MAX(Speed_Sensor_A, Speed_Sensor_B);
ELSE
    Sensor_Drift_Fault := FALSE;
    Speed_Validated := (Speed_Sensor_A + Speed_Sensor_B) / 2.0; // Average
END_IF;

// 2. HIL Digital Twin Sync Validation
// Compares physical speed against the physics model (HIL) expected speed
IF State = 5 AND ABS(Speed_Validated - Expected_Speed_HIL) > HIL_Deviation_Threshold THEN
    Inertia_Anomaly := TRUE; // Could indicate cavitation, shaft shear, or sensor failure
END_IF;

// 3. Main State Machine with Pre-Start Self-Test
CASE State OF
    0: // Stop
        Valve_Open_Cmd := FALSE; Valve_Close_Cmd := TRUE; Governor_PID_Output := 0.0;
        IF Start_Cmd AND NOT Sensor_Drift_Fault THEN
            State := 1; SelfTest_Timer := 0; SelfTest_Pass := FALSE;
        END_IF;

    1: // Self-Test: Stroke Valve Open 10%
        Valve_Close_Cmd := FALSE; Valve_Open_Cmd := TRUE;
        SelfTest_Timer := SelfTest_Timer + 1;
        IF Valve_Position_FB >= 10.0 THEN State := 2; END_IF;
        IF SelfTest_Timer > 500 THEN State := 6; END_IF; // Timeout fail

    2: // Self-Test: Stroke Valve Closed
        Valve_Open_Cmd := FALSE; Valve_Close_Cmd := TRUE;
        IF Valve_Position_FB <= 2.0 THEN
            SelfTest_Pass := TRUE; State := 3;
        END_IF;

    3: // Self-Test Eval
        IF SelfTest_Pass THEN State := 4; ELSE State := 6; END_IF;

    4: // Opening Penstock for Operation
        Valve_Close_Cmd := FALSE; Valve_Open_Cmd := TRUE;
        IF Valve_Position_FB >= 95.0 THEN State := 5; END_IF;

    5: // Running
        IF Sensor_Drift_Fault OR Inertia_Anomaly OR Stop_Cmd THEN
            State := 6;
        ELSE
            Governor_PID_Output := (Target_Speed - Speed_Validated) * 2.0; // P-Gain
            IF Governor_PID_Output > 100.0 THEN Governor_PID_Output := 100.0; END_IF;
            IF Governor_PID_Output < 0.0 THEN Governor_PID_Output := 0.0; END_IF;
        END_IF;

    6: // Stopping / Fault Reaction
        Valve_Open_Cmd := FALSE; Valve_Close_Cmd := TRUE; Governor_PID_Output := 0.0;
        IF Valve_Position_FB < 5.0 THEN State := 0; END_IF;
END_CASE;
END_PROGRAM

FUNCTION_BLOCK "GasTurbine_Combustion_Interlock"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
   VAR_INPUT 
      Temperature_Sensors : ARRAY[1..12] OF REAL; // Thermocouples around the combustion chamber (Celsius)
      Flame_Detectors : ARRAY[1..4] OF BOOL;      // Flame scanners (TRUE = flame detected)
      Turbine_Running : BOOL;                     // Turbine running status
      Reset_Interlock : BOOL;                     // Reset command
      Temp_High_Limit : REAL := 1250.0;           // High temperature limit
      Temp_Spread_Limit : REAL := 150.0;          // Maximum allowable temperature spread
   END_VAR
   VAR_OUTPUT 
      Trip_Signal : BOOL;                         // Signal to trip the gas turbine
      Avg_Temperature : REAL;                     // Calculated average combustion temperature
      Spread_High_Alarm : BOOL;                   // High spread alarm
      Flame_Loss_Alarm : BOOL;                    // Loss of flame alarm
      Over_Temp_Alarm : BOOL;                     // Over temperature alarm
   END_VAR
   VAR 
      Interlock_Active : BOOL;                    // Internal interlock state
      Max_Temp : REAL;
      Min_Temp : REAL;
      Sum_Temp : REAL;
      i : INT;
      Flame_Count : INT;
   END_VAR
BEGIN
    #Max_Temp := -1000.0;
    #Min_Temp := 5000.0;
    #Sum_Temp := 0.0;
    #Flame_Count := 0;
    FOR #i := 1 TO 12 DO
        IF #Temperature_Sensors[#i] > #Max_Temp THEN #Max_Temp := #Temperature_Sensors[#i]; END_IF;
        IF #Temperature_Sensors[#i] < #Min_Temp THEN #Min_Temp := #Temperature_Sensors[#i]; END_IF;
        #Sum_Temp := #Sum_Temp + #Temperature_Sensors[#i];
    END_FOR;
    #Avg_Temperature := #Sum_Temp / 12.0;

    IF #Avg_Temperature > #Temp_High_Limit OR #Max_Temp > (#Temp_High_Limit + 50.0) THEN
        #Over_Temp_Alarm := TRUE;
    ELSE
        #Over_Temp_Alarm := FALSE;
    END_IF;

    IF (#Max_Temp - #Min_Temp) > #Temp_Spread_Limit THEN
        #Spread_High_Alarm := TRUE;
    ELSE
        #Spread_High_Alarm := FALSE;
    END_IF;

    FOR #i := 1 TO 4 DO
        IF #Flame_Detectors[#i] THEN #Flame_Count := #Flame_Count + 1; END_IF;
    END_FOR;

    IF #Turbine_Running AND (#Flame_Count < 2) THEN
        #Flame_Loss_Alarm := TRUE;
    ELSE
        #Flame_Loss_Alarm := FALSE;
    END_IF;

    IF #Over_Temp_Alarm OR #Spread_High_Alarm OR #Flame_Loss_Alarm THEN #Interlock_Active := TRUE; END_IF;
    IF #Reset_Interlock AND NOT (#Over_Temp_Alarm OR #Spread_High_Alarm OR #Flame_Loss_Alarm) THEN #Interlock_Active := FALSE; END_IF;
    #Trip_Signal := #Interlock_Active;
END_FUNCTION_BLOCK

