FUNCTION_BLOCK "GasTurbine_Interlock_Cyber_Redundant"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.4
   VAR_INPUT 
      Temperature_Sensors_mA : ARRAY[1..12] OF REAL;
      Flame_Detectors : ARRAY[1..4] OF BOOL;
      Turbine_Running : BOOL;
      Turbine_Startup : BOOL;
