      Base_Fuel_Demand : REAL;
      SCADA_Reset : BOOL;
      SCADA_Temp_High_Limit : REAL;
      SCADA_Temp_Spread_Limit : REAL;
      Operator_Role_ID : INT; 
      Interlock_Bypass_Key : DWORD; 
      Partner_PLC_Heartbeat : BOOL; 
      This_PLC_Primary : BOOL;
   END_VAR
   VAR_OUTPUT 
      Trip_Signal : BOOL;
      Avg_Temperature : REAL;
      Final_Fuel_Demand : REAL;
      SCADA_Status_Word : WORD;
      SCADA_Fault_Code : INT;
      Redundancy_Fault : BOOL;
   END_VAR
   VAR 
      Interlock_Active : BOOL;
      Max_Temp : REAL;
      Min_Temp : REAL;
      Sum_Temp : REAL;
      i : INT;
      Flame_Count : INT;
      Valid_Sensors : INT;
      Temperature_Sensors_Scaled : ARRAY[1..12] OF REAL;
      Bypass_Enabled : BOOL;
      Heartbeat_Timer : INT;
      Over_Temp_Alarm, Spread_High_Alarm, Flame_Loss_Alarm, EGT_Rate_Alarm : BOOL;
   END_VAR
BEGIN
    IF NOT #Partner_PLC_Heartbeat THEN
        #Heartbeat_Timer := #Heartbeat_Timer + 1;
    ELSE
        #Heartbeat_Timer := 0;
    END_IF;
    IF #Heartbeat_Timer > 50 THEN #Redundancy_Fault := TRUE; ELSE #Redundancy_Fault := FALSE; END_IF;

    IF #This_PLC_Primary OR #Redundancy_Fault THEN
        IF #Operator_Role_ID = 3 AND #Interlock_Bypass_Key = 16#A5A5_5A5A THEN
            #Bypass_Enabled := TRUE;
        ELSE
            #Bypass_Enabled := FALSE;
        END_IF;

        #Max_Temp := -1000.0; #Min_Temp := 5000.0; #Sum_Temp := 0.0; #Flame_Count := 0; #Valid_Sensors := 0; #SCADA_Fault_Code := 0;

        FOR #i := 1 TO 12 DO
            IF #Temperature_Sensors_mA[#i] >= 3.8 AND #Temperature_Sensors_mA[#i] <= 20.5 THEN
                #Temperature_Sensors_Scaled[#i] := ((#Temperature_Sensors_mA[#i] - 4.0) / 16.0) * 1500.0;
                #Valid_Sensors := #Valid_Sensors + 1;
                IF #Temperature_Sensors_Scaled[#i] > #Max_Temp THEN #Max_Temp := #Temperature_Sensors_Scaled[#i]; END_IF;
                IF #Temperature_Sensors_Scaled[#i] < #Min_Temp THEN #Min_Temp := #Temperature_Sensors_Scaled[#i]; END_IF;
                #Sum_Temp := #Sum_Temp + #Temperature_Sensors_Scaled[#i];
            END_IF;
        END_FOR;

        IF #Valid_Sensors > 0 THEN #Avg_Temperature := #Sum_Temp / INT_TO_REAL(#Valid_Sensors); ELSE #Avg_Temperature := 0.0; #Interlock_Active := TRUE; END_IF;

        IF #Avg_Temperature > #SCADA_Temp_High_Limit OR #Max_Temp > (#SCADA_Temp_High_Limit + 50.0) THEN #Over_Temp_Alarm := TRUE; ELSE #Over_Temp_Alarm := FALSE; END_IF;
        IF (#Max_Temp - #Min_Temp) > #SCADA_Temp_Spread_Limit AND #Valid_Sensors > 1 THEN #Spread_High_Alarm := TRUE; ELSE #Spread_High_Alarm := FALSE; END_IF;

        FOR #i := 1 TO 4 DO IF #Flame_Detectors[#i] THEN #Flame_Count := #Flame_Count + 1; END_IF; END_FOR;
        IF (#Turbine_Running OR #Turbine_Startup) AND (#Flame_Count < 2) THEN #Flame_Loss_Alarm := TRUE; ELSE #Flame_Loss_Alarm := FALSE; END_IF;

        IF (#Over_Temp_Alarm OR #Spread_High_Alarm OR #Flame_Loss_Alarm) AND NOT #Bypass_Enabled THEN #Interlock_Active := TRUE; END_IF;
        IF #SCADA_Reset THEN #Interlock_Active := FALSE; END_IF;

        #Trip_Signal := #Interlock_Active;
        IF #Trip_Signal THEN #Final_Fuel_Demand := 0.0; ELSE #Final_Fuel_Demand := #Base_Fuel_Demand; END_IF;

        #SCADA_Status_Word.%X0 := #Trip_Signal;
        #SCADA_Status_Word.%X1 := #Over_Temp_Alarm;
        #SCADA_Status_Word.%X2 := #Bypass_Enabled;
        #SCADA_Status_Word.%X3 := #Redundancy_Fault;
    ELSE
        #Trip_Signal := FALSE;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK "GasTurbine_Interlock_Adversarial"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.5
   VAR_INPUT 
      Temperature_Sensors_mA : ARRAY[1..12] OF REAL;
      Flame_Detectors : ARRAY[1..4] OF BOOL;
      Turbine_Running : BOOL;
      Turbine_Startup : BOOL;
      Base_Fuel_Demand : REAL;
      SCADA_Temp_High_Limit : REAL;
      SCADA_Temp_Spread_Limit : REAL;
      HIL_Mode_Active : BOOL; 
      Initiate_Self_Test : BOOL;
      Drift_Tolerance : REAL := 20.0;
   END_VAR
   VAR_OUTPUT 
      Trip_Signal : BOOL;
      Avg_Temperature : REAL;
      Final_Fuel_Demand : REAL;
      Sensor_Drift_Alarm : ARRAY[1..12] OF BOOL;
      Self_Test_Passed : BOOL;
   END_VAR
   VAR 
      Interlock_Active : BOOL;
      Max_Temp : REAL;
      Min_Temp : REAL;
      Sum_Temp : REAL;
      i, j : INT;
      Flame_Count : INT;
      Valid_Sensors : INT;
      Temperature_Sensors_Scaled : ARRAY[1..12] OF REAL;
      Over_Temp_Alarm, Spread_High_Alarm, Flame_Loss_Alarm : BOOL;
      Test_Step : INT;
      Test_Timer : INT;
      Sim_Over_Temp_Tripped : BOOL;
      Sim_Flame_Loss_Tripped : BOOL;
   END_VAR
BEGIN
    IF #Initiate_Self_Test AND NOT #Turbine_Running AND NOT #Turbine_Startup THEN
        #Test_Step := 1;
        #Self_Test_Passed := FALSE;
        #Sim_Over_Temp_Tripped := FALSE;
        #Sim_Flame_Loss_Tripped := FALSE;
    END_IF;

    IF #Test_Step > 0 THEN
        #Test_Timer := #Test_Timer + 1;
        IF #Test_Step = 1 THEN
            #Over_Temp_Alarm := TRUE;
            #Flame_Loss_Alarm := FALSE;
            IF #Interlock_Active THEN #Sim_Over_Temp_Tripped := TRUE; #Test_Step := 2; #Interlock_Active := FALSE; END_IF;
        ELSIF #Test_Step = 2 THEN
            #Over_Temp_Alarm := FALSE;
            #Flame_Loss_Alarm := TRUE;
            IF #Interlock_Active THEN #Sim_Flame_Loss_Tripped := TRUE; #Test_Step := 3; #Interlock_Active := FALSE; END_IF;
        ELSIF #Test_Step = 3 THEN
            IF #Sim_Over_Temp_Tripped AND #Sim_Flame_Loss_Tripped THEN
                #Self_Test_Passed := TRUE;
            END_IF;
            #Test_Step := 0;
            #Test_Timer := 0;
            #Over_Temp_Alarm := FALSE;
            #Flame_Loss_Alarm := FALSE;
        END_IF;

        #Trip_Signal := #Interlock_Active;
        RETURN;
    END_IF;

    #Max_Temp := -1000.0; #Min_Temp := 5000.0; #Sum_Temp := 0.0; #Flame_Count := 0; #Valid_Sensors := 0;

    FOR #i := 1 TO 12 DO
        IF #Temperature_Sensors_mA[#i] >= 3.8 AND #Temperature_Sensors_mA[#i] <= 20.5 THEN
            #Temperature_Sensors_Scaled[#i] := ((#Temperature_Sensors_mA[#i] - 4.0) / 16.0) * 1500.0;
            #Valid_Sensors := #Valid_Sensors + 1;
            IF #Temperature_Sensors_Scaled[#i] > #Max_Temp THEN #Max_Temp := #Temperature_Sensors_Scaled[#i]; END_IF;
            IF #Temperature_Sensors_Scaled[#i] < #Min_Temp THEN #Min_Temp := #Temperature_Sensors_Scaled[#i]; END_IF;
            #Sum_Temp := #Sum_Temp + #Temperature_Sensors_Scaled[#i];
        END_IF;
    END_FOR;

    FOR #i := 1 TO 12 DO
        #j := #i + 1;
        IF #j > 12 THEN #j := 1; END_IF;
        IF ABS(#Temperature_Sensors_Scaled[#i] - #Temperature_Sensors_Scaled[#j]) > #Drift_Tolerance THEN
            #Sensor_Drift_Alarm[#i] := TRUE;
        ELSE
            #Sensor_Drift_Alarm[#i] := FALSE;
        END_IF;
    END_FOR;

    IF #Valid_Sensors > 0 THEN #Avg_Temperature := #Sum_Temp / INT_TO_REAL(#Valid_Sensors); ELSE #Avg_Temperature := 0.0; #Interlock_Active := TRUE; END_IF;

    IF #Avg_Temperature > #SCADA_Temp_High_Limit OR #Max_Temp > (#SCADA_Temp_High_Limit + 50.0) THEN #Over_Temp_Alarm := TRUE; ELSE #Over_Temp_Alarm := FALSE; END_IF;
    IF (#Max_Temp - #Min_Temp) > #SCADA_Temp_Spread_Limit AND #Valid_Sensors > 1 THEN #Spread_High_Alarm := TRUE; ELSE #Spread_High_Alarm := FALSE; END_IF;

    FOR #i := 1 TO 4 DO IF #Flame_Detectors[#i] THEN #Flame_Count := #Flame_Count + 1; END_IF; END_FOR;
    IF (#Turbine_Running OR #Turbine_Startup) AND (#Flame_Count < 2) THEN #Flame_Loss_Alarm := TRUE; ELSE #Flame_Loss_Alarm := FALSE; END_IF;

    IF #Over_Temp_Alarm OR #Spread_High_Alarm OR #Flame_Loss_Alarm THEN #Interlock_Active := TRUE; END_IF;

    IF NOT #HIL_Mode_Active THEN
        #Trip_Signal := #Interlock_Active;
        IF #Trip_Signal THEN #Final_Fuel_Demand := 0.0; ELSE #Final_Fuel_Demand := #Base_Fuel_Demand; END_IF;
    END_IF;
END_FUNCTION_BLOCK

Here is a Beckhoff Structured Text (ST) program for a Battery Energy Storage System (BESS) that handles State of Charge (SOC) balancing among multiple battery racks and synchronizes with the inverter.

```iecst
TYPE ST_BatteryRack :
STRUCT
    fSOC           : LREAL; (* State of Charge (%) *)
    bChargeCmd     : BOOL;  (* Command to charge *)
    bDischargeCmd  : BOOL;  (* Command to discharge *)
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_BESS_Controller
VAR_INPUT
    aRacks         : ARRAY[1..4] OF ST_BatteryRack;
    bGridSyncCmd   : BOOL;
END_VAR
VAR_OUTPUT
    aRacksOut      : ARRAY[1..4] OF ST_BatteryRack;
    bInverterSync  : BOOL;
    fAverageSOC    : LREAL;
END_VAR
VAR
    i              : INT;
    fTotalSOC      : LREAL;
    fSocTolerance  : LREAL := 2.0; (* 2% tolerance for balancing *)
END_VAR

// Calculate Average SOC
fTotalSOC := 0.0;
FOR i := 1 TO 4 DO
    fTotalSOC := fTotalSOC + aRacks[i].fSOC;
    aRacksOut[i] := aRacks[i]; // Copy input to output
END_FOR;
fAverageSOC := fTotalSOC / 4.0;

// SOC Balancing Logic
FOR i := 1 TO 4 DO
    IF aRacksOut[i].fSOC < (fAverageSOC - fSocTolerance) THEN
        aRacksOut[i].bChargeCmd := TRUE;
        aRacksOut[i].bDischargeCmd := FALSE;
    ELSIF aRacksOut[i].fSOC > (fAverageSOC + fSocTolerance) THEN
        aRacksOut[i].bChargeCmd := FALSE;
        aRacksOut[i].bDischargeCmd := TRUE;
    ELSE
        aRacksOut[i].bChargeCmd := FALSE;
        aRacksOut[i].bDischargeCmd := FALSE;
    END_IF;
END_FOR;

// Inverter Sync Logic
IF bGridSyncCmd AND (fAverageSOC >= 10.0) AND (fAverageSOC <= 90.0) THEN
    bInverterSync := TRUE;
ELSE
    bInverterSync := FALSE;
END_IF;
```

Here is the Beckhoff ST program with the addition of a Thermal Management sub-system to handle HVAC and power derating based on cell temperatures.

```iecst
TYPE ST_BatteryRack_Thermal :
STRUCT
    fSOC           : LREAL;
    fTempC         : LREAL; (* Temperature in Celsius *)
    bChargeCmd     : BOOL;
    bDischargeCmd  : BOOL;
    fPowerLimit    : LREAL; (* Power derating multiplier 0.0 to 1.0 *)
    bCoolingReq    : BOOL;
    bHeatingReq    : BOOL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_BESS_AdvancedController
VAR_INPUT
    aRacks         : ARRAY[1..4] OF ST_BatteryRack_Thermal;
    bGridSyncCmd   : BOOL;
END_VAR
VAR_OUTPUT
    aRacksOut      : ARRAY[1..4] OF ST_BatteryRack_Thermal;
    bInverterSync  : BOOL;
    bGlobalHVAC    : BOOL;
END_VAR
VAR
    i              : INT;
    fTotalSOC      : LREAL;
    fAvgSOC        : LREAL;
    fSocTolerance  : LREAL := 2.0;

    // Thermal Limits
    fMaxTempAlert  : LREAL := 45.0;
    fMaxTempDerate : LREAL := 35.0;
    fMinTempAlert  : LREAL := 5.0;
END_VAR

fTotalSOC := 0.0;
bGlobalHVAC := FALSE;

FOR i := 1 TO 4 DO
    aRacksOut[i] := aRacks[i];
    fTotalSOC := fTotalSOC + aRacks[i].fSOC;

    // Thermal Management
    IF aRacksOut[i].fTempC >= fMaxTempAlert THEN
        aRacksOut[i].fPowerLimit := 0.0; // Shut down rack
        aRacksOut[i].bCoolingReq := TRUE;
    ELSIF aRacksOut[i].fTempC >= fMaxTempDerate THEN
        aRacksOut[i].fPowerLimit := 0.5; // 50% Derating
        aRacksOut[i].bCoolingReq := TRUE;
    ELSE
        aRacksOut[i].fPowerLimit := 1.0;
        aRacksOut[i].bCoolingReq := FALSE;
    END_IF;

    IF aRacksOut[i].fTempC <= fMinTempAlert THEN
        aRacksOut[i].bHeatingReq := TRUE;
    ELSE
        aRacksOut[i].bHeatingReq := FALSE;
    END_IF;

    IF aRacksOut[i].bCoolingReq OR aRacksOut[i].bHeatingReq THEN
        bGlobalHVAC := TRUE;
    END_IF;
END_FOR;

fAvgSOC := fTotalSOC / 4.0;

// SOC Balancing (considering power limits)
FOR i := 1 TO 4 DO
    IF aRacksOut[i].fPowerLimit > 0.0 THEN
        IF aRacksOut[i].fSOC < (fAvgSOC - fSocTolerance) THEN
            aRacksOut[i].bChargeCmd := TRUE;
            aRacksOut[i].bDischargeCmd := FALSE;
        ELSIF aRacksOut[i].fSOC > (fAvgSOC + fSocTolerance) THEN
            aRacksOut[i].bChargeCmd := FALSE;
            aRacksOut[i].bDischargeCmd := TRUE;
        ELSE
            aRacksOut[i].bChargeCmd := FALSE;
            aRacksOut[i].bDischargeCmd := FALSE;
        END_IF;
    ELSE
        aRacksOut[i].bChargeCmd := FALSE;
        aRacksOut[i].bDischargeCmd := FALSE;
    END_IF;
END_FOR;

// Inverter Sync
