    TraversePosition : REAL;
    TraverseDirection : BOOL := 1;
    SpoolWidth : REAL := 500.0;
    TraverseSpeed : REAL;
END_VAR

// Tension Cascade Control
TensionError := TensionSetpoint - TensionActual;
TensionIntegral := TensionIntegral + (TensionError * Ki_Tension);
IF TensionIntegral > 20.0 THEN TensionIntegral := 20.0; END_IF;
IF TensionIntegral < -20.0 THEN TensionIntegral := -20.0; END_IF;
TrimSpeed := (TensionError * Kp_Tension) + TensionIntegral;
CapstanSpeedCmd := MasterLineSpeed + TrimSpeed;

