FUNCTION_BLOCK "FB_Autoclave_Base"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.1
VAR_INPUT
    Start_Cycle : Bool;
    Stop_Cycle : Bool;
    Temp_Process : Real;
    Vacuum_Level : Real;
END_VAR
VAR_OUTPUT
    Heater_Ctrl : Real;
    Vacuum_Pump : Bool;
    Vent_Valve : Bool;
    State : Int;
END_VAR
VAR
    PID_Temp {InstructionName := 'PID_Compact'; LibVersion := '2.2'} : PID_Compact;
    Ramp_SP : Real;
    Timer_Soak {InstructionName := 'TON_TIME'; LibVersion := '1.0'} : TON_TIME;
END_VAR

BEGIN
    // Base State Machine
    IF #Stop_Cycle THEN
        #State := 0; // IDLE
    ELSIF #Start_Cycle AND #State = 0 THEN
        #State := 1; // RAMP
    END_IF;

    CASE #State OF
        0: // IDLE
            #Vacuum_Pump := FALSE;
            #Vent_Valve := TRUE;
            #Heater_Ctrl := 0.0;
        1: // VACUUM & RAMP
            #Vent_Valve := FALSE;
            IF #Vacuum_Level > 0.05 THEN
                #Vacuum_Pump := TRUE;
            ELSE
                #Vacuum_Pump := FALSE;
                #Ramp_SP := 121.0; // Sterilization Temp
            END_IF;

            #PID_Temp(Setpoint:=#Ramp_SP, Input:=#Temp_Process);
            #Heater_Ctrl := #PID_Temp.Output;

            IF #Temp_Process >= 121.0 THEN
                #State := 2; // SOAK
            END_IF;
        2: // SOAK
            #Timer_Soak(IN:=TRUE, PT:=T#15M);
            #PID_Temp(Setpoint:=121.0, Input:=#Temp_Process);
            #Heater_Ctrl := #PID_Temp.Output;
            IF #Timer_Soak.Q THEN
                #State := 3; // VENT
            END_IF;
        3: // VENT
            #Vacuum_Pump := FALSE;
            #Vent_Valve := TRUE;
            #Heater_Ctrl := 0.0;
            #Timer_Soak(IN:=FALSE, PT:=T#15M);
            IF #Vacuum_Level > 0.95 THEN
                #State := 0;
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK

