Here is the advanced Siemens SCL program incorporating IEC 62443 cybersecurity principles, redundant pump failover, and SCADA integration tags.

```scl
FUNCTION_BLOCK "PaintBooth_Mut3_Cyber_Failover_SCADA"
VERSION : 1.3
VAR_INPUT
    bStart_PB : Bool;
    bStop_PB : Bool;
    bCar_In_Position : Bool;
    rOverspray_Concentration : Real;
    rTemp_Actual : Real;
    rHumidity_Actual : Real;
    wPN_Status_Word : Word;

    // Cybersecurity & SCADA
    bSCADA_User_Authenticated : Bool;
    iSecurityLevel : Int; // 0=None, 1=Operator, 2=Admin (IEC 62443 Zones/Conduits principle)
    bPump1_Alarm : Bool;
    bPump2_Alarm : Bool;
END_VAR

VAR_OUTPUT
    bConveyor_Motor : Bool;
    bRobot_Enable : Bool;
    bExhaust_Fan : Bool;
    bCapture_Pump1 : Bool;
    bCapture_Pump2 : Bool;
    rHeater_Valve : Real; 
    rHumidifier_Valve : Real; 
    wPN_Control_Word : Word;

    // SCADA Tags
    wSCADA_State : Word;
    bFault_Active : Bool;
    iFault_Code : Int;
END_VAR

VAR
    bSystem_Running : Bool;
    iState : Int;
    iActive_Pump : Int := 1;

    // Auth Timer
    tAuthTimeout : TON;
    bSec_Lockout : Bool;
END_VAR

BEGIN
    // IEC 62443 Principle: Authenticate before execution
    #tAuthTimeout(IN := #bSCADA_User_Authenticated, PT := T#10m); // Force re-auth
    #bSec_Lockout := (#iSecurityLevel < 1) OR #tAuthTimeout.Q;

    IF #bSec_Lockout THEN
        #bSystem_Running := FALSE;
        #iFault_Code := 999; // Security Lockout
    END_IF;

    // Pump Failover Logic
    IF #iActive_Pump = 1 AND #bPump1_Alarm AND NOT #bPump2_Alarm THEN
        #iActive_Pump := 2;
    ELSIF #iActive_Pump = 2 AND #bPump2_Alarm AND NOT #bPump1_Alarm THEN
        #iActive_Pump := 1;
    END_IF;

    // Start/Stop
    IF #bStop_PB OR #bSec_Lockout THEN
        #bSystem_Running := FALSE;
    ELSIF #bStart_PB AND NOT #bSec_Lockout THEN
        #bSystem_Running := TRUE;
    END_IF;

    // SCADA Status Update
    #wSCADA_State := INT_TO_WORD(#iState);

    // State Machine
    IF NOT #bSystem_Running THEN #iState := 0; ELSIF #bSystem_Running AND #iState = 0 THEN #iState := 1; END_IF;

    CASE #iState OF
        0: // Stop
            #bConveyor_Motor := FALSE;
            #bRobot_Enable := FALSE;
            #wPN_Control_Word := 16#0000;
        1: // Index
            #bRobot_Enable := FALSE;
            #wPN_Control_Word := 16#0000;
            IF NOT #bCar_In_Position THEN #bConveyor_Motor := TRUE;
            ELSE #bConveyor_Motor := FALSE; #iState := 2;
            END_IF;
        2: // Painting
            #bConveyor_Motor := FALSE;
            #bRobot_Enable := TRUE;
            #wPN_Control_Word := 16#0001; 
    END_CASE;

    // Overspray Capture with Redundancy
    IF #bSystem_Running AND (#rOverspray_Concentration > 60.0) THEN
        IF #iActive_Pump = 1 AND NOT #bPump1_Alarm THEN
            #bCapture_Pump1 := TRUE;
            #bCapture_Pump2 := FALSE;
        ELSIF #iActive_Pump = 2 AND NOT #bPump2_Alarm THEN
            #bCapture_Pump1 := FALSE;
            #bCapture_Pump2 := TRUE;
        ELSE // Both Failed
            #bCapture_Pump1 := FALSE;
            #bCapture_Pump2 := FALSE;
            #iFault_Code := 401; 
        END_IF;
    ELSE
        #bCapture_Pump1 := FALSE;
        #bCapture_Pump2 := FALSE;
    END_IF;

END_FUNCTION_BLOCK
```

Here is the highly complex Siemens SCL program that addresses the adversarial conditions: sensor drift detection, HIL digital twin heartbeat synchronization, and an automated start-up self-test.

```scl
FUNCTION_BLOCK "PaintBooth_Mut4_Adversarial"
VERSION : 1.4
VAR_INPUT
    bStart_PB : Bool;
    bStop_PB : Bool;
    bCar_In_Position : Bool;
    rOverspray_SensA : Real; // Dual redundancy for drift
    rOverspray_SensB : Real;
    rTemp_Actual : Real;
    wPN_Status_Word : Word;
    bSCADA_User_Auth : Bool;
    iSecurityLevel : Int;
    bHIL_Sync_Pulse : Bool; // Digital Twin Heartbeat
END_VAR

VAR_OUTPUT
    bConveyor_Motor : Bool;
    bRobot_Enable : Bool;
    bCapture_Pump1 : Bool;
    bCapture_Pump2 : Bool;
    bHIL_Acknowledge : Bool; // Digital Twin Ack
    bFault_Active : Bool;
    iFault_Code : Int;
END_VAR

VAR
    bSystem_Running : Bool;
    iState : Int; // 0=Stop, 1=Self-Test, 2=Index, 3=Paint
    rOverspray_Resolved : Real;

    // Adversarial Vars
    tHIL_Watchdog : TON;
    tSelfTest_Timer : TON;
    bDrift_Fault : Bool;
    bHIL_Fault : Bool;
    bSelfTest_Pass : Bool;
END_VAR

BEGIN
    // Adversarial 1: Sensor Drift Detection
    IF ABS(#rOverspray_SensA - #rOverspray_SensB) > 5.0 THEN
        #bDrift_Fault := TRUE;
        #rOverspray_Resolved := 100.0; // Failsafe
    ELSE
        #bDrift_Fault := FALSE;
        #rOverspray_Resolved := (#rOverspray_SensA + #rOverspray_SensB) / 2.0;
    END_IF;

    // Adversarial 2: HIL Digital Twin Heartbeat Sync
    #tHIL_Watchdog(IN := NOT #bHIL_Sync_Pulse, PT := T#500ms);
    #bHIL_Fault := #tHIL_Watchdog.Q;
    #bHIL_Acknowledge := #bHIL_Sync_Pulse; // Echo back to Twin

    // Security & Faults
    IF (#iSecurityLevel < 1) OR NOT #bSCADA_User_Auth OR #bDrift_Fault OR #bHIL_Fault THEN
        #bSystem_Running := FALSE;
        #bFault_Active := TRUE;
        IF #bDrift_Fault THEN #iFault_Code := 601;
        ELSIF #bHIL_Fault THEN #iFault_Code := 701;
        END_IF;
    ELSE
        #bFault_Active := FALSE;
    END_IF;

    // Start/Stop
    IF #bStop_PB THEN #bSystem_Running := FALSE;
    ELSIF #bStart_PB AND NOT #bFault_Active THEN #bSystem_Running := TRUE;
    END_IF;

    IF NOT #bSystem_Running THEN
        #iState := 0;
        #bSelfTest_Pass := FALSE;
    ELSIF #bSystem_Running AND #iState = 0 THEN
        #iState := 1; // Enter Self-Test
    END_IF;

    // State Machine
    CASE #iState OF
        0: // Stop
            #bConveyor_Motor := FALSE;
            #bRobot_Enable := FALSE;

        1: // Adversarial 3: Automated Startup Self-Test
            #bRobot_Enable := FALSE;
            #bConveyor_Motor := FALSE;
            // Bump pumps to verify contactors (simulated)
            #tSelfTest_Timer(IN := TRUE, PT := T#3s);
            IF #tSelfTest_Timer.Q THEN
                #bSelfTest_Pass := TRUE;
                #iState := 2; // Move to Indexing
                #tSelfTest_Timer(IN := FALSE, PT := T#3s);
            END_IF;

        2: // Index
            IF NOT #bCar_In_Position THEN #bConveyor_Motor := TRUE;
            ELSE #bConveyor_Motor := FALSE; #iState := 3;
            END_IF;

        3: // Painting
            #bRobot_Enable := TRUE;
    END_CASE;

    // Overspray Management
    IF #bSystem_Running AND #bSelfTest_Pass AND (#rOverspray_Resolved > 60.0) THEN
        #bCapture_Pump1 := TRUE;
    ELSE
        #bCapture_Pump1 := FALSE;
    END_IF;
END_FUNCTION_BLOCK
```

