Here is the base Allen-Bradley Structured Text (ST) program for the Engine Block Machining Center:

```iecst
PROGRAM EngineBlockMachining
VAR
    StartPB : BOOL;
    StopPB : BOOL;
    SpindleMotor : BOOL;
    SpindleLoad : REAL;
    MaxSpindleLoad : REAL := 85.0;
    ToolWearOffset : REAL;
    ToolLifeCycles : DINT;
    MaxToolLifeCycles : DINT := 10000;
    AlarmLoad : BOOL;
    AlarmToolWear : BOOL;
    MachiningActive : BOOL;
END_VAR

// Main Control
IF StartPB AND NOT StopPB AND NOT AlarmLoad AND NOT AlarmToolWear THEN
    MachiningActive := TRUE;
    SpindleMotor := TRUE;
ELSIF StopPB OR AlarmLoad OR AlarmToolWear THEN
    MachiningActive := FALSE;
    SpindleMotor := FALSE;
END_IF;

// Spindle Load Monitoring
IF SpindleLoad > MaxSpindleLoad THEN
    AlarmLoad := TRUE;
ELSE
    AlarmLoad := FALSE;
END_IF;

// Tool Wear Compensation
IF MachiningActive THEN
    ToolLifeCycles := ToolLifeCycles + 1;
END_IF;

IF ToolLifeCycles >= MaxToolLifeCycles THEN
    AlarmToolWear := TRUE;
ELSE
    // Calculate wear offset linearly up to 0.05mm
    ToolWearOffset := (DINT_TO_REAL(ToolLifeCycles) / DINT_TO_REAL(MaxToolLifeCycles)) * 0.05;
END_IF;
END_PROGRAM
```

