PROGRAM PRG_HighSpeedSorter
VAR
    bSensorEntry AT %I* : BOOL;
    bBarcodeTrigger AT %Q* : BOOL;
    sBarcodeData AT %I* : STRING(255);
    bBarcodeNewData AT %I* : BOOL;
