    tDiverterDelay : TON;
    tGateOpenTime : TON;
    bValidItem : BOOL;
END_VAR

CASE eState OF
    WAIT_FOR_ITEM:
        bPneumaticDiverter := FALSE;
        bBarcodeTrigger := FALSE;
        IF bSensorEntry THEN
            eState := TRIGGER_SCANNER;
        END_IF

    TRIGGER_SCANNER:
        bBarcodeTrigger := TRUE;
        IF bBarcodeNewData THEN
            bBarcodeTrigger := FALSE;
            eState := WAIT_FOR_DATA;
        END_IF

    WAIT_FOR_DATA:
        IF sBarcodeData = 'TARGET_DEST' THEN
            bValidItem := TRUE;
        ELSE
            bValidItem := FALSE;
        END_IF
        eState := ACTUATE_DIVERTER;

    ACTUATE_DIVERTER:
        tDiverterDelay(IN := TRUE, PT := T#200MS);
        IF tDiverterDelay.Q THEN
            IF bValidItem THEN
                bPneumaticDiverter := TRUE;
            END_IF
            tDiverterDelay(IN := FALSE);
            eState := RESET_GATE;
        END_IF

    RESET_GATE:
        tGateOpenTime(IN := TRUE, PT := T#500MS);
        IF tGateOpenTime.Q THEN
            bPneumaticDiverter := FALSE;
            tGateOpenTime(IN := FALSE);
            eState := WAIT_FOR_ITEM;
        END_IF
END_CASE
