```pascal
PROGRAM PRG_HighSpeedSorter_Cyber_SCADA
VAR
    // Cybersecurity & Access Control
    nCurrentAccessLevel : INT; // 0=Guest, 1=Operator, 2=Admin
    bManualOverrideCmd : BOOL;

    // Hot-Standby Failover
    fbAdsWrite : ADSWRITE;
    stCriticalData : STRUCT
        nTotalSorted : UDINT;
        nTotalFaults : UDINT;
    END_STRUCT;
    bSyncPulse : BOOL;

    // MQTT SCADA
    fbMqttClient : FB_IotMqttClient;
    sTopicPub : STRING(255) := 'factory/sorter/status';
    sPayload : STRING(255);
    tPublishTimer : TON;

    // Process Variables
    bSystemFault : BOOL;
    eState : INT;
END_VAR

// Cybersecurity: Check Access Level for Manual Override
IF bManualOverrideCmd AND nCurrentAccessLevel < 2 THEN
    // Log Security Event: Unauthorized Access Attempt
    bManualOverrideCmd := FALSE;
END_IF

// Hot-Standby Failover via ADS (Sync to Secondary PLC)
bSyncPulse := NOT bSyncPulse;
fbAdsWrite(
    NETID := '192.168.1.20.1.1',
    PORT := 851,
    IDXGRP := 16#4020,
    IDXOFFS := 0,
    LEN := SIZEOF(stCriticalData),
    SRCADDR := ADR(stCriticalData),
    WRITE := bSyncPulse
);

// SCADA Integration via MQTT
fbMqttClient.Execute(bConnect := TRUE);
tPublishTimer(IN := NOT tPublishTimer.Q, PT := T#1S);

IF fbMqttClient.bConnected AND tPublishTimer.Q THEN
    sPayload := CONCAT('{"Sorted":', UDINT_TO_STRING(stCriticalData.nTotalSorted));
    sPayload := CONCAT(sPayload, ',"Faults":');
    sPayload := CONCAT(sPayload, UDINT_TO_STRING(stCriticalData.nTotalFaults));
    sPayload := CONCAT(sPayload, '}');

    fbMqttClient.Publish(
        sTopic := sTopicPub,
        pPayload := ADR(sPayload),
        nPayloadSize := LEN(sPayload),
        eQoS := TcIotMqttQos.AtMostOnceDelivery,
        bRetain := FALSE,
        bQueue := FALSE
    );
END_IF

// Sorter Logic (Simplified)
IF eState = 40 THEN
    stCriticalData.nTotalSorted := stCriticalData.nTotalSorted + 1;
    eState := 10;
END_IF
IF bSystemFault THEN
    stCriticalData.nTotalFaults := stCriticalData.nTotalFaults + 1;
END_IF
