Here is the most advanced iteration. It incorporates a startup self-test to cycle the diverter, a moving average filter to detect sensor drift, and a HIL mode that overrides physical I/O with ADS data from a physics simulation engine.

```pascal
PROGRAM PRG_HighSpeedSorter_Advanced
VAR
    // HIL Digital Twin Mode
    bHIL_Mode : BOOL;
    bSimSensorEntry : BOOL;
    bSimDiverterExtended : BOOL;

    // Physical I/O mapped to unified variables
    bPhysSensorEntry AT %I* : BOOL;
    bPhysDiverterExtended AT %I* : BOOL;

    bActiveSensorEntry : BOOL;
    bActiveDiverterExtended : BOOL;

    // Sensor Drift Detection
    tSensorPulse : TON;
    fAvgResponseTime : LREAL;
    fResponseTimeArray : ARRAY[0..99] OF LREAL;
    nDriftIndex : INT;
    bSensorDriftWarning : BOOL;

    // Self-Test Routine
    bStartupComplete : BOOL;
    nTestStep : INT;
    tTestTimer : TON;
    bPneumaticDiverter AT %Q* : BOOL;

    eState : INT;
END_VAR

// HIL I/O Multiplexer
IF bHIL_Mode THEN
    bActiveSensorEntry := bSimSensorEntry;
    bActiveDiverterExtended := bSimDiverterExtended;
ELSE
    bActiveSensorEntry := bPhysSensorEntry;
    bActiveDiverterExtended := bPhysDiverterExtended;
END_IF

// Self-Test Routine on Startup
IF NOT bStartupComplete THEN
    CASE nTestStep OF
        0: // Start Test
            bPneumaticDiverter := TRUE;
            tTestTimer(IN:=TRUE, PT:=T#500MS);
            IF bActiveDiverterExtended THEN
                nTestStep := 1;
                tTestTimer(IN:=FALSE);
            ELSIF tTestTimer.Q THEN
                nTestStep := 99; // Failed
            END_IF
        1: // Reset Gate
            bPneumaticDiverter := FALSE;
            IF NOT bActiveDiverterExtended THEN
                bStartupComplete := TRUE;
                eState := 10; // Ready
            END_IF
    END_CASE
    RETURN;
END_IF

// Sensor Drift Detection Algorithm
IF bActiveSensorEntry THEN
    tSensorPulse(IN:=TRUE, PT:=T#10S);
ELSE
    IF tSensorPulse.IN THEN
        // Record pulse duration
        fResponseTimeArray[nDriftIndex] := TIME_TO_LREAL(tSensorPulse.ET);
        nDriftIndex := (nDriftIndex + 1) MOD 100;

        // Calculate Moving Average
        fAvgResponseTime := 0;
        FOR nDriftIndex := 0 TO 99 DO
            fAvgResponseTime := fAvgResponseTime + fResponseTimeArray[nDriftIndex];
        END_FOR
        fAvgResponseTime := fAvgResponseTime / 100.0;

        // Drift Threshold Check (> 50ms expected)
        IF fAvgResponseTime > 50.0 THEN
            bSensorDriftWarning := TRUE;
        END_IF
    END_IF
    tSensorPulse(IN:=FALSE);
END_IF

// Main Sorter Logic (Runs in State 10+)
