PROGRAM Palletizer_M2
VAR
    // Base
    Pallet_Full : BOOL := FALSE;
    Current_Layer : INT := 0;
    Max_Layers : INT := 5;
    Cases_In_Layer : INT := 0;
    Max_Cases_Per_Layer : INT := 10;
    Slip_Sheet_Placed : BOOL := FALSE;
    Robot_Cmd : INT := 0;
    Robot_Status_Done : BOOL;

    // Depth (Weight)
    Incoming_Weight : REAL;
    Layer_Weight : REAL := 0.0;
    Max_Layer_Weight : REAL := 250.0;

    // Breadth (EIP & Diagnostics)
    EIP_Connection_Status : DINT;
    EIP_Comm_Fault : BOOL;
    Fault_Code : DINT := 0;
    Diagnostic_Active : BOOL := TRUE;
END_VAR

// Diagnostics & EIP Check
IF EIP_Connection_Status <> 16#00 THEN
    EIP_Comm_Fault := TRUE;
    Fault_Code := 1001;
END_IF;

IF NOT Pallet_Full AND Fault_Code = 0 THEN
    IF Current_Layer < Max_Layers THEN
        IF Cases_In_Layer < Max_Cases_Per_Layer THEN
            IF (Layer_Weight + Incoming_Weight) > Max_Layer_Weight THEN
                Fault_Code := 2001; // Weight Fault
            ELSE
                Robot_Cmd := 1; // 1 = Place Case
                IF Robot_Status_Done THEN
                    Cases_In_Layer := Cases_In_Layer + 1;
                    Layer_Weight := Layer_Weight + Incoming_Weight;
                    Robot_Cmd := 0;
                END_IF;
            END_IF;
        ELSE
            IF (Current_Layer MOD 2 = 1) AND NOT Slip_Sheet_Placed THEN
                Robot_Cmd := 2; // 2 = Place Slip Sheet
                IF Robot_Status_Done THEN
                    Slip_Sheet_Placed := TRUE;
                    Robot_Cmd := 0;
