            bSpliceReq := FALSE;
            bSplicerSync := FALSE;
            fOldRollDiameter := fNewRollDiameter; 
        END_IF
    END_IF

    // Web Tension Control System PID
    fTensionError := fTensionSetpoint - fActualTension;
    IF ABS(fTensionError) > 15.0 THEN
        bTensionFault := TRUE; // Diagnostic limit
    ELSE
        bTensionFault := FALSE;
    END_IF

