VAR
    bStartPrint : BOOL := FALSE;
    bColorRegActive : BOOL := TRUE;
    bSplicerSync : BOOL := FALSE;

    // Color & Splicer
    fMarkPosition : LREAL; fTargetPosition : LREAL := 100.0; fColorError : LREAL; fPhaseCorrection : LREAL;
    bSpliceReq : BOOL := FALSE; fOldRollDiameter : LREAL := 500.0; fNewRollDiameter : LREAL := 1000.0; bSpliceComplete : BOOL := FALSE;

    // Web Tension Control
    fTensionSetpoint : LREAL := 50.0; fActualTension : LREAL; fTensionError : LREAL; fTensionOut : LREAL; fTensionInt : LREAL;

    // EtherCAT & Faults
    nEcatState AT %I* : UINT; bEcatError : BOOL;
    bTensionFault : BOOL; bColorFault : BOOL; bSystemFault : BOOL;

    // IEC 62443 Cybersecurity Role-Based Access
    nCurrentRole : INT; // 0=Guest, 1=Operator, 2=Admin
    bAccessDenied : BOOL;

    // Failover Logic
    bRedundantBusActive : BOOL;
    bSplicerFailoverActive : BOOL;

    // SCADA OPC-UA Integration
    {attribute 'OPC.UA.DA' := '1'}
    fScadaTensionData : LREAL;
    {attribute 'OPC.UA.DA' := '1'}
    bScadaSystemStatus : BOOL;
END_VAR

