```scl
FUNCTION_BLOCK "FB_WeavingLoom_Adversarial"
VERSION : 0.1
VAR_INPUT
    TensionSensor_1_Actual : Real;
    TensionSensor_2_Actual : Real;
    HIL_Mode_Active : Bool;
    HIL_Simulated_Tension : Real;
