Here is a standard Siemens SCL program for an RO Skid regulating a High-Pressure Pump using PID and handling Membrane Flush:

```pascal
FUNCTION_BLOCK "RO_Skid_Base"
VERSION : 0.1
VAR_INPUT
    StartCmd : Bool;
    StopCmd : Bool;
    PermeateFlow_PV : Real;
    PermeateFlow_SP : Real;
    FlushReq : Bool;
END_VAR
VAR_OUTPUT
    HPPump_Run : Bool;
    HPPump_Speed : Real;
    InletValve : Bool;
    FlushValve : Bool;
END_VAR
VAR
    State : Int; // 0=Stop, 1=Run, 2=Flush
    Integral : Real;
    Error : Real;
    Kp : Real := 1.5;
    Ki : Real := 0.2;
END_VAR
BEGIN
    IF StopCmd THEN
        State := 0;
    ELSIF StartCmd AND State = 0 THEN
        State := 1;
    ELSIF FlushReq THEN
        State := 2;
    END_IF;

    CASE State OF
        0: // Stop
            HPPump_Run := False;
            HPPump_Speed := 0.0;
            InletValve := False;
            FlushValve := False;
        1: // Run
            InletValve := True;
            FlushValve := False;
            HPPump_Run := True;
            Error := PermeateFlow_SP - PermeateFlow_PV;
            Integral := Integral + (Error * Ki);
            HPPump_Speed := (Error * Kp) + Integral;
        2: // Flush
            InletValve := True;
            FlushValve := True;
            HPPump_Run := True;
            HPPump_Speed := 40.0;
    END_CASE;
END_FUNCTION_BLOCK
```

