FUNCTION_BLOCK "RO_Skid_Dosing"
VAR_INPUT
    FeedFlow_PV : Real;
    ORP_PV : Real;
    ORP_SP : Real;
END_VAR
VAR_OUTPUT
    Antiscalant_Pump_Speed : Real;
    SMBS_Pump_Speed : Real;
END_VAR
VAR
    SMBS_Integral : Real;
END_VAR
BEGIN
    // ... [Previous RO and Flush Logic] ...

    // Chemical Dosing - Antiscalant (Feed-forward)
    Antiscalant_Pump_Speed := FeedFlow_PV * 0.05; // 5% ratio dosing

    // Chemical Dosing - SMBS (Feed-forward + Feedback trim)
    SMBS_Integral := SMBS_Integral + ((ORP_PV - ORP_SP) * 0.1);
    SMBS_Pump_Speed := (FeedFlow_PV * 0.02) + SMBS_Integral;

    IF SMBS_Pump_Speed < 0.0 THEN SMBS_Pump_Speed := 0.0; END_IF;
    IF SMBS_Pump_Speed > 100.0 THEN SMBS_Pump_Speed := 100.0; END_IF;
END_FUNCTION_BLOCK
