Here is the SCL program with Cybersecurity, Pump Failover, and SCADA Heartbeat:

```pascal
FUNCTION_BLOCK "RO_Skid_Cyber_Failover"
VAR_INPUT
    UserRole : Int; // 1=Operator, 2=Admin
    SCADA_Heartbeat : Bool;
END_VAR
VAR
    Heartbeat_Timer : TON;
    Active_Pump : Int := 1;
    Pump1_Fault : Bool;
    Pump2_Fault : Bool;
    Comms_Loss : Bool;
END_VAR
BEGIN
    // SCADA Heartbeat Monitoring
    Heartbeat_Timer(IN := NOT SCADA_Heartbeat, PT := T#5s);
    IF Heartbeat_Timer.Q THEN
        Comms_Loss := True;
        State := 0; // Fail-safe shutdown
    END_IF;

    // Role-based Access Control (IEC 62443 Concept)
    IF UserRole < 1 THEN
        // Unauthenticated - block commands
        StartCmd := False;
        StopCmd := True;
    END_IF;

    // Duty/Standby Failover Logic
    IF Active_Pump = 1 AND Pump1_Fault THEN
        Active_Pump := 2;
    ELSIF Active_Pump = 2 AND Pump2_Fault THEN
        Active_Pump := 1;
    END_IF;

    // Output Assignment
    HPPump1_Run := (Active_Pump = 1) AND (State = 1);
    HPPump2_Run := (Active_Pump = 2) AND (State = 1);
END_FUNCTION_BLOCK
