VAR
    WellLevel_A : REAL;
    WellLevel_B : REAL;
    WellLevel_Avg : REAL;
    Drift_Alarm : BOOL;
    Max_Drift : REAL := 0.5;
    HIL_Mode_Active : BOOL;
    Twin_Level_Sim : REAL;
    Twin_Sync_Error : REAL;
    Self_Test_Trigger : BOOL;
    Self_Test_Active : BOOL;
    Self_Test_Step : INT;
    Self_Test_Timer : TON;
    Pump1_Cmd : BOOL;
    System_Ready : BOOL;
END_VAR

IF ABS(WellLevel_A - WellLevel_B) > Max_Drift THEN
    Drift_Alarm := TRUE;
    WellLevel_Avg := WellLevel_A;
ELSE
    Drift_Alarm := FALSE;
    WellLevel_Avg := (WellLevel_A + WellLevel_B) / 2.0;
END_IF;

IF HIL_Mode_Active THEN
    Twin_Sync_Error := WellLevel_Avg - Twin_Level_Sim;
    IF ABS(Twin_Sync_Error) > 1.0 THEN
        System_Ready := FALSE;
    ELSE
        System_Ready := TRUE;
        WellLevel_Avg := Twin_Level_Sim;
    END_IF;
ELSE
    System_Ready := NOT Drift_Alarm;
END_IF;

IF Self_Test_Trigger AND NOT Self_Test_Active THEN
    Self_Test_Active := TRUE;
    Self_Test_Step := 1;
END_IF;

IF Self_Test_Active THEN
    Self_Test_Timer(IN := TRUE, PT := T#3s);
    CASE Self_Test_Step OF
        1:
            Pump1_Cmd := TRUE;
            IF Self_Test_Timer.Q THEN
                Self_Test_Step := 2;
                Self_Test_Timer(IN := FALSE);
            END_IF;
        2:
            Pump1_Cmd := FALSE;
            IF Self_Test_Timer.Q THEN
                Self_Test_Active := FALSE;
                Self_Test_Trigger := FALSE;
                Self_Test_Timer(IN := FALSE);
            END_IF;
    END_CASE;
ELSE
    IF System_Ready AND WellLevel_Avg > 5.0 THEN
        Pump1_Cmd := TRUE;
    ELSE
        Pump1_Cmd := FALSE;
    END_IF;
END_IF;
END_PROGRAM
```

