      #stat_ActiveEjector := 2;
   ELSIF #stat_ActiveEjector = 2 AND #i_Ejector2_Fault AND NOT #i_Ejector1_Fault THEN
      #stat_ActiveEjector := 1;
   END_IF;

   // Start/Stop Logic
   IF #i_StartCmd AND NOT #i_StopCmd AND NOT #q_ScadaCommFault THEN
      #stat_Running := TRUE;
   ELSIF #i_StopCmd OR #q_ScadaCommFault THEN
      #stat_Running := FALSE;
