bEtherCAT_OK := (wWcState = 0) AND (wState = 8);

// Out-of-bounds sensor checks
bSensorFault_Supply := (fActualSupplyTemp < -20.0) OR (fActualSupplyTemp > 120.0);
bSensorFault_Return := (fActualReturnTemp < -20.0) OR (fActualReturnTemp > 120.0);
bSystemFault := bSensorFault_Supply OR bSensorFault_Return OR NOT bEtherCAT_OK;

IF NOT bSystemFault THEN
    fSupplyTemp_SP := LIMIT(40.0, 90.0 - (1.5 * fOutdoorTemp), 90.0);

    fbPID_Temp(fSetpoint := fSupplyTemp_SP, fActualValue := fActualSupplyTemp, fKp := 2.5, fTi := 100.0, fControlValue => fPrimaryValveCmd);

