    bSimulationMode : BOOL;
    nHIL_Heartbeat : UDINT;
    nHIL_LastHeartbeat : UDINT;
    tHIL_Timeout : TON;
    bHIL_Fault : BOOL;

    // Self-test routine
    nStartupState : INT := 0;
    tSelfTestDelay : TON;
    bSelfTestComplete : BOOL;

    fPrimaryValveCmd : REAL;
    fPumpSpeedCmd : REAL;
END_VAR

// HIL Digital Twin Heartbeat Monitor
tHIL_Timeout(IN := bSimulationMode AND (nHIL_Heartbeat = nHIL_LastHeartbeat), PT := T#2S, Q => bHIL_Fault);
IF nHIL_Heartbeat <> nHIL_LastHeartbeat THEN
    nHIL_LastHeartbeat := nHIL_Heartbeat;
END_IF

// Sensor Drift Detection
bSensorDriftAlarm := ABS(fSupplyTemp1 - fSupplyTemp2) > fDriftThreshold;

// Startup Self Test Routine State Machine
CASE nStartupState OF
    0: // Init
        fPrimaryValveCmd := 0.0;
        fPumpSpeedCmd := 0.0;
        tSelfTestDelay(IN := TRUE, PT := T#5S);
        IF tSelfTestDelay.Q THEN
            nStartupState := 1;
            tSelfTestDelay(IN := FALSE);
        END_IF

    1: // Actuator Test (Pulse Valve)
        fPrimaryValveCmd := 100.0;
        tSelfTestDelay(IN := TRUE, PT := T#5S);
        IF tSelfTestDelay.Q THEN
            fPrimaryValveCmd := 0.0;
            nStartupState := 2;
            tSelfTestDelay(IN := FALSE);
        END_IF

    2: // Test Complete
        bSelfTestComplete := TRUE;
        nStartupState := 3;

    3: // Normal Operation
        IF bSelfTestComplete AND NOT bSensorDriftAlarm AND NOT bHIL_Fault THEN
            // Execute normal PID logic here (omitted for brevity)
            fPrimaryValveCmd := 50.0;
        ELSE
            // Fallback / Safe state
            fPrimaryValveCmd := 0.0;
        END_IF
END_CASE
