        IF Mill_Weight_1 < 50.0 AND Lube_Pressure_Main > 10.0 THEN // Basic plausibility
            Self_Test_Passed := TRUE;
            Self_Test_Active := FALSE;
        ELSE
            // Fail self-test, hold in safe state
            Feed_Conveyor_Speed := 0.0;
            Lube_Pump_Speed := 0.0;
            RETURN;
        END_IF;
    ELSE
        RETURN;
    END_IF;
END_IF;

// 2. Sensor Drift Detection
IF ABS(Mill_Weight_1 - Mill_Weight_2) > (Max_Allowed_Drift / 100.0 * 600.0) THEN
    Weight_Drift_Error := TRUE;
ELSE
    Weight_Drift_Error := FALSE;
END_IF;

