    bPrimaryActive AT %I* : BOOL;
    bHeartbeatRemote AT %I* : BOOL;
    bIsActiveNode : BOOL;

    // EtherCAT Inputs (Redundant Sensors for Drift Detection)
    fCargoTankLevel AT %I* : REAL;
    fCargoTankPressure1 AT %I* : REAL;
    fCargoTankPressure2 AT %I* : REAL;
    fVaporReturnPressure AT %I* : REAL;
    nPumpDriveStatusWord AT %I* : WORD;
    bEcatStateOk AT %I* : BOOL;

    // HIL Digital Twin & Self-Test
    bHILMode : BOOL; // True = use simulated inputs
    fSimCargoTankPressure : REAL; // Driven by twin model
    bSelfTestRunning : BOOL := TRUE;
    tSelfTestTimer : TON;
    bSelfTestPassed : BOOL;

    // EtherCAT Outputs
    fCryoPumpSpeedRef AT %Q* : REAL;
    bCryoPumpStart AT %Q* : BOOL;
    bBOGValveOpen AT %Q* : BOOL;
    bFlareValveOpen AT %Q* : BOOL;
    bReliquefactionStart AT %Q* : BOOL;
    fReliquefactionCapacity AT %Q* : REAL;
    bVaporReturnValveOpen AT %Q* : BOOL;

    // Internal State
    eState : (INIT_SELF_TEST, IDLE, PRE_COOLING, RAMP_UP, STEADY, SHUTDOWN, FAULT);
    tRampTimer : TON;
    fTargetPumpSpeed : REAL := 100.0;
    fRampRate : REAL := 1.0;

    // Setpoints
    fBOGSetpoint : REAL := 0.25;
    fReliquefactionSetpoint : REAL := 0.28;
    fFlareSetpoint : REAL := 0.30;
    fVaporReturnLimit : REAL := 1.5;

    // Fault Diagnostics & Sensor Drift
    bSystemFault : BOOL;
    eErrorCode : INT := 0;
    fEffectivePressure : REAL;
    fDriftThreshold : REAL := 0.05; // 50 mbar drift tolerance
    bSensorDriftDetected : BOOL;
END_VAR

// 1. Failover & Cybersecurity
bWriteAccessGranted := (sActiveRole = 'ADMIN' OR sActiveRole = 'SUPERVISOR');
bIsActiveNode := bPrimaryActive OR NOT bHeartbeatRemote;

IF bIsActiveNode THEN

    // 2. Sensor Drift Detection & HIL Integration
    IF NOT bHILMode THEN
        IF ABS(fCargoTankPressure1 - fCargoTankPressure2) > fDriftThreshold THEN
            bSensorDriftDetected := TRUE;
            eErrorCode := 4; // Sensor discrepancy
            fEffectivePressure := MAX(fCargoTankPressure1, fCargoTankPressure2); // Safe conservative choice
        ELSE
            bSensorDriftDetected := FALSE;
            fEffectivePressure := (fCargoTankPressure1 + fCargoTankPressure2) / 2.0;
        END_IF
    ELSE
        // In HIL mode, accept simulated data for Digital Twin Synchronization
        fEffectivePressure := fSimCargoTankPressure;
        bSensorDriftDetected := FALSE;
    END_IF

    fSCADACargoPressure := fEffectivePressure;
    eErrorCodeOut := eErrorCode;

    // 3. Fault Diagnostics
    bSystemFault := FALSE; 
    IF NOT bSensorDriftDetected THEN eErrorCode := 0; END_IF; // Reset if drift clears and no other fault
    IF NOT bEcatStateOk THEN bSystemFault := TRUE; eErrorCode := 1;
