    END_IF
    bFlareValveOpen := (fEffectivePressure > fFlareSetpoint);
    bVaporReturnValveOpen := (fVaporReturnPressure < fVaporReturnLimit);

    // 5. State Machine with Self-Test
    CASE eState OF
        INIT_SELF_TEST:
            bSelfTestRunning := TRUE;
            tSelfTestTimer(IN:=TRUE, PT:=T#5S);
            // Simulate valve stroking or IO pinging
            IF tSelfTestTimer.Q THEN
                IF NOT bSystemFault THEN
                    bSelfTestPassed := TRUE;
                    eState := IDLE;
                ELSE
                    eState := FAULT;
                END_IF
                bSelfTestRunning := FALSE;
            END_IF

        IDLE:
            fCryoPumpSpeedRef := 0.0; bCryoPumpStart := FALSE;
            IF bStartRampUpCmd AND bWriteAccessGranted AND NOT bSystemFault THEN eState := PRE_COOLING; tRampTimer(IN:=FALSE); END_IF

        PRE_COOLING:
            bCryoPumpStart := TRUE; fCryoPumpSpeedRef := 10.0;
            tRampTimer(IN:=TRUE, PT:=T#60S);
            IF tRampTimer.Q THEN eState := RAMP_UP; tRampTimer(IN:=FALSE); END_IF

        RAMP_UP:
            tRampTimer(IN:=TRUE, PT:=T#1S);
            IF tRampTimer.Q THEN
                fCryoPumpSpeedRef := MIN(fCryoPumpSpeedRef + fRampRate, fTargetPumpSpeed);
                tRampTimer(IN:=FALSE);
            END_IF
            IF fCryoPumpSpeedRef >= fTargetPumpSpeed THEN eState := STEADY; END_IF

        STEADY:
            fCryoPumpSpeedRef := fTargetPumpSpeed;
            IF NOT bStartRampUpCmd THEN eState := SHUTDOWN; END_IF

        SHUTDOWN:
            fCryoPumpSpeedRef := 0.0; bCryoPumpStart := FALSE; eState := IDLE;

        FAULT:
            fCryoPumpSpeedRef := 0.0; bCryoPumpStart := FALSE; 
            IF NOT bSystemFault AND NOT bStartRampUpCmd THEN eState := IDLE; END_IF
    END_CASE
ELSE
    // Passive node keeps safe outputs
    fCryoPumpSpeedRef := 0.0;
    bCryoPumpStart := FALSE;
    bBOGValveOpen := FALSE;
