    IF #System_Fault THEN
        #Fan_Speed := 0.0; #Cooling_Valve := 0.0; #Purge_Damper := FALSE; #PN_Control_Word := 16#0000; 
        RETURN;
    END_IF;

    #PN_Control_Word := 16#047F; 

    // SCADA Override Handling
    IF #SCADA_Override AND #Valid_Auth THEN
        #Fan_Speed := #SCADA_Fan_Spd; #Cooling_Valve := 50.0; #Purge_Damper := FALSE; #CHWST_Setpoint := 8.0;
        RETURN;
    END_IF;

    // Normal Control
