    END_IF;

    IF #CO2_Level > 1000.0 THEN
        #Purge_Damper := TRUE; #Fan_Speed := 100.0; #Cooling_Valve := 50.0; 
    ELSE
        #Purge_Damper := FALSE;
        IF #OccupancySensor THEN
            #PID_Output := (#Temp_Current - #Temp_Setpoint) * 5.0; 
            IF #PID_Output > 100.0 THEN #PID_Output := 100.0; END_IF;
            IF #PID_Output < 0.0 THEN #PID_Output := 0.0; END_IF;
            #Cooling_Valve := #PID_Output; #Fan_Speed := 60.0 + (#PID_Output * 0.4); 
        ELSE
            #Cooling_Valve := 0.0; #Fan_Speed := 20.0; 
        END_IF;
    END_IF;
END_FUNCTION_BLOCK
