Here is a complete Beckhoff ST program for an Industrial Centrifuge managing Vibration Monitoring and Variable Speed Deceleration. It uses a state machine to safely handle operations and reacts to high vibration levels by decelerating the centrifuge safely.

```iecst
PROGRAM MAIN
VAR
    bStartCmd : BOOL;
    bStopCmd : BOOL;
    bResetCmd : BOOL;
    fVibrationSensor : REAL; // mm/s
    fCurrentSpeed : REAL; // RPM
    fTargetSpeed : REAL := 3000.0;
    fSpeedCommand : REAL;

    fVibrationWarningLimit : REAL := 10.0;
    fVibrationFaultLimit : REAL := 20.0;

    fNormalDecelRate : REAL := 50.0; // RPM/s
    fVibrationDecelRate : REAL := 150.0; // RPM/s

    eState : (INIT, IDLE, ACCELERATING, RUNNING, NORMAL_DECEL, VIBRATION_DECEL, FAULT);
    bVibrationWarning : BOOL;
    bVibrationFault : BOOL;
END_VAR

// Vibration Monitoring
IF fVibrationSensor > fVibrationWarningLimit THEN
    bVibrationWarning := TRUE;
ELSE
    bVibrationWarning := FALSE;
END_IF

IF fVibrationSensor > fVibrationFaultLimit THEN
    bVibrationFault := TRUE;
END_IF

// State Machine
CASE eState OF
    INIT:
        fSpeedCommand := 0.0;
        bVibrationFault := FALSE;
        eState := IDLE;

    IDLE:
        fSpeedCommand := 0.0;
        IF bStartCmd AND NOT bVibrationFault THEN
            eState := ACCELERATING;
        END_IF

    ACCELERATING, RUNNING:
        fSpeedCommand := fTargetSpeed; 
        IF eState = ACCELERATING AND fCurrentSpeed >= (fTargetSpeed - 10.0) THEN
            eState := RUNNING;
        END_IF

        IF bVibrationFault THEN
            eState := VIBRATION_DECEL;
        ELSIF bStopCmd THEN
            eState := NORMAL_DECEL;
        END_IF

    NORMAL_DECEL:
        fSpeedCommand := fSpeedCommand - fNormalDecelRate * 0.01; 
        IF fSpeedCommand <= 0.0 THEN
            fSpeedCommand := 0.0;
        END_IF
        IF fCurrentSpeed <= 5.0 THEN
            eState := IDLE;
        END_IF
        IF bVibrationFault THEN
            eState := VIBRATION_DECEL;
        END_IF

    VIBRATION_DECEL:
        fSpeedCommand := fSpeedCommand - fVibrationDecelRate * 0.01;
        IF fSpeedCommand <= 0.0 THEN
            fSpeedCommand := 0.0;
        END_IF
        IF fCurrentSpeed <= 5.0 THEN
            eState := FAULT;
        END_IF

    FAULT:
        fSpeedCommand := 0.0;
        IF bResetCmd AND fVibrationSensor < fVibrationWarningLimit THEN
            bVibrationFault := FALSE;
            eState := IDLE;
        END_IF
END_CASE
```

