```iecst
PROGRAM MAIN
VAR
    bStartCmd : BOOL;
    bStopCmd : BOOL;
    bResetCmd : BOOL;
    fVibrationSensor : REAL; // mm/s
    fCurrentSpeed : REAL; // RPM
    fTargetSpeed : REAL := 3000.0;
    fSpeedCommand : REAL;

    // Dynamic Braking Sub-system
    fBrakeTorqueCommand : REAL;
    fMaxBrakeTorque : REAL := 100.0;

    fVibrationWarningLimit : REAL := 10.0;
    fVibrationErrorLimit : REAL := 20.0;
    fVibrationCriticalLimit : REAL := 40.0;

    // EtherCAT Diagnostics
    DriveWcState AT %I* : BOOL; // True = Data invalid
    DriveState AT %I* : UINT;   // 8 = OP State

    // Alarms
    bWarningActive : BOOL;
    bErrorActive : BOOL;
    bCriticalActive : BOOL;

    fNormalDecelRate : REAL := 50.0;
    fErrorDecelRate : REAL := 150.0;

    eState : (INIT, IDLE, ACCELERATING, RUNNING, NORMAL_DECEL, ERROR_DECEL, CRITICAL_STOP, FAULT);
END_VAR

// Diagnostics and Fault Categorization
bWarningActive := (fVibrationSensor > fVibrationWarningLimit) AND (fVibrationSensor <= fVibrationErrorLimit);
bErrorActive := (fVibrationSensor > fVibrationErrorLimit) AND (fVibrationSensor <= fVibrationCriticalLimit);
bCriticalActive := (fVibrationSensor > fVibrationCriticalLimit) OR DriveWcState OR (DriveState <> 8);

// Dynamic Braking Calculation
IF eState = ERROR_DECEL OR eState = CRITICAL_STOP THEN
    fBrakeTorqueCommand := LIMIT(0.0, ((fVibrationSensor - fVibrationWarningLimit) / (fVibrationCriticalLimit - fVibrationWarningLimit)) * fMaxBrakeTorque, fMaxBrakeTorque);
    IF eState = CRITICAL_STOP THEN
        fBrakeTorqueCommand := fMaxBrakeTorque; // Full brake on critical
    END_IF
ELSE
    fBrakeTorqueCommand := 0.0;
END_IF

// State Machine
CASE eState OF
    INIT:
        fSpeedCommand := 0.0;
        IF NOT bCriticalActive AND NOT bErrorActive THEN eState := IDLE; END_IF

    IDLE:
        fSpeedCommand := 0.0;
        IF bCriticalActive THEN eState := CRITICAL_STOP;
        ELSIF bErrorActive THEN eState := FAULT;
        ELSIF bStartCmd THEN eState := ACCELERATING;
        END_IF

    ACCELERATING, RUNNING:
        fSpeedCommand := fTargetSpeed; 
        IF eState = ACCELERATING AND fCurrentSpeed >= (fTargetSpeed - 10.0) THEN
            eState := RUNNING;
        END_IF

        IF bCriticalActive THEN eState := CRITICAL_STOP;
        ELSIF bErrorActive THEN eState := ERROR_DECEL;
        ELSIF bStopCmd THEN eState := NORMAL_DECEL;
        END_IF

    NORMAL_DECEL:
        fSpeedCommand := MAX(0.0, fSpeedCommand - fNormalDecelRate * 0.01); 
        IF fCurrentSpeed <= 5.0 THEN eState := IDLE; END_IF
        IF bCriticalActive THEN eState := CRITICAL_STOP;
        ELSIF bErrorActive THEN eState := ERROR_DECEL;
        END_IF

    ERROR_DECEL:
        fSpeedCommand := MAX(0.0, fSpeedCommand - fErrorDecelRate * 0.01);
        IF bCriticalActive THEN eState := CRITICAL_STOP; END_IF
        IF fCurrentSpeed <= 5.0 THEN eState := FAULT; END_IF

    CRITICAL_STOP:
        fSpeedCommand := 0.0; // Coast to stop with full dynamic brake
        IF fCurrentSpeed <= 5.0 THEN eState := FAULT; END_IF

    FAULT:
        fSpeedCommand := 0.0;
        IF bResetCmd AND NOT bErrorActive AND NOT bCriticalActive THEN
            eState := IDLE;
        END_IF
END_CASE
