Here is the advanced Beckhoff ST program that introduces sensor failover, OPC UA SCADA integration, and basic IEC 62443 role-based access control (RBAC).

```iecst
PROGRAM MAIN
VAR
    // SCADA OPC UA Tags (Published via Pragma)
    {attribute 'OPC.UA.DA' := '1'}
    bStartCmd : BOOL;
    {attribute 'OPC.UA.DA' := '1'}
    bStopCmd : BOOL;
    {attribute 'OPC.UA.DA' := '1'}
    bResetCmd : BOOL;
    {attribute 'OPC.UA.DA' := '1'}
    fCurrentSpeed : REAL; // RPM

    // RBAC Security (IEC 62443)
    {attribute 'OPC.UA.DA' := '1'}
    nCurrentRole : INT := 0; // 0=Guest, 1=Operator, 2=Maintenance, 3=Admin
    {attribute 'OPC.UA.DA' := '1'}
    fNewTargetSpeed : REAL;
    {attribute 'OPC.UA.DA' := '1'}
    bApplyParameters : BOOL;
    fTargetSpeed : REAL := 3000.0;

    // Redundant Vibration Sensors
    fVibrationSensor1 AT %I* : REAL;
    fVibrationSensor2 AT %I* : REAL;
    bSensor1Fail AT %I* : BOOL;
    bSensor2Fail AT %I* : BOOL;
    fActiveVibration : REAL;
    bSensorMismatchWarning : BOOL;

    // Braking & Motion
    fSpeedCommand : REAL;
    fBrakeTorqueCommand : REAL;
    fMaxBrakeTorque : REAL := 100.0;

    fVibrationWarningLimit : REAL := 10.0;
    fVibrationErrorLimit : REAL := 20.0;
    fVibrationCriticalLimit : REAL := 40.0;

    // EtherCAT Diagnostics
    DriveWcState AT %I* : BOOL;
    DriveState AT %I* : UINT;

    // Alarms
    bWarningActive : BOOL;
    bErrorActive : BOOL;
    bCriticalActive : BOOL;

    eState : (INIT, IDLE, ACCELERATING, RUNNING, NORMAL_DECEL, ERROR_DECEL, CRITICAL_STOP, FAULT);
END_VAR

// Parameter Change Access Control (IEC 62443 Concept)
IF bApplyParameters THEN
    IF nCurrentRole >= 2 THEN // Maintenance or Admin required
        fTargetSpeed := fNewTargetSpeed;
    END_IF
    bApplyParameters := FALSE;
END_IF

// Sensor Failover Mechanism
IF NOT bSensor1Fail AND NOT bSensor2Fail THEN
    fActiveVibration := MAX(fVibrationSensor1, fVibrationSensor2);
    bSensorMismatchWarning := ABS(fVibrationSensor1 - fVibrationSensor2) > 5.0;
ELSIF NOT bSensor1Fail THEN
    fActiveVibration := fVibrationSensor1;
    bSensorMismatchWarning := FALSE;
ELSIF NOT bSensor2Fail THEN
    fActiveVibration := fVibrationSensor2;
    bSensorMismatchWarning := FALSE;
ELSE
    bCriticalActive := TRUE; // Both sensors failed
    fActiveVibration := fVibrationCriticalLimit + 1.0;
END_IF

// Diagnostics and Fault Categorization
bWarningActive := (fActiveVibration > fVibrationWarningLimit) AND (fActiveVibration <= fVibrationErrorLimit) OR bSensorMismatchWarning;
bErrorActive := (fActiveVibration > fVibrationErrorLimit) AND (fActiveVibration <= fVibrationCriticalLimit);
IF (fActiveVibration > fVibrationCriticalLimit) OR DriveWcState OR (DriveState <> 8) OR (bSensor1Fail AND bSensor2Fail) THEN
    bCriticalActive := TRUE;
END_IF

// Dynamic Braking Calculation
IF eState = ERROR_DECEL OR eState = CRITICAL_STOP THEN
    fBrakeTorqueCommand := LIMIT(0.0, ((fActiveVibration - fVibrationWarningLimit) / (fVibrationCriticalLimit - fVibrationWarningLimit)) * fMaxBrakeTorque, fMaxBrakeTorque);
    IF eState = CRITICAL_STOP THEN fBrakeTorqueCommand := fMaxBrakeTorque; END_IF
ELSE
    fBrakeTorqueCommand := 0.0;
END_IF

// State Machine
CASE eState OF
    INIT:
        fSpeedCommand := 0.0;
        IF NOT bCriticalActive AND NOT bErrorActive THEN eState := IDLE; END_IF

    IDLE:
        fSpeedCommand := 0.0;
        IF bCriticalActive THEN eState := CRITICAL_STOP;
        ELSIF bErrorActive THEN eState := FAULT;
        ELSIF bStartCmd THEN eState := ACCELERATING;
        END_IF

    ACCELERATING, RUNNING:
        fSpeedCommand := fTargetSpeed; 
        IF eState = ACCELERATING AND fCurrentSpeed >= (fTargetSpeed - 10.0) THEN eState := RUNNING; END_IF
        IF bCriticalActive THEN eState := CRITICAL_STOP;
        ELSIF bErrorActive THEN eState := ERROR_DECEL;
        ELSIF bStopCmd THEN eState := NORMAL_DECEL; END_IF

    NORMAL_DECEL:
        fSpeedCommand := MAX(0.0, fSpeedCommand - 0.5); 
        IF fCurrentSpeed <= 5.0 THEN eState := IDLE; END_IF
        IF bCriticalActive THEN eState := CRITICAL_STOP; ELSIF bErrorActive THEN eState := ERROR_DECEL; END_IF

    ERROR_DECEL:
        fSpeedCommand := MAX(0.0, fSpeedCommand - 1.5);
        IF bCriticalActive THEN eState := CRITICAL_STOP; END_IF
        IF fCurrentSpeed <= 5.0 THEN eState := FAULT; END_IF

    CRITICAL_STOP:
        fSpeedCommand := 0.0; 
        IF fCurrentSpeed <= 5.0 THEN eState := FAULT; END_IF

    FAULT:
        fSpeedCommand := 0.0;
        IF bResetCmd AND NOT bErrorActive AND NOT bCriticalActive THEN
            bCriticalActive := FALSE; // Ensure reset clears latched flags if condition passed
            eState := IDLE;
        END_IF
END_CASE
