    // HIL Digital Twin Mode
    bHIL_Mode : BOOL := FALSE; // Set true for offline testing
    fHIL_SimVibration : REAL;
    fHIL_SimSpeed : REAL;

    // Sensors & Drift Detection
    fVibrationSensor1 AT %I* : REAL;
    fVibrationSensor2 AT %I* : REAL;
    bSensor1Fail AT %I* : BOOL;
    bSensor2Fail AT %I* : BOOL;
    fActiveVibration : REAL;

    fSensorDriftIntegral : REAL;
    bDriftFault : BOOL;
    fDriftThreshold : REAL := 1000.0; // Time-integrated drift limit

    // Braking & Alarms
    fSpeedCommand : REAL;
    fBrakeTorqueCommand : REAL;
    fMaxBrakeTorque : REAL := 100.0;
    bWarningActive, bErrorActive, bCriticalActive : BOOL;

    // Self-Test
    bSelfTestComplete : BOOL := FALSE;
    tSelfTestTimer : TON;

    eState : (INIT, SELF_TEST, IDLE, ACCELERATING, RUNNING, NORMAL_DECEL, ERROR_DECEL, CRITICAL_STOP, FAULT);
END_VAR

// Parameter Change Access Control (IEC 62443)
IF bApplyParameters AND nCurrentRole >= 2 THEN
    fTargetSpeed := fNewTargetSpeed;
    bApplyParameters := FALSE;
END_IF

// Hardware-In-the-Loop (HIL) Synchronization
