    fVibrationSensor1 := fHIL_SimVibration;
    fVibrationSensor2 := fHIL_SimVibration;
    fCurrentSpeed := fHIL_SimSpeed;
    // Simulate EtherCAT healthy in HIL
    bCriticalActive := FALSE; 
END_IF

// Sensor Drift Detection and Failover
IF NOT bHIL_Mode THEN
    IF NOT bSensor1Fail AND NOT bSensor2Fail THEN
        fActiveVibration := MAX(fVibrationSensor1, fVibrationSensor2);
        // Integrate difference over time to detect slow drift
        fSensorDriftIntegral := fSensorDriftIntegral + (ABS(fVibrationSensor1 - fVibrationSensor2) * 0.01);
        IF fSensorDriftIntegral > fDriftThreshold THEN bDriftFault := TRUE; END_IF
    ELSIF NOT bSensor1Fail THEN
        fActiveVibration := fVibrationSensor1;
    ELSIF NOT bSensor2Fail THEN
        fActiveVibration := fVibrationSensor2;
    ELSE
        bCriticalActive := TRUE;
    END_IF
END_IF

// Alarm Categorization
bWarningActive := (fActiveVibration > 10.0) AND (fActiveVibration <= 20.0);
bErrorActive := ((fActiveVibration > 20.0) AND (fActiveVibration <= 40.0)) OR bDriftFault;
IF fActiveVibration > 40.0 THEN bCriticalActive := TRUE; END_IF

// Dynamic Braking
IF eState = ERROR_DECEL OR eState = CRITICAL_STOP THEN
    fBrakeTorqueCommand := LIMIT(0.0, ((fActiveVibration - 10.0) / 30.0) * fMaxBrakeTorque, fMaxBrakeTorque);
    IF eState = CRITICAL_STOP THEN fBrakeTorqueCommand := fMaxBrakeTorque; END_IF
ELSE
    fBrakeTorqueCommand := 0.0;
END_IF

// Main State Machine
CASE eState OF
    INIT:
        fSpeedCommand := 0.0;
        bSelfTestComplete := FALSE;
        eState := SELF_TEST;

    SELF_TEST:
