```iecst
// Theme Park Ride - Safety PLC Redundancy and Zone Block System
// Base Implementation

PROGRAM Ride_Safety_Base
VAR
    // Inputs
    Zone1_Clear_Sensor_A : BOOL;
    Zone1_Clear_Sensor_B : BOOL;
    Zone2_Clear_Sensor_A : BOOL;
    Zone2_Clear_Sensor_B : BOOL;

    Train1_In_Zone1 : BOOL;
    Train2_In_Zone2 : BOOL;

    Primary_PLC_Heartbeat : BOOL;
    Secondary_PLC_Heartbeat : BOOL;

    E_Stop_Pressed : BOOL;

    // Outputs
    Zone1_Dispatch_Enable : BOOL;
    Zone2_Dispatch_Enable : BOOL;
    Ride_E_Stop_Active : BOOL;
    System_Fault : BOOL;

    // Internal
    Zone1_Clear : BOOL;
    Zone2_Clear : BOOL;
    Redundancy_Fault : BOOL;
END_VAR

// 1. Redundancy Check
IF NOT Primary_PLC_Heartbeat AND NOT Secondary_PLC_Heartbeat THEN
    Redundancy_Fault := TRUE;
ELSE
    Redundancy_Fault := FALSE;
END_IF;

// 2. Zone Block Logic (Redundant Sensors)
// Both sensors must agree that the zone is clear
Zone1_Clear := Zone1_Clear_Sensor_A AND Zone1_Clear_Sensor_B;
Zone2_Clear := Zone2_Clear_Sensor_A AND Zone2_Clear_Sensor_B;

// Check for sensor discrepancy (Fault condition)
IF (Zone1_Clear_Sensor_A <> Zone1_Clear_Sensor_B) OR (Zone2_Clear_Sensor_A <> Zone2_Clear_Sensor_B) THEN
    System_Fault := TRUE;
END_IF;

// 3. Dispatch Logic (Block System)
// Train can only dispatch if the next zone is clear and no faults
IF Zone2_Clear AND NOT System_Fault AND NOT E_Stop_Pressed AND NOT Redundancy_Fault THEN
    Zone1_Dispatch_Enable := TRUE;
ELSE
    Zone1_Dispatch_Enable := FALSE;
END_IF;

