        1: // Verify Brakes (Simulate apply)
           Brake_Force := 100.0;
           Self_Test_Step := 2;
        2: // Release Brakes
           Brake_Force := 0.0;
           Self_Test_Passed := TRUE;
           Self_Test_Active := FALSE;
    END_CASE;
    RETURN; // Do not execute ride logic during self-test
END_IF;

// 2. Sensor Drift Detection (Analog Redundancy)
IF ABS(Sensor_A_Val - Sensor_B_Val) > Drift_Tolerance THEN
    Drift_Fault := TRUE;
