FUNCTION_BLOCK FB_Cyclotron_Base
TITLE = 'Cyclotron Base Control'
VERSION : '1.0'

VAR_INPUT
    Req_BeamOn : BOOL;          // Request to turn on the beam
    Sens_Vacuum : REAL;         // Vacuum level in mbar
    Sens_MagnetTemp : REAL;     // Magnet temperature in degrees C
END_VAR

VAR_OUTPUT
    Cmd_BeamActive : BOOL;      // Beam output status
    Cmd_MagnetCurrent : REAL;   // Magnet current setpoint
    Sts_Interlock : BOOL;       // Interlock status (TRUE = fault)
END_VAR

VAR
    Stat_Current : REAL := 0.0;
END_VAR

CONST
    LIMIT_VACUUM : REAL := 1.0E-6;  // Maximum allowed vacuum
    LIMIT_TEMP : REAL := 45.0;      // Maximum allowed temperature
    NOM_CURRENT : REAL := 120.0;    // Nominal magnet current
END_CONST

BEGIN
    // 1. Vacuum and Temperature Interlock Evaluation
    IF (Sens_Vacuum > LIMIT_VACUUM) OR (Sens_MagnetTemp > LIMIT_TEMP) THEN
        Sts_Interlock := TRUE;
        Cmd_BeamActive := FALSE;
        Stat_Current := 0.0;
    ELSE
        Sts_Interlock := FALSE;
    END_IF;

    // 2. Beam and Magnet Control
    IF NOT Sts_Interlock AND Req_BeamOn THEN
        // Ramp up magnet current
        IF Stat_Current < NOM_CURRENT THEN
            Stat_Current := Stat_Current + 0.5;
        END_IF;

        // Activate beam when magnet reaches nominal current
        IF Stat_Current >= NOM_CURRENT THEN
            Cmd_BeamActive := TRUE;
        END_IF;
    ELSE
        // Ramp down or reset
        Cmd_BeamActive := FALSE;
        IF Stat_Current > 0.0 THEN
            Stat_Current := Stat_Current - 1.0;
        END_IF;
        IF Stat_Current < 0.0 THEN
            Stat_Current := 0.0;
        END_IF;
    END_IF;

    Cmd_MagnetCurrent := Stat_Current;
END_FUNCTION_BLOCK
