FUNCTION_BLOCK FB_Cyclotron_Reasoning
TITLE = 'Cyclotron with Security & Redundancy'
VERSION : '1.3'

VAR_INPUT
    PN_ControlWord : WORD;
    PN_RoleID : INT;            // IEC 62443 RBAC
    PN_Signature : DWORD;       // Security Signature

    Redundancy_Heartbeat : BOOL;
    Redundancy_Primary : BOOL;

    Sens_Vacuum : REAL;
    Sens_MagnetTemp : REAL;
END_VAR

VAR_OUTPUT
    PN_StatusWord : WORD;
    PN_SecurityAlert : BOOL;

    Cmd_BeamActive : BOOL;
    Cmd_MagnetCurrent : REAL;
    Redundancy_SyncData : DWORD;
END_VAR

VAR
    Req_BeamOn : BOOL;
    Stat_Current : REAL := 0.0;
    SecurityPassed : BOOL;
END_VAR

CONST
    ROLE_OPERATOR : INT := 2;
    ROLE_ADMIN : INT := 5;
END_CONST

BEGIN
    // Redundancy Failover Logic
    IF NOT Redundancy_Primary THEN
        // Standby mode: sync data from primary, output nothing to field
        Stat_Current := DWORD_TO_REAL(Redundancy_SyncData);
        Cmd_BeamActive := FALSE;
        Cmd_MagnetCurrent := 0.0;
        RETURN;
    END_IF;

    // IEC 62443 RBAC & Signature Verification
    // Simplified representation of secure SCADA command validation
    SecurityPassed := (PN_RoleID >= ROLE_OPERATOR) AND (PN_Signature = 16#A5A5_5A5A);
    IF NOT SecurityPassed THEN
        PN_SecurityAlert := TRUE;
        Req_BeamOn := FALSE;
    ELSE
        PN_SecurityAlert := FALSE;
        Req_BeamOn := (PN_ControlWord AND 16#0001) <> 0;
    END_IF;

    // Core Logic (Interlocks & Control)
    IF (Sens_Vacuum > 1.0E-6) OR (Sens_MagnetTemp > 45.0) THEN
        Cmd_BeamActive := FALSE;
        Stat_Current := 0.0;
        PN_StatusWord := 16#0002;
    ELSIF Req_BeamOn THEN
        IF Stat_Current < 120.0 THEN
            Stat_Current := Stat_Current + 0.5;
        ELSE
            Cmd_BeamActive := TRUE;
        END_IF;
        PN_StatusWord := 16#0001;
    ELSE
        Cmd_BeamActive := FALSE;
        Stat_Current := 0.0;
        PN_StatusWord := 16#0000;
    END_IF;

    Cmd_MagnetCurrent := Stat_Current;

    // Sync data to standby controller
    Redundancy_SyncData := REAL_TO_DWORD(Stat_Current);
END_FUNCTION_BLOCK
