FUNCTION_BLOCK FB_Cyclotron_Adversarial
TITLE = 'Cyclotron Advanced HIL & Drift'
VERSION : '2.0'

VAR_INPUT
    PN_ControlWord : WORD;
    HIL_ModeActive : BOOL;
    HIL_SimValues : ARRAY[0..1] OF REAL;

    Sens_Vacuum_A : REAL;
    Sens_Vacuum_B : REAL;
    Sens_MagnetTemp_A : REAL;
    Sens_MagnetTemp_B : REAL;
END_VAR

VAR_OUTPUT
    Cmd_BeamActive : BOOL;
    Cmd_MagnetCurrent : REAL;
    Sts_SensorDrift : BOOL;
    Sts_SelfTestDone : BOOL;
    PN_StatusWord : WORD;
END_VAR

VAR
    Req_BeamOn : BOOL;
    ActualVacuum : REAL;
    ActualTemp : REAL;
    State : INT := 0; // 0=Idle, 1=SelfTest, 2=Ready, 3=Run
    TestTimer : INT := 0;
END_VAR

CONST
    DRIFT_TOLERANCE_VAC : REAL := 0.5E-7;
    DRIFT_TOLERANCE_TMP : REAL := 2.0;
END_CONST

BEGIN
    // HIL Digital Twin Synchronization
    IF HIL_ModeActive THEN
        ActualVacuum := HIL_SimValues[0];
        ActualTemp := HIL_SimValues[1];
        Sts_SensorDrift := FALSE;
    ELSE
        // Sensor Drift Detection (Dual Redundant)
        IF ABS(Sens_Vacuum_A - Sens_Vacuum_B) > DRIFT_TOLERANCE_VAC OR 
           ABS(Sens_MagnetTemp_A - Sens_MagnetTemp_B) > DRIFT_TOLERANCE_TMP THEN
            Sts_SensorDrift := TRUE;
            State := 0; // Force Idle
        ELSE
            Sts_SensorDrift := FALSE;
            ActualVacuum := (Sens_Vacuum_A + Sens_Vacuum_B) / 2.0;
            ActualTemp := (Sens_MagnetTemp_A + Sens_MagnetTemp_B) / 2.0;
        END_IF;
    END_IF;

    Req_BeamOn := (PN_ControlWord AND 16#0001) <> 0;

    // Interlocks
    IF (ActualVacuum > 1.0E-6) OR (ActualTemp > 45.0) OR Sts_SensorDrift THEN
        Cmd_BeamActive := FALSE;
        Cmd_MagnetCurrent := 0.0;
        State := 0;
        PN_StatusWord := 16#0002;
        RETURN;
    END_IF;

    // State Machine including Self-Test
    CASE State OF
        0: // Idle
            Sts_SelfTestDone := FALSE;
            Cmd_BeamActive := FALSE;
            Cmd_MagnetCurrent := 0.0;
            IF Req_BeamOn THEN
                State := 1;
                TestTimer := 0;
            END_IF;

        1: // Pre-beam Self Test (Inject small test current, verify no anomalies)
            Cmd_MagnetCurrent := 5.0;
            TestTimer := TestTimer + 1;
            IF TestTimer > 100 THEN
                Sts_SelfTestDone := TRUE;
                State := 2;
            END_IF;

        2: // Ready / Ramping
            IF Cmd_MagnetCurrent < 120.0 THEN
                Cmd_MagnetCurrent := Cmd_MagnetCurrent + 0.5;
            ELSE
                State := 3;
            END_IF;
            IF NOT Req_BeamOn THEN State := 0; END_IF;

        3: // Run
            Cmd_BeamActive := TRUE;
            PN_StatusWord := 16#0005;
            IF NOT Req_BeamOn THEN State := 0; END_IF;
    END_CASE;
END_FUNCTION_BLOCK
