```iecst
PROGRAM MAIN
VAR
    // ATE States
    eState : (INIT, IDLE, ACQUIRE, STOP, FAULT) := INIT;

    // High-speed data acquisition variables
    aDataBuffer : ARRAY[1..1000] OF LREAL;
    nSampleIndex : INT := 1;
    bStartAcquisition : BOOL;
    bAcquisitionComplete : BOOL;

    // Stimulus Sync
    bStimulusTrigger AT %Q* : BOOL; // Output to external device
    bDataReady AT %I* : BOOL;       // Input from fast sensor
    fSensorValue AT %I* : LREAL;    // Analog input value

    // Timers
    fbTimer : TON;
END_VAR

CASE eState OF
    INIT:
        nSampleIndex := 1;
        bStimulusTrigger := FALSE;
        bAcquisitionComplete := FALSE;
        eState := IDLE;

    IDLE:
        IF bStartAcquisition THEN
            eState := ACQUIRE;
            bStartAcquisition := FALSE;
            // Send stimulus trigger to DUT
            bStimulusTrigger := TRUE;
            fbTimer(IN := FALSE);
        END_IF

    ACQUIRE:
        // High-Speed Data Acquisition
        // Ensure stimulus pulse is off after short duration
        fbTimer(IN := TRUE, PT := T#1MS);
        IF fbTimer.Q THEN
            bStimulusTrigger := FALSE;
        END_IF

        // Sync with data ready signal
        IF bDataReady THEN
            aDataBuffer[nSampleIndex] := fSensorValue;
            nSampleIndex := nSampleIndex + 1;

            IF nSampleIndex > 1000 THEN
                bAcquisitionComplete := TRUE;
                eState := STOP;
            END_IF
        END_IF

    STOP:
        // Processing or waiting for reset
        IF NOT bStartAcquisition THEN
            eState := INIT;
        END_IF

