FUNCTION_BLOCK "FB_Lyophilizer_M4"
VERSION : 0.1
   VAR_INPUT
      Start_Process : Bool;
      Stop_Process : Bool;
      Run_Self_Test : Bool;
      Target_Temp : Real;
      Target_Vacuum : Real;
      Sensor_Temp_Main : Real;
      Sensor_Temp_Redundant : Real;
      Sensor_Vacuum : Real;
      HIL_Data : "UDT_HIL_Sync";
   END_VAR

   VAR_OUTPUT
      Heater_Output : Real;
      Vacuum_Valve_Output : Real;
      State : Int; // 0:Idle, 1:SelfTest, 2:Run, 3:Fault
      Drift_Alarm : Bool;
      Twin_Deviation_Alarm : Bool;
   END_VAR

   VAR
      Kp_Temp : Real := 2.5;
      Kp_Vac : Real := 1.0;
      Validated_Temp : Real;
      Self_Test_Timer : Int;
   END_VAR

BEGIN
   // Sensor Drift Detection (Redundant vs Main)
   IF ABS("Sensor_Temp_Main" - "Sensor_Temp_Redundant") > 2.0 THEN
      "Drift_Alarm" := TRUE;
      "State" := 3; // Fault
   ELSE
      "Drift_Alarm" := FALSE;
      "Validated_Temp" := ("Sensor_Temp_Main" + "Sensor_Temp_Redundant") / 2.0;
   END_IF;

   // HIL Digital Twin Deviation
   IF ABS("Validated_Temp" - "HIL_Data".Twin_Temp_Est) > 5.0 THEN
      "Twin_Deviation_Alarm" := TRUE;
   ELSE
      "Twin_Deviation_Alarm" := FALSE;
   END_IF;

   // State Machine
   IF "Stop_Process" OR "State" = 3 THEN
      "State" := 0;
   ELSIF "Run_Self_Test" AND "State" = 0 THEN
      "State" := 1;
      "Self_Test_Timer" := 0;
   ELSIF "Start_Process" AND "State" = 0 AND NOT "Drift_Alarm" THEN
      "State" := 2;
   END_IF;

   CASE "State" OF
      0, 3: // Idle or Fault
         "Heater_Output" := 0.0;
         "Vacuum_Valve_Output" := 0.0;

      1: // Self-Test Routine
         "Self_Test_Timer" := "Self_Test_Timer" + 1;
         IF "Self_Test_Timer" < 100 THEN
            "Heater_Output" := 10.0; // Pulse heater
            "Vacuum_Valve_Output" := 0.0;
         ELSIF "Self_Test_Timer" < 200 THEN
            "Heater_Output" := 0.0;
            "Vacuum_Valve_Output" := 10.0; // Pulse vac valve
         ELSE
            "State" := 0; // Test Complete
         END_IF;

      2: // Run
         IF "Validated_Temp" < "Target_Temp" THEN
            "Heater_Output" := ("Target_Temp" - "Validated_Temp") * "Kp_Temp";
            IF "Heater_Output" > 100.0 THEN "Heater_Output" := 100.0; END_IF;
