END_VAR

VAR_OUTPUT
    BalanceCmds : ARRAY[1..100] OF BOOL;
    ThermalRunawayAlarm : BOOL;
    SystemFault : BOOL;
    ContactorOpen : BOOL;
    CoolingPumpCmd : BOOL;
    HeatingHeaterCmd : BOOL;
    ChillerCmd : BOOL;
END_VAR

VAR
    i : INT;
    MaxTemp : REAL;
    MinTemp : REAL;
    SumTemp : REAL;
    AvgTemp : REAL;
    TempLimitRunaway : REAL := 60.0;
    TempLimitCooling : REAL := 45.0;
    TempLimitChiller : REAL := 50.0;
    TempLimitHeating : REAL := 15.0;
    SoC_BalanceThreshold : REAL := 5.0;
END_VAR

BEGIN
    ThermalRunawayAlarm := FALSE;
    SystemFault := FALSE;
    ContactorOpen := FALSE;
    CoolingPumpCmd := FALSE;
    HeatingHeaterCmd := FALSE;
    ChillerCmd := FALSE;

    MaxTemp := -100.0;
    MinTemp := 1000.0;
    SumTemp := 0.0;

    FOR i := 1 TO NumCells DO
        IF CellTemps[i] > MaxTemp THEN MaxTemp := CellTemps[i]; END_IF;
        IF CellTemps[i] < MinTemp THEN MinTemp := CellTemps[i]; END_IF;
        SumTemp := SumTemp + CellTemps[i];

        IF CellTemps[i] >= TempLimitRunaway THEN
            ThermalRunawayAlarm := TRUE;
            SystemFault := TRUE;
            ContactorOpen := TRUE;
        END_IF;
    END_FOR;

    AvgTemp := SumTemp / NumCells;

    // Thermal Management
    IF NOT SystemFault THEN
        IF MaxTemp > TempLimitCooling THEN
            CoolingPumpCmd := TRUE;
            IF MaxTemp > TempLimitChiller THEN
                ChillerCmd := TRUE;
            END_IF;
        ELSIF MinTemp < TempLimitHeating THEN
            CoolingPumpCmd := TRUE; // Circulate fluid
            HeatingHeaterCmd := TRUE;
        END_IF;

        // Balancing
        FOR i := 1 TO NumCells DO
            BalanceCmds[i] := FALSE;
            IF ChargeCmd AND (CellSoC[i] - AvgSoC > SoC_BalanceThreshold) THEN
                BalanceCmds[i] := TRUE;
            END_IF;
        END_FOR;
    ELSE
        // On fault, maximize cooling if runaway is imminent
        CoolingPumpCmd := TRUE;
        ChillerCmd := TRUE;
        HeatingHeaterCmd := FALSE;
        FOR i := 1 TO NumCells DO
            BalanceCmds[i] := FALSE;
        END_FOR;
    END_IF;
END_FUNCTION_BLOCK
