```scl
FUNCTION_BLOCK "BESS_DigitalTwin_SelfTest"
VAR_INPUT
    NumCells : INT;
    CellVoltages : ARRAY[1..100] OF REAL;
    CellTemps : ARRAY[1..100] OF REAL;

    // Digital Twin estimates
    DT_CellVoltages : ARRAY[1..100] OF REAL;
    DT_CellTemps : ARRAY[1..100] OF REAL;

    EMS_ControlWord : WORD;
    StartSelfTest : BOOL;
END_VAR

VAR_OUTPUT
    BalanceCmds : ARRAY[1..100] OF BOOL;
    ContactorOpen : BOOL;
    SensorDriftAlarm : BOOL;
    SelfTestActive : BOOL;
    SelfTestPassed : BOOL;
    BESS_ErrorCode : INT;
END_VAR

VAR
    i : INT;
    DriftLimitV : REAL := 0.2; // 200mV
    DriftLimitT : REAL := 5.0; // 5 deg C
    TestStep : INT;
    SystemFault : BOOL;
END_VAR

BEGIN
    SensorDriftAlarm := FALSE;
    SystemFault := FALSE;

    // 1. Sensor Drift Detection against Digital Twin
    FOR i := 1 TO NumCells DO
        IF ABS(CellVoltages[i] - DT_CellVoltages[i]) > DriftLimitV THEN
            SensorDriftAlarm := TRUE;
            BESS_ErrorCode := 201; // Voltage drift
        END_IF;
        IF ABS(CellTemps[i] - DT_CellTemps[i]) > DriftLimitT THEN
            SensorDriftAlarm := TRUE;
            BESS_ErrorCode := 202; // Temp drift
        END_IF;
    END_FOR;

    IF SensorDriftAlarm THEN
        SystemFault := TRUE;
        ContactorOpen := TRUE; // Safe state due to unreliable sensors
    END_IF;

    // 2. Self-Test Routine (e.g. executed on startup)
    IF StartSelfTest AND NOT SystemFault THEN
        SelfTestActive := TRUE;
        SelfTestPassed := FALSE;

        CASE TestStep OF
            0: // Check Contactor Logic
                ContactorOpen := TRUE;
                TestStep := 1;
            1: // Check Balancing commands
                FOR i := 1 TO NumCells DO BalanceCmds[i] := TRUE; END_FOR;
                TestStep := 2;
            2: // End Test
                FOR i := 1 TO NumCells DO BalanceCmds[i] := FALSE; END_FOR;
                ContactorOpen := FALSE;
                SelfTestPassed := TRUE;
                SelfTestActive := FALSE;
                TestStep := 0; // Reset
        END_CASE;
    ELSE
        SelfTestActive := FALSE;
        IF NOT StartSelfTest THEN
            TestStep := 0; // Ensure reset
        END_IF;
    END_IF;

    // 3. Core Thermal Runaway Protection
    IF NOT SelfTestActive THEN
        FOR i := 1 TO NumCells DO
            IF CellTemps[i] >= 60.0 THEN
                SystemFault := TRUE;
                ContactorOpen := TRUE;
                BESS_ErrorCode := 101;
            END_IF;
        END_FOR;
    END_IF;

END_FUNCTION_BLOCK
