FUNCTION_BLOCK "Pasteurizer_CIP_Control"
VAR_INPUT
    Start_Prod : Bool;
    Start_CIP : Bool;
    Stop : Bool;
    Temp_Actual : Real;
    Temp_SP : Real;
END_VAR
VAR_OUTPUT
    Heater_Valve_CV : Real;
    Flow_Diversion_Valve : Bool;
    Acid_Pump : Bool;
    Caustic_Pump : Bool;
    Water_Valve : Bool;
    State : Int; // 0=Off, 1=Prod, 2=CIP_Rinse, 3=CIP_Acid, 4=CIP_Caustic
END_VAR
VAR
    CIP_Timer : TON_TIME;
    Phase_Time : Time;
END_VAR
BEGIN
    IF Stop THEN State := 0; END_IF;
    IF Start_Prod AND State = 0 THEN State := 1; END_IF;
    IF Start_CIP AND State = 0 THEN State := 2; Phase_Time := T#5M; END_IF;

    Acid_Pump := FALSE; Caustic_Pump := FALSE; Water_Valve := FALSE;
    Flow_Diversion_Valve := FALSE;

    CASE State OF
        1: // Production
            Heater_Valve_CV := (Temp_SP - Temp_Actual) * 2.0;
            IF Temp_Actual >= Temp_SP THEN Flow_Diversion_Valve := TRUE; END_IF;
        2: // CIP Rinse
            Water_Valve := TRUE; Flow_Diversion_Valve := TRUE;
            #CIP_Timer(IN:=TRUE, PT:=Phase_Time);
            IF #CIP_Timer.Q THEN State := 3; #CIP_Timer(IN:=FALSE); Phase_Time := T#10M; END_IF;
        3: // CIP Acid
            Acid_Pump := TRUE; Flow_Diversion_Valve := TRUE;
            #CIP_Timer(IN:=TRUE, PT:=Phase_Time);
            IF #CIP_Timer.Q THEN State := 4; #CIP_Timer(IN:=FALSE); Phase_Time := T#10M; END_IF;
        4: // CIP Caustic
            Caustic_Pump := TRUE; Flow_Diversion_Valve := TRUE;
            #CIP_Timer(IN:=TRUE, PT:=Phase_Time);
            IF #CIP_Timer.Q THEN State := 0; #CIP_Timer(IN:=FALSE); END_IF;
        ELSE
            Heater_Valve_CV := 0.0;
    END_CASE;
END_FUNCTION_BLOCK
