```scl
FUNCTION_BLOCK "GrainSiloControl"
VERSION : 0.1
   VAR_INPUT 
      DustLevel : Real; // Dust level in mg/m3
      AugerTorque : Real; // Auger motor torque in Nm
      DustThreshold : Real := 50.0;
      TorqueLimit : Real := 150.0;
      SystemEnable : Bool;
   END_VAR

   VAR_OUTPUT 
      MistValve : Bool;
      AugerFwd : Bool;
      AugerRev : Bool;
      AlarmJam : Bool;
   END_VAR

   VAR 
      JamTimer : TON;
      RevTimer : TON;
      AntiJamActive : Bool;
   END_VAR

BEGIN
    // Dust Suppression Control
    #MistValve := #SystemEnable AND (#DustLevel > #DustThreshold);

    // Auger Anti-Jam Logic
    #JamTimer(IN := #SystemEnable AND (#AugerTorque > #TorqueLimit) AND NOT #AntiJamActive,
              PT := T#2S);

    IF #JamTimer.Q THEN
        #AntiJamActive := TRUE;
    END_IF;

    #RevTimer(IN := #AntiJamActive,
              PT := T#3S);

    IF #RevTimer.Q THEN
        #AntiJamActive := FALSE;
        IF #AugerTorque > #TorqueLimit THEN
            #AlarmJam := TRUE;
        END_IF;
    END_IF;

    IF #SystemEnable AND NOT #AlarmJam THEN
        #AugerFwd := NOT #AntiJamActive;
        #AugerRev := #AntiJamActive;
    ELSE
        #AugerFwd := FALSE;
        #AugerRev := FALSE;
    END_IF;
END_FUNCTION_BLOCK
