    #SystemFault := (#DiagErrorWord <> 16#0000);

    // Actuator Control
    #AerationFan := #SystemEnable AND NOT #SystemFault AND (#MaxTemp > #TempHighLimit);
    #MistValve := #SystemEnable AND NOT #SystemFault AND (#DustLevel > #DustThreshold);

    // Auger Anti-Jam Logic
    #JamTimer(IN := #SystemEnable AND NOT #SystemFault AND (#AugerTorque > #TorqueLimit) AND NOT #AntiJamActive,
