Avg_Temp := (Temp_Furnace_Sensor1 + Temp_Furnace_Sensor2) / 2.0;

// HIL Digital Twin Sync & Verification
IF ABS(Avg_Temp - HIL_Expected_Temp) > 50.0 THEN
    HIL_Mismatch_Alarm := TRUE;
ELSE
    HIL_Mismatch_Alarm := FALSE;
END_IF;

// Self-Test and Isolation Routine
IF Start_Self_Test OR Sensor_Drift_Alarm OR HIL_Mismatch_Alarm THEN
    In_Self_Test := TRUE;
END_IF;

IF In_Self_Test THEN
    System_Isolated := TRUE;
    Grate_Speed := 0.0; // Safe isolation state
ELSE
    System_Isolated := FALSE;
    Grate_Speed := Avg_Temp / 10.0; // Normal operational control
END_IF;

