VERSION : 1.3
   VAR_INPUT
      xSmokeDetected : Bool;
      xDamperOpened : Bool;
      wProfinetStatusVFD : Word;
      xHeartbeat_PeerPLC : Bool;
      xIsPrimaryPLC : Bool;
