   END_VAR

   VAR
      tonPeerTimeout : TON_TIME;
      statActivePLC : Bool;
      statSecureAccess : Bool;
   END_VAR

BEGIN
    // Hot-Standby Failover Logic
    tonPeerTimeout(IN := NOT xHeartbeat_PeerPLC, PT := T#2s);
    IF xIsPrimaryPLC OR tonPeerTimeout.Q THEN
        statActivePLC := TRUE; // Take control
    ELSE
        statActivePLC := FALSE;
    END_IF;

    // IEC 62443 Secure Command Validation (Role-based access)
    // 16#A5A5_5A5A represents an authorized supervisor token
    IF SCADA.OperatorToken = 16#A5A5_5A5A THEN
        statSecureAccess := TRUE;
    ELSE
        statSecureAccess := FALSE;
    END_IF;

    IF statActivePLC THEN
        // System Logic
        IF SCADA.Cmd_AutoMode THEN
            IF xSmokeDetected AND xDamperOpened THEN
                xCmdStartFwd := TRUE; // Simplified for brevity
            ELSE
                xCmdStartFwd := FALSE;
            END_IF;
        ELSIF SCADA.Cmd_Override AND statSecureAccess THEN
            // Manual override allowed only with secure token
            xCmdStartFwd := TRUE; 
        ELSE
            xCmdStartFwd := FALSE;
        END_IF;

        // Update SCADA Status
        SCADA.Status_FansFwd := xCmdStartFwd;
    ELSE
        // Follow peer PLC, outputs off locally
        xCmdStartFwd := FALSE;
        xCmdStartRev := FALSE;
    END_IF;
END_FUNCTION_BLOCK
