PROGRAM Main
VAR
    bVehicleDetected AT %I* : BOOL;
    fWeight AT %I* : REAL;
    sRFID AT %I* : STRING(32);
    bBoomGateOpen AT %Q* : BOOL;
    wEcatWcState AT %I* : WORD;
    {attribute 'OPC.UA.DA' := '1'}
    bRemoteOverride : BOOL;
    {attribute 'OPC.UA.DA' := '1'}
    sScadaStatus : STRING;
    bAuthValid : BOOL;
    bRedundantPlcActive AT %I* : BOOL;
    bPrimary : BOOL := TRUE;
    eState : (STANDBY, INIT, WAITING, PROCESS, OVERRIDE, FAULT);
END_VAR

IF NOT bPrimary AND bRedundantPlcActive THEN
    eState := STANDBY;
END_IF

CASE eState OF
    STANDBY:
        sScadaStatus := 'Standby Mode';
        IF NOT bRedundantPlcActive THEN bPrimary := TRUE; eState := INIT; END_IF
    INIT:
        IF wEcatWcState = 0 THEN eState := WAITING; ELSE eState := FAULT; END_IF
    WAITING:
        sScadaStatus := 'Waiting';
        bBoomGateOpen := FALSE;
        IF bRemoteOverride AND bAuthValid THEN eState := OVERRIDE;
        ELSIF bVehicleDetected THEN eState := PROCESS; END_IF
    PROCESS:
        sScadaStatus := 'Processing';
        IF sRFID <> '' AND fWeight > 0.0 THEN bBoomGateOpen := TRUE; eState := WAITING; END_IF
    OVERRIDE:
        sScadaStatus := 'Override Active';
        bBoomGateOpen := TRUE;
        IF NOT bRemoteOverride THEN eState := WAITING; END_IF
    FAULT:
        sScadaStatus := 'Fault';
        bBoomGateOpen := FALSE;
END_CASE

PROGRAM Main
VAR
    bVehicleDetected AT %I* : BOOL;
    fWeight AT %I* : REAL;
    bBoomGateOpen AT %Q* : BOOL;
    fZeroCalib : REAL := 0.0;
    fDriftThresh : REAL := 5.0;
    bDriftDetected : BOOL;
    {attribute 'OPC.UA.DA' := '1'}
    fSimWeight : REAL;
    {attribute 'OPC.UA.DA' := '1'}
    bHilSync : BOOL;
    tSelfTest : TON;
    eState : (SELF_TEST, ZERO_CALIB, RUN, HIL_SIM, FAULT);
END_VAR

CASE eState OF
    SELF_TEST:
        tSelfTest(IN:=TRUE, PT:=T#3S);
        IF tSelfTest.Q THEN
            tSelfTest(IN:=FALSE);
            eState := ZERO_CALIB;
        END_IF
    ZERO_CALIB:
        fZeroCalib := fWeight;
        IF ABS(fZeroCalib) > fDriftThresh THEN
            bDriftDetected := TRUE;
            eState := FAULT;
        ELSE
            eState := RUN;
        END_IF
    RUN:
        IF bHilSync THEN eState := HIL_SIM; END_IF
        IF NOT bVehicleDetected AND ABS(fWeight - fZeroCalib) > fDriftThresh THEN
            bDriftDetected := TRUE;
            eState := FAULT;
        END_IF
        IF fWeight > 0.0 THEN bBoomGateOpen := TRUE; ELSE bBoomGateOpen := FALSE; END_IF
    HIL_SIM:
        IF NOT bHilSync THEN eState := RUN; END_IF
        IF fSimWeight > 0.0 THEN bBoomGateOpen := TRUE; ELSE bBoomGateOpen := FALSE; END_IF
    FAULT:
        bBoomGateOpen := FALSE;
END_CASE

