        IF NOT bSensorDriftAlarm AND (rPressureSensorA > 10.0) THEN
            bPreTestComplete := TRUE;
            State := 10;
        ELSE
            State := 999;
        END_IF

    10:
        IF bPreTestComplete THEN
            State := 20;
        END_IF

    20:
        bStartCmd := FALSE;
        State := 0;

    999:
        // Fault logic
END_CASE
END_PROGRAM
