END_VAR

IF (Auth_Token = 123456) AND (User_Role_ID = 2) THEN
    Valid_Auth := TRUE;
    Security_Lockout := FALSE;
ELSE
    Valid_Auth := FALSE;
    Security_Lockout := TRUE;
END_IF;

IF NOT Heartbeat_Partner AND NOT Is_Primary_PLC THEN
    Failover_Active := TRUE;
    Is_Primary_PLC := TRUE;
END_IF;

IF Is_Primary_PLC THEN
    System_Healthy := (Process_Temperature > -50.0) AND (Process_Pressure > 0.0);
    IF System_Healthy AND NOT Security_Lockout THEN
        CTL := 1.0 - 0.001 * (Process_Temperature - 15.0);
