PROGRAM CustodyTransfer_Adversarial
VAR
    Coriolis_Flow_Rate : REAL;
    Prover_Loop_Active : BOOL;
    Prover_Volume : REAL;
    Meter_Factor : REAL := 1.0;
    Process_Temperature : REAL;
    Process_Pressure : REAL;
    Net_Standard_Volume : LREAL;
    Is_Primary_PLC : BOOL := TRUE;
    Temp_History : ARRAY[0..99] OF REAL;
    Temp_History_Index : INT := 0;
    Temp_Moving_Avg : REAL;
    Temp_Sum : REAL;
    Drift_Alarm : BOOL;
    i : INT;
    HIL_Mode_Active : BOOL;
    Twin_Flow_Estimate : REAL;
    Twin_Deviation_Error : BOOL;
    Startup_Complete : BOOL := FALSE;
    Self_Test_Step : INT := 0;
    Self_Test_Passed : BOOL := FALSE;
END_VAR

IF NOT Startup_Complete THEN
    CASE Self_Test_Step OF
        0: Self_Test_Step := 1;
        1: IF Process_Temperature > -273.15 THEN Self_Test_Step := 2; END_IF;
        2: Self_Test_Passed := TRUE; Startup_Complete := TRUE;
    END_CASE;
    RETURN;
END_IF;

IF Is_Primary_PLC AND Self_Test_Passed THEN
    Temp_History[Temp_History_Index] := Process_Temperature;
    Temp_History_Index := (Temp_History_Index + 1) MOD 100;
    Temp_Sum := 0.0;
    FOR i := 0 TO 99 DO
        Temp_Sum := Temp_Sum + Temp_History[i];
    END_FOR;
    Temp_Moving_Avg := Temp_Sum / 100.0;
    IF ABS(Process_Temperature - Temp_Moving_Avg) > 5.0 THEN
        Drift_Alarm := TRUE;
    END_IF;
    IF HIL_Mode_Active THEN
        IF ABS(Coriolis_Flow_Rate - Twin_Flow_Estimate) > 2.0 THEN
            Twin_Deviation_Error := TRUE;
        END_IF;
    END_IF;
    IF NOT Drift_Alarm AND NOT Twin_Deviation_Error THEN
        Net_Standard_Volume := Net_Standard_Volume + (Coriolis_Flow_Rate * Meter_Factor);
    END_IF;
END_IF;
END_PROGRAM

