FUNCTION_BLOCK "AmineSweeteningUnit"
VAR_INPUT
    RichAmineFlow_PV : REAL;
    RichAmineFlow_SP : REAL;
    LeanAmineFlow_PV : REAL;
    LeanAmineFlow_SP : REAL;
    ReboilerTemp_PV : REAL;
    ReboilerTemp_SP : REAL;
    Kp_Flow : REAL := 1.5;
    Ki_Flow : REAL := 0.5;
    Kp_Temp : REAL := 2.0;
    Ki_Temp : REAL := 0.2;
    CycleTime : REAL := 0.1;
END_VAR
VAR_OUTPUT
    RichAmineValve : REAL;
    LeanAmineValve : REAL;
    ReboilerSteamValve : REAL;
END_VAR
VAR
    RichFlowErrSum : REAL := 0.0;
    LeanFlowErrSum : REAL := 0.0;
    TempErrSum : REAL := 0.0;
END_VAR
BEGIN
    VAR RichFlowErr := RichAmineFlow_SP - RichAmineFlow_PV;
    RichFlowErrSum := RichFlowErrSum + (RichFlowErr * CycleTime);
    RichAmineValve := (Kp_Flow * RichFlowErr) + (Ki_Flow * RichFlowErrSum);

    VAR LeanFlowErr := LeanAmineFlow_SP - LeanAmineFlow_PV;
    LeanFlowErrSum := LeanFlowErrSum + (LeanFlowErr * CycleTime);
    LeanAmineValve := (Kp_Flow * LeanFlowErr) + (Ki_Flow * LeanFlowErrSum);

    VAR TempErr := ReboilerTemp_SP - ReboilerTemp_PV;
    TempErrSum := TempErrSum + (TempErr * CycleTime);
    ReboilerSteamValve := (Kp_Temp * TempErr) + (Ki_Temp * TempErrSum);

    IF RichAmineValve > 100.0 THEN RichAmineValve := 100.0; ELSIF RichAmineValve < 0.0 THEN RichAmineValve := 0.0; END_IF;
    IF LeanAmineValve > 100.0 THEN LeanAmineValve := 100.0; ELSIF LeanAmineValve < 0.0 THEN LeanAmineValve := 0.0; END_IF;
    IF ReboilerSteamValve > 100.0 THEN ReboilerSteamValve := 100.0; ELSIF ReboilerSteamValve < 0.0 THEN ReboilerSteamValve := 0.0; END_IF;
END_FUNCTION_BLOCK
