FUNCTION_BLOCK "DP_Control"
VAR_INPUT
    Enable : BOOL;
    Setpoint_X : REAL;
    Setpoint_Y : REAL;
    Setpoint_Heading : REAL;
    Actual_X : REAL;
    Actual_Y : REAL;
    Actual_Heading : REAL;
