PROGRAM MooringWinch_Advanced
VAR
    AutoMode, EmergencyQuickRelease, BrakeReleaseCMD, ClutchEngaged : BOOL;
    TensionSetpoint, WinchSpeedCMD, MaxSpeed : REAL := 100.0;
    MRU_HeaveVelocity, AHC_Gain : REAL := 1.0;
    AHC_Enable : BOOL;
    Kp : REAL := 1.5; Ki : REAL := 0.5; Error, Integral : REAL;

    // Redundant Sensors & Drift Detection
    TensionSensor1, TensionSensor2 : REAL;
    Sensor1Valid, Sensor2Valid : BOOL := TRUE;
    ActiveTension : REAL;
    DriftTolerance : REAL := 15.0;
    SensorDriftAlarm : BOOL;

    // HIL Digital Twin & Self-Test
    HIL_ModeActive : BOOL;
    HIL_SimTension : REAL;
    SelfTestActive : BOOL;
    SelfTestStep : INT;
    SelfTestPass : BOOL;

    // Cyber & SCADA
    ActiveUserRole : INT;
    AuthValid : BOOL;
    Fault_System : BOOL;
END_VAR

// HIL / Real-World Selection
IF HIL_ModeActive THEN
    ActiveTension := HIL_SimTension;
ELSE
    // Sensor Drift Detection
    IF ABS(TensionSensor1 - TensionSensor2) > DriftTolerance THEN
        SensorDriftAlarm := TRUE; // Maintenance warning
    END_IF;

    IF Sensor1Valid AND Sensor2Valid THEN
        ActiveTension := (TensionSensor1 + TensionSensor2) / 2.0;
    ELSIF Sensor1Valid THEN
        ActiveTension := TensionSensor1;
    ELSIF Sensor2Valid THEN
        ActiveTension := TensionSensor2;
    ELSE
        Fault_System := TRUE;
    END_IF;
END_IF;

// Pre-Operation Self-Test Routine
IF SelfTestActive THEN
    CASE SelfTestStep OF
        0: // Init
            SelfTestStep := 1;
        1: // Verify comms and sensors
            IF NOT Fault_System THEN SelfTestStep := 2; END_IF;
        2: // Brake engage check
            BrakeReleaseCMD := FALSE;
            SelfTestStep := 3;
        3: // Pass Test
            SelfTestPass := TRUE;
            SelfTestActive := FALSE;
    END_CASE;
    RETURN;
END_IF;

AuthValid := (ActiveUserRole >= 1);

IF EmergencyQuickRelease THEN
    BrakeReleaseCMD := TRUE; ClutchEngaged := FALSE; WinchSpeedCMD := 0.0; Integral := 0.0;
ELSIF Fault_System THEN
    BrakeReleaseCMD := FALSE; WinchSpeedCMD := 0.0;
ELSIF AutoMode AND ClutchEngaged AND AuthValid AND SelfTestPass THEN
    Error := TensionSetpoint - ActiveTension;
    Integral := Integral + (Error * Ki);
    IF Integral > MaxSpeed THEN Integral := MaxSpeed; ELSIF Integral < -MaxSpeed THEN Integral := -MaxSpeed; END_IF;
    WinchSpeedCMD := (Error * Kp) + Integral;
    IF AHC_Enable THEN WinchSpeedCMD := WinchSpeedCMD + (MRU_HeaveVelocity * AHC_Gain); END_IF;
    IF WinchSpeedCMD > MaxSpeed THEN WinchSpeedCMD := MaxSpeed; ELSIF WinchSpeedCMD < -MaxSpeed THEN WinchSpeedCMD := -MaxSpeed; END_IF;
    BrakeReleaseCMD := TRUE;
ELSE
    WinchSpeedCMD := 0.0; BrakeReleaseCMD := FALSE;
END_IF;
END_PROGRAM
