PROGRAM PRG_Subsea_BOP_SCADA_Sec
VAR
    // I/O
    fAccumulatorPressure AT %I* : REAL;
    bAnnularRamClosed    AT %I* : BOOL;
    bShearRamClosed      AT %I* : BOOL;
    bAnnularRamCloseCmd  AT %Q* : BOOL;
    bShearRamCloseCmd    AT %Q* : BOOL;

    // SCADA & Security (IEC 62443)
    sScadaUserToken      : STRING := '';
    bRemoteDisconnectCmd : BOOL;
    bLocalDisconnectCmd  : BOOL;
    bAccessGranted       : BOOL;
    bSecurityAlarm       : BOOL;

    // Redundancy
    bIsActiveController  AT %I* : BOOL;
    bPeerControllerFail  AT %I* : BOOL;
    bTakeoverActive      : BOOL;

    // Core Logic
    bEmergencyDisconnect : BOOL;
    fMinAccPressure      : REAL := 200.0;
    bSystemReady         : BOOL;
    bDeadmanTriggered    : BOOL;

    // Timers
    fbTimerCommLoss      : TON;
    fbTimerHydLoss       : TON;
    bCommLoss            : BOOL;
    bHydraulicPowerLoss  : BOOL;
END_VAR

// Redundancy Management
IF NOT bIsActiveController AND bPeerControllerFail THEN
    bTakeoverActive := TRUE;
END_IF

IF NOT bIsActiveController AND NOT bTakeoverActive THEN
    RETURN; // Standby mode, do not execute control logic
END_IF

// Cybersecurity: Role-Based Access Validation for SCADA Commands
IF bRemoteDisconnectCmd THEN
    IF sScadaUserToken = 'AUTH_TOKEN_OIM_LEVEL4' THEN
        bAccessGranted := TRUE;
        bSecurityAlarm := FALSE;
    ELSE
        bAccessGranted := FALSE;
        bSecurityAlarm := TRUE;
    END_IF
END_IF

bEmergencyDisconnect := bLocalDisconnectCmd OR (bRemoteDisconnectCmd AND bAccessGranted);

// Pressure & Deadman System
bHydraulicPowerLoss := (fAccumulatorPressure < fMinAccPressure);
bSystemReady := NOT bHydraulicPowerLoss;

fbTimerCommLoss(IN := bCommLoss, PT := T#5S);
fbTimerHydLoss(IN := bHydraulicPowerLoss, PT := T#5S);

IF fbTimerCommLoss.Q AND fbTimerHydLoss.Q THEN
    bDeadmanTriggered := TRUE;
END_IF

// BOP Control Execution
IF (bEmergencyDisconnect AND bSystemReady) OR bDeadmanTriggered THEN
    bAnnularRamCloseCmd := TRUE;
    IF bAnnularRamClosed THEN
        bShearRamCloseCmd := TRUE;
    END_IF
END_IF
END_PROGRAM
