PROGRAM PRG_Subsea_BOP_Adversarial
VAR
    // Redundant Sensors
    fAccPressureSensorA  AT %I* : REAL;
    fAccPressureSensorB  AT %I* : REAL;
    fAccPressureFiltered : REAL;
    bSensorDriftAlarm    : BOOL;

    // Digital Twin Sync (HIL)
    fDigitalTwinPressure : REAL;
    fTwinDeviation       : REAL;
    bModelDeviationAlarm : BOOL;

    // Partial Stroke Test (PST)
    bStartPSTCmd         : BOOL;
    bPSTActive           : BOOL;
    bPSTPassed           : BOOL;
    fbTimerPST           : TON;
    bAnnularRamTestCmd   AT %Q* : BOOL;

    // Ram States & Commands
    bAnnularRamClosed    AT %I* : BOOL;
    bShearRamClosed      AT %I* : BOOL;
    bAnnularRamCloseCmd  AT %Q* : BOOL;
    bShearRamCloseCmd    AT %Q* : BOOL;

    // Security & SCADA
    sScadaUserToken      : STRING;
    bRemoteDisconnectCmd : BOOL;

    // Core Execution
    bEmergencyDisconnect : BOOL;
    bDeadmanTriggered    : BOOL;
    bCommLoss            : BOOL;
    bHydraulicPowerLoss  : BOOL;
    fbTimerCommLoss      : TON;
    fbTimerHydLoss       : TON;
END_VAR

// 1. Dual-Redundant Sensor Drift Detection
IF ABS(fAccPressureSensorA - fAccPressureSensorB) > 15.0 THEN
    bSensorDriftAlarm := TRUE;
    fAccPressureFiltered := MIN(fAccPressureSensorA, fAccPressureSensorB); // Conservative voting
ELSE
    bSensorDriftAlarm := FALSE;
    fAccPressureFiltered := (fAccPressureSensorA + fAccPressureSensorB) / 2.0;
END_IF

// 2. HIL Digital Twin Sync
fTwinDeviation := ABS(fAccPressureFiltered - fDigitalTwinPressure);
IF fTwinDeviation > 25.0 THEN
    bModelDeviationAlarm := TRUE; // Twin diverges from physical asset
END_IF

// 3. Periodic Partial Stroke Self-Test (PST)
// Moves the ram 10% to verify hydraulic integrity without closing the well
IF bStartPSTCmd AND NOT bEmergencyDisconnect AND NOT bPSTActive THEN
    bPSTActive := TRUE;
    bStartPSTCmd := FALSE;
    bPSTPassed := FALSE;
END_IF

fbTimerPST(IN := bPSTActive, PT := T#3S);
IF bPSTActive THEN
    bAnnularRamTestCmd := TRUE; // Pilot valve for 10% stroke
    IF fbTimerPST.Q THEN
        bAnnularRamTestCmd := FALSE;
        bPSTActive := FALSE;
        bPSTPassed := TRUE; // Assume position feedback verified in external FB
    END_IF
END_IF

// 4. IEC 62443 CyberSec
IF bRemoteDisconnectCmd AND (sScadaUserToken = 'AUTH_TOKEN_OIM_LEVEL4') THEN
    bEmergencyDisconnect := TRUE;
END_IF

// 5. Deadman Logic
bHydraulicPowerLoss := (fAccPressureFiltered < 200.0);
fbTimerCommLoss(IN := bCommLoss, PT := T#5S);
fbTimerHydLoss(IN := bHydraulicPowerLoss, PT := T#5S);

IF fbTimerCommLoss.Q AND fbTimerHydLoss.Q THEN
    bDeadmanTriggered := TRUE;
END_IF

// 6. Final BOP Actuation Sequence
IF bEmergencyDisconnect OR bDeadmanTriggered THEN
    bPSTActive := FALSE; // Abort test
    bAnnularRamTestCmd := FALSE;

    bAnnularRamCloseCmd := TRUE;
    IF bAnnularRamClosed THEN
        bShearRamCloseCmd := TRUE;
    END_IF
END_IF
END_PROGRAM
