FUNCTION_BLOCK "EAF_Control"
VERSION : 0.1
   VAR_INPUT 
      Arc_Voltage : Real;
      Arc_Current : Real;
      Setpoint_Voltage : Real;
      Setpoint_Current : Real;
   END_VAR
   VAR_OUTPUT 
      Electrode_Position : Real;
      Arc_Stable : Bool;
   END_VAR
   VAR 
      Kp : Real := 1.5;
      Ki : Real := 0.5;
      Error_V : Real;
      Integral_V : Real;
   END_VAR

BEGIN
   // Calculate error for impedance/voltage control
   #Error_V := #Setpoint_Voltage - #Arc_Voltage;

   // PI Control for Electrode Positioning
   #Integral_V := #Integral_V + (#Error_V * 0.1);
   #Electrode_Position := (#Kp * #Error_V) + (#Ki * #Integral_V);

   // Limit Position
   IF #Electrode_Position > 100.0 THEN #Electrode_Position := 100.0; END_IF;
   IF #Electrode_Position < 0.0 THEN #Electrode_Position := 0.0; END_IF;

   // Arc Stability Check
   IF ABS(#Arc_Current - #Setpoint_Current) < (#Setpoint_Current * 0.1) THEN
       #Arc_Stable := TRUE;
   ELSE
       #Arc_Stable := FALSE;
   END_IF;
END_FUNCTION_BLOCK
