    bStopCast : BOOL;

    // Self-Test
    tSelfTestTimer : TON;
    bSelfTestPassed : BOOL;

    // Sensor Drift Detection
    fTempSensor1 : REAL;
    fTempSensor2 : REAL;
    fTempDifference : REAL;
    bDriftFault : BOOL;

    // HIL Digital Twin Sync
    bHilModeActive : BOOL;
    fDigitalTwinPosition : REAL;
    fActualPosition : REAL;
    fSyncError : REAL;

    // SCADA, Cyber, Failover (Summarized)
    bScadaFault : BOOL;
    nUserRole : INT;
    bPrimaryPLC : BOOL := TRUE;
END_VAR

CASE eState OF
    INIT:
        IF nUserRole >= 2 THEN // Admin required for startup
            eState := SELF_TEST;
        END_IF

    SELF_TEST:
        tSelfTestTimer(IN:=TRUE, PT:=T#5S);
        // Simulate actuator movements & feedback check
        IF tSelfTestTimer.Q THEN
            bSelfTestPassed := TRUE;
            eState := RUN;
            tSelfTestTimer(IN:=FALSE);
        END_IF

    RUN:
        // Sensor Drift Detection
        fTempDifference := ABS(fTempSensor1 - fTempSensor2);
        IF fTempDifference > 5.0 THEN
            bDriftFault := TRUE;
            eState := FAULT;
        END_IF

        // HIL Synchronization
        IF bHilModeActive THEN
            fSyncError := ABS(fActualPosition - fDigitalTwinPosition);
            // Broadcast state to HIL environment
        END_IF

        // Core casting logic goes here
        IF bStopCast OR bScadaFault OR NOT bPrimaryPLC THEN
            eState := FAULT;
        END_IF

    FAULT:
        // Safe shutdown logic
        bSelfTestPassed := FALSE;
        tSelfTestTimer(IN:=FALSE);
END_CASE
