    Right_Drum_Height : REAL; // Height command for right cutting drum (m)

    // Internal
    Current_Shield_Index : DINT;
    Target_Shield : DINT;
    Drum_Offset : REAL := 0.1; // Safety offset from boundaries
END_VAR

IF Auto_Mode THEN
    Target_Shield := REAL_TO_DINT(Shearer_Position / 1.5);

    // 1. Coal Face Profiling & Speed Control
    IF Target_Shield >= 0 AND Target_Shield <= 100 THEN
        IF Coal_Face_Profile[Target_Shield] > 2.0 THEN
            Shearer_Speed := 0.1;
        ELSE
            Shearer_Speed := 0.25;
        END_IF;
    END_IF;

    // 2. Automatic Ranging Drum Height Control
    // Use radar data to adjust drum heights continuously
    // Left drum cuts the top/roof, Right drum cuts the bottom/floor
    IF Radar_Seam_Thickness > 0.5 THEN
        Left_Drum_Height := Radar_Seam_Thickness - Drum_Offset;
    ELSE
        Left_Drum_Height := 0.5; // Minimum height
    END_IF;

    IF Radar_Floor_Distance > 0.0 THEN
        Right_Drum_Height := Radar_Floor_Distance + Drum_Offset;
    ELSE
        Right_Drum_Height := 0.1; // Minimum floor clearance
    END_IF;
ELSE
    Shearer_Speed := 0.0;
    Left_Drum_Height := 0.0;
    Right_Drum_Height := 0.0;
END_IF;

// 3. Roof Support Advance
IF Auto_Mode AND Start_Advance THEN
    Current_Shield_Index := Target_Shield - 7;
    IF Current_Shield_Index >= 0 AND Current_Shield_Index <= 100 THEN
        Advance_Roof_Support[Current_Shield_Index] := TRUE;
    END_IF;
    IF Current_Shield_Index > 0 THEN
        Advance_Roof_Support[Current_Shield_Index - 1] := FALSE;
    END_IF;
