    Auto_Mode : BOOL;

    // Outputs
    Shearer_Speed : REAL;
    Left_Drum_Height : REAL;
    Advance_Roof_Support : ARRAY[0..100] OF BOOL;
    System_State : DINT; // 0=Init, 1=SelfTest, 2=Ready, 3=Run, 99=Fault
END_VAR

// 1. Adversarial Robustness: Sensor Drift Detection
// Check if position changes impossibly fast (e.g., > 2 meters per PLC cycle)
Position_Delta := ABS(Raw_Shearer_Position - Last_Position);
IF Position_Delta > 2.0 THEN
    Drift_Fault := TRUE;
ELSE
    Filtered_Shearer_Position := Raw_Shearer_Position; // Accept reading
END_IF;
Last_Position := Filtered_Shearer_Position;

// 2. Hardware-in-the-Loop (HIL) Digital Twin Synchronization
// Compare physical sensor with Digital Twin prediction
HIL_Sync_Error := ABS(Filtered_Shearer_Position - HIL_Simulated_Position);
IF HIL_Sync_Error > 5.0 THEN
    HIL_Mismatch_Fault := TRUE; // Physical system deviated significantly from Twin
ELSE
    HIL_Mismatch_Fault := FALSE;
END_IF;

// 3. Pre-Operation Self-Test Routine
IF System_State = 0 THEN
    System_State := 1; // Enter Self Test
END_IF;

IF System_State = 1 THEN
    // Validate interlocks
    IF Safety_Interlock_1 AND Safety_Interlock_2 AND NOT Drift_Fault THEN
        Self_Test_Passed := TRUE;
        System_State := 2; // Ready
    ELSE
        System_State := 99; // Fault
    END_IF;
END_IF;

// 4. Cybersecurity & SCADA
IF System_State = 2 AND SCADA_Start_Cmd AND (SCADA_Command_Token = 1234) THEN
    IF SCADA_Active_User_Role = 2 THEN // Admin required to start
        System_State := 3; // Run
        Auto_Mode := TRUE;
    END_IF;
END_IF;

// 5. Main Control Execution
IF PLC_Is_Primary AND System_State = 3 THEN
    // Stop immediately on adversarial faults
    IF Drift_Fault OR HIL_Mismatch_Fault THEN
        Auto_Mode := FALSE;
        System_State := 99;
        Shearer_Speed := 0.0;
    ELSE
        // Normal Operation
        Shearer_Speed := 0.25;
        Left_Drum_Height := Raw_Radar_Thickness - 0.1;

        // Example Roof Support Advance
        IF Filtered_Shearer_Position > 10.0 THEN
            Advance_Roof_Support[5] := TRUE;
        END_IF;
    END_IF;
ELSE
    Shearer_Speed := 0.0;
END_IF;
END_PROGRAM
