      mill_motor_cmd : Bool;  
      ore_feeder_cmd : Real;  
      scada_heartbeat_echo : Bool;
      fault_active : Bool;
      fault_code : Word; 
      state_out : Int;
   END_VAR

   VAR 
      state : Int; 
      lp_timer : TON_TIME;
      hp_timer : TON_TIME;
      heartbeat_timer : TON_TIME;
      scada_loss_timer : TON_TIME;
      pid_feeder : "PID_Compact"; 
      pid_ctrl_val : Real;
      active_lp_pump : Int := 1; // 1 or 2
      scada_hb_prev : Bool;
   END_VAR

   VAR_CONSTANT 
      MIN_LP_PRESSURE : Real := 2.5; 
      MIN_HP_PRESSURE : Real := 150.0;
      MIN_LIFT_MM : Real := 0.15;
      MIN_RUN_RPM : Real := 5.0;
      MAX_LUBE_TEMP : Real := 60.0;    
      MAX_MILL_WEIGHT : Real := 500.0; 

      F_NONE : Word := 16#0000;
      F_SECURITY_AUTH : Word := 16#00A1;
      F_SCADA_LOSS : Word := 16#00A2;
      F_LP_DUAL_FAIL : Word := 16#0010;
   END_VAR

BEGIN
    // SCADA Heartbeat Echo & Loss Detection
    scada_heartbeat_echo := scada_heartbeat;
    scada_loss_timer(IN := (scada_heartbeat = scada_hb_prev), PT := T#2s);
    scada_hb_prev := scada_heartbeat;

    IF scada_loss_timer.Q THEN 
        fault_code := F_SCADA_LOSS; 
        state := 99; 
    END_IF;

    // Security Check for Starts
    IF start_cmd AND NOT secure_token_valid THEN
        fault_code := F_SECURITY_AUTH;
    END_IF;

    // Redundant LP Pump Failover Logic
    IF state > 0 AND state <> 99 THEN
        IF active_lp_pump = 1 AND lp_lube_press_act_1 < MIN_LP_PRESSURE THEN
            active_lp_pump := 2; // Failover to Pump 2
        ELSIF active_lp_pump = 2 AND lp_lube_press_act_2 < MIN_LP_PRESSURE THEN
            active_lp_pump := 1; // Failover to Pump 1
        END_IF;

        // Complete failure
        IF lp_lube_press_act_1 < MIN_LP_PRESSURE AND lp_lube_press_act_2 < MIN_LP_PRESSURE THEN
            fault_code := F_LP_DUAL_FAIL; 
            state := 99;
        END_IF;
    END_IF;

    IF stop_cmd THEN state := 0; END_IF;
    IF reset_cmd AND state = 99 THEN fault_code := F_NONE; state := 0; END_IF;

    CASE state OF
        0: // Stop
            lp_pump_1_cmd := FALSE; lp_pump_2_cmd := FALSE;
            hp_lube_pump_cmd := FALSE; mill_motor_cmd := FALSE; ore_feeder_cmd := 0.0;
            fault_active := FALSE;
            IF start_cmd AND NOT stop_cmd AND secure_token_valid AND fault_code = F_NONE THEN state := 10; END_IF;

        10: // LP Lube
            lp_pump_1_cmd := (active_lp_pump = 1);
            lp_pump_2_cmd := (active_lp_pump = 2);
            hp_lube_pump_cmd := FALSE; mill_motor_cmd := FALSE; ore_feeder_cmd := 0.0;

            lp_timer(IN:=((active_lp_pump=1 AND lp_lube_press_act_1 >= MIN_LP_PRESSURE) OR (active_lp_pump=2 AND lp_lube_press_act_2 >= MIN_LP_PRESSURE)), PT:=T#5s);
            IF lp_timer.Q THEN state := 20; END_IF;

        20: // HP Lift
            lp_pump_1_cmd := (active_lp_pump = 1); lp_pump_2_cmd := (active_lp_pump = 2);
            hp_lube_pump_cmd := TRUE;

            hp_timer(IN:=(hp_lube_press_act >= MIN_HP_PRESSURE) AND (trunnion_lift_act >= MIN_LIFT_MM), PT:=T#3s);
            IF hp_timer.Q THEN state := 30; END_IF;

        30: // Main Motor
            lp_pump_1_cmd := (active_lp_pump = 1); lp_pump_2_cmd := (active_lp_pump = 2);
            hp_lube_pump_cmd := TRUE; mill_motor_cmd := TRUE;

            IF mill_speed_act >= MIN_RUN_RPM THEN state := 40; END_IF;

        40: // Normal Run
            lp_pump_1_cmd := (active_lp_pump = 1); lp_pump_2_cmd := (active_lp_pump = 2);
            hp_lube_pump_cmd := FALSE; 
            mill_motor_cmd := TRUE;

            pid_feeder(Setpoint := ore_feed_rate_sp, Feedback := mill_weight_act, Output => pid_ctrl_val);
            ore_feeder_cmd := pid_ctrl_val;

        99: // Fault
            lp_pump_1_cmd := TRUE; lp_pump_2_cmd := TRUE; // Run both to attempt saving bearings
            hp_lube_pump_cmd := TRUE; 
            mill_motor_cmd := FALSE; ore_feeder_cmd := 0.0;
            fault_active := TRUE;
            IF mill_speed_act < 0.1 THEN hp_lube_pump_cmd := FALSE; END_IF;
    END_CASE;

    state_out := state;
END_FUNCTION_BLOCK
