PROGRAM PRG_HeapLeach_Reasoning
VAR
    sUserRole AT %I* : STRING;
    bScadaStart AT %I* : BOOL;
    fPregnantPondLevel AT %I* : REAL;
    fPondPH AT %I* : REAL;
    bValveZone1 AT %Q* : BOOL;
    bValveZone2 AT %Q* : BOOL;
