    bPumpStandby AT %Q* : BOOL;
    bPriFault AT %I* : BOOL;
    bStdFault AT %I* : BOOL;
    bEcError AT %I* : BOOL;
    bAccessGranted : BOOL;
    bSystemActive : BOOL;
    fbTimerZone1 : TON;
    fbTimerZone2 : TON;
    nStep : INT := 0;
END_VAR

bAccessGranted := (sUserRole = 'Operator' OR sUserRole = 'Admin');

IF bAccessGranted AND bScadaStart AND NOT bEcError THEN
    bSystemActive := TRUE;
ELSE
    bSystemActive := FALSE;
END_IF

IF bSystemActive THEN
    IF fPregnantPondLevel > 80.0 THEN
        IF NOT bPriFault THEN
            bPumpPrimary := TRUE;
            bPumpStandby := FALSE;
        ELSIF NOT bStdFault THEN
            bPumpPrimary := FALSE;
            bPumpStandby := TRUE;
        END_IF
    ELSIF fPregnantPondLevel < 20.0 THEN
        bPumpPrimary := FALSE;
        bPumpStandby := FALSE;
    END_IF

    CASE nStep OF
        0: nStep := 10;
        10:
            bValveZone1 := TRUE;
            bValveZone2 := FALSE;
            fbTimerZone1(IN := TRUE, PT := T#2H);
            IF fbTimerZone1.Q THEN fbTimerZone1(IN:=FALSE); nStep:=20; END_IF
        20:
            bValveZone1 := FALSE;
            bValveZone2 := TRUE;
            fbTimerZone2(IN := TRUE, PT := T#2H);
            IF fbTimerZone2.Q THEN fbTimerZone2(IN:=FALSE); nStep:=10; END_IF
    END_CASE
ELSE
    bValveZone1 := FALSE;
    bValveZone2 := FALSE;
    bPumpPrimary := FALSE;
    bPumpStandby := FALSE;
    nStep := 0;
END_IF

PROGRAM PRG_HeapLeach_Adversarial
VAR
    bHilMode AT %I* : BOOL;
    fSimLevel AT %I* : REAL;
    fRealLevel1 AT %I* : REAL;
    fRealLevel2 AT %I* : REAL;
    sUserRole AT %I* : STRING;
    bStartCmd AT %I* : BOOL;
    bValveZ1 AT %Q* : BOOL;
    bValveZ2 AT %Q* : BOOL;
    bPumpPri AT %Q* : BOOL;
    fActiveLevel : REAL;
    bDriftAlarm : BOOL;
    nState : INT := 0;
    nTestStep : INT := 0;
    fbTestTimer : TON;
END_VAR

IF bHilMode THEN
    fActiveLevel := fSimLevel;
    bDriftAlarm := FALSE;
ELSE
    IF ABS(fRealLevel1 - fRealLevel2) > 5.0 THEN
        bDriftAlarm := TRUE;
        fActiveLevel := fRealLevel1;
    ELSE
        bDriftAlarm := FALSE;
        fActiveLevel := (fRealLevel1 + fRealLevel2) / 2.0;
    END_IF
END_IF

CASE nState OF
    0:
        bValveZ1 := FALSE; bValveZ2 := FALSE; bPumpPri := FALSE;
        IF bStartCmd AND (sUserRole = 'Admin') THEN nState := 1; END_IF
    1:
        CASE nTestStep OF
            0:
                bValveZ1 := TRUE;
                fbTestTimer(IN:=TRUE, PT:=T#2S);
                IF fbTestTimer.Q THEN fbTestTimer(IN:=FALSE); bValveZ1:=FALSE; nTestStep:=1; END_IF
            1:
                bValveZ2 := TRUE;
                fbTestTimer(IN:=TRUE, PT:=T#2S);
                IF fbTestTimer.Q THEN fbTestTimer(IN:=FALSE); bValveZ2:=FALSE; nState:=2; nTestStep:=0; END_IF
        END_CASE
    2:
        IF bDriftAlarm THEN nState := 99; END_IF
        IF fActiveLevel > 80.0 THEN bPumpPri := TRUE; ELSIF fActiveLevel < 20.0 THEN bPumpPri := FALSE; END_IF
    99:
        bValveZ1 := FALSE; bValveZ2 := FALSE; bPumpPri := FALSE;
END_CASE

