// Siemens SCL - Mutation 2 (Add Breadth)
FUNCTION_BLOCK "FB_ECoat_Breadth"
VERSION : 0.1
   VAR_INPUT
      PN_Conveyor_Encoder : DINT;
      PN_Rectifier_Status : WORD;
      Bath_Temp_Actual : REAL;
      Bath_Temp_SP : REAL;
      Target_Thickness : REAL;
   END_VAR
   VAR_OUTPUT
      PN_Rectifier_Cmd : WORD;
      PN_Rectifier_V : REAL;
      Heat_Exchanger_Valve : REAL;
      Fault_Code : INT;
   END_VAR
   VAR
      PID_Ctrl : "PID_Compact";
      Conveyor_Speed : REAL;
      Last_Encoder : DINT;
      Slip_Timer : TON;
      Overload_Timer : TON;
   END_VAR

BEGIN
   // Conveyor Slip Diagnostic
   Conveyor_Speed := DINT_TO_REAL(PN_Conveyor_Encoder - Last_Encoder) * 0.1;
   Last_Encoder := PN_Conveyor_Encoder;
   #Slip_Timer(IN := Conveyor_Speed < 5.0, PT := T#2S);

   // Rectifier Overload Diagnostic
   #Overload_Timer(IN := (PN_Rectifier_Status AND 16#0001) = 0, PT := T#1S);

   IF #Slip_Timer.Q THEN
      Fault_Code := 1;
   ELSIF #Overload_Timer.Q THEN
      Fault_Code := 2;
   ELSE
      Fault_Code := 0;
   END_IF;

   IF Fault_Code = 0 THEN
      PN_Rectifier_V := MIN(IN1 := Target_Thickness * (Conveyor_Speed / 100.0) * 1.5, IN2 := 400.0);
      PN_Rectifier_Cmd := 16#0001;
   ELSE
      PN_Rectifier_V := 0.0;
      PN_Rectifier_Cmd := 16#0000;
   END_IF;

   #PID_Ctrl(Setpoint := Bath_Temp_SP, Input := Bath_Temp_Actual, Output => Heat_Exchanger_Valve);
END_FUNCTION_BLOCK
