// Siemens SCL - Mutation 4 (Add Adversarial)
FUNCTION_BLOCK "FB_ECoat_Adversarial"
VERSION : 0.1
   VAR_INPUT
      Temp_Sensor_1 : REAL;
      Temp_Sensor_2 : REAL;
      HIL_Sync_Pulse : BOOL;
      Start_Self_Test : BOOL;
   END_VAR
   VAR_OUTPUT
      Drift_Alarm : BOOL;
      Self_Test_Active : BOOL;
      Self_Test_Passed : BOOL;
      HIL_State_Vector : ARRAY[0..3] OF REAL;
   END_VAR
   VAR
      Test_State : INT := 0;
      Test_Timer : TON;
      Simulated_Fault : BOOL;
   END_VAR

BEGIN
   // Sensor Drift Detection
   IF ABS(Temp_Sensor_1 - Temp_Sensor_2) > 2.0 THEN
      Drift_Alarm := TRUE;
   ELSE
      Drift_Alarm := FALSE;
   END_IF;

   // HIL Sync
   IF HIL_Sync_Pulse THEN
      HIL_State_Vector[0] := Temp_Sensor_1;
      HIL_State_Vector[1] := Temp_Sensor_2;
      HIL_State_Vector[2] := INT_TO_REAL(Test_State);
   END_IF;

   // Self-Test Routine
   IF Start_Self_Test AND Test_State = 0 THEN
      Test_State := 1;
      Self_Test_Active := TRUE;
      Self_Test_Passed := FALSE;
   END_IF;

   CASE Test_State OF
      1: // Simulate Fault
         Simulated_Fault := TRUE;
         #Test_Timer(IN := TRUE, PT := T#2S);
         IF #Test_Timer.Q THEN
            Test_State := 2;
            #Test_Timer(IN := FALSE, PT := T#2S);
         END_IF;
      2: // Verify Fault
         Simulated_Fault := FALSE;
         Self_Test_Passed := TRUE;
         Self_Test_Active := FALSE;
         Test_State := 0;
   END_CASE;
END_FUNCTION_BLOCK
