    bScadaCommandAck AT %Q* : BOOL;

    // Sensor Drift & HIL Digital Twin
    rHistoricalBaseLoad : REAL := 5.0;
    bSensorDriftDetected : BOOL;
    rTwinPredictedLoad : REAL;
    bSyncTwin : BOOL;

    // Self-Test Routine
    eState : (INIT, SELF_TEST, READY, RUNNING, FAULT);
    tTestTimer : TON;
END_VAR

CASE eState OF
    INIT:
        iErrorCode := 0;
        bSystemFault := FALSE;
        eState := SELF_TEST;

    SELF_TEST:
        tTestTimer(IN:=TRUE, PT:=T#2S);
        // Test sensors and twin sync
        IF rSpindleLoad1 < 0.0 OR rSpindleLoad2 < 0.0 THEN
            iErrorCode := 2001; // Self-test failed
            eState := FAULT;
        ELSIF tTestTimer.Q THEN
            tTestTimer(IN:=FALSE);
            eState := READY;
        END_IF

    READY:
        // Cybersecurity: Role-based access control
        IF bScadaCommandEnable AND iUserLevel >= 1 THEN
            bScadaCommandAck := TRUE;
            eState := RUNNING;
        END_IF

    RUNNING:
        bSpindleEnable := TRUE;

        // Sensor Drift Detection
        IF ABS(rSpindleLoad1 - rSpindleLoad2) > 5.0 THEN
            bSensorDriftDetected := TRUE;
        END_IF

        // Failover Logic
        IF rSpindleLoad1 > -10.0 AND NOT bSensorDriftDetected THEN
            rActiveSpindleLoad := rSpindleLoad1;
        ELSE
            rActiveSpindleLoad := rSpindleLoad2;
        END_IF

        // Digital Twin Synchronization
        IF bSyncTwin THEN
            // Validate actual vs digital twin prediction
            IF ABS(rActiveSpindleLoad - rTwinPredictedLoad) > 10.0 THEN
                iErrorCode := 1004; // Twin mismatch anomaly
                eState := FAULT;
            END_IF
        END_IF

        // EtherCAT Monitoring
        IF bEcatStateError OR wEcatWcState <> 0 THEN
            iErrorCode := 1001;
            eState := FAULT;
        END_IF

        // Spindle Load Monitoring
        IF rActiveSpindleLoad > rMaxLoadLimit THEN
            iErrorCode := 1002;
            eState := FAULT;
        END_IF

        // Tool Wear Compensation
        IF bWearCompensate AND rToolLife > 0 THEN
            rWearOffset := rWearOffset + 0.001 * rCutDepth; 
            rToolLife := rToolLife - (0.1 + (rToolTemperature / 1000.0));
        ELSIF rToolLife <= 0 THEN
            iErrorCode := 1003;
            eState := FAULT;
        END_IF

        // Dynamic Coolant Pressure Regulation
        rCoolantPressure := (rToolTemperature * 0.5) + (rCutDepth * 10.0);
        IF rCoolantPressure > 100.0 THEN
            rCoolantPressure := 100.0;
        END_IF

        // SCADA Command
        IF NOT bScadaCommandEnable THEN
            eState := READY;
            bSpindleEnable := FALSE;
            rCoolantPressure := 0.0;
            bScadaCommandAck := FALSE;
        END_IF

    FAULT:
        bSystemFault := TRUE;
        bSpindleEnable := FALSE;
        rCoolantPressure := 0.0;
        bScadaCommandAck := FALSE;
END_CASE
