```iecst
TYPE E_MachineState : (
	INIT,
	SELF_TEST,
	READY,
	RUNNING,
	FAULT
);
END_TYPE

TYPE ST_SCADA_Data :
STRUCT
	PressState : E_MachineState;
	CurrentTonnage : REAL;
	CurrentAngle : LREAL;
	ActiveAlarms : ARRAY[1..10] OF STRING;
END_STRUCT
END_TYPE

PROGRAM MAIN
VAR
	eState : E_MachineState := INIT;

	// I/O & Core
	bDieSensor1 AT %I* : BOOL;
	bDieSensor2 AT %I* : BOOL;
	fTonnageMonitor AT %I* : REAL;
	fMaxTonnageLimit : REAL := 500.0;
	bPressFault : BOOL;
	bStrokeEnable AT %Q* : BOOL;
	fPressAngle AT %I* : LREAL;
	bEjectorValve AT %Q* : BOOL;

	// HIL Digital Twin
	bHilModeActive : BOOL;
	stHilInputs : STRUCT bDie1:BOOL; bDie2:BOOL; fTonnage:REAL; fAngle:LREAL; END_STRUCT;
	stHilOutputs : STRUCT bStroke:BOOL; bEjector:BOOL; END_STRUCT;

	// Sensor Drift (Moving Average)
	aTonnageHistory : ARRAY[1..100] OF REAL;
	nHistIdx : INT := 1;
	fTonnageAverage : REAL;
	fDriftTolerance : REAL := 15.0;
	bDriftDetected : BOOL;

	// Self-Test
	nTestStep : INT;
	timerTest : TON;

	// Diagnostics & SCADA
	aAlarms : ARRAY[1..10] OF STRING;
	nUserRole : INT;
	bStartRequested : BOOL;
	stScadaData {attribute 'OPC.UA.DA' := '1'} : ST_SCADA_Data;
END_VAR

// HIL Synchronization
IF bHilModeActive THEN
	// Override physical inputs with Digital Twin inputs
	bDieSensor1 := stHilInputs.bDie1;
	bDieSensor2 := stHilInputs.bDie2;
	fTonnageMonitor := stHilInputs.fTonnage;
	fPressAngle := stHilInputs.fAngle;
END_IF

// State Machine
CASE eState OF
	INIT:
		IF nUserRole >= 2 THEN // Maintenance or higher for init
			eState := SELF_TEST;
			nTestStep := 1;
		END_IF

	SELF_TEST:
		// Simulate inputs to verify interlocks
		CASE nTestStep OF
			1: // Check Die Sensors
				bStrokeEnable := TRUE;
				bDieSensor1 := FALSE; // Force fault
				timerTest(IN:=TRUE, PT:=T#100MS);
				IF timerTest.Q THEN
					IF bPressFault THEN
						bPressFault := FALSE; // Reset
						timerTest(IN:=FALSE);
						nTestStep := 2;
					ELSE
						aAlarms[5] := 'Self-Test Failed: Die Sensor';
						eState := FAULT;
					END_IF
				END_IF
			2: // All good
				eState := READY;
		END_CASE

	READY:
		IF bStartRequested AND nUserRole >= 1 THEN
			eState := RUNNING;
		END_IF

	RUNNING:
		// Die Protection
		IF NOT bDieSensor1 OR NOT bDieSensor2 THEN
			bPressFault := TRUE;
			aAlarms[2] := 'Die Sensor Fault';
		END_IF

		// Tonnage & Drift Detection
		aTonnageHistory[nHistIdx] := fTonnageMonitor;
		nHistIdx := (nHistIdx MOD 100) + 1;
		fTonnageAverage := 0.0;
		FOR nTestStep := 1 TO 100 DO
			fTonnageAverage := fTonnageAverage + aTonnageHistory[nTestStep];
		END_FOR
		fTonnageAverage := fTonnageAverage / 100.0;

		IF ABS(fTonnageMonitor - fTonnageAverage) > fDriftTolerance THEN
			bDriftDetected := TRUE;
			aAlarms[6] := 'Sensor Drift Detected';
		END_IF

		IF fTonnageMonitor > fMaxTonnageLimit THEN
			bPressFault := TRUE;
		END_IF

		// Cam Ejection
		IF fPressAngle >= 270.0 AND fPressAngle <= 330.0 THEN
			bEjectorValve := TRUE;
		ELSE
			bEjectorValve := FALSE;
		END_IF

		bStrokeEnable := TRUE;

		IF bPressFault THEN
			eState := FAULT;
		END_IF

	FAULT:
		bStrokeEnable := FALSE;
		bEjectorValve := FALSE;
		IF NOT bPressFault THEN
			eState := READY;
		END_IF
END_CASE

// HIL Outputs
IF bHilModeActive THEN
	stHilOutputs.bStroke := bStrokeEnable;
	stHilOutputs.bEjector := bEjectorValve;
END_IF

// SCADA
stScadaData.PressState := eState;
stScadaData.CurrentTonnage := fTonnageMonitor;
stScadaData.CurrentAngle := fPressAngle;
stScadaData.ActiveAlarms := aAlarms;
