    fSilaneSetpoint : REAL := 50.0; (* sccm *)
    fSilaneActual : REAL;
    bRF_Enable : BOOL;
    fRF_ForwardPower : REAL := 300.0; (* Watts *)
    fRF_ActualPower : REAL;

    TMR_Process : TON;
    tProcessTime : TIME := T#5M;
END_VAR

// Gas Flow Control
IF bStartProcess THEN
    bProcessActive := TRUE;
END_IF

IF bProcessActive THEN
    // Command Silane Flow
    // Check if flow is stable before striking plasma
    IF ABS(fSilaneActual - fSilaneSetpoint) < 2.0 THEN
        bRF_Enable := TRUE;
    END_IF

    TMR_Process(IN := TRUE, PT := tProcessTime);
    IF TMR_Process.Q THEN
        bProcessActive := FALSE;
        bRF_Enable := FALSE;
        bStartProcess := FALSE;
        TMR_Process(IN := FALSE);
    END_IF
ELSE
    bRF_Enable := FALSE;
END_IF
END_PROGRAM

PROGRAM Mutation1_PECVD
VAR
    bStartProcess : BOOL;
    bProcessActive : BOOL;
    eState : (IDLE, PUMP_DOWN, GAS_STABILIZE, PLASMA_ON, PURGE) := IDLE;

    fSilaneSetpoint : REAL := 50.0;
    fSilaneActual : REAL;

    bRF_Enable : BOOL;

    fPressureSetpoint : REAL := 1.5; (* Torr *)
    fPressureActual : REAL;
    fThrottleValveCmd : REAL;
    fbPID_Pressure : FB_BasicPID;

    TMR_Process : TON;
END_VAR

CASE eState OF
    IDLE:
        IF bStartProcess THEN eState := PUMP_DOWN; END_IF

    PUMP_DOWN:
        fThrottleValveCmd := 100.0;
        IF fPressureActual < 0.01 THEN eState := GAS_STABILIZE; END_IF

    GAS_STABILIZE:
        fbPID_Pressure(fSetpoint := fPressureSetpoint, fActual := fPressureActual, fOutput => fThrottleValveCmd);
        IF ABS(fSilaneActual - fSilaneSetpoint) < 1.0 AND ABS(fPressureActual - fPressureSetpoint) < 0.05 THEN
            eState := PLASMA_ON;
        END_IF

    PLASMA_ON:
        bRF_Enable := TRUE;
        fbPID_Pressure(fSetpoint := fPressureSetpoint, fActual := fPressureActual, fOutput => fThrottleValveCmd);
        TMR_Process(IN := TRUE, PT := T#5M);
        IF TMR_Process.Q THEN
            bRF_Enable := FALSE;
            eState := PURGE;
            TMR_Process(IN := FALSE);
        END_IF

    PURGE:
        fThrottleValveCmd := 100.0;
        IF fPressureActual < 0.01 THEN
            bStartProcess := FALSE;
            eState := IDLE;
        END_IF
END_CASE
END_PROGRAM

PROGRAM Mutation2_PECVD
VAR
    bEcatError AT %I* : BOOL;
    nEcatState AT %I* : UINT;

    fSilaneActual AT %I* : REAL;
    fPressureActual AT %I* : REAL;
    fRF_ActualPower AT %I* : REAL;
    fThrottleValveCmd AT %Q* : REAL;
    bRF_Enable AT %Q* : BOOL;

    bStartProcess : BOOL;
    eState : (IDLE, FAULT, PUMP_DOWN, GAS_STABILIZE, PLASMA_ON, PURGE) := IDLE;

    bGasFlowFault : BOOL;
    bRFFault : BOOL;
    fbPID_Pressure : FB_BasicPID;
    TMR_Process : TON;
END_VAR

IF bEcatError OR nEcatState <> 8 THEN
    eState := FAULT;
END_IF

bGasFlowFault := (eState = PLASMA_ON) AND (ABS(fSilaneActual - 50.0) > 5.0);
bRFFault := bRF_Enable AND (fRF_ActualPower < 280.0);
IF bGasFlowFault OR bRFFault THEN
    eState := FAULT;
END_IF

CASE eState OF
    IDLE:
        IF bStartProcess THEN eState := PUMP_DOWN; END_IF
    PUMP_DOWN:
        fThrottleValveCmd := 100.0;
        IF fPressureActual < 0.01 THEN eState := GAS_STABILIZE; END_IF
    GAS_STABILIZE:
        fbPID_Pressure(fSetpoint := 1.5, fActual := fPressureActual, fOutput => fThrottleValveCmd);
        IF ABS(fSilaneActual - 50.0) < 1.0 THEN eState := PLASMA_ON; END_IF
    PLASMA_ON:
        bRF_Enable := TRUE;
        fbPID_Pressure(fSetpoint := 1.5, fActual := fPressureActual, fOutput => fThrottleValveCmd);
        TMR_Process(IN := TRUE, PT := T#5M);
        IF TMR_Process.Q THEN
            bRF_Enable := FALSE;
            TMR_Process(IN := FALSE);
            eState := PURGE;
        END_IF
    PURGE:
        fThrottleValveCmd := 100.0;
        IF fPressureActual < 0.01 THEN bStartProcess := FALSE; eState := IDLE; END_IF
    FAULT:
        bRF_Enable := FALSE;
        fThrottleValveCmd := 100.0;
END_CASE
END_PROGRAM

PROGRAM Mutation3_PECVD
VAR
    nUserLevel : UINT;
    bSecurityUnlocked : BOOL;

    bPrimaryActive AT %I* : BOOL;
    bStartProcess_OPC : BOOL;
    nSystemStatus_OPC : UINT;

    fPressureActual AT %I* : REAL;
    fThrottleValveCmd AT %Q* : REAL;
    bRF_Enable AT %Q* : BOOL;
    eState : (STANDBY, ACTIVE, FAULT, FAILOVER) := STANDBY;
END_VAR

bSecurityUnlocked := (nUserLevel >= 2);

IF NOT bPrimaryActive THEN
    eState := FAILOVER;
END_IF

CASE eState OF
    STANDBY:
        nSystemStatus_OPC := 1;
        IF bStartProcess_OPC AND bSecurityUnlocked THEN
            eState := ACTIVE;
        END_IF

    ACTIVE:
        nSystemStatus_OPC := 2;
        bRF_Enable := TRUE;
        IF NOT bSecurityUnlocked THEN
            eState := FAULT;
        END_IF

    FAULT:
        nSystemStatus_OPC := 99;
        bRF_Enable := FALSE;

    FAILOVER:
        bRF_Enable := FALSE;
        nSystemStatus_OPC := 88;
END_CASE
END_PROGRAM

PROGRAM Mutation4_PECVD
VAR
    fSilaneActual AT %I* : REAL;
    fSilaneDigitalTwin : REAL;
    bDriftDetected : BOOL;

    eState : (INIT_SELF_TEST, STANDBY, HIL_SYNC, ACTIVE, FAULT) := INIT_SELF_TEST;

    bRF_Enable AT %Q* : BOOL;
    bStartProcess_OPC : BOOL;

    TMR_Test : TON;
END_VAR

IF ABS(fSilaneActual - fSilaneDigitalTwin) > 2.5 THEN
    bDriftDetected := TRUE;
    eState := FAULT;
END_IF

CASE eState OF
    INIT_SELF_TEST:
        TMR_Test(IN := TRUE, PT := T#10S);
        IF TMR_Test.Q THEN
            TMR_Test(IN := FALSE);
            eState := STANDBY;
        END_IF

    STANDBY:
        IF bStartProcess_OPC THEN
            eState := HIL_SYNC;
        END_IF

    HIL_SYNC:
        IF fSilaneDigitalTwin > 0 THEN 
            eState := ACTIVE;
        END_IF

    ACTIVE:
        bRF_Enable := TRUE;

    FAULT:
        bRF_Enable := FALSE;
END_CASE
END_PROGRAM

PROGRAM CMP_Base
VAR
    bStart, bStop, bSystemActive : BOOL;
    rTargetPressure, rActualPressure, rValvePositionCV : REAL;
    rTargetSlurry, rActualSlurry, rPumpSpeedCV : REAL;
    PID_Pressure, PID_Slurry : PID;
END_VAR

// Basic State Control
IF bStart AND NOT bStop THEN
    bSystemActive := TRUE;
ELSIF bStop THEN
    bSystemActive := FALSE;
END_IF;

// PID Control Execution
IF bSystemActive THEN
    PID_Pressure.Setpoint := rTargetPressure;
    PID_Pressure.ProcessVariable := rActualPressure;
    PID_Pressure();
    rValvePositionCV := PID_Pressure.Output;

    PID_Slurry.Setpoint := rTargetSlurry;
    PID_Slurry.ProcessVariable := rActualSlurry;
    PID_Slurry();
    rPumpSpeedCV := PID_Slurry.Output;
ELSE
    rValvePositionCV := 0.0;
    rPumpSpeedCV := 0.0;
END_IF;
END_PROGRAM

PROGRAM CMP_Mut1
VAR
    bStart, bStop, bVacuumSensor : BOOL;
    iState : INT;
    rTargetPressure, rActualPressure, rValvePositionCV : REAL;
    rTargetSlurry, rActualSlurry, rPumpSpeedCV : REAL;
    rTargetRPM, rActualRPM, rSpindleSpeedCV : REAL;
    bVacuumEnable, bSpindleEnable : BOOL;
    PID_Pressure, PID_Slurry, PID_Spindle : PID;
END_VAR

CASE iState OF
    0: // Idle
        IF bStart THEN
            bVacuumEnable := TRUE;
            iState := 1;
        END_IF;
    1: // Wait Vacuum
        IF bVacuumSensor THEN
            bSpindleEnable := TRUE;
            iState := 2;
        ELSIF bStop THEN
            bVacuumEnable := FALSE;
            iState := 0;
        END_IF;
    2: // Run Polish
        IF bStop OR NOT bVacuumSensor THEN
            iState := 0;
            bVacuumEnable := FALSE;
            bSpindleEnable := FALSE;
        END_IF;
END_CASE;

IF iState = 2 THEN
    PID_Pressure.Setpoint := rTargetPressure;
    PID_Pressure.ProcessVariable := rActualPressure;
    PID_Pressure();
    rValvePositionCV := PID_Pressure.Output;

    PID_Slurry.Setpoint := rTargetSlurry;
    PID_Slurry.ProcessVariable := rActualSlurry;
    PID_Slurry();
    rPumpSpeedCV := PID_Slurry.Output;

    PID_Spindle.Setpoint := rTargetRPM;
    PID_Spindle.ProcessVariable := rActualRPM;
    PID_Spindle();
    rSpindleSpeedCV := PID_Spindle.Output;
ELSE
    rValvePositionCV := 0.0;
    rPumpSpeedCV := 0.0;
    rSpindleSpeedCV := 0.0;
END_IF;
END_PROGRAM

PROGRAM CMP_Mut2
VAR
    bStart, bStop, bVacuumSensor, bEIP_Connected : BOOL;
    iState : INT;
    rTargetPressure, rActualPressure, rValvePositionCV : REAL;
    rTargetSlurry, rActualSlurry, rPumpSpeedCV : REAL;
    rTargetRPM, rActualRPM, rSpindleSpeedCV : REAL;
    bVacuumEnable, bSpindleEnable, bSystemFault : BOOL;
    PID_Pressure, PID_Slurry, PID_Spindle : PID;
    arrFaults : ARRAY[0..31] OF BOOL;
    i : INT;
END_VAR

// Ethernet/IP Connectivity Check
IF NOT bEIP_Connected THEN
    arrFaults[0] := TRUE; // Loss of EIP
END_IF;

// Fault Diagnostics Aggregation
bSystemFault := FALSE;
FOR i := 0 TO 31 DO
    IF arrFaults[i] THEN 
        bSystemFault := TRUE; 
    END_IF;
END_FOR;

CASE iState OF
    0: // Idle
        IF bStart AND NOT bSystemFault THEN
            bVacuumEnable := TRUE;
            iState := 1;
        END_IF;
    1: // Wait Vacuum
        IF bVacuumSensor AND NOT bSystemFault THEN
            bSpindleEnable := TRUE;
            iState := 2;
        ELSIF bStop OR bSystemFault THEN
            bVacuumEnable := FALSE;
            iState := 0;
        END_IF;
    2: // Run Polish
        IF bStop OR NOT bVacuumSensor OR bSystemFault THEN
            iState := 0;
            bVacuumEnable := FALSE;
            bSpindleEnable := FALSE;
        END_IF;
END_CASE;

IF iState = 2 THEN
    PID_Pressure.Setpoint := rTargetPressure;
    PID_Pressure.ProcessVariable := rActualPressure;
    PID_Pressure();
    rValvePositionCV := PID_Pressure.Output;

    PID_Slurry.Setpoint := rTargetSlurry;
    PID_Slurry.ProcessVariable := rActualSlurry;
    PID_Slurry();
    rPumpSpeedCV := PID_Slurry.Output;

    PID_Spindle.Setpoint := rTargetRPM;
    PID_Spindle.ProcessVariable := rActualRPM;
    PID_Spindle();
    rSpindleSpeedCV := PID_Spindle.Output;
ELSE
    rValvePositionCV := 0.0;
    rPumpSpeedCV := 0.0;
    rSpindleSpeedCV := 0.0;
END_IF;
END_PROGRAM

PROGRAM CMP_Mut3
VAR
    bStart, bStop, bVacuumSensor, bEIP_Connected : BOOL;
    iState, iSecurityLevel : INT;
    rTargetPressure, rActualPressure, rValvePositionCV : REAL;
    rTargetSlurry, rActualSlurry, rPumpSpeedCV : REAL;
    rTargetRPM, rActualRPM, rSpindleSpeedCV : REAL;
    bVacuumEnable, bSpindleEnable, bSystemFault, bFailoverActive : BOOL;
