FUNCTION_BLOCK "BakeryOvenControl"
VERSION : 0.1
   VAR_INPUT 
      Start : Bool;
      Stop : Bool;
      TargetSpeed : Real; // Conveyor speed target in m/s
      Zone1_TempTarget : Real; // Target temp in degC
      Zone2_TempTarget : Real;
      Zone3_TempTarget : Real;
      Zone1_TempActual : Real;
      Zone2_TempActual : Real;
      Zone3_TempActual : Real;
   END_VAR

   VAR_OUTPUT 
      ConveyorRun : Bool;
      ConveyorSpeedOut : Real;
      Zone1_Heater : Bool;
      Zone2_Heater : Bool;
      Zone3_Heater : Bool;
      Running : Bool;
   END_VAR

   VAR 
      StateRunning : Bool;
   END_VAR

BEGIN
    // Master Start/Stop Control
    IF #Start AND NOT #Stop THEN
        #StateRunning := TRUE;
    ELSIF #Stop THEN
        #StateRunning := FALSE;
    END_IF;

    #Running := #StateRunning;

    // Main Execution logic
    IF #StateRunning THEN
        // Conveyor control
        #ConveyorRun := TRUE;
        #ConveyorSpeedOut := #TargetSpeed;

        // Zone 1 On/Off Control (Hysteresis of +/- 2 degrees)
        IF #Zone1_TempActual < (#Zone1_TempTarget - 2.0) THEN
            #Zone1_Heater := TRUE;
        ELSIF #Zone1_TempActual > (#Zone1_TempTarget + 2.0) THEN
            #Zone1_Heater := FALSE;
        END_IF;

        // Zone 2 On/Off Control
        IF #Zone2_TempActual < (#Zone2_TempTarget - 2.0) THEN
            #Zone2_Heater := TRUE;
        ELSIF #Zone2_TempActual > (#Zone2_TempTarget + 2.0) THEN
            #Zone2_Heater := FALSE;
        END_IF;

        // Zone 3 On/Off Control
        IF #Zone3_TempActual < (#Zone3_TempTarget - 2.0) THEN
            #Zone3_Heater := TRUE;
        ELSIF #Zone3_TempActual > (#Zone3_TempTarget + 2.0) THEN
            #Zone3_Heater := FALSE;
        END_IF;
    ELSE
        // Standby State - Ensure all outputs are safe
        #ConveyorRun := FALSE;
        #ConveyorSpeedOut := 0.0;
        #Zone1_Heater := FALSE;
        #Zone2_Heater := FALSE;
        #Zone3_Heater := FALSE;
    END_IF;
END_FUNCTION_BLOCK
