PROGRAM MAIN
VAR
    // HIL & Simulation
    bHIL_Mode : BOOL;
    rSimTemp, rSimPressure : REAL;

    // Physical I/O
    rSensor1Temp AT %I* : REAL;
    rSensor2Temp AT %I* : REAL;
    rActualTemp : REAL;
    rCondPressure AT %I* : REAL;

    // Adversarial: Sensor Drift Detection
    rDriftTolerance : REAL := 0.5;
    bSensorDriftFault : BOOL;
    bSensor1Fail, bSensor2Fail : BOOL;

    // Maintenance Self-Test
    bMaintenanceMode : BOOL;
    bStartSelfTest : BOOL;
    iSelfTestState : INT := 0;
    tTestTimer : TON;

    // Outputs
    rCompressorSpeedRef : REAL;
    bCondenserFan1, bCondenserFan2 : BOOL;

    // General
    bEnable : BOOL;
    rSetpoint : REAL := 7.0;
    fbCompPID : FB_BasicPID;
END_VAR

// 1. HIL Abstraction Layer
IF bHIL_Mode THEN
    rActualTemp := rSimTemp;
    rCondPressure := rSimPressure;
    bSensorDriftFault := FALSE;
ELSE
    // 2. Sensor Drift Detection & Voting
    IF ABS(rSensor1Temp - rSensor2Temp) > rDriftTolerance THEN
        bSensorDriftFault := TRUE;
        // Fallback to average or safe value
        rActualTemp := (rSensor1Temp + rSensor2Temp) / 2.0;
    ELSE
        bSensorDriftFault := FALSE;
        rActualTemp := rSensor1Temp; // Default to primary
    END_IF
END_IF

// 3. Maintenance Self-Test Routine
tTestTimer(IN := iSelfTestState > 0, PT := T#10S);

IF bMaintenanceMode AND bStartSelfTest THEN
    IF iSelfTestState = 0 THEN iSelfTestState := 1; END_IF

    CASE iSelfTestState OF
        1: // Test Fan 1
            bCondenserFan1 := TRUE; bCondenserFan2 := FALSE; rCompressorSpeedRef := 0.0;
            IF tTestTimer.Q THEN iSelfTestState := 2; tTestTimer(IN:=FALSE); END_IF
        2: // Test Fan 2
            bCondenserFan1 := TRUE; bCondenserFan2 := TRUE; rCompressorSpeedRef := 0.0;
            IF tTestTimer.Q THEN iSelfTestState := 3; tTestTimer(IN:=FALSE); END_IF
        3: // Test Compressor VFD at min speed (safely bypassed safeties in maint mode)
            bCondenserFan1 := TRUE; bCondenserFan2 := TRUE; rCompressorSpeedRef := 20.0;
            IF tTestTimer.Q THEN iSelfTestState := 4; tTestTimer(IN:=FALSE); END_IF
        4: // Test Complete
            bCondenserFan1 := FALSE; bCondenserFan2 := FALSE; rCompressorSpeedRef := 0.0;
            bStartSelfTest := FALSE;
            iSelfTestState := 0;
    END_CASE
    // Bypass normal control
    RETURN;
END_IF

// 4. Normal Process Control
IF bEnable AND NOT bSensorDriftFault THEN
    fbCompPID(fSetpointValue:=rSetpoint, fActualValue:=rActualTemp, bReset:=FALSE, fKp:=2.5, fTn:=10.0, fMaxCtrlOutput:=100.0, fMinCtrlOutput:=0.0);
    rCompressorSpeedRef := fbCompPID.fCtrlOutput;

    IF rCondPressure > 12.0 THEN bCondenserFan1 := TRUE; ELSIF rCondPressure < 10.0 THEN bCondenserFan1 := FALSE; END_IF
    IF rCondPressure > 15.0 AND bCondenserFan1 THEN bCondenserFan2 := TRUE; ELSIF rCondPressure < 13.0 THEN bCondenserFan2 := FALSE; END_IF
ELSE
    rCompressorSpeedRef := 0.0;
    bCondenserFan1 := FALSE; bCondenserFan2 := FALSE;
    fbCompPID(bReset:=TRUE);
END_IF
