```iecst
PROGRAM GlassMelting_Depth
VAR
    AI_FuelFlow : REAL;
    AI_AirFlow : REAL;
    AI_GlassLevel : REAL;

    SP_AirFuelRatio : REAL := 10.5;
    SP_GlassLevel : REAL := 1200.0;

    PID_Ratio : PID;
    PID_Level : PID;

    AO_AirValveCmd : REAL;
    AO_FeederSpeedCmd : REAL;

    // Regenerator Reversal
    Timer_Firing : TON;
    Timer_Purge : TON;
    State_Reversal : INT := 0; // 0=Fire Left, 1=Purge L->R, 2=Fire Right, 3=Purge R->L
    DO_FireLeft : BOOL;
    DO_FireRight : BOOL;
    DO_PurgeValve : BOOL;
END_VAR

Timer_Firing(IN := (State_Reversal = 0) OR (State_Reversal = 2), PT := T#20m);
Timer_Purge(IN := (State_Reversal = 1) OR (State_Reversal = 3), PT := T#30s);

CASE State_Reversal OF
    0: // Fire Left
        DO_FireLeft := TRUE; DO_FireRight := FALSE; DO_PurgeValve := FALSE;
        IF Timer_Firing.Q THEN State_Reversal := 1; END_IF;
    1: // Purge L->R
        DO_FireLeft := FALSE; DO_FireRight := FALSE; DO_PurgeValve := TRUE;
        IF Timer_Purge.Q THEN State_Reversal := 2; END_IF;
    2: // Fire Right
        DO_FireLeft := FALSE; DO_FireRight := TRUE; DO_PurgeValve := FALSE;
        IF Timer_Firing.Q THEN State_Reversal := 3; END_IF;
    3: // Purge R->L
        DO_FireLeft := FALSE; DO_FireRight := FALSE; DO_PurgeValve := TRUE;
        IF Timer_Purge.Q THEN State_Reversal := 0; END_IF;
END_CASE;

// When purging, lock outputs
IF (State_Reversal = 1) OR (State_Reversal = 3) THEN
    AO_AirValveCmd := 0.0;
ELSE
    IF AI_FuelFlow > 0.0 THEN PID_Ratio.PV := AI_AirFlow / AI_FuelFlow; END_IF;
    PID_Ratio.SP := SP_AirFuelRatio;
    PID_Ratio(AUTO := TRUE);
    AO_AirValveCmd := PID_Ratio.OUT;
END_IF;

PID_Level.PV := AI_GlassLevel;
PID_Level.SP := SP_GlassLevel;
PID_Level(AUTO := TRUE);
AO_FeederSpeedCmd := PID_Level.OUT;

END_PROGRAM
