    Fault_AirSensor : BOOL;
    Fault_LevelSensor : BOOL;
    System_Fault : BOOL;
END_VAR

// Diagnostics
Fault_FuelSensor := (AI_FuelFlow < 0.0) OR (AI_FuelFlow > 5000.0);
Fault_AirSensor := (AI_AirFlow < 0.0) OR (AI_AirFlow > 50000.0);
Fault_LevelSensor := (AI_GlassLevel < 0.0) OR (AI_GlassLevel > 2000.0);

