PROGRAM MAIN
VAR
    // EtherCAT Diagnostics mapped to TwinCAT I/O
    nEcMasterState AT %I* : UINT;
    nEcSlaveState_Valve1 AT %I* : UINT;
    bEcSlaveError : BOOL;

    bStartCycle : BOOL;
