    bSteamValveOpenFeedback AT %I* : BOOL;
    fbValveMonitor : TON;

    fbHoldTimer : TON;
    fbTempPID : FB_BasicPID;

    bFaultActive : BOOL;
    sFaultMessage : STRING;

    eState : (IDLE, CHECK_COMMS, HEATING, STERILIZE, COOLING, COMPLETE, FAULT);
END_VAR

// EtherCAT diagnostic check (8 = OP state)
IF nEcMasterState <> 8 OR nEcSlaveState_Valve1 <> 8 THEN
    bEcSlaveError := TRUE;
    bFaultActive := TRUE;
    sFaultMessage := 'EtherCAT Communication Fault';
    eState := FAULT;
END_IF

// Valve Feedback Diagnostic
fbValveMonitor(IN := (bSteamValveCmd XOR bSteamValveOpenFeedback), PT := T#2S);
IF fbValveMonitor.Q THEN
    bFaultActive := TRUE;
    sFaultMessage := 'Steam Valve Actuation Failure';
    eState := FAULT;
END_IF

// PID Execution
fbTempPID(
    fSetpointValue := rTargetTemp,
    fActualValue := rChamberTemp,
    bReset := (eState = IDLE),
    fKp := 2.5, fTn := 15.0
);

CASE eState OF
    IDLE:
        bSteamValveCmd := FALSE;
        IF bStartCycle AND NOT bFaultActive THEN
            eState := CHECK_COMMS;
        END_IF

    CHECK_COMMS:
        IF NOT bEcSlaveError THEN
            eState := HEATING;
        END_IF

    HEATING:
        bSteamValveCmd := TRUE;
        IF rChamberTemp >= rTargetTemp THEN
            eState := STERILIZE;
        END_IF

    STERILIZE:
        bSteamValveCmd := (fbTempPID.fCtrlOutput > 50.0);
        fbHoldTimer(IN := (rChamberTemp >= rTargetTemp), PT := T#15M);
        IF fbHoldTimer.Q THEN
            fbHoldTimer(IN := FALSE);
            eState := COOLING;
        END_IF

    COOLING:
        bSteamValveCmd := FALSE;
        IF rChamberTemp <= 60.0 THEN
            eState := COMPLETE;
        END_IF

    COMPLETE:
        IF NOT bStartCycle THEN
            eState := IDLE;
        END_IF

    FAULT:
        bSteamValveCmd := FALSE;
        // Await fault reset
END_CASE
