```pascal
// OPC UA Struct Definition for SCADA
TYPE ST_AutoclaveTelemetry :
STRUCT
    {attribute 'OPC.UA.DA' := '1'}
    rAvgTemp : REAL;
    {attribute 'OPC.UA.DA' := '1'}
    rAvgPressure : REAL;
    {attribute 'OPC.UA.DA' := '1'}
    sCurrentState : STRING;
    {attribute 'OPC.UA.DA' := '1'}
    bActiveFault : BOOL;
END_STRUCT
END_TYPE

PROGRAM MAIN
VAR
    // IEC 62443 RBAC
    sCurrentUserLevel : STRING := 'OPERATOR'; // E.g., 'OPERATOR', 'SUPERVISOR'
    bAuthSuccess : BOOL;

    // Redundant Sensors
    rTemp1 AT %I* : REAL;
    rTemp2 AT %I* : REAL;
    bTemp1Fault : BOOL;
    bTemp2Fault : BOOL;
    rActiveTemp : REAL;

    // SCADA Telemetry
    stScadaData : ST_AutoclaveTelemetry;

    bStartCycle : BOOL;
    bSteamValveCmd AT %Q* : BOOL;
    eState : (IDLE, HEATING, STERILIZE, COOLING, FAULT);
END_VAR

// Sensor Failover & Averaging Logic
IF ABS(rTemp1 - rTemp2) > 5.0 THEN
    // Deviation alarm - fall back to safest conservative value
    stScadaData.bActiveFault := TRUE;
END_IF

IF NOT bTemp1Fault AND NOT bTemp2Fault THEN
    rActiveTemp := (rTemp1 + rTemp2) / 2.0;
ELSIF bTemp1Fault AND NOT bTemp2Fault THEN
    rActiveTemp := rTemp2;
ELSIF bTemp2Fault AND NOT bTemp1Fault THEN
    rActiveTemp := rTemp1;
ELSE
    eState := FAULT;
END_IF

stScadaData.rAvgTemp := rActiveTemp;

CASE eState OF
    IDLE:
        stScadaData.sCurrentState := 'IDLE';
        bSteamValveCmd := FALSE;

        // RBAC Check
        IF bStartCycle THEN
            IF sCurrentUserLevel = 'SUPERVISOR' OR sCurrentUserLevel = 'OPERATOR' THEN
                bAuthSuccess := TRUE;
                eState := HEATING;
            ELSE
                stScadaData.bActiveFault := TRUE; // Unauthorized attempt
            END_IF
            bStartCycle := FALSE;
        END_IF

    HEATING:
        stScadaData.sCurrentState := 'HEATING';
        bSteamValveCmd := TRUE;
        IF rActiveTemp >= 121.1 THEN
            eState := STERILIZE;
        END_IF

    STERILIZE:
        stScadaData.sCurrentState := 'STERILIZE';
        // Sterilization logic with redundant sensor validation...
        eState := COOLING;

    COOLING:
        stScadaData.sCurrentState := 'COOLING';
        bSteamValveCmd := FALSE;
        IF rActiveTemp <= 60.0 THEN
            eState := IDLE;
        END_IF

    FAULT:
        stScadaData.sCurrentState := 'FAULT';
        bSteamValveCmd := FALSE;
END_CASE
