    rDriftThreshold : REAL := 1.5; // max deviation in Celsius
    bDriftAlarm : BOOL;

    // Self-Test Routine
    bSelfTestComplete : BOOL;
    fbTestTimer : TON;
    nTestStep : INT;

    // Actuators & Feedback
    bSteamValveCmd AT %Q* : BOOL;
    bSteamValveOpenFb AT %I* : BOOL;

    // Cycle Control
    bStartCycle : BOOL;
    sUserRole : STRING := 'SUPERVISOR';

    eState : (IDLE, SELF_TEST, HEATING, STERILIZE, FAULT);
END_VAR

// 1. Digital Twin / HIL Synchronization
IF bHIL_Mode THEN
    // Inject simulation values
    rTemp1 := rHIL_SimTemp;
    rTemp2 := rHIL_SimTemp;
END_IF

// 2. Sensor Drift Detection
IF ABS(rTemp1 - rTemp2) > rDriftThreshold THEN
    bDriftAlarm := TRUE;
    eState := FAULT;
ELSE
    rActiveTemp := (rTemp1 + rTemp2) / 2.0;
    bDriftAlarm := FALSE;
END_IF

CASE eState OF
    IDLE:
        bSteamValveCmd := FALSE;
        IF bStartCycle AND sUserRole = 'SUPERVISOR' THEN
            bSelfTestComplete := FALSE;
            nTestStep := 1;
            eState := SELF_TEST;
        END_IF

    SELF_TEST:
        // 3. Pre-cycle Automated Self-Test
        CASE nTestStep OF
            1: // Test Steam Valve Actuation
                bSteamValveCmd := TRUE;
                fbTestTimer(IN := TRUE, PT := T#2S);
                IF fbTestTimer.Q THEN
                    IF bSteamValveOpenFb THEN
                        nTestStep := 2;
                        fbTestTimer(IN := FALSE);
                    ELSE
                        eState := FAULT; // Valve failed to open
                    END_IF
                END_IF
            2: // Close Valve and confirm
                bSteamValveCmd := FALSE;
                fbTestTimer(IN := TRUE, PT := T#2S);
                IF fbTestTimer.Q THEN
                    IF NOT bSteamValveOpenFb THEN
                        bSelfTestComplete := TRUE;
                        fbTestTimer(IN := FALSE);
                        eState := HEATING;
                    ELSE
                        eState := FAULT;
                    END_IF
                END_IF
        END_CASE

    HEATING:
        bSteamValveCmd := TRUE;
        IF rActiveTemp >= 121.1 THEN
            eState := STERILIZE;
        END_IF

    STERILIZE:
        bSteamValveCmd := FALSE;
        // ... 

    FAULT:
        bSteamValveCmd := FALSE;
        // Log fault to OPC UA and await reset
END_CASE
