    STATE_PRESSURIZE : INT := 3;
    STATE_IGNITION : INT := 4;
    STATE_MAIN_STAGE : INT := 5;
    STATE_SHUTDOWN : INT := 6;
    tPurgeTimer : TON;
END_VAR

IF bEmergencyStop THEN
    iState := STATE_SHUTDOWN;
END_IF;

tPurgeTimer(IN := (iState = STATE_PURGE), PT := T#10s);

CASE iState OF
    STATE_IDLE:
        bLOX_MainValve := FALSE;
        bLH2_MainValve := FALSE;
