    STATE_CHILLDOWN:
        bChilldownValve_LOX := TRUE;
        bChilldownValve_LH2 := TRUE;
        IF (rLOX_Temp < -180.0) AND (rLH2_Temp < -250.0) THEN
            bChilldownValve_LOX := FALSE;
            bChilldownValve_LH2 := FALSE;
