        fActualPos : LREAL;
        fSoundSpeed : REAL;
        bFault : BOOL;
    END_STRUCT;
    eState : (IDLE, AUTH_CHECK, INIT_SHIELDING, CALIBRATING_ENV, POSITIONING, ACTIVE, STOPPING, FAULT);
END_VAR

bHeartbeatToSecondary := NOT bHeartbeatToSecondary;

stScadaDataPacket.bReady := bSystemReady;
stScadaDataPacket.fActualPos := fAcousticArrayActualPosition;
stScadaDataPacket.fSoundSpeed := fSpeedOfSound;
stScadaDataPacket.bFault := bSystemFault;

fSpeedOfSound := 1448.96 + 4.591*fWaterTemp - 0.05304*fWaterTemp*fWaterTemp + 1.34*(fSalinity - 35.0);

IF bEcSlaveError OR bEcMasterState <> 8 OR NOT bPrimaryControllerActive THEN
    bSystemFault := TRUE;
    eState := FAULT;
END_IF

CASE eState OF
    IDLE:
        bSystemReady := FALSE;
        bRFShieldEngaged := FALSE;
        bCalibrationComplete := FALSE;
        IF bStartMission AND NOT bSystemFault THEN eState := AUTH_CHECK; END_IF
    AUTH_CHECK:
        IF bUserAuthenticated AND bEncryptedChannelActive AND nAccessLevel >= 3 THEN
            eState := INIT_SHIELDING;
        ELSE
            eState := IDLE;
        END_IF
    INIT_SHIELDING:
        IF bRFShieldDoorsClosed THEN
            bRFShieldEngaged := TRUE;
            eState := CALIBRATING_ENV;
        END_IF
    CALIBRATING_ENV:
        IF fWaterTemp > 0.0 AND fSalinity > 0.0 THEN
            bCalibrationComplete := TRUE;
            eState := POSITIONING;
        END_IF
    POSITIONING:
        bAcousticArrayMoving := TRUE;
        IF ABS(fAcousticArrayTargetPosition - fAcousticArrayActualPosition) > 0.1 THEN
            IF fAcousticArrayTargetPosition > fAcousticArrayActualPosition THEN
                fAcousticArrayActualPosition := fAcousticArrayActualPosition + 0.1;
            ELSE
                fAcousticArrayActualPosition := fAcousticArrayActualPosition - 0.1;
            END_IF
        ELSE
            bAcousticArrayMoving := FALSE;
            eState := ACTIVE;
        END_IF
    ACTIVE:
        bSystemReady := TRUE;
        IF bStopMission THEN eState := STOPPING; END_IF
    STOPPING:
        bSystemReady := FALSE;
        bRFShieldEngaged := FALSE;
        eState := IDLE;
    FAULT:
        bSystemReady := FALSE;
        bAcousticArrayMoving := FALSE;
        bRFShieldEngaged := FALSE;
        IF bResetEcErrors AND bUserAuthenticated THEN
            bSystemFault := FALSE;
            eState := IDLE;
        END_IF
END_CASE

