TYPE UDT_Profinet_Data
STRUCT
    ControlWord : WORD;
    StatusWord : WORD;
    ActualSpeed : REAL;
END_STRUCT;
END_TYPE

FUNCTION_BLOCK FB_HydroPlant_Profinet
VAR_INPUT
    PN_In : UDT_Profinet_Data;
    Penstock_Pressure : REAL;
END_VAR
VAR_OUTPUT
    PN_Out : UDT_Profinet_Data;
    Valve_Cmd : INT;
    Diag_Error_Code : DWORD;
END_VAR
VAR
    Cmd_Start : BOOL;
    Cmd_Stop : BOOL;
    Fault_LowPressure : BOOL;
END_VAR
BEGIN
    Cmd_Start := (PN_In.ControlWord AND 16#0001) > 0;
    Cmd_Stop  := (PN_In.ControlWord AND 16#0002) > 0;

    Fault_LowPressure := Penstock_Pressure < 5.0;

    Diag_Error_Code := 0;
    IF Fault_LowPressure THEN Diag_Error_Code := Diag_Error_Code OR 16#00000002; END_IF;

    IF Diag_Error_Code <> 0 OR Cmd_Stop THEN
        Valve_Cmd := 2;
        PN_Out.StatusWord := 16#8000;
    ELSIF Cmd_Start THEN
        Valve_Cmd := 1;
        PN_Out.StatusWord := 16#0003;
    END_IF;
END_FUNCTION_BLOCK
