```iecst
PROGRAM MAIN
VAR
    // Inputs
    RackSOC : ARRAY[1..10] OF REAL; // SOC of 10 battery racks (%)
    GridPowerReq : REAL; // Requested power from grid (kW)
    MaxInverterPower : REAL := 1000.0; // Inverter clipping limit (kW)

    // Outputs
    RackPowerCmd : ARRAY[1..10] OF REAL;
    TotalOutputPower : REAL;

    // Internal
    i : INT;
    AvgSOC : REAL;
    TotalSOC : REAL;
    ClippingActive : BOOL;
    TargetPower : REAL;
END_VAR

// Calculate Average SOC
TotalSOC := 0;
FOR i := 1 TO 10 DO
    TotalSOC := TotalSOC + RackSOC[i];
END_FOR
AvgSOC := TotalSOC / 10.0;

// Inverter Clipping
IF ABS(GridPowerReq) > MaxInverterPower THEN
    TargetPower := SEL(GridPowerReq > 0, -MaxInverterPower, MaxInverterPower);
    ClippingActive := TRUE;
ELSE
    TargetPower := GridPowerReq;
    ClippingActive := FALSE;
END_IF

// SOC Balancing: Distribute power based on SOC deviation
TotalOutputPower := 0;
FOR i := 1 TO 10 DO
    // Simple proportional balancing: higher SOC gets more discharge, lower gets more charge
    IF AvgSOC > 0 THEN
        RackPowerCmd[i] := (TargetPower / 10.0) * (RackSOC[i] / AvgSOC);
    ELSE
        RackPowerCmd[i] := TargetPower / 10.0;
    END_IF
    TotalOutputPower := TotalOutputPower + RackPowerCmd[i];
END_FOR
