    Raise_Tap : BOOL;
    Lower_Tap : BOOL;

    // Distance Protection
    Z_Measured : REAL;
    Z_Zone1_Limit : REAL := 10.0;
    Trip_Breaker : BOOL;

    // Settings
    V_Setpoint : REAL := 11000.0;
    Deadband : REAL := 200.0;
END_VAR

// Distance Protection Logic (Z = V / I)
IF I_Line > 0.0 THEN
    Z_Measured := V_Secondary / I_Line;
ELSE
    Z_Measured := 9999.0;
END_IF;

IF Z_Measured < Z_Zone1_Limit THEN
    Trip_Breaker := TRUE;
ELSE
    Trip_Breaker := FALSE;
END_IF;

// Tap Changer Logic
Raise_Tap := FALSE;
Lower_Tap := FALSE;

IF NOT Trip_Breaker THEN
    IF V_Secondary < (V_Setpoint - Deadband) AND Tap_Position < Tap_Max THEN
        Raise_Tap := TRUE;
        Tap_Position := Tap_Position + 1;
    ELSIF V_Secondary > (V_Setpoint + Deadband) AND Tap_Position > Tap_Min THEN
        Lower_Tap := TRUE;
        Tap_Position := Tap_Position - 1;
    END_IF;
END_IF;
