FUNCTION_BLOCK "BeverageFiller_Profinet"
VAR_INPUT
    PN_Status : Word;
    Start : Bool;
    Stop : Bool;
    Reset : Bool;
    BottlePresent : Bool;
    CapPresent : Bool;
    FillLevelSensor : Real; 
    CarbonationPressure : Real; 
