    eState : (BOOT, SELF_TEST, INIT, STERILIZE, FILL, SEAL, DONE, FAULT_STATE);
    bStartProcess_SCADA : BOOL;
    bJawClosed : BOOL;
    tSterilize, tSeal : TON;
END_VAR

IF ABS(fH2O2_Temp_SensorA - fH2O2_Temp_SensorB) > 2.0 THEN
    bDriftDetected := TRUE;
    fH2O2_Temp_Voted := MIN(fH2O2_Temp_SensorA, fH2O2_Temp_SensorB);
ELSE
    bDriftDetected := FALSE;
    fH2O2_Temp_Voted := (fH2O2_Temp_SensorA + fH2O2_Temp_SensorB) / 2.0;
END_IF

IF bHilModeActive THEN
    fDigitalTwin_H2O2_Temp := fH2O2_Temp_Voted;
    iDigitalTwin_State := eState;
END_IF

CASE eState OF
    BOOT:
        eState := SELF_TEST;
    SELF_TEST:
        bJawClosed := TRUE;
        tSelfTest(IN:=TRUE, PT:=T#3S);
        IF tSelfTest.Q AND NOT bDriftDetected THEN
            bJawClosed := FALSE;
            bSelfTestPassed := TRUE;
            tSelfTest(IN:=FALSE);
            eState := INIT;
        ELSIF tSelfTest.Q AND bDriftDetected THEN
            eState := FAULT_STATE;
        END_IF
    INIT:
        IF bStartProcess_SCADA AND bSelfTestPassed THEN
            eState := STERILIZE;
        END_IF
    STERILIZE:
        tSterilize(IN:=TRUE, PT:=T#5S);
        IF tSterilize.Q THEN tSterilize(IN:=FALSE); eState:=FILL; END_IF
    FILL:
        eState := SEAL;
    SEAL:
        bJawClosed := TRUE;
        tSeal(IN:=TRUE, PT:=T#2S);
        IF tSeal.Q THEN 
            bJawClosed:=FALSE; tSeal(IN:=FALSE); eState:=DONE; 
        END_IF
    DONE:
        bStartProcess_SCADA := FALSE;
        eState := INIT;
    FAULT_STATE:
        bJawClosed := FALSE;
END_CASE
