END_IF;

// Sensor Diagnostics
IF Temp_PV < 0.0 OR Temp_PV > 100.0 THEN
    Temp_Sensor_Fault := TRUE;
    Alarm_Active := TRUE;
END_IF;

IF NOT Alarm_Active THEN
    IF Mash_Phase = 0 THEN // Hydration
        IF Current_Water_Vol < Target_Water_Vol THEN
            Strike_Water_Valve := TRUE;
            IF Current_Water_Vol > (Target_Water_Vol * 0.1) THEN
                Grist_Auger := TRUE;
            ELSE
                Grist_Auger := FALSE;
            END_IF;
            Rake_Speed_SP := 25.0;
        ELSE
            Strike_Water_Valve := FALSE;
            Grist_Auger := FALSE;
            Mash_Phase := 1;
        END_IF;
    ELSIF Mash_Phase = 1 THEN
        Temp_SP := 50.0; 
        Rake_Speed_SP := 15.0;
