```structured-text
PROGRAM MashTun_Adversarial
VAR
    Temp_PV1 : REAL; 
    Temp_PV2 : REAL; 
    Active_Temp_PV : REAL;
    Temp_SP : REAL; 
    Steam_Valve_CV : REAL; 
    Rake_Speed_SP : REAL;
    Mash_Phase : INT; 
    PID_Temp : PID;
    Strike_Water_Valve : BOOL; 
    Grist_Auger : BOOL;
    Current_Water_Vol : REAL; 
    Target_Water_Vol : REAL;
    EIP_Comm_Status : DINT; 
    Temp_Sensor_Fault : BOOL; 
    Alarm_Active : BOOL;
    User_Role : INT; 
    SCADA_Heartbeat : INT; 
    Write_Access_Granted : BOOL;
    Drift_Timer : TON;
    PV1_History : REAL; 
    PV2_History : REAL;
    Drift_Error : BOOL;
    HIL_Mode : BOOL;
    Digital_Twin_Temp : REAL;
    Self_Test_Active : BOOL;
    Self_Test_Step : INT;
    Valve_Feedback : BOOL;
END_VAR

// Digital Twin Sync (HIL)
IF HIL_Mode THEN
    Active_Temp_PV := Digital_Twin_Temp;
ELSE
    // Sensor Drift Detection
    Drift_Timer(IN := TRUE, PT := T#10s);
    IF Drift_Timer.Q THEN
        IF ABS((Temp_PV1 - PV1_History) - (Temp_PV2 - PV2_History)) > 2.0 THEN
            Drift_Error := TRUE; 
            Alarm_Active := TRUE;
        END_IF;
        PV1_History := Temp_PV1; 
        PV2_History := Temp_PV2;
        Drift_Timer(IN := FALSE); // Reset
    END_IF;

    IF ABS(Temp_PV1 - Temp_PV2) > 5.0 THEN 
        Temp_Sensor_Fault := TRUE; 
        Alarm_Active := TRUE; 
    END_IF;

    IF NOT Temp_Sensor_Fault AND NOT Drift_Error THEN 
        Active_Temp_PV := (Temp_PV1 + Temp_PV2) / 2.0; 
    END_IF;
END_IF;

Write_Access_Granted := (User_Role >= 2) AND (SCADA_Heartbeat > 0);
IF EIP_Comm_Status <> 1 THEN 
    Alarm_Active := TRUE; 
END_IF;

// Self-Test Routine
IF Self_Test_Active THEN
    CASE Self_Test_Step OF
        0: 
            Strike_Water_Valve := TRUE; 
            Self_Test_Step := 1;
        1: 
            IF Valve_Feedback THEN 
                Strike_Water_Valve := FALSE; 
                Self_Test_Step := 2; 
            END_IF;
        2: 
            IF NOT Valve_Feedback THEN 
                Self_Test_Active := FALSE; 
                Mash_Phase := 0; 
            END_IF;
    END_CASE;
    RETURN;
END_IF;

IF NOT Alarm_Active AND NOT Self_Test_Active THEN
    IF Mash_Phase = 0 THEN
        IF Current_Water_Vol < Target_Water_Vol THEN
            Strike_Water_Valve := TRUE; 
            IF Current_Water_Vol > (Target_Water_Vol * 0.1) THEN
                Grist_Auger := TRUE;
            ELSE
                Grist_Auger := FALSE;
            END_IF;
            Rake_Speed_SP := 25.0;
        ELSE 
            Strike_Water_Valve := FALSE; 
            Grist_Auger := FALSE; 
            Mash_Phase := 1; 
        END_IF;
    ELSIF Mash_Phase = 1 THEN 
        Temp_SP := 50.0; 
        Rake_Speed_SP := 15.0;
    ELSIF Mash_Phase = 2 THEN 
        Temp_SP := 65.0; 
        Rake_Speed_SP := 10.0;
    ELSIF Mash_Phase = 3 THEN 
        Temp_SP := 75.0; 
        Rake_Speed_SP := 20.0;
    END_IF;

    IF Write_Access_Granted THEN
        PID_Temp.PV := Active_Temp_PV; 
        PID_Temp.SP := Temp_SP; 
        PID_Temp.KP := 2.5; 
        PID_Temp.KI := 0.1;
        PID_Temp(); 
        Steam_Valve_CV := PID_Temp.CV;
    END_IF;
ELSE
    Steam_Valve_CV := 0.0; 
    Rake_Speed_SP := 0.0; 
    Strike_Water_Valve := FALSE; 
    Grist_Auger := FALSE;
END_IF;
