        TempError := TargetTemp - ActualTemp;
        HeaterOutput := LIMIT(MN:=0.0, IN:=(TempError * 5.0), MX:=100.0);

        // Thickness Control
        ThicknessError := TargetThickness - ActualThickness;
        PumpSpeed := LIMIT(MN:=10.0, IN:=(BeltSpeed * 1.5) + (Viscosity * 0.2) + (ThicknessError * 5.0), MX:=100.0);

        // Blower Coordination
        BlowerVelocity := LIMIT(MN:=10.0, IN:=(PumpSpeed * 0.8) - (TempError * 1.5), MX:=100.0);
    ELSE
        HeaterOutput := 0.0;
        BlowerVelocity := 0.0;
        PumpSpeed := 0.0;
    END_IF;
END_FUNCTION_BLOCK
