    // HIL Digital Twin Sync
    bHIL_ModeActive : BOOL;
    rHIL_SimTemp : REAL;

    // Sensor Drift Detection
    rMaxAllowedDrift : REAL := 0.5; // °C
    rCurrentDrift : REAL;
    bSensorDriftFault : BOOL;
    rEffectiveHoldTemp : REAL;

    // Self-Test Routine
    bStartMorningSelfTest : BOOL;
    iSelfTestState : INT := 0;
    fbSelfTestTimer : TON;
    bSelfTestPass : BOOL;

    // Core parameters
    rPasteurizationTemp : REAL := 72.0;
    tHoldingTime : TIME := T#15S;

    // Core logic
    fbHoldTimer : TON;
    bTempOK : BOOL;
    bSystemSafe : BOOL;
END_VAR

// 1. Digital Twin Synchronization
IF bHIL_ModeActive THEN
    // Use simulated data from Digital Twin for testing
    rEffectiveHoldTemp := rHIL_SimTemp;
    bSensorDriftFault := FALSE;
ELSE
    // 2. Dual-Redundant Sensor Drift Detection
    rCurrentDrift := ABS(rHoldTempA - rHoldTempB);
    IF rCurrentDrift > rMaxAllowedDrift THEN
        bSensorDriftFault := TRUE; // Critical deviation
    ELSE
        bSensorDriftFault := FALSE;
        // Average the two sensors if within tolerance
        rEffectiveHoldTemp := (rHoldTempA + rHoldTempB) / 2.0;
    END_IF
END_IF

// 3. Morning Self-Test Routine for FDV
