    CASE iSelfTestState OF
        0: // Init
            bFlowDiversionValve := FALSE;
            fbSelfTestTimer(IN:=FALSE);
            iSelfTestState := 10;
        10: // Activate FDV
            bFlowDiversionValve := TRUE;
            fbSelfTestTimer(IN:=TRUE, PT:=T#5S);
            IF fbSelfTestTimer.Q THEN
                iSelfTestState := 20;
            END_IF
        20: // Deactivate FDV and check feedback (assuming feedback exists)
            bFlowDiversionValve := FALSE;
            bSelfTestPass := TRUE;
            bStartMorningSelfTest := FALSE;
            iSelfTestState := 0;
    END_CASE;
    RETURN; // Halt normal operation during test
END_IF

// 4. Main Safety Logic
bSystemSafe := NOT bSensorDriftFault AND bSelfTestPass;
bTempOK := (rEffectiveHoldTemp >= rPasteurizationTemp) AND bSystemSafe;

fbHoldTimer(IN := bTempOK, PT := tHoldingTime);

IF fbHoldTimer.Q THEN
    bFlowDiversionValve := TRUE; // Pasteurized, forward flow
ELSE
    bFlowDiversionValve := FALSE; // Diverted
END_IF
