```scl
FUNCTION_BLOCK "Bioreactor_Advanced"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.2
   VAR_INPUT 
      DO_PV : Real;   
      DO_SP : Real;   
      Agitator_Power_PV : Real; 
      Power_Max : Real; 
      pH_PV : Real;
      pH_SP : Real;
      Foam_Level_Sensor : Bool;
      Reset : Bool; 
   END_VAR

   VAR_OUTPUT 
      Agitator_Speed_SP : Real; 
      Air_Flow_SP : Real;       
      Acid_Pump_Cmd : Bool;
      Base_Pump_Cmd : Bool;
      Antifoam_Pump_Cmd : Bool;
