```scl
FUNCTION_BLOCK "Bioreactor_Cyber_Failover"
{ S7_Optimized_Access := 'TRUE' }
VERSION : 0.4
   VAR_INPUT 
      DO_PV_1 : Real;
      DO_PV_2 : Real;
      SCADA_Heartbeat : Bool;
      User_Role : Int; // 0=None, 1=Operator, 2=Admin
      SCADA_DO_SP : Real;
      Local_DO_SP : Real;
   END_VAR

   VAR_OUTPUT 
      Active_DO_PV : Real;
      DO_Sensor_Mismatch : Bool;
      Comm_Loss : Bool;
      Agitator_Speed_SP : Real;
   END_VAR

   VAR 
      Heartbeat_Timer : TON;
      Last_Heartbeat : Bool;
      Effective_SP : Real;
      DO_PID : "PID_Compact";
      DO_Control_Out : Real;
   END_VAR

BEGIN
    // 1. Cybersecurity & RBAC (IEC 62443-3-3)
    // SCADA Comm Loss Detection via Heartbeat
    #Heartbeat_Timer(IN := (#SCADA_Heartbeat = #Last_Heartbeat), PT := T#2s);
    #Comm_Loss := #Heartbeat_Timer.Q;
    #Last_Heartbeat := #SCADA_Heartbeat;

    // Role-based Access Control for Setpoints
    IF NOT #Comm_Loss AND #User_Role = 2 THEN
        #Effective_SP := #SCADA_DO_SP; // Admin level allows SCADA override
    ELSE
        #Effective_SP := #Local_DO_SP; // Operators restricted to local HMI
    END_IF;

    // 2. Redundant Sensor Failover (1oo2 Voting logic)
    #DO_Sensor_Mismatch := ABS(#DO_PV_1 - #DO_PV_2) > 10.0;

    IF (#DO_PV_1 > 0.0 AND #DO_PV_1 <= 100.0) AND NOT #DO_Sensor_Mismatch THEN
        #Active_DO_PV := (#DO_PV_1 + #DO_PV_2) / 2.0; // Average if healthy
    ELSIF #DO_PV_1 > 0.0 AND #DO_PV_1 <= 100.0 THEN
        #Active_DO_PV := #DO_PV_1; // Trust primary if deviating but valid bounds
    ELSIF #DO_PV_2 > 0.0 AND #DO_PV_2 <= 100.0 THEN
        #Active_DO_PV := #DO_PV_2; // Failover to secondary
    ELSE
        #Active_DO_PV := 50.0; // Safe state fallback
    END_IF;

    // 3. DO Control Execution
    #DO_PID(Setpoint := #Effective_SP,
            Input := #Active_DO_PV,
            Output => #DO_Control_Out);

    #Agitator_Speed_SP := (#DO_Control_Out / 100.0) * 300.0; 

END_FUNCTION_BLOCK
