PROGRAM MAIN
VAR
    bStartCIP : BOOL;
    bStopCIP : BOOL;
    fConductivity : REAL;
    fPumpSuctionPressure : REAL;
    bSupplyPumpRun : BOOL;
    bReturnPumpRun : BOOL;
    bWaterValve : BOOL;
    bAcidValve : BOOL;
    bCausticValve : BOOL;
    bDrainValve : BOOL;
    bRecoverValve : BOOL;
    nStep : INT;
    fCavitationLimit : REAL := 0.2;
    fWaterCondThreshold : REAL := 1.0;
    fAcidCondThreshold : REAL := 20.0;
    fCausticCondThreshold : REAL := 50.0;
    bCavitationAlarm : BOOL;
    tStepTimer : TON;
END_VAR

// Pump Cavitation Prevention
IF (bSupplyPumpRun OR bReturnPumpRun) AND (fPumpSuctionPressure < fCavitationLimit) THEN
    bCavitationAlarm := TRUE;
    bSupplyPumpRun := FALSE;
    bReturnPumpRun := FALSE;
END_IF
IF NOT (bSupplyPumpRun OR bReturnPumpRun) AND fPumpSuctionPressure >= fCavitationLimit THEN
    bCavitationAlarm := FALSE;
END_IF

// Phase Separation Logic
IF fConductivity > fCausticCondThreshold THEN
    bRecoverValve := TRUE; bDrainValve := FALSE;
ELSIF fConductivity > fAcidCondThreshold THEN
    bRecoverValve := TRUE; bDrainValve := FALSE;
ELSIF fConductivity < fWaterCondThreshold THEN
    bRecoverValve := TRUE; bDrainValve := FALSE;
ELSE
    bRecoverValve := FALSE; bDrainValve := TRUE;
END_IF

// CIP State Machine
IF bStartCIP AND NOT bCavitationAlarm THEN
    nStep := 10;
    bStartCIP := FALSE;
END_IF
IF bStopCIP THEN
    nStep := 0;
    bStopCIP := FALSE;
END_IF

CASE nStep OF
    0:
        bSupplyPumpRun := FALSE; bReturnPumpRun := FALSE;
        bWaterValve := FALSE; bAcidValve := FALSE; bCausticValve := FALSE;
    10:
        bWaterValve := TRUE;
        bSupplyPumpRun := TRUE; bReturnPumpRun := TRUE;
        tStepTimer(IN:=TRUE, PT:=T#5M);
        IF tStepTimer.Q THEN
            tStepTimer(IN:=FALSE); bWaterValve := FALSE; nStep := 20;
        END_IF
    20:
        bCausticValve := TRUE;
        tStepTimer(IN:=TRUE, PT:=T#15M);
        IF tStepTimer.Q THEN
            tStepTimer(IN:=FALSE); bCausticValve := FALSE; nStep := 30;
        END_IF
    30:
        bWaterValve := TRUE;
        tStepTimer(IN:=TRUE, PT:=T#5M);
        IF tStepTimer.Q THEN
            tStepTimer(IN:=FALSE); bWaterValve := FALSE;
            bSupplyPumpRun := FALSE; bReturnPumpRun := FALSE; nStep := 0;
        END_IF
END_CASE

PROGRAM MAIN
VAR
    bStartCIP : BOOL;
    fConductivity : REAL;
    fPumpSuctionPressure : REAL;
    bSupplyPumpRun : BOOL;
    bReturnPumpRun : BOOL;
    bWaterValve : BOOL;
    bCausticValve : BOOL;
    bRecoverValve : BOOL;
    bDrainValve : BOOL;
    nStep : INT;
    fCavitationLimit : REAL := 0.2;
    bCavitationAlarm : BOOL;
    tStepTimer : TON;
    fbPID : FB_BasicPID;
    fActualTemp : REAL;
    fSetpointTemp : REAL;
    fSteamValvePos : LREAL;
    bHeatEnable : BOOL;
END_VAR

IF (bSupplyPumpRun OR bReturnPumpRun) AND (fPumpSuctionPressure < fCavitationLimit) THEN
    bCavitationAlarm := TRUE;
    bSupplyPumpRun := FALSE;
    bReturnPumpRun := FALSE;
END_IF

fbPID(
    fSetpointValue := fSetpointTemp,
    fActualValue := fActualTemp,
    bReset := NOT bHeatEnable,
    fCtrlCycleTime := 0.1,
    fKp := 2.5, fTn := 10.0,
    fMaxCtrlOutput := 100.0, fMinCtrlOutput := 0.0,
    fCtrlOutput => fSteamValvePos
);
IF NOT bHeatEnable THEN fSteamValvePos := 0.0; END_IF

IF fConductivity > 50.0 THEN bRecoverValve := TRUE; bDrainValve := FALSE;
ELSIF fConductivity < 1.0 THEN bRecoverValve := TRUE; bDrainValve := FALSE;
ELSE bRecoverValve := FALSE; bDrainValve := TRUE;
END_IF

CASE nStep OF
    0:
        bSupplyPumpRun := FALSE; bReturnPumpRun := FALSE;
        bWaterValve := FALSE; bCausticValve := FALSE; bHeatEnable := FALSE;
        IF bStartCIP AND NOT bCavitationAlarm THEN nStep := 10; END_IF
    10:
        bWaterValve := TRUE;
        bSupplyPumpRun := TRUE; bReturnPumpRun := TRUE;
        tStepTimer(IN:=TRUE, PT:=T#5M);
        IF tStepTimer.Q THEN
            tStepTimer(IN:=FALSE); bWaterValve := FALSE; nStep := 20;
        END_IF
    20:
        bCausticValve := TRUE;
        fSetpointTemp := 80.0;
        bHeatEnable := TRUE;
        IF fActualTemp >= (fSetpointTemp - 2.0) THEN
            tStepTimer(IN:=TRUE, PT:=T#15M);
        END_IF
        IF tStepTimer.Q THEN
            tStepTimer(IN:=FALSE); bCausticValve := FALSE; bHeatEnable := FALSE; nStep := 0;
            bSupplyPumpRun := FALSE; bReturnPumpRun := FALSE;
