    // HIL Digital Twin Sync Heartbeat
    IF #HIL_Sync_Signal = #Expected_HIL_Signal THEN
        #HIL_Sync_Loss := FALSE;
        #Expected_HIL_Signal := #Expected_HIL_Signal + 1; // Basic rolling code sync
    ELSE
        #HIL_Sync_Loss := TRUE;
    END_IF;

    // Sensor Drift Detection (Adversarial Resilience)
    // Compare sensors 1 and 2 over time to detect slow drift
    #Drift_Integrator := #Drift_Integrator + ABS(#Sensor_Thrust_1 - #Sensor_Thrust_2) * 0.001;
    IF #Drift_Integrator > 50.0 THEN
        #Drift_Alarm := TRUE;
    ELSE
        #Drift_Alarm := FALSE;
    END_IF;

    // Redundancy Voting (2 out of 3)
    IF ABS(#Sensor_Thrust_1 - #Sensor_Thrust_2) < 5.0 THEN
        #Validated_Thrust := (#Sensor_Thrust_1 + #Sensor_Thrust_2) / 2.0;
    ELSIF ABS(#Sensor_Thrust_1 - #Sensor_Thrust_3) < 5.0 THEN
        #Validated_Thrust := (#Sensor_Thrust_1 + #Sensor_Thrust_3) / 2.0;
    ELSE
        #Validated_Thrust := #Sensor_Thrust_2; // Fallback
    END_IF;

    // Pre-boring Self-Test Routine
    IF #Initiate_Self_Test AND #Self_Test_Status = 0 THEN
        #Self_Test_Status := 1;
        #Self_Test_Timer := 0;
    END_IF;

    IF #Self_Test_Status = 1 THEN
        #Self_Test_Timer := #Self_Test_Timer + 1;
        // Simulate actuations and check feedback (mocked here)
        IF #Self_Test_Timer > 100 THEN
            IF NOT #Drift_Alarm AND NOT #HIL_Sync_Loss THEN
