PROGRAM PileDriver_Base
VAR
    Start_System : BOOL;
    Stop_System : BOOL;
    System_Running : BOOL;

    // Hammer Stroke Variables
    Hammer_Target_Stroke : REAL := 1.5; // meters
    Hammer_Actual_Stroke : REAL;
    Hammer_Pressure : REAL;
    Hammer_Valve : BOOL;

    // Winch Variables
    Winch_Target_Speed : REAL := 10.0; // rpm
    Winch_Actual_Speed : REAL;
    Winch_Drive_Ref : REAL;

    // Sensors
    Pile_Depth : REAL;
    Max_Depth : REAL := 50.0; // meters
END_VAR

// System Control
IF Start_System AND NOT Stop_System AND Pile_Depth < Max_Depth THEN
    System_Running := TRUE;
ELSIF Stop_System OR Pile_Depth >= Max_Depth THEN
    System_Running := FALSE;
END_IF;

// Hammer Stroke Regulation
IF System_Running THEN
    IF Hammer_Actual_Stroke < Hammer_Target_Stroke AND Hammer_Pressure > 100.0 THEN
        Hammer_Valve := TRUE; // Lift hammer
    ELSE
        Hammer_Valve := FALSE; // Drop hammer
    END_IF;
ELSE
    Hammer_Valve := FALSE;
END_IF;

// Winch Spooling Regulation
IF System_Running THEN
    IF Winch_Actual_Speed < Winch_Target_Speed THEN
        Winch_Drive_Ref := Winch_Drive_Ref + 0.1;
    ELSIF Winch_Actual_Speed > Winch_Target_Speed THEN
        Winch_Drive_Ref := Winch_Drive_Ref - 0.1;
    END_IF;

    // Limits
    IF Winch_Drive_Ref > 100.0 THEN Winch_Drive_Ref := 100.0; END_IF;
    IF Winch_Drive_Ref < 0.0 THEN Winch_Drive_Ref := 0.0; END_IF;
ELSE
    Winch_Drive_Ref := 0.0;
END_IF;
END_PROGRAM
