PROGRAM PileDriver_M1
VAR
    Start_System : BOOL;
    Stop_System : BOOL;
    System_Running : BOOL;

    // Hammer & Winch
    Hammer_Target_Stroke : REAL;
    Hammer_Actual_Stroke : REAL;
    Hammer_Valve : BOOL;
    Winch_Target_Speed : REAL;
    Winch_Actual_Speed : REAL;
    Winch_Drive_Ref : REAL;

    // HPU Variables
    HPU_Pump1_Run : BOOL;
    HPU_Pump2_Run : BOOL;
    HPU_Pressure_Actual : REAL;
    HPU_Pressure_Target : REAL;
    HPU_Temp : REAL;
    HPU_Cooler_Fan : BOOL;

    // Soil Resistance
    Soil_Resistance : REAL; // Feedback from pile impact
END_VAR

// System Control
IF Start_System AND NOT Stop_System THEN
    System_Running := TRUE;
ELSE
    System_Running := FALSE;
END_IF;

// HPU Pressure Target varies with Soil Resistance
HPU_Pressure_Target := 150.0 + (Soil_Resistance * 0.5);
IF HPU_Pressure_Target > 300.0 THEN HPU_Pressure_Target := 300.0; END_IF;

// HPU Pump Control (Lead/Lag with redundancy)
IF System_Running THEN
    IF HPU_Pressure_Actual < HPU_Pressure_Target - 10.0 THEN
        HPU_Pump1_Run := TRUE;
    END_IF;

    IF HPU_Pressure_Actual < HPU_Pressure_Target - 30.0 THEN
        HPU_Pump2_Run := TRUE; // Start lag pump
    END_IF;

    IF HPU_Pressure_Actual >= HPU_Pressure_Target THEN
        HPU_Pump1_Run := FALSE;
        HPU_Pump2_Run := FALSE;
    END_IF;
ELSE
    HPU_Pump1_Run := FALSE;
    HPU_Pump2_Run := FALSE;
END_IF;

// HPU Cooling
IF HPU_Temp > 60.0 THEN
    HPU_Cooler_Fan := TRUE;
ELSIF HPU_Temp < 50.0 THEN
    HPU_Cooler_Fan := FALSE;
END_IF;

// Hammer & Winch Logic
IF System_Running AND HPU_Pressure_Actual >= (HPU_Pressure_Target * 0.8) THEN
    Hammer_Target_Stroke := 1.0 + (Soil_Resistance * 0.01);

    IF Hammer_Actual_Stroke < Hammer_Target_Stroke THEN
        Hammer_Valve := TRUE;
    ELSE
        Hammer_Valve := FALSE;
    END_IF;

    Winch_Drive_Ref := Winch_Target_Speed * 10.0; 
ELSE
    Hammer_Valve := FALSE;
    Winch_Drive_Ref := 0.0;
END_IF;
END_PROGRAM
