```iecst
(*
REASONING:
To meet IEC 62443 standards within an AB PLC environment, we must ensure that commands coming over the network (SCADA) are authenticated and authorized. 
We will implement:
1. Role-Based Access Control (RBAC): Checking an incoming token against required clearance levels.
2. Command Integrity: A simplified HMAC/Hash validation (simulated in ST) to ensure the command wasn't altered.
3. Hot-Standby Failover: A heartbeat and primary/secondary designation system. If the primary misses 3 heartbeats, the secondary takes control.
4. SCADA UDT: A structured data block mapping statuses, alarms, and timestamps (using GSV for system time).
*)

TYPE SCADA_Command_Type :
STRUCT
    TokenID : DINT;
    Cmd_Code : INT;
    Cmd_Arg : REAL;
    Signature : DINT; // Mock HMAC
END_STRUCT;
END_TYPE

TYPE SCADA_Telemetry_Type :
STRUCT
    System_State : INT;
    HPU_Pressure : REAL;
    Pile_Depth : REAL;
    Alarm_Word : DINT;
    Timestamp_Year : INT;
    Timestamp_Month : INT;
    Timestamp_Day : INT;
    Timestamp_Hour : INT;
    Timestamp_Min : INT;
    Timestamp_Sec : INT;
    Timestamp_Micro : DINT;
END_STRUCT;
END_TYPE

PROGRAM PileDriver_M3
VAR
    SCADA_Cmd : SCADA_Command_Type;
    SCADA_Tele : SCADA_Telemetry_Type;

    // Failover Variables
    Is_Primary : BOOL := TRUE;
    Partner_Heartbeat : DINT;
    Last_Partner_Heartbeat : DINT;
    Heartbeat_Timeout_Timer : TON;
    My_Heartbeat : DINT;
    Takeover_Active : BOOL;

    // Security
    Cmd_Valid : BOOL;
    Required_Token : DINT := 16#A1B2C3D4;

    // Time
    SystemTime : ARRAY[0..6] OF DINT;
END_VAR

// 1. Failover / Redundancy Logic
Heartbeat_Timeout_Timer(IN:=(Partner_Heartbeat = Last_Partner_Heartbeat), PT:=T#500ms);
IF Heartbeat_Timeout_Timer.Q AND NOT Is_Primary THEN
    Takeover_Active := TRUE;
    Is_Primary := TRUE;
END_IF;
Last_Partner_Heartbeat := Partner_Heartbeat;
My_Heartbeat := My_Heartbeat + 1;

// Only execute control if this PLC is Primary
IF Is_Primary THEN
    // 2. Security Validation (IEC 62443 concept)
    // Hash = (TokenID XOR Cmd_Code) + (Cmd_Arg * 100) (simplified mock)
    IF SCADA_Cmd.TokenID = Required_Token THEN
        IF SCADA_Cmd.Signature = ( (SCADA_Cmd.TokenID XOR SCADA_Cmd.Cmd_Code) + REAL_TO_DINT(SCADA_Cmd.Cmd_Arg * 100.0) ) THEN
            Cmd_Valid := TRUE;
        ELSE
            Cmd_Valid := FALSE;
        END_IF;
    ELSE
        Cmd_Valid := FALSE;
    END_IF;

    // Process Valid Commands
    IF Cmd_Valid THEN
        CASE SCADA_Cmd.Cmd_Code OF
            1: // Start
                SCADA_Tele.System_State := 1;
            2: // Stop
                SCADA_Tele.System_State := 0;
            3: // Set Target Depth
                // Set depth logic here
        END_CASE;
        // Clear command after processing
        SCADA_Cmd.Cmd_Code := 0; 
    END_IF;

    // 3. Process Control (Placeholder for Pile Driver logic)
    SCADA_Tele.HPU_Pressure := 210.5; // Simulated reading
    SCADA_Tele.Pile_Depth := SCADA_Tele.Pile_Depth + 0.01;

    // 4. Update SCADA Telemetry Timestamps (Mock GSV WallClockTime)
    // In actual Logix, use: GSV(WallClockTime, , DateTime, SystemTime[0]);
    SCADA_Tele.Timestamp_Year := DINT_TO_INT(SystemTime[0]);
    SCADA_Tele.Timestamp_Month := DINT_TO_INT(SystemTime[1]);
    SCADA_Tele.Timestamp_Day := DINT_TO_INT(SystemTime[2]);
    SCADA_Tele.Timestamp_Hour := DINT_TO_INT(SystemTime[3]);
    SCADA_Tele.Timestamp_Min := DINT_TO_INT(SystemTime[4]);
    SCADA_Tele.Timestamp_Sec := DINT_TO_INT(SystemTime[5]);
    SCADA_Tele.Timestamp_Micro := SystemTime[6];

ELSE
    // Secondary PLC mode: sync data from primary, do not drive outputs
    Takeover_Active := FALSE;
END_IF;
END_PROGRAM
```

```iecst
(*
ADVERSARIAL ROBUSTNESS & DIGITAL TWIN
This program adds a pre-operation self-test phase that intentionally injects false values to ensure the trip logic acts correctly. 
It also implements sensor drift detection by comparing the physical HPU pressure and Winch speed against a Digital Twin running on an edge device, synchronized via UDP.
*)

PROGRAM PileDriver_M4
VAR
    System_Mode : INT := 0; // 0=Boot, 1=SelfTest, 2=Ready, 3=Run, 4=Fault

    // Physical Sensors
    Sens_Pressure_Actual : REAL;
    Sens_Winch_Speed : REAL;

    // Digital Twin Data (via UDP)
    Twin_Pressure_Pred : REAL;
    Twin_Winch_Pred : REAL;
    Twin_Sync_Active : BOOL;

    // Sensor Drift Diagnostics
    Pressure_Drift : REAL;
    Winch_Drift : REAL;
    Drift_Fault : BOOL;
    Max_Allowed_Drift : REAL := 15.0; // % deviation

    // Self-Test Variables
    Test_Step : INT := 0;
    Test_Timer : TON;
    Simulated_Pressure : REAL;
    Trip_Success_Flag : BOOL;

    // Control Outputs
    HPU_Pump : BOOL;
    Winch_Ref : REAL;
END_VAR

CASE System_Mode OF
    0: // Boot
        System_Mode := 1;
        Test_Step := 0;

    1: // Self-Test Routine (Fault Injection)
        // Inject synthetic high pressure to test trip logic
        CASE Test_Step OF
            0: 
                Simulated_Pressure := 100.0; // Normal
                Test_Timer(IN:=TRUE, PT:=T#2s);
                IF Test_Timer.Q THEN
                    Test_Timer(IN:=FALSE);
                    Test_Step := 1;
                END_IF;
            1:
                Simulated_Pressure := 400.0; // Overpressure condition
                // Logic should set Trip_Success_Flag
                IF Trip_Success_Flag THEN
                    Simulated_Pressure := 100.0; // Reset
                    Test_Step := 2;
                END_IF;
            2:
                // Test complete
                System_Mode := 2; // Ready
        END_CASE;

        // Mock Trip Logic evaluation during self-test
        IF Simulated_Pressure > 350.0 THEN
            Trip_Success_Flag := TRUE;
            HPU_Pump := FALSE;
        END_IF;

    2: // Ready
        IF Twin_Sync_Active AND NOT Drift_Fault THEN
            // Wait for SCADA Start command
            // System_Mode := 3; 
        END_IF;

    3: // Run (Adversarial Monitoring Active)

        // 1. Digital Twin Drift Detection
        IF Sens_Pressure_Actual <> 0.0 THEN
            Pressure_Drift := ABS(Sens_Pressure_Actual - Twin_Pressure_Pred) / Sens_Pressure_Actual * 100.0;
        END_IF;

        IF Sens_Winch_Speed <> 0.0 THEN
            Winch_Drift := ABS(Sens_Winch_Speed - Twin_Winch_Pred) / ABS(Sens_Winch_Speed) * 100.0;
        END_IF;

        // 2. Drift Trip Logic
        IF (Pressure_Drift > Max_Allowed_Drift) OR (Winch_Drift > Max_Allowed_Drift) THEN
            Drift_Fault := TRUE;
            System_Mode := 4; // Fault
        END_IF;

        // 3. Normal Control
        IF NOT Drift_Fault THEN
            HPU_Pump := TRUE;
            Winch_Ref := 25.0;
        END_IF;

    4: // Fault
        HPU_Pump := FALSE;
        Winch_Ref := 0.0;
        // Wait for Reset
END_CASE;
END_PROGRAM
