FUNCTION_BLOCK FB_ContinuousMiner
TITLE = 'Continuous Miner Control'
VERSION : '1.0'
AUTHOR : 'Synthetic'

VAR_INPUT
    bStart : BOOL; // Start command
    bStop : BOOL; // Stop command
    rShearerTargetElevation : REAL; // Target elevation for shearer drum (mm)
    rConveyorTargetSpeed : REAL; // Target speed for conveyor tram (m/s)
    rShearerActualElevation : REAL; // Actual elevation (mm)
    rConveyorActualSpeed : REAL; // Actual speed (m/s)
END_VAR

VAR_OUTPUT
    rShearerLiftCmd : REAL; // Command to shearer lift hydraulics
    rConveyorSpeedCmd : REAL; // Command to conveyor drive
    bSystemRunning : BOOL; // System is active
END_VAR

VAR
    bActive : BOOL := FALSE;
    rElevationError : REAL;
    Kp_Elev : REAL := 0.5; // Proportional gain for elevation
END_VAR

BEGIN
    // Start/Stop Logic
    IF bStart AND NOT bStop THEN
        bActive := TRUE;
    ELSIF bStop THEN
        bActive := FALSE;
    END_IF;

    bSystemRunning := bActive;

    IF bActive THEN
        // Shearer Drum Elevation Control (Simple P-Controller)
        rElevationError := rShearerTargetElevation - rShearerActualElevation;
        rShearerLiftCmd := rElevationError * Kp_Elev;

        // Clamp lift command
        IF rShearerLiftCmd > 100.0 THEN rShearerLiftCmd := 100.0; END_IF;
        IF rShearerLiftCmd < -100.0 THEN rShearerLiftCmd := -100.0; END_IF;

        // Conveyor Tram Control (Direct speed reference)
        rConveyorSpeedCmd := rConveyorTargetSpeed;
    ELSE
        rShearerLiftCmd := 0.0;
        rConveyorSpeedCmd := 0.0;
    END_IF;

END_FUNCTION_BLOCK
