FUNCTION_BLOCK FB_CNC_Mill_Reasoning
VAR_INPUT
    Enable : BOOL;
    UserRole : INT;
    SessionToken : DINT;
    PartnerPLC_Heartbeat : BOOL;
END_VAR
VAR_OUTPUT
    OPC_UA_Data : "SCADA_Data";
    FailoverActive : BOOL;
    AccessDenied : BOOL;
END_VAR
VAR
    HeartbeatTimer : TON;
    IsPrimary : BOOL := TRUE;
END_VAR
BEGIN
    // IEC 62443 Role-based Access Control
    IF UserRole < 1 OR SessionToken = 0 THEN
        AccessDenied := TRUE;
        RETURN;
    ELSE
        AccessDenied := FALSE;
    END_IF;

    // Hardware Failover Logic
    HeartbeatTimer(IN := NOT PartnerPLC_Heartbeat, PT := t#500ms);
    IF HeartbeatTimer.Q THEN
        FailoverActive := TRUE;
        IsPrimary := TRUE;
    ELSE
        FailoverActive := FALSE;
    END_IF;

    IF IsPrimary THEN
        // SCADA OPC UA Publishing
        OPC_UA_Data.MachineState := 1; // Running
        OPC_UA_Data.SpindleTemp := 25.5;
        OPC_UA_Data.ActiveTool := 5;
        OPC_UA_Data.ActiveAlarms := 16#00000000;
    END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_CNC_Mill_Adversarial
VAR_INPUT
    StartSeq : BOOL;
    RawSensorValue : REAL;
    HIL_SimValue : REAL;
END_VAR
VAR_OUTPUT
    MachineReady : BOOL;
    SensorDriftDetected : BOOL;
    HIL_SyncError : BOOL;
    SelfTestState : INT;
END_VAR
VAR
    SensorHistory : ARRAY[0..9] OF REAL;
    HistoryIdx : INT := 0;
    MovingAvg : REAL;
    Sum : REAL;
    i : INT;
END_VAR
BEGIN
    // Sensor Drift Detection (Moving Average)
    SensorHistory[HistoryIdx] := RawSensorValue;
    HistoryIdx := (HistoryIdx + 1) MOD 10;
    Sum := 0.0;
    FOR i := 0 TO 9 DO
        Sum := Sum + SensorHistory[i];
    END_FOR;
    MovingAvg := Sum / 10.0;

    IF ABS(RawSensorValue - MovingAvg) > 5.0 THEN
        SensorDriftDetected := TRUE;
    ELSE
        SensorDriftDetected := FALSE;
    END_IF;

    // HIL Digital Twin Sync
    IF ABS(RawSensorValue - HIL_SimValue) > 2.0 THEN
        HIL_SyncError := TRUE;
    ELSE
        HIL_SyncError := FALSE;
    END_IF;

    // Pre-Flight Self-Test State Machine
    IF StartSeq AND SelfTestState = 0 THEN
        SelfTestState := 1;
    END_IF;

    CASE SelfTestState OF
        1: // Sim Chiller Failure
            SelfTestState := 2;
        2: // Sim Coolant Loss
            SelfTestState := 3;
        3: // Sim Profinet Loss
            SelfTestState := 4;
        4: // Verification Passed
            IF NOT SensorDriftDetected AND NOT HIL_SyncError THEN
                MachineReady := TRUE;
                SelfTestState := 5; // Ready
            END_IF;
    END_CASE;
END_FUNCTION_BLOCK

