    fTargetThrust       : LREAL := 50.0;
END_VAR

IF bEmergencyStop THEN
    eState := FAULT;
END_IF

CASE eState OF
    INIT:
        fBleedAirValve := 0.0;
        bTestRunning := FALSE;
        eState := IDLE;

    IDLE:
        IF bStartTest AND NOT bEmergencyStop THEN
            eState := TEST;
            bTestRunning := TRUE;
        END_IF

