        IF NOT bStartTest THEN
            eState := SHUTDOWN;
        END_IF

    SHUTDOWN:
        fBleedAirValve := 0.0;
        bTestRunning := FALSE;
        eState := IDLE;

    FAULT:
        fBleedAirValve := 100.0; // Fail-safe open
        bTestRunning := FALSE;
        IF NOT bEmergencyStop THEN
            eState := INIT;
        END_IF
END_CASE
