```pascal
PROGRAM PRG_TurbofanTest
VAR
    // Inputs
    fThrustLoadCell     AT %I* : LREAL;
    fEngineRPM          AT %I* : LREAL;
    bStartTest          AT %I* : BOOL;
    bEmergencyStop      AT %I* : BOOL;

    // Outputs
    fBleedAirValve      AT %Q* : LREAL;
    fVIGV_Position      AT %Q* : LREAL; // Variable Inlet Guide Vane position
    bTestRunning        AT %Q* : BOOL;

    // Internal
    eState              : (INIT, IDLE, RAMP, TEST, SHUTDOWN, FAULT);
    fTargetThrust       : LREAL := 50.0;
    fTargetRPM          : LREAL := 10000.0;

    // PID Controller for VIGV
    fbVIGV_PID          : FB_BasicPID;
END_VAR

IF bEmergencyStop THEN
    eState := FAULT;
END_IF

fbVIGV_PID(
    fSetpoint := fTargetRPM,
    fActualValue := fEngineRPM,
    bReset := (eState = INIT),
    fKp := 1.5, fTn := 0.5, fTv := 0.1,
    fControlOutput => fVIGV_Position
);

CASE eState OF
    INIT:
        fBleedAirValve := 0.0;
        bTestRunning := FALSE;
        eState := IDLE;

    IDLE:
        IF bStartTest AND NOT bEmergencyStop THEN
            eState := TEST;
            bTestRunning := TRUE;
        END_IF

    TEST:
        // VIGV PID control is continuously evaluated above
        // Bleed Air Valve management based on thrust
        IF fThrustLoadCell > fTargetThrust THEN
