// Rotor Lock Logic
IF bCmdLockRotor THEN bRotorLockActuator := TRUE; ELSIF bCmdUnlockRotor THEN bRotorLockActuator := FALSE; END_IF;

// Yaw Logic
IF bRotorUnlockedSensor THEN
    IF bCmdYawLeft THEN bYawMotorLeft := TRUE; bYawMotorRight := FALSE;
    ELSIF bCmdYawRight THEN bYawMotorRight := TRUE; bYawMotorLeft := FALSE;
    ELSE bYawMotorLeft := FALSE; bYawMotorRight := FALSE; END_IF;
END_IF

// Blade Pitch Control (P-Controller)
IF bPitchEnable THEN
    fPitchError := fPitchTargetAngle - fPitchCurrentAngle;
    fPitchMotorVelocity := fPitchError * fKpPitch;

    // Saturation
    IF fPitchMotorVelocity > fMaxPitchVelocity THEN
        fPitchMotorVelocity := fMaxPitchVelocity;
    ELSIF fPitchMotorVelocity < -fMaxPitchVelocity THEN
        fPitchMotorVelocity := -fMaxPitchVelocity;
    END_IF
ELSE
    fPitchMotorVelocity := 0.0;
END_IF

