// ============================================================
// FB: DiffusionFurnace_MultiZone
// Desc: 3-zone independent PID, gas manifold switching,
//       zone deviation alarms, cross-coupling compensation.
// IEC 61131-3 Siemens SCL (TIA Portal V17)
// ============================================================
FUNCTION_BLOCK DiffusionFurnace_MultiZone
VAR_INPUT
    Enable           : BOOL;
    SetpointTemp     : REAL;
    RampRate         : REAL;
    ActualTemp_Top   : REAL;
    ActualTemp_Ctr   : REAL;
    ActualTemp_Bot   : REAL;
    ProcessPhase     : INT;
    ZoneDevLimit     : REAL := 3.0;
END_VAR
VAR_OUTPUT
    Heater_Top       : REAL;
    Heater_Ctr       : REAL;
    Heater_Bot       : REAL;
    Valve_N2         : BOOL;
    Valve_O2         : BOOL;
    Valve_DCS        : BOOL;
    Valve_Exhaust    : BOOL;
    RampDone         : BOOL;
    ZoneDevAlarm     : BOOL;
    FaultActive      : BOOL;
END_VAR
VAR
    RampTarget       : REAL;
    RampIncrement    : REAL;
    Err_Top, Int_Top, Drv_Top, PrevErr_Top   : REAL;
    Err_Ctr, Int_Ctr, Drv_Ctr, PrevErr_Ctr  : REAL;
    Err_Bot, Int_Bot, Drv_Bot, PrevErr_Bot   : REAL;
    Kp_Z    : REAL := 2.8;
    Ki_Z    : REAL := 0.09;
    Kd_Z    : REAL := 0.45;
    Ts      : REAL := 0.1;
    CC_TC   : REAL := 0.05;
    CC_BC   : REAL := 0.05;
    AvgTemp  : REAL;
    Dev_Top  : REAL;
    Dev_Ctr  : REAL;
    Dev_Bot  : REAL;
    MaxDev   : REAL;
    TempHiLimit : REAL := 1200.0;
    TempLoLimit : REAL := 15.0;
END_VAR

IF (ActualTemp_Top > TempHiLimit) OR (ActualTemp_Ctr > TempHiLimit) OR
   (ActualTemp_Bot > TempHiLimit) OR
   (ActualTemp_Top < TempLoLimit) OR (ActualTemp_Ctr < TempLoLimit) OR
   (ActualTemp_Bot < TempLoLimit) THEN
    FaultActive   := TRUE;
    Heater_Top    := 0.0;  Heater_Ctr := 0.0;  Heater_Bot := 0.0;
    Valve_N2:=TRUE; Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=TRUE;
    RETURN;
END_IF;

FaultActive := FALSE;

IF NOT Enable THEN
    Heater_Top:=0.0; Heater_Ctr:=0.0; Heater_Bot:=0.0;
    Valve_N2:=FALSE; Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=FALSE;
    RETURN;
END_IF;

RampIncrement := RampRate / 600.0;
CASE ProcessPhase OF
    1:  IF RampTarget < SetpointTemp THEN
            RampTarget := RampTarget + RampIncrement;
            IF RampTarget > SetpointTemp THEN RampTarget := SetpointTemp; END_IF;
            RampDone := FALSE;
        ELSE  RampDone := TRUE;  END_IF;
    2:  RampTarget := SetpointTemp;  RampDone := TRUE;
    3:  IF RampTarget > 200.0 THEN
            RampTarget := RampTarget - RampIncrement;
        ELSE  RampTarget := 200.0;  RampDone := TRUE;  END_IF;
    4:  Heater_Top:=0.0; Heater_Ctr:=0.0; Heater_Bot:=0.0;
    ELSE: RampTarget:=ActualTemp_Ctr; RampDone:=FALSE;
END_CASE;

AvgTemp := (ActualTemp_Top + ActualTemp_Ctr + ActualTemp_Bot) / 3.0;
Dev_Top := ABS(ActualTemp_Top - AvgTemp);
Dev_Ctr := ABS(ActualTemp_Ctr - AvgTemp);
Dev_Bot := ABS(ActualTemp_Bot - AvgTemp);
MaxDev  := Dev_Top;
IF Dev_Ctr > MaxDev THEN MaxDev := Dev_Ctr; END_IF;
IF Dev_Bot > MaxDev THEN MaxDev := Dev_Bot; END_IF;
ZoneDevAlarm := (MaxDev > ZoneDevLimit);

VAR_TEMP
    SP_Top_Comp : REAL;
    SP_Ctr_Comp : REAL;
    SP_Bot_Comp : REAL;
END_VAR
SP_Top_Comp := RampTarget;
SP_Bot_Comp := RampTarget;
SP_Ctr_Comp := RampTarget
             - CC_TC * (ActualTemp_Top - RampTarget)
             - CC_BC * (ActualTemp_Bot - RampTarget);

IF ProcessPhase = 1 OR ProcessPhase = 2 OR ProcessPhase = 3 THEN
    Err_Top:=SP_Top_Comp-ActualTemp_Top; Int_Top:=Int_Top+Err_Top*Ts;
    Drv_Top:=(Err_Top-PrevErr_Top)/Ts; PrevErr_Top:=Err_Top;
    Heater_Top:=LIMIT(0.0,Kp_Z*Err_Top+Ki_Z*Int_Top+Kd_Z*Drv_Top,100.0);
    IF Heater_Top>=100.0 OR Heater_Top<=0.0 THEN Int_Top:=Int_Top-Err_Top*Ts; END_IF;

    Err_Ctr:=SP_Ctr_Comp-ActualTemp_Ctr; Int_Ctr:=Int_Ctr+Err_Ctr*Ts;
    Drv_Ctr:=(Err_Ctr-PrevErr_Ctr)/Ts; PrevErr_Ctr:=Err_Ctr;
    Heater_Ctr:=LIMIT(0.0,Kp_Z*Err_Ctr+Ki_Z*Int_Ctr+Kd_Z*Drv_Ctr,100.0);
    IF Heater_Ctr>=100.0 OR Heater_Ctr<=0.0 THEN Int_Ctr:=Int_Ctr-Err_Ctr*Ts; END_IF;

    Err_Bot:=SP_Bot_Comp-ActualTemp_Bot; Int_Bot:=Int_Bot+Err_Bot*Ts;
    Drv_Bot:=(Err_Bot-PrevErr_Bot)/Ts; PrevErr_Bot:=Err_Bot;
    Heater_Bot:=LIMIT(0.0,Kp_Z*Err_Bot+Ki_Z*Int_Bot+Kd_Z*Drv_Bot,100.0);
    IF Heater_Bot>=100.0 OR Heater_Bot<=0.0 THEN Int_Bot:=Int_Bot-Err_Bot*Ts; END_IF;
END_IF;

CASE ProcessPhase OF
    0:  Valve_N2:=FALSE; Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=FALSE;
    1:  Valve_N2:=TRUE;  Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=TRUE;
    2:  Valve_N2:=FALSE; Valve_O2:=TRUE;  Valve_DCS:=FALSE; Valve_Exhaust:=TRUE;
    3:  Valve_N2:=TRUE;  Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=TRUE;
    4:  Valve_N2:=TRUE;  Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=TRUE;
    ELSE: Valve_N2:=FALSE; Valve_O2:=FALSE; Valve_DCS:=FALSE; Valve_Exhaust:=FALSE;
END_CASE;

END_FUNCTION_BLOCK
