```scl
// ============================================================
// FB: DiffusionFurnace_Adversarial
// Desc: Full furnace + sensor drift detection (poly model),
//       HIL digital twin sync, and pre-start self-test FSM.
// IEC 61131-3 Siemens SCL (TIA Portal V17)
// ============================================================

TYPE DriftRecord
    STRUCT
        ZoneID       : INT;
        MeasuredTemp : REAL;
        ModelTemp    : REAL;
        DriftError   : REAL;   // MAD over window
        DriftFlag    : BOOL;
    END_STRUCT;
END_TYPE

TYPE SelfTestResult
    STRUCT
        TestID       : INT;
        TestName     : STRING[32];
        Passed       : BOOL;
        ActualValue  : REAL;
        ExpectedMin  : REAL;
        ExpectedMax  : REAL;
    END_STRUCT;
END_TYPE

TYPE HIL_SyncBlock
    STRUCT
        DT_Temp_Top,DT_Temp_Ctr,DT_Temp_Bot         : REAL;
        DT_Heater_Top,DT_Heater_Ctr,DT_Heater_Bot   : REAL;
        DT_ProcessPhase : INT;
        DT_RampTarget   : REAL;
        DT_FrameID      : DWORD;
        DT_SP_Feedback  : REAL;
        DT_DivergenceFlag : BOOL;
        DT_Timestamp    : REAL;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK DiffusionFurnace_Adversarial
VAR_INPUT
    Enable           : BOOL;
    DriftThreshold   : REAL := 5.0;
    ZoneDevLimit     : REAL := 3.0;
    PN_TempRaw_Top,PN_TempRaw_Ctr,PN_TempRaw_Bot : INT;
    PN_ValveFB_N2,PN_ValveFB_O2,PN_ValveFB_DCS,PN_ValveFB_Exh : BOOL;
    PN_CommStatus    : WORD;
    HIL_In           : HIL_SyncBlock;
    RunSelfTest      : BOOL;
    CmdPhase         : INT;
    CmdSetpoint      : REAL;
    CmdRampRate      : REAL;
    CmdValid         : BOOL;
END_VAR
VAR_OUTPUT
    PN_SCR_Top,PN_SCR_Ctr,PN_SCR_Bot : INT;
    PN_Valve_N2,PN_Valve_O2,PN_Valve_DCS,PN_Valve_Exh : BOOL;
    RampDone,ZoneDevAlarm,FaultActive : BOOL;
    ActiveFaultCode  : INT;
    Drift_T,Drift_C,Drift_B : DriftRecord;
    SensorDriftFault : BOOL;
    HIL_Out          : HIL_SyncBlock;
    SelfTestRunning  : BOOL;
    SelfTestPassed   : BOOL;
    SelfTestReport   : ARRAY[0..15] OF SelfTestResult;
    SelfTestCount    : INT;
END_VAR
VAR
    SetpointTemp : REAL := 900.0;
    RampRate     : REAL := 5.0;
    ProcessPhase : INT  := 0;
    ActTemp_T,ActTemp_C,ActTemp_B : REAL;
    RampTarget,RampIncrement : REAL;
    Err_T,Int_T,Drv_T,PErr_T : REAL;
    Err_C,Int_C,Drv_C,PErr_C : REAL;
    Err_B,Int_B,Drv_B,PErr_B : REAL;
    Kp:REAL:=2.8; Ki:REAL:=0.09; Kd:REAL:=0.45; Ts:REAL:=0.1;
    Out_T,Out_C,Out_B : REAL;
    AvgTemp,MaxDev : REAL;
    // Drift detection
    Drift_SumErr_T,Drift_SumErr_C,Drift_SumErr_B : REAL;
    Drift_SampleCnt : INT;
    DRIFT_WINDOW    : INT := 100;
    ModelTemp_T,ModelTemp_C,ModelTemp_B : REAL;
    PolyA0:REAL:=-1.5; PolyA1:REAL:=1.002; PolyA2:REAL:=0.000003;
    // HIL
    HIL_FrameCounter  : DWORD;
    HIL_DivergenceCnt : INT;  HIL_DIV_MAX : INT := 50;
    // Self-test FSM
    SelfTestState : INT := 0;
    ST_EdgePrev   : BOOL;
    ST_StepTimer  : INT;
    ST_AllPass    : BOOL;
    // Valves
    Cmd_N2,Cmd_O2,Cmd_DCS,Cmd_Exh : BOOL;
    TempHiLim : REAL := 1200.0;
END_VAR

// SECTION 0: Command application
IF CmdValid THEN
    ProcessPhase:=CmdPhase; SetpointTemp:=CmdSetpoint; RampRate:=CmdRampRate;
END_IF;

// SECTION 1: Profinet scaling and safety
ActTemp_T:=INT_TO_REAL(PN_TempRaw_Top)*1300.0/32767.0;
ActTemp_C:=INT_TO_REAL(PN_TempRaw_Ctr)*1300.0/32767.0;
ActTemp_B:=INT_TO_REAL(PN_TempRaw_Bot)*1300.0/32767.0;
FaultActive:=FALSE; ActiveFaultCode:=0;
IF PN_CommStatus<>0 THEN
    FaultActive:=TRUE; ActiveFaultCode:=1004;
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=TRUE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=TRUE; RETURN;
END_IF;
IF (ActTemp_T>TempHiLim) OR (ActTemp_C>TempHiLim) OR (ActTemp_B>TempHiLim) THEN
    FaultActive:=TRUE; ActiveFaultCode:=1000;
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=TRUE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=TRUE; RETURN;
END_IF;

// SECTION 2: Sensor drift detection (sliding window MAD vs polynomial model)
ModelTemp_T:=PolyA0+PolyA1*RampTarget+PolyA2*(RampTarget*RampTarget);
ModelTemp_C:=PolyA0+PolyA1*RampTarget+PolyA2*(RampTarget*RampTarget);
ModelTemp_B:=PolyA0+PolyA1*RampTarget+PolyA2*(RampTarget*RampTarget);
Drift_SumErr_T:=Drift_SumErr_T+ABS(ActTemp_T-ModelTemp_T);
Drift_SumErr_C:=Drift_SumErr_C+ABS(ActTemp_C-ModelTemp_C);
Drift_SumErr_B:=Drift_SumErr_B+ABS(ActTemp_B-ModelTemp_B);
Drift_SampleCnt:=Drift_SampleCnt+1;
IF Drift_SampleCnt>=DRIFT_WINDOW THEN
    Drift_T.ZoneID:=1; Drift_T.MeasuredTemp:=ActTemp_T; Drift_T.ModelTemp:=ModelTemp_T;
    Drift_T.DriftError:=Drift_SumErr_T/INT_TO_REAL(DRIFT_WINDOW);
    Drift_T.DriftFlag:=(Drift_T.DriftError>DriftThreshold);

    Drift_C.ZoneID:=2; Drift_C.MeasuredTemp:=ActTemp_C; Drift_C.ModelTemp:=ModelTemp_C;
    Drift_C.DriftError:=Drift_SumErr_C/INT_TO_REAL(DRIFT_WINDOW);
    Drift_C.DriftFlag:=(Drift_C.DriftError>DriftThreshold);

    Drift_B.ZoneID:=3; Drift_B.MeasuredTemp:=ActTemp_B; Drift_B.ModelTemp:=ModelTemp_B;
    Drift_B.DriftError:=Drift_SumErr_B/INT_TO_REAL(DRIFT_WINDOW);
    Drift_B.DriftFlag:=(Drift_B.DriftError>DriftThreshold);

    SensorDriftFault:=Drift_T.DriftFlag OR Drift_C.DriftFlag OR Drift_B.DriftFlag;
    IF SensorDriftFault THEN FaultActive:=TRUE; ActiveFaultCode:=2000; END_IF;
    Drift_SumErr_T:=0.0; Drift_SumErr_C:=0.0; Drift_SumErr_B:=0.0; Drift_SampleCnt:=0;
END_IF;

IF FaultActive THEN
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=TRUE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=TRUE; RETURN;
END_IF;
IF NOT Enable THEN
    PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    PN_Valve_N2:=FALSE; PN_Valve_O2:=FALSE; PN_Valve_DCS:=FALSE; PN_Valve_Exh:=FALSE; RETURN;
END_IF;

// SECTION 3: Self-test FSM
IF RunSelfTest AND NOT ST_EdgePrev THEN
    SelfTestState:=1; SelfTestRunning:=TRUE; SelfTestPassed:=FALSE;
    SelfTestCount:=0; ST_AllPass:=TRUE;
END_IF;
ST_EdgePrev:=RunSelfTest;

IF SelfTestRunning THEN
    ST_StepTimer:=ST_StepTimer+1;
    CASE SelfTestState OF
        1: // TC ambient range
            SelfTestReport[0].TestID:=1; SelfTestReport[0].TestName:='TC_Ambient_Range';
            SelfTestReport[0].ActualValue:=ActTemp_T;
            SelfTestReport[0].ExpectedMin:=15.0; SelfTestReport[0].ExpectedMax:=80.0;
            SelfTestReport[0].Passed:=(ActTemp_T>=15.0 AND ActTemp_T<=80.0);
            IF NOT SelfTestReport[0].Passed THEN ST_AllPass:=FALSE; END_IF;
            SelfTestState:=2;

        2: // N2 valve feedback
            PN_Valve_N2:=TRUE;
            IF ST_StepTimer>5 THEN
                SelfTestReport[1].TestID:=2; SelfTestReport[1].TestName:='N2_Valve_Feedback';
                SelfTestReport[1].Passed:=(PN_ValveFB_N2=TRUE);
                SelfTestReport[1].ActualValue:=BOOL_TO_REAL(PN_ValveFB_N2);
                SelfTestReport[1].ExpectedMin:=1.0; SelfTestReport[1].ExpectedMax:=1.0;
                IF NOT SelfTestReport[1].Passed THEN ST_AllPass:=FALSE; END_IF;
                PN_Valve_N2:=FALSE; ST_StepTimer:=0; SelfTestState:=3;
            END_IF;

        3: // Exhaust valve feedback
            PN_Valve_Exh:=TRUE;
            IF ST_StepTimer>5 THEN
                SelfTestReport[2].TestID:=3; SelfTestReport[2].TestName:='Exhaust_Valve_FB';
                SelfTestReport[2].Passed:=(PN_ValveFB_Exh=TRUE);
                SelfTestReport[2].ActualValue:=BOOL_TO_REAL(PN_ValveFB_Exh);
                SelfTestReport[2].ExpectedMin:=1.0; SelfTestReport[2].ExpectedMax:=1.0;
                IF NOT SelfTestReport[2].Passed THEN ST_AllPass:=FALSE; END_IF;
                PN_Valve_Exh:=FALSE; ST_StepTimer:=0; SelfTestState:=4;
            END_IF;

        4: // Profinet status
            SelfTestReport[3].TestID:=4; SelfTestReport[3].TestName:='Profinet_CommStatus';
            SelfTestReport[3].Passed:=(PN_CommStatus=0);
            SelfTestReport[3].ActualValue:=INT_TO_REAL(WORD_TO_INT(PN_CommStatus));
            SelfTestReport[3].ExpectedMin:=0.0; SelfTestReport[3].ExpectedMax:=0.0;
            IF NOT SelfTestReport[3].Passed THEN ST_AllPass:=FALSE; END_IF;
            SelfTestState:=5;

        5: // HIL divergence clear
            SelfTestReport[4].TestID:=5; SelfTestReport[4].TestName:='HIL_DT_NoDivergence';
            SelfTestReport[4].Passed:=(NOT HIL_In.DT_DivergenceFlag);
            SelfTestReport[4].ActualValue:=BOOL_TO_REAL(HIL_In.DT_DivergenceFlag);
            SelfTestReport[4].ExpectedMin:=0.0; SelfTestReport[4].ExpectedMax:=0.0;
            IF NOT SelfTestReport[4].Passed THEN ST_AllPass:=FALSE; END_IF;
            SelfTestCount:=5; SelfTestState:=99;

        99: // Complete
            SelfTestPassed:=ST_AllPass;
            SelfTestRunning:=FALSE; SelfTestState:=0; ST_StepTimer:=0;
    END_CASE;
    RETURN;  // Block process during self-test
END_IF;

// SECTION 4: Ramp + 3-zone PID
RampIncrement:=RampRate/600.0;
CASE ProcessPhase OF
    1:  RampTarget:=LIMIT(0.0,RampTarget+RampIncrement,SetpointTemp);
        RampDone:=(RampTarget>=SetpointTemp);
    2:  RampTarget:=SetpointTemp; RampDone:=TRUE;
    3:  RampTarget:=LIMIT(200.0,RampTarget-RampIncrement,1200.0);
        RampDone:=(RampTarget<=200.0);
    4:  PN_SCR_Top:=0; PN_SCR_Ctr:=0; PN_SCR_Bot:=0;
    ELSE: RampTarget:=ActTemp_C; RampDone:=FALSE;
END_CASE;

AvgTemp:=(ActTemp_T+ActTemp_C+ActTemp_B)/3.0;
MaxDev:=MAX(ABS(ActTemp_T-AvgTemp),MAX(ABS(ActTemp_C-AvgTemp),ABS(ActTemp_B-AvgTemp)));
ZoneDevAlarm:=MaxDev>ZoneDevLimit;

IF ProcessPhase>=1 AND ProcessPhase<=3 THEN
    Err_T:=RampTarget-ActTemp_T; Int_T:=Int_T+Err_T*Ts;
    Drv_T:=(Err_T-PErr_T)/Ts; PErr_T:=Err_T;
    Out_T:=LIMIT(0.0,Kp*Err_T+Ki*Int_T+Kd*Drv_T,100.0);
    IF Out_T>=100.0 OR Out_T<=0.0 THEN Int_T:=Int_T-Err_T*Ts; END_IF;
    Err_C:=RampTarget-ActTemp_C; Int_C:=Int_C+Err_C*Ts;
    Drv_C:=(Err_C-PErr_C)/Ts; PErr_C:=Err_C;
    Out_C:=LIMIT(0.0,Kp*Err_C+Ki*Int_C+Kd*Drv_C,100.0);
    IF Out_C>=100.0 OR Out_C<=0.0 THEN Int_C:=Int_C-Err_C*Ts; END_IF;
    Err_B:=RampTarget-ActTemp_B; Int_B:=Int_B+Err_B*Ts;
    Drv_B:=(Err_B-PErr_B)/Ts; PErr_B:=Err_B;
    Out_B:=LIMIT(0.0,Kp*Err_B+Ki*Int_B+Kd*Drv_B,100.0);
    IF Out_B>=100.0 OR Out_B<=0.0 THEN Int_B:=Int_B-Err_B*Ts; END_IF;
    PN_SCR_Top:=REAL_TO_INT(Out_T*327.67);
    PN_SCR_Ctr:=REAL_TO_INT(Out_C*327.67);
    PN_SCR_Bot:=REAL_TO_INT(Out_B*327.67);
END_IF;

// SECTION 5: Gas manifold
CASE ProcessPhase OF
    0:  Cmd_N2:=FALSE; Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=FALSE;
    1:  Cmd_N2:=TRUE;  Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    2:  Cmd_N2:=FALSE; Cmd_O2:=TRUE;  Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    3:  Cmd_N2:=TRUE;  Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    4:  Cmd_N2:=TRUE;  Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=TRUE;
    ELSE: Cmd_N2:=FALSE; Cmd_O2:=FALSE; Cmd_DCS:=FALSE; Cmd_Exh:=FALSE;
END_CASE;
PN_Valve_N2:=Cmd_N2; PN_Valve_O2:=Cmd_O2; PN_Valve_DCS:=Cmd_DCS; PN_Valve_Exh:=Cmd_Exh;

// SECTION 6: HIL digital twin synchronization
HIL_FrameCounter:=HIL_FrameCounter+1;
HIL_Out.DT_Temp_Top:=ActTemp_T; HIL_Out.DT_Temp_Ctr:=ActTemp_C; HIL_Out.DT_Temp_Bot:=ActTemp_B;
HIL_Out.DT_Heater_Top:=Out_T; HIL_Out.DT_Heater_Ctr:=Out_C; HIL_Out.DT_Heater_Bot:=Out_B;
HIL_Out.DT_ProcessPhase:=ProcessPhase;
HIL_Out.DT_RampTarget:=RampTarget;
HIL_Out.DT_FrameID:=HIL_FrameCounter;

IF HIL_In.DT_DivergenceFlag THEN
    HIL_DivergenceCnt:=HIL_DivergenceCnt+1;
    IF HIL_DivergenceCnt>=HIL_DIV_MAX THEN
        FaultActive:=TRUE; ActiveFaultCode:=3000;  // HIL sustained divergence
        HIL_DivergenceCnt:=0;
    END_IF;
ELSE
    HIL_DivergenceCnt:=0;
END_IF;

IF ABS(HIL_In.DT_SP_Feedback-SetpointTemp)>10.0 THEN
    ActiveFaultCode:=3001;  // HIL setpoint mismatch warning
END_IF;

END_FUNCTION_BLOCK
