PROGRAM PRG_IonImplanter_Base
VAR
    // IO Variables
    fBeamCurrent AT %I* : REAL; // µA
    bImplantEnable AT %I* : BOOL;
    fStageX_Cmd AT %Q* : LREAL;
    fStageY_Cmd AT %Q* : LREAL;

    // Dosimetry
    fTargetDose : LREAL := 1.0E15;
    fAccumulatedDose : LREAL := 0.0;
    fCycleTime : LREAL := 0.01; // 10ms cycle
    bImplantComplete : BOOL;

    // Stage control
    fScanSpeed : LREAL := 10.0;
END_VAR

// Dosimetry Integration
IF bImplantEnable AND NOT bImplantComplete THEN
    fAccumulatedDose := fAccumulatedDose + (fBeamCurrent * fCycleTime);
    IF fAccumulatedDose >= fTargetDose THEN
        bImplantComplete := TRUE;
    END_IF

    // Stage Scanning
    fStageX_Cmd := fStageX_Cmd + (fScanSpeed * fCycleTime);
    IF fStageX_Cmd > 300.0 THEN
        fStageX_Cmd := 0;
        fStageY_Cmd := fStageY_Cmd + 5.0;
    END_IF
ELSE
    IF NOT bImplantEnable THEN
        bImplantComplete := FALSE;
        fAccumulatedDose := 0.0;
    END_IF
END_IF
