PROGRAM PRG_IonImplanter_M3
VAR
    // Redundancy
    bIsPrimaryPLC : BOOL;
    bHeartbeatFromPeer AT %I* : BOOL;
    tHeartbeatTimer : TON;
    bPeerLost : BOOL;

    // SCADA
    {attribute 'OPC.UA.DA' := '1'}
    stScada : ST_SCADA_Data;

    // Security
    bParamsValid : BOOL;
    fTargetDoseSecure : LREAL;
END_VAR

// Failover
tHeartbeatTimer(IN := NOT bHeartbeatFromPeer, PT := T#500MS);
IF tHeartbeatTimer.Q THEN
    bPeerLost := TRUE;
    IF NOT bIsPrimaryPLC THEN bIsPrimaryPLC := TRUE; END_IF
ELSE
    bPeerLost := FALSE;
END_IF

IF bIsPrimaryPLC THEN
    // IEC 62443 RBAC
    IF stScada.bStartCommand THEN
        IF stScada.nUserLevel >= 1 THEN // Operator
            IF stScada.fTargetDose > 1.0E12 AND stScada.fTargetDose < 1.0E17 THEN
                fTargetDoseSecure := stScada.fTargetDose;
                bParamsValid := TRUE;
            ELSE
                bParamsValid := FALSE; // bounds check failed
            END_IF
        ELSE
            bParamsValid := FALSE; // auth failed
            END_IF
    END_IF

    IF bParamsValid AND NOT bPeerLost THEN
        // Implant logic
        stScada.fCurrentDose := stScada.fCurrentDose + 1.0E10;
    END_IF
END_IF
