TYPE E_SysMode : (MODE_IDLE, MODE_SELF_TEST, MODE_IMPLANT, MODE_FAULT); END_TYPE

PROGRAM PRG_IonImplanter_M4
VAR
    eMode : E_SysMode := MODE_IDLE;

    // Drift Detection
    fBeamCurrent : REAL;
    aHistory : ARRAY[1..10] OF REAL;
    nIdx : INT := 1;
    fMovingAvg : REAL;
    bDriftDetected : BOOL;

    // HIL Digital Twin
    fModelStageX : LREAL;
    fActualStageX AT %I* : LREAL;
    bTwinMismatch : BOOL;

    // Self Test
    bSelfTestPassed : BOOL;
    nTestStep : INT;
    tTimer : TON;
    bStartCmd : BOOL;
END_VAR

// Sensor Drift
aHistory[nIdx] := fBeamCurrent;
nIdx := nIdx + 1; IF nIdx > 10 THEN nIdx := 1; END_IF
fMovingAvg := 0.0;
FOR i:=1 TO 10 DO fMovingAvg := fMovingAvg + aHistory[i]; END_FOR
fMovingAvg := fMovingAvg / 10.0;
IF ABS(fBeamCurrent - fMovingAvg) > 5.0 THEN bDriftDetected := TRUE; END_IF

// HIL Sync
fModelStageX := fModelStageX + 0.1;
IF ABS(fModelStageX - fActualStageX) > 2.0 THEN bTwinMismatch := TRUE; END_IF

IF bDriftDetected OR bTwinMismatch THEN eMode := MODE_FAULT; END_IF

CASE eMode OF
    MODE_IDLE:
        IF bStartCmd AND NOT bSelfTestPassed THEN eMode := MODE_SELF_TEST; nTestStep := 1; END_IF
    MODE_SELF_TEST:
        tTimer(IN:=TRUE, PT:=T#1S);
        CASE nTestStep OF
            1: IF tTimer.Q THEN nTestStep := 2; tTimer(IN:=FALSE); END_IF
            2: IF tTimer.Q THEN bSelfTestPassed := TRUE; eMode := MODE_IDLE; tTimer(IN:=FALSE); END_IF
        END_CASE
    MODE_IMPLANT:
        // Control logic
    MODE_FAULT:
        bSelfTestPassed := FALSE;
END_CASE
