```pascal
(* ============================================================
   CVD CHAMBER CONTROL — MUTATION 2 (Add Breadth)
   Platform : Allen-Bradley ControlLogix / Studio 5000
   Standard : IEC 61131-3 Structured Text
   Rev      : 3.0
   Added    : Ethernet/IP MSG comms to supervisory PLC,
              Fault Diagnostic subsystem (fault codes +
              ring-buffer fault log), remote SP updates
   ============================================================ *)

(* ---------- USER-DEFINED TYPES ---------- *)
TYPE
  eProcState : (
    ST_IDLE, ST_PURGE, ST_HEAT_RAMP, ST_RAMP_FLOW,
    ST_DEPOSIT, ST_INTER_PURGE, ST_VENT, ST_FAULT
  );

  tRecipeLayer : STRUCT
    rFlowSP    : REAL;
    rPressSP   : REAL;
    rTempSP    : REAL;
    tDuration  : TIME;
  END_STRUCT;

  tFaultRecord : STRUCT
    iCode      : INT;
    sDesc      : STRING[64];
    dtStamp    : DATE_AND_TIME;
    eState     : eProcState;
  END_STRUCT;

  tEIPStatus : STRUCT
    bConnected : BOOL;
    iRetryCount: INT;
    iLastError : INT;
  END_STRUCT;
END_TYPE

VAR CONSTANT
  MAX_LAYERS    : INT := 8;
  FAULT_LOG_SZ  : INT := 32;
  (* Fault codes *)
  FC_NONE       : INT := 0;
  FC_OVERTEMP   : INT := 101;
  FC_FLOW_HIGH  : INT := 102;
  FC_PRESS_HIGH : INT := 103;
  FC_EMG_STOP   : INT := 104;
  FC_EIP_LOSS   : INT := 105;
  FC_HEAT_WATCHDOG : INT := 106;
  FC_MSG_TIMEOUT   : INT := 107;
END_VAR

VAR
  (* --- State & Recipe --- *)
  eState           : eProcState := ST_IDLE;
  aRecipe          : ARRAY [0..7] OF tRecipeLayer;
  iLayerIdx        : INT := 0;
  iTotalLayers     : INT := 3;

  (* --- Process Variables & Setpoints --- *)
  rFlowPV, rFlowSP_Active   : REAL;
  rPressPV, rPressSP_Active : REAL;
  rTempPV, rTempSP_Active   : REAL;

  (* --- PID Function Blocks --- *)
  fbFlowPID, fbPressPID, fbTempPID : PIDE;
  rMFC_CV, rThrottle_CV, rHeater_CV : REAL;

  rFlow_KP : REAL := 1.2;  rFlow_KI : REAL := 0.5;  rFlow_KD : REAL := 0.05;
  rPress_KP: REAL := 2.0;  rPress_KI: REAL := 0.8;  rPress_KD: REAL := 0.10;
  rTemp_KP : REAL := 3.5;  rTemp_KI : REAL := 0.1;  rTemp_KD : REAL := 0.2;

  (* --- Heater protection --- *)
  rTempMaxLimit    : REAL := 700.0;
  bOverTempLatch   : BOOL := FALSE;
  bHeaterEnable    : BOOL := FALSE;

  (* --- Timers --- *)
  tPurge, tHeatRamp, tDeposit, tInterPurge : TON;

  (* --- Interlocks --- *)
  bEmgStop         : BOOL := FALSE;

  (* --- Fault Subsystem --- *)
  aFaultLog        : ARRAY [0..31] OF tFaultRecord;
  iFaultHead       : INT := 0;   (* ring-buffer write pointer *)
  iFaultCount      : INT := 0;
  iActiveFaultCode : INT := FC_NONE;
  bFaultAck        : BOOL := FALSE;  (* operator acknowledgement *)

  (* --- Ethernet/IP MSG Blocks --- *)
  msgSendStatus    : MESSAGE;   (* send PV/state to supervisor *)
  msgRecvSP        : MESSAGE;   (* receive new SP from supervisor *)
  stEIP            : tEIPStatus;
  tMsgSendTimer    : TON;       (* send heartbeat every 500 ms *)
  tMsgTimeout      : TON;       (* watchdog on recv MSG *)

  (* Remote SP buffer (filled by msgRecvSP) *)
  rRemoteFlowSP    : REAL := 0.0;
  rRemotePressSP   : REAL := 0.0;
  rRemoteTempSP    : REAL := 0.0;
  bRemoteSPValid   : BOOL := FALSE;

  (* Scratch *)
  rMaxFlow         : REAL := 200.0;
  rMaxPress        : REAL := 10.0;
END_VAR

(* ============================================================
   ACTION: Log a fault into the ring buffer
   ============================================================ *)
ACTION LogFault:
  (* Parameters passed via iActiveFaultCode and sDesc local var *)
  aFaultLog[iFaultHead].iCode   := iActiveFaultCode;
  aFaultLog[iFaultHead].dtStamp := DT#2024-01-01-00:00:00;  (* replace with system DT call *)
  aFaultLog[iFaultHead].eState  := eState;
  iFaultHead := (iFaultHead + 1) MOD FAULT_LOG_SZ;
  IF iFaultCount < FAULT_LOG_SZ THEN
    iFaultCount := iFaultCount + 1;
  END_IF;
END_ACTION

(* ============================================================
   ACTION: Ethernet/IP — Send status heartbeat to supervisor
   ============================================================ *)
ACTION EIP_SendStatus:
  tMsgSendTimer(IN := TRUE, PT := T#500MS);
  IF tMsgSendTimer.Q THEN
    tMsgSendTimer(IN := FALSE);
    IF NOT msgSendStatus.EN THEN
      (* Configure CIP Generic MSG — write to supervisor tag *)
      msgSendStatus.MessageType      := MESSAGE_CIP_GENERIC;
      msgSendStatus.RequestedLength  := 12;  (* 3 × REAL = 12 bytes *)
      msgSendStatus.CommTypeCode     := CIP_CONNECTED;
      (* Source: internal tag mapped to MSG source element *)
      (* Target: supervisory PLC CIP path e.g. '192.168.1.10,1,0' *)
      msgSendStatus.EN := TRUE;
    END_IF;
    IF msgSendStatus.ER THEN
      stEIP.bConnected  := FALSE;
      stEIP.iLastError  := msgSendStatus.ERR;
      stEIP.iRetryCount := stEIP.iRetryCount + 1;
      IF stEIP.iRetryCount > 5 THEN
        iActiveFaultCode := FC_EIP_LOSS;
        LogFault();
        eState := ST_FAULT;
      END_IF;
    ELSIF msgSendStatus.DN THEN
      stEIP.bConnected  := TRUE;
      stEIP.iRetryCount := 0;
    END_IF;
  END_IF;
END_ACTION

(* ============================================================
   ACTION: Ethernet/IP — Receive new setpoints from supervisor
   ============================================================ *)
ACTION EIP_RecvSetpoints:
  IF NOT msgRecvSP.EN THEN
    msgRecvSP.MessageType     := MESSAGE_CIP_GENERIC;
    msgRecvSP.RequestedLength := 12;
    msgRecvSP.CommTypeCode    := CIP_CONNECTED;
    msgRecvSP.EN := TRUE;
  END_IF;

  tMsgTimeout(IN := msgRecvSP.EN, PT := T#3S);
  IF tMsgTimeout.Q THEN
    iActiveFaultCode := FC_MSG_TIMEOUT;
    LogFault();
    msgRecvSP.EN := FALSE;
    tMsgTimeout(IN := FALSE);
  END_IF;

  IF msgRecvSP.DN THEN
    bRemoteSPValid   := TRUE;
    (* Values populated in msgRecvSP destination tag mapped to rRemote* *)
    aRecipe[iLayerIdx].rFlowSP  := rRemoteFlowSP;
    aRecipe[iLayerIdx].rPressSP := rRemotePressSP;
    aRecipe[iLayerIdx].rTempSP  := rRemoteTempSP;
    msgRecvSP.EN := FALSE;
  END_IF;
END_ACTION

(* ============================================================
   ACTION: Heater control with over-temp protection
   ============================================================ *)
ACTION HeaterControl:
  IF rTempPV >= rTempMaxLimit THEN
    bOverTempLatch := TRUE;
  END_IF;
  IF bOverTempLatch THEN
    bHeaterEnable := FALSE;
    rHeater_CV    := 0.0;
    fbTempPID.EnableIn := FALSE;
    iActiveFaultCode := FC_OVERTEMP;
    LogFault();
    eState := ST_FAULT;
    RETURN;
  END_IF;
  IF bHeaterEnable THEN
    fbTempPID.SP       := rTempSP_Active;
    fbTempPID.PV       := rTempPV;
    fbTempPID.Kp       := rTemp_KP;
    fbTempPID.Ki       := rTemp_KI;
    fbTempPID.Kd       := rTemp_KD;
    fbTempPID.EnableIn := TRUE;
    fbTempPID.CVEU_HI  := 100.0;
    fbTempPID.CVEU_LO  := 0.0;
    fbTempPID();
    rHeater_CV := fbTempPID.CV;
  ELSE
    fbTempPID.EnableIn := FALSE;
    rHeater_CV := 0.0;
  END_IF;
END_ACTION

(* ============================================================
   ACTION: Load recipe layer
   ============================================================ *)
ACTION LoadLayer:
  IF iLayerIdx < iTotalLayers THEN
    fbFlowPID.SP   := aRecipe[iLayerIdx].rFlowSP;
    fbPressPID.SP  := aRecipe[iLayerIdx].rPressSP;
    rTempSP_Active := aRecipe[iLayerIdx].rTempSP;
  END_IF;
END_ACTION

(* ============================================================
   MAIN SCAN
   ============================================================ *)

EIP_SendStatus();
EIP_RecvSetpoints();
HeaterControl();

IF bEmgStop THEN
  iActiveFaultCode := FC_EMG_STOP;
  LogFault();
  eState := ST_FAULT;
END_IF;

IF rFlowPV > rMaxFlow THEN
  iActiveFaultCode := FC_FLOW_HIGH;
  LogFault();
  eState := ST_FAULT;
END_IF;

IF rPressPV > rMaxPress THEN
  iActiveFaultCode := FC_PRESS_HIGH;
  LogFault();
  eState := ST_FAULT;
END_IF;

IF bFaultAck AND (eState = ST_FAULT) AND (iActiveFaultCode <> FC_OVERTEMP) THEN
  bOverTempLatch   := FALSE;
  iActiveFaultCode := FC_NONE;
  eState           := ST_IDLE;
  bFaultAck        := FALSE;
END_IF;

CASE eState OF
  ST_IDLE:
    bHeaterEnable := FALSE;
    fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
    rMFC_CV := 0.0; rThrottle_CV := 0.0;
    iLayerIdx := 0;

  ST_PURGE:
    rMFC_CV := 0.0; rThrottle_CV := 50.0;
    tPurge(IN := TRUE, PT := T#60S);
    IF tPurge.Q THEN
      tPurge(IN := FALSE);
      bHeaterEnable := TRUE;
      LoadLayer();
      eState := ST_HEAT_RAMP;
    END_IF;

  ST_HEAT_RAMP:
    IF ABS(rTempPV - rTempSP_Active) <= 2.0 THEN
      tHeatRamp(IN := FALSE);
      eState := ST_RAMP_FLOW;
    END_IF;
    tHeatRamp(IN := TRUE, PT := T#1800S);
    IF tHeatRamp.Q THEN
      iActiveFaultCode := FC_HEAT_WATCHDOG;
      LogFault();
      eState := ST_FAULT;
    END_IF;

  ST_RAMP_FLOW:
    rMFC_CV := rMFC_CV + 1.0;
    IF rMFC_CV > 100.0 THEN rMFC_CV := 100.0; END_IF;
    IF rFlowPV >= (aRecipe[iLayerIdx].rFlowSP * 0.95) THEN
      eState := ST_DEPOSIT;
    END_IF;

  ST_DEPOSIT:
    fbFlowPID.PV := rFlowPV; fbFlowPID.Kp := rFlow_KP;
    fbFlowPID.Ki := rFlow_KI; fbFlowPID.Kd := rFlow_KD;
    fbFlowPID.EnableIn := TRUE; fbFlowPID.CVEU_HI := 100.0; fbFlowPID.CVEU_LO := 0.0;
    fbFlowPID(); rMFC_CV := fbFlowPID.CV;

    fbPressPID.PV := rPressPV; fbPressPID.Kp := rPress_KP;
    fbPressPID.Ki := rPress_KI; fbPressPID.Kd := rPress_KD;
    fbPressPID.EnableIn := TRUE; fbPressPID.CVEU_HI := 100.0; fbPressPID.CVEU_LO := 0.0;
    fbPressPID(); rThrottle_CV := fbPressPID.CV;

    tDeposit(IN := TRUE, PT := aRecipe[iLayerIdx].tDuration);
    IF tDeposit.Q THEN
      tDeposit(IN := FALSE);
      fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
      iLayerIdx := iLayerIdx + 1;
      IF iLayerIdx < iTotalLayers THEN eState := ST_INTER_PURGE;
      ELSE eState := ST_VENT; END_IF;
    END_IF;

  ST_INTER_PURGE:
    rMFC_CV := 0.0; rThrottle_CV := 50.0;
    tInterPurge(IN := TRUE, PT := T#30S);
    IF tInterPurge.Q THEN
      tInterPurge(IN := FALSE);
      LoadLayer();
      eState := ST_HEAT_RAMP;
    END_IF;

  ST_VENT:
    bHeaterEnable := FALSE; fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
    rMFC_CV := 0.0; rThrottle_CV := 100.0;
    IF rPressPV < 0.01 THEN eState := ST_IDLE; END_IF;

  ST_FAULT:
    bHeaterEnable := FALSE; fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
    rMFC_CV := 0.0; rThrottle_CV := 0.0; rHeater_CV := 0.0;

END_CASE;
