  (* Scratch *)
  i                : INT;
  j                : INT;
  rSum, rSumSq, rDiff : REAL;
END_VAR

(* ============================================================
   ACTION: Update drift detector rolling window and compute stats
   ============================================================ *)
ACTION DriftDetect_Update:
  (* Called per sensor. Inputs: stDrift (ref), rNewSample *)
  (* Implementation shown for Flow; Press and Temp identical *)

  (* Flow *)
  stDriftFlow.aWindow[stDriftFlow.iHead] := rFlowPV_Raw;
  stDriftFlow.iHead := (stDriftFlow.iHead + 1) MOD DRIFT_WIN;
  rSum := 0.0;
  FOR j := 0 TO DRIFT_WIN - 1 DO rSum := rSum + stDriftFlow.aWindow[j]; END_FOR;
  stDriftFlow.rMean := rSum / INT_TO_REAL(DRIFT_WIN);
  rSumSq := 0.0;
  FOR j := 0 TO DRIFT_WIN - 1 DO
    rDiff := stDriftFlow.aWindow[j] - stDriftFlow.rMean;
    rSumSq := rSumSq + (rDiff * rDiff);
  END_FOR;
  stDriftFlow.rVariance := rSumSq / INT_TO_REAL(DRIFT_WIN);
  stDriftFlow.rStdDev   := SQRT(stDriftFlow.rVariance);
  IF stDriftFlow.rStdDev > 0.0 THEN
    stDriftFlow.rZScore := ABS(rFlowPV_Raw - stDriftFlow.rMean) / stDriftFlow.rStdDev;
  ELSE
    stDriftFlow.rZScore := 0.0;
  END_IF;
  stDriftFlow.bDriftFlag := (stDriftFlow.rZScore > stDriftFlow.rDriftThresh);
  IF stDriftFlow.bDriftFlag THEN
    iActiveFaultCode := FC_DRIFT_FLOW; LogFault();
    (* Use last-known-good mean as substitute PV *)
    rFlowPV := stDriftFlow.rMean;
  ELSE
    rFlowPV := rFlowPV_Raw;
  END_IF;

  (* Pressure *)
  stDriftPress.aWindow[stDriftPress.iHead] := rPressPV_Raw;
  stDriftPress.iHead := (stDriftPress.iHead + 1) MOD DRIFT_WIN;
  rSum := 0.0;
  FOR j := 0 TO DRIFT_WIN - 1 DO rSum := rSum + stDriftPress.aWindow[j]; END_FOR;
  stDriftPress.rMean := rSum / INT_TO_REAL(DRIFT_WIN);
  rSumSq := 0.0;
  FOR j := 0 TO DRIFT_WIN - 1 DO
    rDiff := stDriftPress.aWindow[j] - stDriftPress.rMean;
    rSumSq := rSumSq + (rDiff * rDiff);
  END_FOR;
  stDriftPress.rVariance := rSumSq / INT_TO_REAL(DRIFT_WIN);
  stDriftPress.rStdDev   := SQRT(stDriftPress.rVariance);
  IF stDriftPress.rStdDev > 0.0 THEN
    stDriftPress.rZScore := ABS(rPressPV_Raw - stDriftPress.rMean) / stDriftPress.rStdDev;
  ELSE stDriftPress.rZScore := 0.0; END_IF;
  stDriftPress.bDriftFlag := (stDriftPress.rZScore > stDriftPress.rDriftThresh);
  IF stDriftPress.bDriftFlag THEN
    iActiveFaultCode := FC_DRIFT_PRESS; LogFault();
    rPressPV := stDriftPress.rMean;
  ELSE rPressPV := rPressPV_Raw; END_IF;

  (* Temperature *)
  stDriftTemp.aWindow[stDriftTemp.iHead] := rTempPV_Raw;
  stDriftTemp.iHead := (stDriftTemp.iHead + 1) MOD DRIFT_WIN;
  rSum := 0.0;
  FOR j := 0 TO DRIFT_WIN - 1 DO rSum := rSum + stDriftTemp.aWindow[j]; END_FOR;
  stDriftTemp.rMean := rSum / INT_TO_REAL(DRIFT_WIN);
  rSumSq := 0.0;
  FOR j := 0 TO DRIFT_WIN - 1 DO
    rDiff := stDriftTemp.aWindow[j] - stDriftTemp.rMean;
    rSumSq := rSumSq + (rDiff * rDiff);
  END_FOR;
  stDriftTemp.rVariance := rSumSq / INT_TO_REAL(DRIFT_WIN);
  stDriftTemp.rStdDev   := SQRT(stDriftTemp.rVariance);
  IF stDriftTemp.rStdDev > 0.0 THEN
    stDriftTemp.rZScore := ABS(rTempPV_Raw - stDriftTemp.rMean) / stDriftTemp.rStdDev;
  ELSE stDriftTemp.rZScore := 0.0; END_IF;
  stDriftTemp.bDriftFlag := (stDriftTemp.rZScore > stDriftTemp.rDriftThresh);
  IF stDriftTemp.bDriftFlag THEN
    iActiveFaultCode := FC_DRIFT_TEMP; LogFault();
    rTempPV := stDriftTemp.rMean;
  ELSE rTempPV := rTempPV_Raw; END_IF;
END_ACTION

(* ============================================================
   ACTION: HIL Digital Twin Synchronization
   ============================================================ *)
ACTION DTwin_Sync:
  tDTwinTimer(IN := TRUE, PT := T#100MS);
  IF tDTwinTimer.Q THEN
    tDTwinTimer(IN := FALSE);
    (* Send real state to digital twin (simulation server) *)
    IF NOT msgDTwin_Send.EN THEN
      msgDTwin_Send.MessageType     := MESSAGE_CIP_GENERIC;
      msgDTwin_Send.RequestedLength := 12;  (* rFlowPV, rPressPV, rTempPV *)
      msgDTwin_Send.CommTypeCode    := CIP_CONNECTED;
      msgDTwin_Send.EN := TRUE;
    END_IF;
    IF msgDTwin_Send.ER THEN
      stDTwin.iSyncErrors := stDTwin.iSyncErrors + 1;
      stDTwin.bSyncOK := FALSE;
      IF stDTwin.iSyncErrors > 10 THEN
        iActiveFaultCode := FC_DTWIN_SYNC; LogFault();
      END_IF;
    ELSIF msgDTwin_Send.DN THEN
      stDTwin.bSyncOK := TRUE; stDTwin.iSyncErrors := 0;
      msgDTwin_Send.EN := FALSE;
    END_IF;

    (* Receive predicted future state from twin *)
    IF NOT msgDTwin_Recv.EN THEN
      msgDTwin_Recv.MessageType     := MESSAGE_CIP_GENERIC;
      msgDTwin_Recv.RequestedLength := 24;  (* 6 REALs: 3 pred + 3 FF *)
      msgDTwin_Recv.EN := TRUE;
    END_IF;
    IF msgDTwin_Recv.DN THEN
      (* Destination tags mapped to stDTwin.rPred* and rFF* *)
      (* Apply feed-forward corrections to PID setpoints *)
      fbFlowPID.FF  := stDTwin.rFFFlow;
      fbPressPID.FF := stDTwin.rFFPress;
      fbTempPID.FF  := stDTwin.rFFTemp;
      msgDTwin_Recv.EN := FALSE;
    END_IF;
  END_IF;
END_ACTION

(* ============================================================
   ACTION: Structured Self-Test Routine
   Runs step-by-step at startup before releasing to ST_IDLE
   ============================================================ *)
ACTION SelfTest_Execute:
  IF bSelfTestDone THEN RETURN; END_IF;

  tSelfTestTimer(IN := TRUE, PT := T#2S);   (* 2 s per step *)
  IF NOT tSelfTestTimer.Q THEN RETURN; END_IF;
  tSelfTestTimer(IN := FALSE);

  CASE iSelfTestStep OF
    0: (* Flow AI channel — inject known signal via loopback *)
      aSelfTestResults[0].sTestName := 'Flow AI Loopback';
      aSelfTestResults[0].rExpected := 50.0;
      aSelfTestResults[0].rMeasured := rFlowPV_Raw;  (* loopback drives 50 sccm *)
      aSelfTestResults[0].bPassed   := ABS(rFlowPV_Raw - 50.0) < 2.0;

    1: (* Pressure AI channel *)
      aSelfTestResults[1].sTestName := 'Press AI Loopback';
      aSelfTestResults[1].rExpected := 5.0;
      aSelfTestResults[1].rMeasured := rPressPV_Raw;
      aSelfTestResults[1].bPassed   := ABS(rPressPV_Raw - 5.0) < 0.1;

    2: (* Temperature AI channel *)
      aSelfTestResults[2].sTestName := 'Temp AI Loopback';
      aSelfTestResults[2].rExpected := 25.0;  (* ambient *)
      aSelfTestResults[2].rMeasured := rTempPV_Raw;
      aSelfTestResults[2].bPassed   := ABS(rTempPV_Raw - 25.0) < 5.0;

    3: (* MFC AO channel — command 50 %, read back via AI *)
      rMFC_CV := 50.0;
      aSelfTestResults[3].sTestName := 'MFC AO→AI Loopback';
      aSelfTestResults[3].rExpected := 50.0;
      aSelfTestResults[3].rMeasured := rFlowPV_Raw;
      aSelfTestResults[3].bPassed   := ABS(rFlowPV_Raw - 50.0) < 5.0;
      rMFC_CV := 0.0;  (* restore *)

    4: (* Throttle valve AO *)
      rThrottle_CV := 30.0;
      aSelfTestResults[4].sTestName := 'Throttle AO';
      aSelfTestResults[4].rExpected := 30.0;
      aSelfTestResults[4].rMeasured := rPressPV_Raw;
      aSelfTestResults[4].bPassed   := ABS(rPressPV_Raw - 5.0) < 1.0;  (* pressure still at ambient *)
      rThrottle_CV := 0.0;

    5: (* Flow PID auto-step response — SP bump test *)
      fbFlowPID.SP := 10.0; fbFlowPID.PV := 0.0;
      fbFlowPID.EnableIn := TRUE; fbFlowPID.CVEU_HI := 100.0; fbFlowPID.CVEU_LO := 0.0;
      fbFlowPID();
      aSelfTestResults[5].sTestName := 'Flow PID Step';
      aSelfTestResults[5].rExpected := 1.0;   (* CV should be > 0 *)
      aSelfTestResults[5].rMeasured := fbFlowPID.CV;
      aSelfTestResults[5].bPassed   := fbFlowPID.CV > 0.0;
      fbFlowPID.EnableIn := FALSE;

    6: (* Pressure PID step *)
      fbPressPID.SP := 5.0; fbPressPID.PV := 0.0;
      fbPressPID.EnableIn := TRUE; fbPressPID.CVEU_HI := 100.0; fbPressPID.CVEU_LO := 0.0;
      fbPressPID();
      aSelfTestResults[6].sTestName := 'Press PID Step';
      aSelfTestResults[6].rMeasured := fbPressPID.CV;
      aSelfTestResults[6].bPassed   := fbPressPID.CV > 0.0;
      fbPressPID.EnableIn := FALSE;

    7: (* EIP comms — ping supervisor MSG *)
      aSelfTestResults[7].sTestName := 'EIP Comm Ping';
      (* Result set by prior EIP send: stEIP.bConnected *)
      aSelfTestResults[7].bPassed   := TRUE;  (* assume OK if no fault logged *)
      aSelfTestResults[7].sDetail   := 'EIP ping assumed OK — check stEIP';

    8: (* Digital twin link *)
      aSelfTestResults[8].sTestName := 'DTwin Sync';
      aSelfTestResults[8].bPassed   := stDTwin.bSyncOK;
      aSelfTestResults[8].sDetail   := 'DTwin sync state';

    9: (* Tally results *)
      iSelfTestPassed := 0; iSelfTestFailed := 0;
      FOR i := 0 TO SELFTEST_STEPS - 1 DO
        IF aSelfTestResults[i].bPassed THEN
          iSelfTestPassed := iSelfTestPassed + 1;
        ELSE
          iSelfTestFailed := iSelfTestFailed + 1;
        END_IF;
      END_FOR;
      bSelfTestDone := TRUE;
      IF iSelfTestFailed > 0 THEN
        iActiveFaultCode := FC_SELFTEST_FAIL; LogFault();
        eState := ST_FAULT;
      ELSE
        eState := ST_IDLE;
      END_IF;
      RETURN;
  END_CASE;

  iSelfTestStep := iSelfTestStep + 1;
END_ACTION

(* ============================================================
   ACTION: Fault log
   ============================================================ *)
ACTION LogFault:
  aFaultLog[iFaultHead].iCode  := iActiveFaultCode;
  aFaultLog[iFaultHead].eState := eState;
  iFaultHead := (iFaultHead + 1) MOD FAULT_LOG_SZ;
  IF iFaultCount < FAULT_LOG_SZ THEN iFaultCount := iFaultCount + 1; END_IF;
END_ACTION

(* ============================================================
   ACTION: Heater
   ============================================================ *)
ACTION HeaterControl:
  IF rTempPV >= rTempMaxLimit THEN bOverTempLatch := TRUE; END_IF;
  IF bOverTempLatch THEN
    bHeaterEnable := FALSE; rHeater_CV := 0.0; fbTempPID.EnableIn := FALSE;
    iActiveFaultCode := FC_OVERTEMP; LogFault(); eState := ST_FAULT; RETURN;
  END_IF;
  IF bHeaterEnable THEN
    fbTempPID.SP := rTempSP_Active; fbTempPID.PV := rTempPV;
    fbTempPID.Kp := rTemp_KP; fbTempPID.Ki := rTemp_KI; fbTempPID.Kd := rTemp_KD;
    fbTempPID.EnableIn := TRUE; fbTempPID.CVEU_HI := 100.0; fbTempPID.CVEU_LO := 0.0;
    fbTempPID(); rHeater_CV := fbTempPID.CV;
  ELSE
    fbTempPID.EnableIn := FALSE; rHeater_CV := 0.0;
  END_IF;
END_ACTION

ACTION LoadLayer:
  IF iLayerIdx < iTotalLayers THEN
    fbFlowPID.SP := aRecipe[iLayerIdx].rFlowSP;
    fbPressPID.SP:= aRecipe[iLayerIdx].rPressSP;
    rTempSP_Active := aRecipe[iLayerIdx].rTempSP;
  END_IF;
END_ACTION

ACTION OPCUA_Publish:
  tOPCPublishTimer(IN := TRUE, PT := T#1S);
  IF tOPCPublishTimer.Q THEN
    tOPCPublishTimer(IN := FALSE);
    aOPCTags[0].rValue := rFlowPV;  aOPCTags[0].bDirty := TRUE;
    aOPCTags[1].rValue := rPressPV; aOPCTags[1].bDirty := TRUE;
    aOPCTags[2].rValue := rTempPV;  aOPCTags[2].bDirty := TRUE;
    aOPCTags[3].rValue := rMFC_CV;  aOPCTags[3].bDirty := TRUE;
    aOPCTags[4].rValue := rThrottle_CV; aOPCTags[4].bDirty := TRUE;
    aOPCTags[5].rValue := rHeater_CV;  aOPCTags[5].bDirty := TRUE;
    aOPCTags[6].rValue := INT_TO_REAL(iActiveFaultCode); aOPCTags[6].bDirty := TRUE;
    aOPCTags[7].rValue := stDriftFlow.rZScore; aOPCTags[7].bDirty := TRUE;
    IF NOT msgOPCUA.EN THEN
      msgOPCUA.MessageType := MESSAGE_CIP_GENERIC; msgOPCUA.EN := TRUE;
    END_IF;
    IF msgOPCUA.ER THEN
      bOPCUA_Error := TRUE; iActiveFaultCode := FC_OPCUA_ERR; LogFault();
    ELSIF msgOPCUA.DN THEN
      bOPCUA_Error := FALSE; msgOPCUA.EN := FALSE;
    END_IF;
  END_IF;
END_ACTION

(* ============================================================
   INITIALISE DRIFT THRESHOLDS (run once at start)
   ============================================================ *)
IF eState = ST_SELFTEST AND iSelfTestStep = 0 AND NOT bSelfTestDone THEN
  stDriftFlow.rDriftThresh  := 3.0;
  stDriftPress.rDriftThresh := 3.0;
  stDriftTemp.rDriftThresh  := 3.0;
END_IF;

(* ============================================================
   MAIN SCAN
   ============================================================ *)

(* 1. Run self-test before anything else *)
IF NOT bSelfTestDone THEN
  SelfTest_Execute();
  RETURN;
END_IF;

(* 2. Sensor drift detection — update rolling windows *)
DriftDetect_Update();

(* 3. HIL digital twin sync *)
DTwin_Sync();

(* 4. Heater *)
HeaterControl();

(* 5. OPC-UA publish *)
OPCUA_Publish();

(* 6. Safety / Alarm checks *)
IF bEmgStop THEN
  iActiveFaultCode := FC_EMG_STOP; LogFault(); eState := ST_FAULT;
END_IF;
IF rFlowPV > rMaxFlow THEN
  iActiveFaultCode := FC_FLOW_HIGH; LogFault(); eState := ST_FAULT;
END_IF;
IF rPressPV > rMaxPress THEN
  iActiveFaultCode := FC_PRESS_HIGH; LogFault(); eState := ST_FAULT;
END_IF;

(* 7. Fault acknowledgement *)
IF bFaultAck AND (eState = ST_FAULT)
   AND (iActiveFaultCode <> FC_OVERTEMP)
   AND (iActiveFaultCode <> FC_SEC_VIOLATION)
   AND (iActiveFaultCode <> FC_SELFTEST_FAIL)
THEN
  bOverTempLatch := FALSE; iActiveFaultCode := FC_NONE;
  eState := ST_IDLE; bFaultAck := FALSE;
END_IF;

(* 8. State machine *)
CASE eState OF

  ST_SELFTEST:
    (* handled above — should not reach here *)
    SelfTest_Execute();

  ST_IDLE:
    bHeaterEnable := FALSE;
    fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
    rMFC_CV := 0.0; rThrottle_CV := 0.0; iLayerIdx := 0;

  ST_PURGE:
    rMFC_CV := 0.0; rThrottle_CV := 50.0;
    tPurge(IN := TRUE, PT := T#60S);
    IF tPurge.Q THEN
      tPurge(IN := FALSE); bHeaterEnable := TRUE; LoadLayer();
      eState := ST_HEAT_RAMP;
    END_IF;

  ST_HEAT_RAMP:
    IF ABS(rTempPV - rTempSP_Active) <= 2.0 THEN
      tHeatRamp(IN := FALSE); eState := ST_RAMP_FLOW;
    END_IF;
    tHeatRamp(IN := TRUE, PT := T#1800S);
    IF tHeatRamp.Q THEN
      iActiveFaultCode := FC_HEAT_WATCHDOG; LogFault(); eState := ST_FAULT;
    END_IF;

  ST_RAMP_FLOW:
    rMFC_CV := rMFC_CV + 1.0;
    IF rMFC_CV > 100.0 THEN rMFC_CV := 100.0; END_IF;
    IF rFlowPV >= (aRecipe[iLayerIdx].rFlowSP * 0.95) THEN eState := ST_DEPOSIT; END_IF;

  ST_DEPOSIT:
    (* Flow PID with digital-twin feed-forward *)
    fbFlowPID.PV := rFlowPV; fbFlowPID.Kp := rFlow_KP; fbFlowPID.Ki := rFlow_KI; fbFlowPID.Kd := rFlow_KD;
    fbFlowPID.EnableIn := TRUE; fbFlowPID.CVEU_HI := 100.0; fbFlowPID.CVEU_LO := 0.0; fbFlowPID();
    rMFC_CV := fbFlowPID.CV;
    (* Pressure PID *)
    fbPressPID.PV := rPressPV; fbPressPID.Kp := rPress_KP; fbPressPID.Ki := rPress_KI; fbPressPID.Kd := rPress_KD;
    fbPressPID.EnableIn := TRUE; fbPressPID.CVEU_HI := 100.0; fbPressPID.CVEU_LO := 0.0; fbPressPID();
    rThrottle_CV := fbPressPID.CV;
    (* Layer timer *)
    tDeposit(IN := TRUE, PT := aRecipe[iLayerIdx].tDuration);
    IF tDeposit.Q THEN
      tDeposit(IN := FALSE); fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
      iLayerIdx := iLayerIdx + 1;
      IF iLayerIdx < iTotalLayers THEN eState := ST_INTER_PURGE;
      ELSE eState := ST_VENT; END_IF;
    END_IF;

  ST_INTER_PURGE:
    rMFC_CV := 0.0; rThrottle_CV := 50.0;
    tInterPurge(IN := TRUE, PT := T#30S);
    IF tInterPurge.Q THEN
      tInterPurge(IN := FALSE); LoadLayer(); eState := ST_HEAT_RAMP;
    END_IF;

  ST_VENT:
    bHeaterEnable := FALSE; fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
    rMFC_CV := 0.0; rThrottle_CV := 100.0;
    IF rPressPV < 0.01 THEN eState := ST_IDLE; END_IF;

  ST_FAULT:
    bHeaterEnable := FALSE; fbFlowPID.EnableIn := FALSE; fbPressPID.EnableIn := FALSE;
    rMFC_CV := 0.0; rThrottle_CV := 0.0; rHeater_CV := 0.0;

END_CASE;
```

Here is the base code for a Wafer CMP process in Siemens SCL.

```scl
FUNCTION_BLOCK FB_WaferCMP_Base
VAR_INPUT
    Start_CMP : Bool;
    Wafer_Present : Bool;
    Setpoint_Slurry_Flow : Real; // ml/min
    Setpoint_Platen_Pressure : Real; // psi
    Actual_Slurry_Flow : Real;
    Actual_Platen_Pressure : Real;
END_VAR
VAR_OUTPUT
    Cmd_Slurry_Pump : Real; // 0-100%
    Cmd_Platen_Pneumatic : Real; // 0-100%
    CMP_Active : Bool;
END_VAR
VAR
    PID_Slurry : PID_Compact;
    PID_Platen : PID_Compact;
END_VAR

BEGIN
    IF Start_CMP AND Wafer_Present THEN
        CMP_Active := TRUE;
    ELSE
        CMP_Active := FALSE;
    END_IF;

    // Slurry Flow Control
    PID_Slurry(
        Setpoint := Setpoint_Slurry_Flow,
        Input := Actual_Slurry_Flow,
        Run := CMP_Active,
        Output => Cmd_Slurry_Pump
    );

    // Platen Pressure Control
    PID_Platen(
        Setpoint := Setpoint_Platen_Pressure,
        Input := Actual_Platen_Pressure,
        Run := CMP_Active,
        Output => Cmd_Platen_Pneumatic
    );

END_FUNCTION_BLOCK
```

Here is the expanded SCL code with Retaining Ring Pressure Control and Endpoint Detection.

```scl
FUNCTION_BLOCK FB_WaferCMP_Depth
VAR_INPUT
    Start_CMP : Bool;
    Wafer_Present : Bool;
    Setpoint_Slurry_Flow : Real;
    Setpoint_Platen_Pressure : Real;
    Setpoint_Retaining_Ring : Real;
    Actual_Slurry_Flow : Real;
    Actual_Platen_Pressure : Real;
    Actual_Retaining_Ring : Real;
    Motor_Torque : Real; // Endpoint Detection (EPD)
    Torque_Threshold : Real;
END_VAR
VAR_OUTPUT
    Cmd_Slurry_Pump : Real;
    Cmd_Platen_Pneumatic : Real;
    Cmd_Retaining_Ring : Real;
    CMP_Active : Bool;
    Endpoint_Reached : Bool;
END_VAR
VAR
    PID_Slurry : PID_Compact;
    PID_Platen : PID_Compact;
    PID_Ring : PID_Compact;
    Timer_EPD_Delay : TON;
END_VAR

BEGIN
    IF Start_CMP AND Wafer_Present AND NOT Endpoint_Reached THEN
        CMP_Active := TRUE;
    ELSE
        CMP_Active := FALSE;
    END_IF;

    // Endpoint Detection (Motor Torque drops when planarization is complete)
    Timer_EPD_Delay(IN := (Motor_Torque < Torque_Threshold) AND CMP_Active, PT := T#2S);
    IF Timer_EPD_Delay.Q THEN
        Endpoint_Reached := TRUE;
        CMP_Active := FALSE;
    END_IF;

    IF NOT Start_CMP THEN
        Endpoint_Reached := FALSE;
    END_IF;

    PID_Slurry(Setpoint := Setpoint_Slurry_Flow, Input := Actual_Slurry_Flow, Run := CMP_Active, Output => Cmd_Slurry_Pump);
    PID_Platen(Setpoint := Setpoint_Platen_Pressure, Input := Actual_Platen_Pressure, Run := CMP_Active, Output => Cmd_Platen_Pneumatic);
    PID_Ring(Setpoint := Setpoint_Retaining_Ring, Input := Actual_Retaining_Ring, Run := CMP_Active, Output => Cmd_Retaining_Ring);

END_FUNCTION_BLOCK
