```scl
FUNCTION_BLOCK FB_WaferCMP_Reasoning
VAR_INPUT
    Start_CMP : Bool;
    Wafer_Present : Bool;
    Operator_Level : Int; // IEC 62443 RBAC
    SCADA_Heartbeat : Bool;
    Primary_PLC_Active : Bool; // Failover
    Setpoint_Slurry_Flow : Real;
    Setpoint_Platen_Pressure : Real;
    Actual_Slurry_Flow : Real;
    Actual_Platen_Pressure : Real;
END_VAR
VAR_OUTPUT
    Cmd_Slurry_Pump : Real;
    Cmd_Platen_Pneumatic : Real;
    CMP_Active : Bool;
    System_Ready : Bool;
    Security_Alarm : Bool;
END_VAR
VAR
    PID_Slurry : PID_Compact;
    PID_Platen : PID_Compact;
    Heartbeat_Timer : TON;
    Is_Master : Bool;
END_VAR

BEGIN
    // Cybersecurity & RBAC
    IF Operator_Level < 2 AND Start_CMP THEN
        Security_Alarm := TRUE;
    ELSE
        Security_Alarm := FALSE;
    END_IF;

    // SCADA Integration
    Heartbeat_Timer(IN := NOT SCADA_Heartbeat, PT := T#3S);

    // Redundancy Failover
    Is_Master := Primary_PLC_Active; 

    IF NOT Heartbeat_Timer.Q AND Is_Master AND NOT Security_Alarm THEN
        System_Ready := TRUE;
    ELSE
        System_Ready := FALSE;
    END_IF;

    IF Start_CMP AND Wafer_Present AND System_Ready THEN
        CMP_Active := TRUE;
    ELSE
        CMP_Active := FALSE;
    END_IF;

    PID_Slurry(Setpoint := Setpoint_Slurry_Flow, Input := Actual_Slurry_Flow, Run := CMP_Active, Output => Cmd_Slurry_Pump);
    PID_Platen(Setpoint := Setpoint_Platen_Pressure, Input := Actual_Platen_Pressure, Run := CMP_Active, Output => Cmd_Platen_Pneumatic);

END_FUNCTION_BLOCK
