PROGRAM PRG_EUV_Scanner
VAR
    bEnableReticleStage : BOOL;
    fReticlePositionSetPoint : LREAL;
    fReticlePositionActual : LREAL;
    fReticleVelocity : LREAL;
    bReticleStageReady : BOOL;
    bEnablePiezo : BOOL;
    fPiezoVoltageSetPoint : LREAL;
    fPiezoVoltageActual : LREAL;
    bPiezoAligned : BOOL;
    fReticleError : LREAL;
    fPiezoError : LREAL;
    Kp_Reticle : LREAL := 0.5;
    Kp_Piezo : LREAL := 1.2;
END_VAR

IF bEnableReticleStage THEN
    fReticleError := fReticlePositionSetPoint - fReticlePositionActual;
    fReticleVelocity := fReticleError * Kp_Reticle;
    IF ABS(fReticleError) < 0.001 THEN
        bReticleStageReady := TRUE;
    ELSE
        bReticleStageReady := FALSE;
    END_IF
ELSE
    fReticleVelocity := 0.0;
    bReticleStageReady := FALSE;
END_IF

IF bEnablePiezo THEN
    fPiezoError := fPiezoVoltageSetPoint - fPiezoVoltageActual;
    fPiezoVoltageSetPoint := fPiezoVoltageActual + (fPiezoError * Kp_Piezo);
    IF ABS(fPiezoError) < 0.01 THEN
        bPiezoAligned := TRUE;
    ELSE
        bPiezoAligned := FALSE;
    END_IF
ELSE
    bPiezoAligned := FALSE;
END_IF
