PROGRAM PRG_EUV_Scanner_EtherCAT
VAR
    NetId AT %I* : ARRAY[0..5] OF BYTE;
    PortState AT %I* : UINT;
    WcState AT %I* : BOOL;
    bEtherCATFault : BOOL;
    fReticlePosAct AT %I* : LREAL;
    fReticleVelCtrl AT %Q* : LREAL;
    fWaferPosAct AT %I* : LREAL;
    fWaferVelCtrl AT %Q* : LREAL;
    fPiezoVolAct AT %I* : LREAL;
    fPiezoVolCtrl AT %Q* : LREAL;
    eState : INT := 0;
    nErrorCode : UDINT;
END_VAR

CASE eState OF
    0:
        fReticleVelCtrl := 0;
        fWaferVelCtrl := 0;
        fPiezoVolCtrl := 0;
        eState := 1;
    1:
        IF WcState THEN
            bEtherCATFault := TRUE;
            nErrorCode := 16#E001;
            eState := 4;
        ELSIF PortState = 16#0008 THEN
            eState := 2;
        END_IF
    2:
        eState := 3;
    3:
        IF WcState THEN
            eState := 4;
        ELSE
            fWaferVelCtrl := ( (fReticlePosAct / -4.0) - fWaferPosAct ) * 15.0;
            fReticleVelCtrl := 100.0;
            fPiezoVolCtrl := fPiezoVolAct * 0.95 + 0.5;
        END_IF
    4:
        fReticleVelCtrl := 0;
        fWaferVelCtrl := 0;
        fPiezoVolCtrl := 0;
END_CASE
