        1:
            IF fSensorWaferPos > 0.0 AND NOT bDriftAlarm THEN
                bSelfTestPassed := TRUE;
            ELSE
                bSelfTestPassed := FALSE;
            END_IF
            fWaferOut := 0.0;
            bRunSelfTest := FALSE;
    END_CASE
ELSE
    IF bSelfTestPassed AND NOT bDriftAlarm THEN
        fWaferOut := 10.0;
    ELSE
        fWaferOut := 0.0;
    END_IF
