FUNCTION STATUS_TO_ESR : ESR_DATA
VAR_INPUT
    status : BYTE;
    adress : STRING(10);
    DT_in : DT;
    TS : TIME;
END_VAR
VAR
    Result : ESR_DATA;
END_VAR

