    IF s0 THEN
        ESR_Out[cnt].TYP := BYTE#11;
    ELSE
        ESR_Out[cnt].TYP := BYTE#10;
    END_IF;
    ESR_Out[cnt].ADRESS := a0;
    ESR_Out[cnt].DS := DT_in;
    ESR_Out[cnt].TS := tx;
    x0 := s0;
    cnt := cnt + INT#1;
    ESR_Flag := TRUE;
