    DIN : DWORD;
    E : BOOL := TRUE;
    RD : BOOL;
    WD : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    DOUT : DWORD;
    EMPTY : BOOL;
    FULL : BOOL;
END_VAR
VAR
