    Pt : INT;
END_VAR

IF RST THEN
    Pt := INT#0;
    EMPTY := TRUE;
    FULL := FALSE;
    DOUT := DWORD#0;
ELSIF E THEN
    IF NOT EMPTY AND RD THEN
        Pt := Pt - INT#1;
        DOUT := Stack[Pt];
        EMPTY := Pt = INT#0;
        FULL := FALSE;
    END_IF;
    IF NOT FULL AND WD THEN
        Stack[Pt] := DIN;
        Pt := Pt + INT#1;
        FULL := Pt > INT#15;
        EMPTY := FALSE;
    END_IF;
END_IF;
