FUNCTION_BLOCK TONOF
VAR_INPUT
    IN : BOOL;
    T_ON : TIME;
    T_OFF : TIME;
END_VAR
VAR_OUTPUT
    Q : BOOL;
END_VAR
VAR
    X : TON;
    Old : BOOL;
    Mode : BOOL;
END_VAR

IF IN XOR Old THEN
    X(IN := FALSE, PT := SEL(G := IN, IN0 := T_OFF, IN1 := T_ON));
    Mode := IN;
    Old := IN;
END_IF;
X(IN := TRUE);
IF X.Q THEN
    Q := Mode;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TP_X
VAR_INPUT
    IN : BOOL;
    PT : TIME;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    ET : TIME;
END_VAR
VAR
    Edge : BOOL;
    Start : DWORD;
    Tx : DWORD;
    TxValue : UDINT;
    StartValue : UDINT;
    PeriodValue : UDINT;
END_VAR

Tx := T_PLC_MS();
TxValue := DWORD_TO_UDINT(Tx);
StartValue := DWORD_TO_UDINT(Start);
PeriodValue := DWORD_TO_UDINT(TIME_TO_DWORD(PT));

IF IN AND NOT Edge THEN
    Start := Tx;
    ET := T#0ms;
    Q := PT > T#0ms;
ELSIF Q THEN
    ET := DWORD_TO_TIME(UDINT_TO_DWORD(TxValue - StartValue));
    IF TxValue - StartValue >= PeriodValue THEN
        Q := FALSE;
        ET := T#0ms;
    END_IF;
END_IF;
Edge := IN;
END_FUNCTION_BLOCK


FUNCTION_BLOCK CLK_PRG
VAR_INPUT
    PT : TIME := T#10ms;
END_VAR
VAR_OUTPUT
    Q : BOOL;
END_VAR
VAR
    Init : BOOL;
    LastMs : DINT;
    TxMs : DINT;
END_VAR

TxMs := DWORD_TO_DINT(T_PLC_MS());

IF NOT Init THEN
    Init := TRUE;
    LastMs := TxMs - DWORD_TO_DINT(TIME_TO_DWORD(PT));
END_IF;

Q := TxMs - LastMs >= DWORD_TO_DINT(TIME_TO_DWORD(PT));
IF Q THEN
    LastMs := TxMs;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TP_1D
VAR_INPUT
    IN : BOOL;
    PT1 : TIME;
    PTD : TIME;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    W : BOOL;
END_VAR
VAR
    TxMs : DINT;
    StartMs : DINT;
    Edge : BOOL;
END_VAR

TxMs := DWORD_TO_DINT(T_PLC_MS());

IF RST THEN
    Q := FALSE;
    W := FALSE;
ELSIF W THEN
    IF TxMs - StartMs >= DWORD_TO_DINT(TIME_TO_DWORD(PTD)) THEN
        W := FALSE;
    END_IF;
ELSIF IN AND NOT Edge THEN
    Q := TRUE;
    StartMs := TxMs;
ELSIF Q AND TxMs - StartMs >= DWORD_TO_DINT(TIME_TO_DWORD(PT1)) THEN
    Q := FALSE;
    W := TRUE;
    StartMs := TxMs;
END_IF;

Edge := IN;
END_FUNCTION_BLOCK

