FUNCTION_BLOCK SELECT_8
VAR_INPUT
    E : BOOL;
    SetIn : BOOL;
    IN : BYTE;
    UP : BOOL;
    DN : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    Q0 : BOOL;
    Q1 : BOOL;
    Q2 : BOOL;
    Q3 : BOOL;
    Q4 : BOOL;
    Q5 : BOOL;
    Q6 : BOOL;
    Q7 : BOOL;
    STATE : INT;
END_VAR
VAR
    LastUp : BOOL;
    LastDn : BOOL;
END_VAR

IF RST THEN
    STATE := INT#0;
ELSIF SetIn THEN
    STATE := BYTE_TO_INT(IN := IN);
ELSIF UP AND NOT LastUp THEN
    STATE := INC(STATE, INT#1, INT#7);
ELSIF DN AND NOT LastDn THEN
    STATE := INC(STATE, INT#-1, INT#7);
END_IF;
LastUp := UP;
LastDn := DN;

Q0 := FALSE;
Q1 := FALSE;
Q2 := FALSE;
Q3 := FALSE;
Q4 := FALSE;
Q5 := FALSE;
Q6 := FALSE;
Q7 := FALSE;

IF E THEN
    CASE STATE OF
        INT#0:
            Q0 := TRUE;
        INT#1:
            Q1 := TRUE;
        INT#2:
            Q2 := TRUE;
        INT#3:
            Q3 := TRUE;
        INT#4:
            Q4 := TRUE;
        INT#5:
            Q5 := TRUE;
        INT#6:
            Q6 := TRUE;
        INT#7:
            Q7 := TRUE;
    END_CASE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK SHR_4E
VAR_INPUT
    SetIn : BOOL;
    D0 : BOOL;
    CLK : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    Q0 : BOOL;
    Q1 : BOOL;
    Q2 : BOOL;
    Q3 : BOOL;
END_VAR
VAR
    Edge : BOOL;
END_VAR

IF SetIn OR RST THEN
    Q0 := NOT RST;
    Q1 := Q0;
    Q2 := Q0;
    Q3 := Q0;
ELSIF CLK AND NOT Edge THEN
    Q3 := Q2;
    Q2 := Q1;
    Q1 := Q0;
    Q0 := D0;
END_IF;
Edge := CLK;
END_FUNCTION_BLOCK

FUNCTION_BLOCK SHR_4UDE
VAR_INPUT
    SetIn : BOOL;
    D0 : BOOL;
    D3 : BOOL;
    CLK : BOOL;
    DN : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    Q0 : BOOL;
    Q1 : BOOL;
    Q2 : BOOL;
    Q3 : BOOL;
END_VAR
VAR
    Edge : BOOL;
END_VAR

IF SetIn OR RST THEN
    Q0 := NOT RST;
    Q1 := Q0;
    Q2 := Q0;
    Q3 := Q0;
ELSIF CLK AND NOT Edge THEN
    IF DN THEN
        Q0 := Q1;
        Q1 := Q2;
        Q2 := Q3;
        Q3 := D3;
    ELSE
        Q3 := Q2;
        Q2 := Q1;
        Q1 := Q0;
        Q0 := D0;
    END_IF;
END_IF;
Edge := CLK;
END_FUNCTION_BLOCK

FUNCTION_BLOCK SHR_8PLE
VAR_INPUT
    Din : BOOL;
    Dload : BYTE;
    CLK : BOOL;
    UP : BOOL := TRUE;
    LoadIn : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    DOut : BOOL;
END_VAR
VAR
    Edge : BOOL;
    RegisterValue : BYTE;
END_VAR

IF RST THEN
    RegisterValue := BYTE#0;
    DOut := FALSE;
ELSIF CLK AND NOT Edge THEN
    IF UP THEN
        RegisterValue := SHL(RegisterValue, INT#1);
        IF Din THEN
            RegisterValue := RegisterValue OR BYTE#1;
        END_IF;
    ELSE
        RegisterValue := SHR(RegisterValue, INT#1);
        IF Din THEN
            RegisterValue := RegisterValue OR BYTE#16#80;
        END_IF;
    END_IF;

    IF LoadIn THEN
        RegisterValue := Dload;
    END_IF;

    IF UP THEN
        DOut := (RegisterValue AND BYTE#16#80) = BYTE#16#80;
    ELSE
        DOut := (RegisterValue AND BYTE#1) = BYTE#1;
    END_IF;
END_IF;
Edge := CLK;
END_FUNCTION_BLOCK

FUNCTION_BLOCK SHR_8UDE
VAR_INPUT
    SetIn : BOOL;
    D0 : BOOL;
    D7 : BOOL;
    CLK : BOOL;
    DN : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    Q0 : BOOL;
    Q1 : BOOL;
    Q2 : BOOL;
    Q3 : BOOL;
    Q4 : BOOL;
    Q5 : BOOL;
    Q6 : BOOL;
    Q7 : BOOL;
END_VAR
VAR
    Edge : BOOL;
END_VAR

IF SetIn OR RST THEN
    Q0 := NOT RST;
    Q1 := Q0;
    Q2 := Q0;
    Q3 := Q0;
    Q4 := Q0;
    Q5 := Q0;
    Q6 := Q0;
    Q7 := Q0;
ELSIF CLK AND NOT Edge THEN
    IF DN THEN
        Q0 := Q1;
        Q1 := Q2;
        Q2 := Q3;
        Q3 := Q4;
        Q4 := Q5;
        Q5 := Q6;
        Q6 := Q7;
        Q7 := D7;
    ELSE
        Q7 := Q6;
        Q6 := Q5;
        Q5 := Q4;
        Q4 := Q3;
        Q3 := Q2;
        Q2 := Q1;
        Q1 := Q0;
        Q0 := D0;
    END_IF;
END_IF;
Edge := CLK;
END_FUNCTION_BLOCK

(* OSCAT BASIC 3.33 signal-generator helpers. *)

FUNCTION_BLOCK _RMP_B
VAR_INPUT
    DIR : BOOL;
    E : BOOL := TRUE;
    TR : TIME;
END_VAR
VAR_IN_OUT
    RMP : BYTE;
END_VAR
VAR
    TxMs : UDINT;
    LastMs : UDINT;
    LastTr : TIME;
    Init : BOOL;
    LastDir : BOOL;
    Start : BYTE;
END_VAR

TxMs := DWORD_TO_UDINT(T_PLC_MS());

IF E AND Init AND (DIR = LastDir) AND (RMP <> SEL(G := DIR, IN0 := BYTE#0, IN1 := BYTE#255)) AND TR = LastTr THEN
    RMP := FRMP_B(START := Start, DIR := DIR, TD := DWORD_TO_TIME(UDINT_TO_DWORD(TxMs - LastMs)), TR := TR);
ELSE
    Init := TRUE;
    LastMs := TxMs;
    LastTr := TR;
    Start := RMP;
END_IF;
LastDir := DIR;
END_FUNCTION_BLOCK

FUNCTION_BLOCK _RMP_NEXT
VAR_INPUT
    E : BOOL := TRUE;
    IN : BYTE;
    TR : TIME;
    TF : TIME;
    TL : TIME;
END_VAR
VAR_OUTPUT
    DIR : BOOL;
    UP : BOOL;
    DN : BOOL;
END_VAR
VAR_IN_OUT
    OUT : BYTE;
END_VAR
VAR
    Ramp : _RMP_B;
    DirectionTrend : TREND_DW;
    Lockout : TP;
    EnableRamp : BOOL;
    RampDir : BOOL;
END_VAR

DirectionTrend(X := BYTE_TO_DWORD(IN := IN));
Lockout(IN := FALSE, PT := TL);

IF DirectionTrend.TU AND (OUT < IN) THEN
    IF NOT RampDir AND EnableRamp THEN
        Lockout(IN := TRUE);
    END_IF;
    EnableRamp := TRUE;
    RampDir := TRUE;
ELSIF DirectionTrend.TD AND (OUT > IN) THEN
    IF RampDir AND EnableRamp THEN
        Lockout(IN := TRUE);
    END_IF;
    EnableRamp := TRUE;
    RampDir := FALSE;
ELSIF EnableRamp THEN
    IF (RampDir AND (OUT >= IN)) OR (NOT RampDir AND (OUT <= IN)) THEN
        EnableRamp := FALSE;
        IF TL > T#0s THEN
            Lockout(IN := TRUE);
        END_IF;
    END_IF;
END_IF;

IF NOT Lockout.Q AND EnableRamp THEN
    UP := RampDir;
    DIR := RampDir;
    DN := NOT RampDir;
ELSE
    UP := FALSE;
    DN := FALSE;
END_IF;

Ramp(RMP := OUT, E := E AND (UP OR DN), DIR := DIR, TR := SEL(G := DIR, IN0 := TF, IN1 := TR));
END_FUNCTION_BLOCK

FUNCTION_BLOCK _RMP_W
VAR_INPUT
    DIR : BOOL;
    E : BOOL := TRUE;
    TR : TIME;
END_VAR
VAR_IN_OUT
    RMP : WORD;
END_VAR
VAR
    Tx : DWORD;
    LastTime : DWORD;
    StepValue : DINT;
    Init : BOOL;
    LastDir : BOOL;
END_VAR

Tx := T_PLC_MS();
IF E AND Init THEN
    IF DIR XOR LastDir THEN
        LastTime := Tx;
        LastDir := DIR;
    END_IF;
    IF TR > T#0s THEN
        StepValue := REAL_TO_DINT(UDINT_TO_REAL(DWORD_TO_UDINT(Tx) - DWORD_TO_UDINT(LastTime)) * 65536.0 / UDINT_TO_REAL(DWORD_TO_UDINT(TIME_TO_DWORD(TR))));
    ELSE
        StepValue := DINT#65535;
    END_IF;
    IF StepValue > 0 THEN
        LastTime := Tx;
        IF NOT DIR THEN
            StepValue := -StepValue;
        END_IF;
        RMP := DINT_TO_WORD(LIMIT(MN := DINT#0, IN := WORD_TO_DINT(RMP) + StepValue, MX := DINT#65535));
    END_IF;
ELSE
    LastTime := Tx;
    Init := TRUE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK GEN_PULSE
VAR_INPUT
    ENQ : BOOL := TRUE;
    PTH : TIME;
    PTL : TIME;
END_VAR
VAR_OUTPUT
    Q : BOOL;
END_VAR
VAR
    TxMs : UDINT;
    NextMs : UDINT;
    Init : BOOL;
END_VAR

IF ENQ THEN
    TxMs := DWORD_TO_UDINT(T_PLC_MS());
    IF NOT Init THEN
        Init := TRUE;
        NextMs := TxMs;
    END_IF;
    IF TxMs - NextMs >= DWORD_TO_UDINT(TIME_TO_DWORD(SEL(G := Q, IN0 := PTH, IN1 := PTL))) THEN
        NextMs := NextMs + DWORD_TO_UDINT(TIME_TO_DWORD(SEL(G := Q, IN0 := PTH, IN1 := PTL)));
        Q := NOT Q;
    END_IF;
ELSE
    Q := FALSE;
    Init := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK GEN_PW2
VAR_INPUT
    ENQ : BOOL;
    TH1 : TIME;
    TL1 : TIME;
    TH2 : TIME;
    TL2 : TIME;
    TS : BOOL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    TH : TIME;
    TL : TIME;
END_VAR
VAR
    HighTime : TIME;
    LowTime : TIME;
    TxMs : UDINT;
    StartMs : UDINT;
    Init : BOOL;
    ElapsedMs : UDINT;
END_VAR

TxMs := DWORD_TO_UDINT(T_PLC_MS());

IF NOT Init THEN
    StartMs := TxMs;
    Init := TRUE;
    TH := T#0s;
    TL := T#0s;
END_IF;

IF TS THEN
    HighTime := TH2;
    LowTime := TL2;
ELSE
    HighTime := TH1;
    LowTime := TL1;
END_IF;

IF ENQ THEN
    ElapsedMs := TxMs - StartMs;
    IF NOT Q THEN
        IF ElapsedMs >= DWORD_TO_UDINT(TIME_TO_DWORD(LowTime)) THEN
            Q := TRUE;
            StartMs := TxMs;
            TL := T#0s;
        ELSE
            TL := DWORD_TO_TIME(UDINT_TO_DWORD(ElapsedMs));
        END_IF;
    ELSE
        IF ElapsedMs >= DWORD_TO_UDINT(TIME_TO_DWORD(HighTime)) THEN
            Q := FALSE;
            StartMs := TxMs;
            TH := T#0s;
        ELSE
            TH := DWORD_TO_TIME(UDINT_TO_DWORD(ElapsedMs));
        END_IF;
    END_IF;
ELSE
    Q := FALSE;
    TH := T#0s;
    TL := T#0s;
    StartMs := TxMs;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK GEN_RDM
VAR_INPUT
    PT : TIME;
    AM : REAL := 1.0;
    OS : REAL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    OUT : REAL;
END_VAR
VAR
    TxMs : UDINT;
    LastMs : UDINT;
    ElapsedMs : UDINT;
    Init : BOOL;
END_VAR

TxMs := DWORD_TO_UDINT(T_PLC_MS());

IF NOT Init THEN
    Init := TRUE;
    LastMs := TxMs;
    ElapsedMs := UDINT#0;
ELSE
    ElapsedMs := TxMs - LastMs;
END_IF;

IF ElapsedMs >= DWORD_TO_UDINT(TIME_TO_DWORD(PT)) THEN
    LastMs := LastMs + DWORD_TO_UDINT(TIME_TO_DWORD(PT));
    ElapsedMs := ElapsedMs - DWORD_TO_UDINT(TIME_TO_DWORD(PT));
    OUT := AM * (RDM(LAST := REAL#0.0) - 0.5) + OS;
    Q := TRUE;
ELSE
    Q := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK GEN_RDT
VAR_INPUT
    Enable : BOOL := TRUE;
    Min_Time_ms : TIME := T#1s;
    Max_Time_ms : TIME := T#1200ms;
    TP_Q : TIME := T#100ms;
END_VAR
VAR_OUTPUT
    xQ : BOOL;
END_VAR
VAR
    RandomTimer : TON;
    PulseHold : TOF;
    RandomTime : TIME;
    RandomSeed : REAL;
    MinMs : UDINT;
    MaxMs : UDINT;
END_VAR

RandomTimer(IN := Enable, PT := RandomTime);
PulseHold(IN := RandomTimer.Q, PT := TP_Q);
xQ := PulseHold.Q;
IF RandomTimer.Q THEN
    xQ := TRUE;
    RandomSeed := RDM(LAST := RandomSeed);
    MinMs := DWORD_TO_UDINT(TIME_TO_DWORD(Min_Time_ms));
    MaxMs := DWORD_TO_UDINT(TIME_TO_DWORD(Max_Time_ms));
    RandomTime := DWORD_TO_TIME(UDINT_TO_DWORD(REAL_TO_UDINT(
        RandomSeed * UDINT_TO_REAL(MaxMs - MinMs) + UDINT_TO_REAL(MinMs)
    )));
    RandomTimer(IN := FALSE);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK GEN_RMP
VAR_INPUT
    PT : TIME := T#1s;
    AM : REAL := 1.0;
    OS : REAL;
    DL : REAL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    OUT : REAL;
END_VAR
VAR
    TxMs : UDINT;
    LastMs : UDINT;
    ElapsedMs : UDINT;
    Init : BOOL;
    Temp : REAL;
    LastTemp : REAL;
    DelayLocal : REAL;
    PeriodMs : UDINT;
    PeriodMsReal : REAL;
END_VAR

TxMs := DWORD_TO_UDINT(T_PLC_MS());
PeriodMs := DWORD_TO_UDINT(TIME_TO_DWORD(PT));
PeriodMsReal := UDINT_TO_REAL(PeriodMs);
DelayLocal := MODR(IN := DL, DIVI := REAL#1.0);
IF DelayLocal < 0.0 THEN
    DelayLocal := 1.0 - DelayLocal;
END_IF;

IF NOT Init THEN
    Init := TRUE;
    LastMs := TxMs;
    ElapsedMs := UDINT#0;
ELSE
    ElapsedMs := TxMs - LastMs;
END_IF;

IF ElapsedMs >= PeriodMs THEN
    LastMs := LastMs + PeriodMs;
    ElapsedMs := ElapsedMs - PeriodMs;
END_IF;

LastTemp := Temp;
IF PeriodMs > UDINT#0 THEN
    Temp := FRACT(X := (UDINT_TO_REAL(ElapsedMs) + PeriodMsReal * DelayLocal) / PeriodMsReal);
END_IF;
OUT := AM * Temp + OS;
Q := Temp < LastTemp;
END_FUNCTION_BLOCK

FUNCTION_BLOCK GEN_SIN
VAR_INPUT
    PT : TIME;
    AM : REAL := 1.0;
    OS : REAL;
    DL : REAL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    OUT : REAL;
END_VAR
VAR
    TxMs : UDINT;
    LastMs : UDINT;
    ElapsedMs : UDINT;
    Init : BOOL;
    Temp : REAL;
    DelayLocal : REAL;
    PeriodMs : UDINT;
    PeriodMsReal : REAL;
END_VAR

TxMs := DWORD_TO_UDINT(T_PLC_MS());
PeriodMs := DWORD_TO_UDINT(TIME_TO_DWORD(PT));
PeriodMsReal := UDINT_TO_REAL(PeriodMs);
DelayLocal := MODR(IN := DL, DIVI := REAL#1.0);
IF DelayLocal < 0.0 THEN
    DelayLocal := 1.0 - DelayLocal;
END_IF;

IF NOT Init THEN
    Init := TRUE;
    LastMs := TxMs;
    ElapsedMs := UDINT#0;
ELSE
    ElapsedMs := TxMs - LastMs;
END_IF;

IF ElapsedMs >= PeriodMs THEN
    LastMs := LastMs + PeriodMs;
    ElapsedMs := ElapsedMs - PeriodMs;
END_IF;

IF PeriodMs > UDINT#0 THEN
    Temp := SIN(MATH.PI2 * (UDINT_TO_REAL(ElapsedMs) + PeriodMsReal * DelayLocal) / PeriodMsReal);
END_IF;
OUT := AM * 0.5 * Temp + OS;
Q := NOT SIGN_R(IN := Temp);
END_FUNCTION_BLOCK

FUNCTION_BLOCK GEN_SQR
VAR_INPUT
    PT : TIME;
    AM : REAL := 1.0;
    OS : REAL;
    DC : REAL := 0.5;
    DL : REAL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    OUT : REAL;
END_VAR
VAR
    TxMs : UDINT;
    LastMs : UDINT;
    ElapsedMs : UDINT;
    Init : BOOL;
    DelayLocal : REAL;
    DutyLocal : REAL;
    PeriodMs : UDINT;
    PeriodMsReal : REAL;
    PhaseStart : REAL;
    PhaseEnd : REAL;
    ElapsedReal : REAL;
END_VAR

IF DC = 0.0 THEN
    OUT := -AM * 0.5 + OS;
    Q := FALSE;
ELSIF DC = 1.0 THEN
    OUT := AM * 0.5 + OS;
    Q := TRUE;
ELSE
    TxMs := DWORD_TO_UDINT(T_PLC_MS());
    PeriodMs := DWORD_TO_UDINT(TIME_TO_DWORD(PT));
    PeriodMsReal := UDINT_TO_REAL(PeriodMs);
    DelayLocal := MODR(IN := DL, DIVI := REAL#1.0);
    IF DelayLocal < 0.0 THEN
        DelayLocal := 1.0 - DelayLocal;
    END_IF;
    DutyLocal := MODR(IN := DC, DIVI := REAL#1.0);
    IF DutyLocal < 0.0 THEN
        DutyLocal := 1.0 - DutyLocal;
    END_IF;

    IF NOT Init THEN
        Init := TRUE;
        LastMs := TxMs;
        ElapsedMs := UDINT#0;
    ELSE
        ElapsedMs := TxMs - LastMs;
    END_IF;

    IF ElapsedMs >= PeriodMs THEN
        LastMs := LastMs + PeriodMs;
        ElapsedMs := ElapsedMs - PeriodMs;
    END_IF;

    PhaseStart := PeriodMsReal * DelayLocal;
    PhaseEnd := PeriodMsReal * (DelayLocal + DutyLocal);
    ElapsedReal := UDINT_TO_REAL(ElapsedMs);
    IF PhaseEnd >= PeriodMsReal THEN
        IF ElapsedReal >= PhaseEnd - PeriodMsReal THEN
            OUT := -AM * 0.5 + OS;
            Q := FALSE;
        END_IF;
        IF ElapsedReal >= PhaseStart THEN
            OUT := AM * 0.5 + OS;
            Q := TRUE;
        END_IF;
    ELSE
        IF ElapsedReal >= PhaseStart THEN
            OUT := AM * 0.5 + OS;
            Q := TRUE;
        END_IF;
        IF ElapsedReal >= PhaseEnd THEN
            OUT := -AM * 0.5 + OS;
            Q := FALSE;
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK PWM_DC
VAR_INPUT
    F : REAL;
    DC : REAL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
END_VAR
VAR
    Clock : CLK_PRG;
    Pulse : TP_X;
    PeriodMs : REAL;
END_VAR

IF F > 0.0 THEN
    PeriodMs := 1000.0 / F;
    Clock(PT := DWORD_TO_TIME(UDINT_TO_DWORD(REAL_TO_UDINT(PeriodMs))));
    Pulse(IN := Clock.Q, PT := DWORD_TO_TIME(UDINT_TO_DWORD(REAL_TO_UDINT(PeriodMs * DC))));
    Q := Pulse.Q;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK PWM_PW
VAR_INPUT
    F : REAL;
    PW : TIME;
END_VAR
VAR_OUTPUT
    Q : BOOL;
END_VAR
VAR
    Clock : CLK_PRG;
    Pulse : TP_X;
END_VAR

IF F > 0.0 THEN
    Clock(PT := DWORD_TO_TIME(UDINT_TO_DWORD(REAL_TO_UDINT(1000.0 / F))));
    Pulse(IN := Clock.Q, PT := PW);
    Q := Pulse.Q;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK RMP_B
VAR_INPUT
    SET_HIGH : BOOL;
    PT : TIME;
    E : BOOL := TRUE;
    UP : BOOL := TRUE;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    OUT : BYTE;
    BUSY : BOOL;
    HIGH : BOOL;
    LOW : BOOL;
END_VAR
VAR
    Ramp : _RMP_B;
END_VAR

Ramp(DIR := UP, E := E, TR := PT, RMP := OUT);

IF RST THEN
    OUT := BYTE#0;
ELSIF SET_HIGH THEN
    OUT := BYTE#255;
END_IF;

LOW := OUT = BYTE#0;
HIGH := OUT = BYTE#255;
BUSY := NOT (LOW OR HIGH) AND E;
END_FUNCTION_BLOCK

FUNCTION_BLOCK RMP_SOFT
VAR_INPUT
    IN : BOOL;
    VAL : BYTE;
END_VAR
VAR_INPUT CONSTANT
    PT_ON : TIME;
    PT_OFF : TIME;
END_VAR
VAR_OUTPUT
    OUT : BYTE;
END_VAR
VAR
    Ramp : _RMP_B;
    Target : BYTE;
END_VAR

Target := SEL(G := IN, IN0 := BYTE#0, IN1 := VAL);
IF Target > OUT THEN
    Ramp(DIR := TRUE, E := TRUE, TR := PT_ON, RMP := OUT);
    IF OUT > Target THEN
        OUT := Target;
    END_IF;
ELSIF Target < OUT THEN
    Ramp(DIR := FALSE, E := TRUE, TR := PT_OFF, RMP := OUT);
    IF OUT < Target THEN
        OUT := Target;
    END_IF;
ELSE
    Ramp(E := FALSE, RMP := OUT);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK RMP_W
VAR_INPUT
    SET_HIGH : BOOL;
    PT : TIME;
    E : BOOL := TRUE;
    UP : BOOL := TRUE;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    OUT : WORD;
    BUSY : BOOL;
    HIGH : BOOL;
    LOW : BOOL;
END_VAR
VAR
    Ramp : _RMP_W;
END_VAR

Ramp(DIR := UP, E := E, TR := PT, RMP := OUT);

IF RST THEN
    OUT := WORD#0;
ELSIF SET_HIGH THEN
    OUT := WORD#65535;
END_IF;

LOW := OUT = WORD#0;
HIGH := OUT = WORD#65535;
BUSY := NOT (LOW OR HIGH) AND E;
END_FUNCTION_BLOCK

(* OSCAT BASIC 3.33 signal-processing helpers. *)

FUNCTION BYTE_TO_RANGE : REAL
VAR_INPUT
    X : BYTE;
    low : REAL;
    high : REAL;
END_VAR
BYTE_TO_RANGE := (high - low) * DINT_TO_REAL(BYTE_TO_DINT(X)) / 255.0 + low;
END_FUNCTION

FUNCTION RANGE_TO_BYTE : BYTE
VAR_INPUT
    X : REAL;
    low : REAL;
    high : REAL;
END_VAR
VAR
    LimitedValue : REAL;
    ScaledValue : REAL;
    TruncatedValue : DINT;
END_VAR
LimitedValue := LIMIT(MN := low, IN := X, MX := high);
ScaledValue := (LimitedValue - low) * 255.0 / (high - low);
TruncatedValue := FLOOR2(X := ScaledValue);
RANGE_TO_BYTE := DINT_TO_BYTE(TruncatedValue);
END_FUNCTION

FUNCTION RANGE_TO_WORD : WORD
VAR_INPUT
    X : REAL;
    low : REAL;
    high : REAL;
END_VAR
VAR
    LimitedValue : REAL;
    ScaledValue : REAL;
    TruncatedValue : DINT;
END_VAR
LimitedValue := LIMIT(MN := low, IN := X, MX := high);
ScaledValue := (LimitedValue - low) * 65535.0 / (high - low);
TruncatedValue := FLOOR2(X := ScaledValue);
RANGE_TO_WORD := DINT_TO_WORD(TruncatedValue);
END_FUNCTION

FUNCTION SCALE : REAL
VAR_INPUT
    X : REAL;
    K : REAL;
    O : REAL;
    MX : REAL;
    MN : REAL;
END_VAR
SCALE := LIMIT(MN := MN, IN := X * K + O, MX := MX);
END_FUNCTION

FUNCTION WORD_TO_RANGE : REAL
VAR_INPUT
    X : WORD;
    low : REAL;
    high : REAL;
END_VAR
WORD_TO_RANGE := (high - low) * DINT_TO_REAL(WORD_TO_DINT(X)) / 65535.0 + low;
END_FUNCTION

FUNCTION_BLOCK DELAY
VAR_INPUT
    IN : REAL;
    N : INT;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    OUT : REAL;
END_VAR
VAR
    BUF : ARRAY[0..31] OF REAL;
    I : INT;
    INIT : BOOL;
    STOP : INT;
    WINDOW : INT;
END_VAR

WINDOW := LIMIT(INT#0, N, INT#32);
STOP := WINDOW - INT#1;
IF RST OR NOT INIT THEN
    INIT := TRUE;
    FOR I := INT#0 TO STOP DO
        BUF[I] := IN;
    END_FOR;
    OUT := IN;
    I := INT#0;
ELSIF STOP < INT#0 THEN
    OUT := IN;
ELSE
    OUT := BUF[I];
    BUF[I] := IN;
    I := INC1(X := I, N := WINDOW);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TREND_DW
VAR_INPUT
    X : DWORD;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    TU : BOOL;
    TD : BOOL;
    D : DWORD;
END_VAR
VAR
    LastX : DWORD;
END_VAR

IF X > LastX THEN
    TU := TRUE;
    TD := FALSE;
    D := UDINT_TO_DWORD(DWORD_TO_UDINT(X) - DWORD_TO_UDINT(LastX));
    Q := TRUE;
ELSIF X < LastX THEN
    TD := TRUE;
    TU := FALSE;
    D := UDINT_TO_DWORD(DWORD_TO_UDINT(LastX) - DWORD_TO_UDINT(X));
    Q := FALSE;
ELSE
    TU := FALSE;
    TD := FALSE;
    D := DWORD#0;
END_IF;
LastX := X;
END_FUNCTION_BLOCK

FUNCTION AIN : REAL
VAR_INPUT
    in : DWORD;
END_VAR
VAR_INPUT CONSTANT
    Bits : BYTE;
    sign : BYTE := BYTE#255;
    low : REAL;
    high : REAL := 10.0;
END_VAR
VAR CONSTANT
    ff : DWORD := DWORD#16#FFFFFFFF;
END_VAR
VAR
    Temp1 : DWORD;
    Temp2 : DWORD;
    SignedValue : BOOL;
END_VAR

IF sign < BYTE#32 THEN
    Temp1 := SHR(in, BYTE_TO_INT(sign));
    SignedValue := (Temp1 AND DWORD#1) = DWORD#1;
ELSE
    SignedValue := FALSE;
END_IF;
Temp1 := SHR(ff, INT#32 - BYTE_TO_INT(Bits));
Temp2 := in AND Temp1;
AIN := (high - low) * DWORD_TO_REAL(Temp2) / DWORD_TO_REAL(Temp1) + low;
IF SignedValue THEN
    AIN := -AIN;
END_IF;
END_FUNCTION

FUNCTION_BLOCK AIN1
VAR_INPUT
    in : DWORD;
END_VAR
VAR_INPUT CONSTANT
    sign_bit : INT := INT#255;
    error_bit : INT := INT#255;
    error_code_en : BOOL;
    error_code : DWORD;
    overflow_bit : INT := INT#255;
    overflow_code_en : BOOL;
    overflow_code : DWORD;
    Bit_0 : INT;
    Bit_N : INT := INT#31;
    out_min : REAL;
    out_max : REAL := 10.0;
    code_min : DWORD;
    code_max : DWORD := DWORD#16#FFFFFFFF;
    error_output : REAL;
    overflow_output : REAL := 10.0;
END_VAR
VAR_OUTPUT
    out : REAL;
    sign : BOOL;
    error : BOOL;
    overflow : BOOL;
END_VAR
VAR
    DataBits : DWORD;
END_VAR

error := ((SHR(in, error_bit) AND DWORD#1) = DWORD#1) OR (error_code_en AND error_code = in);
IF error THEN
    out := error_output;
ELSE
    DataBits := SHR(SHL(in, INT#31 - Bit_N), INT#31 - Bit_N + Bit_0);
    overflow := ((SHR(in, overflow_bit) AND DWORD#1) = DWORD#1)
        OR (overflow_code_en AND overflow_code = in)
        OR (DataBits < code_min OR DataBits > code_max);
    IF overflow THEN
        out := overflow_output;
    ELSE
        sign := (SHR(in, sign_bit) AND DWORD#1) = DWORD#1;
        out := UDINT_TO_REAL(DWORD_TO_UDINT(DataBits) - DWORD_TO_UDINT(code_min)) * (out_max - out_min) / UDINT_TO_REAL(DWORD_TO_UDINT(code_max) - DWORD_TO_UDINT(code_min)) + out_min;
        IF sign THEN
            out := out * -1.0;
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION AOUT : DWORD
VAR_INPUT
    in : REAL;
END_VAR
VAR_INPUT CONSTANT
    Bits : BYTE;
    sign : BYTE := BYTE#255;
    low : REAL;
    high : REAL := 10.0;
END_VAR
VAR CONSTANT
    ff : DWORD := DWORD#1;
END_VAR
VAR
    InputValue : REAL;
    SignedValue : BOOL;
END_VAR

IF sign < BYTE#32 THEN
    SignedValue := SIGN_R(IN := in);
    InputValue := ABS(in);
ELSE
    InputValue := in;
END_IF;

InputValue := LIMIT(MN := low, IN := InputValue, MX := high);
AOUT := UDINT_TO_DWORD(
    REAL_TO_UDINT(
        (InputValue - low) / (high - low) * UDINT_TO_REAL(DWORD_TO_UDINT(SHL(ff, BYTE_TO_INT(Bits))) - UDINT#1)
    )
);
IF SignedValue THEN
    AOUT := SHL(ff, BYTE_TO_INT(sign)) OR AOUT;
END_IF;
END_FUNCTION

FUNCTION AOUT1 : DWORD
VAR_INPUT
    in : REAL;
END_VAR
VAR_INPUT CONSTANT
    Bit_0 : INT;
    Bit_N : INT := INT#31;
    sign : INT := INT#255;
    low : REAL;
    high : REAL := 10.0;
END_VAR
VAR CONSTANT
    ff : DWORD := DWORD#1;
END_VAR
VAR
    SignedValue : BOOL;
    InputValue : REAL;
END_VAR

IF sign < INT#32 THEN
    SignedValue := SIGN_R(IN := in);
    InputValue := ABS(in);
ELSE
    InputValue := in;
END_IF;

InputValue := LIMIT(MN := low, IN := InputValue, MX := high);
AOUT1 := SHL(
    UDINT_TO_DWORD(
        REAL_TO_UDINT(
            (InputValue - low) / (high - low) * UDINT_TO_REAL(DWORD_TO_UDINT(SHL(ff, Bit_N - Bit_0 + INT#1)) - UDINT#1)
        )
    ),
    Bit_0
);
IF SignedValue THEN
    AOUT1 := SHL(ff, sign) OR AOUT1;
END_IF;
END_FUNCTION

