FUNCTION SDD : REAL
VAR_INPUT
	T : REAL;
	ICE: BOOL;
END_VAR
IF ice THEN
	SDD := 611.153 * EXP(22.4433 * T / (272.186 + T));
ELSE
	SDD := 611.213 * EXP(17.5043 * T / (241.2 + T));
END_IF;
END_FUNCTION

FUNCTION SDD_NH3 : REAL
VAR_INPUT
	T : REAL;
END_VAR
IF T < -33.65 THEN
	SDD_NH3 := EXP(7.3396511649 - ( 1166.7498002 / ( T + 192.37 )));
ELSE
	SDD_NH3 := EXP(11.210964456 - ( 2564.9140075 / ( T + 262.741 )));
END_IF;
END_FUNCTION

FUNCTION SDT_NH3 : REAL
VAR_INPUT
	P : REAL;
END_VAR
IF P < 1.0E-3 THEN
	SDT_NH3 := -110.0;
ELSIF P < 1.0 THEN
	SDT_NH3 := 506.713 / (3.18757 - LOG(P)) - 192.37 ;
ELSE
	SDT_NH3 := 1113.928 / (4.86886 - LOG(P)) - 262.71 ;
END_IF;
END_FUNCTION

FUNCTION_BLOCK T_AVG24
VAR_INPUT
	TS : INT;
	DTI : DT;
	RST : BOOL;
END_VAR
VAR_INPUT CONSTANT
	T_FILTER : TIME := T#10m;
	SCALE : REAL := 1.0;
	OFS : REAL;
END_VAR
VAR_OUTPUT
	TA : REAL;
	TP : BOOL;
END_VAR
VAR_IN_OUT
	T24 : REAL;
	T24_MAX : REAL;
	T24_MIN : REAL;
END_VAR
VAR
	samples : ARRAY[0..47] OF INT;
	pos : INT;
	init: BOOL;
	ft1 : FILTER_I;
	sum : DINT;
	last: DT;
END_VAR
VAR_TEMP
	tmp_max : INT;
	tmp_min : INT;
	i: INT;
	MinuteOfDay : INT;
END_VAR
ft1(X := TS, T := T_FILTER);
IF rst OR NOT init THEN
	init := TRUE;
	IF T24 = -1000.0 THEN t24 := INT_TO_REAL(ft1.Y) * 0.1; END_IF;
	FOR pos := 0 TO 47 DO
		samples[pos] := REAL_TO_INT(T24 * 10.0);
	END_FOR;
	pos := 0;
	sum := INT_TO_DINT(samples[0]) * 48;
	TA := (INT_TO_REAL(ft1.Y) * 0.1 + OFS) * SCALE;
	T24 := (DINT_TO_REAL(sum) * 0.00208333333333 + OFS) * SCALE;
	tp := TRUE;
ELSIF DTI > last THEN
	MinuteOfDay := HOUR(DT_TO_TOD(DTI)) * 60 + MINUTE(DT_TO_TOD(DTI));
	IF MinuteOfDay MOD 30 = 0 THEN
		last := ADD_DT_TIME(DTI, T#1m);
		sum := sum - INT_TO_DINT(samples[pos]);
		samples[pos] := ft1.Y;
		sum := sum + INT_TO_DINT(samples[pos]);
		pos := INC1(pos, 48);
		TA := (INT_TO_REAL(ft1.Y) * 0.1 + OFS) * SCALE;
		T24 := (DINT_TO_REAL(sum) * 0.00208333333333 + OFS) * SCALE;
		tmp_max := -32000;
		tmp_min := 32000;
		FOR i := 0 TO 47 DO
			tmp_max := MAX(tmp_max, samples[i]);
			tmp_min := MIN(tmp_min, samples[i]);
		END_FOR;
		T24_MAX := (INT_TO_REAL(tmp_max) * 0.1 + OFS) * SCALE;
		T24_MIN := (INT_TO_REAL(tmp_min) * 0.1 + OFS) * SCALE;
		tp := TRUE;
	ELSE
		tp := FALSE;
	END_IF;
ELSE
	tp := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TANK_LEVEL
VAR_INPUT
    LEVEL : BOOL;
    LEAK : BOOL;
    ACLR : BOOL;
END_VAR
VAR_INPUT CONSTANT
    MAX_VALVE_TIME : TIME;
    LEVEL_DELAY_TIME : TIME;
END_VAR
VAR_OUTPUT
    VALVE : BOOL;
    ALARM : BOOL;
    STATUS : BYTE;
END_VAR
VAR
    cx : ACTUATOR_COIL;
    tn : TON;
    tl : TONOF;
    open : BOOL;
END_VAR

tl(in := level, T_ON := level_delay_time, T_OFF := level_delay_time);
open := tl.Q;
IF ALARM THEN
    IF ACLR THEN
        ALARM := FALSE;
        STATUS := BYTE#101;
        cx(in := FALSE);
    END_IF;
ELSE
    IF LEAK THEN
        cx(in := FALSE);
        ALARM := TRUE;
        STATUS := BYTE#1;
    ELSIF open THEN
        cx(in := TRUE);
        STATUS := BYTE#102;
    ELSE
        cx(in := FALSE);
        STATUS := BYTE#100;
    END_IF;
    tn(in := cx.OUT AND (MAX_VALVE_TIME > T#0s), PT := MAX_VALVE_TIME);
    IF tn.Q THEN
        ALARM := TRUE;
        STATUS := BYTE#2;
        cx(in := FALSE);
    END_IF;
    VALVE := cx.OUT;
END_IF;
END_FUNCTION_BLOCK

