    Q0 : BOOL;
    Q1 : BOOL;
    Q2 : BOOL;
    Q3 : BOOL;
END_VAR
VAR
    off : TON;
    edge : BOOL;
END_VAR
IF RST OR off.Q THEN
    SN := 0;
ELSIF IN AND NOT edge THEN
    SN := SN + 1;
    IF SN > 4 THEN
        SN := 0;
    END_IF;
END_IF;
edge := IN;
Q0 := FALSE;
Q1 := FALSE;
Q2 := FALSE;
Q3 := FALSE;
CASE SN OF
    1:
        Q0 := TRUE;
    2:
        Q0 := TRUE;
        Q1 := TRUE;
    3:
        Q0 := TRUE;
        Q1 := TRUE;
        Q2 := TRUE;
    4:
        Q0 := TRUE;
        Q1 := TRUE;
        Q2 := TRUE;
        Q3 := TRUE;
END_CASE;
IF Timeout > T#0s THEN
    off(IN := SN > 0, PT := Timeout);
END_IF;
