FUNCTION_BLOCK FLOW_CONTROL
VAR_INPUT
    IN : BOOL;
    REQ : BOOL;
    ENQ : BOOL;
    RST : BOOL;
END_VAR
VAR_INPUT CONSTANT
    T_AUTO : TIME := T#1h;
    T_DELAY : TIME := T#23h;
END_VAR
VAR_OUTPUT
    Q : BOOL;
    STATUS : BYTE;
END_VAR
VAR
    timer : TP_1D;
    TimerReq : BOOL;
END_VAR
STATUS := BYTE#100;
TimerReq := FALSE;
IF RST THEN
    Q := FALSE;
    STATUS := BYTE#103;
ELSIF ENQ THEN
    IF IN THEN
        STATUS := BYTE#101;
    END_IF;
    IF REQ THEN
        TimerReq := TRUE;
        STATUS := BYTE#102;
    END_IF;
END_IF;
timer(IN := TimerReq, PT1 := T_AUTO, PTD := T_DELAY, RST := RST);
Q := (IN AND ENQ) OR timer.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_Profile
VAR_INPUT
    K : REAL := 1.0;
    O : REAL;
    M : REAL := 1.0;
    E : BOOL;
END_VAR
VAR_INPUT CONSTANT
    value_0 : REAL;
    time_1 : TIME;
    value_1 : REAL;
    time_2 : TIME;
    value_2 : REAL;
    time_3 : TIME;
    value_3 : REAL;
    time_10 : TIME;
    value_10 : REAL;
    time_11 : TIME;
    value_11 : REAL;
    time_12 : TIME;
    value_12 : REAL;
    time_13 : TIME;
    value_13 : REAL;
END_VAR
VAR_OUTPUT
    Y : REAL;
    RUN : BOOL;
    ET : TIME;
END_VAR
VAR
    tx : DWORD;
    edge : BOOL;
    state : INT;
    ta : DWORD;
    tb : DWORD;
    t0 : DWORD;
    temp : REAL;
    va : REAL;
    vb : REAL;
    ElapsedMs : UDINT;
END_VAR

tx := T_PLC_MS();
IF E AND NOT edge THEN
    RUN := TRUE;
    ET := T#0s;
    t0 := tx;
    ta := tx;
    tb := TIME_TO_DWORD(multime(time_1, M));
    va := value_0;
    vb := value_1;
    temp := value_0;
    state := 1;
END_IF;
edge := E;
IF run THEN
    ElapsedMs := DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(ta);
    CASE state OF
        1:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_2, time_1), M));
                va := value_1;
                vb := value_2;
                temp := value_1;
                state := 2;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        2:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_3, time_2), M));
                va := value_2;
                vb := value_3;
                temp := value_2;
                state := 3;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        3:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_10, time_3), M));
                va := value_3;
                vb := value_10;
                temp := value_3;
                state := 4;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        4:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_11, time_10), M));
                va := value_10;
                vb := value_11;
                temp := value_10;
                IF E THEN
                    state := 5;
                ELSE
                    state := 6;
                END_IF;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        5:
            IF E THEN
                ta := tx;
            ELSE
                state := 6;
            END_IF;
        6:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_12, time_11), M));
                va := value_11;
                vb := value_12;
                temp := value_11;
                state := 7;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        7:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                ta := tx;
                tb := TIME_TO_DWORD(multime(SUB_TIME(time_13, time_12), M));
                va := value_12;
                vb := value_13;
                temp := value_12;
                state := 8;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
        8:
            IF ElapsedMs >= DWORD_TO_UDINT(tb) THEN
                temp := value_13;
                run := FALSE;
            ELSIF DWORD_TO_UDINT(tb) > UDINT#0 THEN
                temp := ((vb - va) * UDINT_TO_REAL(ElapsedMs) / DWORD_TO_REAL(tb) + va);
            ELSE
                temp := vb;
            END_IF;
    END_CASE;
    Y := temp * K + O;
    ET := DWORD_TO_TIME(UDINT_TO_DWORD(DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(t0)));
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INC_DEC
VAR_INPUT
	CHa : BOOL;
	CHb : BOOL;
	RST : BOOL;
END_VAR
VAR_OUTPUT
	dir : BOOL;
	cnt : INT;
END_VAR
VAR
	edgea : BOOL;
	clk: BOOL;
	clka: BOOL;
	clkb: BOOL;
	edgeb: BOOL;
	axb: BOOL;
END_VAR
axb := cha XOR chb;
clka := cha XOR edgea;
edgea := cha;
clkb := chb XOR edgeb;
edgeb := chb;
clk := clka OR clkb;
IF axb AND clka THEN dir := TRUE; END_IF;
IF axb AND clkb THEN dir := FALSE; END_IF;
IF clk AND dir THEN cnt := cnt + 1; END_IF;
IF clk AND NOT dir THEN cnt := cnt -1; END_IF;
IF rst THEN cnt := 0; END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INTERLOCK
