	Q1, Q2 : BOOL;
END_VAR
VAR
	T1, T2 : TOF;
END_VAR
T1(IN := I1, PT := TL);
T2(IN := I2, PT := TL);
Q1 := I1 AND NOT t2.Q;
Q2 := I2 AND NOT t1.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK INTERLOCK_4
VAR_INPUT CONSTANT
END_VAR
VAR_INPUT
    I0 : BOOL;
    I1 : BOOL;
    I2 : BOOL;
    I3 : BOOL;
    E : BOOL;
    MODE : INT;
END_VAR
VAR_OUTPUT
    OUT : BYTE;
    TP : BOOL;
END_VAR
VAR
    InValue : BYTE;
    Changed : BYTE;
    Last : BYTE;
    Old : BYTE;
    LMode : INT;
END_VAR
IF E THEN
    IF MODE <> LMode THEN
        OUT := BYTE#0;
        Last := BYTE#0;
        Old := BYTE#0;
        LMode := MODE;
    END_IF;
    InValue := BYTE#0;
    IF I0 THEN InValue := InValue OR BYTE#1; END_IF;
    IF I1 THEN InValue := InValue OR BYTE#2; END_IF;
    IF I2 THEN InValue := InValue OR BYTE#4; END_IF;
    IF I3 THEN InValue := InValue OR BYTE#8; END_IF;
    IF InValue <> Last THEN
        CASE MODE OF
            0:
                OUT := InValue;
            1:
                IF (InValue AND BYTE#8) <> BYTE#0 THEN OUT := BYTE#8;
                ELSIF (InValue AND BYTE#4) <> BYTE#0 THEN OUT := BYTE#4;
                ELSIF (InValue AND BYTE#2) <> BYTE#0 THEN OUT := BYTE#2;
                ELSE OUT := InValue;
                END_IF;
            2:
                Changed := (InValue XOR Last) AND InValue;
                IF (Changed AND BYTE#8) <> BYTE#0 THEN OUT := BYTE#8;
                ELSIF (Changed AND BYTE#4) <> BYTE#0 THEN OUT := BYTE#4;
                ELSIF (Changed AND BYTE#2) <> BYTE#0 THEN OUT := BYTE#2;
                ELSE OUT := Changed;
                END_IF;
            3:
                IF (OUT AND InValue) = BYTE#0 THEN
                    IF (InValue AND BYTE#8) <> BYTE#0 THEN OUT := BYTE#8;
                    ELSIF (InValue AND BYTE#4) <> BYTE#0 THEN OUT := BYTE#4;
                    ELSIF (InValue AND BYTE#2) <> BYTE#0 THEN OUT := BYTE#2;
                    ELSE OUT := InValue;
                    END_IF;
                END_IF;
        END_CASE;
        Last := InValue;
    END_IF;
    TP := OUT <> Old;
    Old := OUT;
ELSE
    OUT := BYTE#0;
    Last := BYTE#0;
    Old := BYTE#0;
    LMode := 0;
    TP := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION MANUAL : BOOL
