FUNCTION_BLOCK DerivativeFilter IMPLEMENTS IComponent
VAR
    ReadyValue : BOOL;
    ErrorValue : BOOL;
    ErrorIdValue : WORD;
    StatusValue : BYTE;
    OutputValue : REAL;
    GainValue : REAL := REAL#1.0;
    LastSample : REAL;
    LastTime : DWORD;
    Initialized : BOOL;
END_VAR

METHOD PUBLIC Initialize
ReadyValue := TRUE;
ClearError();
END_METHOD

METHOD PUBLIC Reset
Initialized := FALSE;
OutputValue := REAL#0.0;
ClearError();
END_METHOD

METHOD PUBLIC ClearError
ErrorValue := FALSE;
ErrorIdValue := ComponentErrorNone;
StatusValue := BYTE#0;
END_METHOD

METHOD PUBLIC Snapshot : ComponentStatus
VAR
    Result : ComponentStatus;
END_VAR
Result.Ready := ReadyValue;
Result.Error := ErrorValue;
Result.ErrorId := ErrorIdValue;
Result.Status := StatusValue;
Snapshot := Result;
END_METHOD

METHOD PUBLIC Configure
VAR_INPUT
    Gain : REAL;
END_VAR
GainValue := Gain;
ClearError();
END_METHOD

METHOD PUBLIC Update : REAL
VAR_INPUT
    Sample : REAL;
END_VAR
VAR
    NowTime : DWORD;
    DeltaUs : REAL;
END_VAR
NowTime := T_PLC_US();
DeltaUs := UDINT_TO_REAL(DWORD_TO_UDINT(NowTime) - DWORD_TO_UDINT(LastTime));
IF NOT Initialized THEN
    Initialized := TRUE;
    LastSample := Sample;
    OutputValue := REAL#0.0;
ELSIF DeltaUs > REAL#0.0 THEN
    OutputValue := (Sample - LastSample) / DeltaUs * REAL#1000000.0 * GainValue;
    LastSample := Sample;
ELSE
    OutputValue := REAL#0.0;
END_IF;
LastTime := NowTime;
Update := OutputValue;
END_METHOD

PUBLIC PROPERTY Ready : BOOL
GET
    Ready := ReadyValue;
END_GET
END_PROPERTY

PUBLIC PROPERTY Error : BOOL
GET
    Error := ErrorValue;
END_GET
END_PROPERTY

PUBLIC PROPERTY ErrorId : WORD
GET
    ErrorId := ErrorIdValue;
END_GET
END_PROPERTY

PUBLIC PROPERTY Status : BYTE
GET
    Status := StatusValue;
END_GET
END_PROPERTY

PUBLIC PROPERTY Output : REAL
GET
    Output := OutputValue;
END_GET
END_PROPERTY
END_FUNCTION_BLOCK

