FUNCTION_BLOCK PumpDrive IMPLEMENTS IPump
VAR
    IdValue : INT;
    FaultValue : BOOL;
    RemoteValue : BOOL := TRUE;
    RunningValue : BOOL;
    RuntimeValue : REAL;
    SpeedValue : REAL;
    ReadyValue : BOOL;
    ErrorValue : BOOL;
    ErrorIdValue : WORD;
    StatusValue : BYTE;
    RuntimeMeter : OntimeMeter;
END_VAR

METHOD PUBLIC Configure
VAR_INPUT
    PumpId : INT;
    RuntimeHoursInitial : REAL;
    Faulted : BOOL;
END_VAR
IdValue := PumpId;
RuntimeValue := RuntimeHoursInitial;
FaultValue := Faulted;
END_METHOD

METHOD PUBLIC Initialize
ReadyValue := TRUE;
RuntimeMeter.Initialize();
RuntimeMeter.Reset();
ClearError();
END_METHOD

METHOD PUBLIC Reset
RunningValue := FALSE;
SpeedValue := REAL#0.0;
ClearError();
END_METHOD

METHOD PUBLIC ClearError
ErrorValue := FALSE;
ErrorIdValue := WORD#0;
StatusValue := BYTE#0;
END_METHOD

METHOD PUBLIC Snapshot : ComponentStatus
VAR
    Result : ComponentStatus;
END_VAR
Result.Ready := ReadyValue;
Result.Error := ErrorValue;
Result.ErrorId := ErrorIdValue;
Result.Status := StatusValue;
Snapshot := Result;
END_METHOD

METHOD PUBLIC Run
VAR_INPUT
    SpeedReference : REAL;
END_VAR
IF NOT FaultValue AND RemoteValue THEN
    RunningValue := TRUE;
    SpeedValue := LIMIT(REAL#0.0, SpeedReference, REAL#100.0);
ELSE
    RunningValue := FALSE;
    SpeedValue := REAL#0.0;
END_IF;
RuntimeMeter.Update(Input := RunningValue);
END_METHOD

METHOD PUBLIC Stop
RunningValue := FALSE;
SpeedValue := REAL#0.0;
RuntimeMeter.Update(Input := FALSE);
END_METHOD

