FUNCTION_BLOCK SignalConditioningPipeline
VAR
    Tc1 : RawAnalogInput;
    Tc2 : RawAnalogInput;
    Tc3 : RawAnalogInput;
    Voted : VotingDecorator;
    Clamped : RangeClampDecorator;
    SpikeRejected : SpikeRejectDecorator;
    Filtered : Pt1SignalDecorator;
    Conditioned : ISignalSource;
END_VAR

METHOD PUBLIC Initialize
Tc1.Initialize();
Tc2.Initialize();
Tc3.Initialize();
Voted.Initialize();
Clamped.Initialize();
SpikeRejected.Initialize();
Filtered.Initialize();
Voted.SetSources(First := Tc1, Second := Tc2, Third := Tc3);
Clamped.Wrap(InnerSource := Voted, Minimum := REAL#0.0, Maximum := REAL#400.0);
SpikeRejected.Wrap(InnerSource := Clamped, MaxStep := REAL#25.0);
Filtered.Wrap(InnerSource := SpikeRejected, TimeConstant := T#1s);
Conditioned := Filtered;
END_METHOD

METHOD PUBLIC Update : REAL
VAR_INPUT
    Input1 : REAL;
    Quality1 : BYTE;
    Input2 : REAL;
    Quality2 : BYTE;
    Input3 : REAL;
    Quality3 : BYTE;
END_VAR
Tc1.Configure(InputValue := Input1, InputQuality := Quality1);
Tc2.Configure(InputValue := Input2, InputQuality := Quality2);
Tc3.Configure(InputValue := Input3, InputQuality := Quality3);
Conditioned.Update();
Update := Conditioned.Value;
END_METHOD

PUBLIC PROPERTY ConditionedValue : REAL
GET
    ConditionedValue := Conditioned.Value;
END_GET
END_PROPERTY

PUBLIC PROPERTY Quality : BYTE
GET
    Quality := Conditioned.Quality;
END_GET
END_PROPERTY

PUBLIC PROPERTY RejectedCount : INT
GET
    RejectedCount := SpikeRejected.RejectedCount;
END_GET
END_PROPERTY

PUBLIC PROPERTY ClampFault : BOOL
GET
    ClampFault := Clamped.ClampFault;
END_GET
END_PROPERTY
END_FUNCTION_BLOCK

(* Scan role: Main wires the example objects and exposes the PLC call path under test. *)
PROGRAM Main
VAR
    Conditioning : SignalConditioningPipeline;
    Tc1Raw : INT;
    Tc2Raw : INT;
    Tc3Raw : INT;
    ConditionedRaw : INT;
    GoodQualityOut : BOOL;
END_VAR

Conditioning.Initialize();
ConditionedRaw := REAL_TO_INT(Conditioning.Update(Input1 := INT_TO_REAL(Tc1Raw), Quality1 := BYTE#2, Input2 := INT_TO_REAL(Tc2Raw), Quality2 := BYTE#2, Input3 := INT_TO_REAL(Tc3Raw), Quality3 := BYTE#2));
GoodQualityOut := Conditioning.Quality = BYTE#2;
END_PROGRAM

FUNCTION_BLOCK ClassicTemperatureConditioning
VAR
    Filter : Pt1Filter;
    LastGoodValue : REAL;
    HasLastGood : BOOL;
    RejectedCountValue : INT;
    QualityValue : BYTE;
    ClampFaultValue : BOOL;
    ConditionedValueValue : REAL;
END_VAR

METHOD PUBLIC Initialize
Filter.Initialize();
Filter.Configure(TimeConstant := T#1s, Gain := REAL#1.0);
LastGoodValue := REAL#0.0;
HasLastGood := FALSE;
RejectedCountValue := INT#0;
QualityValue := BYTE#0;
ClampFaultValue := FALSE;
ConditionedValueValue := REAL#0.0;
END_METHOD

METHOD PUBLIC Update : REAL
VAR_INPUT
    Input1 : REAL;
    Quality1 : BYTE;
    Input2 : REAL;
    Quality2 : BYTE;
    Input3 : REAL;
    Quality3 : BYTE;
END_VAR
VAR
    VotedValue : REAL;
    VotedQuality : BYTE;
    ClampedValue : REAL;
    ClampedQuality : BYTE;
END_VAR
IF (Quality1 = BYTE#2) AND (Quality2 = BYTE#2) THEN
    VotedValue := (Input1 + Input2) / REAL#2.0;
    VotedQuality := BYTE#2;
ELSIF (Quality1 = BYTE#2) AND (Quality3 = BYTE#2) THEN
    VotedValue := (Input1 + Input3) / REAL#2.0;
    VotedQuality := BYTE#2;
ELSIF (Quality2 = BYTE#2) AND (Quality3 = BYTE#2) THEN
    VotedValue := (Input2 + Input3) / REAL#2.0;
    VotedQuality := BYTE#2;
ELSE
    VotedQuality := BYTE#0;
END_IF;

ClampFaultValue := FALSE;
IF VotedValue < REAL#0.0 THEN
    ClampedValue := REAL#0.0;
    ClampedQuality := BYTE#0;
    ClampFaultValue := TRUE;
ELSIF VotedValue > REAL#400.0 THEN
    ClampedValue := REAL#400.0;
    ClampedQuality := BYTE#0;
    ClampFaultValue := TRUE;
ELSE
    ClampedValue := VotedValue;
    ClampedQuality := VotedQuality;
END_IF;

IF ClampedQuality <> BYTE#2 THEN
    ConditionedValueValue := ClampedValue;
    QualityValue := ClampedQuality;
ELSIF HasLastGood AND (ABS(ClampedValue - LastGoodValue) > REAL#25.0) THEN
    ConditionedValueValue := LastGoodValue;
    QualityValue := BYTE#1;
    RejectedCountValue := RejectedCountValue + INT#1;
ELSE
    LastGoodValue := ClampedValue;
    HasLastGood := TRUE;
    ConditionedValueValue := Filter.Update(Sample := ClampedValue);
    QualityValue := BYTE#2;
END_IF;
Update := ConditionedValueValue;
END_METHOD

PUBLIC PROPERTY ConditionedValue : REAL
GET
    ConditionedValue := ConditionedValueValue;
END_GET
END_PROPERTY

PUBLIC PROPERTY Quality : BYTE
GET
    Quality := QualityValue;
END_GET
END_PROPERTY

PUBLIC PROPERTY RejectedCount : INT
GET
    RejectedCount := RejectedCountValue;
END_GET
END_PROPERTY

PUBLIC PROPERTY ClampFault : BOOL
GET
    ClampFault := ClampFaultValue;
END_GET
END_PROPERTY
END_FUNCTION_BLOCK

PROGRAM Main
VAR
    Conditioning : ClassicTemperatureConditioning;
    Value : REAL;
END_VAR
Conditioning.Initialize();
Value := Conditioning.Update(Input1 := REAL#100.0, Quality1 := BYTE#2, Input2 := REAL#101.0, Quality2 := BYTE#2, Input3 := REAL#100.5, Quality3 := BYTE#2);
END_PROGRAM

