VAR_INPUT
    LiftCommand : BOOL;
    TravelCommand : BOOL;
    LowerCommand : BOOL;
    UpperLimit : BOOL;
    Overload : BOOL;
    DriveFault : BOOL;
END_VAR
IF DriveFault OR Overload THEN
    OnExecute := INT#90;
ELSIF LiftCommand AND NOT UpperLimit THEN
    OnExecute := INT#10;
ELSIF TravelCommand THEN
    OnExecute := INT#20;
ELSIF LowerCommand THEN
    OnExecute := INT#30;
ELSE
