NAMESPACE DemoLib
FUNCTION Add : DINT
VAR_INPUT
    A : DINT;
    B : DINT;
END_VAR
Add := A + B;
END_FUNCTION

FUNCTION SwapDint : BOOL
VAR_IN_OUT
    A : DINT;
    B : DINT;
END_VAR
VAR_TEMP
    temp : DINT;
END_VAR
temp := A;
A := B;
B := temp;
SwapDint := TRUE;
END_FUNCTION

FUNCTION_BLOCK FB_Accumulator
VAR_INPUT
    In : DINT;
END_VAR
VAR_OUTPUT
    Sum : DINT;
    StatusByte : BYTE;
    StatusBit : BOOL;
END_VAR
VAR
    status : WORD := WORD#16#1234;
END_VAR
Sum := Sum + In;
StatusBit := status.%X0;
StatusByte := status.%B1;
status.%B0 := BYTE#16#FF;
END_FUNCTION_BLOCK
END_NAMESPACE

PROGRAM MainProg
VAR
    motor : DemoImpl.Motor;
    sensor : DemoTypes.Sensor;
    values : DemoTypes.ValueArray;
    acc : DemoLib.FB_Accumulator;
    sum : DINT := 0;
    total : DINT := 0;
    sensor_size : DINT := 0;
    sensor_type_size : DINT := 0;
    values_size : DINT := 0;
    acc_status_byte : BYTE;
    acc_status_bit : BOOL;
    color : Color := Color#Red;
    swap_a : DINT := 10;
    swap_b : DINT := 20;
    ok : BOOL := FALSE;
END_VAR

ok := motor.Start(100);
motor.Speed := 100;
ok := motor.Stop();

sensor.id := 1;
sensor.label := 'Main';
sensor.active := TRUE;
sensor.value := REAL#12.5;
sensor_size := SIZEOF(sensor);
sensor_type_size := SIZEOF(DemoTypes.Sensor);

values[0] := DINT#1;
values[1] := DINT#2;
values[2] := DINT#3;
values[3] := DINT#4;
values_size := SIZEOF(values);

sum := DemoLib.Add(A := values[0], B := values[1]);
acc(In := sum);
total := acc.Sum;
acc_status_byte := acc.StatusByte;
acc_status_bit := acc.StatusBit;
ok := DemoLib.SwapDint(swap_a, swap_b);

IF ok THEN
    total := total + swap_a + swap_b;
    color := Color#Green;
END_IF;
END_PROGRAM

TYPE Color :
(
    Red := 0,
    Green := 1,
    Blue := 2
);
END_TYPE

NAMESPACE DemoTypes
TYPE Sensor :
STRUCT
    id : DINT;
    label : STRING[32];
    active : BOOL;
    value : REAL;
END_STRUCT
END_TYPE

TYPE ValueArray : ARRAY[0..3] OF DINT; END_TYPE
END_NAMESPACE

TYPE
    Phase : (IDLE, RUNNING, DONE);
    Payload : STRUCT
        count : DINT;
        flag : BOOL;
    END_STRUCT;
END_TYPE

FUNCTION_BLOCK Bump
VAR_INPUT
    IN : DINT;
END_VAR
VAR_OUTPUT
    OUT : DINT;
END_VAR
OUT := IN + DINT#1;
END_FUNCTION_BLOCK

PROGRAM Main
VAR
    in0 AT %IX0.0 : BOOL;
    out0 AT %QX0.0 : BOOL;
    out_word AT %QW2 : WORD;
    phase : Phase := Phase#IDLE;
    payload : Payload;
    samples : ARRAY[0..2] OF DINT;
    fb : Bump;
    ref_count : REF_TO DINT;
END_VAR
VAR RETAIN
    retained_count : DINT := DINT#5;
END_VAR

ref_count := REF(payload.count);

IF in0 THEN
    phase := RUNNING;
    samples[0] := DINT#7;
    samples[1] := samples[0] + DINT#2;
    samples[2] := samples[1] + DINT#3;
    ref_count^ := samples[2];
    payload.flag := TRUE;
    fb(IN := payload.count);
    retained_count := retained_count + fb.OUT;
    out0 := payload.flag;
    out_word := WORD#16#1234;
ELSE
    phase := IDLE;
    payload.flag := FALSE;
    out0 := FALSE;
    out_word := WORD#0;
END_IF
END_PROGRAM

