*)
FUNCTION BYTE_TO_STRH : STRING(2)
VAR_INPUT
	IN : BYTE;
END_VAR
VAR
	temp : BYTE;
	PT : POINTER TO BYTE;
END_VAR
(* read pointer to output string *)
PT := ADR(BYTE_TO_STRH);
(* calculate high order hex value *)
temp := SHR(in,4);
(* convert value to hex character *)
