				Time duration for on duty output.
			</summary>
		</docu>
	~*)
	inOnTime : TIME;

	(*~
		<docu>
			<summary>
				Time duration for off duty output.
			</summary>
		</docu>
	~*)
	inOffTime : TIME;
END_VAR
VAR_OUTPUT	
	outQ : BOOL;
END_VAR
VAR
	{attribute 'hide'}
	_onTimer : TON;
	{attribute 'hide'}
	_offTimer : TON;
	{attribute 'hide'}
	_nextExpectedCycle : ULINT;
	{attribute 'hide'}
	_state : INT;
END_VAR
IF(THIS^.Context.StartCycleCount <>  _nextExpectedCycle) THEN
	_state := 0;
END_IF

_nextExpectedCycle := THIS^.Context.StartCycleCount + 1;


IF(_state = 0) THEN
		_offTimer(IN := FALSE);	
		_onTimer(IN := FALSE);
		_state := 1;
END_IF;		

IF(_state = 1) THEN
		_onTimer(IN := TRUE, PT:=inOnTime);
		outQ := TRUE;
		IF(_onTimer.Q) THEN
			_state := 2;
			RETURN;
 		END_IF;
END_IF;		

IF(_state = 2) THEN	
		_offTimer(IN := TRUE, PT:=inOffTime);
		outQ := FALSE;
		IF(_offTimer.Q) THEN
			_state := 0;
 		END_IF;		
END_IF
END_FUNCTION_BLOCK

