END_VAR

VAR
	{attribute 'hide'}
    _taskEnabled : BOOL;


	{attribute addProperty Name "<#Run Command#>"}
    _runCommandTask : TcoSmartFunctionKitCommand_v_4_x_x(THIS^);


	{attribute addProperty Name "<#Get last Results#>" }
