	eAxisEncoderReferenceSystem.ABSOLUTE :
		TcoAxisEncoderReferenceSystem	:=	eAxisEncoderReferenceSystem.ABSOLUTE;
		LREAL_TO_Tco_AxisEncoderReferenceSystem	:= TRUE;
	eAxisEncoderReferenceSystem.ABSOLUTE_MODULO :
