    {attribute addProperty Name "<#Halt#>"}
    _haltTask : HaltTask(THIS^);
    {attribute addProperty Name "<#Move relative#>"}
    _moveRelativeTask : MoveRelativeTask(THIS^);
    {attribute addProperty Name "<#Move absolute#>"}
    _moveAbsoluteTask : MoveAbsoluteTask(THIS^);
    {attribute addProperty Name "<#Move modulo#>"}
    _moveModuloTask : MoveModuloTask(THIS^);
END_VAR

VAR
	{attribute 'hide'}
	_sb : TcoCore.StringBuilder;
END_VAR
IF NOT __ISVALIDREF(inoAxisRef) THEN
    Messenger.Post('Invalid reference', TcoCore.eMessageCategory.ProgrammingError);
    RETURN;
END_IF

_axisRef REF= inoAxisRef;



_mcReadStatus(Axis := _axisRef, Enable := TRUE);
UpdateAxisStatus();

_overrideInternal:=_override;
IF _config.OverrideInService>0.0 AND _config.OverrideInService<=100.0 AND THIS^.IsService THEN
	_overrideInternal:=_config.OverrideInService;
	Messenger.Notify(_sb.Clear().Append('<#Drive in override mode (Reduced velocity) due service mode! Limited to #>').Append(LREAL_TO_STRING(_overrideInternal)).Append(' %').ToString()); 
END_IF


_power(inEnable := inEnable,
    inEnablePositive := inEnablePositive,
    inEnableNegative := inEnableNegative,
    inOverride := _overrideInternal,
    inIsServiceMode := THIS^.IsService);

_resetTask();

_soEResetTask();
_setPositionTask();
_homeTask();
_jog(inIsServiceMode := THIS^.IsService);
_moveVelocityTask();
_stopTask();
_haltTask();
_moveRelativeTask();
_moveAbsoluteTask();
_moveModuloTask();
_torqueTask(inIsServiceMode:= THIS^.IsService);

IF(_axisStatus.Error) THEN Messenger.Error(_sb.Clear().Append('<#Drive error no #>').Append(UDINT_TO_STRING(_axisStatus.ErrorId)).Append(' |[[0]AdvancedDiagnosticMessage]|').Append('.').Append('For details see the service mode').ToString()); END_IF;
END_FUNCTION_BLOCK

