FUNCTION_BLOCK TcoTask_DownCounter EXTENDS TcoCore.TcoTask
VAR
	_SetUpValue		:	LINT;
	_CounterValue	:	LINT := -1;
	_InvokeCounter	: LINT;
	_DoneCounter	: LINT;
END_VAR
IF(THIS^._taskState = eTaskState.Requested) THEN
	CounterValue := SetUpValue;
	_InvokeCounter := _InvokeCounter + 1; 
END_IF;

IF(Execute()) THEN
	_CounterValue := _CounterValue - 1;
	DoneWhen(_CounterValue <= 0);			
END_IF

IF(THIS^._taskState = eTaskState.Done) THEN
	_DoneCounter := _DoneCounter + 1; 
END_IF;
