FUNCTION_BLOCK TcoDesignerClearInspectionResults_v_2_x_x EXTENDS TcoCore.TcoTask
VAR_IN_OUT
	inoIoData	: TcoDesignerData_2_x_x;
    inoConfig	: TcoDesignerConfig_v_2_x_x;
	inoStatus	: TcoDesignerStatus_v_2_x_x;	
	//inoResults	: TcoInsightResults_v_5_x_x;
END_VAR
VAR
    {attribute 'hide'} 
	_progress : INT := 0;
    {attribute 'hide'} 
	_infoTimer :  TON;
    {attribute 'hide'} 
	_errorTimer :  TON;
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
END_VAR
IF Execute() THEN
	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoIoData) THEN
			_varInfo :=__VARINFO(inoIoData);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
//		ELSIF NOT __ISVALIDREF(inoResults) THEN                                              
//			_varInfo :=__VARINFO(inoResults);                                                
//			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSE
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 1 THEN
		CallTimers(FALSE);
		THIS^.inoIoData.PlcToPc.Trigger := FALSE;
		THIS^.inoIoData.PlcToPc.LoadJob := FALSE;

		THIS^.inoIoData.PlcToPc.Reset := FALSE;
		THIS^.inoIoData.PlcToPc.ResultsAck := FALSE;

		THIS^.inoIoData.PlcToPc.ClearResults:=FALSE;

		_progress := _progress + 1;
	END_IF

	IF _progress = 2 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Info('<#Reset Request!#>'); 
		THIS^.inoIoData.PlcToPc.Reset := TRUE;
		IF THIS^.inoIoData.PcToPlc.InspectionReady
			AND NOT THIS^.inoIoData.PcToPlc.ClearResultsAck
			AND NOT THIS^.inoIoData.PcToPlc.ResultsAvailable 
			AND NOT THIS^.inoIoData.PcToPlc.JobLoadDone THEN
			THIS^.inoIoData.PlcToPc.Reset := FALSE;
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 3 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Warning('<#Waiting for the Online signal!#>'); 
		IF THIS^.inoIoData.PcToPlc.SystemOnline THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 4 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Info('<#Waiting to Acknowledge results!#>'); 
		THIS^.inoIoData.PlcToPc.ResultsAck:=TRUE;
		IF NOT THIS^.inoIoData.PcToPlc.ResultsAvailable  THEN
			THIS^.inoIoData.PlcToPc.ResultsAck:=FALSE;
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 5 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Info('<#Waiting to clear old data!#>'); 
		THIS^.inoIoData.PlcToPc.ClearResults:=TRUE;

		IF  THIS^.inoIoData.PcToPlc.ClearResultsAck  THEN
			THIS^.inoIoData.PlcToPc.ClearResults:=FALSE;
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 6 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Info('<#Waiting for Inspection ready!#>'); 
		IF THIS^.inoIoData.PcToPlc.InspectionReady 
			 THEN
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress = 7 THEN	
		THIS^.Messenger.OnCondition(_infoTimer.Q).Info('<#Waiting for data were cleared!#>'); 
			IF  NOT THIS^.inoIoData.PcToPlc.ClearResultsAck
			AND NOT THIS^.inoIoData.PcToPlc.InspectionResults.ResultFail
			AND NOT THIS^.inoIoData.PcToPlc.InspectionResults.ResultPass THEN
			CallTimers(FALSE);
			THIS^.DoneWhen(TRUE);
		END_IF
	END_IF

	CallTimers(TRUE);

		THIS^.ThrowWhen(_errorTimer.Q   OR THIS^.inoIoData.PcToPlc.Error );	
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK TcoDesignerTrigger_v_2_x_x EXTENDS TcoCore.TcoTask
VAR_INPUT
	inTriggerType:eTcoDesignerTriggerType;
	refClearResultsTask: REFERENCE TO TcoDesignerClearInspectionResults_v_2_x_x;
END_VAR 

VAR
	_clearResultsTask: REFERENCE TO TcoDesignerClearInspectionResults_v_2_x_x;
END_VAR
VAR_IN_OUT
	inoIoData	: TcoDesignerData_2_x_x;
    inoConfig	: TcoDesignerConfig_v_2_x_x;
	inoStatus	: TcoDesignerStatus_v_2_x_x;	
	//inoResults	: TcoInsightResults_v_5_x_x;
END_VAR
VAR

	_progress : INT := 0;
    {attribute 'hide'} 
	_infoTimer :  TON;
    {attribute 'hide'} 
	_errorTimer :  TON;
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;

END_VAR
IF NOT __ISVALIDREF(refClearResultsTask)  THEN
    Messenger.Post('<#Invalid reference ClearResultsTask>', TcoCore.eMessageCategory.ProgrammingError);
    RETURN;
END_IF
_clearResultsTask REF= refClearResultsTask;

IF Execute() THEN
	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoIoData) THEN
			_varInfo :=__VARINFO(inoIoData);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();

		ELSIF inTriggerType = eTcoDesignerTriggerType.TriggerWithTimeout 
			AND inoConfig.ErrorTime < inoConfig.TriggerTimemout THEN
				Messenger.Error(_sb.Clear().Append('<#Error time is lower than timeout. Please check config!#>').ToString()).Pin();

		ELSE
			_progress := _progress + 1;
			CallTimers(FALSE);

		END_IF
	END_IF


	IF _progress = 1 THEN
		IF inTriggerType = eTcoDesignerTriggerType.TriggerFast THEN
			_progress := _progress + 1;
		ELSIF inTriggerType = eTcoDesignerTriggerType.TriggerWithTimeout THEN
			inoIoData.PlcToPc.Timeout:=TIME_TO_UINT( inoConfig.TriggerTimemout);
			IF _clearResultsTask.Invoke().Done THEN
				_progress := _progress + 1;
			END_IF;
		ELSIF _clearResultsTask.Invoke().Done THEN
			_progress := _progress + 1;
		END_IF

	END_IF;

	IF _progress = 2 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q).Info('<#Trigger!#>'); 
		THIS^.inoIoData.PlcToPc.Trigger:=TRUE;

		IF NOT THIS^.inoIoData.PcToPlc.InspectionReady  THEN
			THIS^.inoIoData.PlcToPc.Trigger:=FALSE;
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF


	IF _progress=3 THEN	
		Messenger.Info('Waiting for results available');
		IF THIS^.inoIoData.PcToPlc.ResultsAvailable  THEN		
			CallTimers(FALSE);
			_progress := _progress + 1;
		END_IF
	END_IF

	IF _progress=4 THEN	
		Messenger.Info('Acknovledge results');
		THIS^.inoIoData.PlcToPc.ResultsAck:=TRUE;
		IF NOT THIS^.inoIoData.PcToPlc.ResultsAvailable  THEN
			THIS^.inoIoData.PlcToPc.ResultsAck:=FALSE;
			THIS^.DoneWhen(TRUE);

		END_IF
	END_IF




	CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q  OR THIS^.inoIoData.PcToPlc.Error 
		OR (inTriggerType = eTcoDesignerTriggerType.TriggerWithTimeout AND THIS^.inoIoData.PcToPlc.TriggerTimeout) );	

END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK TcoDataman_v_5_x_x  EXTENDS TcoIo.TcoPnIoComponent IMPLEMENTS TcoAbstractions.ITcoCodeReader
VAR_IN_OUT
inoIoData : TcoDatamanIO_v_5_x_x;
END_VAR

VAR
	{attribute addProperty Name "<#Config#>"}
    _config : TcoDatamanConfig_v_5_x_x;
	{attribute addProperty Name "<#Status#>"}
	_status : TcoDatamanStatus_v_5_x_x;	
END_VAR

VAR
	{attribute addProperty Name "<#UserData#>"}
	_userData	: TcoDatamanUser_v_5_x_x;
	{attribute addProperty Name "<#Results#>"}
	_results	: TcoDatamanResults_v_5_x_x;
END_VAR

VAR
	{attribute 'hide'}
    _taskEnabled : BOOL;
	{attribute addProperty Name "<#Restore#>"}
    _restoreTask : TcoCore.TcoTask(THIS^);
	{attribute addProperty Name "<#Update signal states#>"}
    _updateSignalStatesTask : TcoCore.TcoTask(THIS^);
	{attribute addProperty Name "<#Clear result data#>"}
    _clearResultDataTask : TcoDatamanClearResultData_v_5_x_x(THIS^);
	{attribute addProperty Name "<#Read#>"}
    _readTask : TcoDatamanRead_v_5_x_x(THIS^);
END_VAR
VAR
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
END_VAR
IF InvalidReference() THEN
    RETURN;
END_IF

SUPER^(inPnIoBoxState := THIS^.inoIoData.PnIoBoxState,inPnIoBoxDiag := THIS^.inoIoData.PnIoBoxDiag);



IF THIS^._config.ContinuousReading THEN
	ContinuousReading();
END_IF

IF NOT SUPER^.ProfinetReady THEN
	THIS^._status.ActionDescription := '<#Not ready for operation by means of Profinet network!#>';	
END_IF

IF SUPER^.ProfinetReady AND THIS^._status.ActionDescription = '<#Not ready for operation by means of Profinet network!#>' THEN
	THIS^._status.ActionDescription := '<#Ready for operation!#>';	
END_IF

//*************RESTORE********************
_taskEnabled := TRUE;
_restoreTask.Enabled := _taskEnabled;
IF _restoreTask.Execute() THEN
	Restore();
END_IF
//****************************************

//*************UPDATE*********************
IF _config.UpdateStatesPermanently THEN
	UpdateSignalStates();
END_IF;
_taskEnabled := SUPER^.ProfinetReady;
_updateSignalStatesTask.Enabled := _taskEnabled AND NOT _config.UpdateStatesPermanently ;
IF _updateSignalStatesTask.Execute() THEN
	UpdateSignalStates();
END_IF

//****************************************

//*************CLEAR*DATA*****************
_taskEnabled := SUPER^.ProfinetReady AND  NOT _readTask.Busy;
_clearResultDataTask.Enabled := _taskEnabled;
_clearResultDataTask(inoIoData := THIS^.inoIoData,inoConfig := THIS^._config,inoStatus := THIS^._status,inoResults := THIS^._results);
//****************************************

//*************READ***********************
_taskEnabled := SUPER^.ProfinetReady AND NOT _clearResultDataTask.Busy;
_readTask.Enabled :=  _taskEnabled;
_readTask(inoIoData := THIS^.inoIoData,inoConfig := THIS^._config,inoStatus := THIS^._status,inoResults := THIS^._results);

IF NOT _readTask.Busy AND NOT _readTask.Error 
	AND NOT _clearResultDataTask.Busy AND NOT _clearResultDataTask.Error THEN
	_status.ResultString := GetResultAsString(0,_status.SignalStatus.ResultLength);
END_IF;
//****************************************
END_FUNCTION_BLOCK

