FUNCTION_BLOCK FastCounter EXTENDS TcoCore.TcoTask
VAR
	Counter : INT;	
	_counterProgressCheck :INT;
	_await : fbAwait;
END_VAR
IF Execute() THEN 


	IF _await.Delay(T#50MS) THEN
		Counter := Counter +1;
		_counterProgressCheck := Counter;
	END_IF

ThrowWhen(_counterProgressCheck > Counter);
	DoneWhen(Counter = 100);

END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK SlowCounter EXTENDS TcoCore.TcoTask
VAR
	Counter : INT;
	_await : fbAwait;
END_VAR
IF Execute() THEN 
	IF _await.Delay(T#250MS) THEN
		Counter := Counter +1;
	END_IF
	DoneWhen(Counter = 100);
END_IF
END_FUNCTION_BLOCK

