FUNCTION TRUST_SYNC_ProcessActiveCommand : BOOL
VAR_INPUT
    SlaveIndex : UINT;
END_VAR
VAR
    MasterIndex : UINT;
    SourcePosition : REAL;
    PreviousSource : REAL;
    StartThreshold : REAL;
    TargetPosition : REAL;
    Ratio : REAL;
    LastPoint : INT;
    EffectiveMaster : REAL;
    ProfileEnd : REAL;
END_VAR
TRUST_SYNC_ProcessActiveCommand := FALSE;
g_trust_sync_active_start_sync_pulse[SlaveIndex] := FALSE;
g_trust_sync_active_end_of_profile_pulse[SlaveIndex] := FALSE;
IF g_trust_sync_active_command_id[SlaveIndex] <> UINT#0 THEN
MasterIndex := g_trust_sync_active_master_axis_index[SlaveIndex];
SourcePosition := TRUST_SYNC_ReadMasterSourcePosition(
    MasterAxisIndex := MasterIndex,
    Source := g_trust_sync_active_master_value_source[SlaveIndex]
);
PreviousSource := g_trust_sync_active_previous_source_position[SlaveIndex];
CASE g_trust_sync_active_command_kind[SlaveIndex] OF
    TRUST_SYNC_COMMAND_KIND#trustSyncCamIn:
        StartThreshold := g_trust_sync_active_master_sync_position[SlaveIndex] - g_trust_sync_active_master_start_distance[SlaveIndex];
        IF (NOT g_trust_sync_active_start_sync_seen[SlaveIndex]) AND (SourcePosition >= StartThreshold) THEN
            g_trust_sync_active_start_sync_seen[SlaveIndex] := TRUE;
        END_IF;
        IF SourcePosition >= g_trust_sync_active_master_sync_position[SlaveIndex] THEN
            g_trust_sync_active_in_sync[SlaveIndex] := TRUE;
            g_trust_sync_axis_state[SlaveIndex] := MC_AXIS_STATUS#mcSynchronizedMotion;
        ELSE
            g_trust_sync_axis_state[SlaveIndex] := MC_AXIS_STATUS#mcContinuousMotion;
        END_IF;
        IF g_trust_sync_active_start_mode[SlaveIndex] = MC_START_MODE#mcAbsolute THEN
            EffectiveMaster := (SourcePosition * g_trust_sync_active_master_scaling[SlaveIndex]) + g_trust_sync_active_master_offset[SlaveIndex];
        ELSE
            EffectiveMaster := ((SourcePosition - g_trust_sync_active_command_start_master_position[SlaveIndex]) * g_trust_sync_active_master_scaling[SlaveIndex]) + g_trust_sync_active_master_offset[SlaveIndex];
        END_IF;
        LastPoint := TRUST_SYNC_CamLastPointIndex(SlaveIndex := SlaveIndex);
        ProfileEnd := REAL#0.0;
        IF LastPoint >= INT#0 THEN
            ProfileEnd := g_trust_sync_selected_cam_master[SlaveIndex, LastPoint];
        END_IF;
        IF g_trust_sync_selected_cam_periodic[SlaveIndex] AND (PreviousSource < ProfileEnd) AND (SourcePosition >= ProfileEnd) THEN
            g_trust_sync_active_end_of_profile_pulse[SlaveIndex] := TRUE;
            IF EffectiveMaster > ProfileEnd THEN
                EffectiveMaster := EffectiveMaster - ProfileEnd;
            END_IF;
        ELSIF (NOT g_trust_sync_selected_cam_periodic[SlaveIndex]) AND (PreviousSource < ProfileEnd) AND (SourcePosition >= ProfileEnd) THEN
            g_trust_sync_active_end_of_profile_pulse[SlaveIndex] := TRUE;
            EffectiveMaster := ProfileEnd;
        END_IF;
        TargetPosition := TRUST_SYNC_CamSlavePositionAt(SlaveIndex := SlaveIndex, SampleMaster := EffectiveMaster);
        TargetPosition := (TargetPosition * g_trust_sync_active_slave_scaling[SlaveIndex]) + g_trust_sync_active_slave_offset[SlaveIndex];
        IF g_trust_sync_active_in_sync[SlaveIndex] THEN
            TRUST_SYNC_ApplySlaveTarget(SlaveIndex := SlaveIndex, TargetPosition := TargetPosition);
        END_IF;
    TRUST_SYNC_COMMAND_KIND#trustSyncGearIn:
        Ratio := REAL#0.0;
        IF g_trust_sync_active_ratio_denominator[SlaveIndex] <> UINT#0 THEN
            Ratio := INT_TO_REAL(g_trust_sync_active_ratio_numerator[SlaveIndex]) / UINT_TO_REAL(g_trust_sync_active_ratio_denominator[SlaveIndex]);
        END_IF;
        TargetPosition := g_trust_sync_active_command_start_slave_position[SlaveIndex] +
            ((SourcePosition - g_trust_sync_active_command_start_master_position[SlaveIndex]) * Ratio);
        TRUST_SYNC_ApplySlaveTarget(SlaveIndex := SlaveIndex, TargetPosition := TargetPosition);
        IF SourcePosition <> g_trust_sync_active_command_start_master_position[SlaveIndex] THEN
            g_trust_sync_active_in_gear[SlaveIndex] := TRUE;
            g_trust_sync_axis_state[SlaveIndex] := MC_AXIS_STATUS#mcSynchronizedMotion;
        ELSE
            g_trust_sync_axis_state[SlaveIndex] := MC_AXIS_STATUS#mcContinuousMotion;
        END_IF;
    TRUST_SYNC_COMMAND_KIND#trustSyncGearInPos:
        StartThreshold := g_trust_sync_active_master_sync_position[SlaveIndex] - g_trust_sync_active_master_start_distance[SlaveIndex];
        IF (NOT g_trust_sync_active_start_sync_seen[SlaveIndex]) AND (SourcePosition >= StartThreshold) THEN
            g_trust_sync_active_start_sync_seen[SlaveIndex] := TRUE;
            g_trust_sync_active_start_sync_pulse[SlaveIndex] := TRUE;
        END_IF;
        IF SourcePosition >= g_trust_sync_active_master_sync_position[SlaveIndex] THEN
            Ratio := REAL#0.0;
            IF g_trust_sync_active_ratio_denominator[SlaveIndex] <> UINT#0 THEN
                Ratio := INT_TO_REAL(g_trust_sync_active_ratio_numerator[SlaveIndex]) / UINT_TO_REAL(g_trust_sync_active_ratio_denominator[SlaveIndex]);
            END_IF;
            TargetPosition := g_trust_sync_active_slave_sync_position[SlaveIndex] +
                ((SourcePosition - g_trust_sync_active_master_sync_position[SlaveIndex]) * Ratio);
            TRUST_SYNC_ApplySlaveTarget(SlaveIndex := SlaveIndex, TargetPosition := TargetPosition);
            g_trust_sync_active_in_sync[SlaveIndex] := TRUE;
            g_trust_sync_axis_state[SlaveIndex] := MC_AXIS_STATUS#mcSynchronizedMotion;
        ELSE
            g_trust_sync_axis_state[SlaveIndex] := MC_AXIS_STATUS#mcContinuousMotion;
        END_IF;
END_CASE;
g_trust_sync_active_previous_source_position[SlaveIndex] := SourcePosition;
TRUST_SYNC_ProcessActiveCommand := TRUE;
END_IF;
END_FUNCTION

FUNCTION_BLOCK TRUST_SYNC_TestSeed
VAR_IN_OUT
    Master : AXIS_REF;
    Slave : AXIS_REF;
END_VAR
VAR_INPUT
    StartPosition : REAL;
    ExitPosition : REAL;
    RatioNumerator : REAL;
    RatioDenominator : REAL;
    PhaseOffset : REAL;
    LoadDefaultCam : BOOL;
END_VAR
VAR
    MasterIndex : UINT;
    SlaveIndex : UINT;
END_VAR
MasterIndex := TRUST_SYNC_AxisIndex(Axis := Master);
SlaveIndex := TRUST_SYNC_AxisIndex(Axis := Slave);
TRUST_SYNC_ResetAxis(AxisIndex := MasterIndex);
TRUST_SYNC_ResetSlaveKernel(AxisIndex := SlaveIndex);
g_trust_sync_seed_start_position[SlaveIndex] := StartPosition;
g_trust_sync_seed_exit_position[SlaveIndex] := ExitPosition;
g_trust_sync_seed_ratio_numerator[SlaveIndex] := RatioNumerator;
g_trust_sync_seed_ratio_denominator[SlaveIndex] := RatioDenominator;
g_trust_sync_seed_phase_offset[SlaveIndex] := PhaseOffset;
g_trust_sync_seed_break_requested[SlaveIndex] := FALSE;
IF LoadDefaultCam THEN
    TRUST_SYNC_LoadDefaultCamTable(SlaveIndex := SlaveIndex);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TRUST_SYNC_AdvanceMasterAxis
VAR_IN_OUT
    Master : AXIS_REF;
    Slave : AXIS_REF;
END_VAR
VAR_INPUT
    NextCommandedMasterPosition : REAL;
    NextActualMasterPosition : REAL;
    UseActualMasterPosition : BOOL;
    BreakSync : BOOL;
END_VAR
VAR_OUTPUT
    InSync : BOOL;
    InGear : BOOL;
    GearSlavePosition : REAL;
    CamSlavePosition : REAL;
    StartSync : BOOL;
    EndOfProfile : BOOL;
END_VAR
VAR
    MasterIndex : UINT;
    SlaveIndex : UINT;
    Ratio : REAL;
END_VAR
MasterIndex := TRUST_SYNC_AxisIndex(Axis := Master);
SlaveIndex := TRUST_SYNC_AxisIndex(Axis := Slave);
IF NOT g_trust_sync_axis_initialized[MasterIndex] THEN
    TRUST_SYNC_ResetAxis(AxisIndex := MasterIndex);
END_IF;
IF NOT g_trust_sync_axis_initialized[SlaveIndex] THEN
    TRUST_SYNC_ResetSlaveKernel(AxisIndex := SlaveIndex);
END_IF;
g_trust_sync_axis_last_commanded_position[MasterIndex] := g_trust_sync_axis_commanded_position[MasterIndex];
g_trust_sync_axis_commanded_position[MasterIndex] := NextCommandedMasterPosition;
IF UseActualMasterPosition THEN
    g_trust_sync_axis_actual_position[MasterIndex] := NextActualMasterPosition;
ELSE
    g_trust_sync_axis_actual_position[MasterIndex] := NextCommandedMasterPosition;
END_IF;
g_trust_sync_axis_velocity[MasterIndex] :=
    g_trust_sync_axis_commanded_position[MasterIndex] - g_trust_sync_axis_last_commanded_position[MasterIndex];
g_trust_sync_seed_break_requested[SlaveIndex] := BreakSync;
IF BreakSync AND (g_trust_sync_active_command_id[SlaveIndex] <> UINT#0) THEN
    TRUST_SYNC_RecordAbortedCommand(AxisIndex := SlaveIndex, CommandID := g_trust_sync_active_command_id[SlaveIndex]);
    TRUST_SYNC_ClearActiveCommandSlot(AxisIndex := SlaveIndex);
    g_trust_sync_axis_state[SlaveIndex] := MC_AXIS_STATUS#mcContinuousMotion;
    TRUST_SYNC_PromoteQueuedCommand(SlaveIndex := SlaveIndex);
END_IF;
IF g_trust_sync_active_command_id[SlaveIndex] <> UINT#0 THEN
    TRUST_SYNC_ProcessActiveCommand(SlaveIndex := SlaveIndex);
    InSync := g_trust_sync_active_in_sync[SlaveIndex];
    InGear := g_trust_sync_active_in_gear[SlaveIndex];
    StartSync := g_trust_sync_active_start_sync_pulse[SlaveIndex];
    EndOfProfile := g_trust_sync_active_end_of_profile_pulse[SlaveIndex];
    GearSlavePosition := g_trust_sync_axis_commanded_position[SlaveIndex];
    CamSlavePosition := g_trust_sync_axis_commanded_position[SlaveIndex];
ELSE
    InSync :=
        (g_trust_sync_axis_commanded_position[MasterIndex] >= g_trust_sync_seed_start_position[SlaveIndex]) AND
        (g_trust_sync_axis_commanded_position[MasterIndex] < g_trust_sync_seed_exit_position[SlaveIndex]) AND
        (NOT BreakSync);
    Ratio := REAL#0.0;
    IF g_trust_sync_seed_ratio_denominator[SlaveIndex] <> REAL#0.0 THEN
        Ratio := g_trust_sync_seed_ratio_numerator[SlaveIndex] / g_trust_sync_seed_ratio_denominator[SlaveIndex];
    END_IF;
    GearSlavePosition := (g_trust_sync_axis_commanded_position[MasterIndex] * Ratio) + g_trust_sync_seed_phase_offset[SlaveIndex];
    CamSlavePosition := TRUST_SYNC_CamSlavePositionAt(
        SlaveIndex := SlaveIndex,
        SampleMaster := g_trust_sync_axis_commanded_position[MasterIndex]
    );
    InGear := InSync;
    StartSync := FALSE;
    EndOfProfile := FALSE;
    IF InSync THEN
        g_trust_sync_axis_state[SlaveIndex] := MC_AXIS_STATUS#mcSynchronizedMotion;
        TRUST_SYNC_ApplySlaveTarget(SlaveIndex := SlaveIndex, TargetPosition := GearSlavePosition);
    ELSE
        g_trust_sync_axis_state[SlaveIndex] := MC_AXIS_STATUS#mcContinuousMotion;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TRUST_SYNC_TestProbe
VAR_IN_OUT
    Axis : AXIS_REF;
END_VAR
VAR_OUTPUT
    State : MC_AXIS_STATUS;
    CommandedPosition : REAL;
    ActualPosition : REAL;
    Velocity : REAL;
    SelectedCamReady : BOOL;
    SelectedCamID : MC_CAM_ID;
    HasActiveCommand : BOOL;
    HasQueuedCommand : BOOL;
    InSync : BOOL;
    InGear : BOOL;
    StartSync : BOOL;
    EndOfProfile : BOOL;
END_VAR
VAR
    AxisIndex : UINT;
END_VAR
AxisIndex := TRUST_SYNC_AxisIndex(Axis := Axis);
State := g_trust_sync_axis_state[AxisIndex];
CommandedPosition := g_trust_sync_axis_commanded_position[AxisIndex];
ActualPosition := g_trust_sync_axis_actual_position[AxisIndex];
Velocity := g_trust_sync_axis_velocity[AxisIndex];
SelectedCamReady := g_trust_sync_selected_cam_ready[AxisIndex];
SelectedCamID := g_trust_sync_selected_cam_id[AxisIndex];
HasActiveCommand := g_trust_sync_active_command_id[AxisIndex] <> UINT#0;
HasQueuedCommand := g_trust_sync_queued_command_id[AxisIndex] <> UINT#0;
InSync := g_trust_sync_active_in_sync[AxisIndex];
InGear := g_trust_sync_active_in_gear[AxisIndex];
StartSync := g_trust_sync_active_start_sync_pulse[AxisIndex];
EndOfProfile := g_trust_sync_active_end_of_profile_pulse[AxisIndex];
END_FUNCTION_BLOCK

TYPE TRUST_MOTION_COMMAND_KIND : (
    trustMotionNone,
    trustMotionHome,
    trustMotionStepAbsoluteSwitch,
    trustMotionStepLimitSwitch,
    trustMotionStepBlock,
    trustMotionStepReferencePulse,
    trustMotionStepDistanceCoded,
    trustMotionHomeDirect,
    trustMotionHomeAbsolute,
    trustMotionFinishHoming,
    trustMotionHalt,
    trustMotionMoveAbsolute,
    trustMotionMoveRelative,
    trustMotionMoveAdditive,
    trustMotionMoveVelocity,
    trustMotionMoveContinuousAbsolute,
    trustMotionMoveContinuousRelative,
    trustMotionSetPosition,
    trustMotionWriteParameter,
    trustMotionWriteBoolParameter
);
END_TYPE

FUNCTION TRUST_MOTION_AxisIndex : UINT
VAR_INPUT
    Axis : AXIS_REF;
END_VAR
TRUST_MOTION_AxisIndex := Axis.InternalIndex;
END_FUNCTION

FUNCTION TRUST_MOTION_IsNumericParameter : BOOL
VAR_INPUT
    ParameterNumber : INT;
END_VAR
TRUST_MOTION_IsNumericParameter :=
    (ParameterNumber = INT#1) OR
    (ParameterNumber = INT#2) OR
    (ParameterNumber = INT#3) OR
    (ParameterNumber = INT#7) OR
    (ParameterNumber = INT#8) OR
    (ParameterNumber = INT#9) OR
    (ParameterNumber = INT#10) OR
    (ParameterNumber = INT#11) OR
    (ParameterNumber = INT#12) OR
    (ParameterNumber = INT#13) OR
    (ParameterNumber = INT#14) OR
    (ParameterNumber = INT#15) OR
    (ParameterNumber = INT#16) OR
    (ParameterNumber = INT#17);
END_FUNCTION

FUNCTION TRUST_MOTION_IsBoolParameter : BOOL
VAR_INPUT
    ParameterNumber : INT;
END_VAR
TRUST_MOTION_IsBoolParameter :=
    (ParameterNumber = INT#4) OR
    (ParameterNumber = INT#5) OR
    (ParameterNumber = INT#6) OR
    (ParameterNumber = INT#1000);
END_FUNCTION

FUNCTION TRUST_MOTION_NextCommandId : UINT
VAR_INPUT
    AxisIndex : UINT;
END_VAR
g_trust_motion_next_command_id[AxisIndex] := g_trust_motion_next_command_id[AxisIndex] + UINT#1;
IF g_trust_motion_next_command_id[AxisIndex] = UINT#0 THEN
    g_trust_motion_next_command_id[AxisIndex] := UINT#1;
END_IF;
TRUST_MOTION_NextCommandId := g_trust_motion_next_command_id[AxisIndex];
END_FUNCTION

FUNCTION TRUST_MOTION_CommandIsQueued : BOOL
VAR_INPUT
    AxisIndex : UINT;
    CommandID : UINT;
END_VAR
TRUST_MOTION_CommandIsQueued :=
    ((g_trust_motion_queue_depth[AxisIndex] >= UINT#1) AND (g_trust_motion_queue0_command_id[AxisIndex] = CommandID)) OR
    ((g_trust_motion_queue_depth[AxisIndex] >= UINT#2) AND (g_trust_motion_queue1_command_id[AxisIndex] = CommandID));
END_FUNCTION

FUNCTION TRUST_MOTION_CommandWasAborted : BOOL
VAR_INPUT
    AxisIndex : UINT;
    CommandID : UINT;
END_VAR
TRUST_MOTION_CommandWasAborted :=
    (g_trust_motion_aborted0_command_id[AxisIndex] = CommandID) OR
    (g_trust_motion_aborted1_command_id[AxisIndex] = CommandID) OR
    (g_trust_motion_aborted2_command_id[AxisIndex] = CommandID);
END_FUNCTION

FUNCTION TRUST_MOTION_ClearAbortedCommand : BOOL
VAR_INPUT
    AxisIndex : UINT;
    CommandID : UINT;
END_VAR
TRUST_MOTION_ClearAbortedCommand := FALSE;
IF g_trust_motion_aborted0_command_id[AxisIndex] = CommandID THEN
    g_trust_motion_aborted0_command_id[AxisIndex] := UINT#0;
    TRUST_MOTION_ClearAbortedCommand := TRUE;
END_IF;
IF g_trust_motion_aborted1_command_id[AxisIndex] = CommandID THEN
    g_trust_motion_aborted1_command_id[AxisIndex] := UINT#0;
    TRUST_MOTION_ClearAbortedCommand := TRUE;
END_IF;
IF g_trust_motion_aborted2_command_id[AxisIndex] = CommandID THEN
    g_trust_motion_aborted2_command_id[AxisIndex] := UINT#0;
    TRUST_MOTION_ClearAbortedCommand := TRUE;
END_IF;
END_FUNCTION

FUNCTION TRUST_MOTION_RecordAbortedCommand : BOOL
VAR_INPUT
    AxisIndex : UINT;
    CommandID : UINT;
END_VAR
TRUST_MOTION_RecordAbortedCommand := FALSE;
IF CommandID <> UINT#0 THEN
    IF TRUST_MOTION_CommandWasAborted(AxisIndex := AxisIndex, CommandID := CommandID) THEN
        TRUST_MOTION_RecordAbortedCommand := TRUE;
    ELSIF g_trust_motion_aborted0_command_id[AxisIndex] = UINT#0 THEN
        g_trust_motion_aborted0_command_id[AxisIndex] := CommandID;
        TRUST_MOTION_RecordAbortedCommand := TRUE;
    ELSIF g_trust_motion_aborted1_command_id[AxisIndex] = UINT#0 THEN
        g_trust_motion_aborted1_command_id[AxisIndex] := CommandID;
        TRUST_MOTION_RecordAbortedCommand := TRUE;
    ELSIF g_trust_motion_aborted2_command_id[AxisIndex] = UINT#0 THEN
        g_trust_motion_aborted2_command_id[AxisIndex] := CommandID;
        TRUST_MOTION_RecordAbortedCommand := TRUE;
    END_IF;
END_IF;
END_FUNCTION

FUNCTION TRUST_MOTION_PromoteQueuedCommand : BOOL
VAR_INPUT
    AxisIndex : UINT;
END_VAR
TRUST_MOTION_PromoteQueuedCommand := FALSE;
IF (g_trust_motion_active_command_id[AxisIndex] = UINT#0) AND (g_trust_motion_queue_depth[AxisIndex] >= UINT#1) THEN
    g_trust_motion_active_command_id[AxisIndex] := g_trust_motion_queue0_command_id[AxisIndex];
    g_trust_motion_active_command_kind[AxisIndex] := g_trust_motion_queue0_command_kind[AxisIndex];
    g_trust_motion_active_buffer_mode[AxisIndex] := g_trust_motion_queue0_buffer_mode[AxisIndex];
    g_trust_motion_queue0_command_id[AxisIndex] := g_trust_motion_queue1_command_id[AxisIndex];
    g_trust_motion_queue0_command_kind[AxisIndex] := g_trust_motion_queue1_command_kind[AxisIndex];
    g_trust_motion_queue0_buffer_mode[AxisIndex] := g_trust_motion_queue1_buffer_mode[AxisIndex];
    g_trust_motion_queue1_command_id[AxisIndex] := UINT#0;
    g_trust_motion_queue1_command_kind[AxisIndex] := TRUST_MOTION_COMMAND_KIND#trustMotionNone;
    g_trust_motion_queue1_buffer_mode[AxisIndex] := MC_BUFFER_MODE#mcAborting;
    g_trust_motion_queue_depth[AxisIndex] := g_trust_motion_queue_depth[AxisIndex] - UINT#1;
    TRUST_MOTION_PromoteQueuedCommand := TRUE;
END_IF;
END_FUNCTION

FUNCTION TRUST_MOTION_FlushQueuedCommands : BOOL
VAR_INPUT
    AxisIndex : UINT;
END_VAR
TRUST_MOTION_FlushQueuedCommands := FALSE;
IF g_trust_motion_queue_depth[AxisIndex] >= UINT#1 THEN
    TRUST_MOTION_RecordAbortedCommand(AxisIndex := AxisIndex, CommandID := g_trust_motion_queue0_command_id[AxisIndex]);
    g_trust_motion_queue0_command_id[AxisIndex] := UINT#0;
    g_trust_motion_queue0_command_kind[AxisIndex] := TRUST_MOTION_COMMAND_KIND#trustMotionNone;
    g_trust_motion_queue0_buffer_mode[AxisIndex] := MC_BUFFER_MODE#mcAborting;
    TRUST_MOTION_FlushQueuedCommands := TRUE;
END_IF;
IF g_trust_motion_queue_depth[AxisIndex] >= UINT#2 THEN
    TRUST_MOTION_RecordAbortedCommand(AxisIndex := AxisIndex, CommandID := g_trust_motion_queue1_command_id[AxisIndex]);
    g_trust_motion_queue1_command_id[AxisIndex] := UINT#0;
    g_trust_motion_queue1_command_kind[AxisIndex] := TRUST_MOTION_COMMAND_KIND#trustMotionNone;
    g_trust_motion_queue1_buffer_mode[AxisIndex] := MC_BUFFER_MODE#mcAborting;
    TRUST_MOTION_FlushQueuedCommands := TRUE;
END_IF;
g_trust_motion_queue_depth[AxisIndex] := UINT#0;
END_FUNCTION

FUNCTION TRUST_MOTION_ClearActiveCommandSlot : BOOL
VAR_INPUT
    AxisIndex : UINT;
END_VAR
TRUST_MOTION_ClearActiveCommandSlot := TRUE;
g_trust_motion_active_command_id[AxisIndex] := UINT#0;
g_trust_motion_active_command_kind[AxisIndex] := TRUST_MOTION_COMMAND_KIND#trustMotionNone;
g_trust_motion_active_buffer_mode[AxisIndex] := MC_BUFFER_MODE#mcAborting;
END_FUNCTION

FUNCTION TRUST_MOTION_EnterErrorStopAndFlushQueue : BOOL
VAR_INPUT
    AxisIndex : UINT;
END_VAR
g_trust_motion_state[AxisIndex] := MC_AXIS_STATUS#mcErrorStop;
TRUST_MOTION_ClearActiveCommandSlot(AxisIndex := AxisIndex);
TRUST_MOTION_FlushQueuedCommands(AxisIndex := AxisIndex);
TRUST_MOTION_EnterErrorStopAndFlushQueue := TRUE;
END_FUNCTION

FUNCTION TRUST_MOTION_SupportsSingleAxisBufferMode : BOOL
VAR_INPUT
    BufferMode : MC_BUFFER_MODE;
END_VAR
TRUST_MOTION_SupportsSingleAxisBufferMode :=
    (BufferMode = MC_BUFFER_MODE#mcAborting) OR
    (BufferMode = MC_BUFFER_MODE#mcBuffered);
END_FUNCTION

FUNCTION_BLOCK TRUST_MOTION_RequestBufferedCommand
VAR_INPUT
    AxisIndex : UINT;
    Kind : TRUST_MOTION_COMMAND_KIND;
    BufferMode : MC_BUFFER_MODE;
END_VAR
VAR_OUTPUT
    Accepted : BOOL;
    ActiveNow : BOOL;
    Error : BOOL;
    ErrorID : WORD;
    CommandID : UINT;
END_VAR
IF NOT TRUST_MOTION_SupportsSingleAxisBufferMode(BufferMode := BufferMode) THEN
    Error := TRUE;
    ErrorID := WORD#16#0500;
ELSIF BufferMode = MC_BUFFER_MODE#mcAborting THEN
    IF g_trust_motion_active_command_id[AxisIndex] <> UINT#0 THEN
        TRUST_MOTION_RecordAbortedCommand(AxisIndex := AxisIndex, CommandID := g_trust_motion_active_command_id[AxisIndex]);
    END_IF;
    TRUST_MOTION_FlushQueuedCommands(AxisIndex := AxisIndex);
    g_trust_motion_active_command_id[AxisIndex] := UINT#0;
    g_trust_motion_active_command_kind[AxisIndex] := TRUST_MOTION_COMMAND_KIND#trustMotionNone;
    g_trust_motion_active_buffer_mode[AxisIndex] := MC_BUFFER_MODE#mcAborting;
    CommandID := TRUST_MOTION_NextCommandId(AxisIndex := AxisIndex);
    g_trust_motion_active_command_id[AxisIndex] := CommandID;
    g_trust_motion_active_command_kind[AxisIndex] := Kind;
    g_trust_motion_active_buffer_mode[AxisIndex] := BufferMode;
    Accepted := TRUE;
    ActiveNow := TRUE;
ELSIF (g_trust_motion_active_command_id[AxisIndex] = UINT#0) AND (g_trust_motion_queue_depth[AxisIndex] = UINT#0) THEN
    CommandID := TRUST_MOTION_NextCommandId(AxisIndex := AxisIndex);
    g_trust_motion_active_command_id[AxisIndex] := CommandID;
    g_trust_motion_active_command_kind[AxisIndex] := Kind;
    g_trust_motion_active_buffer_mode[AxisIndex] := BufferMode;
    Accepted := TRUE;
    ActiveNow := TRUE;
ELSIF g_trust_motion_queue_depth[AxisIndex] >= UINT#2 THEN
    Error := TRUE;
    ErrorID := WORD#16#0400;
ELSE
    CommandID := TRUST_MOTION_NextCommandId(AxisIndex := AxisIndex);
    IF g_trust_motion_queue_depth[AxisIndex] = UINT#0 THEN
        g_trust_motion_queue0_command_id[AxisIndex] := CommandID;
        g_trust_motion_queue0_command_kind[AxisIndex] := Kind;
        g_trust_motion_queue0_buffer_mode[AxisIndex] := BufferMode;
    ELSE
        g_trust_motion_queue1_command_id[AxisIndex] := CommandID;
        g_trust_motion_queue1_command_kind[AxisIndex] := Kind;
        g_trust_motion_queue1_buffer_mode[AxisIndex] := BufferMode;
    END_IF;
    g_trust_motion_queue_depth[AxisIndex] := g_trust_motion_queue_depth[AxisIndex] + UINT#1;
    Accepted := TRUE;
    ActiveNow := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION TRUST_MOTION_ApplyNumericParameterWrite : BOOL
VAR_INPUT
    AxisIndex : UINT;
    ParameterNumber : INT;
    Value : REAL;
END_VAR
TRUST_MOTION_ApplyNumericParameterWrite := TRUE;
IF ParameterNumber = INT#1 THEN
    g_trust_motion_commanded_position[AxisIndex] := Value;
ELSIF ParameterNumber = INT#2 THEN
    g_trust_motion_sw_limit_pos[AxisIndex] := Value;
ELSIF ParameterNumber = INT#3 THEN
    g_trust_motion_sw_limit_neg[AxisIndex] := Value;
ELSIF ParameterNumber = INT#7 THEN
    g_trust_motion_max_position_lag[AxisIndex] := Value;
ELSIF ParameterNumber = INT#8 THEN
    g_trust_motion_max_velocity_system[AxisIndex] := Value;
ELSIF ParameterNumber = INT#9 THEN
    g_trust_motion_max_velocity_appl[AxisIndex] := Value;
ELSIF ParameterNumber = INT#10 THEN
    g_trust_motion_actual_velocity[AxisIndex] := Value;
ELSIF ParameterNumber = INT#11 THEN
    g_trust_motion_commanded_velocity[AxisIndex] := Value;
ELSIF ParameterNumber = INT#12 THEN
    g_trust_motion_max_acceleration_system[AxisIndex] := Value;
ELSIF ParameterNumber = INT#13 THEN
    g_trust_motion_max_acceleration_appl[AxisIndex] := Value;
ELSIF ParameterNumber = INT#14 THEN
    g_trust_motion_max_deceleration_system[AxisIndex] := Value;
ELSIF ParameterNumber = INT#15 THEN
    g_trust_motion_max_deceleration_appl[AxisIndex] := Value;
ELSIF ParameterNumber = INT#16 THEN
    g_trust_motion_max_jerk_system[AxisIndex] := Value;
ELSIF ParameterNumber = INT#17 THEN
    g_trust_motion_max_jerk_appl[AxisIndex] := Value;
ELSE
    TRUST_MOTION_ApplyNumericParameterWrite := FALSE;
