    ErrorID := WORD#16#0000;
    IF g_trust_motion_grouped[AxisIndex] THEN
        Error := TRUE;
        ErrorID := WORD#16#0101;
    ELSIF NOT TRUST_MOTION_SupportsSingleAxisBufferMode(BufferMode := BufferMode) THEN
        Error := TRUE;
        ErrorID := WORD#16#0500;
    ELSE
        WasActive := FALSE;
        Request(AxisIndex := AxisIndex, Kind := TRUST_MOTION_COMMAND_KIND#trustMotionHomeAbsolute, BufferMode := BufferMode);
        IF Request.Error THEN
            Error := TRUE;
            ErrorID := Request.ErrorID;
            AcceptedCommandID := UINT#0;
        ELSE
            AcceptedCommandID := Request.CommandID;
            Busy := TRUE;
            Active := Request.ActiveNow;
            IF Request.ActiveNow THEN
                WasActive := TRUE;
                g_trust_motion_state[AxisIndex] := MC_AXIS_STATUS#mcHoming;
            END_IF;
        END_IF;
    END_IF;
ELSIF AcceptedCommandID <> UINT#0 THEN
    IF TRUST_MOTION_CommandWasAborted(AxisIndex := AxisIndex, CommandID := AcceptedCommandID) THEN
        Busy := FALSE;
        Active := FALSE;
        Done := FALSE;
        CommandAborted := TRUE;
        Error := FALSE;
        ErrorID := WORD#16#0000;
        TRUST_MOTION_ClearAbortedCommand(AxisIndex := AxisIndex, CommandID := AcceptedCommandID);
        AcceptedCommandID := UINT#0;
        WasActive := FALSE;
    ELSIF g_trust_motion_active_command_id[AxisIndex] = AcceptedCommandID THEN
        IF NOT WasActive THEN
            WasActive := TRUE;
            Busy := TRUE;
            Active := TRUE;
            g_trust_motion_state[AxisIndex] := MC_AXIS_STATUS#mcHoming;
        END_IF;
        Busy := FALSE;
        Active := FALSE;
        Done := TRUE;
        CommandAborted := FALSE;
        Error := FALSE;
        ErrorID := WORD#16#0000;
        TRUST_HOME_FinalizeHoming(AxisIndex := AxisIndex, Position := g_trust_motion_abs_encoder_position[AxisIndex]);
        TRUST_MOTION_ClearActiveCommandSlot(AxisIndex := AxisIndex);
        AcceptedCommandID := UINT#0;
        WasActive := FALSE;
    ELSE
        Busy := TRUE;
        Active := FALSE;
    END_IF;
END_IF;
LastExecute := Execute;
END_FUNCTION_BLOCK

FUNCTION_BLOCK MC_FinishHoming
VAR_IN_OUT
    Axis : AXIS_REF;
END_VAR
VAR_INPUT
    Execute : BOOL;
    Distance : REAL;
    Velocity : REAL;
    Acceleration : REAL;
    Deceleration : REAL;
    Jerk : REAL;
    BufferMode : MC_BUFFER_MODE;
END_VAR
VAR_OUTPUT
    Done : BOOL;
    Busy : BOOL;
    Active : BOOL;
    CommandAborted : BOOL;
    Error : BOOL;
    ErrorID : WORD;
END_VAR
VAR
    AxisIndex : UINT;
    Context : TRUST_MOTION_AxisContext;
    LastExecute : BOOL;
    AcceptedCommandID : UINT;
    AcceptedDistance : REAL;
    WasActive : BOOL;
    Request : TRUST_MOTION_RequestBufferedCommand;
END_VAR
Context(Axis := Axis);
AxisIndex := Context.AxisIndex;
TRUST_MOTION_PromoteQueuedCommand(AxisIndex := AxisIndex);
IF Execute AND (NOT LastExecute) THEN
    Done := FALSE;
    Busy := FALSE;
    Active := FALSE;
    CommandAborted := FALSE;
    Error := FALSE;
    ErrorID := WORD#16#0000;
    IF g_trust_motion_grouped[AxisIndex] THEN
        Error := TRUE;
        ErrorID := WORD#16#0101;
    ELSIF (Velocity < REAL#0.0) OR (Acceleration < REAL#0.0) OR (Deceleration < REAL#0.0) OR (Jerk < REAL#0.0) THEN
        Error := TRUE;
        ErrorID := WORD#16#0001;
    ELSIF NOT TRUST_MOTION_SupportsSingleAxisBufferMode(BufferMode := BufferMode) THEN
        Error := TRUE;
        ErrorID := WORD#16#0500;
    ELSE
        AcceptedDistance := Distance;
        WasActive := FALSE;
        Request(AxisIndex := AxisIndex, Kind := TRUST_MOTION_COMMAND_KIND#trustMotionFinishHoming, BufferMode := BufferMode);
        IF Request.Error THEN
            Error := TRUE;
            ErrorID := Request.ErrorID;
            AcceptedCommandID := UINT#0;
        ELSE
            AcceptedCommandID := Request.CommandID;
            Busy := TRUE;
            Active := Request.ActiveNow;
            IF Request.ActiveNow THEN
                WasActive := TRUE;
                g_trust_motion_state[AxisIndex] := MC_AXIS_STATUS#mcHoming;
                g_trust_motion_resolved_acceleration[AxisIndex] := TRUST_MOTION_ResolveDynamicInput(RequestedValue := Acceleration, MaximumValue := g_trust_motion_max_acceleration_appl[AxisIndex]);
                g_trust_motion_resolved_deceleration[AxisIndex] := TRUST_MOTION_ResolveDynamicInput(RequestedValue := Deceleration, MaximumValue := g_trust_motion_max_deceleration_appl[AxisIndex]);
                g_trust_motion_resolved_jerk[AxisIndex] := TRUST_MOTION_ResolveDynamicInput(RequestedValue := Jerk, MaximumValue := g_trust_motion_max_jerk_appl[AxisIndex]);
            END_IF;
        END_IF;
    END_IF;
ELSIF AcceptedCommandID <> UINT#0 THEN
    IF TRUST_MOTION_CommandWasAborted(AxisIndex := AxisIndex, CommandID := AcceptedCommandID) THEN
        Busy := FALSE;
        Active := FALSE;
        Done := FALSE;
        CommandAborted := TRUE;
        Error := FALSE;
        ErrorID := WORD#16#0000;
        TRUST_MOTION_ClearAbortedCommand(AxisIndex := AxisIndex, CommandID := AcceptedCommandID);
        AcceptedCommandID := UINT#0;
        WasActive := FALSE;
    ELSIF g_trust_motion_active_command_id[AxisIndex] = AcceptedCommandID THEN
        IF NOT WasActive THEN
            WasActive := TRUE;
            Busy := TRUE;
            Active := TRUE;
            g_trust_motion_state[AxisIndex] := MC_AXIS_STATUS#mcHoming;
        END_IF;
        Busy := FALSE;
        Active := FALSE;
        Done := TRUE;
        CommandAborted := FALSE;
        Error := FALSE;
        ErrorID := WORD#16#0000;
        TRUST_HOME_FinalizeHoming(AxisIndex := AxisIndex, Position := g_trust_motion_actual_position[AxisIndex] + AcceptedDistance);
        TRUST_MOTION_ClearActiveCommandSlot(AxisIndex := AxisIndex);
        AcceptedCommandID := UINT#0;
        WasActive := FALSE;
    ELSE
        Busy := TRUE;
        Active := FALSE;
    END_IF;
END_IF;
LastExecute := Execute;
END_FUNCTION_BLOCK

FUNCTION TRUST_HOME_DirectionPositive : BOOL
VAR_INPUT
    Direction : MC_HOME_DIRECTION;
    SignalActive : BOOL;
END_VAR
CASE Direction OF
    MC_HOME_DIRECTION#mcPositiveDirection:
        TRUST_HOME_DirectionPositive := TRUE;
    MC_HOME_DIRECTION#mcNegativeDirection:
        TRUST_HOME_DirectionPositive := FALSE;
    MC_HOME_DIRECTION#mcSwitchPositive:
        TRUST_HOME_DirectionPositive := NOT SignalActive;
    MC_HOME_DIRECTION#mcSwitchNegative:
        TRUST_HOME_DirectionPositive := SignalActive;
ELSE
    TRUST_HOME_DirectionPositive := TRUE;
END_CASE;
END_FUNCTION

FUNCTION TRUST_HOME_SwitchModeMet : BOOL
VAR_INPUT
    SwitchMode : MC_SWITCH_MODE;
    CurrentSignal : BOOL;
    PreviousSignal : BOOL;
    DirectionPositive : BOOL;
END_VAR
CASE SwitchMode OF
    MC_SWITCH_MODE#mcOn:
        TRUST_HOME_SwitchModeMet := CurrentSignal;
    MC_SWITCH_MODE#mcOff:
        TRUST_HOME_SwitchModeMet := NOT CurrentSignal;
    MC_SWITCH_MODE#mcRisingEdge:
        TRUST_HOME_SwitchModeMet := (NOT PreviousSignal) AND CurrentSignal;
    MC_SWITCH_MODE#mcFallingEdge:
        TRUST_HOME_SwitchModeMet := PreviousSignal AND (NOT CurrentSignal);
    MC_SWITCH_MODE#mcEdgeSwitchPositive:
        IF DirectionPositive THEN
            TRUST_HOME_SwitchModeMet := (NOT PreviousSignal) AND CurrentSignal;
        ELSE
            TRUST_HOME_SwitchModeMet := PreviousSignal AND (NOT CurrentSignal);
        END_IF;
    MC_SWITCH_MODE#mcEdgeSwitchNegative:
        IF DirectionPositive THEN
            TRUST_HOME_SwitchModeMet := PreviousSignal AND (NOT CurrentSignal);
        ELSE
            TRUST_HOME_SwitchModeMet := (NOT PreviousSignal) AND CurrentSignal;
        END_IF;
ELSE
    TRUST_HOME_SwitchModeMet := FALSE;
END_CASE;
END_FUNCTION

FUNCTION TRUST_HOME_LimitError : BOOL
VAR_INPUT
    ConditionMet : BOOL;
    TimeLimit : TIME;
    DistanceLimit : REAL;
END_VAR
TRUST_HOME_LimitError := (NOT ConditionMet) AND ((TimeLimit > TIME#0ms) OR (DistanceLimit > REAL#0.0));
END_FUNCTION

FUNCTION TRUST_HOME_BlockConditionMet : BOOL
VAR_INPUT
    AxisIndex : UINT;
    DetectionVelocityLimit : REAL;
    TorqueLimit : REAL;
END_VAR
VAR
    VelocityInWindow : BOOL;
    ActualVelocity : REAL;
END_VAR
ActualVelocity := g_trust_motion_actual_velocity[AxisIndex];
VelocityInWindow := (ActualVelocity <= DetectionVelocityLimit) AND (ActualVelocity >= (REAL#0.0 - DetectionVelocityLimit));
TRUST_HOME_BlockConditionMet := (TorqueLimit > REAL#0.0) AND (g_trust_motion_actual_torque[AxisIndex] >= TorqueLimit) AND VelocityInWindow;
END_FUNCTION

FUNCTION TRUST_HOME_ReferenceSignalCurrent : BOOL
VAR_INPUT
    AxisIndex : UINT;
    ReferenceSignal : MC_REF_SIGNAL_REF;
END_VAR
TRUST_HOME_ReferenceSignalCurrent := ReferenceSignal.Signal OR g_trust_motion_ref_signal_active[AxisIndex];
END_FUNCTION

FUNCTION TRUST_HOME_StartHoming : BOOL
VAR_INPUT
    AxisIndex : UINT;
    DirectionPositive : BOOL;
    Velocity : REAL;
END_VAR
VAR
    SignedVelocity : REAL;
END_VAR
SignedVelocity := Velocity;
IF NOT DirectionPositive THEN
    SignedVelocity := REAL#0.0 - Velocity;
END_IF;
g_trust_motion_state[AxisIndex] := MC_AXIS_STATUS#mcHoming;
g_trust_motion_commanded_velocity[AxisIndex] := SignedVelocity;
g_trust_motion_set_velocity[AxisIndex] := SignedVelocity;
g_trust_motion_actual_velocity[AxisIndex] := SignedVelocity;
g_trust_motion_constant_velocity[AxisIndex] := FALSE;
g_trust_motion_accelerating[AxisIndex] := TRUE;
g_trust_motion_decelerating[AxisIndex] := FALSE;
TRUST_HOME_StartHoming := TRUE;
END_FUNCTION

FUNCTION TRUST_HOME_ApplyAxisPosition : BOOL
VAR_INPUT
    AxisIndex : UINT;
    Position : REAL;
END_VAR
g_trust_motion_actual_position[AxisIndex] := Position;
g_trust_motion_set_position[AxisIndex] := Position;
g_trust_motion_commanded_position[AxisIndex] := Position;
TRUST_HOME_ApplyAxisPosition := TRUE;
END_FUNCTION

FUNCTION TRUST_HOME_CompleteStep : BOOL
VAR_INPUT
    AxisIndex : UINT;
    UpdatePosition : BOOL;
    Position : REAL;
END_VAR
IF UpdatePosition THEN
    TRUST_HOME_ApplyAxisPosition(AxisIndex := AxisIndex, Position := Position);
END_IF;
g_trust_motion_state[AxisIndex] := MC_AXIS_STATUS#mcHoming;
g_trust_motion_commanded_velocity[AxisIndex] := REAL#0.0;
g_trust_motion_set_velocity[AxisIndex] := REAL#0.0;
g_trust_motion_actual_velocity[AxisIndex] := REAL#0.0;
g_trust_motion_constant_velocity[AxisIndex] := FALSE;
g_trust_motion_accelerating[AxisIndex] := FALSE;
g_trust_motion_decelerating[AxisIndex] := FALSE;
g_trust_motion_is_homed[AxisIndex] := FALSE;
TRUST_HOME_CompleteStep := TRUE;
END_FUNCTION

FUNCTION TRUST_HOME_FinalizeHoming : BOOL
VAR_INPUT
    AxisIndex : UINT;
    Position : REAL;
END_VAR
TRUST_HOME_ApplyAxisPosition(AxisIndex := AxisIndex, Position := Position);
g_trust_motion_state[AxisIndex] := MC_AXIS_STATUS#mcStandstill;
g_trust_motion_commanded_velocity[AxisIndex] := REAL#0.0;
g_trust_motion_set_velocity[AxisIndex] := REAL#0.0;
g_trust_motion_actual_velocity[AxisIndex] := REAL#0.0;
g_trust_motion_constant_velocity[AxisIndex] := FALSE;
g_trust_motion_accelerating[AxisIndex] := FALSE;
g_trust_motion_decelerating[AxisIndex] := FALSE;
g_trust_motion_is_homed[AxisIndex] := TRUE;
TRUST_HOME_FinalizeHoming := TRUE;
END_FUNCTION

