(* OSCAT BASIC 3.33 Chapter 5 Mathematics helpers. *)

FUNCTION ACOSH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ACOSH := LN(SQRT(X * X - 1.0) + X);
END_FUNCTION

FUNCTION ACOTH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ACOTH := LN((X + 1.0) / (X - 1.0)) * 0.5;
END_FUNCTION

FUNCTION AGDF : REAL
VAR_INPUT
    X : REAL;
END_VAR
AGDF := LN((1.0 + SIN(X)) / COS(X));
END_FUNCTION

FUNCTION ASINH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ASINH := LN(SQRT(X * X + 1.0) + X);
END_FUNCTION

FUNCTION ATAN2 : REAL
VAR_INPUT
    Y : REAL;
    X : REAL;
END_VAR
IF X > 0.0 THEN
    ATAN2 := ATAN(Y / X);
ELSIF X < 0.0 THEN
    IF Y >= 0.0 THEN
        ATAN2 := ATAN(Y / X) + MATH.PI;
    ELSE
        ATAN2 := ATAN(Y / X) - MATH.PI;
    END_IF;
ELSIF Y > 0.0 THEN
    ATAN2 := MATH.PI05;
ELSIF Y < 0.0 THEN
    ATAN2 := -MATH.PI05;
ELSE
    ATAN2 := 0.0;
END_IF;
END_FUNCTION

FUNCTION ATANH : REAL
VAR_INPUT
    X : REAL;
END_VAR
ATANH := LN((X + 1.0) / (1.0 - X)) * 0.5;
END_FUNCTION

FUNCTION BETA : REAL
VAR_INPUT
    X : REAL;
    Y : REAL;
END_VAR
BETA := GAMMA(X := X) * GAMMA(X := Y) / GAMMA(X := X + Y);
END_FUNCTION

FUNCTION BINOM : DINT
VAR_INPUT
    N : INT;
    K : INT;
END_VAR
VAR
    Result : DINT;
    WorkN : INT;
    WorkK : INT;
    I : INT;
END_VAR
WorkN := N;
WorkK := K;
IF 2 * WorkK > WorkN THEN
    WorkK := WorkN - WorkK;
END_IF;
IF WorkK > WorkN THEN
    BINOM := DINT#0;
ELSIF WorkK = 0 OR WorkK = WorkN THEN
    BINOM := DINT#1;
ELSIF WorkK = 1 THEN
    BINOM := INT_TO_DINT(WorkN);
ELSE
    Result := INT_TO_DINT(WorkN);
    WorkN := WorkN + 1;
    FOR I := 2 TO WorkK DO
        Result := Result * INT_TO_DINT(WorkN - I) / INT_TO_DINT(I);
    END_FOR;
    BINOM := Result;
END_IF;
END_FUNCTION

FUNCTION CAUCHY : REAL
VAR_INPUT
    X : REAL;
    T : REAL;
    U : REAL;
END_VAR
VAR
    Temp : REAL;
END_VAR
Temp := X - T;
CAUCHY := MATH.PI_INV * U / (U * U + Temp * Temp);
END_FUNCTION

FUNCTION CAUCHYCD : REAL
VAR_INPUT
    X : REAL;
    T : REAL;
    U : REAL;
END_VAR
CAUCHYCD := 0.5 + MATH.PI_INV * ATAN((X - T) / U);
END_FUNCTION

FUNCTION CEIL : INT
VAR_INPUT
    X : REAL;
END_VAR
CEIL := REAL_TO_INT(X);
IF INT_TO_REAL(CEIL) < X THEN
    CEIL := CEIL + 1;
END_IF;
END_FUNCTION

FUNCTION CEIL2 : DINT
VAR_INPUT
    X : REAL;
END_VAR
CEIL2 := REAL_TO_DINT(X);
IF DINT_TO_REAL(CEIL2) < X THEN
    CEIL2 := CEIL2 + 1;
END_IF;
END_FUNCTION

FUNCTION CMP : BOOL
VAR_INPUT
    X : REAL;
    Y : REAL;
    N : INT;
END_VAR
VAR
    ScaleFactor : REAL;
    LogValue : REAL;
    DecadeExponent : INT;
    XDigits : DINT;
    YDigits : DINT;
END_VAR
ScaleFactor := ABS(X);
IF ScaleFactor > 0.0 THEN
    LogValue := LOG(ScaleFactor);
    DecadeExponent := FLOOR(X := LogValue) - N + 1;
    ScaleFactor := EXP10(X := INT_TO_REAL(DecadeExponent));
    XDigits := FLOOR2(X := X / ScaleFactor);
    YDigits := FLOOR2(X := Y / ScaleFactor);
    CMP := XDigits = YDigits;
ELSE
    CMP := X = Y;
END_IF;
END_FUNCTION

FUNCTION COSH : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    T : REAL;
END_VAR
T := EXP(X);
COSH := (1.0 / T + T) * 0.5;
END_FUNCTION

FUNCTION COTH : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 20.0 THEN
    COTH := 1.0;
ELSIF X < -20.0 THEN
    COTH := -1.0;
ELSE
    COTH := 1.0 + 2.0 / (EXP(X * 2.0) - 1.0);
END_IF;
END_FUNCTION

FUNCTION D_TRUNC : DINT
VAR_INPUT
    X : REAL;
END_VAR
D_TRUNC := REAL_TO_DINT(X);
IF X > 0.0 THEN
    IF DINT_TO_REAL(D_TRUNC) > X THEN
        D_TRUNC := D_TRUNC - 1;
    END_IF;
ELSE
    IF DINT_TO_REAL(D_TRUNC) < X THEN
        D_TRUNC := D_TRUNC + 1;
    END_IF;
END_IF;
END_FUNCTION

FUNCTION DEC1 : INT
VAR_INPUT
    X : INT;
    N : INT;
END_VAR
IF X = 0 THEN
    DEC1 := N - 1;
ELSE
    DEC1 := X - 1;
END_IF;
END_FUNCTION

FUNCTION DEG : REAL
VAR_INPUT
    RAD : REAL;
END_VAR
DEG := MODR(IN := 57.29577951308232 * RAD, DIVI := 360.0);
END_FUNCTION

FUNCTION DIFFER : BOOL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    X : REAL;
END_VAR
DIFFER := ABS(IN1 - IN2) > X;
END_FUNCTION

FUNCTION ERF : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    X2 : REAL;
    AX2 : REAL;
END_VAR
X2 := X * X;
AX2 := 0.147 * X2 + 1.0;
ERF := SQRT(1.0 - EXP(-X2 * ((0.27323954473516 + AX2) / AX2))) * INT_TO_REAL(SGN(X := X));
END_FUNCTION

FUNCTION ERFC : REAL
VAR_INPUT
    X : REAL;
END_VAR
ERFC := 1.0 - ERF(X := X);
END_FUNCTION

FUNCTION EVEN : BOOL
VAR_INPUT
    IN : DINT;
END_VAR
EVEN := (IN MOD 2) = 0;
END_FUNCTION

FUNCTION EXP10 : REAL
VAR_INPUT
    X : REAL;
END_VAR
EXP10 := EXP(X * 2.30258509299405);
END_FUNCTION

FUNCTION EXPN : REAL
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
VAR
    Base : REAL;
    Exponent : INT;
    NegativeExponent : BOOL;
END_VAR
Base := X;
Exponent := N;
NegativeExponent := Exponent < 0;
Exponent := ABS(Exponent);
IF (Exponent MOD 2) = 1 THEN
    EXPN := Base;
ELSE
    EXPN := 1.0;
END_IF;
Exponent := Exponent / 2;
WHILE Exponent > 0 DO
    Base := Base * Base;
    IF (Exponent MOD 2) = 1 THEN
        EXPN := EXPN * Base;
    END_IF;
    Exponent := Exponent / 2;
END_WHILE;
IF NegativeExponent THEN
    EXPN := 1.0 / EXPN;
END_IF;
END_FUNCTION

FUNCTION FACT : DINT
VAR_INPUT
    X : INT;
END_VAR
VAR
    I : INT;
END_VAR
IF X < 0 OR X > 12 THEN
    FACT := -1;
ELSIF X < 2 THEN
    FACT := 1;
ELSE
    FACT := 1;
    FOR I := 2 TO X DO
        FACT := FACT * INT_TO_DINT(I);
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION FIB : DINT
VAR_INPUT
    X : INT;
END_VAR
VAR
    WorkX : INT;
    T1 : DINT;
    T2 : DINT;
END_VAR
WorkX := X;
IF WorkX < 0 OR WorkX > 46 THEN
    FIB := -1;
ELSIF WorkX < 2 THEN
    FIB := INT_TO_DINT(WorkX);
ELSE
    T2 := 1;
    WHILE WorkX > 3 DO
        WorkX := WorkX - 2;
        T1 := T1 + T2;
        T2 := T1 + T2;
    END_WHILE;
    IF WorkX > 2 THEN
        T1 := T1 + T2;
    END_IF;
    FIB := T1 + T2;
END_IF;
END_FUNCTION

FUNCTION FLOOR : INT
VAR_INPUT
    X : REAL;
END_VAR
FLOOR := REAL_TO_INT(X);
IF INT_TO_REAL(FLOOR) > X THEN
    FLOOR := FLOOR - 1;
END_IF;
END_FUNCTION

FUNCTION FLOOR2 : DINT
VAR_INPUT
    X : REAL;
END_VAR
FLOOR2 := REAL_TO_DINT(X);
IF DINT_TO_REAL(FLOOR2) > X THEN
