END_IF;
END_FUNCTION

FUNCTION FRACT : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    IntegerPart : DINT;
END_VAR
IF ABS(X) < 2.0E9 THEN
    IntegerPart := D_TRUNC(X := X);
    FRACT := X - DINT_TO_REAL(IntegerPart);
ELSE
    FRACT := 0.0;
END_IF;
END_FUNCTION

FUNCTION GAMMA : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 0.0 THEN
    GAMMA := SQRT(MATH.PI2 / X) * EXPT(MATH.E_INV * (X + 1.0 / (12.0 * X - 0.1 / X)), X);
END_IF;
END_FUNCTION

FUNCTION GAUSS : REAL
VAR_INPUT
    X : REAL;
    U : REAL;
    SI : REAL;
END_VAR
VAR
    Temp : REAL;
    SIInv : REAL;
END_VAR
IF SI = 0.0 THEN
    GAUSS := 0.0;
ELSE
    Temp := X - U;
    SIInv := 1.0 / SI;
    GAUSS := EXP(Temp * Temp * SIInv * SIInv * -0.5) * 0.39894228 * SIInv;
END_IF;
END_FUNCTION

FUNCTION GAUSSCD : REAL
VAR_INPUT
    X : REAL;
    U : REAL;
    SI : REAL;
END_VAR
IF SI = 0.0 THEN
    IF X < U THEN
        GAUSSCD := 0.0;
    ELSE
        GAUSSCD := 1.0;
    END_IF;
ELSE
    GAUSSCD := (ERF(X := (X - U) / (SI * 1.414213562)) + 1.0) * 0.5;
END_IF;
END_FUNCTION

FUNCTION GCD : INT
VAR_INPUT
    A : DINT;
    B : DINT;
END_VAR
VAR
    Left : DINT;
    Right : DINT;
    Temp : DINT;
END_VAR
Left := ABS(A);
Right := ABS(B);
WHILE Right <> 0 DO
    Temp := Left MOD Right;
    Left := Right;
    Right := Temp;
END_WHILE;
GCD := DINT_TO_INT(Left);
END_FUNCTION

FUNCTION GDF : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    GDF := 0.0;
ELSIF X > 15.0 THEN
    GDF := MATH.PI05;
ELSIF X < -15.0 THEN
    GDF := -MATH.PI05;
ELSE
    GDF := ATAN(EXP(X)) * 2.0 - MATH.PI05;
END_IF;
END_FUNCTION

FUNCTION GOLD : REAL
VAR_INPUT
    X : REAL;
END_VAR
GOLD := (X + SQRT(X * X + 4.0)) * 0.5;
END_FUNCTION

FUNCTION HYPOT : REAL
VAR_INPUT
