END_IF;
END_FUNCTION

FUNCTION INC2 : INT
VAR_INPUT
    X : INT;
    D : INT;
    L : INT;
    U : INT;
END_VAR
VAR
    Span : INT;
END_VAR
Span := U - L + 1;
INC2 := (X + D - L + Span) MOD Span + L;
END_FUNCTION

FUNCTION INV : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X <> 0.0 THEN
    INV := 1.0 / X;
ELSE
    INV := 0.0;
END_IF;
END_FUNCTION

FUNCTION LAMBERT_W : REAL
VAR_INPUT
    X : REAL;
END_VAR
VAR
    W : REAL;
    NextW : REAL;
    We : REAL;
    W1e : REAL;
    Ewx : REAL;
    I : INT;
END_VAR
IF X < -0.367879441171442 THEN
    LAMBERT_W := -1000.0;
ELSIF X = 0.0 THEN
    LAMBERT_W := 0.0;
ELSE
    IF X <= 500.0 THEN
        W := LN(X + 1.0);
        W := 0.665 * (1.0 + 0.0195 * W) * W + 0.04;
    ELSE
        W := LN(X - 4.0) - (1.0 - 1.0 / LN(X)) * LN(LN(X));
    END_IF;
    FOR I := 0 TO 5 DO
        Ewx := EXP(W);
        We := W * Ewx - X;
        W1e := (W + 1.0) * Ewx;
        NextW := W - (We / (W1e - (W + 2.0) * We / (2.0 * W + 2.0)));
        IF ABS(NextW - W) < 1.0E-6 THEN
            W := NextW;
            EXIT;
        END_IF;
        W := NextW;
    END_FOR;
    LAMBERT_W := W;
END_IF;
END_FUNCTION

FUNCTION LANGEVIN : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    LANGEVIN := 0.0;
ELSE
    LANGEVIN := COTH(X := X) - 1.0 / X;
END_IF;
END_FUNCTION

FUNCTION MAX3 : REAL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    IN3 : REAL;
END_VAR
MAX3 := MAX(MAX(IN1, IN2), IN3);
END_FUNCTION

FUNCTION MID3 : REAL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    IN3 : REAL;
END_VAR
VAR
    A : REAL;
    B : REAL;
END_VAR
A := IN1;
B := IN2;
IF A > B THEN
    MID3 := A;
    A := B;
    B := MID3;
END_IF;
IF B > IN3 THEN
    B := IN3;
END_IF;
MID3 := SEL(A > B, B, A);
END_FUNCTION

FUNCTION MIN3 : REAL
VAR_INPUT
    IN1 : REAL;
    IN2 : REAL;
    IN3 : REAL;
END_VAR
MIN3 := MIN(MIN(IN1, IN2), IN3);
END_FUNCTION

FUNCTION MODR : REAL
VAR_INPUT
    IN : REAL;
    DIVI : REAL;
END_VAR
VAR
    QuotientFloor : DINT;
END_VAR
IF DIVI = 0.0 THEN
    MODR := 0.0;
ELSE
    QuotientFloor := FLOOR2(X := IN / DIVI);
    MODR := IN - DINT_TO_REAL(QuotientFloor) * DIVI;
END_IF;
END_FUNCTION

FUNCTION MUL_ADD : REAL
VAR_INPUT
    X : REAL;
    K : REAL;
    O : REAL;
END_VAR
MUL_ADD := X * K + O;
END_FUNCTION

FUNCTION NEGX : REAL
VAR_INPUT
