END_VAR
NEGX := -X;
END_FUNCTION

FUNCTION RAD : REAL
VAR_INPUT
    DEG : REAL;
END_VAR
RAD := MODR(IN := 0.0174532925199433 * DEG, DIVI := MATH.PI2);
END_FUNCTION

FUNCTION RDM : REAL
VAR_INPUT
    LAST : REAL;
END_VAR
VAR
    Tn : DWORD;
    Tc : INT;
    Seed : REAL;
END_VAR
Tn := T_PLC_MS();
Tc := BIT_COUNT(IN := Tn);
Tn := ROL(Tn OR DWORD#16#80000001, Tc MOD 32);
Seed := LIMIT(0.0, LAST, 1.0);
RDM := FRACT(X := ABS(SIN(DWORD_TO_REAL(Tn) * 0.0001 + Seed * MATH.PI2)) * 10000.0);
END_FUNCTION

FUNCTION RDM2 : INT
VAR_INPUT
    LAST : INT;
    LOW : INT;
    HIGH : INT;
END_VAR
VAR
    Span : INT;
END_VAR
Span := HIGH - LOW + 1;
RDM2 := DINT_TO_INT(D_TRUNC(X := RDM(LAST := FRACT(X := INT_TO_REAL(LAST) * MATH.PI)) * INT_TO_REAL(Span))) + LOW;
END_FUNCTION

FUNCTION RDMDW : DWORD
VAR_INPUT
    LAST : DWORD;
END_VAR
VAR
    RX : REAL;
    M : REAL;
END_VAR
M := INT_TO_REAL(BIT_COUNT(IN := LAST));
RX := RDM(LAST := FRACT(X := M * MATH.PI));
RDMDW := SHL(REAL_TO_DWORD(RX * 65535.0), 16);
RX := RDM(LAST := FRACT(X := M * MATH.E));
RDMDW := RDMDW OR (REAL_TO_DWORD(RX * 65535.0) AND DWORD#16#0000FFFF);
END_FUNCTION

FUNCTION REAL_TO_FRAC : FRACTION
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
VAR
    Result : FRACTION;
    Temp : DINT;
    IsNegative : BOOL;
    WorkX : REAL;
    Rounded : DINT;
    IntegerPart : REAL;
    Numerator : DINT := 1;
    Denominator : DINT := 0;
    NumeratorOld : DINT := 0;
    DenominatorOld : DINT := 1;
END_VAR
WorkX := X;
IF WorkX < 0.0 THEN
    IsNegative := TRUE;
    WorkX := ABS(WorkX);
END_IF;
REPEAT
    Rounded := REAL_TO_DINT(WorkX);
    Temp := Numerator * Rounded + NumeratorOld;
    NumeratorOld := Numerator;
    Numerator := Temp;
    Temp := Denominator * Rounded + DenominatorOld;
    DenominatorOld := Denominator;
    Denominator := Temp;
    IntegerPart := DINT_TO_REAL(Rounded);
    IF WorkX = IntegerPart THEN
        IF ABS(Denominator) <= N THEN
            NumeratorOld := Numerator;
            DenominatorOld := Denominator;
        END_IF;
        EXIT;
    ELSE
        WorkX := 1.0 / (WorkX - IntegerPart);
    END_IF;
UNTIL ABS(Denominator) > N
END_REPEAT;
IF IsNegative THEN
    Result.NUMERATOR := -ABS(DINT_TO_INT(NumeratorOld));
ELSE
    Result.NUMERATOR := ABS(DINT_TO_INT(NumeratorOld));
END_IF;
Result.DENOMINATOR := ABS(DINT_TO_INT(DenominatorOld));
REAL_TO_FRAC := Result;
END_FUNCTION

FUNCTION RND : REAL
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
VAR
    M : REAL;
END_VAR
IF X = 0.0 THEN
    RND := 0.0;
ELSE
    M := EXPN(X := 10.0, N := N - CEIL(X := LOG(ABS(X))));
    RND := DINT_TO_REAL(D_TRUNC(X := X * M)) / M;
END_IF;
END_FUNCTION

FUNCTION ROUND : REAL
VAR_INPUT
    IN : REAL;
    N : INT;
END_VAR
VAR
    Scale : REAL;
    Rounded : DINT;
END_VAR
Scale := EXPN(X := 10.0, N := LIMIT(0, N, 8));
IF IN >= 0.0 THEN
    Rounded := D_TRUNC(X := IN * Scale + 0.5);
ELSE
    Rounded := D_TRUNC(X := IN * Scale - 0.5);
END_IF;
ROUND := DINT_TO_REAL(Rounded) / Scale;
END_FUNCTION

FUNCTION SGN : INT
VAR_INPUT
    X : REAL;
END_VAR
IF X > 0.0 THEN
    SGN := 1;
ELSIF X < 0.0 THEN
    SGN := -1;
ELSE
    SGN := 0;
END_IF;
END_FUNCTION

FUNCTION SIGMOID : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 20.0 THEN
    SIGMOID := 1.0;
ELSIF X < -85.0 THEN
    SIGMOID := 0.0;
ELSE
    SIGMOID := 1.0 / (1.0 + EXP(-X));
END_IF;
END_FUNCTION

FUNCTION SIGN_I : BOOL
VAR_INPUT
    IN : DINT;
END_VAR
SIGN_I := IN < 0;
END_FUNCTION

FUNCTION SIGN_R : BOOL
VAR_INPUT
    IN : REAL;
END_VAR
SIGN_R := IN < 0.0;
END_FUNCTION

FUNCTION SINC : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    SINC := 1.0;
ELSE
    SINC := SIN(X) / X;
END_IF;
END_FUNCTION

FUNCTION SINH : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF ABS(X) < 2.0E-3 THEN
    SINH := X;
ELSE
    SINH := (EXP(X) - EXP(-X)) * 0.5;
END_IF;
END_FUNCTION

FUNCTION SQRTN : REAL
VAR_INPUT
    X : REAL;
    N : INT;
END_VAR
IF N > 0 THEN
    IF X = 0.0 THEN
        SQRTN := 0.0;
    ELSIF X > 0.0 THEN
        SQRTN := EXP(LN(X) / INT_TO_REAL(N));
    ELSE
        SQRTN := 0.0;
    END_IF;
ELSE
    SQRTN := 0.0;
END_IF;
END_FUNCTION

FUNCTION TANC : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X = 0.0 THEN
    TANC := 1.0;
ELSE
    TANC := TAN(X) / X;
END_IF;
END_FUNCTION

FUNCTION TANH : REAL
VAR_INPUT
    X : REAL;
END_VAR
IF X > 20.0 THEN
    TANH := 1.0;
ELSIF X < -20.0 THEN
    TANH := -1.0;
ELSE
    TANH := 1.0 - 2.0 / (EXP(2.0 * X) + 1.0);
END_IF;
END_FUNCTION

FUNCTION WINDOW : BOOL
VAR_INPUT
    LOW : REAL;
    IN : REAL;
    HIGH : REAL;
END_VAR
WINDOW := IN < HIGH AND IN > LOW;
END_FUNCTION

FUNCTION WINDOW2 : BOOL
VAR_INPUT
