END_VAR
WINDOW2 := IN >= LOW AND IN <= HIGH;
END_FUNCTION

(* OSCAT BASIC 3.33 Chapter 6 Arrays helpers. *)

FUNCTION _ARRAY_ABS : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    PT^[I] := ABS(PT^[I]);
END_FOR;
_ARRAY_ABS := TRUE;
END_FUNCTION

FUNCTION _ARRAY_ADD : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
    X : REAL;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    PT^[I] := PT^[I] + X;
END_FOR;
_ARRAY_ADD := TRUE;
END_FUNCTION

FUNCTION _ARRAY_INIT : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
    INIT : REAL;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    PT^[I] := INIT;
END_FOR;
_ARRAY_INIT := TRUE;
END_FUNCTION

FUNCTION _ARRAY_MEDIAN : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    Mid : INT;
END_VAR
_ARRAY_SORT(PT := PT, SIZE := SIZE);
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    _ARRAY_MEDIAN := 0.0;
ELSIF (Count MOD 2) = 1 THEN
    Mid := Count / 2;
    _ARRAY_MEDIAN := PT^[Mid];
ELSE
    Mid := Count / 2;
    _ARRAY_MEDIAN := (PT^[Mid - 1] + PT^[Mid]) * 0.5;
END_IF;
END_FUNCTION

FUNCTION _ARRAY_MUL : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
    X : REAL;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    PT^[I] := PT^[I] * X;
END_FOR;
_ARRAY_MUL := TRUE;
END_FUNCTION

FUNCTION _ARRAY_SHUFFLE : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Temp : REAL;
    Pos : INT;
    I : INT;
    Stop : INT;
END_VAR
Stop := UINT_TO_INT(SIZE) / 4 - 1;
FOR I := 0 TO Stop DO
    Pos := RDM2(LAST := I + Pos, LOW := I, HIGH := Stop);
    Temp := PT^[I];
    PT^[I] := PT^[Pos];
    PT^[Pos] := Temp;
END_FOR;
_ARRAY_SHUFFLE := TRUE;
END_FUNCTION

FUNCTION _ARRAY_SORT : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
    J : INT;
    Value : REAL;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 1 TO Count - 1 DO
    Value := PT^[I];
    J := I - 1;
    WHILE J >= 0 DO
        IF PT^[J] > Value THEN
            PT^[J + 1] := PT^[J];
            J := J - 1;
        ELSE
            EXIT;
        END_IF;
    END_WHILE;
    PT^[J + 1] := Value;
END_FOR;
_ARRAY_SORT := TRUE;
END_FUNCTION

FUNCTION ARRAY_AVG : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_AVG := 0.0;
ELSE
    ARRAY_AVG := PT^[0];
    FOR I := 1 TO Count - 1 DO
        ARRAY_AVG := ARRAY_AVG + PT^[I];
    END_FOR;
    ARRAY_AVG := ARRAY_AVG / INT_TO_REAL(Count);
END_IF;
END_FUNCTION

FUNCTION ARRAY_GAV : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
ARRAY_GAV := 1.0;
FOR I := 0 TO Count - 1 DO
    IF PT^[I] > 0.0 THEN
        ARRAY_GAV := ARRAY_GAV * PT^[I];
    ELSE
        ARRAY_GAV := 0.0;
        EXIT;
    END_IF;
END_FOR;
IF ARRAY_GAV > 0.0 THEN
    ARRAY_GAV := SQRTN(X := ARRAY_GAV, N := Count);
END_IF;
END_FUNCTION

FUNCTION ARRAY_HAV : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 1 DO
    IF PT^[I] <> 0.0 THEN
        ARRAY_HAV := ARRAY_HAV + 1.0 / PT^[I];
    ELSE
        ARRAY_HAV := 0.0;
        EXIT;
    END_IF;
END_FOR;
IF ARRAY_HAV <> 0.0 THEN
    ARRAY_HAV := INT_TO_REAL(Count) / ARRAY_HAV;
END_IF;
END_FUNCTION

FUNCTION ARRAY_MAX : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_MAX := 0.0;
ELSE
    ARRAY_MAX := PT^[0];
    FOR I := 1 TO Count - 1 DO
        IF PT^[I] > ARRAY_MAX THEN
            ARRAY_MAX := PT^[I];
        END_IF;
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION ARRAY_MIN : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_MIN := 0.0;
ELSE
    ARRAY_MIN := PT^[0];
    FOR I := 1 TO Count - 1 DO
        IF PT^[I] < ARRAY_MIN THEN
            ARRAY_MIN := PT^[I];
        END_IF;
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION ARRAY_SDV : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
ARRAY_SDV := SQRT(ARRAY_VAR(PT := PT, SIZE := SIZE));
END_FUNCTION

FUNCTION ARRAY_SPR : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
ARRAY_SPR := ARRAY_MAX(PT := PT, SIZE := SIZE) - ARRAY_MIN(PT := PT, SIZE := SIZE);
END_FUNCTION

FUNCTION ARRAY_SUM : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_SUM := 0.0;
ELSE
    ARRAY_SUM := PT^[0];
    FOR I := 1 TO Count - 1 DO
        ARRAY_SUM := ARRAY_SUM + PT^[I];
    END_FOR;
END_IF;
END_FUNCTION

FUNCTION ARRAY_TREND : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    Stop : INT;
    Half : INT;
    StartSecond : INT;
    I : INT;
    Acc : REAL;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 0 THEN
    ARRAY_TREND := 0.0;
ELSE
    Stop := Count - 1;
    Half := Stop / 2;
    FOR I := 0 TO Half DO
        Acc := Acc - PT^[I];
    END_FOR;
    IF (Stop MOD 2) = 0 THEN
        StartSecond := Half;
    ELSE
        StartSecond := Half + 1;
    END_IF;
    FOR I := StartSecond TO Stop DO
        Acc := Acc + PT^[I];
    END_FOR;
    ARRAY_TREND := Acc / INT_TO_REAL(Half + 1);
END_IF;
END_FUNCTION

FUNCTION ARRAY_VAR : REAL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    Avg : REAL;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
IF Count <= 1 THEN
    ARRAY_VAR := 0.0;
ELSE
    Avg := ARRAY_AVG(PT := PT, SIZE := SIZE);
    FOR I := 0 TO Count - 1 DO
        ARRAY_VAR := ARRAY_VAR + (PT^[I] - Avg) * (PT^[I] - Avg);
    END_FOR;
    ARRAY_VAR := ARRAY_VAR / INT_TO_REAL(Count - 1);
END_IF;
END_FUNCTION

FUNCTION IS_SORTED : BOOL
VAR_INPUT
    PT : POINTER TO ARRAY[*] OF REAL;
    SIZE : UINT;
END_VAR
VAR
    Count : INT;
    I : INT;
END_VAR
Count := UINT_TO_INT(SIZE) / 4;
FOR I := 0 TO Count - 2 DO
    IF PT^[I] > PT^[I + 1] THEN
        IS_SORTED := FALSE;
        EXIT;
    END_IF;
END_FOR;
IF Count > 0 THEN
    IS_SORTED := TRUE;
END_IF;
END_FUNCTION

(* OSCAT BASIC 3.33 Chapter 7 complex mathematics helpers. *)

FUNCTION CABS : REAL
VAR_INPUT
    X : COMPLEX;
END_VAR
CABS := HYPOT(X := X.RE, Y := X.IM);
END_FUNCTION

FUNCTION CACOS : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Y : COMPLEX;
    Result : COMPLEX;
END_VAR
Y := CACOSH(X := X);
Result.RE := Y.IM;
Result.IM := -Y.RE;
CACOS := Result;
END_FUNCTION

FUNCTION CACOSH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Y : COMPLEX;
END_VAR
Y.RE := (X.RE - X.IM) * (X.RE + X.IM) - REAL#1.0;
Y.IM := REAL#2.0 * X.RE * X.IM;
Y := CSQRT(X := Y);
Y.RE := Y.RE + X.RE;
Y.IM := Y.IM + X.IM;
CACOSH := CLOG(X := Y);
END_FUNCTION

FUNCTION CADD : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := X.RE + Y.RE;
Result.IM := X.IM + Y.IM;
CADD := Result;
END_FUNCTION

FUNCTION CARG : REAL
VAR_INPUT
    X : COMPLEX;
END_VAR
CARG := ATAN2(Y := X.IM, X := X.RE);
END_FUNCTION

FUNCTION CASIN : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Y : COMPLEX;
    Result : COMPLEX;
END_VAR
Y.RE := -X.IM;
Y.IM := X.RE;
Y := CASINH(X := Y);
Result.RE := Y.IM;
Result.IM := -Y.RE;
CASIN := Result;
END_FUNCTION

FUNCTION CASINH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Y : COMPLEX;
END_VAR
Y.RE := (X.RE - X.IM) * (X.RE + X.IM) + REAL#1.0;
Y.IM := REAL#2.0 * X.RE * X.IM;
Y := CSQRT(X := Y);
Y.RE := Y.RE + X.RE;
Y.IM := Y.IM + X.IM;
CASINH := CLOG(X := Y);
END_FUNCTION

FUNCTION CATAN : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    RealSquared : REAL;
    Numerator : REAL;
    Denominator : REAL;
    Result : COMPLEX;
END_VAR
RealSquared := X.RE * X.RE;
Denominator := REAL#1.0 - RealSquared - X.IM * X.IM;
Result.RE := REAL#0.5 * ATAN(REAL#2.0 * X.RE / Denominator);
Numerator := X.IM + REAL#1.0;
Numerator := RealSquared + Numerator * Numerator;
Denominator := X.IM - REAL#1.0;
Denominator := RealSquared + Denominator * Denominator;
Result.IM := REAL#0.25 * (LN(Numerator) - LN(Denominator));
CATAN := Result;
END_FUNCTION

FUNCTION CATANH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    ImagSquared : REAL;
    Numerator : REAL;
    Denominator : REAL;
    Result : COMPLEX;
END_VAR
ImagSquared := X.IM * X.IM;
Numerator := REAL#1.0 + X.RE;
Numerator := ImagSquared + Numerator * Numerator;
Denominator := REAL#1.0 - X.RE;
Denominator := ImagSquared + Denominator * Denominator;
Result.RE := REAL#0.25 * (LN(Numerator) - LN(Denominator));
Denominator := REAL#1.0 - X.RE * X.RE - ImagSquared;
Result.IM := REAL#0.5 * ATAN(REAL#2.0 * X.IM / Denominator);
CATANH := Result;
END_FUNCTION

FUNCTION CCON : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := X.RE;
Result.IM := -X.IM;
CCON := Result;
END_FUNCTION

FUNCTION CCOS : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result := CCOSH(X := CSET(RE := -X.IM, IM := X.RE));
CCOS := Result;
END_FUNCTION

FUNCTION CCOSH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := COSH(X := X.RE) * COS(X.IM);
Result.IM := SINH(X := X.RE) * SIN(X.IM);
CCOSH := Result;
END_FUNCTION

FUNCTION CDIV : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Result : COMPLEX;
END_VAR
Temp := Y.RE * Y.RE + Y.IM * Y.IM;
Result.RE := (X.RE * Y.RE + X.IM * Y.IM) / Temp;
Result.IM := (X.IM * Y.RE - X.RE * Y.IM) / Temp;
CDIV := Result;
END_FUNCTION

FUNCTION CEXP : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Result : COMPLEX;
END_VAR
Temp := EXP(X.RE);
Result.RE := Temp * COS(X.IM);
Result.IM := Temp * SIN(X.IM);
CEXP := Result;
END_FUNCTION

FUNCTION CINV : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Result : COMPLEX;
END_VAR
Temp := X.RE * X.RE + X.IM * X.IM;
Result.RE := X.RE / Temp;
Result.IM := -X.IM / Temp;
CINV := Result;
END_FUNCTION

FUNCTION CLOG : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := LN(HYPOT(X := X.RE, Y := X.IM));
Result.IM := ATAN2(Y := X.IM, X := X.RE);
CLOG := Result;
END_FUNCTION

FUNCTION CMUL : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := X.RE * Y.RE - X.IM * Y.IM;
Result.IM := X.RE * Y.IM + X.IM * Y.RE;
CMUL := Result;
END_FUNCTION

FUNCTION CPOL : COMPLEX
VAR_INPUT
    L : REAL;
    A : REAL;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := L * COS(A);
Result.IM := L * SIN(A);
CPOL := Result;
END_FUNCTION

FUNCTION CPOW : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result := CEXP(X := CMUL(X := Y, Y := CLOG(X := X)));
CPOW := Result;
END_FUNCTION

FUNCTION CSET : COMPLEX
VAR_INPUT
    RE : REAL;
    IM : REAL;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := RE;
Result.IM := IM;
CSET := Result;
END_FUNCTION

FUNCTION CSIN : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := COSH(X := X.IM) * SIN(X.RE);
Result.IM := SINH(X := X.IM) * COS(X.RE);
CSIN := Result;
END_FUNCTION

FUNCTION CSINH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := SINH(X := X.RE) * COS(X.IM);
Result.IM := COSH(X := X.RE) * SIN(X.IM);
CSINH := Result;
END_FUNCTION

FUNCTION CSQRT : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Result : COMPLEX;
END_VAR
Temp := HYPOT(X := X.RE, Y := X.IM);
Result.RE := SQRT(REAL#0.5 * (Temp + X.RE));
Result.IM := INT_TO_REAL(SGN(X := X.IM)) * SQRT(REAL#0.5 * (Temp - X.RE));
CSQRT := Result;
END_FUNCTION

FUNCTION CSUB : COMPLEX
VAR_INPUT
    X : COMPLEX;
    Y : COMPLEX;
END_VAR
VAR
    Result : COMPLEX;
END_VAR
Result.RE := X.RE - Y.RE;
Result.IM := X.IM - Y.IM;
CSUB := Result;
END_FUNCTION

FUNCTION CTAN : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Xi2 : REAL;
    Xr2 : REAL;
    Result : COMPLEX;
END_VAR
Xi2 := REAL#2.0 * X.IM;
Xr2 := REAL#2.0 * X.RE;
Temp := REAL#1.0 / (COS(Xr2) + COSH(X := Xi2));
Result.RE := Temp * SIN(Xr2);
Result.IM := Temp * SINH(X := Xi2);
CTAN := Result;
END_FUNCTION

FUNCTION CTANH : COMPLEX
VAR_INPUT
    X : COMPLEX;
END_VAR
VAR
    Temp : REAL;
    Xi2 : REAL;
    Xr2 : REAL;
    Result : COMPLEX;
END_VAR
Xi2 := REAL#2.0 * X.IM;
Xr2 := REAL#2.0 * X.RE;
Temp := REAL#1.0 / (COSH(X := Xr2) + COS(Xi2));
Result.RE := Temp * SINH(X := Xr2);
Result.IM := Temp * SIN(Xi2);
CTANH := Result;
END_FUNCTION

(* OSCAT BASIC 3.33 arithmetic helpers with REAL2 double-precision tuples. *)

FUNCTION R2_ABS : REAL2
VAR_INPUT
    X : REAL2;
END_VAR
VAR
    Result : REAL2;
END_VAR

IF X.RX >= REAL#0.0 THEN
    Result.RX := X.RX;
    Result.R1 := X.R1;
ELSE
    Result.RX := -X.RX;
    Result.R1 := -X.R1;
END_IF;
R2_ABS := Result;
END_FUNCTION

FUNCTION R2_ADD : REAL2
VAR_INPUT
    X : REAL2;
    Y : REAL;
END_VAR
VAR
    Temp : REAL;
    Result : REAL2;
END_VAR

Temp := X.RX;
Result.RX := Y + X.R1 + X.RX;
Result.R1 := Temp - Result.RX + Y + X.R1;
R2_ADD := Result;
END_FUNCTION

FUNCTION R2_ADD2 : REAL2
VAR_INPUT
    X : REAL2;
    Y : REAL2;
END_VAR
VAR
    Result : REAL2;
END_VAR

Result.R1 := X.R1 + Y.R1;
Result.RX := X.RX + Y.RX;
R2_ADD2 := Result;
END_FUNCTION

FUNCTION R2_MUL : REAL2
VAR_INPUT
    X : REAL2;
    Y : REAL;
END_VAR
VAR
    Result : REAL2;
END_VAR

Result.RX := X.RX * Y;
Result.R1 := X.R1 * Y;
R2_MUL := Result;
END_FUNCTION

FUNCTION R2_SET : REAL2
VAR_INPUT
    X : REAL;
END_VAR
VAR
    Result : REAL2;
END_VAR

Result.RX := X;
Result.R1 := REAL#0.0;
R2_SET := Result;
END_FUNCTION

(* OSCAT BASIC 3.33 arithmetic function helpers. *)

FUNCTION F_LIN : REAL
VAR_INPUT
    X : REAL;
    A : REAL;
    B : REAL;
END_VAR
F_LIN := A * X + B;
END_FUNCTION

FUNCTION F_LIN2 : REAL
VAR_INPUT
    X : REAL;
    X1 : REAL;
    Y1 : REAL;
    X2 : REAL;
    Y2 : REAL;
END_VAR
F_LIN2 := (Y2 - Y1) / (X2 - X1) * (X - X1) + Y1;
END_FUNCTION

FUNCTION F_POLY : REAL
VAR_INPUT
    X : REAL;
    C : ARRAY[0..7] OF REAL;
END_VAR
F_POLY := (((((((C[7] * X + C[6]) * X + C[5]) * X + C[4]) * X + C[3]) * X + C[2]) * X + C[1]) * X + C[0]);
END_FUNCTION

FUNCTION F_POWER : REAL
VAR_INPUT
