    X : REAL;
    N : REAL;
END_VAR
F_POWER := A * EXPT(X, N);
END_FUNCTION

FUNCTION F_QUAD : REAL
VAR_INPUT
    X : REAL;
    A : REAL;
    B : REAL;
    C : REAL;
END_VAR
F_QUAD := (A * X + B) * X + C;
END_FUNCTION

FUNCTION FRMP_B : BYTE
VAR_INPUT
    START : BYTE;
    DIR : BOOL;
    TD : TIME;
    TR : TIME;
END_VAR
VAR
    TdMs : DWORD;
    TrMs : DWORD;
    DeltaValue : DINT;
    StartValue : DINT;
    ResultValue : DINT;
    MaxDeltaValue : DINT;
END_VAR
IF TD < TR THEN
    TdMs := TIME_TO_DWORD(IN := TD);
    TrMs := TIME_TO_DWORD(IN := TR);
    DeltaValue := D_TRUNC(
        X := UDINT_TO_REAL(IN := DWORD_TO_UDINT(IN := TdMs)) * REAL#256.0
            / UDINT_TO_REAL(IN := DWORD_TO_UDINT(IN := TrMs))
    );
    StartValue := BYTE_TO_DINT(IN := START);
    IF DIR THEN
        MaxDeltaValue := DINT#255 - StartValue;
        IF DeltaValue > MaxDeltaValue THEN
            DeltaValue := MaxDeltaValue;
        END_IF;
        ResultValue := StartValue + DeltaValue;
    ELSE
        MaxDeltaValue := StartValue;
        IF DeltaValue > MaxDeltaValue THEN
            DeltaValue := MaxDeltaValue;
        END_IF;
        ResultValue := StartValue - DeltaValue;
    END_IF;
    FRMP_B := DINT_TO_BYTE(IN := ResultValue);
ELSE
    IF DIR THEN
        FRMP_B := BYTE#255;
    ELSE
        FRMP_B := BYTE#0;
    END_IF;
END_IF;
END_FUNCTION

FUNCTION_BLOCK FT_AVG
VAR_INPUT
    IN : REAL;
    E : BOOL := TRUE;
    N : INT := INT#32;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    AVG : REAL;
END_VAR
VAR
    BUFF : DELAY;
    I : INT;
    INIT : BOOL;
    WINDOW : INT;
END_VAR

WINDOW := LIMIT(INT#0, N, INT#32);
IF NOT INIT OR RST THEN
    FOR I := INT#1 TO WINDOW DO
        BUFF(IN := IN, N := WINDOW, RST := FALSE);
    END_FOR;
    AVG := IN;
    INIT := TRUE;
ELSIF E THEN
    BUFF(IN := IN, N := WINDOW, RST := FALSE);
    AVG := AVG + (IN - BUFF.OUT) / INT_TO_REAL(IN := WINDOW);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_MIN_MAX
VAR_INPUT
    IN : REAL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    MX : REAL;
    MN : REAL;
END_VAR
VAR
    INIT : BOOL;
END_VAR

IF RST OR NOT INIT THEN
    MN := IN;
    MX := IN;
    INIT := TRUE;
ELSIF IN < MN THEN
    MN := IN;
ELSIF IN > MX THEN
    MX := IN;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FT_RMP
VAR_INPUT
    RMP : BOOL := TRUE;
    IN : REAL;
    KR : REAL;
    KF : REAL;
END_VAR
VAR_OUTPUT
    OUT : REAL;
    BUSY : BOOL;
    UD : BOOL;
END_VAR
VAR
    TxMs : DINT;
    LastMs : DINT;
    DeltaMs : DINT;
    INIT : BOOL;
END_VAR

TxMs := DWORD_TO_DINT(T_PLC_MS());
IF NOT INIT THEN
    INIT := TRUE;
    LastMs := TxMs;
    OUT := IN;
END_IF;
DeltaMs := TxMs - LastMs;

IF NOT RMP THEN
    OUT := IN;
    BUSY := FALSE;
ELSIF OUT > IN THEN
    OUT := OUT - DINT_TO_REAL(DeltaMs) * REAL#0.001 * KF;
    OUT := MAX(IN, OUT);
ELSIF OUT < IN THEN
    OUT := OUT + DINT_TO_REAL(DeltaMs) * REAL#0.001 * KR;
    OUT := MIN(IN, OUT);
END_IF;

IF OUT < IN THEN
    BUSY := TRUE;
    UD := TRUE;
ELSIF OUT > IN THEN
    BUSY := TRUE;
    UD := FALSE;
ELSE
    BUSY := FALSE;
END_IF;
LastMs := TxMs;
END_FUNCTION_BLOCK

FUNCTION LINEAR_INT : REAL
VAR_INPUT
    X : REAL;
    XY : ARRAY[1..20, 0..1] OF REAL;
    PTS : INT;
END_VAR
VAR
    I : INT;
    LocalPts : INT;
END_VAR

LocalPts := MIN(PTS, INT#20);
I := INT#2;
WHILE (I < LocalPts) AND (XY[I, 0] < X) DO
    I := I + 1;
END_WHILE;
LINEAR_INT := ((XY[I, 1] - XY[I - 1, 1]) * X - XY[I, 1] * XY[I - 1, 0] + XY[I - 1, 1] * XY[I, 0]) / (XY[I, 0] - XY[I - 1, 0]);
END_FUNCTION

FUNCTION POLYNOM_INT : REAL
VAR_INPUT
    X : REAL;
    XY : ARRAY[1..5, 0..1] OF REAL;
    PTS : INT;
END_VAR
VAR
    I : INT;
    J : INT;
    K : INT;
    Stop : INT;
    LocalPts : INT;
    Work : ARRAY[1..5, 0..1] OF REAL;
END_VAR

LocalPts := MIN(PTS, INT#5);
FOR I := INT#1 TO LocalPts DO
    FOR K := INT#0 TO INT#1 DO
        Work[I, K] := XY[I, K];
    END_FOR;
END_FOR;
FOR I := INT#1 TO LocalPts DO
    Stop := I + 1;
    FOR J := LocalPts TO Stop BY -1 DO
        Work[J, 1] := (Work[J, 1] - Work[J - 1, 1]) / (Work[J, 0] - Work[J - I, 0]);
    END_FOR;
END_FOR;

POLYNOM_INT := REAL#0.0;
FOR I := LocalPts TO INT#1 BY -1 DO
    POLYNOM_INT := POLYNOM_INT * (X - Work[I, 0]) + Work[I, 1];
END_FOR;
END_FUNCTION

(* OSCAT BASIC 3.33 geometric helpers. *)

FUNCTION CIRCLE_A : REAL
VAR_INPUT
    RX : REAL;
    AX : REAL;
END_VAR

CIRCLE_A := RX * RX * REAL#8.726646E-3 * AX;
END_FUNCTION

FUNCTION CIRCLE_C : REAL
VAR_INPUT
    RX : REAL;
    AX : REAL;
END_VAR

CIRCLE_C := REAL#1.7453293E-2 * RX * AX;
END_FUNCTION

FUNCTION CIRCLE_SEG : REAL
VAR_INPUT
    RX : REAL;
    HX : REAL;
END_VAR
VAR
    Angle : REAL;
END_VAR

CIRCLE_SEG := REAL#0.0;
IF RX > REAL#0.0 THEN
    Angle := REAL#2.0 * ACOS(IN := REAL#1.0 - LIMIT(MN := REAL#0.0, IN := HX / RX, MX := REAL#2.0));
    CIRCLE_SEG := (Angle - SIN(IN := Angle)) * RX * RX * REAL#0.5;
END_IF;
END_FUNCTION

FUNCTION CONE_V : REAL
VAR_INPUT
    RX : REAL;
    HX : REAL;
END_VAR

CONE_V := REAL#1.047197551 * RX * RX * HX;
END_FUNCTION

FUNCTION ELLIPSE_A : REAL
VAR_INPUT
    R1 : REAL;
    R2 : REAL;
END_VAR

ELLIPSE_A := REAL#3.141592653589793 * R1 * R2;
END_FUNCTION

FUNCTION ELLIPSE_C : REAL
VAR_INPUT
    R1 : REAL;
    R2 : REAL;
END_VAR

ELLIPSE_C := REAL#3.141592653589793 * (REAL#3.0 * (R1 + R2) - SQRT(IN := (REAL#3.0 * R1 + R2) * (REAL#3.0 * R2 + R1)));
END_FUNCTION

FUNCTION SPHERE_V : REAL
VAR_INPUT
    RX : REAL;
END_VAR

SPHERE_V := REAL#4.188790205 * RX * RX * RX;
END_FUNCTION

FUNCTION TRIANGLE_A : REAL
VAR_INPUT
    S1 : REAL;
    A : REAL;
    S2 : REAL;
    S3 : REAL;
END_VAR

IF A = REAL#0.0 THEN
    TRIANGLE_A := SQRT(IN := (S1 + S2 + S3) * (S1 + S2 - S3) * (S2 + S3 - S1) * (S3 + S1 - S2)) * REAL#0.25;
ELSE
    TRIANGLE_A := S1 * S2 * SIN(IN := RAD(DEG := A)) * REAL#0.5;
END_IF;
END_FUNCTION

(* OSCAT BASIC 3.33 Chapter 11 vector mathematics helpers. *)

FUNCTION V3_ABS : REAL
VAR_INPUT
    A : VECTOR_3;
END_VAR
V3_ABS := SQRT(A.X * A.X + A.Y * A.Y + A.Z * A.Z);
END_FUNCTION

FUNCTION V3_ADD : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := A.X + B.X;
Result.Y := A.Y + B.Y;
Result.Z := A.Z + B.Z;
V3_ADD := Result;
END_FUNCTION

FUNCTION V3_ANG : REAL
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
VAR
    D : REAL;
END_VAR
D := V3_ABS(A := A) * V3_ABS(A := B);
IF D > REAL#0.0 THEN
    V3_ANG := ACOS(LIMIT(REAL#-1.0, V3_DPRO(A := A, B := B) / D, REAL#1.0));
END_IF;
END_FUNCTION

FUNCTION V3_DPRO : REAL
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
V3_DPRO := A.X * B.X + A.Y * B.Y + A.Z * B.Z;
END_FUNCTION

FUNCTION V3_NORM : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    LengthA : REAL;
    Result : VECTOR_3;
END_VAR
LengthA := V3_ABS(A := A);
IF LengthA > REAL#0.0 THEN
    Result := V3_SMUL(A := A, M := REAL#1.0 / LengthA);
END_IF;
V3_NORM := Result;
END_FUNCTION

FUNCTION V3_NUL : BOOL
VAR_INPUT
    A : VECTOR_3;
END_VAR
V3_NUL := A.X = REAL#0.0 AND A.Y = REAL#0.0 AND A.Z = REAL#0.0;
END_FUNCTION

FUNCTION V3_PAR : BOOL
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
V3_PAR := V3_ABS(A := V3_XPRO(A := A, B := B)) = REAL#0.0;
END_FUNCTION

FUNCTION V3_REV : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := -A.X;
Result.Y := -A.Y;
Result.Z := -A.Z;
V3_REV := Result;
END_FUNCTION

FUNCTION V3_SMUL : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
    M : REAL;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := A.X * M;
Result.Y := A.Y * M;
Result.Z := A.Z * M;
V3_SMUL := Result;
END_FUNCTION

FUNCTION V3_SUB : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := A.X - B.X;
Result.Y := A.Y - B.Y;
Result.Z := A.Z - B.Z;
V3_SUB := Result;
END_FUNCTION

FUNCTION V3_XANG : REAL
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    LengthA : REAL;
END_VAR
LengthA := V3_ABS(A := A);
IF LengthA > REAL#0.0 THEN
    V3_XANG := ACOS(A.X / LengthA);
END_IF;
END_FUNCTION

FUNCTION V3_XPRO : VECTOR_3
VAR_INPUT
    A : VECTOR_3;
    B : VECTOR_3;
END_VAR
VAR
    Result : VECTOR_3;
END_VAR
Result.X := A.Y * B.Z - A.Z * B.Y;
Result.Y := A.Z * B.X - A.X * B.Z;
Result.Z := A.X * B.Y - A.Y * B.X;
V3_XPRO := Result;
END_FUNCTION

FUNCTION V3_YANG : REAL
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    LengthA : REAL;
END_VAR
LengthA := V3_ABS(A := A);
IF LengthA > REAL#0.0 THEN
    V3_YANG := ACOS(A.Y / LengthA);
END_IF;
END_FUNCTION

FUNCTION V3_ZANG : REAL
VAR_INPUT
    A : VECTOR_3;
END_VAR
VAR
    LengthA : REAL;
END_VAR
LengthA := V3_ABS(A := A);
IF LengthA > REAL#0.0 THEN
    V3_ZANG := ACOS(A.Z / LengthA);
END_IF;
END_FUNCTION

