    D0 : BOOL;
    D1 : BOOL;
    D2 : BOOL;
    D3 : BOOL;
    L : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    Q0 : BOOL;
    Q1 : BOOL;
    Q2 : BOOL;
    Q3 : BOOL;
END_VAR

IF RST THEN
    Q0 := FALSE;
    Q1 := FALSE;
    Q2 := FALSE;
    Q3 := FALSE;
ELSIF L THEN
    Q0 := D0;
    Q1 := D1;
    Q2 := D2;
    Q3 := D3;
