END_FUNCTION_BLOCK

FUNCTION_BLOCK FF_DRE
VAR_INPUT
    SetIn : BOOL;
    DATA : BOOL;
    CLK : BOOL;
    RST : BOOL;
END_VAR
VAR_OUTPUT
    Q : BOOL;
END_VAR
VAR
    Edge : BOOL;
