(* OSCAT BASIC 3.33 and OSCAT BUILDING control modules by manual chapter. *)

FUNCTION_BLOCK ACTUATOR_COIL
VAR_INPUT
	IN : BOOL;
END_VAR
VAR_INPUT CONSTANT
	self_act_cycle : TIME := t#10d;
	self_act_time : TIME := t#1s;
END_VAR
VAR_OUTPUT
	OUT :BOOL;
	STATUS : BYTE;
END_VAR
VAR
	last : UDINT;
	init: BOOL;
	tx: UDINT;
	now: UDINT;
END_VAR
now := DWORD_TO_UDINT(T_PLC_MS());
IF NOT init THEN
	last := now;
	init := TRUE;
END_IF;
IF IN THEN
	OUT := TRUE;
	STATUS := BYTE#101;
	LAST := now;
ELSE
	OUT := FALSE;
	STATUS := BYTE#100;
	tx := now - last;
	IF (self_act_cycle > T#0s) AND (tx >= DWORD_TO_UDINT(TIME_TO_DWORD(self_act_cycle))) THEN
		OUT := TRUE;
		STATUS := BYTE#102;
		IF tx >= DWORD_TO_UDINT(TIME_TO_DWORD(self_act_cycle)) + DWORD_TO_UDINT(TIME_TO_DWORD(self_act_time)) THEN
			last := now;
			OUT := FALSE;
			STATUS := BYTE#100;
		END_IF;
	END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TIMER_1
VAR_INPUT
	E : BOOL := TRUE;
	DTI : DT;
	START : TOD;
	DURATION : TIME;
	DAY : BYTE := 2#0111_1111;
END_VAR
VAR_OUTPUT
	Q : BOOL;
	stop : TIME;
END_VAR
VAR
	StopTod : TOD;
END_VAR
IF E THEN
	StopTod := ADD_TOD_TIME(START, DURATION);
	stop := ADD_TIME(
		HOUR_TO_TIME(INT_TO_REAL(HOUR(StopTod))),
		ADD_TIME(
			MINUTE_TO_TIME(INT_TO_REAL(MINUTE(StopTod))),
			SECOND_TO_TIME(SECOND(StopTod))
		)
	);
	Q := TIMECHECK(TD := DT_TO_TOD(DTI), START := START, STOP := StopTod)
		AND (SHR(BYTE#128, DAY_OF_WEEK(DT_TO_DATE(DTI))) AND DAY) > BYTE#0;
ELSE
	Q := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION BAND_B : BYTE
VAR_INPUT
	X : BYTE;
	B : BYTE;
END_VAR
IF X < B THEN
	BAND_B := BYTE#0;
ELSIF BYTE_TO_INT(X) > INT#255 - BYTE_TO_INT(B) THEN
	BAND_B := BYTE#255;
ELSE
	BAND_B := X;
END_IF;
END_FUNCTION

FUNCTION_BLOCK CONTROL_SET1
VAR_INPUT
	Kt : REAL;
	Tt : REAL;
	PI : BOOL;
	PID : BOOL;
END_VAR
VAR_INPUT CONSTANT
	P_K : REAL := 0.5;
	PI_K : REAL := 0.45;
	PI_TN : REAL := 0.83;
	PID_K : REAL := 0.6;
	PID_TN : REAL := 0.5;
	PID_TV : REAL := 0.125;
END_VAR
VAR_OUTPUT
	KP : REAL;
	TN : REAL;
	TV : REAL;
	KI : REAL;
	KD : REAL;
END_VAR
IF pi AND PID THEN
	KP := 0.0;
	TN := 0.0;
	TV := 0.0;
ELSIF PID THEN
	KP := PID_K * Kt;
	TN := PID_TN * Tt;
	TV := PID_TV * Tt;
ELSIF PI THEN
	KP := PI_K * Kt;
	TN := PI_TN * Tt;
ELSE
	KP := P_K * Kt;
END_IF;
IF tn > 0.0 THEN KI := KP / TN; ELSE KI := 0.0; END_IF;
KD := KP * TV;
END_FUNCTION_BLOCK

FUNCTION_BLOCK CONTROL_SET2
VAR_INPUT
	KS : REAL;
	TU : REAL;
	TG : REAL;
	PI : BOOL;
	PID : BOOL;
END_VAR
VAR_INPUT CONSTANT
	P_K : REAL := 1.0;
	PI_K : REAL := 0.9;
	PI_TN : REAL := 3.33;
	PID_K : REAL := 1.2;
	PID_TN : REAL := 2.0;
	PID_TV : REAL := 0.5;
END_VAR
VAR_OUTPUT
	KP : REAL;
	TN : REAL;
	TV : REAL;
	KI : REAL;
	KD : REAL;
END_VAR
VAR
	TX : REAL;
END_VAR
IF TU > 0.0 AND KS > 0.0 THEN TX := TG / TU / KS; END_IF;
IF pi AND PID THEN
	KP := 0.0;
	TN := 0.0;
	TV := 0.0;
ELSIF PID THEN
	KP := PID_K * TX;
	TN := PID_TN * TU;
	TV := PID_TV * TU;
ELSIF PI THEN
	KP := PI_K * TX;
	TN := PI_TN * TU;
ELSE
	KP := P_K * TX;
END_IF;
IF TN > 0.0 THEN KI := KP / TN; ELSE KI := 0.0; END_IF;
KD := KP * TV;
END_FUNCTION_BLOCK

FUNCTION CTRL_IN : REAL
VAR_INPUT
