FUNCTION_BLOCK SRAMP
VAR_INPUT
	X : REAL;
	A_UP : REAL;
	A_DN :REAL;
	VU_MAX : REAL;
	VD_MAX : REAL;
	LIMIT_HIGH : REAL;
	LIMIT_LOW : REAL;
	RST : BOOL;
END_VAR
VAR_OUTPUT
	Y : REAL;
	V : REAL;
END_VAR
VAR
	cycle_time : TC_S;
	init: BOOL;
	AUpLimited : REAL;
	ADnLimited : REAL;
	VUpMaxLimited : REAL;
	VDnMaxLimited : REAL;
END_VAR
cycle_time();
AUpLimited := MAX(0.0, A_UP);
ADnLimited := MIN(0.0, A_DN);
VUpMaxLimited := MAX(0.0, VU_MAX);
VDnMaxLimited := MIN(0.0, VD_MAX);
IF rst OR NOT init THEN
	init := TRUE;
	Y := 0.0;
	V := 0.0;
ELSIF X = Y THEN
	v := 0.0;
ELSIF X > Y THEN
	v := MIN(v + AUpLimited * cycle_time.TC, VUpMaxLimited);
	v := MIN(SQRT((Y-X) * 2.0 * ADnLimited), v);
	y := LIMIT(limit_low, y + MIN(v * cycle_time.TC, X-Y), limit_high);
ELSIF X < Y THEN
	v := MAX(v + ADnLimited * cycle_time.TC, VDnMaxLimited);
	v := MAX(-SQRT((Y-X) * 2.0 * AUpLimited), v);
	y := LIMIT(limit_low, y + MAX(v * cycle_time.TC, X-Y), limit_high);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TUNE
VAR_INPUT
    SET_REQ : BOOL;
    SU, SD : BOOL;
    RST : BOOL;
END_VAR
VAR_INPUT CONSTANT
    SS : REAL := 0.1;
    Limit_L : REAL;
    LIMIT_H : REAL := 100.0;
    RST_val : REAL;
    SET_val : REAL := 100.0;
    T1 : TIME := T#500ms;
    T2 : TIME := T#2s;
    S1 : REAL := 2.0;
    S2 : REAL := 10.0;
END_VAR
VAR_OUTPUT
    Y : REAL;
END_VAR
VAR
    tx : DWORD;
    start, start2 : DWORD;
    state : INT;
    in : BOOL;
    STEP_DELTA : REAL;
    SPEED : REAL;
    Y_start : REAL;
    Y_start2 : REAL;
    ElapsedMs : UDINT;
    T1Ms : UDINT;
    T2Ms : UDINT;
END_VAR

tx := T_PLC_MS();
T1Ms := DWORD_TO_UDINT(TIME_TO_DWORD(T1));
T2Ms := DWORD_TO_UDINT(TIME_TO_DWORD(T2));
IF rst THEN
    Y := RST_val;
    state := 0;
ELSIF SET_REQ THEN
    Y := SET_val;
    state := 0;
ELSIF state > 0 THEN
    IF state = 1 THEN
        in := su;
    ELSE
        in := sd;
    END_IF;
    ElapsedMs := DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(start);
    IF NOT in AND ElapsedMs <= T1Ms THEN
        Y := Y_start + STEP_DELTA;
        state := 0;
    ELSIF in AND ElapsedMs >= T2Ms THEN
        Y := Y_start2 + UDINT_TO_REAL(DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(start2)) * s2 / speed;
    ELSIF in AND ElapsedMs >= T1Ms THEN
        Y := Y_start + UDINT_TO_REAL(ElapsedMs - T1Ms) * S1 / speed;
        start2 := tx;
        Y_start2 := Y;
    ELSIF NOT in THEN
        state := 0;
    END_IF;
ELSIF su THEN
    state := 1;
    start := tx;
    STEP_DELTA := ss;
    speed := 1000.0;
    Y_start := Y;
ELSIF sd THEN
    state := 2;
    start := tx;
    STEP_DELTA := -ss;
    speed := -1000.0;
    Y_start := Y;
END_IF;
Y := LIMIT(LIMIT_L, Y, LIMIT_H);
END_FUNCTION_BLOCK

FUNCTION_BLOCK TUNE2
VAR_INPUT
    SET_REQ : BOOL;
    SU, SD : BOOL;
    FU, FD : BOOL;
    RST : BOOL;
END_VAR
VAR_INPUT CONSTANT
    SS : REAL := 0.1;
    FS : REAL := 5.0;
    Limit_L : REAL;
    LIMIT_H : REAL := 100.0;
    RST_val : REAL;
    SET_val : REAL := 100.0;
    TR : TIME := T#500ms;
    S1 : REAL := 2.0;
    S2 : REAL := 10.0;
END_VAR
VAR_OUTPUT
    Y : REAL;
END_VAR
VAR
    tx : DWORD;
    start : DWORD;
    state : INT;
    in : BOOL;
    STEP_DELTA : REAL;
    SPEED : REAL;
    Y_start : REAL;
    ElapsedMs : UDINT;
    TRMs : UDINT;
END_VAR

tx := T_PLC_MS();
TRMs := DWORD_TO_UDINT(TIME_TO_DWORD(TR));
IF rst THEN
    Y := RST_val;
    state := 0;
ELSIF SET_REQ THEN
    Y := SET_val;
    state := 0;
ELSIF state > 0 THEN
    CASE state OF
        1 :
            in := su;
        2 :
            in := sd;
        3 :
            in := fu;
        4 :
            in := fd;
    END_CASE;
    ElapsedMs := DWORD_TO_UDINT(tx) - DWORD_TO_UDINT(start);
    IF NOT in AND ElapsedMs <= TRMs THEN
        Y := Y_start + STEP_DELTA;
        state := 0;
    ELSIF in AND ElapsedMs >= TRMs THEN
        Y := Y_start + UDINT_TO_REAL(ElapsedMs - TRMs) * speed;
    ELSIF NOT in THEN
        state := 0;
    END_IF;
ELSIF su THEN
    state := 1;
    start := tx;
    STEP_DELTA := ss;
    speed := s1 * 1.0E-3;
    Y_start := Y;
ELSIF sd THEN
    state := 2;
    start := tx;
    STEP_DELTA := -ss;
    speed := -s1 * 1.0E-3;
    Y_start := Y;
ELSIF fu THEN
    state := 3;
    start := tx;
    STEP_DELTA := fs;
    speed := s2 * 1.0E-3;
    Y_start := Y;
ELSIF fd THEN
    state := 4;
    start := tx;
    STEP_DELTA := -fs;
    speed := -s2 * 1.0E-3;
    Y_start := Y;
END_IF;
Y := LIMIT(LIMIT_L, Y, LIMIT_H);
END_FUNCTION_BLOCK

FUNCTION _BUFFER_CLEAR : BOOL
