FUNCTION_BLOCK EcoStrategy IMPLEMENTS IAhuStrategy
VAR
    ReadyValue : BOOL;
    ErrorValue : BOOL;
    ErrorIdValue : WORD;
    StatusValue : BYTE;
    OutputValue : REAL;
    Filter : Pt1Filter;
END_VAR

METHOD PUBLIC Initialize
ReadyValue := TRUE;
Filter.Initialize();
