FUNCTION_BLOCK PUBLIC ABSTRACT TcoUrRoboticsTask EXTENDS TcoCore.TcoTask 
VAR_IN_OUT
    inoConfig 	: TcoUrRobotics_Config_v_1_x_x;
	inoControl 	: TcoUrRobotics_Control_v_1_x_x;
	inoStatus 	: TcoUrRobotics_Status_v_1_x_x;	
END_VAR
VAR
	_errorMessage:TcoCore.TcoMessenger(THIS^);
    {attribute 'hide'} 
	_progress : INT := 0;
    {attribute 'hide'} 
	_infoTimer :  TON;
    {attribute 'hide'} 
	_errorTimer :  TON;
	{attribute 'hide'} 
	_timer :  TON;
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
	{attribute 'hide'}
	_blink:TcoUtilities.TcoBlinker(THIS^);
END_VAR

END_FUNCTION_BLOCK

FUNCTION_BLOCK StartAtMainTask EXTENDS TcoUrRoboticsTask
IF Execute() THEN 
	_blink(inOnTime:=T#500MS,inOffTime:=T#500MS);

	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoControl) THEN
			_varInfo :=__VARINFO(inoControl);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSE
			_progress := _progress + 1;
		END_IF

	END_IF

	IF _progress = 1 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.NO_IsNormalMode)
		.Warning(_sb.Clear().Append('<# Waiting to Normal Mode. #>').ToString());
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.RD_IsReducedMode)
		.Warning(_sb.Clear().Append('<# Waiting to Reduced Mode. #>').ToString());

		IF inoStatus.State.Inputs.Safety.NO_IsNormalMode OR inoStatus.State.Inputs.Safety.RD_IsReducedMode THEN
			_progress := _progress + 1;

		END_IF
	END_IF;		

	IF _progress = 2 THEN

		inoControl.Start :=   _blink.outQ;
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Robot.PR_IsProgramRunning).Warning(_sb.Clear().Append('<#Waiting to program running! #>').ToString());

		IF inoStatus.State.Inputs.Robot.PR_IsProgramRunning THEN
			inoControl.Start :=FALSE;
			_progress:=0;
		END_IF
	END_IF
    DoneWhen(inoStatus.State.Inputs.Robot.PR_IsProgramRunning );

    CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q );

END_IF;

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK StartMotorsAndProgramTask EXTENDS TcoUrRoboticsTask
IF Execute() THEN
	 _blink(inOnTime:=T#500MS,inOffTime:=T#500MS);

  	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoControl) THEN
			_varInfo :=__VARINFO(inoControl);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSE

			_progress := _progress + 1;

		END_IF

	END_IF

	IF _progress = 1 THEN
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.NO_IsNormalMode)
		.Warning(_sb.Clear().Append('<# Waiting to Normal Mode. #>').ToString());
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.RD_IsReducedMode)
		.Warning(_sb.Clear().Append('<# Waiting to Reduced Mode. #>').ToString());

		IF inoStatus.State.Inputs.Safety.NO_IsNormalMode OR inoStatus.State.Inputs.Safety.RD_IsReducedMode THEN
			_progress := _progress + 1;

		END_IF
	END_IF;		

	IF _progress = 2 THEN	
		Messenger.Warning('<#Robot has error Reset#>');

		IF NOT inoStatus.State.Inputs.Safety.FT_IsFault THEN
			_progress := _progress + 1;
		END_IF
	END_IF;

	IF _progress = 3 THEN	
		Messenger.Debug('<#Robot Emergency Stop Reset#>');
		_varInfo :=__VARINFO( inoStatus.State.Inputs.Safety.ES_IsEmergencyStopped );                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.ES_IsEmergencyStopped ).Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

		_varInfo :=__VARINFO( inoStatus.State.Inputs.Safety.PS_IsProtectiveStopped );                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.PS_IsProtectiveStopped ).Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

		_varInfo :=__VARINFO( inoStatus.State.Inputs.Safety.SS_IsSafeguardStopped );                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.SS_IsSafeguardStopped ).Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

		_varInfo :=__VARINFO( inoStatus.State.Inputs.Safety.RC_IsRecoveryMode );                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.RC_IsRecoveryMode ).Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

		_varInfo :=__VARINFO( inoStatus.State.Inputs.Safety.ST_IsStoppedDueSafety );                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.ES_IsEmergencyStopped ).Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

		_varInfo :=__VARINFO( inoStatus.State.Inputs.Safety.VL_IsViolation );                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.VL_IsViolation ).Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());


		IF NOT inoStatus.State.Inputs.Safety.ES_IsEmergencyStopped 
				AND NOT inoStatus.State.Inputs.Safety.PS_IsProtectiveStopped  
				AND NOT inoStatus.State.Inputs.Safety.SS_IsSafeguardStopped  
				AND NOT inoStatus.State.Inputs.Safety.RC_IsRecoveryMode 
				AND NOT inoStatus.State.Inputs.Safety.ST_IsStoppedDueSafety 
				AND NOT inoStatus.State.Inputs.Safety.VL_IsViolation THEN
			_progress := _progress + 1;
		END_IF
	END_IF;


	IF _progress = 4 THEN	
		IF inoStatus.State.Inputs.Safety.FT_IsFault THEN 
			_progress := 1;
		END_IF
		Messenger.Debug('<#Robot Power on#>');
		_varInfo :=__VARINFO( inoStatus.State.Inputs.Robot.PW_IsPowerOn);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Robot.PW_IsPowerOn).Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());
		_varInfo :=__VARINFO( inoStatus.State.Inputs.Safety.FT_IsFault);                                                
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.FT_IsFault).Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

		inoControl.MotorOn:=_blink.outQ;	
		IF inoStatus.State.Inputs.Robot.PW_IsPowerOn  AND NOT inoStatus.State.Inputs.Safety.FT_IsFault THEN
			 inoControl.MotorOn:=FALSE;
			_progress := _progress + 1;
		END_IF
	END_IF;		

	IF _progress = 5 THEN	
		IF inoStatus.State.Inputs.Safety.FT_IsFault THEN 
			_progress := 1;
		END_IF
		inoControl.Start:=_blink.outQ;
		THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Robot.PR_IsProgramRunning).Warning(_sb.Clear().Append('<#Waiting to program running! #>').ToString());

		IF  inoStatus.State.Inputs.Robot.PR_IsProgramRunning AND NOT inoStatus.State.Inputs.Safety.FT_IsFault THEN
				inoControl.Start:=FALSE;
		END_IF
	END_IF;		


    DoneWhen(inoStatus.State.Inputs.Robot.PR_IsProgramRunning AND inoStatus.State.Inputs.Robot.PW_IsPowerOn AND NOT inoStatus.State.Inputs.Safety.FT_IsFault);
    CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q );

END_IF

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK StartMotorsProgramAndMovementsTask EXTENDS TcoUrRoboticsTask
VAR_INPUT
	refStartMotorsAndProgramTask: REFERENCE TO StartMotorsAndProgramTask;
END_VAR 
VAR
     _moveParams:TcoAbstractions.TcoRoboticsMovementsParams;


END_VAR
VAR
	_startMotorsAndProgramTask: REFERENCE TO StartMotorsAndProgramTask;
END_VAR
IF NOT __ISVALIDREF(refStartMotorsAndProgramTask)  THEN
    Messenger.Post('<#Invalid reference StartMotorAndProgramTask#>', TcoCore.eMessageCategory.ProgrammingError);
    RETURN;
END_IF
_startMotorsAndProgramTask REF= refStartMotorsAndProgramTask;

IF Execute() THEN
	IF _progress = 0 THEN
		IF NOT __ISVALIDREF(inoControl) THEN
			_varInfo :=__VARINFO(inoControl);
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoConfig) THEN                                                  
			_varInfo :=__VARINFO(inoConfig);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
		ELSIF NOT __ISVALIDREF(inoStatus) THEN                                                  
			_varInfo :=__VARINFO(inoStatus);                                                    
			Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
			ELSE
			_progress := _progress + 1;
		END_IF

	END_IF

	IF _progress = 1 THEN
		IF _startMotorsAndProgramTask.Invoke().Done THEN
			_progress := _progress + 1;
		END_IF

	END_IF;


	IF _progress = 2 THEN
		inoControl.GlobalSpeed := _moveParams.GlobalSpeed;
		inoControl.ToolNo := _moveParams.ToolNo;
		inoControl.WorkobjectNo := _moveParams.WorkobjectNo;
		inoControl.PointNo := _moveParams.PointNo;
		inoControl.UserSpecSpeed1 := _moveParams.UserSpecSpeed1;
		inoControl.UserSpecSpeed2 := _moveParams.UserSpecSpeed2;
		inoControl.Coordinates := _moveParams.Coordinates; 		

		inoControl.ActionNo := 254;
		IF inoControl.ActionNo = inoStatus.State.ActionNo THEN
			_progress:=_progress + 1;
		END_IF
	END_IF;	
	IF _progress = 3 THEN
		IF 	inoStatus.State.GlobalSpeed = _moveParams.GlobalSpeed AND
			inoStatus.State.ToolNo = _moveParams.ToolNo AND
			inoStatus.State.WorkobjectNo = _moveParams.WorkobjectNo AND
			inoStatus.State.PointNo = _moveParams.PointNo AND
			inoStatus.State.UserSpecSpeed1 = _moveParams.UserSpecSpeed1 AND
			inoStatus.State.UserSpecSpeed2 =_moveParams.UserSpecSpeed2 AND
			TcoAbstractions.CoordinatesAreEqual(inoStatus.State.Coordinates,_moveParams.Coordinates,0.01,0.01,0.01,0.01,0.01,0.01) THEN
			inoControl.ActionNo := 255;
			_progress:=_progress + 1;
		END_IF
	END_IF;	

	IF _progress = 4 THEN
		IF inoControl.ActionNo = inoStatus.State.ActionNo THEN
			_progress:=_progress + 1;
		END_IF
	END_IF;	


	IF _progress = 5 THEN

		Messenger.Info(CONCAT('<#Moving to position ID#>: ', INT_TO_STRING(_moveParams.ActionNo)));
		inoControl.ActionNo := _moveParams.ActionNo;
		IF inoControl.ActionNo = inoStatus.State.ActionNo THEN
			inoControl.ActionNo :=255;
				_progress := _progress + 1;
		END_IF
	END_IF;		

	IF _progress = 6 THEN
		IF inoControl.ActionNo = inoStatus.State.ActionNo THEN
			 DoneWhen(TRUE);
		END_IF
	END_IF;		

   CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q OR inoStatus.State.Inputs.Safety.FT_IsFault);
END_IF

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK StartMotorsTask EXTENDS TcoUrRoboticsTask
IF Execute() THEN
    _blink(inOnTime := T#500MS, inOffTime := T#500MS);

    IF _progress = 0 THEN
        IF NOT __ISVALIDREF(inoControl) THEN
            _varInfo := __VARINFO(inoControl);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT __ISVALIDREF(inoConfig) THEN
            _varInfo := __VARINFO(inoConfig);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSIF NOT __ISVALIDREF(inoStatus) THEN
            _varInfo := __VARINFO(inoStatus);
            Messenger.Programming(_sb.Clear().Append('<#Invalid reference: #>').Append(_varInfo.Symbol).ToString()).Pin();
        ELSE

            _progress := _progress + 1;

        END_IF

    END_IF

    IF _progress = 1 THEN
        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.NO_IsNormalMode)
            .Warning(_sb.Clear().Append('<# Waiting to Normal Mode. #>').ToString());

        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.RD_IsReducedMode)
            .Warning(_sb.Clear().Append('<# Waiting to Reduced Mode. #>').ToString());

        IF inoStatus.State.Inputs.Safety.NO_IsNormalMode OR inoStatus.State.Inputs.Safety.RD_IsReducedMode THEN
            _progress := _progress + 1;

        END_IF
    END_IF;

    IF _progress = 2 THEN
        Messenger.Warning('<#Robot has error Reset#>');

        IF NOT inoStatus.State.Inputs.Safety.FT_IsFault THEN
            _progress := _progress + 1;
        END_IF
    END_IF;

    IF _progress = 3 THEN
        Messenger.Debug('<#Robot Emergency Stop Reset#>');
        _varInfo := __VARINFO(inoStatus.State.Inputs.Safety.ES_IsEmergencyStopped);
        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.ES_IsEmergencyStopped)
            .Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

        _varInfo := __VARINFO(inoStatus.State.Inputs.Safety.PS_IsProtectiveStopped);
        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.PS_IsProtectiveStopped)
            .Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

        _varInfo := __VARINFO(inoStatus.State.Inputs.Safety.SS_IsSafeguardStopped);
        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.SS_IsSafeguardStopped)
            .Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

        _varInfo := __VARINFO(inoStatus.State.Inputs.Safety.RC_IsRecoveryMode);
        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.RC_IsRecoveryMode)
            .Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

        _varInfo := __VARINFO(inoStatus.State.Inputs.Safety.ST_IsStoppedDueSafety);
        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.ES_IsEmergencyStopped)
            .Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

        _varInfo := __VARINFO(inoStatus.State.Inputs.Safety.VL_IsViolation);
        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.VL_IsViolation)
            .Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

        //inoControl.ResetEmgStop := inoStatus.State.EmgStop AND _blink.outQ;
        IF NOT inoStatus.State.Inputs.Safety.ES_IsEmergencyStopped AND
            NOT inoStatus.State.Inputs.Safety.PS_IsProtectiveStopped AND
            NOT inoStatus.State.Inputs.Safety.SS_IsSafeguardStopped AND
            NOT inoStatus.State.Inputs.Safety.RC_IsRecoveryMode AND
            NOT inoStatus.State.Inputs.Safety.ST_IsStoppedDueSafety AND
            NOT inoStatus.State.Inputs.Safety.VL_IsViolation THEN
            //inoControl.ResetEmgStop:=FALSE;
            _progress := _progress + 1;
        END_IF
    END_IF;

    IF _progress = 4 THEN
        IF inoStatus.State.Inputs.Safety.FT_IsFault THEN
            _progress := 1;
        END_IF

        Messenger.Debug('<#Robot Power on#>');
        _varInfo := __VARINFO(inoStatus.State.Inputs.Robot.PW_IsPowerOn);
        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Robot.PW_IsPowerOn)
            .Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

        _varInfo := __VARINFO(inoStatus.State.Inputs.Safety.FT_IsFault);
        THIS^.Messenger.OnCondition(_infoTimer.Q AND NOT inoStatus.State.Inputs.Safety.FT_IsFault)
            .Warning(_sb.Clear().Append('<# Waiting for signal: #>').Append(_varInfo.Symbol).ToString());

        inoControl.MotorOn := _blink.outQ;

        IF inoStatus.State.Inputs.Robot.PW_IsPowerOn AND NOT inoStatus.State.Inputs.Safety.FT_IsFault AND
		    inoStatus.State.Inputs.Joints.JointMode[0] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[1] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[2] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[3] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[4] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[5] = 253 THEN
            inoControl.MotorOn := FALSE;
            _progress := _progress + 1;
        END_IF
    END_IF;


    DoneWhen(inoStatus.State.Inputs.Robot.PW_IsPowerOn AND
            NOT inoStatus.State.Inputs.Safety.FT_IsFault AND
            inoStatus.State.Inputs.Joints.JointMode[0] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[1] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[2] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[3] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[4] = 253 AND
            inoStatus.State.Inputs.Joints.JointMode[5] = 253);

    CallTimers(TRUE);

    THIS^.ThrowWhen(_errorTimer.Q);

END_IF

IF THIS^.Error AND NOT _errorMessage.Pinned THEN
    THIS^.Restore();
END_IF
END_FUNCTION_BLOCK

