			AND inoConfig.SeparatorHasWorkPosition
			AND inoStatus.SeparatorWorkPos THEN
			_progress := _progress + 1;
			_timer(In:=FALSE); 
		ELSIF inoConfig.OutOfBoxSensorDisabled 
			AND NOT inoConfig.SeparatorHasWorkPosition
			AND _timer.Q  THEN
			_progress := _progress + 1;
			_timer(In:=FALSE); 

