		THIS^.DoneWhen(TRUE);
	END_IF;		


    CallTimers(TRUE);

	THIS^.ThrowWhen(_errorTimer.Q );

END_IF

inoStatus.ComponentReady:=_componentReady;

IF  THIS^.Error AND NOT _errorMessage.Pinned THEN
	THIS^.Restore();
END_IF
