FUNCTION_BLOCK RealValueSimulation
VAR_INPUT
    inMinValue : REAL;
    inMaxValue : REAL;
END_VAR
VAR_IN_OUT
    inoutValue : REAL;
END_VAR
VAR
	_dc : LREAL :=5.4;
    _min : REAL;
    _max : REAL;
    _p1 : LREAL := 2;
    _p2 : LREAL := 3.5;
    _x0 : LREAL;
    _x1 : LREAL;
    _pm : LREAL;
	_ex : LREAL;
END_VAR
_ex := EXPT(10, _dc);
_x0 := inoutValue * _ex;

IF _x0 = 0 THEN
    _x0 := (inMaxValue + inMinValue) / 2 * _ex;
END_IF

_min := inMinValue * _ex;
_max := inMaxValue * _ex;
_pm := (_max - _min);
_x1 := _min + (Tc2_Math.LMOD((_x0 * _p1 + _p2), _pm));

inoutValue := Tc2_Math.LTRUNC(_x1 / _ex);
END_FUNCTION_BLOCK

