    {attribute 'hide'}
    _mcReadStatus : Tc2_MC2.MC_ReadStatus;


    _override : LREAL := 100.0;
	{attribute 'hide'}
	_overrideInternal : LREAL :=100.0;
	{attribute addProperty Name "<#Axis status#>"}
    {attribute clr [ReadOnly()]}
    _axisStatus : TcoAxisStatus;
	{attribute addProperty Name "<#Axis config#>"}
    _config : TcoAxisConfig;

	_reduceMovementsInServiceMode:REAL;

END_VAR
