		ContextOpen();	
		THIS^.PLCinstanceRun();
		_cycleCount := _cycleCount + 1;
		_runPLCinstanceOnce := FALSE;
		ContextClose();	
	END_IF

	IF _runPLCinstanceCyclicaly AND NOT _runPLCinstanceOnce THEN
		ContextOpen();	
		THIS^.PLCinstanceRun();
		_cycleCount := _cycleCount + 1;
		ContextClose();	
	END_IF
END_IF;
