FUNCTION_BLOCK TcoDesigner_v_2_x_x  EXTENDS TcoCore.TcoComponent
VAR_IN_OUT
	inoData:TcoDesignerRootContainer;
END_VAR

VAR
	{attribute addProperty Name "<#Generic Data#>"}
	_genericData:TcoDesignerData_2_x_x;
	{attribute addProperty Name "<#Config#>"}
    _config : TcoDesignerConfig_v_2_x_x;
	{attribute addProperty Name "<#Status#>"}
	_status : TcoDesignerStatus_v_2_x_x;	

	_triggerType: eTcoDesignerTriggerType;
	_internalLiveBit: BOOL;
END_VAR


VAR

	{attribute 'hide'}
    _taskEnabled : BOOL;
	{attribute addProperty Name "<#Restore#>"}
    _restoreTask : TcoCore.TcoTask(THIS^);

	{attribute addProperty Name "<#Clear result data#>"}
    _clearResultDataTask : TcoDesignerClearInspectionResults_v_2_x_x(THIS^);

	{attribute clr [RenderIgnore()]}
    _triggerInternalTask :TcoDesignerTrigger_v_2_x_x(THIS^);

	{attribute addProperty Name "<#Trigger#>"}
    _triggerTask : TcoCore.TcoTask(THIS^);
	{attribute addProperty Name "<#Trigger Fast#>"}
    _triggerFastTask : TcoCore.TcoTask(THIS^);
	{attribute addProperty Name "<#Trigger with Timeout#>"}
    _triggerWithTimeoutTask : TcoCore.TcoTask(THIS^);	

	{attribute addProperty Name "<#Results#>"}
	{attribute clr [MemberByIdentity()]}
	_specificData : TcoDesignerRootContainer(THIS^);


	_timerConnection: TON;



END_VAR

VAR
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
END_VAR
_specificData:=inoData;
_status.SignalStatus:=_genericData.PcToPlc;

_timerConnection(In:=_internalLiveBit XOR _status.SignalStatus.LiveBit ,PT:=_config.ConnectionTimemout);
_status.ClientConnected:= NOT  _timerConnection.Q;//_timerConnection.ET<_timerConnection.PT AND _timerConnection.ET<>T#0MS;
_internalLiveBit:=NOT _status.SignalStatus.LiveBit;
IF NOT _status.ClientConnected  THEN
	THIS^._status.ActionDescription := '<#Vision system is not  responding via Ads. Check connection with Cognex Designer!#>';	
	THIS^.Messenger.Error(_status.ActionDescription).Pin();

END_IF


//*************RESTORE********************

_restoreTask.Enabled := TRUE;
IF _restoreTask.Execute() THEN
	Restore();
	_restoreTask.DoneWhen(TRUE);
END_IF
//****************************************


//****************************************

//*************CLEAR*DATA*****************
_clearResultDataTask.Enabled := _status.ClientConnected;
_clearResultDataTask(inoIoData := _genericData,inoConfig := THIS^._config,inoStatus := THIS^._status);
//****************************************

//*************TRIGGER ********************
_triggerTask.Enabled :=  NOT _triggerFastTask.Busy AND NOT _triggerWithTimeoutTask.Busy  AND _status.ClientConnected;
IF _triggerTask.Execute() THEN
	_triggerInternalTask.Enabled :=  TRUE;
	_triggerType :=eTcoDesignerTriggerType.Trigger;
	_triggerTask.DoneWhen(_triggerInternalTask.Invoke().Done);
	_triggerTask.ThrowWhen(_triggerInternalTask.Error);
END_IF
//***********************************************

//*************TRIGGER WITH TIMEOUT********************

_triggerWithTimeoutTask.Enabled :=  NOT _triggerFastTask.Busy AND NOT _triggerTask.Busy  AND _status.ClientConnected;
IF _triggerWithTimeoutTask.Execute() THEN
	_triggerInternalTask.Enabled :=  TRUE;
	_triggerType :=eTcoDesignerTriggerType.TriggerWithTimeout;
	_triggerWithTimeoutTask.DoneWhen(_triggerInternalTask.Invoke().Done);
	_triggerWithTimeoutTask.ThrowWhen(_triggerInternalTask.Error);
END_IF
//***********************************************



//*************TRIGGER FAST********************

_triggerFastTask.Enabled :=  NOT _triggerWithTimeoutTask.Busy AND NOT _triggerTask.Busy  AND _status.ClientConnected;
IF _triggerFastTask.Execute() THEN
	_triggerInternalTask.Enabled :=  TRUE;
	_triggerType :=eTcoDesignerTriggerType.TriggerFast;

	_triggerFastTask.DoneWhen(_triggerInternalTask.Invoke().Done);
	_triggerFastTask.ThrowWhen(_triggerInternalTask.Error);
END_IF
//***********************************************

_triggerInternalTask(inTriggerType:=_triggerType, refClearResultsTask:=_clearResultDataTask, inoIoData := _genericData,inoConfig := THIS^._config,inoStatus := THIS^._status);

inoData:=_specificData;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TcoInsight_v_5_x_x  EXTENDS TcoIo.TcoPnIoComponent 
VAR_IN_OUT
	inoIoData : TcoInsightIO_v_5_x_x;
END_VAR

VAR
	{attribute addProperty Name "<#Config#>"}
    _config : TcoInsightConfig_v_5_x_x;
	{attribute addProperty Name "<#Status#>"}
	_status : TcoInsightStatus_v_5_x_x;	
END_VAR

VAR
	{attribute addProperty Name "<#UserData#>"}
	_userData 	: TcoInsightUser_v_5_x_x;
	{attribute addProperty Name "<#Results#>"}
	_results : TcoInsightResults_v_5_x_x;
END_VAR

VAR
	{attribute 'hide'}
    _taskEnabled : BOOL;
	{attribute addProperty Name "<#Restore#>"}
    _restoreTask : TcoCore.TcoTask(THIS^);
	{attribute addProperty Name "<#Update signal states#>"}
    _updateSignalStatesTask : TcoCore.TcoTask(THIS^);
	{attribute addProperty Name "<#Change job by number#>"}
    _changeJobByNumberTask : TcoInsightChangeJobByNumber_v_5_x_x(THIS^);
	{attribute addProperty Name "<#Change job by name#>"}
    _changeJobByNameTask : TcoInsightChangeJobByName_v_5_x_x(THIS^);
	{attribute addProperty Name "<#Clear inspection results#>"}
    _clearInspectionResultsTask : TcoInsightClearInspectionResults_v_5_x_x(THIS^);
	{attribute addProperty Name "<#Soft event#>"}
    _softEventTask : TcoInsightSoftEvent_v_5_x_x(THIS^);
	{attribute addProperty Name "<#Trigger#>"}
    _triggerTask : TcoInsightTrigger_v_5_x_x(THIS^);
END_VAR
VAR
    {attribute 'hide'} 
	_varInfo : __SYSTEM.VAR_INFO;
    {attribute 'hide'} 
	_sb : TcoCore.StringBuilder;
END_VAR
IF InvalidReference() THEN
    RETURN;
END_IF

SUPER^(inPnIoBoxState := THIS^.inoIoData.PnIoBoxState,inPnIoBoxDiag := THIS^.inoIoData.PnIoBoxDiag);

IF NOT SUPER^.ProfinetReady THEN
	THIS^._status.ActionDescription := '<#Not ready for operation by means of Profinet network!#>';	
END_IF

IF SUPER^.ProfinetReady AND THIS^._status.ActionDescription = '<#Not ready for operation by means of Profinet network!#>' THEN
	THIS^._status.ActionDescription := '<#Ready for operation!#>';	
END_IF

CheckIfOnline();

//*************RESTORE********************
_taskEnabled := TRUE;
_restoreTask.Enabled := _taskEnabled;
IF _restoreTask.Execute() THEN
	Restore();
//	UpdateSignalStates();
END_IF
//****************************************

//*************UPDATE*********************
IF _config.UpdateStatesPermanently THEN
	UpdateSignalStates();
END_IF;

_taskEnabled:=SUPER^.ProfinetReady;
_taskEnabled := _taskEnabled AND NOT _restoreTask.Busy ;
_updateSignalStatesTask.Enabled := _taskEnabled;
IF _updateSignalStatesTask.Execute() THEN
	UpdateSignalStates();
END_IF
//****************************************

//*************CHANGE*JOB*BY*NUMBER*******
_taskEnabled:=SUPER^.ProfinetReady;
_taskEnabled := _taskEnabled AND NOT _updateSignalStatesTask.Busy;
_changeJobByNumberTask.Enabled := _taskEnabled;
_changeJobByNumberTask(inoIoData := THIS^.inoIoData,inoConfig := THIS^._config,inoStatus := THIS^._status);
//****************************************

//*************CHANGE*JOB*BY*NAME*********
_taskEnabled:=SUPER^.ProfinetReady;
_taskEnabled := _taskEnabled AND NOT _changeJobByNumberTask.Busy;
_changeJobByNameTask.Enabled := _taskEnabled;
_changeJobByNameTask(inoIoData := THIS^.inoIoData,inoConfig := THIS^._config,inoStatus := THIS^._status);
//****************************************

//*************CLEAR*DATA*****************
_taskEnabled:=SUPER^.ProfinetReady;
_taskEnabled := _taskEnabled AND NOT _changeJobByNameTask.Busy;
_clearInspectionResultsTask.Enabled := _taskEnabled;
_clearInspectionResultsTask(inoIoData := THIS^.inoIoData,inoConfig := THIS^._config,inoStatus := THIS^._status,inoResults := THIS^._results);
//****************************************

//*************SOFT*EVENT*****************
_taskEnabled:=SUPER^.ProfinetReady;
_taskEnabled := _taskEnabled AND THIS^.inoIoData.AcquisitionStatus.Online AND NOT _clearInspectionResultsTask.Busy;
_softEventTask.Enabled := _taskEnabled;
_softEventTask(inoIoData := THIS^.inoIoData,inoConfig := THIS^._config,inoStatus := THIS^._status);
//****************************************

//*************TRIGGER********************
_taskEnabled:=SUPER^.ProfinetReady;
_taskEnabled := _taskEnabled AND NOT _clearInspectionResultsTask.Busy;
_triggerTask.Enabled :=  _taskEnabled;
_triggerTask(inoIoData := THIS^.inoIoData,inoConfig := THIS^._config,inoStatus := THIS^._status,inoResults := THIS^._results);
//****************************************
END_FUNCTION_BLOCK

