FUNCTION CalculateDistance : REAL
VAR_INPUT
	inDistType : eTcoRoboticsDistance;
	inP1 : TcoRoboticsCoordinates;
	inP2 : TcoRoboticsCoordinates;
END_VAR
CASE inDistType OF
	eTcoRoboticsDistance.X:
		CalculateDistance := SQRT(EXPT((inP1.X-inP2.X),2));	
	eTcoRoboticsDistance.Y:
		CalculateDistance := SQRT(EXPT((inP1.Y-inP2.Y),2));	
	eTcoRoboticsDistance.Z:
		CalculateDistance := SQRT(EXPT((inP1.Z-inP2.Z),2));	
	eTcoRoboticsDistance.XY:
		CalculateDistance := SQRT(EXPT((inP1.X-inP2.X),2)+EXPT((inP1.Y-inP2.Y),2));	
	eTcoRoboticsDistance.XZ:
		CalculateDistance := SQRT(EXPT((inP1.X-inP2.X),2)+EXPT((inP1.Z-inP2.Z),2));	
	eTcoRoboticsDistance.YZ:
		CalculateDistance := SQRT(EXPT((inP1.Y-inP2.Y),2)+EXPT((inP1.Z-inP2.Z),2));	
	eTcoRoboticsDistance.XYZ:
		CalculateDistance := SQRT(EXPT((inP1.X-inP2.X),2)+EXPT((inP1.Y-inP2.Y),2)+EXPT((inP1.Z-inP2.Z),2));	
END_CASE
END_FUNCTION_BLOCK

FUNCTION CoordinatesAreEqual : bool
VAR_INPUT
	Coordinates1 : TcoRoboticsCoordinates;
	Coordinates2 : TcoRoboticsCoordinates;
	EpsilonX : REAL; 
	EpsilonY : REAL; 
	EpsilonZ : REAL; 
	EpsilonRx : REAL; 
	EpsilonRy : REAL; 
	EpsilonRz : REAL; 
END_VAR

VAR

END_VAR
CoordinatesAreEqual :=	IsNearlyEqual(Coordinates1.X,Coordinates2.X,EpsilonX)  AND
						IsNearlyEqual(Coordinates1.Y,Coordinates2.Y,EpsilonY)  AND
						IsNearlyEqual(Coordinates1.Z,Coordinates2.Z,EpsilonZ)  AND
						IsNearlyEqual(Coordinates1.Rx,Coordinates2.Rx,EpsilonRx)  AND
						IsNearlyEqual(Coordinates1.Ry,Coordinates2.Ry,EpsilonRy)  AND
						IsNearlyEqual(Coordinates1.Rz,Coordinates2.Rz,EpsilonRz);
END_FUNCTION_BLOCK

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE eTcoRoboticsStopType :
(
	Soft := 10,
	Quick := 20
);
END_TYPE

FUNCTION  IsNearlyEqual : bool
VAR_INPUT
	Coordinate1 : REAL;
	Coordinate2 : REAL;
	Epsilon : REAL; 
END_VAR
VAR
	AbsCoordinate1 : REAL;
	AbsCoordinate2 : REAL;
	Diff : REAL;
	Denominator : LREAL;
END_VAR
IsNearlyEqual := FALSE;
AbsCoordinate1 := ABS(Coordinate1);
AbsCoordinate2 := ABS (Coordinate2);
Diff := ABS(Coordinate1-Coordinate2) ;
Denominator := AbsCoordinate1;
Denominator := Denominator + AbsCoordinate2;

IF Epsilon < 0 THEN
	RETURN;
END_IF	

IF Coordinate1 = Coordinate2 THEN
	IsNearlyEqual := TRUE;
ELSIF (Coordinate1 = 0 OR Coordinate2 = 0) AND Diff <= Epsilon THEN 
	IsNearlyEqual := Diff <= Epsilon;
ELSE
	IsNearlyEqual := Diff / Denominator <= Epsilon;
END_IF;
END_FUNCTION_BLOCK

