/// Integrate with constant jerk for duration t. Returns new position, new velocity, and new acceleration.
FUNCTION INTERNAL Integrate
VAR_INPUT
  t, p0, v0, a0, j : LREAL;
END_VAR
VAR_IN_OUT
  p, v, a : LREAL;
END_VAR
p := p0 + t * (v0 + t * (a0 * 0.5 + t * j / 6));
v := v0 + t * (a0 + t * j * 0.5);
a := a0 + t * j;
END_FUNCTION_BLOCK

