{attribute 'hide'}
/// Internal bubble-sort helper for `LREAL` arrays.
/// Returns sorted index positions in `indicesSorted` without modifying input `data`.
FUNCTION BubbleSortLreal : BOOL
VAR_INPUT
  data : POINTER TO LREAL; //< Input unsorted array.
  size : INT; //< Number of elements in `data`.
  indicesSorted : POINTER TO INT; //< Output sorted indices.
END_VAR
VAR
  i, j, h : INT;
END_VAR
FOR i:=0 TO size
DO
  indicesSorted[i] := i;
END_FOR

// Bubblesort possible_t_syncs from best to worst
FOR i:=0 TO size-1
DO
  FOR j:=0 TO size-1-i
  DO  
    IF data[indicesSorted[j]] > data[indicesSorted[j+1]]
    THEN
      h := indicesSorted[j];
      indicesSorted[j] := indicesSorted[j+1];
      indicesSorted[j+1] := h;     
		END_IF
  END_FOR
END_FOR
END_FUNCTION_BLOCK

