/// Returns the smallest integer value greater than or equal to `val`.
/// NaN and +/-Infinity are passed through unchanged.
FUNCTION Ceil : LREAL
VAR_INPUT
  val : LREAL; //< Input value.
END_VAR
VAR CONSTANT
  InfinityBits : ULINT := ULINT#16#7FF0000000000000;
END_VAR
VAR
  InfinityPtr : POINTER TO LREAL := ADR(InfinityBits);
END_VAR
IF val <> val OR_ELSE val = InfinityPtr^ OR_ELSE val = -InfinityPtr^ // nan or inf
THEN
  RETURN;
END_IF

Ceil := DINT_TO_LREAL(LREAL_TO_DINT(val));
IF Ceil < val THEN
	Ceil := Ceil + 1;
END_IF;
END_FUNCTION_BLOCK

