  Sigma : LREAL;
  Size : DINT;
  Maximum : LREAL;
  Minimum : LREAL;
END_VAR
VAR
  _meanMem : LREAL;
  _varianceSum : LREAL;
END_VAR

END_FUNCTION_BLOCK

