// Clones a generic.
// NOTE: memory is allocated in the heap for the clone and is set to pValue. Dont forget to delete it when done. 
FUNCTION F_Clone_Generic : T_Generic
VAR_INPUT
	Source : T_Generic;
END_VAR
VAR_OUTPUT
	bSuccess : BOOL;
	Error : T_Error := GVL_Errors.ERR_NO_ERROR;
END_VAR
F_Clone_Generic.diSize := Source.diSize;
F_Clone_Generic.TypeClass := Source.TypeClass;

IF Source.pValue = 0 OR_ELSE Source.diSize = 0 THEN bSuccess := TRUE; RETURN; END_IF

F_Clone_Generic.pValue := __NEW(BYTE, TO_UDINT(Source.diSize));

IF F_Clone_Generic.pValue = 0 THEN
	Error := GVL_Errors.ERR_MALLOC_FAILED;
	RETURN;
	END_IF

CASE Source.TypeClass OF
	T_Type.TYPE_STRING:
		Tc2_Utilities.STRNCPY(F_Clone_Generic.pValue, Source.pValue, TO_UDINT(Source.diSize));
	T_Type.TYPE_WSTRING:
		Tc2_Utilities.WSTRNCPY(F_Clone_Generic.pValue, Source.pValue, TO_UDINT(Source.diSize));
ELSE
	Tc2_System.MEMCPY(F_Clone_Generic.pValue, Source.pValue, TO_UDINT(Source.diSize));
	END_CASE

bSuccess := TRUE;
END_FUNCTION_BLOCK

// Compares value A to generic value B of any type and returns the evaluation.
FUNCTION F_Compare_Any : T_Comparison
VAR_INPUT
	A : ANY;
	B : ANY;
END_VAR
F_Compare_Any := F_Compare_Generics(A, B);
END_FUNCTION_BLOCK

// Compares generic value A to generic value B and returns the evaluation.
FUNCTION F_Compare_Generics : T_Comparison
VAR_INPUT
	A, B : T_Generic;
END_VAR
VAR_OUTPUT
	bUndefined : BOOL; // If TRUE, values were compared but truthfulness of comparison cannot be verified. 
END_VAR
VAR
	fA, fB : LREAL;
	tA, tB : LTIME;
	dtA, dtB : DT;
END_VAR
IF F_Is_Numeric_Generic(A) AND_THEN F_Is_Numeric_Generic(B) THEN
	fA := F_Generic_To_LREAL(A);
	fB := F_Generic_To_LREAL(B);
	F_Compare_Generics := SEL(fA = fB, SEL(fA > fB, T_Comparison.Less, T_Comparison.Greater), T_Comparison.Equal);
	RETURN;
	END_IF

IF F_Is_Time_Generic(A) AND_THEN F_Is_Time_Generic(B) THEN
	tA := F_Generic_To_LTIME(A);
	tB := F_Generic_To_LTIME(B);
	F_Compare_Generics := SEL(tA = tB, SEL(tA > tB, T_Comparison.Less, T_Comparison.Greater), T_Comparison.Equal);
	RETURN;
	END_IF

IF F_Is_Date_Generic(A) AND_THEN F_Is_Date_Generic(B) THEN
	dtA := F_Generic_To_DT(A);
	dtB := F_Generic_To_DT(B);
	F_Compare_Generics := SEL(dtA = dtB, SEL(dtA > dtB, T_Comparison.Less, T_Comparison.Greater), T_Comparison.Equal);
	RETURN;
	END_IF

IF F_Matching_Generics(A, B) THEN
	bUndefined := A.TypeClass = T_Type.TYPE_USERDEF;
	A.diSize := SEL(A.TypeClass = T_Type.TYPE_STRING, SEL(A.TypeClass = T_Type.TYPE_WSTRING, A.diSize, TO_DINT(Tc2_Utilities.WLEN2(A.pValue))) , TO_DINT(Tc2_Utilities.LEN2(A.pValue)));
	B.diSize := SEL(B.TypeClass = T_Type.TYPE_STRING, SEL(B.TypeClass = T_Type.TYPE_WSTRING, B.diSize, TO_DINT(Tc2_Utilities.WLEN2(B.pValue))) , TO_DINT(Tc2_Utilities.LEN2(B.pValue)));
	CASE Tc2_System.MEMCMP(A.pValue, B.pValue, TO_UDINT(MIN(A.diSize, B.diSize))) OF
		-1		: F_Compare_Generics := T_Comparison.Less;
		0		: F_Compare_Generics := T_Comparison.Equal;
		1		: F_Compare_Generics := T_Comparison.Greater;
		16#FF	:
			bUndefined := TRUE; 
			F_Compare_Generics := SEL(A.diSize = B.diSize, SEL(A.diSize > B.diSize, T_Comparison.Less, T_Comparison.Greater), T_Comparison.Equal);
		END_CASE
	RETURN;
	END_IF

bUndefined := TRUE;
F_Compare_Generics := SEL(A.TypeClass > B.TypeClass, T_Comparison.Less, T_Comparison.Greater);
END_FUNCTION_BLOCK

