IF NOT( __ISVALIDREF(Source) OR_ELSE __ISVALIDREF(Destination)) THEN 
	Error := GVL_Errors.ERR_INVALID_REFERENCE;
	RETURN; 
	END_IF

bSuccess := Tc2_System.MEMCPY(
	Destination.pValue, Source.pValue, 
	TO_UDINT(MIN(Source.diSize, Destination.diSize))) > 0;
END_FUNCTION_BLOCK

// Deletes a generic's value.
FUNCTION F_Delete_Generic
VAR_INPUT
	Source : REFERENCE TO T_Generic;
END_VAR
VAR_OUTPUT
	bSuccess : BOOL;
	Error : T_Error := GVL_Errors.ERR_NO_ERROR;
END_VAR
IF (NOT __ISVALIDREF(Source)) THEN 
	Error := GVL_Errors.ERR_INVALID_REFERENCE;
	RETURN;
	END_IF

CASE Tc2_System.F_CheckMemoryArea(Source.pValue, 1) OF
	Tc2_System.E_TcMemoryArea.Dynamic: __DELETE(Source.pValue);
