// Allocates memory for T_Generic.
FUNCTION F_Malloc_Generic : POINTER TO T_Generic
VAR_INPUT
	Count : T_Capacity;
END_VAR
VAR_OUTPUT
	bSuccess : BOOL;
	Error : T_Error := GVL_Errors.ERR_NO_ERROR;
END_VAR
VAR
	i : T_Capacity;
	Size : UDINT;
END_VAR
IF Count = 0 THEN bSuccess := TRUE; RETURN; END_IF

Size := TO_UDINT(SIZEOF(T_Generic) * Count);
F_Malloc_Generic := __NEW(BYTE, Size);

IF F_Malloc_Generic = 0 THEN 
	Error := GVL_Errors.ERR_MALLOC_FAILED;
	RETURN;
	END_IF

FOR i := 0 TO count - 1 DO
	F_Malloc_Generic[i].TypeClass := T_Type.TYPE_NONE;
	END_FOR

bSuccess := TRUE;
END_FUNCTION_BLOCK

// Checks if 2 generics can be compared to see if they match (same size, same class). Match = TRUE, Not Matching = FALSE.
// The exception is strings. If 2 generics are strings they're considered to be matching regardless of size;
FUNCTION F_Matching_Generics : BOOL
VAR_INPUT
	A, B : T_Generic;
END_VAR
F_Matching_Generics := 
	(A.diSize = B.diSize AND_THEN A.TypeClass = B.TypeClass)
	OR_ELSE
	(A.TypeClass = __SYSTEM.TYPE_CLASS.TYPE_STRING AND_THEN B.TypeClass = __SYSTEM.TYPE_CLASS.TYPE_STRING)
	OR_ELSE
	(A.TypeClass = __SYSTEM.TYPE_CLASS.TYPE_WSTRING AND_THEN B.TypeClass = __SYSTEM.TYPE_CLASS.TYPE_WSTRING);
END_FUNCTION_BLOCK

// Generates a 32-bit hash code using MurmurHash3, created by Austin Appleby. Source: https://en.wikipedia.org/wiki/MurmurHash
FUNCTION F_Murmur3_Hash : DWORD
VAR_INPUT
	Data : T_Generic;
END_VAR
VAR
	i, nSize 	: UDINT;
	nK, nHash 	: DWORD;
END_VAR
CASE Data.TypeClass OF
	__SYSTEM.TYPE_CLASS.TYPE_STRING:
		nSize := Tc2_Utilities.LEN2(Data.pValue);
	__SYSTEM.TYPE_CLASS.TYPE_WSTRING:
		nSize := Tc2_Utilities.WLEN2(Data.pValue)*2;
ELSE
		nSize := TO_UDINT(Data.diSize);
END_CASE

FOR i := SHR(nSize, 2) TO 1 BY -1 DO
	MEMCPY(ADR(nK), Data.pValue, SIZEOF(DWORD));
	Data.pValue := Data.pValue + SIZEOF(DWORD);
	nHash := nHash XOR F_Murmur_Scramble(nK);
	nHash := SHL(nHash,13) OR SHR(nHash,19);
	nHash := nHash * 5 + 16#E6546B64;
	END_FOR

nK := 0;
FOR i := (nSize AND 3) TO 1 BY -1 DO
	nK := SHL(nK,8);
	nK := nK OR Data.pValue[i-1];
	END_FOR

nHash := nHash XOR F_Murmur_Scramble(nK);
nHash := nHash XOR nSize;
nHash := nHash XOR SHR(nHash, 16);
nHash := nHash * 16#85EBCA6B;
nHash := nHash XOR SHR(nHash, 13);
nHash := nHash * 16#C2B2AE35;
nHash := nHash XOR SHR(nHash, 16); 

F_Murmur3_Hash := nHash;
END_FUNCTION_BLOCK

FUNCTION INTERNAL F_Murmur_Scramble : DWORD
VAR_INPUT
	nK : DWORD;
END_VAR
VAR
END_VAR
nK := nK * 16#CC9E2D51;
nK := SHL(nK, 15) OR SHR(nK, 17);
nK := nK * 16#1B873593;
F_Murmur_Scramble := nK;
END_FUNCTION_BLOCK

// Converts string to generic.
FUNCTION F_String_To_Any
VAR_INPUT
	sValue : REFERENCE TO STRING;
	Value : ANY;
END_VAR
VAR_OUTPUT
	bSuccess : BOOL;
	Error : T_Error := GVL_Errors.ERR_NO_ERROR;
END_VAR
VAR
	pBool			: POINTER TO BOOL;
    pByte			: POINTER TO BYTE;
    pWord			: POINTER TO WORD;
    pDWord			: POINTER TO DWORD;
    pLWord			: POINTER TO LWORD;
    pSint			: POINTER TO SINT;
    pInt			: POINTER TO INT;
    pDint			: POINTER TO DINT;
    pLint			: POINTER TO LINT;
    pUSint			: POINTER TO USINT;
    pUInt			: POINTER TO UINT;
    pUDint			: POINTER TO UDINT;
    pULint			: POINTER TO ULINT;
    pReal			: POINTER TO REAL;
    pLReal			: POINTER TO LREAL;
    pString			: POINTER TO STRING(255);
    pWString		: POINTER TO WSTRING;
    pTime			: POINTER TO TIME;
    pDate			: POINTER TO DATE;
    pDate_And_Time	: POINTER TO DATE_AND_TIME;
    pTime_Of_Day	: POINTER TO TIME_OF_DAY;
    pPointer		: POINTER TO PVOID;
	pLTime 			: POINTER TO LTIME;
END_VAR
IF (Value.pValue = 0) OR_ELSE (NOT __ISVALIDREF(sValue)) THEN 
	Error := GVL_Errors.ERR_INVALID_REFERENCE;
	RETURN; 
	END_IF;

IF NOT F_String_Convertable_Generic(Value) THEN
	Error := GVL_Errors.ERR_INVALID_CONVERSION;
	RETURN;
	END_IF

CASE Value.TypeClass OF 
	__SYSTEM.TYPE_CLASS.TYPE_BOOL:
		pBool := Value.pValue;
		pBool^ := TO_BOOL(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_BYTE:
		pByte := Value.pValue;
		pByte^ := TO_BYTE(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_WORD:
		pWord := Value.pValue;
		pWord^ := TO_WORD(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_DWORD:
		pDWord := Value.pValue;
		pDWord^ := TO_DWORD(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_LWORD:
		pLWord := Value.pValue;
		pLWord^ := TO_LWORD(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_SINT:
		pSint := Value.pValue;
		pSint^ := TO_SINT(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_INT:
		pInt := Value.pValue;
		pInt^ := TO_INT(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_DINT:
		pDint := Value.pValue;
		pDint^ := TO_DINT(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_LINT:
		pLint := Value.pValue;
		pLint^ := TO_LINT(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_USINT:
		pUSint := Value.pValue;
		pUSint^ := TO_USINT(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_UINT:
		pUInt := Value.pValue;
		pUInt^ := TO_UINT(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_UDINT:
		pUDint := Value.pValue;
		pUDint^ := TO_UDINT(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_ULINT:
		pULint := Value.pValue;
		pULint^ := TO_ULINT(sValue);

   __SYSTEM.TYPE_CLASS.TYPE_REAL:
		pReal := Value.pValue;
		pReal^ := TO_REAL(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_LREAL:
		pLReal := Value.pValue;
		pLReal^ := TO_LREAL(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_STRING:
		Tc2_Utilities.STRNCPY(Value.pValue, ADR(sValue), TO_UDINT(Value.diSize)); 

   __SYSTEM.TYPE_CLASS.TYPE_WSTRING:
   		Tc2_Utilities.STRING_TO_WSTRING2(Value.pValue, ADR(sValue), TO_UDINT(Value.diSize));

    __SYSTEM.TYPE_CLASS.TYPE_TIME:
		pTime := Value.pValue;
		pTime^ := TO_TIME(sValue);

	__SYSTEM.TYPE_CLASS.TYPE_LTIME:
		pLTime := Value.pValue;
		pLTime^ := TO_LTIME(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_DATE:
		pDate := Value.pValue;
		pDate^ := TO_DATE(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_DATEANDTIME:
		pDate_And_Time := Value.pValue;
		pDate_And_Time^ := TO_DT(sValue);

    __SYSTEM.TYPE_CLASS.TYPE_TIMEOFDAY:
		pTime_Of_Day := Value.pValue;
		pTime_Of_Day^ := TO_TOD(sValue);

	__SYSTEM.TYPE_CLASS.TYPE_POINTER:
		pPointer := Value.pValue;
		pPointer^ := Tc2_Utilities.STRING_TO_PVOID(sValue);
END_CASE

bSuccess := TRUE;
END_FUNCTION_BLOCK

// Swaps generic A with B.
FUNCTION F_Swap_Generics
VAR_INPUT
	A, B : REFERENCE TO T_Generic;
END_VAR
VAR_OUTPUT
	bSuccess : BOOL;
	Error : T_Error := GVL_Errors.ERR_NO_ERROR;
END_VAR
VAR
	Tmp : T_Generic;
END_VAR
IF NOT(__ISVALIDREF(A) AND_THEN __ISVALIDREF(B)) THEN 
	Error := GVL_Errors.ERR_INVALID_REFERENCE;
	RETURN;
	END_IF

Tmp := A;
A := B;
B := Tmp;
bSuccess := TRUE;
END_FUNCTION_BLOCK

