/// `TcLog` is the client side of the logger.  
///
/// It is used to send the logs to `TcLogCore`. Typically, it is instantiated
/// once in each `FUNCTION_BLOCK` or `PROGRAM` where logging is done. The same 
/// instance can then be used for all logging within that POU. 
///
/// `TcLog` implements a string builder that facilitates the compilation of the log
/// message without the need for external data type conversions or multiple chained `CONCAT` calls.
/// See the method section for more information.
///
/// The last method to call after the log message has been built is one of ´[Debug|Information|Warning|Error|Fatal]`. 
/// This sets the log level of the message and sends it off to the log message queue of `TcLogCore` where it will
/// be processed according to its configuration.
{attribute 'hide_all_locals'}
{attribute 'reflection'} 
FUNCTION_BLOCK TcLog IMPLEMENTS ILog
VAR
  _logConditionSatisfied : BOOL; // flag that indicates, whether log condition has been satisfied.
                                // Logging will only be carried out it this evaluates to TRUE.                    
  _logDataInitialized : BOOL; // flag that indicate, whether log data has been initialized.
                             // Necessary for configuration methods to provide a fluent interface.                            
  _logData : Tc2_System.T_MaxString; // contains message to be logged.
  _usedLogger : ILogCore;
  {attribute 'instance-path'} 
  {attribute 'noinit'} 
  _instancePath : STRING; // contains instance path
END_VAR
VAR_STAT
  {attribute 'hide'}
  s_loggerSingletonInstance : ILogCore; // Wires up TcLog ("Client") to TcLogCore ("Server") (Singleton-Behaviour)
END_VAR
VAR CONSTANT
  InvalidLoggerReference : UDINT := 0;
END_VAR

END_FUNCTION_BLOCK

/// `TcLogCore` provides the base functionality of the logger and sets the configuration.
/// The logger can be configured by calling its methods that set the configuration.
///
/// > [!NOTE]
/// > `TcLogCore.RunLogger()` should be called once each cycle. The configuration methods should be called **before** 
/// > `RunLogger` is called.
///
/// When declaring an instance of TcLogCore, the ininital buffer size has to be set. If the buffer size is set too low, it will expand
/// automatically if enough memory is available.
///
/// To set the inital buffer size to accomodate 100 messages, use it like this:
///
/// ```st
/// VAR
///   myLogger: TcLogCore(BufferSize := 100 * (Tc2_System.MAX_STRING_LENGTH * Constants.FifoOverhead));
/// END_VAR
/// ```
///
{attribute 'hide_all_locals'}
FUNCTION_BLOCK TcLogCore IMPLEMENTS ILogCore
VAR
	_loggingSingleton : TcLog; // Logger-Singleton: Required to provide Singleton-functionality for TcLog.
	_utcTimeAsFileTime : Tc2_Utilities.T_FILETIME; // Current utc time as filetime
	_localTimeAsSystemTime : Tc2_Utilities.TIMESTRUCT; // Current local time as timestring
	_localTimeAsString : STRING; // Current local time as string
	_logCache : DynamicStringBuffer; // Dynamic string buffer to cache logs to be processed
	_startLoggingConfiguration : BOOL; // Aux variable to provide fluent interface.
	_internalErrorOccured : BOOL; // Aux variable to log internal errors to Error-property.                                                   				
	_config : LoggingConfiguration; // Logging configuration. Is set by invoking configuration methods.
	_error : Error; // Contains information about internal error.
	_busy : BOOL; // Logger is busy, typically with writing logs to the file system.
  _timeInfoReady : BOOL := FALSE; // Set to true once the time information is available
END_VAR
// Nothing to be done here. Logger works by invoking its methods.
// "RunLogger" contains all the implementation that has to be processed cyclically.
END_FUNCTION_BLOCK

