	ipState=> ipCurrentState);


xOn				:= FALSE;
xOff			:= FALSE;
xCancel			:= FALSE;
xCardInserted	:= FALSE;
xCardEjected	:= FALSE;


CASE ipCurrentState.Description OF 
	E_StateDescription.Undefined :
						CurrentStateDescription := 'ATM is in undefined state, please contact the bank.';
	E_StateDescription.Off :	
