FUNCTION F_VerboseLogger : BOOL
VAR_INPUT
	Message : STRING;
END_VAR
ADSLOGSTR( msgCtrlMask := ADSLOG_MSGTYPE_LOG, msgFmtStr := 'Verbose Msg. : %s', strArg := Message);
END_FUNCTION_BLOCK

PROGRAM MAIN
VAR
    Notifications 	: NotificationCollection;
	n				: Object;
	iterator	  	: Iterator;

	bInit			: BOOL;
	bReset			: BOOL;
	bExecute : BOOL;
	nPosition : INT;
	stext : STRING;
END_VAR
IF NOT bInit THEN
	bInit := TRUE;

	Notifications.addItem(str := 'The');
	Notifications.addItem(str := 'quick');
	Notifications.addItem(str := 'brown');
	Notifications.addItem(str := 'fox');
	Notifications.addItem(str := 'jumps');
	Notifications.addItem(str := 'over');
	Notifications.addItem(str := 'the');
	Notifications.addItem(str := 'lazy');
	Notifications.addItem(str := 'dog');

	iterator := notifications.createIterator();	
	n := Iterator.current();

	nPosition := Iterator.Position;
	stext := CONCAT(TO_STRING(nPosition),n.getNotification()); 

	F_VerboseLogger(stext);
	//	F_VerboseLogger(n.getNotification());
END_IF


IF bExecute THEN
	WHILE(Iterator.hasNext()) DO
		n := Iterator.next();

		nPosition := Iterator.Position;
		stext := CONCAT(TO_STRING(nPosition),n.getNotification()); 

		F_VerboseLogger(stext);
	//	F_VerboseLogger(n.getNotification());

	END_WHILE
END_IF
bExecute := FALSE;

IF bReset THEN
	iterator.reset();
	n := Iterator.current();

	nPosition := Iterator.Position;
	stext := CONCAT(TO_STRING(nPosition),n.getNotification());

	F_VerboseLogger(stext);
	//	F_VerboseLogger(n.getNotification());
	bReset := FALSE;
END_IF
END_FUNCTION_BLOCK

