FUNCTION_BLOCK FB_ShapeCreator
VAR_INPUT
	eShape : E_Shape;
END_VAR
VAR_OUTPUT
END_VAR
VAR
      pCircle    : POINTER TO FB_Circle;
      pRectangle : POINTER TO FB_Rectangle;
      pSquare    : POINTER TO FB_Square;
      pStar      : POINTER TO FB_Star;
      pTriangle  : POINTER TO FB_Triangle;
      iShape 	 : I_Shape;
END_VAR
//Hemos declarado punteros a cada bloque de función de forma correspondiente, 
//lo que nos permitiría crear una instancia dinámica del bloque de función de forma solicitado y ahorrar espacio en la memoria. 
//Si los hubiéramos declarado como fbCircle : FB_Circle en su lugar y asumiéramos que nunca necesitaríamos dibujar Circle, 
//aún ocuparíamos el espacio de memoria en este bloque de funciones. 

//En el programa principal, el usuario proporcionará una entrada para la forma deseada y 'M_GetShapeObject' decidirá qué bloque de función de forma crear una instancia y lo devolverá.
END_FUNCTION_BLOCK

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE E_Shape :
(
	init := 0,
	Circle,
	Rectangle,
	Sqaure,
	Star,
	Triangle,
	end,
	Custom
);
END_TYPE

PROGRAM MAIN
VAR
//	fbShapeCreator : FB_ShapeCreator;
	fbShapeCreator : FB_ShapeCreatorEX;
	eShape : E_Shape := E_Shape.init;

	iShape : I_Shape;
END_VAR
fbShapeCreator(eShape:= eShape);

CASE eShape OF
	E_Shape.Circle:
		iShape := fbShapeCreator.M_GetShapeObject();
		IF iShape <> 0 THEN
			iShape.M_Draw();
		END_IF	

		eShape := E_Shape.Rectangle;

	E_Shape.Rectangle:
		iShape := fbShapeCreator.M_GetShapeObject();
		IF iShape <> 0 THEN
			iShape.M_Draw();
		END_IF

		eShape := E_Shape.Sqaure;	

	E_Shape.Sqaure:
		iShape := fbShapeCreator.M_GetShapeObject();
		IF iShape <> 0 THEN
			iShape.M_Draw();
		END_IF	

		eShape := E_Shape.Star;	

	E_Shape.Star:
		iShape := fbShapeCreator.M_GetShapeObject();
		IF iShape <> 0 THEN
			iShape.M_Draw();
		END_IF

		eShape := E_Shape.Triangle;	

	E_Shape.Triangle:
		iShape := fbShapeCreator.M_GetShapeObject();
		IF iShape <> 0 THEN
			iShape.M_Draw();
		END_IF	

		//eShape := E_Shape.end;	
		eShape := E_Shape.Custom;	

	E_Shape.Custom:
		iShape := fbShapeCreator.M_GetShapeObject();
		IF iShape <> 0 THEN
			iShape.M_Draw();
		END_IF

		eShape := E_Shape.end;	
END_CASE
END_FUNCTION_BLOCK

