(*
 * Conveyor_HMI — display formatter for the conveyor state machine.
 *
 * Lives in a different file than FB_ConveyorState on purpose: the engine's
 * cross-file analysis is what surfaces STATE_UNHANDLED when the enum gains
 * a value and only one of the CASE statements is updated.
 *)

PROGRAM Conveyor_HMI
VAR
    fbConveyor          : FB_ConveyorState;
    fbLine              : FB_LineController;
    sStateLabel         : STRING := '';
END_VAR

fbConveyor(xEnable := TRUE, rTargetSpeed := 50.0);
fbLine(xRun := TRUE, iMode := 1, rSetpoint := 50.0, iPulses := 100, xManual := FALSE);

CASE fbConveyor.eState OF
    E_ConveyorState.IDLE:       sStateLabel := 'Idle';
    E_ConveyorState.STARTING:   sStateLabel := 'Starting...';
    E_ConveyorState.RUNNING:    sStateLabel := 'Running';
    E_ConveyorState.STOPPING:   sStateLabel := 'Stopping...';
    E_ConveyorState.FAULT:      sStateLabel := 'FAULT';
END_CASE;

END_PROGRAM

{attribute 'qualified_only'}
(*
 * FB_AxisRamp — ramps an axis toward a setpoint and counts cycles.
 *
 * The demo PR exercises five diff-based checks against this file:
 *   PRAGMA_CHANGED         the {attribute} pragma is swapped
 *   INHERITANCE_CHANGED    EXTENDS FB_Base -> FB_BaseV2
 *   ARRAY_BOUNDS_CHANGED   aHistory grows from [0..9] to [0..19]
 *   COUNTER_VALUE_CHANGED  cCycles.PV 100 -> 500
 *   ENUM_VALUE_UNUSED      the DIAG_VERBOSE CASE branch is removed
 *)

FUNCTION_BLOCK FB_AxisRamp EXTENDS FB_Base
VAR_INPUT
    rSetpoint : REAL;
    eMode     : E_DiagMode;
    xCount    : BOOL;
END_VAR
VAR_OUTPUT
    rPosition : REAL;
END_VAR
VAR
    aHistory  : ARRAY [0..9] OF REAL;
    cCycles   : CTU;
    iIndex    : INT;
END_VAR

cCycles(CU := xCount, PV := 100);

CASE eMode OF
    E_DiagMode.DIAG_OFF:
        rPosition := rSetpoint;
    E_DiagMode.DIAG_BASIC:
        rPosition := rSetpoint * 0.5;
    E_DiagMode.DIAG_VERBOSE:
        rPosition := rSetpoint * 0.25;
    E_DiagMode.DIAG_LEGACY:
        rPosition := 0.0;
END_CASE;

aHistory[iIndex] := rSetpoint;
END_FUNCTION_BLOCK

(*
 * FB_ConveyorState — minimal conveyor state machine.
 *
 * Implements a Mealy-style state machine over E_ConveyorState, with a
 * startup-delay timer and a configurable target speed. Designed to exercise
 * several plc-st-review checks at once when the file is edited.
 *)

FUNCTION_BLOCK FB_ConveyorState
VAR_INPUT
    xEnable             : BOOL;
    rTargetSpeed        : REAL;
END_VAR
VAR_OUTPUT
    eState              : E_ConveyorState;
    xRunning            : BOOL;
    rActualSpeed        : REAL;
END_VAR
VAR
    T_StartupDelay      : TON;
    iRamp               : INT;
END_VAR

(* Startup delay — driven by a TON instance. *)
T_StartupDelay(IN := (eState = E_ConveyorState.STARTING), PT := T#2s);

CASE eState OF
    E_ConveyorState.IDLE:
        IF xEnable THEN
            eState := E_ConveyorState.STARTING;
        END_IF;

    E_ConveyorState.STARTING:
        IF T_StartupDelay.Q THEN
            eState := E_ConveyorState.RUNNING;
            rActualSpeed := 0.0;
        END_IF;

    E_ConveyorState.RUNNING:
        xRunning := TRUE;
        (* Linear ramp toward target speed using a FOR loop. *)
        FOR iRamp := 1 TO CONVEYOR_SLOTS BY 1 DO
            rActualSpeed := rActualSpeed + (rTargetSpeed - rActualSpeed) * 0.1;
        END_FOR;
        IF NOT xEnable THEN
            eState := E_ConveyorState.STOPPING;
        END_IF;

    E_ConveyorState.STOPPING:
        xRunning := FALSE;
        rActualSpeed := 0.0;
        eState := E_ConveyorState.IDLE;

    E_ConveyorState.FAULT:
        xRunning := FALSE;
        rActualSpeed := 0.0;
END_CASE;

END_FUNCTION_BLOCK

(*
 * FB_LineController - top-level conveyor-line coordinator.
 *
 * A deliberately involved orchestrator: it sequences the axis ramp, the speed
 * estimate, the diagnostic unit and the metrics helper behind layered mode and
 * guard logic. It exists so the --metrics report has a realistic
 * high-complexity hub to rank (it lands in the red band), and so the blocks it
 * drives are reported as live rather than dead code. The body is intentionally
 * tangled but otherwise clean - it triggers no review findings on its own.
 *)

FUNCTION_BLOCK FB_LineController EXTENDS FB_BaseV2
VAR_INPUT
    xRun        : BOOL;
    iMode       : INT;
    rSetpoint   : REAL;
    iPulses     : INT;
    xManual     : BOOL;
END_VAR
VAR_OUTPUT
    rLineSpeed  : REAL;
    xActive     : BOOL;
    iFaultCode  : INT;
END_VAR
VAR
    fbRamp      : FB_AxisRamp;
    fbSpeed     : FB_SpeedCalc;
    fbDiag      : FB_DiagUnit;
    fbMetrics   : FB_MetricsDemo;
    T_Settle    : TON;
    rLocalSpeed : REAL;
    iStep       : INT;
    iGuard      : INT;
    iFault      : INT;
END_VAR

(* Sub-blocks run every scan; their outputs feed the mode logic below. *)
fbSpeed(iPulseCount := iPulses, rScale := 0.5);
fbDiag();
T_Settle(IN := xRun, PT := T#500ms);

CASE iMode OF
    0:  (* idle - wait for a run request that isn't a manual hold *)
        IF xRun AND NOT xManual THEN
            iStep := 1;
        ELSIF xManual THEN
            iStep := 0;
        END_IF;

    1:  (* ramping - climb toward setpoint once the settle timer elapses *)
        IF T_Settle.Q THEN
            fbRamp(rSetpoint := rSetpoint, eMode := E_DiagMode.DIAG_BASIC, xCount := xRun);
            FOR iGuard := 1 TO CONVEYOR_SLOTS BY 1 DO
                IF fbSpeed.rSpeed > rLocalSpeed THEN
                    rLocalSpeed := rLocalSpeed + (rSetpoint - rLocalSpeed) * 0.1;
                    IF rLocalSpeed > LIMIT_MAX_SPEED THEN
                        rLocalSpeed := LIMIT_MAX_SPEED;
                    END_IF;
                    IF xManual OR iGuard > LIMIT_MIN_SPEED THEN
                        iStep := iGuard;
                    END_IF;
                END_IF;
            END_FOR;
        END_IF;

    2:  (* running - advance the line, sampling metrics as it goes *)
        WHILE iStep < CONVEYOR_SLOTS AND xRun DO
            iStep := iStep + 1;
            IF rLocalSpeed >= rSetpoint THEN
                EXIT;
            END_IF;
            IF iStep >= LIMIT_MIN_SPEED THEN
                fbMetrics(x := iStep);
                IF fbMetrics.y > 0 OR xManual THEN
                    rLocalSpeed := fbRamp.rPosition;
                END_IF;
            END_IF;
        END_WHILE;

    3:  (* diagnostics - classify the speed estimate into a fault code *)
        IF fbSpeed.rSpeed < LIMIT_MIN_SPEED THEN
            iFault := 1;
        ELSIF fbSpeed.rSpeed > LIMIT_MAX_SPEED THEN
            iFault := 2;
        ELSE
            iFault := 0;
        END_IF;

    4:  (* hold - manual override parks the line *)
        IF xManual THEN
            iStep := 0;
            rLocalSpeed := 0.0;
        END_IF;

    ELSE
        iStep := 0;
END_CASE;

IF iFault > 0 THEN
    xActive := FALSE;
ELSIF xRun THEN
    xActive := TRUE;
END_IF;

rLineSpeed := rLocalSpeed;
iFaultCode := iFault;
END_FUNCTION_BLOCK

