    Out_Left : bool; // Ausgang Links
    BCD_Nr : int; // BCD Nummer
    OutputLeft : ARRAY[1..16] OF BOOL;
    OutputRight : ARRAY[1..16] OF BOOL; 
end_var

// Interne Variablen
var
    Freigabe : bool; // Freigabesignal
    Edge_flag_pos_3SW : bool; // Flankenmerker für drei Pos. Schalter
    Edge_flag_pos_LeftSW : bool; // Flankenmerker für Linken Schalter
    Edge_flag_pos_RightSW : bool; // Flankenmerker für Rechten Schalter
    BCD_is_diff : bool; // Marker für BCD-Änderung
	BCD_Nr_cache : int; // Alte BCD_Nr
    Bit_Wert_0 : int; // Wert von Bit 0
    Bit_Wert_1 : int; // Wert von Bit 1
    Bit_Wert_2 : int; // Wert von Bit 2
    Bit_Wert_3 : int; // Wert von Bit 3
    Constant_bit0 :int := 1; // Konstante für Bit 0
    Constant_bit1 :int := 2; // Konstante für Bit 1
    Constant_bit2 :int := 4; // Konstante für Bit 2
    Constant_bit3 :int := 8; // Konstante für Bit 3
    i :int; //index für die FOR Schleife
end_var

// Temporäre Variablen
var_temp
    BCD_Result :int; // BCD Ergebnis
    Pulse_GrundStellung :bool; // Puls für Grundstellung
    Pulse_Left :bool; // Puls für Linken Schalter
    Pulse_Right :bool; // Puls für Rechten Schalter
end_var

begin
// Direkte Steuerung der LED-Anzeigen
LED_Red := not not_halt_OK;
LED_Green := ((activity_sensor AND NOT drei_pos_sw AND LED_Takt) OR (activity_sensor AND drei_pos_sw AND Freigabe)) AND not_halt_OK;


// Bit-Werte Berechnung basierend auf Bit-Eingängen
Bit_Wert_0 := 0;
IF Bit_0 THEN Bit_Wert_0 := Constant_bit0; END_IF;

Bit_Wert_1 := 0;
IF Bit_1 THEN Bit_Wert_1 := Constant_bit1; END_IF;

Bit_Wert_2 := 0;
IF Bit_2 THEN Bit_Wert_2 := Constant_bit2; END_IF;

Bit_Wert_3 := 0;
IF Bit_3 THEN Bit_Wert_3 := Constant_bit3; END_IF;


// Summierung der Bit-Werte zur BCD-Berechnung
BCD_Result := Bit_Wert_0 + Bit_Wert_1 + Bit_Wert_2 + Bit_Wert_3 + BCD_offset;

// Prüfung auf Änderung der BCD-Nummer
BCD_is_diff := (BCD_Result <> BCD_Nr_cache);
IF BCD_is_diff THEN
    BCD_Nr := BCD_Result;
    BCD_Nr_cache := BCD_Result;
ELSIF NOT Freigabe THEN
    BCD_is_diff := FALSE;
END_IF;



// Zurücksetzen der Freigabe bei BCD-Änderung oder Zustimmtaster-Release
Freigabe := NOT (BCD_is_diff OR NOT drei_pos_sw OR NOT not_halt_OK) AND Freigabe;


// Aktivierung der Freigabe bei positiver Flanke des Zustimmtasters
Pulse_GrundStellung := drei_pos_sw AND NOT  Edge_flag_pos_3SW;
Edge_flag_pos_3SW := drei_pos_sw;

Freigabe := Freigabe OR (NOT Freigabe AND NOT Out_Left AND NOT Out_Right AND activity_sensor AND Pulse_GrundStellung AND not_halt_OK);


// Steuerung des Ausgangs Links
Pulse_Left := SW_Left AND NOT Edge_flag_pos_LeftSW;
Edge_flag_pos_LeftSW := SW_Left;

// Out_Left aktiv setzen, wenn Pulse_Left aktiv ist und keine Blockierung vorliegt (SW_Right ist nicht aktiv).
// Out_Left bleibt aktiv, bis SW_Left deaktiviert wird oder die Freigabe zurückgenommen wird.
IF Pulse_Left AND Freigabe AND not_halt_OK AND NOT SW_Right THEN
    Out_Left := TRUE;
ELSIF NOT SW_Left OR NOT Freigabe THEN
    Out_Left := FALSE;
END_IF;


// Steuerung des Ausgangs Rechts
Pulse_Right := SW_Right AND NOT Edge_flag_pos_RightSW;
Edge_flag_pos_RightSW := SW_Right;

if  Freigabe
    AND not_halt_OK
    AND Pulse_Right
    AND NOT SW_Left
then
      Out_Right := TRUE; // Rechten Ausgang aktivieren
elsif NOT SW_Right OR NOT Freigabe
then
      Out_Right := FALSE; // Rechten Ausgang deaktivieren
end_if;


// Steuerung der Einzelausgänge
FOR i := 1 TO 15 DO
    OutputLeft[i] := BCD_Result = i AND Out_Left;
    OutputRight[i] := BCD_Result = i AND Out_Right;
END_FOR;


end_function_block

FUNCTION_BLOCK Test_Complex
VAR_INPUT
    a : INT;
    b : INT;
    c : INT;
END_VAR
VAR_OUTPUT
    result : INT;
END_VAR
VAR_TEMP
    temp : INT;
END_VAR
BEGIN
    result := a;

    FOR temp := a TO b BY c DO
        result := result;
    END_FOR;

    WHILE a DO
        result := result;
    END_WHILE;

    REPEAT
        result := result;
    UNTIL a
    END_REPEAT;

    CASE a OF
        a : result := a;
        b : result := b;
    ELSE
        result := c;
    END_CASE;
END_FUNCTION_BLOCK

(* =============================================================
   FB_ButtonLamp — Illuminated Pushbutton Controller

   Category:     Actuators
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Controls an illuminated pushbutton with multiple lamp modes:
   - OFF: Lamp off
   - ON: Lamp solid on
   - BLINK_SLOW: 1Hz blink (500ms on / 500ms off)
   - BLINK_FAST: 4Hz blink (125ms on / 125ms off)

   Also provides edge detection on the button input.

   Usage:
     fbStart : FB_ButtonLamp;
     fbStart(bButton := bDI_StartBtn, nLampMode := 1);
     bStartPressed := fbStart.bPressed;
     bStartLamp    := fbStart.bLamp;
   ============================================================= *)
FUNCTION_BLOCK FB_ButtonLamp
VAR_INPUT
    bButton     : BOOL;                (* Button input (NO contact) *)
    nLampMode   : INT := 0;            (* 0=OFF, 1=ON, 2=BLINK_SLOW, 3=BLINK_FAST *)
END_VAR
VAR_OUTPUT
    bLamp       : BOOL;                (* Lamp output *)
    bPressed    : BOOL;                (* Button is pressed (debounced) *)
    bRising     : BOOL;                (* Rising edge on button *)
    bFalling    : BOOL;                (* Falling edge on button *)
END_VAR
VAR
    tonDebounce : TON;
    rtrigBtn    : R_TRIG;
    ftrigBtn    : F_TRIG;
    tonBlinkOn  : TON;
    tonBlinkOff : TON;
    bBlinkState : BOOL;
    tOnTime     : TIME;
    tOffTime    : TIME;
END_VAR

(* Debounce button *)
tonDebounce(IN := bButton, PT := T#30MS);
bPressed := tonDebounce.Q;

(* Edge detection *)
rtrigBtn(CLK := bPressed);
ftrigBtn(CLK := bPressed);
bRising := rtrigBtn.Q;
bFalling := ftrigBtn.Q;

(* Lamp control *)
CASE nLampMode OF
0: (* OFF *)
    bLamp := FALSE;

1: (* Solid ON *)
    bLamp := TRUE;

2: (* Blink slow — 1Hz *)
    tOnTime := T#500MS;
    tOffTime := T#500MS;
    IF NOT bBlinkState THEN
        tonBlinkOff(IN := TRUE, PT := tOffTime);
        IF tonBlinkOff.Q THEN
            bBlinkState := TRUE;
            tonBlinkOff(IN := FALSE, PT := tOffTime);
        END_IF
    ELSE
        tonBlinkOn(IN := TRUE, PT := tOnTime);
        IF tonBlinkOn.Q THEN
            bBlinkState := FALSE;
            tonBlinkOn(IN := FALSE, PT := tOnTime);
        END_IF
    END_IF
    bLamp := bBlinkState;

3: (* Blink fast — 4Hz *)
    tOnTime := T#125MS;
    tOffTime := T#125MS;
    IF NOT bBlinkState THEN
        tonBlinkOff(IN := TRUE, PT := tOffTime);
        IF tonBlinkOff.Q THEN
            bBlinkState := TRUE;
            tonBlinkOff(IN := FALSE, PT := tOffTime);
        END_IF
    ELSE
        tonBlinkOn(IN := TRUE, PT := tOnTime);
        IF tonBlinkOn.Q THEN
            bBlinkState := FALSE;
            tonBlinkOn(IN := FALSE, PT := tOnTime);
        END_IF
    END_IF
    bLamp := bBlinkState;

ELSE
    bLamp := FALSE;
END_CASE

END_FUNCTION_BLOCK

(* =============================================================
   FB_PneumaticCylinder — Pneumatic Cylinder Controller

   Category:     Actuators
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Controls single-acting or double-acting pneumatic cylinders
   with optional limit switch feedback and timeout monitoring.

   Features:
   - Extend/retract commands with edge detection
   - Limit switch monitoring (extended/retracted sensors)
   - Configurable timeout for fault detection
   - Manual/auto mode support

   Usage:
     fbClamp : FB_PneumaticCylinder;
     fbClamp(bExtend := bCmdClamp, bRetract := bCmdUnclamp,
             bSnsExtended := bDI_ClampFwd, bSnsRetracted := bDI_ClampRev,
             tTimeout := T#3S);
     bClamped   := fbClamp.bExtended;
     bUnclamped := fbClamp.bRetracted;
     bFault     := fbClamp.bErr;
   ============================================================= *)
FUNCTION_BLOCK FB_PneumaticCylinder
VAR_INPUT
    bExtend         : BOOL;                (* Command: extend cylinder *)
    bRetract        : BOOL;                (* Command: retract cylinder *)
    bSnsExtended    : BOOL;                (* Sensor: fully extended *)
    bSnsRetracted   : BOOL;                (* Sensor: fully retracted *)
    tTimeout        : TIME := T#5S;        (* Motion timeout *)
    bDoubleActing   : BOOL := TRUE;        (* TRUE=double-acting, FALSE=spring-return *)
    bEnable         : BOOL := TRUE;        (* Enable control *)
    bReset          : BOOL;                (* Reset error *)
END_VAR
VAR_OUTPUT
    bSolExtend      : BOOL;                (* Solenoid: extend valve *)
    bSolRetract     : BOOL;                (* Solenoid: retract valve (double-acting only) *)
    bExtended       : BOOL;                (* Status: fully extended *)
    bRetracted      : BOOL;                (* Status: fully retracted *)
    bMoving         : BOOL;                (* Status: in motion *)
    bErr          : BOOL;                (* Error: timeout or sensor conflict *)
    nErrId          : DINT;                 (* 0=OK, 1=Extend timeout, 2=Retract timeout, 3=Sensor conflict *)
END_VAR
VAR
    nState          : INT := 0;            (* 0=Idle, 1=Extending, 2=Extended, 3=Retracting, 4=Retracted, 10=Error *)
    tonTimeout      : TON;
    rtrigExtend     : R_TRIG;
    rtrigRetract    : R_TRIG;
END_VAR

rtrigExtend(CLK := bExtend);
rtrigRetract(CLK := bRetract);

(* Sensor conflict detection *)
IF bSnsExtended AND bSnsRetracted THEN
    nState := 10;
    nErrId := 3;
    bErr := TRUE;
    bSolExtend := FALSE;
    bSolRetract := FALSE;
END_IF

(* Reset *)
IF bReset AND bErr THEN
    nState := 0;
    bErr := FALSE;
    nErrId := 0;
    tonTimeout(IN := FALSE, PT := tTimeout);
END_IF

IF NOT bEnable THEN
    bSolExtend := FALSE;
    bSolRetract := FALSE;
    bMoving := FALSE;
    RETURN;
END_IF

CASE nState OF
0: (* Idle *)
    bSolExtend := FALSE;
    bSolRetract := FALSE;
    bMoving := FALSE;
    bExtended := bSnsExtended;
    bRetracted := bSnsRetracted;

    IF rtrigExtend.Q AND NOT bSnsExtended THEN
        nState := 1;
    ELSIF rtrigRetract.Q AND NOT bSnsRetracted THEN
        nState := 3;
    END_IF

1: (* Extending *)
    bSolExtend := TRUE;
    IF bDoubleActing THEN bSolRetract := FALSE; END_IF
    bMoving := TRUE;
    tonTimeout(IN := TRUE, PT := tTimeout);

    IF bSnsExtended THEN
        nState := 2;
        tonTimeout(IN := FALSE, PT := tTimeout);
    ELSIF tonTimeout.Q THEN
        nState := 10;
        nErrId := 1;
        bErr := TRUE;
        bSolExtend := FALSE;
    END_IF

2: (* Extended — hold position *)
    bSolExtend := TRUE;
    IF bDoubleActing THEN bSolRetract := FALSE; END_IF
    bMoving := FALSE;
    bExtended := TRUE;
    bRetracted := FALSE;

    IF rtrigRetract.Q THEN
        nState := 3;
    END_IF

3: (* Retracting *)
    bSolExtend := FALSE;
    IF bDoubleActing THEN bSolRetract := TRUE; END_IF
    bMoving := TRUE;
    tonTimeout(IN := TRUE, PT := tTimeout);

    IF bSnsRetracted THEN
        nState := 4;
        tonTimeout(IN := FALSE, PT := tTimeout);
    ELSIF tonTimeout.Q THEN
        nState := 10;
        nErrId := 2;
        bErr := TRUE;
        IF bDoubleActing THEN bSolRetract := FALSE; END_IF
    END_IF

4: (* Retracted — hold position *)
    bSolExtend := FALSE;
    IF bDoubleActing THEN bSolRetract := FALSE; END_IF
    bMoving := FALSE;
    bExtended := FALSE;
    bRetracted := TRUE;

    IF rtrigExtend.Q THEN
        nState := 1;
    END_IF

10: (* Error *)
    bSolExtend := FALSE;
    bSolRetract := FALSE;
    bMoving := FALSE;

END_CASE

END_FUNCTION_BLOCK

(* =============================================================
   FB_PumpManager — Dual Pump Coordination with Failover

   Category:     Actuators
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Manages two pumps with automatic failover, runtime
   equalization, and maintenance hour tracking. Alternates
   primary pump based on accumulated runtime.

   Usage:
     fbPumps : FB_PumpManager;
     fbPumps(
       bEnable   := bCoolingEnable,
       bFlowOK   := bFlowSwitch,
       bPump1OK  := NOT bPump1Fault,
       bPump2OK  := NOT bPump2Fault
     );
     bPump1 := fbPumps.bPump1;
     bPump2 := fbPumps.bPump2;
   ============================================================= *)
FUNCTION_BLOCK FB_PumpManager
VAR_INPUT
    bEnable             : BOOL;             (* Enable pump system *)
    bFlowOK             : BOOL;             (* Flow sensor feedback *)
    bPump1OK            : BOOL := TRUE;     (* Pump 1 healthy *)
    bPump2OK            : BOOL := TRUE;     (* Pump 2 healthy *)
    bSwapPumps          : BOOL;             (* Manual swap command *)
    tFlowCheckDelay     : TIME := T#5S;     (* Delay before flow check *)
    nHoursToSwap        : DINT := 100;      (* Runtime hours before auto-swap *)
END_VAR
VAR_OUTPUT
    bPump1              : BOOL;             (* Pump 1 output *)
    bPump2              : BOOL;             (* Pump 2 output *)
    bFlowAlarm          : BOOL;             (* No flow detected *)
    bBothFaulted        : BOOL;             (* Both pumps faulted *)
    bPumpActive         : BOOL;             (* A pump is running *)
    nActivePump         : INT;              (* 1 or 2 *)
    nRunHours1         : DINT;             (* Pump 1 runtime hours *)
    nRunHours2         : DINT;             (* Pump 2 runtime hours *)
END_VAR
VAR
    bPrimaryIs1         : BOOL := TRUE;     (* TRUE=pump1 is primary *)
    tonFlowCheck        : TON;              (* Flow check delay *)
    tonHourCounter1     : TON;              (* 1-hour timer pump 1 *)
    tonHourCounter2     : TON;              (* 1-hour timer pump 2 *)
    rtrigSwap           : R_TRIG;           (* Swap edge detect *)
    bFailover           : BOOL;             (* Failover active *)
END_VAR

(* ============================================================
   SWAP LOGIC — equalize runtime
   ============================================================ *)

rtrigSwap(CLK := bSwapPumps);

(* Manual swap *)
IF rtrigSwap.Q THEN
    bPrimaryIs1 := NOT bPrimaryIs1;
END_IF;

(* Auto-swap based on runtime hours *)
IF bPrimaryIs1 AND (nRunHours1 - nRunHours2 >= nHoursToSwap) THEN
    bPrimaryIs1 := FALSE;
ELSIF NOT bPrimaryIs1 AND (nRunHours2 - nRunHours1 >= nHoursToSwap) THEN
    bPrimaryIs1 := TRUE;
END_IF;

(* ============================================================
   PUMP SELECTION AND FAILOVER
   ============================================================ *)

IF bEnable THEN
    bBothFaulted := NOT bPump1OK AND NOT bPump2OK;

    IF bBothFaulted THEN
        bPump1 := FALSE;
        bPump2 := FALSE;
        nActivePump := 0;
    ELSIF bPrimaryIs1 THEN
        IF bPump1OK AND NOT bFailover THEN
            bPump1 := TRUE;
            bPump2 := FALSE;
            nActivePump := 1;
        ELSIF bPump2OK THEN
            bPump1 := FALSE;
            bPump2 := TRUE;
            nActivePump := 2;
            bFailover := TRUE;
        ELSE
            bPump1 := TRUE;
            bPump2 := FALSE;
            nActivePump := 1;
        END_IF;
    ELSE
        IF bPump2OK AND NOT bFailover THEN
            bPump1 := FALSE;
            bPump2 := TRUE;
            nActivePump := 2;
        ELSIF bPump1OK THEN
            bPump1 := TRUE;
            bPump2 := FALSE;
            nActivePump := 1;
            bFailover := TRUE;
        ELSE
            bPump1 := FALSE;
            bPump2 := TRUE;
            nActivePump := 2;
        END_IF;
    END_IF;
ELSE
    bPump1 := FALSE;
    bPump2 := FALSE;
    nActivePump := 0;
    bFailover := FALSE;
END_IF;

bPumpActive := bPump1 OR bPump2;

(* ============================================================
   FLOW MONITORING
   ============================================================ *)

tonFlowCheck(IN := bPumpActive, PT := tFlowCheckDelay);
bFlowAlarm := tonFlowCheck.Q AND NOT bFlowOK;

(* On flow alarm, trigger failover *)
IF bFlowAlarm AND NOT bFailover THEN
    bFailover := TRUE;
END_IF;

(* Reset failover when manually swapped or fault clears *)
IF rtrigSwap.Q THEN
    bFailover := FALSE;
END_IF;

(* ============================================================
   RUNTIME HOUR COUNTERS
   ============================================================ *)

tonHourCounter1(IN := bPump1, PT := T#1H);
IF tonHourCounter1.Q THEN
    nRunHours1 := nRunHours1 + 1;
    tonHourCounter1(IN := FALSE);
END_IF;

tonHourCounter2(IN := bPump2, PT := T#1H);
IF tonHourCounter2.Q THEN
    nRunHours2 := nRunHours2 + 1;
    tonHourCounter2(IN := FALSE);
END_IF;

END_FUNCTION_BLOCK

(* =============================================================
   FB_BrakeMotor — Motor with Electromagnetic Brake

   Category:     Motion
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Controls a motor with electromagnetic holding brake.
   Sequence: Release brake → wait → start motor (and reverse on stop).
   Prevents mechanical shock from simultaneous brake/motor switching.

   Usage:
     fbHoist : FB_BrakeMotor;
     fbHoist(bStart := bCmdHoist, bOverload := bDI_HoistOL);
     bMotorOut := fbHoist.bContactor;
     bBrakeOut := fbHoist.bBrakeRelease;
   ============================================================= *)
FUNCTION_BLOCK FB_BrakeMotor
VAR_INPUT
    bStart          : BOOL;                (* Start command *)
    bOverload       : BOOL := TRUE;        (* Thermal overload (NC) *)
    tBrakeDelay     : TIME := T#300MS;     (* Brake release delay before motor start *)
    tBrakeApply     : TIME := T#200MS;     (* Motor stop delay before brake apply *)
    bEnable         : BOOL := TRUE;        (* Enable control *)
    bReset          : BOOL;                (* Reset error *)
END_VAR
VAR_OUTPUT
    bContactor      : BOOL;                (* Motor contactor output *)
    bBrakeRelease   : BOOL;                (* Brake release output (TRUE=released) *)
    bRunning        : BOOL;                (* Motor is running *)
    bErr          : BOOL;                (* Error active *)
    nErrId          : DINT;                (* 0=OK, 1=Overload *)
END_VAR
VAR
    nState          : INT := 0;
    tonBrakeRel     : TON;
    tonBrakeApp     : TON;
END_VAR

(* Reset *)
IF bReset AND bErr THEN
    nState := 0;
    bErr := FALSE;
    nErrId := 0;
END_IF

(* Overload — immediate stop *)
IF NOT bOverload THEN
    bContactor := FALSE;
    bBrakeRelease := FALSE;
    bRunning := FALSE;
    bErr := TRUE;
    nErrId := 1;
    nState := 10;
    RETURN;
END_IF

IF NOT bEnable THEN
    bContactor := FALSE;
    bBrakeRelease := FALSE;
    bRunning := FALSE;
    nState := 0;
    RETURN;
END_IF

CASE nState OF
0: (* Stopped — brake applied *)
    bContactor := FALSE;
    bBrakeRelease := FALSE;
    bRunning := FALSE;
    tonBrakeRel(IN := FALSE, PT := tBrakeDelay);
    tonBrakeApp(IN := FALSE, PT := tBrakeApply);

    IF bStart THEN
        nState := 1;
    END_IF

1: (* Releasing brake *)
    bBrakeRelease := TRUE;
    bContactor := FALSE;
    tonBrakeRel(IN := TRUE, PT := tBrakeDelay);

    IF tonBrakeRel.Q THEN
        nState := 2;
        tonBrakeRel(IN := FALSE, PT := tBrakeDelay);
    END_IF

    IF NOT bStart THEN
        nState := 0;
        bBrakeRelease := FALSE;
    END_IF

2: (* Running *)
    bContactor := TRUE;
    bBrakeRelease := TRUE;
    bRunning := TRUE;

    IF NOT bStart THEN
        nState := 3;
    END_IF

3: (* Stopping — motor off, brake delayed *)
    bContactor := FALSE;
    bBrakeRelease := TRUE;
    bRunning := FALSE;
    tonBrakeApp(IN := TRUE, PT := tBrakeApply);

    IF tonBrakeApp.Q THEN
        bBrakeRelease := FALSE;
        tonBrakeApp(IN := FALSE, PT := tBrakeApply);
        nState := 0;
    END_IF

10: (* Error *)
    bContactor := FALSE;
    bBrakeRelease := FALSE;
    bRunning := FALSE;

END_CASE

END_FUNCTION_BLOCK

(* =============================================================
   FB_StandardMotor — Direct-On-Line Motor with Contactor

   Category:     Motion
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Controls a standard DOL motor with contactor feedback,
   start delay, and overload protection monitoring.

   Usage:
     fbPump : FB_StandardMotor;
     fbPump(bStart := bCmdPump, bFeedback := bDI_PumpContactor,
            bOverload := bDI_PumpOL);
     bPumpOutput := fbPump.bContactor;
     bPumpRunning := fbPump.bRunning;
   ============================================================= *)
FUNCTION_BLOCK FB_StandardMotor
VAR_INPUT
    bStart          : BOOL;                (* Start command *)
    bFeedback       : BOOL;                (* Contactor feedback (aux contact) *)
    bOverload       : BOOL;                (* Thermal overload relay (NC) *)
    bUseFeedback    : BOOL := FALSE;       (* Enable feedback monitoring *)
    tStartDelay     : TIME := T#0S;        (* Delay before start *)
    tFeedbackTime   : TIME := T#3S;        (* Contactor feedback timeout *)
    bEnable         : BOOL := TRUE;        (* Enable control *)
    bReset          : BOOL;                (* Reset error *)
END_VAR
VAR_OUTPUT
    bContactor      : BOOL;                (* Contactor output *)
    bRunning        : BOOL;                (* Motor is running *)
    bErr          : BOOL;                (* Error active *)
    nErrId          : DINT;                (* 0=OK, 1=Overload, 2=No feedback, 3=Lost feedback *)
END_VAR
VAR
    nState          : INT := 0;
    tonDelay        : TON;
    tonFeedback     : TON;
END_VAR

(* Reset *)
IF bReset AND bErr THEN
    nState := 0;
    bErr := FALSE;
    nErrId := 0;
END_IF

(* Overload trip — immediate stop *)
IF NOT bOverload THEN
    bContactor := FALSE;
    bRunning := FALSE;
    bErr := TRUE;
    nErrId := 1;
    nState := 10;
    RETURN;
END_IF

IF NOT bEnable THEN
    bContactor := FALSE;
    bRunning := FALSE;
    nState := 0;
    RETURN;
END_IF

CASE nState OF
0: (* Stopped *)
    bContactor := FALSE;
    bRunning := FALSE;
    tonDelay(IN := FALSE, PT := tStartDelay);
    tonFeedback(IN := FALSE, PT := tFeedbackTime);

    IF bStart THEN
        nState := 1;
    END_IF

1: (* Start delay *)
    tonDelay(IN := TRUE, PT := tStartDelay);
    IF tonDelay.Q OR tStartDelay = T#0S THEN
        bContactor := TRUE;
        nState := 2;
        tonDelay(IN := FALSE, PT := tStartDelay);
    END_IF

    IF NOT bStart THEN
        nState := 0;
        tonDelay(IN := FALSE, PT := tStartDelay);
    END_IF

2: (* Starting — waiting for feedback *)
    bContactor := TRUE;
    IF bUseFeedback THEN
        tonFeedback(IN := NOT bFeedback, PT := tFeedbackTime);
        IF bFeedback THEN
            bRunning := TRUE;
            nState := 3;
            tonFeedback(IN := FALSE, PT := tFeedbackTime);
        ELSIF tonFeedback.Q THEN
            bContactor := FALSE;
            bErr := TRUE;
            nErrId := 2;
            nState := 10;
        END_IF
    ELSE
        bRunning := TRUE;
        nState := 3;
    END_IF

    IF NOT bStart THEN
        nState := 0;
        bContactor := FALSE;
    END_IF

3: (* Running *)
    bContactor := TRUE;
    bRunning := TRUE;

    (* Lost feedback while running *)
    IF bUseFeedback AND NOT bFeedback THEN
        bContactor := FALSE;
        bRunning := FALSE;
        bErr := TRUE;
        nErrId := 3;
        nState := 10;
    END_IF

    IF NOT bStart THEN
        nState := 0;
        bContactor := FALSE;
        bRunning := FALSE;
    END_IF

10: (* Error *)
    bContactor := FALSE;
    bRunning := FALSE;

END_CASE

END_FUNCTION_BLOCK

(* =============================================================
   FB_VfdDrive — Variable Frequency Drive Controller

   Category:     Motion
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.1
   Dependencies: None (standard IEC only)

   Controls a VFD/inverter via digital outputs (run/direction)
   and analog output (speed reference). Includes ramp limiting,
   fault monitoring, and frequency feedback.

   Festo CMMT-AS/ST Note:
     For Festo servo drives with EtherCAT, use FB_ServoAxis
     with the Festo PtP Package instead. This FB is for
     traditional VFDs controlled via analog/digital I/O.
     See resource: knowledge://festo-ptp-reference

   Usage:
     fbSpindle : FB_VfdDrive;
     fbSpindle(bRun := bCmdSpin, rSpeedRef := 50.0,
               bFault := bDI_VfdFault, nFeedbackHz := nAD_VfdFreq);
     bRunOut   := fbSpindle.bRunOutput;
     nSpeedOut := fbSpindle.nAnalogOut;
   ============================================================= *)
FUNCTION_BLOCK FB_VfdDrive
VAR_INPUT
    bRun            : BOOL;                (* Run command *)
    bReverse        : BOOL;                (* Direction: FALSE=FWD, TRUE=REV *)
    rSpeedRef       : REAL := 0.0;         (* Speed reference [Hz or %] *)
    rSpeedMax       : REAL := 60.0;        (* Maximum speed [Hz] *)
    rRampUpTime     : REAL := 5.0;         (* Acceleration ramp [seconds] *)
    rRampDownTime   : REAL := 3.0;         (* Deceleration ramp [seconds] *)
    bFault          : BOOL;                (* VFD fault input (NO) *)
    nFeedbackHz     : INT := 0;            (* Speed feedback raw [ADC] *)
    nFeedbackMax    : INT := 32767;        (* Feedback at max speed *)
    bEnable         : BOOL := TRUE;        (* Enable control *)
    bReset          : BOOL;                (* Reset error *)
END_VAR
VAR_OUTPUT
    bRunOutput      : BOOL;                (* Run digital output *)
    bDirOutput      : BOOL;                (* Direction output (TRUE=REV) *)
    nAnalogOut      : INT;                 (* Speed ref analog output [0-32767] *)
    rActualSpeed    : REAL;                (* Actual speed [Hz] *)
    bAtSpeed        : BOOL;                (* At target speed (+-2%) *)
    bRunning        : BOOL;                (* Drive is running *)
    bErr          : BOOL;                (* Error active *)
    nErrId          : DINT;                (* 0=OK, 1=VFD fault *)
END_VAR
VAR
    nState          : INT := 0;
    rRampedRef      : REAL := 0.0;
    rRampStep       : REAL;
    rDiff           : REAL;
END_VAR

(* Reset *)
IF bReset AND bErr THEN
    nState := 0;
    bErr := FALSE;
    nErrId := 0;
END_IF

(* VFD fault *)
IF bFault THEN
    bRunOutput := FALSE;
    bRunning := FALSE;
    bErr := TRUE;
    nErrId := 1;
    nState := 10;
END_IF

IF NOT bEnable THEN
    bRunOutput := FALSE;
    bRunning := FALSE;
    rRampedRef := 0.0;
    nState := 0;
END_IF

(* Feedback conversion *)
IF nFeedbackMax > 0 THEN
    rActualSpeed := INT_TO_REAL(nFeedbackHz) / INT_TO_REAL(nFeedbackMax) * rSpeedMax;
ELSE
    rActualSpeed := 0.0;
END_IF

CASE nState OF
0: (* Stopped *)
    bRunOutput := FALSE;
    bRunning := FALSE;
    rRampedRef := 0.0;
    nAnalogOut := 0;

    IF bRun THEN
        bDirOutput := bReverse;
        nState := 1;
    END_IF

1: (* Running — ramping *)
    bRunOutput := TRUE;
    bRunning := TRUE;

    (* Clamp reference *)
    IF rSpeedRef > rSpeedMax THEN rSpeedRef := rSpeedMax; END_IF
    IF rSpeedRef < 0.0 THEN rSpeedRef := 0.0; END_IF

    (* Ramp calculation per scan *)
    rDiff := rSpeedRef - rRampedRef;
    IF rDiff > 0.0 AND rRampUpTime > 0.0 THEN
        rRampStep := rSpeedMax / (rRampUpTime * 1000.0);  (* per ms, approx *)
        rRampedRef := rRampedRef + rRampStep;
        IF rRampedRef > rSpeedRef THEN rRampedRef := rSpeedRef; END_IF
    ELSIF rDiff < 0.0 AND rRampDownTime > 0.0 THEN
        rRampStep := rSpeedMax / (rRampDownTime * 1000.0);
        rRampedRef := rRampedRef - rRampStep;
        IF rRampedRef < rSpeedRef THEN rRampedRef := rSpeedRef; END_IF
    ELSE
        rRampedRef := rSpeedRef;
    END_IF

    (* Convert to analog output *)
    IF rSpeedMax > 0.0 THEN
        nAnalogOut := REAL_TO_INT(rRampedRef / rSpeedMax * 32767.0);
    ELSE
        nAnalogOut := 0;
    END_IF
    IF nAnalogOut < 0 THEN nAnalogOut := 0; END_IF
    IF nAnalogOut > 32767 THEN nAnalogOut := 32767; END_IF

    (* At speed detection *)
    bAtSpeed := ABS(rRampedRef - rSpeedRef) < (rSpeedMax * 0.02);

    IF NOT bRun THEN
        nState := 2;
    END_IF

2: (* Decelerating to stop *)
    bRunning := TRUE;
    IF rRampDownTime > 0.0 THEN
        rRampStep := rSpeedMax / (rRampDownTime * 1000.0);
        rRampedRef := rRampedRef - rRampStep;
    END_IF
    IF rRampedRef <= 0.0 THEN
        rRampedRef := 0.0;
        nState := 0;
    END_IF
    IF rSpeedMax > 0.0 THEN
        nAnalogOut := REAL_TO_INT(rRampedRef / rSpeedMax * 32767.0);
    ELSE
        nAnalogOut := 0;
    END_IF
    IF nAnalogOut < 0 THEN nAnalogOut := 0; END_IF
    bAtSpeed := FALSE;

10: (* Error *)
    bRunOutput := FALSE;
    bRunning := FALSE;
    rRampedRef := 0.0;
    nAnalogOut := 0;

END_CASE

END_FUNCTION_BLOCK

(* =============================================================
   FB_FaultDetection — Multi-Input Fault Consolidation

   Category:     Safety
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Consolidates up to 16 fault inputs with latching and
   acknowledgment. Each fault is latched on rising edge and
   must be explicitly acknowledged. Provides consolidated
   fault output and active fault count.

   Usage:
     fbFaults : FB_FaultDetection;
     fbFaults(bFault0 := bOverTemp, bFault1 := bOverPress,
              bFault2 := bLowFlow, bAckAll := bBtnAck);
     bAnyFault := fbFaults.bFaultActive;
     nFaults   := fbFaults.nActiveFaults;
   ============================================================= *)
FUNCTION_BLOCK FB_FaultDetection
VAR_INPUT
    bFault0         : BOOL;    (* Fault input 0 *)
    bFault1         : BOOL;    (* Fault input 1 *)
    bFault2         : BOOL;    (* Fault input 2 *)
    bFault3         : BOOL;    (* Fault input 3 *)
    bFault4         : BOOL;    (* Fault input 4 *)
    bFault5         : BOOL;    (* Fault input 5 *)
    bFault6         : BOOL;    (* Fault input 6 *)
    bFault7         : BOOL;    (* Fault input 7 *)
    bFault8         : BOOL;    (* Fault input 8 *)
    bFault9         : BOOL;    (* Fault input 9 *)
    bFault10        : BOOL;    (* Fault input 10 *)
    bFault11        : BOOL;    (* Fault input 11 *)
    bFault12        : BOOL;    (* Fault input 12 *)
    bFault13        : BOOL;    (* Fault input 13 *)
    bFault14        : BOOL;    (* Fault input 14 *)
    bFault15        : BOOL;    (* Fault input 15 *)
    bAckAll         : BOOL;    (* Acknowledge all faults *)
    bResetAll       : BOOL;    (* Reset all latches (clears even if active) *)
END_VAR
VAR_OUTPUT
    bFaultActive    : BOOL;    (* At least one fault is latched *)
    nActiveFaults   : INT;     (* Number of active latched faults *)
    wFaultWord      : WORD;    (* Bitmask of latched faults *)
    wCurrentWord    : WORD;    (* Bitmask of currently active inputs *)
    nFirstFault     : INT;     (* Index of first active fault (-1=none) *)
END_VAR
VAR
    aLatched        : ARRAY[0..15] OF BOOL;
    aInputs         : ARRAY[0..15] OF BOOL;
    i               : INT;
    rtrigAck        : R_TRIG;
END_VAR

rtrigAck(CLK := bAckAll);

(* Map inputs to array *)
aInputs[0] := bFault0;   aInputs[1] := bFault1;
aInputs[2] := bFault2;   aInputs[3] := bFault3;
aInputs[4] := bFault4;   aInputs[5] := bFault5;
aInputs[6] := bFault6;   aInputs[7] := bFault7;
aInputs[8] := bFault8;   aInputs[9] := bFault9;
aInputs[10] := bFault10; aInputs[11] := bFault11;
aInputs[12] := bFault12; aInputs[13] := bFault13;
aInputs[14] := bFault14; aInputs[15] := bFault15;

(* Reset all *)
IF bResetAll THEN
    FOR i := 0 TO 15 DO
        aLatched[i] := FALSE;
    END_FOR
END_IF

(* Process each fault *)
nActiveFaults := 0;
wFaultWord := 0;
wCurrentWord := 0;
nFirstFault := -1;

FOR i := 0 TO 15 DO
    (* Latch on rising edge *)
    IF aInputs[i] THEN
        aLatched[i] := TRUE;
        wCurrentWord := wCurrentWord OR SHL(WORD#1, i);
    END_IF

    (* Acknowledge: clear latch only if input is gone *)
    IF rtrigAck.Q AND aLatched[i] AND NOT aInputs[i] THEN
        aLatched[i] := FALSE;
    END_IF

    (* Count and build word *)
    IF aLatched[i] THEN
        nActiveFaults := nActiveFaults + 1;
        wFaultWord := wFaultWord OR SHL(WORD#1, i);
        IF nFirstFault = -1 THEN
            nFirstFault := i;
        END_IF
    END_IF
END_FOR

bFaultActive := nActiveFaults > 0;

END_FUNCTION_BLOCK

(* =============================================================
   FB_LightCurtain — Safety Light Curtain Monitor

   Category:     Safety
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Monitors a dual-channel safety light curtain (OSSD outputs).
   Detects discrepancy between channels, provides muting support
   for material pass-through.

   Usage:
     fbCurtain : FB_LightCurtain;
     fbCurtain(bOSSD1 := bDI_Curtain_Ch1, bOSSD2 := bDI_Curtain_Ch2,
               bMuteRequest := bMuteActive);
     bCurtainOK := fbCurtain.bSafe;
   ============================================================= *)
FUNCTION_BLOCK FB_LightCurtain
VAR_INPUT
    bOSSD1          : BOOL;                (* OSSD channel 1 (TRUE=clear) *)
    bOSSD2          : BOOL;                (* OSSD channel 2 (TRUE=clear) *)
    bMuteRequest    : BOOL;                (* Muting request (bypass curtain) *)
    tDiscrepancy    : TIME := T#200MS;     (* Max channel discrepancy time *)
    tMuteMaxTime    : TIME := T#60S;       (* Maximum muting duration *)
    bEnable         : BOOL := TRUE;        (* Enable monitoring *)
    bReset          : BOOL;                (* Reset errors *)
END_VAR
VAR_OUTPUT
    bSafe           : BOOL;                (* Curtain clear / safe *)
    bIntrusion      : BOOL;                (* Object detected in field *)
    bMuted          : BOOL;                (* Curtain is muted *)
    bDiscrepancy    : BOOL;                (* Channel discrepancy fault *)
    bErr          : BOOL;                (* Error active *)
    nErrId          : DINT;                 (* 0=OK, 1=Intrusion, 2=Discrepancy, 3=Mute timeout *)
END_VAR
VAR
    tonDiscrep      : TON;
    tonMute         : TON;
    bBothClear      : BOOL;
    rtrigReset      : R_TRIG;
END_VAR

rtrigReset(CLK := bReset);

IF NOT bEnable THEN
    bSafe := FALSE;
    RETURN;
END_IF

bBothClear := bOSSD1 AND bOSSD2;

(* Discrepancy detection *)
tonDiscrep(IN := (bOSSD1 XOR bOSSD2), PT := tDiscrepancy);
IF tonDiscrep.Q AND NOT bDiscrepancy THEN
    bDiscrepancy := TRUE;
    bErr := TRUE;
    nErrId := 2;
END_IF

(* Muting *)
IF bMuteRequest AND NOT bDiscrepancy THEN
    bMuted := TRUE;
    tonMute(IN := TRUE, PT := tMuteMaxTime);
    IF tonMute.Q THEN
        bMuted := FALSE;
        bErr := TRUE;
        nErrId := 3;
    END_IF
ELSE
    bMuted := FALSE;
    tonMute(IN := FALSE, PT := tMuteMaxTime);
END_IF

(* Safe output *)
IF bDiscrepancy THEN
    bSafe := FALSE;
    bIntrusion := FALSE;
ELSIF bMuted THEN
    bSafe := TRUE;
    bIntrusion := FALSE;
ELSE
    bSafe := bBothClear;
    bIntrusion := NOT bBothClear;
    IF bIntrusion THEN
        nErrId := 1;
    ELSIF NOT bErr THEN
        nErrId := 0;
    END_IF
END_IF

(* Reset *)
IF rtrigReset.Q THEN
    bDiscrepancy := FALSE;
    bErr := FALSE;
    nErrId := 0;
    tonMute(IN := FALSE, PT := tMuteMaxTime);
END_IF

END_FUNCTION_BLOCK

(* =============================================================
   FB_DataLogger — Cyclic Data Logger to CSV File

   Category:     System
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: SysFile (SysFileOpen, SysFileWrite, SysFileClose)

   Cyclic data logger that writes PLC variables to CSV format
   via the SysFile library. Features configurable interval timer,
   automatic file rotation after N samples, and error handling.

   Usage:
     fbLog : FB_DataLogger;
     fbLog(bEnable    := TRUE,
           tInterval  := T#1S,
           sFilePath  := '/var/log/plcdata.csv',
           sData      := CONCAT(REAL_TO_STRING(rTemp), ',',
                                REAL_TO_STRING(rPressure)));
     nSamples := fbLog.nSampleCount;
   ============================================================= *)
FUNCTION_BLOCK FB_DataLogger
VAR_INPUT
    bEnable         : BOOL;                (* Enable cyclic logging *)
    tInterval       : TIME := T#1S;        (* Logging interval *)
    sFilePath       : STRING(255);         (* Target CSV file path *)
    sData           : STRING(255);         (* CSV data line to write *)
    nMaxSamples     : UDINT := 10000;      (* Max samples before file rotation *)
    bReset          : BOOL;                (* Reset sample counter and close file *)
END_VAR
VAR_OUTPUT
    bBusy           : BOOL;                (* Logger is active *)
    bErr            : BOOL;                (* Error occurred *)
    nErrId          : DINT;                (* Error code: 0=none, 1=open fail, 2=write fail, 3=close fail *)
    nSampleCount    : UDINT;               (* Total samples written to current file *)
    bFileRotated    : BOOL;                (* File rotation occurred this cycle *)
END_VAR
VAR CONSTANT
    LF              : STRING(1) := '$N';   (* Line feed character *)
END_VAR
VAR
    nState          : INT := 0;            (* State machine *)
    tonInterval     : TON;                 (* Interval timer *)
    hFile           : DWORD := 0;          (* SysFile handle *)
    bFileOpen       : BOOL := FALSE;       (* File currently open *)
    nBytesWritten   : UDINT;               (* Bytes written in last operation *)
    sLine           : STRING(255);         (* Formatted output line *)
    nFileIndex      : UDINT := 0;          (* File rotation counter *)
    bWasEnabled     : BOOL := FALSE;       (* Previous enable state *)
    nResult         : DINT;                (* SysFile operation result *)
END_VAR

(* ============================================================
   RESET HANDLING
   ============================================================ *)

IF bReset THEN
    IF bFileOpen THEN
        (* Close the open file *)
        nResult := SysFileClose(hFile);
        bFileOpen := FALSE;
        hFile := 0;
    END_IF
    nSampleCount := 0;
    nState := 0;
    bBusy := FALSE;
    bErr := FALSE;
    nErrId := 0;
    bFileRotated := FALSE;
    bWasEnabled := FALSE;
    RETURN;
END_IF

(* ============================================================
   MAIN STATE MACHINE
   ============================================================ *)

bFileRotated := FALSE;

CASE nState OF

0: (* IDLE — waiting for enable *)
    bBusy := FALSE;
    bErr := FALSE;
    nErrId := 0;
    IF bEnable THEN
        nState := 10;
    END_IF

10: (* OPEN FILE *)
    bBusy := TRUE;
    IF bFileOpen THEN
        (* File already open, skip to logging *)
        nState := 20;
    ELSE
        (* Open file in append mode *)
        hFile := SysFileOpen(sFilePath, AM_APPEND, ADR(nResult));
        IF hFile <> 0 AND nResult = 0 THEN
            bFileOpen := TRUE;
            nState := 20;
        ELSE
            (* Open failed — try write mode to create new file *)
            hFile := SysFileOpen(sFilePath, AM_WRITE, ADR(nResult));
            IF hFile <> 0 AND nResult = 0 THEN
                bFileOpen := TRUE;
                nState := 20;
            ELSE
                bErr := TRUE;
                nErrId := 1;  (* File open error *)
                nState := 99;
            END_IF
        END_IF
    END_IF

20: (* WAIT FOR INTERVAL *)
    IF NOT bEnable THEN
        nState := 80;
        RETURN;
    END_IF

    tonInterval(IN := TRUE, PT := tInterval);
    IF tonInterval.Q THEN
        tonInterval(IN := FALSE, PT := tInterval);
        nState := 30;
    END_IF

30: (* WRITE DATA *)
    sLine := CONCAT(sData, LF);
    nBytesWritten := SysFileWrite(hFile, ADR(sLine), INT_TO_UDINT(LEN(sLine)), ADR(nResult));
    IF nResult = 0 THEN
        nSampleCount := nSampleCount + 1;
        nState := 40;
    ELSE
        bErr := TRUE;
        nErrId := 2;  (* Write error *)
        nState := 99;
    END_IF

40: (* CHECK FILE ROTATION *)
    IF nSampleCount >= nMaxSamples THEN
        (* Close current file *)
        nResult := SysFileClose(hFile);
        bFileOpen := FALSE;
        hFile := 0;
        nSampleCount := 0;
        nFileIndex := nFileIndex + 1;
        bFileRotated := TRUE;
        nState := 10;  (* Re-open (next file) *)
    ELSE
        nState := 20;  (* Back to interval wait *)
    END_IF

80: (* CLOSE FILE — disable requested *)
    IF bFileOpen THEN
        nResult := SysFileClose(hFile);
        IF nResult <> 0 THEN
            bErr := TRUE;
            nErrId := 3;  (* Close error *)
        END_IF
        bFileOpen := FALSE;
        hFile := 0;
    END_IF
    nState := 0;

99: (* ERROR *)
    bBusy := FALSE;
    bErr := TRUE;
    IF bFileOpen THEN
        nResult := SysFileClose(hFile);
        bFileOpen := FALSE;
        hFile := 0;
    END_IF
    (* Stay in error until disabled and re-enabled *)
    IF NOT bEnable THEN
        nState := 0;
    END_IF

END_CASE

bWasEnabled := bEnable;

END_FUNCTION_BLOCK

(* =============================================================
   FB_EventLogger — Circular Event Buffer Logger

   Category:     System
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Logs events (alarms, state changes, operator actions) into a
   circular buffer. Stores event code, timestamp, and message.
   Oldest events are overwritten when buffer is full.

   Usage:
     fbLog : FB_EventLogger;
     fbLog(bLogEvent := bNewAlarm, nEventCode := 1001,
           sMessage := 'Over temperature detected');
     nTotalEvents := fbLog.nEventCount;
   ============================================================= *)
FUNCTION_BLOCK FB_EventLogger
VAR_INPUT
    bLogEvent       : BOOL;                (* Trigger: log new event *)
    nEventCode      : DINT;                (* Event code *)
    sMessage        : STRING(80);          (* Event message *)
    bClear          : BOOL;                (* Clear all events *)
END_VAR
VAR_OUTPUT
    nEventCount     : UDINT;               (* Total events logged *)
    nBufferUsed     : INT;                 (* Entries in buffer *)
    bBufferFull     : BOOL;                (* Buffer has wrapped *)
    (* Last event info *)
    nLastCode       : DINT;
    sLastMessage    : STRING(80);
END_VAR
VAR CONSTANT
    MAX_EVENTS      : INT := 100;
END_VAR
VAR
    aEventCodes     : ARRAY[0..99] OF DINT;
    aEventMessages  : ARRAY[0..99] OF STRING(80);
    nWriteIndex     : INT := 0;
    bWrapped        : BOOL := FALSE;
    rtrigLog        : R_TRIG;
END_VAR

rtrigLog(CLK := bLogEvent);

IF bClear THEN
    nWriteIndex := 0;
    nEventCount := 0;
    nBufferUsed := 0;
    bWrapped := FALSE;
    bBufferFull := FALSE;
    RETURN;
END_IF

IF rtrigLog.Q THEN
    (* Write to buffer *)
    aEventCodes[nWriteIndex] := nEventCode;
    aEventMessages[nWriteIndex] := sMessage;

    (* Update last event *)
    nLastCode := nEventCode;
    sLastMessage := sMessage;

    (* Advance write pointer *)
    nWriteIndex := nWriteIndex + 1;
    nEventCount := nEventCount + 1;

    IF nWriteIndex >= MAX_EVENTS THEN
        nWriteIndex := 0;
        bWrapped := TRUE;
    END_IF

    (* Buffer usage *)
    IF bWrapped THEN
        nBufferUsed := MAX_EVENTS;
        bBufferFull := TRUE;
    ELSE
        nBufferUsed := nWriteIndex;
    END_IF
END_IF

END_FUNCTION_BLOCK

(* =============================================================
   FB_SystemMonitor — System Watchdog and Diagnostics

   Category:     System
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Monitors system health: HMI heartbeat, PLC cycle time,
   runtime hours, and provides a watchdog output toggle for
   external monitoring.

   Usage:
     fbSysMon : FB_SystemMonitor;
     fbSysMon(bHmiHeartbeat := GVL_HMI.bHeartbeat,
              tHmiTimeout := T#5S);
     bHmiOK     := fbSysMon.bHmiAlive;
     bWatchdog  := fbSysMon.bWatchdogToggle;
   ============================================================= *)
FUNCTION_BLOCK FB_SystemMonitor
VAR_INPUT
    bHmiHeartbeat   : BOOL;            (* HMI heartbeat signal (toggles) *)
    tHmiTimeout     : TIME := T#5S;    (* HMI communication timeout *)
    bEnable         : BOOL := TRUE;    (* Enable monitoring *)
END_VAR
VAR_OUTPUT
    bHmiAlive       : BOOL;            (* HMI communication OK *)
    bWatchdogToggle : BOOL;            (* PLC watchdog toggle (1Hz) *)
    nRunHours       : UDINT;           (* Total PLC runtime hours *)
    nRunMinutes     : USINT;           (* Runtime minutes (0-59) *)
    nCycleCount     : UDINT;           (* Scan cycle counter *)
    bFirstScan      : BOOL;            (* First scan after start *)
END_VAR
VAR
    tonHmi          : TON;
    tonWatchdog     : TON;
    tonHour         : TON;
    bHmiPrev        : BOOL;
    bHmiChanged     : BOOL;
    bInit           : BOOL := FALSE;
    nMinCounter     : INT := 0;
END_VAR

(* First scan detection *)
IF NOT bInit THEN
    bFirstScan := TRUE;
    bInit := TRUE;
ELSE
    bFirstScan := FALSE;
END_IF

nCycleCount := nCycleCount + 1;

IF NOT bEnable THEN RETURN; END_IF

(* HMI heartbeat monitoring *)
bHmiChanged := (bHmiHeartbeat XOR bHmiPrev);
bHmiPrev := bHmiHeartbeat;

IF bHmiChanged THEN
    tonHmi(IN := FALSE, PT := tHmiTimeout);
    bHmiAlive := TRUE;
ELSE
    tonHmi(IN := TRUE, PT := tHmiTimeout);
    IF tonHmi.Q THEN
        bHmiAlive := FALSE;
    END_IF
END_IF

(* Watchdog toggle — 1Hz *)
tonWatchdog(IN := NOT tonWatchdog.Q, PT := T#500MS);
IF tonWatchdog.Q THEN
    bWatchdogToggle := NOT bWatchdogToggle;
    tonWatchdog(IN := FALSE, PT := T#500MS);
END_IF

(* Runtime hour counter *)
tonHour(IN := TRUE, PT := T#60S);
IF tonHour.Q THEN
    tonHour(IN := FALSE, PT := T#60S);
    nMinCounter := nMinCounter + 1;
    nRunMinutes := INT_TO_USINT(nMinCounter MOD 60);
    IF nMinCounter >= 60 THEN
        nRunHours := nRunHours + 1;
        nMinCounter := 0;
    END_IF
END_IF

END_FUNCTION_BLOCK

(* =============================================================
   FB_AnalogFilter — First-Order Low-Pass / Moving Average Filter

   Category:     Utilities
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Smooths noisy analog signals. Supports two modes:
   - LOW_PASS: Exponential moving average (alpha = tCycle / tFilter)
   - MOVING_AVG: Simple moving average over nSamples

   Usage:
     fbFilter : FB_AnalogFilter;
     fbFilter(rIn := rRawAnalog, nMode := 0, rFilterFactor := 0.1);
     rSmooth := fbFilter.rOut;
   ============================================================= *)
FUNCTION_BLOCK FB_AnalogFilter
VAR_INPUT
    rIn             : REAL;            (* Raw input value *)
    nMode           : INT := 0;        (* 0=Low-pass, 1=Moving average *)
    rFilterFactor   : REAL := 0.1;     (* Low-pass alpha (0.0-1.0, lower=smoother) *)
    nSamples        : INT := 10;       (* Moving average window size (max 32) *)
    bReset          : BOOL;            (* Reset filter to current input *)
END_VAR
VAR_OUTPUT
    rOut            : REAL;            (* Filtered output *)
END_VAR
VAR
    bInit           : BOOL := FALSE;
    (* Moving average buffer *)
    aBuffer         : ARRAY[0..31] OF REAL;
    nIndex          : INT := 0;
    rSum            : REAL := 0.0;
    nCount          : INT := 0;
END_VAR

IF bReset OR NOT bInit THEN
    rOut := rIn;
    bInit := TRUE;
    rSum := 0.0;
    nIndex := 0;
    nCount := 0;
    bReset := FALSE;
END_IF

CASE nMode OF
0: (* Low-pass exponential filter *)
    rOut := rOut + rFilterFactor * (rIn - rOut);

1: (* Moving average *)
    IF nSamples < 1 THEN nSamples := 1; END_IF
    IF nSamples > 32 THEN nSamples := 32; END_IF

    rSum := rSum - aBuffer[nIndex] + rIn;
    aBuffer[nIndex] := rIn;
    nIndex := nIndex + 1;
    IF nIndex >= nSamples THEN
        nIndex := 0;
    END_IF
    IF nCount < nSamples THEN
        nCount := nCount + 1;
    END_IF
    IF nCount > 0 THEN
        rOut := rSum / INT_TO_REAL(nCount);
    END_IF
END_CASE

END_FUNCTION_BLOCK

(* =============================================================
   FB_Blink — LED/Output Blink Pattern Generator

   Category:     Utilities
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Generates a blinking output with configurable on/off times.
   Useful for status LEDs, warning indicators, HMI feedback.

   Usage:
     fbBlink : FB_Blink;
     fbBlink(bEnable := TRUE, tOnTime := T#500MS, tOffTime := T#500MS);
     bLedOutput := fbBlink.bOut;
   ============================================================= *)
FUNCTION_BLOCK FB_Blink
VAR_INPUT
    bEnable     : BOOL;                (* Enable blinking *)
    tOnTime     : TIME := T#500MS;     (* ON duration *)
    tOffTime    : TIME := T#500MS;     (* OFF duration *)
END_VAR
VAR_OUTPUT
    bOut        : BOOL;                (* Blinking output *)
END_VAR
VAR
    tonOn       : TON;
    tonOff      : TON;
END_VAR

IF NOT bEnable THEN
    bOut := FALSE;
    tonOn(IN := FALSE, PT := tOnTime);
    tonOff(IN := FALSE, PT := tOffTime);
    RETURN;
END_IF

IF NOT bOut THEN
    tonOff(IN := TRUE, PT := tOffTime);
    IF tonOff.Q THEN
        bOut := TRUE;
        tonOff(IN := FALSE, PT := tOffTime);
    END_IF
ELSE
    tonOn(IN := TRUE, PT := tOnTime);
    IF tonOn.Q THEN
        bOut := FALSE;
        tonOn(IN := FALSE, PT := tOnTime);
    END_IF
END_IF

END_FUNCTION_BLOCK

(* =============================================================
   FB_Debounce — Digital Input Debounce Filter

   Category:     Utilities
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   Filters noisy digital inputs using a TON timer. Output only
   changes after the input has been stable for tDebounce time.

   Usage:
     fbDebounce : FB_Debounce;
     fbDebounce(bIn := bRawInput, tDebounce := T#50MS);
     bFiltered := fbDebounce.bOut;
   ============================================================= *)
FUNCTION_BLOCK FB_Debounce
VAR_INPUT
    bIn         : BOOL;                (* Raw digital input *)
    tDebounce   : TIME := T#50MS;      (* Debounce time *)
END_VAR
VAR_OUTPUT
    bOut        : BOOL;                (* Filtered output *)
    bRising     : BOOL;                (* Rising edge detected *)
    bFalling    : BOOL;                (* Falling edge detected *)
END_VAR
VAR
    tonOn       : TON;
    tonOff      : TON;
    bPrev       : BOOL;
END_VAR

tonOn(IN := bIn, PT := tDebounce);
tonOff(IN := NOT bIn, PT := tDebounce);

IF tonOn.Q THEN
    bOut := TRUE;
ELSIF tonOff.Q THEN
    bOut := FALSE;
END_IF

bRising  := bOut AND NOT bPrev;
bFalling := NOT bOut AND bPrev;
bPrev    := bOut;

END_FUNCTION_BLOCK

(* =============================================================
   FB_MqttPublisher — Simplified MQTT Publish with Auto-Reconnect

   Category:     Utilities
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only, MQTT client concept)

   Simplified MQTT publish wrapper that manages broker connection,
   automatic reconnection on disconnect, and message publishing.
   Uses a state machine with configurable reconnect delay.

   Usage:
     fbMqtt : FB_MqttPublisher;
     fbMqtt(bEnable     := TRUE,
            sBrokerAddr := '192.168.1.50',
            nPort       := 1883,
            sTopic      := 'plc/temperature',
            sPayload    := REAL_TO_STRING(rTemp));
     bOK := fbMqtt.bConnected AND fbMqtt.bPublished;
   ============================================================= *)
FUNCTION_BLOCK FB_MqttPublisher
VAR_INPUT
    bEnable         : BOOL;                (* Enable MQTT connection *)
    sBrokerAddr     : STRING(80);          (* MQTT broker IP or hostname *)
    nPort           : UINT := 1883;        (* MQTT broker port *)
    sClientId       : STRING(80) := 'CODESYS_PLC';  (* MQTT client identifier *)
    sTopic          : STRING(255);         (* Publish topic *)
    sPayload        : STRING(255);         (* Message payload *)
    bPublish        : BOOL;                (* Rising edge: trigger publish *)
    nQos            : INT := 0;            (* QoS level: 0, 1, or 2 *)
    bRetain         : BOOL := FALSE;       (* Retain flag *)
    tReconnectDelay : TIME := T#5S;        (* Delay before reconnect attempt *)
    tPublishTimeout : TIME := T#3S;        (* Publish acknowledgment timeout *)
END_VAR
VAR_OUTPUT
    bConnected      : BOOL;                (* Broker connection active *)
    bPublished      : BOOL;                (* Last publish succeeded *)
    bBusy           : BOOL;                (* Operation in progress *)
    bErr            : BOOL;                (* Error occurred *)
    nErrId          : DINT;                (* Error code: 0=none, 1=connect, 2=publish, 3=timeout, 4=disconnect *)
    nPublishCount   : UDINT;               (* Total successful publishes *)
END_VAR
VAR
    nState          : INT := 0;            (* State machine *)
    rtrigPublish    : R_TRIG;              (* Publish edge detection *)
    tonReconnect    : TON;                 (* Reconnect delay timer *)
    tonPubTimeout   : TON;                 (* Publish timeout timer *)
    tonConnTimeout  : TON;                 (* Connection timeout timer *)
    hClient         : DWORD := 0;          (* MQTT client handle *)
    nResult         : DINT;                (* Operation result *)
    bConnLost       : BOOL := FALSE;       (* Connection lost flag *)
    nReconnectCount : UDINT := 0;          (* Reconnection attempts *)
    bPubPending     : BOOL := FALSE;       (* Publish waiting for connection *)
END_VAR

(* ============================================================
   EDGE DETECTION
   ============================================================ *)

rtrigPublish(CLK := bPublish);

(* Capture publish request even if not yet connected *)
IF rtrigPublish.Q THEN
    bPubPending := TRUE;
    bPublished := FALSE;
END_IF

(* ============================================================
   MAIN STATE MACHINE
   ============================================================ *)

CASE nState OF

0: (* IDLE — waiting for enable *)
    bBusy := FALSE;
    bConnected := FALSE;
    bPublished := FALSE;
    bErr := FALSE;
    nErrId := 0;
    bConnLost := FALSE;
    IF bEnable THEN
        nState := 10;
    END_IF

10: (* CONNECTING — establish MQTT connection *)
    bBusy := TRUE;
    bErr := FALSE;
    nErrId := 0;
    (* Placeholder: hClient := MqttConnect(sBrokerAddr, nPort, sClientId, ADR(nResult)); *)
    tonConnTimeout(IN := TRUE, PT := T#10S);
    IF tonConnTimeout.Q THEN
        tonConnTimeout(IN := FALSE, PT := T#10S);
        bErr := TRUE;
        nErrId := 1;  (* Connection failed *)
        nState := 70;  (* Go to reconnect wait *)
        RETURN;
    END_IF

    (* Simulated: assume connection established *)
    IF TRUE THEN
        hClient := 1;
        bConnected := TRUE;
        bBusy := FALSE;
        tonConnTimeout(IN := FALSE, PT := T#10S);
        nState := 20;
    END_IF

20: (* CONNECTED — monitor connection, wait for publish *)
    IF NOT bEnable THEN
        nState := 80;
        RETURN;
    END_IF

    (* Check connection health *)
    (* Placeholder: bConnLost := NOT MqttIsConnected(hClient); *)
    IF bConnLost THEN
        bConnected := FALSE;
        nErrId := 4;  (* Disconnect detected *)
        nState := 70;  (* Go to reconnect *)
        RETURN;
    END_IF

    (* Process pending publish *)
    IF bPubPending THEN
        nState := 30;
    END_IF

30: (* PUBLISHING — send MQTT message *)
    bBusy := TRUE;
    (* Placeholder: nResult := MqttPublish(hClient, sTopic, sPayload, nQos, bRetain); *)
    tonPubTimeout(IN := TRUE, PT := tPublishTimeout);

    IF tonPubTimeout.Q THEN
        tonPubTimeout(IN := FALSE, PT := tPublishTimeout);
        bErr := TRUE;
        nErrId := 3;  (* Publish timeout *)
        bPubPending := FALSE;
        bBusy := FALSE;
        nState := 20;
        RETURN;
    END_IF

    (* Simulated: assume publish succeeded *)
    IF TRUE THEN
        bPublished := TRUE;
        bPubPending := FALSE;
        nPublishCount := nPublishCount + 1;
        tonPubTimeout(IN := FALSE, PT := tPublishTimeout);
        bBusy := FALSE;
        bErr := FALSE;
        nErrId := 0;
        nState := 20;
    END_IF

70: (* RECONNECT WAIT — delay before retry *)
    bConnected := FALSE;
    bBusy := TRUE;

    IF NOT bEnable THEN
        nState := 80;
        RETURN;
    END_IF

    tonReconnect(IN := TRUE, PT := tReconnectDelay);
    IF tonReconnect.Q THEN
        tonReconnect(IN := FALSE, PT := tReconnectDelay);
        nReconnectCount := nReconnectCount + 1;
        bConnLost := FALSE;
        nState := 10;  (* Retry connection *)
    END_IF

80: (* DISCONNECT — clean shutdown *)
    IF hClient <> 0 THEN
        (* Placeholder: MqttDisconnect(hClient); *)
        hClient := 0;
    END_IF
    bConnected := FALSE;
    bBusy := FALSE;
    bPubPending := FALSE;
    nState := 0;

END_CASE

END_FUNCTION_BLOCK

(* =============================================================
   FB_PidController — Generic PID Controller with Anti-Windup

   Category:     Utilities
   Platform:     CODESYS V3.5 (IEC 61131-3)
   Version:      1.0
   Dependencies: None (standard IEC only)

   General-purpose PID controller for any closed-loop control:
   temperature, pressure, flow, position, speed, etc.
   Features: P-I-D action, configurable deadband, output
   clamping, integral anti-windup, and self-retriggering
   cycle timer for consistent sample rate.

   Usage:
     fbPid : FB_PidController;
     fbPid(
       bEnable   := bControlActive,
       rSetpoint := 100.0,
       rFeedback := rSensorValue,
       rKp       := 2.0,
       rKi       := 0.5,
       rKd       := 0.1
     );
     rControlOutput := fbPid.rOutput;
   ============================================================= *)
FUNCTION_BLOCK FB_PidController
VAR_INPUT
    bEnable             : BOOL;             (* Enable control loop *)
    rSetpoint           : REAL;             (* Target value [engineering units] *)
    rFeedback           : REAL;             (* Actual value [engineering units] *)
    (* Tuning parameters *)
    rKp                 : REAL := 1.0;      (* Proportional gain *)
    rKi                 : REAL := 0.0;      (* Integral gain *)
    rKd                 : REAL := 0.0;      (* Derivative gain *)
    (* Output limits *)
    rOutputMax          : REAL := 100.0;    (* Max output *)
    rOutputMin          : REAL := 0.0;      (* Min output *)
    rDeadband           : REAL := 0.0;      (* Error deadband [engineering units] *)
    (* Sample time *)
    tCycleTime          : TIME := T#10MS;   (* Match to PLC task cycle *)
END_VAR
VAR_OUTPUT
    rOutput             : REAL;             (* Control output *)
    bAtSetpoint         : BOOL;             (* Within deadband *)
    rError              : REAL;             (* Current error *)
    bSaturated          : BOOL;             (* Output at limits *)
END_VAR
VAR
    (* PID internal state *)
    rIntegral           : REAL;
    rPrevError          : REAL;
    rDerivative         : REAL;
    (* Calculated terms *)
    rPropTerm           : REAL;
    rIntTerm            : REAL;
    rDerTerm            : REAL;
    rRawOutput          : REAL;
    (* Timing *)
    tonCycle            : TON;
    rDtSeconds          : REAL;
    (* Anti-windup *)
    rIntegralMax        : REAL;
    rIntegralMin        : REAL;
    (* First scan flag *)
    bFirstCycle         : BOOL := TRUE;
END_VAR

(* ============================================================
   CYCLE TIMING — self-retriggering for consistent sample rate
   ============================================================ *)

tonCycle(IN := NOT tonCycle.Q, PT := tCycleTime);
rDtSeconds := TIME_TO_REAL(tCycleTime) / 1000.0;

(* ============================================================
   PID CALCULATION
   ============================================================ *)

IF bEnable THEN
    IF tonCycle.Q OR bFirstCycle THEN
        bFirstCycle := FALSE;

        (* --- Error Calculation --- *)
        rError := rSetpoint - rFeedback;

        (* Deadband: suppress control action near setpoint *)
        IF rDeadband > 0.0 AND ABS(rError) <= rDeadband THEN
            rError := 0.0;
            bAtSetpoint := TRUE;
        ELSE
            bAtSetpoint := FALSE;
        END_IF;

        (* --- Proportional Term --- *)
        rPropTerm := rKp * rError;

        (* --- Integral Term with Anti-Windup --- *)
        IF NOT bSaturated THEN
            rIntegral := rIntegral + (rError * rDtSeconds);
        END_IF;

        (* Clamp integral *)
        IF rKi > 0.0 THEN
            rIntegralMax := (rOutputMax - rOutputMin) / rKi;
        ELSE
            rIntegralMax := 1000.0;
        END_IF;
        rIntegralMin := -rIntegralMax;

        IF rIntegral > rIntegralMax THEN
            rIntegral := rIntegralMax;
        ELSIF rIntegral < rIntegralMin THEN
            rIntegral := rIntegralMin;
        END_IF;

        rIntTerm := rKi * rIntegral;

        (* --- Derivative Term --- *)
        IF rDtSeconds > 0.0 THEN
            rDerivative := (rError - rPrevError) / rDtSeconds;
        ELSE
            rDerivative := 0.0;
        END_IF;
        rDerTerm := rKd * rDerivative;

        rPrevError := rError;

        (* --- Total Output --- *)
        rRawOutput := rPropTerm + rIntTerm + rDerTerm;

        (* --- Output Clamping --- *)
        IF rRawOutput > rOutputMax THEN
            rOutput := rOutputMax;
            bSaturated := TRUE;
        ELSIF rRawOutput < rOutputMin THEN
            rOutput := rOutputMin;
            bSaturated := TRUE;
        ELSE
            rOutput := rRawOutput;
            bSaturated := FALSE;
        END_IF;
    END_IF;
ELSE
    (* --- Disabled: reset all state --- *)
    rOutput := 0.0;
    rIntegral := 0.0;
    rPrevError := 0.0;
    rDerivative := 0.0;
    bFirstCycle := TRUE;
    bAtSetpoint := FALSE;
    bSaturated := FALSE;
END_IF;

END_FUNCTION_BLOCK

(*
    Conveyor fault detection and latching.

    Responsibilities:
    - Monitor basic conditions and set fault bits.
    - Latch faults until operator performs a reset.
    - Provide a consolidated Fault_Active output.

    Simplifications:
    - Run feedback timeout is modeled via a simple cycle counter.
    - Timing is abstract, no vendor-specific timers used.
*)

FUNCTION_BLOCK FB_ConveyorFaults
VAR_INPUT
    Run_Command          : BOOL; (* Command to run motor *)
    Run_Feedback         : BOOL; (* Feedback that conveyor is moving *)
    EStop_OK             : BOOL; (* E-Stop chain status *)
    Interlocks_OK        : BOOL; (* Permissive status from interlock block *)
    Motor_Fault_Input    : BOOL; (* Fault from drive or overload *)
    Reset_Faults_Command : BOOL; (* Operator fault reset command *)
END_VAR
VAR_OUTPUT
    Fault_Active        : BOOL; (* TRUE if any fault latched *)
    Fault_EStop         : BOOL;
    Fault_Interlock     : BOOL;
    Fault_Motor         : BOOL;
    Fault_RunTimeout    : BOOL;
END_VAR
VAR
    RunTimeoutCounter : INT;
    RunTimeoutLimit   : INT := 50; (* Number of cycles allowed to see feedback *)
END_VAR

(* E-Stop fault detection *)
IF NOT EStop_OK THEN
    Fault_EStop := TRUE;
END_IF;

(* Interlock loss while running *)
IF Run_Command AND NOT Interlocks_OK THEN
    Fault_Interlock := TRUE;
END_IF;

(* Direct motor fault input *)
IF Motor_Fault_Input THEN
    Fault_Motor := TRUE;
END_IF;

(* Run feedback timeout *)
IF Run_Command AND NOT Run_Feedback THEN
    IF RunTimeoutCounter < RunTimeoutLimit THEN
        RunTimeoutCounter := RunTimeoutCounter + 1;
    ELSE
        Fault_RunTimeout := TRUE;
    END_IF;
ELSE
    (* Reset counter when not commanding run or feedback is present *)
    RunTimeoutCounter := 0;
END_IF;

(* Latching behavior: faults remain until reset command and conditions are safe *)
IF Reset_Faults_Command THEN
    IF EStop_OK AND Interlocks_OK AND NOT Motor_Fault_Input THEN
        Fault_EStop      := FALSE;
        Fault_Interlock  := FALSE;
        Fault_Motor      := FALSE;
        Fault_RunTimeout := FALSE;
    END_IF;
END_IF;

Fault_Active := Fault_EStop OR Fault_Interlock OR Fault_Motor OR Fault_RunTimeout;

END_FUNCTION_BLOCK

(*
    Conveyor state machine.

    States:
    - Stopped
    - Starting
    - Running
    - Stopping
    - Fault

    Responsibilities:
    - Drive motor run command based on requests, interlocks, and faults.
    - Provide a clear state for diagnostics and commissioning.
*)

TYPE E_ConveyorState :
(
    Conveyor_Stopped,
    Conveyor_Starting,
    Conveyor_Running,
    Conveyor_Stopping,
    Conveyor_Fault
);
END_TYPE


FUNCTION_BLOCK FB_ConveyorStateMachine
VAR_INPUT
    Run_Request   : BOOL; (* From FB_StartStopLatch *)
    Interlocks_OK : BOOL; (* From FB_ConveyorInterlocks *)
    Fault_Active  : BOOL; (* From FB_ConveyorFaults *)
END_VAR
VAR_OUTPUT
    State           : E_ConveyorState;
    Motor_Run_Cmd   : BOOL;
    Ready_For_Start : BOOL; (* Simple indicator used in test harness *)
END_VAR
VAR
    Next_State : E_ConveyorState;
END_VAR

(* Default outputs *)
Motor_Run_Cmd   := FALSE;
Ready_For_Start := FALSE;
Next_State      := State;

CASE State OF

    Conveyor_Stopped:
        Ready_For_Start := TRUE;
        IF Fault_Active THEN
            Next_State := Conveyor_Fault;
        ELSIF Run_Request AND Interlocks_OK THEN
            Next_State := Conveyor_Starting;
        END_IF;

    Conveyor_Starting:
        Motor_Run_Cmd := TRUE;
        IF Fault_Active THEN
            Next_State := Conveyor_Fault;
        ELSIF NOT Run_Request THEN
            Next_State := Conveyor_Stopping;
        ELSIF Interlocks_OK THEN
            (* For this simple model, assume we reach running as soon as interlocks hold *)
            Next_State := Conveyor_Running;
        ELSE
            (* Loss of interlocks during starting drives to fault via external block *)
        END_IF;

    Conveyor_Running:
        Motor_Run_Cmd := TRUE;
        IF Fault_Active THEN
            Next_State := Conveyor_Fault;
        ELSIF NOT Run_Request THEN
            Next_State := Conveyor_Stopping;
        ELSIF NOT Interlocks_OK THEN
            (* Interlock loss triggers fault behavior in external fault block *)
            Next_State := Conveyor_Fault;
        END_IF;

    Conveyor_Stopping:
        Motor_Run_Cmd := FALSE;
        IF Fault_Active THEN
            Next_State := Conveyor_Fault;
        ELSIF NOT Run_Request THEN
            Next_State := Conveyor_Stopped;
        ELSIF Run_Request AND Interlocks_OK THEN
            (* Operator requested start again while stopping, go back to starting *)
            Next_State := Conveyor_Starting;
        END_IF;

    Conveyor_Fault:
        Motor_Run_Cmd := FALSE;
        IF NOT Fault_Active THEN
            (* After faults are cleared and operator has removed the condition,
               return to a stopped, ready state. *)
            Next_State := Conveyor_Stopped;
        END_IF;

END_CASE;

State := Next_State;

END_FUNCTION_BLOCK

(*
    Conveyor test sequence.

    Responsibilities:
    - Provide a simple way to exercise the conveyor logic in simulation.
    - Drive inputs through a basic sequence:
      - Normal start
      - Run
      - Simulated motor fault
      - Fault reset and restart attempt

    This program is intended to run in a simulated PLC task.
*)

PROGRAM Conveyor_Test
VAR
    (* Operator / system inputs *)
    Start_PB           : BOOL;
    Stop_PB            : BOOL;
    EStop_OK           : BOOL := TRUE;
    GuardDoors_Closed  : BOOL := TRUE;
    Downstream_Ready   : BOOL := TRUE;
    No_Jam_Detected    : BOOL := TRUE;
    Motor_Fault_Input  : BOOL := FALSE;
    Run_Feedback       : BOOL := FALSE;
    Reset_Faults_Cmd   : BOOL := FALSE;

    (* Internal wiring *)
    Run_Request        : BOOL;
    Interlocks_OK      : BOOL;
    Fault_Active       : BOOL;
    Fault_EStop        : BOOL;
    Fault_Interlock    : BOOL;
    Fault_Motor        : BOOL;
    Fault_RunTimeout   : BOOL;
    Motor_Run_Cmd      : BOOL;
    Conveyor_State     : E_ConveyorState;

    (* Test sequencing *)
    Step_Counter       : INT := 0;
    Cycle_Counter      : INT := 0;

    FB_StartStop      : FB_StartStopLatch;
    FB_Interlocks     : FB_ConveyorInterlocks;
    FB_Faults         : FB_ConveyorFaults;
    FB_StateMachine   : FB_ConveyorStateMachine;
END_VAR

(* Simple test sequencer, advances every 50 cycles *)
Cycle_Counter := Cycle_Counter + 1;
IF Cycle_Counter >= 50 THEN
    Cycle_Counter := 0;
    Step_Counter  := Step_Counter + 1;
END_IF;

(* Default inputs each cycle *)
Start_PB          := FALSE;
Stop_PB           := FALSE;
Reset_Faults_Cmd  := FALSE;
Motor_Fault_Input := FALSE;

CASE Step_Counter OF
    0:
        (* Idle, no commands *)
    1:
        (* Operator presses Start *)
        Start_PB := TRUE;

    2, 3:
        (* Conveyor is starting; simulate run feedback present *)
        Run_Feedback := Motor_Run_Cmd;

    4:
        (* Simulate motor fault during run *)
        Motor_Fault_Input := TRUE;

    5:
        (* Operator acknowledges and resets fault after resolving issue *)
        Motor_Fault_Input := FALSE;
        Reset_Faults_Cmd  := TRUE;

    6:
        (* Attempt to start again *)
        Start_PB := TRUE;

    7:
        (* Simulate stop command *)
        Stop_PB := TRUE;

    ELSE
        (* Hold in whatever state we reach *)
END_CASE;

(* Instantiate and call blocks in a simple wiring order *)

(* Start/Stop latch *)
FB_StartStop(
    Start_PB := Start_PB,
    Stop_PB  := Stop_PB,
    EStop_OK := EStop_OK,
    Run_Request => Run_Request
);

(* Interlocks *)
FB_Interlocks(
    Run_Request       := Run_Request,
    EStop_OK          := EStop_OK,
    GuardDoors_Closed := GuardDoors_Closed,
    Downstream_Ready  := Downstream_Ready,
    No_Jam_Detected   := No_Jam_Detected,
    Interlocks_OK     => Interlocks_OK
);

(* Fault detection *)
FB_Faults(
    Run_Command          := Motor_Run_Cmd,
    Run_Feedback         := Run_Feedback,
    EStop_OK             := EStop_OK,
    Interlocks_OK        := Interlocks_OK,
    Motor_Fault_Input    := Motor_Fault_Input,
    Reset_Faults_Command := Reset_Faults_Cmd,
    Fault_Active         => Fault_Active,
    Fault_EStop          => Fault_EStop,
    Fault_Interlock      => Fault_Interlock,
    Fault_Motor          => Fault_Motor,
    Fault_RunTimeout     => Fault_RunTimeout
);

(* State machine *)
FB_StateMachine(
    Run_Request   := Run_Request,
    Interlocks_OK := Interlocks_OK,
    Fault_Active  := Fault_Active,
    State         => Conveyor_State,
    Motor_Run_Cmd => Motor_Run_Cmd
);

END_PROGRAM

(*
    Conveyor line control.

    A worked example covering the constructs plcforge is expected to handle:
    an enumeration, a structure, a function, a function block with a timer and
    a state machine, and a program that ties them together.
*)

TYPE ConveyorState : (Idle := 0, Starting, Running, Faulted); END_TYPE

TYPE ConveyorSetup :
STRUCT
    nominalSpeed : REAL := 1.5;     (* m/s at 100% *)
    rampTime     : TIME := T#2s;    (* time to reach nominal speed *)
    jamLimit     : INT  := 3;       (* faults before the line latches out *)
END_STRUCT
END_TYPE


(* Scale a raw analogue value to engineering units. *)
FUNCTION ScaleAnalog : REAL
VAR_INPUT
    raw     : INT;      (* raw counts, 0..27648 *)
    minimum : REAL;
    maximum : REAL;
END_VAR
VAR
    clamped : REAL;
END_VAR
    clamped := LIMIT(0.0, INT_TO_REAL(raw), 27648.0);
    ScaleAnalog := minimum + (maximum - minimum) * clamped / 27648.0;
END_FUNCTION


(* One conveyor segment: start/stop with a ramp and jam supervision. *)
FUNCTION_BLOCK ConveyorSegment
VAR_INPUT
    enable   : BOOL;                (* master enable from the line control *)
    jam      : BOOL;                (* photo eye blocked longer than allowed *)
    reset    : BOOL;
    setup    : ConveyorSetup;
END_VAR
VAR_OUTPUT
    active   : BOOL;                (* segment is transporting *)
    speed    : REAL;                (* commanded speed in m/s *)
    state    : ConveyorState;
    faults   : INT;
END_VAR
VAR
    rampTimer  : TON;
    jamEdge    : R_TRIG;
    history    : ARRAY [1..5] OF REAL := [5(0.0)];
    index      : INT;
END_VAR

    jamEdge(CLK := jam);
    rampTimer(IN := enable AND NOT jam, PT := setup.rampTime);

    IF jamEdge.Q THEN
        faults := faults + 1;
    END_IF;

    IF reset THEN
        faults := 0;
        state  := Idle;
    END_IF;

    CASE state OF
        Idle:
            speed := 0.0;
            IF enable AND NOT jam THEN
                state := Starting;
            END_IF;

        Starting:
            (* Ramp the command up while the timer runs. *)
            speed := setup.nominalSpeed * TIME_TO_REAL(rampTimer.ET) / TIME_TO_REAL(setup.rampTime);
            IF rampTimer.Q THEN
                state := Running;
            ELSIF NOT enable THEN
                state := Idle;
            END_IF;

        Running:
            speed := setup.nominalSpeed;
            IF NOT enable OR jam THEN
                state := Idle;
            END_IF;

        Faulted:
            speed := 0.0;
    END_CASE;

    IF faults >= setup.jamLimit THEN
        state := Faulted;
    END_IF;

    (* Shift the speed history one sample down. *)
    FOR index := 1 TO 4 BY 1 DO
        history[index] := history[index + 1];
    END_FOR;
    history[5] := speed;

